-- ============================================================
-- Ozbek3a (1/2): Günə-özəl push bildirişlərinin UZ tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be'::uuid, 'Kelajakni rejalashtiring 💭', 'Homiladorlik albomiga ilk «boshlang‘ich» suratni yuklashni istamaysizmi?'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'Poydevor qo‘yamiz 🏗️', 'Tanangiz yangi bir mo‘jizaga tayyorlanmoqda, hayz tugash arafasida. Bo‘lajak chaqaloqning sog‘lom rivojlanishi uchun foliy kislotasi (B9) zaxirasi juda muhim. Ovqatlanish bo‘limidagi foydali taomlar menyusini ko‘rdingizmi? 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'Uyqu — shirin ne’mat 😴', 'Quvvat to‘plash kerak. Uyqusiz tunlar boshlanishidan oldin kuniga kamida 8 soat uxlashga harakat qiling.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'Yashil kuchni ishga soling! 🥦', 'Ismaloq va brokkoli shunchaki sabzavot emas, balki tabiiy vitaminlar xazinasidir. Bugun menyuingizga albatta yashil mahsulotlar qo‘shing.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'Shifokoringizni tanladingizmi? 👩‍⚕️', 'Ishonch bildirishingiz mumkin bo‘lgan mutaxassisni hozirdanoq izlang. Shifokorlar va klinikalar bo‘limidagi sharhlarni ko‘rib, tanlovingizni aniqlashtirishingiz mumkin.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'Tanangiz signal beryaptimi? 🌡️', 'Ovulyatsiya davri yaqinlashmoqda. Tana haroratingizga e’tibor bering — homilador bo‘lish imkoniyati eng yuqori bo‘lgan kunlar yaqin!'),
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d', 'Yangi sayohat boshlanmoqda! 🚀', 'Tanangiz buyuk bir mo‘jizaga mezbonlik qilishga tayyorlanmoqda. Siz bunga tayyormisiz?'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'Vitaminlarni unutdingizmi? 💊', 'Foliy kislotasi endi sizning eng yaqin do‘stingiz. Bo‘lajak chaqaloq salomatligining mustahkam poydevori uchun Oziqlanish bo‘limini ko‘rib chiqing!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'Bugun o‘zingizni qanday his qilyapsiz? 🌈', 'Yangi davr boshlanishida his-tuyg‘ularingiz o‘zgarishi mumkin. Bugungi hislaringizni Kayfiyat kundaligiga yozib, holatingizni kuzatib boring.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'Hozircha mikroskopik darajada 🔬', 'Buyuk hikoyalar mitti zarrachalardan boshlanadi. Hozir bo‘lajak chaqaloq shunchaki bir g‘oyaga o‘xshaydi, ammo uning imkoniyatlari cheksiz!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'Detoks vaqti! 🚫', 'Sigaret, spirtli ichimlik yoki ortiqcha kofein? Ular bilan xayrlashishning ayni vaqti. Sog‘lom ona = Sog‘lom boshlanish.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'Suv idishingiz yoningizdami? 💧', 'Tanangizni yetarli darajada suv bilan ta’minlash hozir ikki karra muhim. Kunlik suv me’yorini ichishni unutmang.'),
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4', 'Yong‘oq va bodom vaqti 🥜', 'Yengil tamaddi uchun chips emas, yong‘oq tanlang. Omega-3 ham sizga, ham bo‘lajak chaqaloqqa zarur.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'O‘zingizga vaqt ajrating 💆‍♀️', 'Stress gormonlarini haydaymiz! Bugun sevimli filmingizni tomosha qiling yoki iliq dush qabul qiling.'),
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3', 'Eng kichik boshlanish 🫧', 'Hozircha ko‘zga ko‘rinmaydi. Bo‘lajak chaqaloq atigi bitta hujayra, ammo uning rejalari katta!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'Sehrli lahza keldimi? ✨', 'Urug‘lanish odatda shu kunlarda sodir bo‘ladi. Siz buni sezmasangiz ham, mo‘jizaviy jarayon boshlangan.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'Oqsil bombasi 🍳', 'Nonushtaga tuxum bormi? Hujayralarning yangilanishi uchun oqsil muhim. Yoqimli ishtaha!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'Sayrga chiqamizmi? 👟', 'Toza havo kayfiyatingizni ko‘taradi. Mashqlar bo‘limidagi yengil yurish dasturini ko‘ring.'),
  ('1466cb19-fd27-4f75-a79c-d709e1623239', 'Ko‘knori urug‘idek 🌱', 'Chaqaloq allaqachon bachadoningizda o‘z joyini egallamoqda. U hali juda kichkina bo‘lsa-da, yuragi shakllana boshlaydi.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'DNK to‘plami tayyor! 🧬', 'Chaqaloqning ko‘z rangi, sochi va jinsi allaqachon kodlangan. Sizningcha, u kimga o‘xshaydi?'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'Rezavorlar ziyofati 🍓', 'Malinami yoki qulupnay? Antioksidantlarga boy bu mevalar immunitetingizni mustahkamlaydi.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'Sokin inqilob yuz bermoqda 🤫', 'Urug‘langan tuxum hujayra bachadoningizga joylashmoqda. Siz buni sezmasangiz ham, ajoyib jarayon davom etmoqda.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'Suyaklar uchun kalsiy 🥛', 'Sut, qatiq yoki pishloq? Chaqaloqning bo‘lajak skeleti uchun bugun albatta sut mahsulotlaridan iste’mol qiling.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'Holsizmisiz? Buning sababi bor 🥱', 'Progesteron gormoni miqdori oshmoqda. Agar to‘shak sizni chorlayotgan bo‘lsa, yo‘q demang, dam oling!'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'Vitaminni unutdingizmi? 😬', 'Foliy kislotasi mening kelajakdagi umurtqa pog‘onam uchun asosdir! Dori eslatmasini tekshiring, bugungi dozani qabul qildingizmi? ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'Qonli ajralma normalmi? 🩸', 'Qo‘rqmang, bu implantatsion qon ketishi bo‘lishi mumkin. Shubhangiz bo‘lsa, Shifokorlar bo‘limiga kiring.'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'Temirga boy taomlar yeysizmi? 🥩', 'Qon hajmingiz ortadi. Qizil go‘sht yoki yasmiq yeb, kamqonlikka yo‘l qo‘ymang.'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'Hayajonli kutish... 🧘‍♀️', 'Hayz vaqti yaqinlashmoqda. Stressni kamaytirish uchun Oq shovqinlar bo‘limini tinglang.'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'Taqvimga qaradingizmi? 🗓️', 'Hayz kechikayotgan bo‘lsa, balki test qilish vaqti kelgandir? Quvonchli xabarni biz bilan bo‘lishing!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'Kunjut donasidek! 🌱', 'Endi u rasman embrion deb ataladi. U tez o‘smoqda, siz esa o‘zgarib boryapsiz.'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'Ko‘nglingiz ayniyaptimi? 🤢', 'Ertalablari qiynalyapsizmi? Zanjabil choyi yoki limonli suv yordam berishi mumkin. Oshqozoningizni bo‘sh qoldirmang.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'Muhim bunyodkorlik ketmoqda! 🚧', 'Bosh miya va umurtqa pog‘onasi shakllanmoqda. Foliy kislotasini qabul qilishda davom eting!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'Ertalabki ko‘ngil aynishi? 🤢', 'Yotoqdan turmasdan oldin tuzli kreker yeng. Qondagi qand miqdorini barqaror saqlash uchun oz-ozdan ovqatlaning.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'Gup-gup... Eshityapsizmi? 💓', 'Yuragim ura boshladi! Bu mitti motorning ovozini eshitishni sabrsizlik bilan kutyapsizmi? Taqvimga birinchi UTT vaqtini belgilab qo‘ying! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'Rasman tasdiqlash vaqti keldi! ✅', 'Agar hali bormagan bo‘lsangiz, shifokor qabuliga yoziling. Shifokorlar bo‘limidan o‘zingizga mosini toping.'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'Ilk yurak urishlari 💓', 'Siz eshitmasangiz ham, bu mitti yurak allaqachon ishga tushgan. U daqiqasiga 100 martadan ko‘proq urmoqda!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'Limonli suv mo‘jizasi 🍋', 'Ko‘ngil aynishini kamaytiradi, tanani tozalaydi. Suvsizlanish bosh og‘rig‘iga sabab bo‘lishi mumkin.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'Batareyangiz tugayaptimi? 🔋', 'Quvvatingiz tez tugashi mumkin. Tushlikdan keyingi qisqa uyqu sizga juda yaxshi ta’sir qiladi.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'Menga hovuz kerak! 🏊‍♀️', 'Men suzadigan suvni (amniotik suyuqlikni) siz yaratasiz, Onajon. Suv kuzatuvchisiga kiring. Bir stakan suv ichdingizmi? ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'Hissiyotlar karuseli 🎢', 'Kulish, keyin esa yig‘lash... Gormonlar sizni aqldan ozdirgani yo‘q, ular shunchaki o‘z ishini qilyapti.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'Hidlarga sezgirmisiz? 👃', 'Yoqtirmaydigan taomlaringizni o‘zingizni majburlab yemang. Muqobil variantlar uchun Oziqlanish bo‘limiga qarang.'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'Miya rivojlanmoqda! 🧠', 'Nerv nayi yopilmoqda. Foliy kislotasini qabul qilishni to‘xtatmang — bo‘lajak dahoning poydevori qo‘yilmoqda!'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'Zanjabil choyi yordamga! 🍵', 'Ko‘ngil aynishi hech qo‘ymayaptimi? Zanjabil oshqozonni tinchlantiradi. Ovqatlanish bo‘limida retseptlar bor.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'Charchoq avjiga chiqdimi? 😴', 'Tanangiz energiya zavodi kabi ishlamoqda. Kunduzi biroz mizg‘ib olish — sizning onalik haqqingiz!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'Shiringina no‘xat donasi 🟢', 'Taxminan 6 mm. Qo‘l va oyoqlari kichik kurtakchalar kabi o‘sib chiqa boshlaydi. Kichkina suzuvchi!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'Poyga mashinasidek! 🏎️', 'Yuragi daqiqasiga 100-160 marta uradi. Siznikidan ikki baravar tez! Bu tovush sizga musiqadek tuyuladi.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'Qondagi qand miqdori tushib ketmasin! 📉', 'Oshqozon bo‘sh qolsa, ko‘ngil aynishi kuchayadi. Sumkangizda doimo kreker yoki quruq meva saqlang.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'Hojatxona marafonimi? 🚻', 'Tez-tez hojatga borish odatiy hol. Buyraklaringiz ko‘proq ishlamoqda. Ammo suvni kamaytirmang, aksincha, ko‘proq iching!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'Ko‘nglingiz ayniyaptimi? Kechiring! 🥺', 'Gormonlar bazm uyushtiryapti, bunga men sababchiman. Sizni qiynayapmanmi? Tuzli kreker yeymizmi? 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'Yuzi shakllanmoqda 👀', 'Ko‘zlari, burni va quloqlari shakllanmoqda. Hozircha ular qora nuqtalarga o‘xshaydi, ammo yuz qiyofasi asta-sekin paydo bo‘lmoqda.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'B6 vitamini qayerda bor? 🍌', 'Banan, avokado yoki tovuq go‘shti... Bu vitamin ko‘ngil aynishini yengillashtirishi mumkin.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'Yashirin raqs bazmi! 💃', 'Siz hali sezmasangiz ham, u allaqachon harakatlanmoqda. Uning ilk harakatlari shunchaki mayin qimirlagandek bo‘ladi.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'Tuzlama yoki shokolad? 🥒', 'G‘alati narsalarni yegingiz kelishi odatiy hol. Ammo shakar miqdoriga e’tibor bering! Ratsionda ularning foydali muqobillari bor.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'Shim torlik qilyaptimi? 👖', 'Vazn kuzatuvchisiga boshlang‘ich vazningizni kiritdingizmi? 📈'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'Xuddi o‘smirlikdagidekmi? 😳', 'Yuzingizda husnbuzarlar paydo bo‘lishi mumkin. Bunga gormonlar sababchi! Teringizni toza tuting, o‘zboshimchalik bilan dori ishlatmang.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'Birinchi suratimizni oldingizmi? 🤰', 'Galereyaga ilk Baby Bump suratingizni yuklang! ✨'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'Qabziyat muammosi bormi? 🚽', 'Ko‘p suv ichish va tolaga boy mahsulotlar iste’mol qilish sizga yordam beradi. Kivi va turshak ajoyib samara berishi mumkin.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'Sizni siqib qo‘yyapmanmi? Kechiring!', 'Vazningiz oshmasa ham, men uyimni kengaytiryapman. Keling, o‘sha tor shimingizni yechib, qulayroq kiyim kiyamiz. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'Tuzlama yoki shokolad? 🍫', 'Ovqatlanish bo‘limiga qarang, bugungi menyuda qanday foydali taomlar bor ekan? 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'Ta’m bilish boshlanmoqda 👅', 'Tilida ta’m kurtaklari shakllanmoqda. Siz yegan taomlarning ta’mini u ham his qiladi.'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'Kofeinni kamaytirdingizmi? ☕', 'Kuniga 1 finjondan oshirmang. Kofeinsiz yoki o‘simlik choylarini ham sinab ko‘ring.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'Men raqsga tushyapman! 🕺', 'Qo‘l va oyoqlarim bukilmoqda. Men bachadoningizda akrobatik harakatlar qilyapman, ammo siz buni hali his qilmayapsiz.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'Sabzavotli sho‘rva-chi? 🥣', 'Oshqozoningiz og‘ir taomlarni qabul qilmasa, yengil sho‘rva iching. Ham vitamin, ham suyuqlik!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'Harakat vaqti 🧘‍♀️', 'Harakat qilishni xohlaysizmi? Mashqlar bo‘limida sizga mos nimalar borligini ko‘ramizmi?'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'Bo‘lajak otani ham jalb qiling 🗣️', 'Bu faqat sizning sarguzashtingiz emas. Ilk UTT tasvirini birga tomosha qiling va kelajakdagi rejalaringiz haqida suhbatlashing.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'Tishlarim qichishmayapti... hozircha! 😬', 'Sut, qatiq, pishloq... Bugungi ovqatlanish ro‘yxatingizda ular bormi? 🥛'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'Go‘sht hidi yoqmayaptimi? 🥩', 'Oqsil kerak! Agar go‘sht yeya olmasangiz, uning o‘rniga yasmiq, no‘xat yoki yong‘oq iste’mol qiling.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'Byustgalter torlik qilyaptimi? 👙', 'Ko‘kragingiz kattalashib, sezgir bo‘lib bormoqda. Qulay, sport uslubidagi va karkassiz ichki kiyimga o‘tish vaqti keldi.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'Tanangiz suv so‘rayapti! 💧', 'Suvsizlanish bosh og‘rig‘iga sabab bo‘lishi mumkin. Suv kuzatuvchisiga kiring va bir stakan suv iching! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'U endi inson qiyofasida! 👶', 'Yuzingizdagi mashhur Homiladorlik Yog‘dusi-chi? ✨ Bu go‘zallikni Galereyada abadiylashtiring!'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'C vitamini portlashi 🍊', 'Apelsin, kivi yoki bulg‘or qalampiri... Immunitetingizni po‘latdek mustahkam saqlang, kasal bo‘lish mumkin emas!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'Buyraklar ishga tushdi! 🚽', 'Ajablanarli, ammo u allaqachon siydik chiqarmoqda. Amniotik suyuqlikni yutadi va chiqaradi. Aylanish boshlandi!'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'Kalsiy yetishmasin 🥛', 'Tish kurtaklari shakllanmoqda. Tvorog, pishloq yoki yogurt... Bular uning kelajakdagi chiroyli tabassumi uchun zarur!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'Boshingiz og‘riyaptimi? 🤕', 'Dori ichishga shoshilmang. Qorong‘i xona, sovuq kompress yoki massaj ko‘proq yordam berishi mumkin.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'Qon aylanishingiz jadallashmoqda! 🌊', 'Tomirlaringizdagi qon miqdori ortmoqda, yuragingiz tezroq ishlamoqda. Bu tizimni sovitib turish uchun suv muhim. Boshingiz aylanmasligi uchun suv ichishni unutmang! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'Qurilish ishlari davom etmoqda! 🏗️', 'Chaqaloqqa kalsiy kerak! Oziqlanish bo‘limidagi sut mahsulotlarini ko‘rib chiqing. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'Baliq kuni! 🐟', 'Simob miqdori past bo‘lgan baliqni tanlang. Miya rivoji uchun Omega-3 juda muhim.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'Cho‘zilish izlariga yo‘q deng! 🧴', 'Qorningiz hali bilinmasa ham, teringizni namlantiring. Bodom yoki kokos moyi qichishishni ham yengillashtiradi.'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'Greypfrut kattaligida bo‘ldi! 🍊', 'Belingiz yo‘g‘onlashishi mumkin. Raqamlar o‘zgardimi? Vazn kuzatuvchisiga kiriting! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'Ikkilik test vaqti keldimi? 🗓️', '11-14 haftalar oralig‘i muhim. Daun sindromi xavfini tekshirish uchun shifokoringiz bilan maslahatlashing.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'Ochmisiz yoki chanqadingizmi? 🤔', 'Ba’zan miya bu ikki hissiyotni adashtiradi. Avval bir stakan suv iching. Hali ham och bo‘lsangiz, demak, ovqatlanish vaqti kelibdi.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'Gimnastika vaqti! 🤸', 'U allaqachon qo‘llarini musht qilib, og‘zini ochmoqda. Siz buni sezmasangiz ham, ichkarida haqiqiy olimpiada ketmoqda!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'Aqlli chaqaloq kelmoqda! 🧠', 'Yod miya rivojlanishi uchun zarur. Ratsioningizda yodlangan tuz, baliq yoki sut mahsulotlari bormi?'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'Men cho‘zilyapman! 🤸', 'Siz ham harakatsiz qolmang, Onajon. Mashqlar bo‘limidagi yengil yoga harakatlarini ko‘rib chiqamizmi?'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'Sirni oshkor qilish vaqti keldimi? 📢', '1-trimestr yakunlanmoqda. Xavf kamaydi. Xushxabarni do‘stlaringiz bilan bo‘lishishga tayyormisiz?'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'Skelet mustahkamlanmoqda! 🦴', 'Yumshoq tog‘aylar suyakka aylanmoqda. Kalsiy zaxirangizni to‘ldiring, chaqalog‘ingiz baquvvat bo‘lsin!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'Okean yaratyapsiz! 🌊', 'Amniotik suyuqlik yangilanmoqda. Chaqalog‘ingiz toza hovuzda suzishi uchun ko‘p suv ichishni unutmang.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'Qorningiz qichishyaptimi? 🌵', 'Teri cho‘zilgani sari qichishish odatiy hol. Bodom moyi yoki maxsus krem surtib, yengillik his qiling.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'Quvvatingiz qaytyaptimi? 🔋', 'Bugun o‘zingizni qanday his qilyapsiz? Alomatlar kundaligiga qayd eting! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'Sizni «Ona» deb chaqiraman... 🥺', 'Ovoz paylarim shakllanmoqda. Hozircha jimman, ammo sizni ilk bor chaqiradigan kunimni tasavvur qilyapsizmi? Men tasavvur qilyapman...'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'Tolali oziq-ovqat — qahramon 🌾', 'Hazmni yaxshilash uchun suli yormasi, sabzavot va mevalarni ko‘proq iste’mol qiling. Oziqlanish bo‘limida mazali salatlar bor.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'Og‘irlik ko‘taryapsizmi? 🏋️‍♀️', 'Chaqaloqda yog‘ qatlami to‘planib, skeleti mustahkamlanmoqda. Vaznimiz tez oshyapti!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'Oziqa oqimi tezlashdi!', 'Bugun qanday foydali taom yedingiz? Oziqlanish ro‘yxatini tekshiring! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'Barmog‘ini so‘ryapti! 👍', 'Ultratovush tekshiruvida uning bosh barmog‘ini so‘rayotganini ko‘rishingiz mumkin. Bu tug‘ilgandan keyingi emish refleksi uchun mashqdir.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'Suzishni yoqtirasizmi? 🏊‍♀️', 'U suv ichida yashaydi. Amniotik suyuqlik toza va yetarli bo‘lishi uchun siz ham kun davomida ko‘p suv ichishingiz kerak.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'Ovozingizni balandlating! 🗣️', 'Chaqaloq endi ovozingizni va yurak urishingizni aniq eshitadi. Unga alla aytishni boshlang — bu uni tinchlantiradi. 🎶'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'Yong‘oq va funduk kuchi 🐿️', 'Miya rivojlanishi uchun Omega-3 juda muhim. Sumkangizda yong‘oq va boshqa mag‘izlarni olib yuring: ular ham to‘q tutadi, ham chaqaloqning aqliy rivojlanishini qo‘llab-quvvatlaydi.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'Oltin davr boshlandi! ✨', 'Tabriklaymiz! Siz 2-trimestrga qadam qo‘ydingiz. Quvvatingiz oshadi, xavflar esa kamayadi. Endi homiladorlikdan zavqlanish vaqti.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'Energiya bombasi kerak 💥', 'Chaqaloq tez o‘smoqda. Qizil go‘sht, tuxum yoki dukkaklilar... Temir va oqsil zaxirangizni to‘ldirishni unutmang.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'Hajmi limondek! 🍋', 'Taxminan 7-8 sm. U endi boshini bura oladi, hatto qovog‘ini ham sola oladi. Yuz ifodalari rivojlanmoqda!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'Shkafingizni ko‘zdan kechiring 👗', 'Tugmalar yopilmayaptimi? Tor shimlarni yig‘ishtirib qo‘ying. Keng, qulay va tabiiy matolardan tikilgan kiyimlarga o‘ting.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'Qizmi yoki o‘g‘il? 🩷💙', 'Jinsiy a’zolari to‘liq shakllanmoqda. UTTda ko‘rish qiyin bo‘lsa-da, u allaqachon kimligini biladi! Sizningcha, qaysi biri?'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'Temir xonim — bu sizsiz! 🦸‍♀️', 'Bosh aylanishining oldini olish uchun qizil go‘sht yoki yasmiq iste’mol qiling. «Oziqlanish» bo‘limida retseptlar bor.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'Bir dona olmadek 🍎', 'Shim tugmasini yechib qo‘ysangiz ham bo‘ladi, o‘zingizni erkin tuting! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'Tish go‘shtlaringiz qonayaptimi? 😬', 'Gormonlar tish go‘shtlarini sezgir qiladi. Yumshoq tish cho‘tkasidan foydalaning va og‘zingizni tuzli suv bilan chaying.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'Sizni eshityapman, Onajon! 👂', 'Quloq suyaklarim qattiqlashmoqda. Endi ovozingiz ohangini, kulgingizni va yurak urishingizni taniyman.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'Chaqaloq skeleti qattiqlashmoqda🦴', 'U sizning kalsiy zaxirangizni kamaytirib yubormasligi uchun sut, qatiq yoki bodom iste’mol qiling.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'Chap yonboshingizda uxlang 🛌', 'Chalqancha uxlash qon aylanishini qiyinlashtirishi mumkin. Chap yonboshda uxlash sizga ham, chaqaloqqa ham ko‘proq kislorod yetib borishiga yordam beradi.'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'SPA kunimi? ✨', 'Chaqaloqning terisi suvda burishib qolmasligi uchun maxsus krem bilan qoplangan. Siz-chi? Bugun o‘zingizga vaqt ajrating! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'Yorug‘likni ko‘rdim! 💡', 'Ko‘z qovoqlari yopiq bo‘lsa ham, u kuchli yorug‘likni sezadi. Qorningizga fonar tutsangiz, u yuzini boshqa tomonga burishi mumkin.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'Qabziyatdan qoching 🏃‍♀️', 'Dori o‘rniga ko‘proq suv iching, qora olxo‘ri qoqisi va kivi yeng.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'Kalit qayerda? 🔑', 'Unutuvchanlik — odatiy hol. Miyangiz hozir bundan ham muhimroq ish bilan band: inson yaratmoqda! Ro‘yxat tuzishni boshlang.'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'Oyoqlaringiz tortishyaptimi? 🦵', 'Bunga magniy va kalsiy yetishmovchiligi sabab bo‘lishi mumkin. Banan, bodom yoki qatiq yeng. Ko‘proq suv ichishni ham unutmang!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'Hajmi nokdek! 🍐', 'Bo‘yi uzayib, tanasi tiklanmoqda. Endi u boshini butunlay tik tuta oladi. U ulg‘aymoqda, siz esa yanada go‘zallashmoqdasiz!'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'Qorningiz tortishyaptimi? 😣', 'Keskin harakat qilmang. Iliq dush yoki yengil massaj og‘riqni kamaytirishi mumkin.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'Barmoq izlari tayyor! 🖐️', 'Dunyoda hech kimda uchramaydigan o‘sha noyob naqshlar allaqachon shakllandi. U hozirdanoq alohida bir shaxs. Ajoyib emasmi?'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'Qorningiz tez-tez ochyaptimi? 😋', 'Ishtahangiz oshgani juda yaxshi, ammo ikki kishilik ovqatlanish — afsona. Sifatli kaloriya manbalarini tanlang: yong‘oq, meva va sabzavotlar.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'Burningiz bitib qolganmi? 🤧', 'Siz kasal emassiz, bu homiladorlik riniti. Tuzli suvli spreydan foydalaning va xona havosini namlantiring.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'Tezkor yetkazib berish! 🚚', 'Men och qolganimda sizni turtkilay boshlashim mumkin. Oziqlanish bo‘limida bugun qanday foydali tavsiyalar bor? 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'Yog‘ qatlami hosil bo‘lmoqda 🧸', 'Chaqaloq issiqlikni saqlash uchun yog‘ to‘play boshlaydi.'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'Qabziyat ketmayaptimi? 🚽', 'Tolaga boy mahsulotlar va ko‘p suv — eng yaxshi davo. Harakatsiz qolmang, kundalik sayr ichaklar faoliyatini yaxshilaydi.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'Suyaklar qattiqlashmoqda! 🦴', 'Rezina kabi yumshoq tog‘aylar suyakka aylanmoqda. Kalsiy zaxirangizni to‘ldiring, chaqaloq skeleti po‘latdek mustahkam bo‘lsin!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'Bosh aylanishiga chek qo‘ying! 🛑', 'Qon hajmingiz oshgani sari temirga bo‘lgan ehtiyojingiz ham ortadi. Ismaloq, grechka yoki qizil go‘sht... Menyungizga albatta qo‘shing!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'Qorningizda diskotekami? 💃', 'Ichkarida salto qilishni o‘rganyapman! Sezdingizmi?'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'G‘alati tushlar ko‘ryapsizmi? 😴', 'Gormonlar tunlaringizni kinoga aylantirishi mumkin. Qo‘rqmang, bu normal holat. Tushlaringizni Kayfiyat kundaligiga yozib qo‘ying!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'Tabiiy krem surtilmoqda! 🧴', 'Teri burishib qolmasligi uchun u vernix deb ataladigan oq, pishloqsimon modda bilan qoplanmoqda. Bu — tabiatning o‘z himoya kremi!'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'Temirning do‘sti kim? 🍊', 'Agar temir qabul qilayotgan bo‘lsangiz, uni albatta C vitamini bilan birga iching. Shunda temir yaxshiroq so‘riladi.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'Belingiz og‘riyaptimi? 👠', 'Baland poshnali poyabzallarni javonga olib qo‘ying — endi qulaylik vaqti! Ortopedik poyabzal tanlang.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'Yonlaringiz tortishyaptimi? ⚡', 'To‘satdan sanchiq paydo bo‘lishi mumkin, qo‘rqmang, shunchaki uyimni kengaytiryapman! Mashqlar bo‘limidagi yengillik beruvchi mashqlarni bajarib ko‘ring. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'Pasporti tayyor! 🛂', 'Barmoq izlari to‘liq shakllandi. Dunyoda boshqa hech kimda uchramaydigan o‘sha naqshlar endi unda bor. Betakror inson dunyoga kelmoqda!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'Suvning ta’mi yo‘qmi? 💧', 'Ichish qiyin bo‘lsa, bodring, tarvuz yoki yalpiz qo‘shilgan suvni sinab ko‘ring. Suvsizlanish bosh og‘rig‘iga sabab bo‘ladi.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'Onajon, sizni eshityapman! 👂', 'Ovozingiz menga alla kabi eshitiladi. Yurak urishingiz esa eng go‘zal ohangdir. Men bilan ko‘proq gaplashing, sizni tanishni istayman.'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'Rux: Yashirin qahramon 🛡️', 'Hujayralarim tez bo‘linmoqda. Menga qurilish materiali kerak! Menyuda qizil go‘sht, pishloq yoki yong‘oqlar bormi?'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'Mangodek bo‘ldim! 🥭', 'Taxminan 15 sm. Terim hali yupqa, ammo yog‘ qatlamim shakllanmoqda. Endi ancha to‘laroq ko‘rinaman, Onajon!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'Sezdingizmi? Tepdim! ⚽', 'Onajon, men uyg‘oqman! O‘sha yengil qimirlaganim — sizga salom deyishim. Qo‘lingizni qorningizga qo‘ying, balki yana tepib qolarman?'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'O‘g‘ilmi yoki qiz? 💙💗', 'Jinsimni bilish uchun UTT vaqti yaqinlashmoqda. Hayajondamisiz?'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'Birinchi o‘yinchog‘im bor!', 'Kindik tizimchasini ushlab o‘ynayman, ba’zan uni siqaman. Barmoqlarim ushlashni o‘rganmoqda.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'Katta uchrashuv vaqti keldi! 🗓️', '18-22 haftalar — eng batafsil UTT o‘tkaziladigan vaqt. Barmoqlarimni, yuragimni — hamma narsamni tekshirishadi. Shifokor qabuliga yozildingizmi?'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'Temir kerak 🏗️', 'Qizil qon hujayralarini yaratish bilan bandman. Menga yordam bering: mol go‘shti, ismaloq yoki yasmiq yeng.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'Oyoqlaringiz shishyaptimi? 👠', 'Shishlar paydo bo‘lishi mumkin. Ishda yoki uyda imkon qadar oyoqlaringizni balandroq ko‘tarib turing. Qulay oyoq kiyim tanlang!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'Hiq... Hiq... 🤭', 'Qorningiz bir maromda sakrayaptimi? Qo‘rqmang, Onajon, bu shunchaki hiqichoq! Diafragmamni mashq qildiryapman.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'Ta’mlarni ajratadi! 👅', 'Amniotik suyuqlikning ta’mi siz yegan ovqatlarga qarab o‘zgaradi. Achchiq qalampir yedingizmi? U buni sezadi!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'Ko‘zlarim raqsga tushmoqda...', 'Ko‘z qovoqlarim yumuq bo‘lsa-da, allaqachon tush ko‘ryapman. Sizningcha, tushimda nima bor?'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'Jig‘ildoningiz qaynayaptimi? 🔥', 'Bachadon oshqozonni siqmoqda. Oz-ozdan, lekin tez-tez ovqatlaning. Ovqatdan keyin darhol yotmang, tik o‘tiring.'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'Bir banan kattaligida! 🍌', 'Taxminan 18-20 sm. Endi boshimdan oyog‘imgacha o‘lchanaman. Bo‘yim o‘sib, tanam tiklanib bormoqda.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'Pss, men uxlayapman 😴', 'Mening ham uyqu tartibim bor, Onajon. Siz yurganingizda tebranib uxlayman, yotganingizda esa uyg‘onib, diskoteka boshlayman! Kechiring 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'Yo‘lning yarmi ortda qoldi! 🏁', 'Tabriklaymiz! 20 hafta ortda qoldi. Siz homiladorlikning qoq yarmidasiz. Siz ajoyibsiz, buni albatta nishonlashingiz kerak!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'Yuklanmoqda... 50% ⏳', 'Tabriklayman! Yo‘lning yarmini ortda qoldirdik. Ushbu tarixiy kunni nishonlash uchun Galereyaga bir surat qo‘shsak arziydi! ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'Dadam meni his qilarmikan?', 'Agar qo‘lini qorningizga qo‘ysa, balki unga ham salom berarman.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'Rang-barang tushlar ko‘ryapsizmi?', 'Homiladorlikdagi tushlar xuddi filmga o‘xshaydi, shunday emasmi? Men ham o‘sha tushlaringizdamanmi? 😴'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'O‘zingizga g‘amxo‘rlik kuni 💅', 'Agar homiladorlik dog‘lari paydo bo‘lgan bo‘lsa, quyoshdan saqlaning. Bugun yuzingizga niqob qo‘yishga nima deysiz?'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'Yuzini kashf qilmoqda! 👶', 'Qo‘llari bilan yuzi, burni, hatto kindik ichagiga tegadi. Teginishni his qilish qobiliyati rivojlanmoqda. U o‘zini tanib boryapti!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'Tuzlama va muzqaymoq? 🥒🍦', 'G‘alati taomlar aralashmasini xohlayapsizmi? Bu tanangizning signallari. Ammo shakar va tuzni me’yorida iste’mol qilishga harakat qiling.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'Hajmi kokosdek! 🥥', 'Taxminan 28 sm. Vazni yarim kilodan oshdi! Endi u yanada kuchliroq tepadi.'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'Musiqa qo‘yamizmi? 🎶', 'Onajon, tashqaridagi tovushlarni eshityapman! Siz sevgan qo‘shiqlar menga ham yoqadi. Birga raqsga tushamizmi?'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'Kindigingiz bo‘rtib chiqdimi? 🔘', 'Qorin kattalashgani sari kindik bo‘rtib chiqadi. Qo‘rqmang, tug‘ruqdan keyin joyiga qaytadi!'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'Bu qanday ovoz edi, Onajon? 🔊', 'To‘satdan chiqqan shovqindan cho‘chib ketaman. Siz xotirjam bo‘lsangiz, men ham tinchlanaman. Menga alla aytib bera olasizmi?'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'Mening beshigim — siz... 💤', 'Siz yurganingizda men tebranib uxlab qolaman. Siz to‘xtaganingizda esa uyg‘onaman! Meni uxlatish uchun yengil sayrlarni davom ettiramizmi? 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'Shakarli suv ichdingizmi? 🥤', 'Gestatsion diabet testi muhim. Ham mening, ham sizning sog‘lig‘ingiz uchun albatta tekshiruvdan o‘ting.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'Qorningizda chiziq paydo bo‘ldimi? ➖', 'Linea Nigra gormonlar ta’sirida paydo bo‘ladi. Qo‘rqmang, tug‘ruqdan keyin yo‘qoladi. Siz har qanday holatda ham go‘zalsiz!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'Yashab qolish imkoniyatim oshdi! 🌟', '24 haftalik bo‘ldim! Tibbiy jihatdan endi yashashga qodir deb hisoblanaman. Bu juda katta bosqich, Onajon.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'Jig‘ildoningiz qaynayaptimi? 🔥', 'Bu sochlarim o‘sayotgani uchun emas, bachadon oshqozoningizni siqayotgani uchun yuz beradi. Ovqatdan keyin darhol yotmang, tik o‘tiring.'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'To‘lg‘oqmi yoki mashq? 🤔', 'Qorningiz taranglashyaptimi? Bu soxta to‘lg‘oq bo‘lishi mumkin. Bachadon tug‘ruqqa tayyorgarlik ko‘rmoqda. Agar og‘riqsiz bo‘lsa, bu normal holat.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'Sho‘r ovqatlardan saqlaning 🧂', 'Oyoqlaringiz shishsa, tuzni kamaytiring. Ko‘p suv ichish va petrushka yordam berishi mumkin. Uzuk barmog‘ingizni siqmayaptimi?'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'Kichik fabrika ishga tushdi! 🏭', 'Endi qon hujayralarini jigarim emas, suyak ko‘migim ishlab chiqarmoqda. Menga yordam berish uchun ratsioningizga temirga boy nimalarni qo‘shishingiz mumkin?'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'Shshsh, uxlayapman... 🤫', 'Onajon, nega men harakat qilmayapman? Chunki kunning ko‘p qismini uxlab o‘tkazaman. Men uxlaganimda siz ham dam oling.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'Yashirin mashq vaqti! 🧘‍♀️', 'Kegel mashqlarini unutmang. O‘tirgan joyingizda tos tubi mushaklarini qisib, bo‘shashtiring. Bu tug‘ruq paytida kerak bo‘ladi!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'Ilk nafas mashqlari! 🫁', 'O‘pkamda surfaktant hosil bo‘lmoqda. Bu modda tug‘ilganimda ilk nafasimni olishimga yordam beradi. Mashq qilyapman!'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'Onajon, men zerikdim! 🤸', 'Siz tinch turganingizda men uyg‘onaman. Qorningizni silang, balki sizga kichkina tepki bilan javob berarman?'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'Qovundek bo‘ldim! 🍈', 'Taxminan 600 qram. Endi joyim biroz torayib boryapti. Tepishlarim kuchliroq bo‘lishi mumkin, kechiring! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'Oyoq kiyimingiz siqyaptimi? 👟', 'Oyoq o‘lchamingiz kattalashishi mumkin. Hozir uslub emas, qulaylik muhim. Kengroq sport oyoq kiyimiga o‘ting!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'Sochlarim rangga kiryapti! 🎨', 'Genetik lotereya boshlandi. Sariq, qora yoki malla? Sochlarimda pigment hosil bo‘lyapti. Sizningcha, kimga o‘xsharkanman?'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'Shishlardan charchadingizmi? 🎈', 'Qiziq holat: suv ichish shishni kamaytiradi. Bodring va tarvuz kabi sersuv mahsulotlar ham yordam berishi mumkin. Tuzdan uzoqroq turing.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'Men pushti tusga kiryapman...', 'Terim endi shishadek shaffof emas! Kapillyarlarim qonga to‘lib, rangim pushti tusga kiryapti. Qon aylanishini qo‘llab-quvvatlash uchun Suv kuzatuvchisi orqali suv ichishni unutmang! 🥤'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'Voy! Bu nima ovoz edi? 😳', 'Eshik qarsillab yopilganda cho‘chib ketdim. Eshitish qobiliyatim juda yaxshi, Onajon. Sokin musiqa qo‘ying, birga dam olaylik.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'Burnim ochildi! 👃', 'Burun teshiklarim berk edi, endi ochildi. Nafas olishni mashq qilyapman.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'Hazm sustlashdimi? 🐌', 'Progesteron ichaklar faoliyatini sekinlashtiradi. Turshak, qora olxo‘ri va kepakli non sizga yordam berishi mumkin.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'Yostiqlardan qal’a quring! 🏰', 'Qulay uxlay olmayapsizmi? Oyoqlaringiz orasiga va qorningiz tagiga yostiq qo‘ying. Tayanch bo‘lishi juda muhim!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'Men yoga ustasiman! 🦶', 'Ishonmaysiz, lekin oyog‘imning bosh barmog‘ini ushlab, og‘zimga sola olaman! Juda egiluvchanman. Sizga esa egilish qiyin bo‘lyaptimi?'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'Ko‘zlarimni ochdim! 👀', 'Onajon, ishonmaysiz, lekin qovoqlarimni ochdim. Atrof qorong‘i bo‘lsa-da, nigohim allaqachon shakllanmoqda. Sizni ko‘rishimga oz qoldi!'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'Dadamni eshityapmanmi? 🗣️', 'Erkak kishining ovozi yo‘g‘onroq bo‘lgani uchun uni yaxshiroq eshitaman. Dadam bilan gaplashing, menga ertak o‘qib bersin.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'Siz mening qalqonimsiz!', 'Immun tizimim shakllanmoqda, sizdan menga antitanachalar o‘tmoqda. Meni kasalliklardan himoya qilyapsiz, Onajon. ❤️'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'Oyoqlaringiz tirishib qolayaptimi? 🦶', 'Kechasi boldiringiz tirishib qoladimi? Magniy yetishmayapti. Banan, bodom yoki qatiq... Mushaklaringiz bo‘shashishi kerak.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'Ko‘zlarimni ochdim! 👀', 'Qorong‘i bo‘lsa-da, endi qovoqlarimni ocha olaman. Kipriklarimni pirpiratyapman. Dunyoni ko‘radigan kunimga oz qoldi!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'Yorug‘lik tushyapti, Onajon! ☀️', 'Ko‘zlarimni pirpiratyapman! Agar qorningizga quyosh nuri tushsa, men uning yorug‘ligini ko‘raman. Dunyo qanday rangda?'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'Krem surtish vaqti keldi 🧴', 'Qorningiz tez kattalashmoqda, teringiz taranglashmoqda. Qichishishning oldini olish uchun har kuni namlantiruvchi krem surting.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'Birinchi emlash — sizdan 🛡️', 'Sizdan unga antitanachalar o''tadi. Bu uni tug''ilgandan keyingi dastlabki oylarda himoya qiladi.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'Tuzlangan bodringmi? Yo''q! 🚫', 'Oyoqlaringiz shishayotgan bo''lsa, tuz iste''molini imkon qadar kamaytiring. Tuzlama mazali, ammo shish paydo bo''lishiga sabab bo''ladi. Limonli suv ichishga o''ting.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'Dunyo juda shovqinli... 🔊', 'Quloqlarim shu qadar sezgir bo''lib qoldiki, hatto tashqaridagi signallarni ham eshitaman. Biroz tinchlanamizmi? Menga Oq shovqinlardan yomg''ir ovozini qo''yib bering, birga mizg''ib olamiz. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'Men ritmni ushlayapman 🥁', 'Yuragim bir maromda urmoqda, nafas olishni mashq qilyapman. Ba''zida hiqichoq tutadi.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'Marraga yaqinlashyapmiz! 🏁', '2-trimestrning so''nggi kunlari. 3-bosqich boshlanishidan oldin to''yib uxlab oling!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', 'Xush kelibsiz, 3-trimestr! 🏁', 'So''nggi bosqich boshlandi! Endi tanangiz yanada og''irlashadi, ammo marra chizig''i ko''rinib turibdi. Sabrli bo''ling, onajon!'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'Oshqozoningizda yong‘inmi? 🔥', 'Bachadon oshqozonni yuqoriga siqmoqda. Sut ichish yoki bir hovuch xom bodom yeyish jig‘ildon qaynashini bosishi mumkin.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'Bir bosh brokkolidekman 🥦', 'Endi yog‘ qatlamim ko‘paymoqda, qo‘l va oyoqlarim do‘mboqlashmoqda.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'Uya tayyorlaymizmi? 🐣', 'Mening karavotim, kichkina kiyimlarim... Ro‘yxatni otam bilan birga Birgalikdagi xaridlar bo‘limida tuzing! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'Qon guruhingiz manfiymi? 🩸', 'Rezus omili manfiy bo‘lgan onalar uchun muhim hafta. Immunoglobulin ukoli kerak bo‘lishi mumkin. Shifokoringiz bilan gaplashing!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'Kipriklarim uzaydi! 👁️', 'Ko‘zlarimni ochib-yumaman. Yorug‘lik va qorong‘ilikni farqlay olaman. Qorningizga fonar tutsangiz, yuzimni boshqa tomonga buraman. Sinab ko‘rishni xohlaysizmi?'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'Baliq, baliq, baliq! 🐟', 'Hozir miyam eng tez rivojlanadigan davr. Menga Omega-3 kerak. Haftada 2 marta baliq yeysizmi?'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'Xarakterim qanday bo‘ladi? ✨', 'Qaysar yoki hissiyotga beriluvchan? Tug‘iladigan sanamga ko‘ra burjim men haqimda nima deydi? Sizning burjingizga mos kelamanmi? Keling, munajjimlar bashoratini ko‘ramiz! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'Qovurg‘alaringiz og‘riyaptimi? 🥊', 'Kechiring, Onajon, joyim kamlik qilyapti. Oyoqlarimni uzatganimda qovurg‘alaringizga tegib ketaman. Tik o‘tirish sizga yordam berishi mumkin.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'Tepkilarimni sanayapsizmi? 🦶', 'Endi harakatlanish tartibim shakllanmoqda. Tepki hisoblagichiga kiring va faolligimni kuzating. Hammasi joyidami?'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'Miyam burishmoqda! 🧠', 'Avval silliq edi, endi esa unda burmalar va egatlar paydo bo‘lmoqda. Bu milliardlab neyronlar ishga tushayotganini anglatadi. Daho dunyoga kelmoqda!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'Reflyuks sizni charchatyaptimi? 🔥', 'Oshqozon kislotasi tomog‘ingizga chiqyaptimi? Ovqatdan keyin saqich chaynash yoki iliq sut ichish yordam berishi mumkin.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'Qovoqdek bo‘ldim! 🎃', 'Taxminan 39-40 sm. Vaznim 1.2 kg bo‘ldi! Sizga og‘irlik qilyapmanmi? Kechiring, Onajon, ammo men vazn yig‘ishim kerak.'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'Men shu yerdaman, Onajon! 👋', 'Ba’zan tinchlanaman, ba’zan esa raqsga tushaman. Tepishlarimni sanayapsizmi? Hammasi joyida, shunchaki joyim torayib boryapti.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'Oyoqlaringizda to‘r paydo bo‘ldimi? 🕸️', 'Varikoz tomirlar paydo bo‘lishi mumkin. Uzoq vaqt oyoqda turmang. Kechqurun oyoqlaringizni devorga tirab, yotib dam oling.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'Qon fabrikasi ishga tushdi 🩸', 'Shu paytgacha qon hujayralarini jigar ishlab chiqargan bo‘lsa, endi bu vazifani suyak ko‘migi bajarmoqda. Bu mustaqil hayotga tayyorgarlikdir!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'Temir+C vitamini juftligi 🥩🍊', 'Kamqonlik xavfiga qarshi: Go‘sht yeganda, yoniga apelsin sharbatini iching. C vitamini temirning so‘rilishini 2 baravar oshiradi.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'Katta karam 🥬', 'Terim silliqlashib, yonoqlarim to‘lishmoqda. Sizni ko‘rishga sabrim chidamayapti!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'Nafas ololmayapsizmi? 😮‍💨', 'Men yuqoriga ko‘tarilganim sari diafragmangizni siqaman. Chuqur nafas olishga harakat qiling, Onajon. Oz qoldi, tez orada pastga tushaman.'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'Sumka haqida o‘ylab qo‘ydingizmi? 👜', 'Hali erta emas! Tug‘ruqxona sumkasi ro‘yxatini ko‘rib chiqing. Yetishmayotgan narsalarni hozirdanoq tayyorlab qo‘yish stressni kamaytiradi.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'Bir sirni aytaymi? 🤫', 'Siz uxlayotganingizda ovozingizni xayolimga keltirib, uyquga ketaman. Tushimda kimni ko‘raman, deb o‘ylaysiz? Albatta, sizni! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'Bu shokolad edimi? 🍫', 'Mmm, mazasi bu yergacha yetib keldi! Endi energiyam jo‘sh urmoqda. Keling, raqsga tushamiz, Onajon! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'Qovoqdek bo‘lib qoldim! 🎃', 'Yonoqlarim shunchalik dumaloqlashyaptiki, meni tishlab ko‘rgingiz keladi! Joyim tor, ammo sizga yaqin bo‘lish juda yoqimli.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'Boshim bilan pastga turibman! 🙃', 'Hayotni teskari ko‘rish qiziq ekan! Tug‘ilishga tayyorlanyapman, Onajon. Shu holatda sizga yanada yaqinman.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'Qorningiz qotib qolyaptimi? 🤰', 'Qo‘rqmang, azizam! Bu shunchaki mashq. Biz bir jamoa bo‘lib, o‘sha buyuk kunga tayyorlanyapmiz!'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'Dadamning ovozi eshitildi! 🧔', 'Uning ovozini eshitganimda yuragim yanada tezroq uradi. Unga men ham shu yerda ekanimni va salom yo‘llayotganimni ayting! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'Suyaklarimni mustahkamlang! 💪', 'Menga kalsiy kerak, Onajon. Bir stakan sut yoki qatiq ichsangiz, ikkalamiz ham juda kuchli bo‘lamiz! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'Taq-taq! U yerda kim bor? ✊', 'Tepishlarim ba’zan sizni og‘rityaptimi? Kechiring 🥺 Shunchaki sizga tegishni xohlayapman.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'Nafasingiz qisilyaptimi? 😮‍💨', 'Men biroz yuqoriga ko‘tarilib, o‘pkangizni siqib qo‘yyapman. Kechiring, Onajon, tez orada pastga tushaman va siz bemalol nafas olasiz! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'Hidingizni his qilaman...', 'Meni bag‘ringizga bosadigan o‘sha onni o‘ylayapsizmi? Men har kuni o‘sha onni orzu qilib ulg‘ayyapman, Onajon! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'Uyim torayib boryapti... 🏠', 'Harakatlarim musht va tirsak zarbalariga aylanmoqda. Hammasi joyidami? Keling, birgalikda Tepkilar hisoblagichini tekshiramiz!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'Manikyurim tayyor!', 'Ishonmaysiz, tirnoqlarim allaqachon barmoq uchlarimga yetib keldi.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'Shifokor ko‘riklari ko‘payadi! 🩺', 'Tug‘ruqxona va tug‘ruqni qabul qiladigan shifokorni tanladingizmi? Shifokorlar va klinikalar ro‘yxatini ko‘rib chiqing! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'Bir kulib, bir yig‘layapsizmi?', 'Gormonlar yana o‘z o‘yinini boshladi. Tug‘ruqdan qo‘rqish va chaqaloq bilan uchrashish quvonchi bir-biriga aralashib ketgan. Kayfiyat kundaligiga dardingizni yozib, yengil torting. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'Sizdan menga super kuch o‘tadi! 🛡️', 'Kasal bo‘lmang, Onajon! Sizning immunitetingiz mening ilk qalqonim bo‘ladi. Biz yengilmas jamoamiz! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'Yana uyqungiz qochdimi? 🥺', 'Men esa mazza qilib uxlayapman. Ko‘zlaringizni yuming, meni tasavvur qiling... Balki tushlarimiz birlashar? 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'Suyaklarim toshdek qattiq bo‘lib boryapti! 🦴', 'Ammo buning uchun sizning zaxirangizni o‘g‘irlayapman... Kechiring! 🙈 Bir stakan sut ichsangiz, yarashamizmi? 🥛'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'Sizga toza havo kerak 🌿', 'Bugun uydan chiqib, havosi toza va shinam joyda choy ichamizmi? Onalar uchun qulay joylarni ko‘rib chiqing!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'O‘sha katta kun... ✨', 'Shoshilmaylik, ammo sumkamizni asta-sekin tayyorlab qo‘yaylik. Tug‘ruqxona sumkasi ro‘yxatida nimalar borligini ko‘rib chiqamizmi?'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'Shshsh... Men uxlayapman 😴', 'Miyam shu qadar tez rivojlanmoqdaki, ko‘p vaqtimni uyquda o‘tkazaman. Siz ham dam oling, Onajon.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'Menga qanday ism qo‘yasiz? 👶', 'Agar hali qaror qilmagan bo‘lsangiz, otam bilan Chaqaloq ismlari ro‘yxatini ko‘rib chiqing. Qaysi ism menga ko‘proq yarashadi?'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'Xonam, karavotim, mitti buyumlarim... 🐣', 'Bizga kerak bo‘ladigan hamma narsani oldingizmi? Tavsiya etilgan mahsulotlarni ko‘rib chiqing, balki nimadir esdan chiqqandir.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'Bachadon mushaklari tug‘ruqqa tayyorlanmoqda.', 'Qo‘rqmang, bu shunchaki mashq. Agar og‘riqlar tez-tez takrorlansa, To‘lg‘oq o‘lchagich yordamida ular orasidagi intervalni tekshiring!'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'O‘sha qo‘shiqni yana bir bor kuylang! 🎶', 'Ovozingiz menga shunchalik taskin beradiki... Siz kuylaganingizda men ichkarida raqsga tushaman, sezyapsizmi? 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'Devorlar ustimga yopirilyapti! 🏠', 'Joyim juda torayib qoldi, Onajon. Oyog‘imni uzatsam, qovurg‘angizga tegadi... Og‘ritib qo‘ygan bo‘lsam, o‘pib tuzataman, xo‘pmi? 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'Kiyimlarimni dazmolladingizmi? 👗', 'Ularning hidi hozirdanoq dimog‘imga kelayotgandek. Meni o‘sha kiyimlarda ko‘rishni intiqlik bilan kutayotganingizni bilaman! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'Hovuzimning suvi kamayibdi... 💧', 'Men toza va mo‘l suvda suzishni yaxshi ko‘raman. Men uchun bir stakan suv ichasizmi? 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'Yo‘lni tekshiryapman! 🔦', 'Boshim pastda, chiqish eshigiga qarab turibman. Siz faqat chuqur nafas oling, hammasi a’lo bo‘ladi!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'Bu kimning iliq qo‘li? 🖐️', 'Dadammi? Uning teginishini his qilganimda tinchlanaman. Unga ayting, men ham qo‘limni qo‘ydim, besh beraylik! ✋'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'Ko‘zlarimni katta-katta ochdim! 👀', 'Qorong‘i bo‘lsa ham, hamma narsani kuzatyapman. Sizga o‘xsharmikanman yoki dadamga? Garov o‘ynadingizmi? 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'Shshsh... Men uxlayapman! 😴', 'Miyam shunchalik tez rivojlanyaptiki, menga ko‘p uyqu kerak. Siz ham men bilan birga uxlang, Onajon? 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'Uyda o‘zgarish qilyapsizmi? 🌪️', 'Hamma joyni tozalash, shkaflarni tartibga keltirishni xohlaysiz... Bu uya qurish instinkti! Ammo o‘zingizni charchatmang, menga yaxshi dam olgan ona kerak.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'Bu yer juda tor! 🏠', 'Aylanmoqchiman, ammo joyim yo‘q. Tirsagimni chiqarsam, qorningiz qiyshayib ko‘rinadi. Ko‘rib kulasiz! 😄'),
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8', 'Menga yog‘ kerak! 🥑', 'Avokado, yong‘oq yoki zaytun moyi... Meni do‘mboqqina qilish sizning qo‘lingizda!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'Yuragingiz menga alla aytadi... 💓', 'Boshim pastda, qulog‘im yuragingizga yanada yaqinroq. Bu ritm meni tinchlantiradigan yagona musiqadir.'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'Men kuch to‘playapman! ⚡', 'Ko‘p harakat qilmayapmanmi? Qo‘rqmang. Hozir menga uyqu kerak. Katta kun uchun kuch to‘playapman. Siz ham dam oling! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'Tirsagimni sezdingizmi? 💪', 'Kechiring, Onajon! Kerishgim kelyapti, ammo joyim yo‘q. Qorningiz qiyshiq-qing‘ir bo‘lib ko‘ringanda ustimdan kulasizmi? 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'Pingvindek yuribsizmi? 🤭', 'Men pastga tushganim uchun yurishingiz o‘zgardi. Ammo siz har qanday holatingiz va yurishingiz bilan dunyodagi eng go‘zal onasiz! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'Hiq... Hiq... 😲', 'Yana hiqichoq tutdi! Diafragmamni mashq qildiryapman. Qorningiz bir maromda sakrasa, bilingki, bu menman!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800'::uuid, 'Shifokor bilan ko‘rishdikmi? 👩‍⚕️', 'O‘sha sovuq gel qorningizga tekkanda qitiqlanaman! 🙈 Ammo yurak urishimni eshitish sizga xotirjamlik berishini bilaman.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'Biz bir jamoamiz! 🤝', 'To‘lg‘oq boshlanganda qo‘rqmang. Chuqur nafas oling. Biz birgalikda uddalaymiz, va’da beraman!'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'Xonam tayyormi? 🧸', 'Beshigimga qarab, xayol suryapsizmi? U yerga qo‘ygan o‘yinchog‘ingizni quchoqlashga sabrim chidamayapti! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'Pastga tushyapman, sezyapsizmi? ⬇️', 'Tos suyaklaringiz orasiga joylashyapman. Endi erkinroq nafas olasiz, ammo hojatxonaga tez-tez yugurishingizga to‘g‘ri keladi! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'Immunitetim mustahkamlanmoqda 🛡️', 'Sizdan menga o‘tayotgan antitanachalar meni mikroblar olamiga tayyorlamoqda. Sut bilan ham meni himoya qilasiz, Onajon!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'Mening ilk kiyimim qani? 👕', 'Tug‘ruqxona sumkasini tayyorlab qo‘ydingizmi? Menga kiydiradigan o‘sha mitti kiyimchani silab qo‘ying...'),
  ('deba1190-6096-4dec-88eb-70e669fb3ccb', 'Sizni ko‘rishni istayman! 👀', 'Ko‘zlarim ochiq, ammo bu yer qorong‘i. Yuzingizni, tabassumingizni ko‘rish uchun kunlarni sanayapman. Oz qoldi! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'Terim silliqlashmoqda! 🧖‍♀️', 'Mayin tuklarim to‘kilib, yog‘ qatlamim ko‘paymoqda. Sizning o‘sha nozik teginishingizga tayyorlanyapman, Onajon. Yumshoq bo‘laman! ☁️'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'Uxlay olmayapsizmi? 🥺', 'Ko‘zingizga uyqu kelmayaptimi? Keling, tug‘ilganimdan keyin menga eshittiradigan tovushlarni hozirdanoq birga tinglaymiz. Oq shovqinlar bo‘limi ikkalamizni ham tinchlantiradi. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'Chamodonimni yig‘ib, eshik oldida kutyapman! 🚪', '38 hafta! Endi rasman tug‘ilishga tayyorman. O‘pkam, miyam — hamma a’zolarim to‘liq rivojlangan.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'Suvingiz ketsa, nima qilasiz? 💦', 'Vahimaga tushmang! Blog bo‘limidagi Tug‘ruqning 3 ta asosiy belgisi maqolasini o‘qing.'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'Pastga tushyapman... ⬇️', 'Chanoq suyaklaringizga bosim qilayotganimni bilaman. Ammo bu siz bilan uchrashishimning yagona yo‘li. Mening sabrli Onajonim! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'Uyqusiz tunlar? 🥱', 'Tug‘ruq yaqinlashgani sari uxlab qolish qiyinlashishi mumkin. Shu tariqa tanangiz sizni chaqaloq rejimiga tayyorlaydi.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'Yuragim qanday uryapti? 💓', 'Meni sog‘inganingizda qo‘lingizni qorningizga qo‘ying. Yuraklarimiz bir maromda uradi. Hammasi joyida, faqat uchrashadigan kunimizni kutyapmiz. 🗓️'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'Taq-taq, bu men! ✊', 'Qorningizda to‘lg‘oq boshlanib, keyin qo‘yib yuboryaptimi? Vaqtni boy bermang, To‘lg‘oq o‘lchagich tugmasini bosing. Agar to‘lg‘oqlar orasidagi vaqt qisqarayotgan bo‘lsa, demak, katta kun bugun! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'Oltin sut keldimi? ✨', 'Ko‘krakdan sarg‘ish suyuqlik ajralishi mumkin — bu chaqaloq uchun ilk emlashdek himoyadir. Bloglarda emizish haqida o‘qing. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'Soxta yoki haqiqiy? 🤔', 'Qorningiz taranglashib, keyin bo‘shashyaptimi? Agar to‘lg‘oqlar muntazam bo‘lmasa, ular soxta to‘lg‘oqdir. Ishonch hosil qilish uchun To‘lg‘oq o‘lchagichni ochib, tekshirib ko‘ring!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'Shilliq tiqin tushdimi? 🩸', 'Quyuq shilliq ajralma tushgan bo‘lsa, demak, bachadon bo‘yni ochila boshlagan. Qo‘rqmang, bu shunchaki tayyorgarlik ko‘rish vaqti kelganidan darak.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'Shalop! Bu qanday ovoz edi? 💦', 'Suvingiz ketsa, vahimaga tushmang. Shunchaki chuqur nafas oling va shifokoringizga xabar bering. Men kelyapman! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'Stressni haydash kerak! 😮‍💨', 'Hayajondamisiz? Mashqlar bo‘limidagi Tug‘ruqda nafas olish usullarini hozirdanoq o‘rganing. To‘lg‘oq paytida ular sizga juda asqatadi.'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'Sumkalar eshik oldidami? 🎒', 'Istalgan payt «Syurpriz!» deyishim mumkin. Menga kiydiradigan o‘sha birinchi qalpoqchani sumkaga soldingizmi? Sovqotishni istamayman. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'Marraga oz qoldi! 🏆', '37-hafta tugayapti! Endi erta muddat bosqichidamiz. Ya’ni bugun tug‘ilsam ham, o‘pkalarim nafas olishga tayyor!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'Tushimda sizni ko‘rdim... 💤', 'Ovozingiz, hidingiz, taftingiz... Uyg‘onib, sizni chinakamiga quchoqlashni sabrsizlik bilan kutyapman, Onajon!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'Qorningiz taranglashdimi? 🤰', 'Bu shunchaki mashqmi yoki men kelyapmanmi? Shubhangiz bo‘lsa, To‘lg‘oq hisoblagichini oching. U sizga aniq aytadi: shifoxonaga borish kerakmi yoki yotib dam olishmi?'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'Men hali ham shu yerdaman! 👋', 'Joyim juda tor, shuning uchun kamroq qimirlab turibman. Ammo xavotirda bo‘lsangiz, Tepki hisoblagichiga kiring. Keling, birga sanaymiz! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'Paypoqlarimni soldingizmi? 🧦', 'Men sovqotishni istamayman, Onajon! Tug‘ruqxona sumkasi ro‘yxatini so‘nggi marta tekshirib chiqing. Mening birinchi kombinezonim u yerdami? 🥰'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'Tabiiy usulda yordam 🍍', 'Xurmo va ananas bachadon bo‘ynini yumshatishi aytiladi. Bugun ovqatlanish bo‘limida ularni menyuingizga qo‘shing. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'Yurak urishlari... ❤️', '40 haftadan o‘tganda yo‘ldoshning holatini tekshirish uchun KTG (NST) tekshiruvi muhim. Hammasi joyida ekaniga ishonch hosil qiling.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'Zinadan chiqamizmi? 🪜', 'Menga yo‘l ko‘rsating! Zinadan chiqish yoki cho‘kkalab o‘tirish pastga tushishimga yordam berishi mumkin. Mashqlar bo‘limiga qarang.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'Bu yerda juda qulay 🌡️', 'Iliq, qorong‘i va qulay... Chiqishni istamayman desam, mendan jahlingiz chiqmaydimi? 🥺 Hazillashdim, kelyapman!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'Yuragim qanday uryapti? 💓', 'Shifokor huzurida NST tekshiruvidan o‘tyapmizmi? O‘sha dup-dup ovozini eshitganingizda qanchalik xotirjam bo‘lasiz...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'Xurmo yeyapsizmi? 🌴', 'Tabiiy tug‘ruq uchun bu mazali usulni sinab ko‘rishga arziydi!'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'Men semiryapman-ku! ⚖️', 'Bu yerda qolgan har bir kunimda yanada dumaloqlashib boryapman. Yonoqlarim shirinlashmoqda, ammo sizga tobora qiyin bo‘lyapti. Kechiring! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'Sumkaga yegulik soldingizmi? 🍫', 'Tug‘ruqdan keyin juda och qolasiz! Tug‘ruqxona sumkasiga sevimli pechenye yoki shokoladingizni solib qo‘ying.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'Yo‘ldosh qarib qolyaptimi? 🍂', 'Shifokor homila suvi miqdorini tekshiryaptimi? Menga hali ham kislorod yetib kelayotgan bo‘lsa, demak, muammo yo‘q. Shunchaki birga o‘tkazadigan so‘nggi kunlarimiz.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'Kechasi to‘lg‘oq boshlandimi? 🌙', 'Uyqudan uyg‘otgan o‘sha og‘riq... Bu haqiqiy to‘lg‘oqmi? Vaqtni boy bermang, To‘lg‘oq o‘lchagichni ishga tushiring. Balki bugun AYNAN O‘SHA TUNDIR! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'Ko‘chirish buyrug‘i keldimi? 📢', 'Shifokor sun’iy to‘lg‘oqni taklif qilyaptimi? Qo‘rqmang. Eng muhimi — men sog‘-salomat quchog‘ingizga yetib borishim. Qaysi yo‘l bilan ekanining farqi yo‘q!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'Homiladorlikdagi so‘nggi suratingiz... 📸', 'Bu qoringa so‘nggi bor qarang. Balki ertaga men quchog‘ingizda bo‘larman. Mo‘jizakor tanangiz bilan faxrlaning, Onajon!'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'Tepishlarim kamayib qoldimi? 🦶', 'Joyim juda tor, Onajon! Ammo harakatlarimni his qilishingiz kerak. Agar shubhangiz bo‘lsa, shirin narsa yeng va Tepishlar hisoblagichiga kiring.'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'Hujjatlar joyidami? 📄', 'Shaxsni tasdiqlovchi hujjat, tahlil natijalari... Sumkangizni yana bir bor tekshiring. Tug‘ruqxona sumkasi ro‘yxatidagi hamma narsani belgilab chiqdingizmi? ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'Ko‘zlaringizni yuming... 😌', 'Tug‘ruqdan qo‘rqmang. Shunchaki meni ilk bor bag‘ringizga bosadigan o‘sha onni tasavvur qiling. O‘sha hid barcha og‘riqlarni unuttiradi.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'Serviks (Bachadon bo‘yni) 🗝️', 'Yashirin ish ketmoqda! Bachadon bo‘yni yumshaydi, yupqalashadi va ochiladi. Siz buni his qilmasangiz ham, tanangiz men uchun eshikni ochmoqda.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'Bugun o‘sha kunmi? 🗓️', '40 hafta to‘ldi! Taqvim aynan bugunni ko‘rsatmoqda. Kelaymi yoki yana biroz noz qilaymi? Istalgan lahzada sizga syurpriz qilishim mumkin! Tayyor bo‘ling! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'Men kechikkanim yo‘q! 👑', 'Shunchaki, yulduzlar sahnaga eng oxirida chiqadi, Onajon! Yana biroz noz qilay, keyin kelaman. Sabr qiling! 😌')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c'::uuid, 'Chaqalog‘ingizning emish refleksi juda kuchli! 🍼', 'Har bir emizish vaqtini taymer yordamida kuzatib, uning yetarlicha to‘yganiga ishonch hosil qiling.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'Sababsiz ko‘nglingiz bo‘shab ketyaptimi? 😢', 'Bu mutlaqo tabiiy! Anacan AI yoki Hamjamiyatimizda his-tuyg‘ularingizni baham ko‘rib, yordam olishingiz mumkin.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'Chaqalog‘ingizni uxlatishda qiynalyapsizmi? 🎶', 'Ilovamizdagi Oq shovqin vositasini yoqing — chaqalog‘ingiz ona qornidagidek chuqur uyquga ketsin.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'Kindik qoldig‘i quruq va toza saqlanishi kerak. ⏱️', 'Agar kindik qoldig‘i ho‘l bo‘lib qolsa, uni albatta quritish va shifokor buyurgan antiseptik eritmani har kuni qo‘llash kerak.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'Onalarning vitaminlarga boy ovqatlanishi juda muhim! 🥗', 'Sog‘lom retseptlar bo‘limini ko‘rib chiqing va kuchingizni tiklang.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'U sizni hidingiz va ovozingizdan taniydi! 👃', 'Shu sababli siz xonadan chiqib ketganingizda, chaqalog‘ingiz bezovtalanib, o‘zini xavf ostida his qiladi.'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', 'Chaqaloq quchoqqa o‘rganib qoladi degan afsonalarga ishonmang! 🤗', 'Chaqalog‘ingizni tez-tez quchoqlang. Bu nafaqat orangizdagi rishtani mustahkamlaydi, balki sutingizni ham ko‘paytiradi.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'Kecha bilan kunduz almashib qoldimi? 🛌', 'Uyqu tartibi va kundalik me’yorlarni ilova orqali kuzatib boring, chaqalog‘ingiz uxlaganda siz ham ko‘zingizni yuming.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'Muntazam ko‘riklar boshlanadi. 💉', 'Chaqalog‘ingizning bo‘yi va vazni haqidagi ma’lumotlarni Rivojlanish kuzatuvchisiga kiritib, uning shaxsiy rivojlanish grafigini yarating!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'Oraliqlarni unutmaslik uchun taymer shu yerda. 🍼', 'Taglik almashtirish va ovqatlantirish vaqtlarini Anacan yordamida osongina tartibga soling.'),
  ('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c', 'Super ona bo‘lishga majbur emassiz! 🦸‍♀', '️ Yordam so‘rashdan tortinmang. Ruhlantiruvchi maslahatlar uchun Bloglar bo‘limimizdagi maqolalarni o‘qing.'),
  ('ded576fe-d3fa-4078-9b83-36eaf5b495d5', 'Rivojlanishni qadamma-qadam kuzatib boring. 📏', 'Bosh aylanasi, bo‘yi va vazni haqidagi ma’lumotlarni Vazn kuzatuvchisiga kiritishni unutdingizmi? Hozir qayd eting.'),
  ('1af46170-3a5b-41ea-bb18-ce899698f996', 'Birinchi kuningiz muborak! 🥳', 'Chaqalog‘ingizning uyqu va ovqatlanish tartibini kuzatish uchun Anacan ilovasidagi taymerdan foydalanishni boshlang.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'Chaqalog‘ingiz uxlayotganda siz ham dam oling! 😴', 'Bugun o‘zingizni qanday his qilganingizni Kayfiyat kundaligiga yozishni unutmang.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'Og‘iz suti — ilk emlashdir! 🤱', 'Ovqatlantirish me’yorini ilovadagi Ovqatlanishni kuzatish vositasi yordamida osongina qayd eting.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', '«Sutim kam», deb xafa bo‘lmang! 🥛', 'Chaqalog‘ingizning oshqozoni hali gilosdek kichkina. Kundalik ovqatlanish statistikasini ilovada kuzatishingiz mumkin.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'O‘zingizga vaqt ajrating. 💆‍♀', '️ Bachadon mushaklaringiz tiklanmoqda. Bugungi his-tuyg‘ularingizni Kayfiyat kundaligiga qayd etib, yengil torting.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'Chaqaloq terisidagi oq qoplama uni himoya qiladi. 👶 Xavotir olmang.', 'Taglikni almashtirganda buni Anacan ilovasida qayd etib, me’yorlarni tekshirishni unutmang!'),
  ('0240c7db-30e2-4d5b-86a4-0b27f230557c', 'Dadasining bag‘ri 🫂', 'Birinchi haftadagi charchoq butun vujudingizga singib ketgan. Bugun kechqurun chaqaloq dadasining ko‘ksida uxlasin, u Oq shovqinlarni yoqib qo‘ysin. Siz esa iliq dush qabul qilib, yopiq eshik ortida bor-yo‘g‘i 15 daqiqaga suv ostida hamma narsani unuting. Siz buni uddalaysiz.'),
  ('7449500c-dd2f-4529-a9a7-67ddeee4fe31', 'Tummy time (qorni bilan yotish) vaqti! 🐢', 'Chaqaloq uyg‘oq paytida uni 1-2 daqiqaga qorni bilan yotqizing va mushaklarini mustahkamlang.'),
  ('74dae015-c762-4d96-ad34-7d706065ef5f', 'Tabriklaymiz, ona bo‘lganingizga 1 hafta bo‘ldi! 🥳', 'Tabriklaymiz, ona bo‘lganingizga 1 hafta bo‘ldi! 🥳 Chaqaloq fotosessiyasi bo‘limidan foydalanib, ushbu alohida kun uchun esdalik suratini yarating.'),
  ('7c7a5fbe-09ea-4f4c-a054-883ad490f939', 'Birinchi hafta tahlillarini ko‘rib chiqamizmi? 📊', 'Anacan ilovasida uyqu, taglik va oziqlantirish bo‘yicha haftalik statistikangizni tekshirishni xohlaysizmi?'),
  ('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c', 'Jismoniy tiklanish 🩹', 'Tanangiz hali ham tiklanmoqda, ehtimol, choklaringiz ham og‘riyotgandir. O‘zingizdan mukammallikni talab qilmang.'),
  ('d83a6f20-2dc5-45c9-9550-38fedec5c042', 'Ichak mikroflorasi shakllanmoqda! 🦠', 'Agar qorin dam bo‘lishi va sanchiqlar boshlangan bo‘lsa, Anacan ilovasining Oq shovqinlar bo‘limidagi ohanglar chaqaloqning tinchlanishiga yordam beradi.'),
  ('092f30cd-002d-4c4e-a83e-0b13c38cc743', 'Chaqalog‘ingizning nigohi tiniqlashmoqda! 👀', 'U endi yuzingizni yaxshiroq taniydi. Ushbu yoqimli lahzalar sizda uyg‘otgan his-tuyg‘ularni Kayfiyat kundaligiga yozing.'),
  ('20684bd3-d3fb-479e-89f1-9adf84e485af', 'Ovqatlantirish tartibi qanday ketyapti? 🤱', 'Ilovadagi taymerni ishga tushiring va ovqatlantirish me’yorini Ovqatlanishni kuzatish vositasi yordamida osongina nazorat qiling.'),
  ('7797557a-9277-450c-98b3-b0fa58923513', 'Kechki cho‘miltirishdan so‘ng uxlash vaqti! 🛁', 'Chaqalog‘ingiz osongina uxlab qolishi uchun uni tungi uyqudan oldin cho‘miltirish juda foydali.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'Kunlik tagliklar sonini kuzatyapsizmi? 🧷', 'Chaqaloqning to‘yganini ko‘rsatuvchi eng yaxshi belgi — uning tagliklari. Har safar almashtirganingizda Anacan ilovasida qayd etishni unutmang!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'Uyqu tartibini tahlil qilamiz. ⏱️', 'U uxlayotganda uyqu taymerini yoqing va chaqalog‘ingiz kunlik uyqu me’yoriga qanchalik rioya qilayotganini grafik orqali ko‘ring.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'Onalar uchun mazali va foydali tanlov! 🍲', 'Quvvatingizni oshiradigan Sog‘lom retseptlar bo‘limimizni ko‘rib chiqing va o‘zingizga yaxshi g‘amxo‘rlik qiling.'),
  ('3258a482-400c-485d-af7c-ccb221416732', 'Tunda uyg‘onishlar sizni charchatyaptimi? 😴', 'Kayfiyat kundaligiga bugungi his-tuyg‘ularingizni yozib qo‘ying, Anacan AI sizga foydali maslahatlar bersin.'),
  ('80a2cd79-a6d6-4c87-b540-c42931228485', 'Chaqalog‘ingizning oshqozoni kattalashmoqda. 🍒', 'Oziqlanishni kuzatish vositasida iste’mol qilgan miqdorini qayd etib, kunlik me’yorni tekshiring.'),
  ('cdd7b6ae-f340-479e-9d33-221c6775ebb3', 'Chaqaloqni qattiq yo‘rgaklamang, erkin harakatlansin! 🚫', 'Foydali ma’lumotlar va zamonaviy yondashuvlar haqida ko‘proq o‘qish uchun bloglarimizga kiring.'),
  ('1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'Sutingiz endi kaloriyaga boy yetilgan sutga aylanmoqda. 🥛', 'Emizish taymerini yoqing va chaqalog‘ingiz bugun qancha oziqlanganini aniq o‘lchang!'),
  ('9a18572b-e386-4df8-ba20-b5eb78b8f99f', 'Dastlabki 10 kun qanday o‘tdi? 📸', 'Uyqusizlik, qo‘rquvlar, ba’zan ko‘z yoshlar va ulkan sevgi to‘lqini... Dastlabki 10 kunni, ya’ni eng qiyin boshlang‘ich davrni ortda qoldirdingiz! Siz ajoyibsiz.'),
  ('ffd7ff0c-bf80-4552-8a28-8d30f0674b07', 'Bugun hech bo‘lmasa 15 daqiqani faqat o‘zingizga ajrating. 🛁', 'Iliq dush qabul qiling va ilovadagi foydali retseptlar bilan o‘zingizni siylang.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'Chaqalog‘ingiz tez o‘smoqda! ⚖', '️ Haftalik vaznini Rivojlanish kuzatuvchisiga kiriting va uning sog‘lom rivojlanish egri chizig‘ini ilovada kuzatib boring.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'Savolingiz bormi? 🤖', 'Hatto tunda ham Anacan AI siz bilan! Sizni tashvishga solayotgan savollarni bering va darhol yordam oling.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'Birgalikdagi ilk sayrlar! 🌳', 'Havo yaxshi bo‘lsa, tashqariga chiqing. Chaqalog‘ingizning har kuni toza havoda bo‘lishi juda muhim va foydali.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'Lahzalarni abadiylashtiring! 📸', 'Bugungi yoqimli lahzalarni Chaqaloq albomiga yuklang va kelajakda ko‘rib, tabassum qiladigan xotiralarni yarating.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'Uyqu va oziqlanish o‘rtasidagi muvozanat. 📚', 'Bloglar bo‘limidagi yangi tug‘ilgan chaqaloqlarning rivojlanishi haqidagi eng so‘nggi maqolamizni o‘qidingizmi?'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'Tabriklaymiz, chaqalog‘ingiz 2 haftalik bo‘ldi! 🎈', 'Ushbu kichik yubileyni nishonlash uchun Chaqaloq fotosessiyasi bo‘limidagi qiziqarli mavzulardan foydalaning.'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'Ba’zan oziqlantirish vaqti cho‘zilishi mumkin. 🍼', 'Taymer yordamida jarayonni tahlil qiling. Eng muhimi, siz ham, chaqalog‘ingiz ham o‘zingizni qulay his qilishingizdir.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'O‘zingizni qanday his qilyapsiz? 🧘‍♀', '️ Onalik ham go‘zal, ham charchatadigan davrdir. Kayfiyat kundaligiga kiring va bugungi kunni baholang.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'Chaqaloq parvarishi uchun yana nimalar kerak? 🧴', 'Boshqa onalar sinab ko‘rgan va yoqtirgan mahsulotlarni Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'Taglik almashtirish endi odatiy yumushga aylandi! 👶', 'Chaqalog‘ingizning salomatligini kuzatib borish uchun uning kunlik siydik va najas chiqarishini taglik kuzatuvchisiga qayd eting.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'Ona ham dam olishi kerak! 🛋', '️ Agar chaqalog‘ingizning uyqu rejimini taymer yordamida qayd etgan bo‘lsangiz, endi navbat sizniki. O‘zingizga choy quyib, dam oling.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'Qorin dam bo‘lishidan og‘riq bezovta qilyaptimi? 🌪️', 'Vahimaga tushmang. Chaqalog‘ingizning qornini yengil massaj qiling va chalg‘itish uchun fonda Oq shovqinlarni yoqing.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'Qorin bilan yotish vaqti! 🐢', 'Kuniga bir necha daqiqa qorin bilan yotish uning bo‘yin mushaklarini mustahkamlaydi.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'Tungi uyquga tayyorgarlik. 🌙', 'Uxlashdan oldin xona haroratini sozlang va Anacan ilovasidagi uyqu taymerini ishga tushiring.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'Sutingizni ko‘paytiradigan sirlar! 🥛', 'Sog‘lom retseptlar bo‘limida sutni ko‘paytirishga yordam beradigan tabiiy mahsulotlar va smuzi retseptlari sizni kutmoqda.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'Rivojlanishdagi sakrash bo‘lishi mumkin. 📈', 'Hech qanday sababsiz chinqirib yig‘layaptimi? 3-haftadagi rivojlanish xuruji gaz sanchig‘i eng kuchayadigan davrga ham to‘g‘ri keladi. Vahimaga tushmang.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'Quchoqqa mahkum 🛋️', 'Chaqaloqni joyiga qo‘yishingiz bilan uyg‘onib, yig‘layaptimi? Bugun to‘rt devor orasida uni quchoqdan qo‘ymay o‘tirishga mahkumdek his qilishingiz mumkin. Ammo chaqalog‘ingiz uchun eng xavfsiz joy sizning quchog‘ingiz ekanini unutmang. Sabrli bo‘ling.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'Turmush o‘rtog‘ingizni ham jarayonga jalb qiling. 👨‍👩‍👦', 'Bugun kechqurun taglikni almashtirish yoki Oq shovqinlar yordamida uxlatish navbatini unga bering, o‘zingiz esa dam oling.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'Teri parvarishi vaqti. 🛁', 'Chaqalog‘ingizning nozik terisiga mos kremlar izlayapsizmi? Tavsiya etilgan mahsulotlar ro‘yxati sizga yordam beradi.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'Reflekslar rivojlanmoqda! 🖐️', 'Chaqalog‘ingiz barmog‘ingizni qanchalik mahkam ushlaydi? Bu haqda batafsil bilish uchun Bloglardagi maqolalarimiz bilan tanishing.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'Kundalik hisobotingiz tayyor! 📊', 'Anacan ilovasiga kirib, bugungi uyqu, ovqatlanish va taglik almashtirish grafiklari tahlilini ko‘rib chiqing.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'O‘sish bosqichini kuzatamiz! 📏', 'Keyingi oy yaqinlashmoqda. Ilovadagi Rivojlanish kuzatuvchisi bo‘limiga kirib, ma’lumotlarni yangilaganingizga ishonch hosil qiling.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'Birga ekaningizga 20 kun bo‘ldi! 🥰', 'Siz ajoyib onasiz! Chaqaloq fotosessiyasi vositasi yordamida bu kunni go‘zal xotiraga aylantiring.'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'Bugun faqat ijobiy his-tuyg‘ular! ✨', 'Kayfiyat kundaligingizni oching va chaqalog‘ingiz sizni eng ko‘p kuldirgan lahzani qayd eting. Anacan AI sizni tinglaydi!'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'Rivojlanishdagi keskin o‘sish davri! 📈', 'Chaqalog‘ingiz tez-tez och qolishi mumkin. Taymerli oziqlantirish yordamida jarayonni kuzatib boring.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'Kechki bezovtalik kuchaydimi? 🎶', 'Bunga qorin dam bo‘lishi yoki charchoq sabab bo‘lishi mumkin. Uni Oq shovqinlar bo‘limidagi tabiat tovushlari bilan tinchlantiring.'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'Ro‘ppa-rosa 3 haftalik! 🎉', 'Chaqalog‘ingizning ushbu kichik yubileyini nishonlash uchun Chaqaloq fotosessiyasi bo‘limidan foydalanib, yoqimli bir lahzani abadiylashtiring.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'O‘zingizni unutmang! 🥗', 'Sizning sog‘lig‘ingiz — uning ham sog‘lig‘i. Ayollar uchun foydali retseptlar orasidan quvvatingizni tiklaydigan yengil tamaddini tanlang.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'Kunlik uyqu me’yori muhim. 😴', 'Chaqalog‘ingiz uxlaganda uyqu taymerini ishga tushiring va uning uyqusi kunlik me’yorga qanchalik mos kelishini tekshiring.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'Boshini ko‘tarishga urinmoqda! 🐢', 'Qorni bilan (tummy time) yotganida qilgan harakatlarini Chaqaloq albomiga video sifatida qo‘shing.'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'Savolingiz bormi? 🤖', '“Nega chaqalog‘im kechasi tez-tez uyg‘onadi?” kabi sizni o‘ylantirayotgan savollarga javob berishda Anacan AI doim yordamga tayyor.'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'Kunlik taglik ko‘rsatkichlari qanday? 🧷', 'Chaqalog‘ingiz yetarlicha oziqlanayotganini bilishning eng oson yo‘li — taglik almashtirish qaydlarini yuritish. Ularni hoziroq ilovaga kiriting!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'Ilk tabassum yaqinlashmoqda! 😊', 'Uning yuzingizga diqqat bilan qarayotgan lahzalarini o‘tkazib yubormang. Bu lahzalar sizda uyg‘otgan his-tuyg‘ularni Kayfiyat kundaligiga yozing.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'Kun tartibini shakllantirishni boshlaymiz! 🌙', 'Har kuni bir vaqtda cho‘miltiring, emizing va Oq shovqinni yoqib, uyqu taymerini ishga tushiring.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'Onalik ehtiyojlaringizni unutmang. 🛍', '️Ko‘krak uchi kremi va ko‘krak prokladkalaridan foydalanish o‘zingizni qulayroq his qilishingizga yordam beradi va himoyani ta’minlaydi.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'Ochiq havoda sayr qilish vaqti! ☀️', 'Bemalol dam olishingiz mumkin bo‘lgan, chaqaloq bilan borishga qulay joy qidiryapsizmi? “Onalar uchun qulay joylar” blogimizni albatta ko‘rib chiqing.'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'Vaqt topganingizda o‘qing va o‘rganing. 📚', 'Yangi tug‘ilgan chaqaloqlarning rivojlanishi va parvarishi haqidagi eng foydali maqolalar sizni Bloglar bo‘limida kutmoqda.'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'Birinchi oy ko‘rigi yaqinlashmoqda. ⚖️', 'Chaqalog‘ingizning shu paytgacha vazni va bo‘yi qanchaga o‘sganini Rivojlanishni kuzatish bo‘limiga kiritganingizga ishonch hosil qiling.'),
  ('eabf6802-121e-4850-8036-ab2dbabaf84e', 'His-tuyg‘ularingizni bo‘lishishdan tortinmang. 📝', 'Charchadingizmi yoki xursandmisiz? Farqi yo‘q, bugungi his-tuyg‘ularingizni Kayfiyat kundaligiga yozib, yengil torting.'),
  ('2b4adff1-6ebf-471c-9dc4-e4e39cc16323', 'Diqqati kuchaymoqda! 👀', 'U endi qora-oq kontrast ranglarni yaxshiroq ajrata oladi.  Qorni bilan yotish mashqi paytida rivojlantiruvchi kartochkalardan foydalanishni unutmang.'),
  ('5e1b47e3-2994-433f-a7c8-b1e6a121de30', 'Qaysi ko‘krakdan emizganingizni unutdingizmi? 🤱', 'Taymer yordamida o‘ng yoki chap ko‘krakdan emizganingizni belgilang, Oziqlantirishni nazorat qilish vositasi hammasini eslab qolsin!'),
  ('8152dc55-7f72-41b2-bb12-02cf7745f75a', 'Otalarni ham jarayonga jalb qilamiz! 👨‍🍼', 'Hamkor rejimi orqali otalar ham chaqaloqning rivojlanishidan xabardor bo‘lishlari mumkin.'),
  ('77ad5a07-cc0a-4fb4-b323-d177412300b1', 'Haftalik statistikangiz tayyor! 📊', 'So‘nggi kunlarda uyqu va ovqatlanish me’yorlariga qanday rioya qilganingizni tahlil qilish uchun ilovaga kiring.'),
  ('8fac7e6d-3d63-4646-99a7-c927a088e849', 'Toza havo ishtahani ochadi! 🌳', 'Chaqalog‘ingizni har kuni toza havoga olib chiqishga harakat qiling. Bu siz uchun ham, chaqalog‘ingiz uchun ham juda foydali.'),
  ('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124', 'Sutingiz sifatini yaxshilang. 🍲', 'Sog‘lom va mazali ovqatlanish uchun ilovadagi Sog‘lom retseptlar bo‘limini ko‘rib chiqing.'),
  ('15d59560-fd44-4273-9de7-62fd70c1a0dd', '1 oylik ko‘rsatkichlar! 📏', 'Bo‘y va vazn haqidagi yangi ma’lumotlarni Rivojlanish kuzatuvchisiga kiriting, sog‘lom o‘sish grafigini ko‘rib, faxrlaning.'),
  ('22b47ac3-665d-4f67-b497-67efe6238be4', 'Tabriklaymiz, endi 1 oylik bo‘ldik! 🥳', 'Ushbu muhim kunni nishonlash uchun Chaqaloq fotosessiyasi bo‘limida qiziqarli suratlar yarating.'),
  ('ed8acfc1-dd31-48da-a8f2-04bd91f60de7', 'O‘zingizga minnatdorlik bildiring! 💖', 'Birinchi va eng qiyin oyni ortda qoldirdingiz. Kayfiyat kundaligiga kirib, bu oydagi qahramonligingizni qayd eting.'),
  ('2037f6e8-905d-4847-8172-fdba3ba09cf5', 'Kechki tartib buzilyaptimi? 🌙', 'Xavotir olmang. Oq shovqinlardan yurak urishi tovushini tanlang — shunda chaqalog‘ingiz o‘zini ona qornidagidek xavfsiz his qiladi.'),
  ('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8', 'Ba’zan bizga shunchaki tanaffus kerak bo‘ladi. ☕', 'Chaqalog‘ingiz uxlayotganda Uyqu taymerini yoqing va o‘zingiz uchun biroz tinch vaqt ajrating.'),
  ('b61a8e62-d1c0-449f-9d5b-6bb72079c512', 'Uyg‘oq qolish vaqti uzaymoqda. ⏱️', 'U bilan o‘ynash va rivojlanishini qo‘llab-quvvatlash uchun Bloglar bo‘limidagi o‘yin tavsiyalarini o‘qing.'),
  ('111e6f27-8aef-4cfb-a5ab-60fea52474e0', 'Keyingi oyga tayyorgarlik. 🛒', 'Yangi oyiga mos tagliklar va parvarish vositalarini izlayotgan bo‘lsangiz, Tavsiya etilgan mahsulotlar albatta asqotadi.'),
  ('713d2aac-0316-483d-9c46-781631bb7e21', 'Siz ajoyib onasiz! ✨', 'Birga ekaningizga 30 kun bo‘ldi. Chaqaloq albomiga ilk kun bilan bugungi kun orasidagi farqni ko‘rsatadigan kollaj qo‘shing.'),
  ('ef07a5ff-817b-4b0a-ad2a-706e799bad22', 'Yangi oy, yangi sahifa. 📊', 'Oylik ovqatlanish, uyqu va taglik statistikasini ko‘rib, chaqalog‘ingiz tartibini naqadar yaxshi shakllantirganingizga guvoh bo‘ling!'),
  ('282baeb2-eb26-44cb-9eff-2eb2d88677a2', 'Kun charchog‘ini chiqaring. 🛁', 'O‘zingizga vaqt ajrating va bugungi his-tuyg‘ularingizni Kayfiyat kundaligiga yozib, yengil torting.'),
  ('5366cee2-8491-4a45-8d5c-88d78aa6eee0', 'Mana, 2-oyga ham qadam qo‘ydik! 🎊', 'Chaqalog‘ingizning rivojlanishini qo‘llab-quvvatlash uchun kun davomida u bilan gaplashing.'),
  ('c5b12eaa-4012-417b-bf89-d5bd9d26aee9', 'Ovqatlanish tartibi o‘zgarishi mumkin. 🍼', 'Chaqalog‘ingizning ishtahasini kuzatish uchun Anacan taymerini ishga tushiring va kunlik me’yorni tekshiring.'),
  ('24927359-7877-4f99-9dea-0460583a0880', 'Kunlik tagliklar sonini kuzatamiz. 🧷', 'Chaqaloq yetarlicha oziqlanayotganiga ishonch hosil qilish uchun Anacan ilovasida har bir taglik almashtirilishini qayd etishda davom eting.'),
  ('77d01c80-0ffb-4089-a192-db04bf909aa1', 'Uxlab qolishga qiynalyaptimi? 🌙', 'Oq shovqinlardan okean to‘lqinlari ovozini tanlang, chaqalog‘ingiz qattiq uyquga ketganda siz ham dam oling.'),
  ('afe3841b-76da-4cfe-9cf7-b2077153f607', 'Ilk «a-gu» tovushlari eshitilmoqda! 🗣️', 'Nutq rivojlanishini qo‘llab-quvvatlash uchun siz ham chaqalog‘ingiz chiqarayotgan tovushlarni takrorlang va u bilan gaplashing.'),
  ('5bfad78e-cb6a-405d-8517-a356018909ca', 'Bo‘yi va vazni qanday o‘smoqda? 📏', 'Rivojlanishni kuzatish bo‘limida yangi ko‘rsatkichlarni qayd eting va shaxsiy rivojlanish grafigini tahlil qiling.'),
  ('d87d1938-6445-47b1-b0eb-19c7a9941726', 'Toza havo izlab! 🌳', 'Chaqalog‘ingiz bilan bemalol sayr qilish uchun bolalar aravachasi bilan kirish mumkin bo‘lgan yaqin joyni tanlang.'),
  ('fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1', 'Anacan AI har doim yoningizda! 🤖', 'Uyqu rejimi haqida savollaringiz bormi? Sun’iy intellektimizga yozing — u darhol javob beradi.'),
  ('0ac0ad4d-776b-416d-a345-c0bddd639ff1', 'Diqqatni jamlash qobiliyati rivojlanmoqda! 👀', 'Chaqalog‘ingiz xonadagi buyumlarni nigohi bilan qanday kuzatayotganiga e’tibor bering. Rivojlanish haqida ko‘proq bilish uchun Bloglar bo‘limiga kiring.'),
  ('1a8980b4-ba5e-4179-adce-580423431a55', 'Uyqu me’yorlarini bilish muhim. ⏱️', 'Chaqalog‘ingiz uxlayotganda uyqu taymerini yoqing va u kunlik uyqu me’yoriga rioya qilayotganini tekshiring.'),
  ('c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f', 'Onalarga energiya kerak! 🍳', 'Sog‘lom retseptlar orasidan oson tayyorlanadigan mazali smuzi bilan kuchingizni tiklang.'),
  ('041b2f2c-3594-4ff1-96a1-f589206d267b', 'Emizish va tanaffuslar. 🤱', 'Har bir emizish davomiyligini Oziqlanishni kuzatish vositasi yordamida o‘lchab, kun tartibingizni yanada takomillashtiring.'),
  ('bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec', 'Kayfiyatingiz qanday, aziz ona? 💖', 'Ba’zan barcha tashvishlar bir paytning o‘zida yig‘ilib qolishi mumkin. Kayfiyat kundaligingizni oching va ichingizdagilarni bemalol yozing.'),
  ('cb8cc6b6-0d64-4498-81ae-bc15f03ad73b', 'Chaqalog‘ingiz terisi uchun alohida parvarish. 🧴', 'Uning baxmaldek mayin terisi uchun eng yaxshi vositalarni onalar tanlagan Tavsiya etilgan mahsulotlar blogimizdan toping.'),
  ('47a30b46-d385-4b3c-979c-5465d481ef29', 'Qorin dam bo‘lishiga qarshi mashq! 🚴', 'Velosiped mashqini bajarayotganda fonda Oq shovqinni yoqing — shunda chaqalog‘ingiz ham zavqlanadi, ham tinchlanadi.'),
  ('a7868664-8e30-4849-9648-70deec39cf3a', '6-haftalik rivojlanish sakrashi yaqinlashmoqda! 📈', 'Chaqalog‘ingiz odatdagidan ko‘proq yig‘lashi mumkin. Ushbu rivojlanish bosqichi va uning sabablari haqida bilish uchun Bloglar bo‘limiga qarang.'),
  ('ba4d5548-5eb3-44e1-bb68-bbab9deb11ee', 'Otalar bilan birga parvarish qilish vaqti. 👨‍🍼', 'Kechki emizishdan keyin chaqaloqning kekirishiga yordam berishni dadasiga topshiring, o‘zingiz esa biroz mizg‘ib oling.'),
  ('22e06076-dd91-4e1b-834c-b78c42879a13', 'Uydan tashqarida ham qulaylik. ☕', 'Do‘stlaringiz bilan uchrashishni rejalashtiryapsizmi? Onalar uchun qulay joylar xaritamizni ko‘rmay turib, uydan chiqmang.'),
  ('367f3154-4760-43d6-b507-b914372b7538', 'Jilmayishga tayyor bo‘ling! 😊', 'Chaqalog‘ingiz har qanday paytda sizga javoban jilmayishni boshlashi mumkin. Telefoningizni tayyor tuting.'),
  ('56603835-e00b-48c0-82ab-bbdf1844d6ac', 'Kun tartibi uyqu sifatini yaxshilaydi. 🛁', 'Chaqalog‘ingizni cho‘miltiring, emizing va uyqu taymerini ishga tushirib, ilovada kundalik uyqu tahlilini yuriting.'),
  ('173da4aa-4d6e-4106-ab0c-34773a383b02', 'Qorin bilan yotish vaqti uzaymoqda! 🐢', 'U endi boshini tikroq tutmoqda. Bo‘yin mushaklarini mustahkamlaydigan bu mashqlarni kundalik tartibingizga kiriting.'),
  ('3c5122e2-a92c-4444-baa3-d7b7fdd4786f', 'Taglik almashtirish statistikangizni ko‘rib chiqamizmi? 📊', 'Anacan ilovasiga kiring va so‘nggi kunlardagi taglik ma’lumotlarini taqqoslang. Hammasi joyidami?'),
  ('f653426f-c687-4b5c-806e-74f597e75cf2', 'Hammasi joyida ekaniga ishonch hosil qilish uchun. 🤖', 'Sizni o‘ylantirayotgan har qanday tafsilot haqida hatto tunda ham Anacan AI’dan so‘rashingiz mumkin.'),
  ('2a04ee0c-770e-425b-8987-e6ab25472f0b', 'Sutni ko‘paytirishning tabiiy usullari. 🥛', 'Sutni ko‘paytirish uchun Sog‘lom retseptlar bo‘limidagi to‘yimli sho‘rva va ichimlik retseptlarini sinab ko‘ring.'),
  ('6a605601-9da6-47e9-8d07-a1f552eb5fc0', 'Kundalik ovqatlanish va uyqu muvozanati. ⚖', '️ Bugungi ko‘rsatkichlaringizni Ovqatlanishni nazorat qilish va uyqu grafiklari orqali tahlil qilib, keyingi kunni rejalashtiring.'),
  ('756d2914-ecb6-4838-adb6-d312a4bc59a2', 'Qo‘llarini kashf etmoqda! 👐', 'U endi qo‘llarini og‘ziga olib bora oladi.'),
  ('2dcd9888-3b4b-4cb6-a25a-51c4642e3c54', 'Bugun chillamiz chiqadi! 🧿', 'Ushbu alohida va an’anaviy kunni unutilmas qilish uchun Chaqaloq fotosessiyasi bo‘limidan qiziqarli mavzularni tanlab, suratlar yarating.'),
  ('92e4d1aa-c4f4-477c-ab81-176ef4f03a16', 'Osoyishta uyquga o‘tish. 🌙', 'Ushbu o‘zgacha kun yakunida xonani qorong‘ilating, Oq shovqinlarni yoqing va chaqalog‘ingiz chuqur uyquga ketgach, siz ham miriqib uxlang.'),
  ('ba92608f-780e-4381-a0e7-3f6af86021be', 'O‘zingizni qanday his qilyapsiz? ✨', '40 kunlik muhim va alohida davrni yakunladingiz! Siz haqiqiy qahramonsiz!'),
  ('6dd4f975-8504-4871-83c4-a6f7bc24a950', 'Buguningiz qanday o''tdi? 📝', 'O''zingizga bir finjon qahva quyib, bugungi ichki kechinmalaringizni Kayfiyat kundaligiga yozing va yengil torting.'),
  ('c6c2469c-d36e-4ffe-a532-bee6050f4bac', 'Chilladan keyingi yangi davr! 🌸', 'Chaqalog''ingiz atrofga tobora ko''proq qiziqish bildirmoqda. Atrofida aqlni rivojlantiruvchi kartochkalar bo''lishi chaqalog''ingiz uchun foydali.'),
  ('d647162e-98ae-41c0-81b4-cc5ca3e15dff', 'Ovqatlantirish tartibi qanday ketyapti? 🍼', 'Ilovadagi Ovqatlantirishni kuzatish vositasi va taymer yordamida kunlik me''yorga qanchalik rioya qilayotganingizni tekshiring.'),
  ('06dbea83-4e3d-4be5-8968-0961033df8d5', 'Ranglarni yaxshiroq ajrata boshladi! 🔴', 'Xonadagi yorqin buyumlarni qanday kuzatayotganiga e''tibor bering.'),
  ('295afbf2-1104-44c2-abf4-fb0e41a0ff0e', 'Toza havo ikkalangizga ham foydali. 🌳', 'Sayrga chiqish uchun Onalar uchun qulay joylar xaritasidan bolalar aravachasi bilan bemalol kirish mumkin bo''lgan joyni tanlang.'),
  ('9f7dfdf1-83be-4fad-a93a-817e105844ce', 'Uyquga ketishini osonlashtiring. 🌙', 'Kechki cho''milishdan so''ng Oq shovqinlar orasidan fen yoki yomg''ir tovushini tanlab, uni chuqur uyquga tayyorlang.'),
  ('431cbe5a-0f52-442d-a6e8-ab53cd482a5f', 'Kundalik statistikangiz tayyor! 📊', 'Chaqalog‘ingiz bugun qancha uxlagani va oziqlanganini ko‘rish uchun ilovadagi grafiklaringizni tahlil qiling.'),
  ('c4adf9ce-d711-4011-af60-94f404f59ae5', 'Bo‘y va vazn o‘sishini kuzatamiz! 📏', 'Rivojlanishni kuzatish bo‘limida so‘nggi ko‘rsatkichlarni yangilang, sog‘lom rivojlanish grafigini ko‘rib faxrlaning.'),
  ('ffb18a7a-0d53-482c-b130-00223f89efd3', 'Onalar uchun energiya manbai! 🥗', 'Kuchingizni tiklash uchun ilovadagi Ayollar uchun sog‘lom retseptlardan vitaminlarga boy va mazali taomni tanlang.'),
  ('40712cc0-bb4b-4d42-9a36-7942cb47a970', 'Tovushlarga munosabati kuchaymoqda! 🎶', 'Ovozingizni eshitganda qanday tinchlanishini ko‘ryapsizmi? Bu yoqimli lahzalarni Chaqaloq albomida abadiylashtiring.'),
  ('aa025645-c5cd-4f2b-840e-6fb50bb6398b', 'Xarid qilish kerakmi? 🛍', '️Chaqalog‘ingizning yangi oyiga mos parvarish vositalari yoki o‘yinchoqlar uchun Tavsiya etilgan mahsulotlar ro‘yxatimizni ko‘rib chiqing.'),
  ('c6ae0bdf-11e6-43d9-a0ab-d021b7461194', 'Tagliklarni sanashda davom eting! 🧷', 'Chaqalog‘ingiz yetarlicha oziqlanayotganiga ishonch hosil qilish uchun har kuni nechta taglik almashtirganingizni Anacan’da qayd eting.'),
  ('99125d76-b832-4f75-8c29-6320b71e5e67', '6-haftalik rivojlanish sakrashi! 📈', 'Bugun chaqalog‘ingiz biroz talabchan bo‘lishi mumkin. Xavotir olmang, yordam olish uchun Anacan AI bilan maslahatlashing.'),
  ('9f56ae7d-2431-4cb2-8d79-fa19be16c242', 'Tungi uyg‘onishlarni tartibga solamiz. 😴', 'Chaqaloq har safar uyg‘onganida chiroqlarni yoqmang. Anacan taymeri yordamida uni oziqlantiring va Oq shovqinlar bilan yana uxlatib qo‘ying.'),
  ('bef1515a-3c39-4799-b9d9-717742d94d5f', 'U uxlayotganda siz ham dam oling. ⏱️', 'Uyqu taymerini yoqing, chaqalog‘ingiz uxlayotgan paytda siz ham ko‘zingizni yuming yoki kitob o‘qing.'),
  ('3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c', 'Ilk «agu» tovushlari davom etmoqda! 🗣️', 'Uning siz bilan gaplashishga urinishlarini qayd eting. Chaqaloq fotosessiyasi bo‘limidan shu lahzaga mos ramkani tanlang.'),
  ('48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179', 'Ko‘krak suti ko‘payishiga yordam beradigan mahsulotlar. 🍲', 'Ayollar uchun foydali retseptlar bo‘limidagi ko‘krak sutini ko‘paytirishga yordam beradigan sho‘rva va ichimliklar bilan o‘zingizni siylang.'),
  ('bcfe1987-8bea-4b53-a1dc-7ef7e234e755', 'His-tuyg‘ularingizni boshqaring. 💖', 'Onalik charchatishi mumkin. Kayfiyat kundaligiga kirib, bugun sizni nima bezovta qilganini yozing va yengil torting.'),
  ('4c289cf6-60de-4ba6-9f14-eae4086d8d21', 'Tanaffuslarni tartibga solamiz. 🍼', 'Ovqatlanish va tanaffus vaqtlarini Ovqatlanishni nazorat qilish vositasi orqali kuzatib, chaqalog‘ingiz uchun mukammal kun tartibini yarating.'),
  ('7f93cf2f-abf0-4b16-9f93-396050a7ddb9', 'Yana savollaringiz bormi? 🤖', 'Chaqalog‘im bugun kam uxladi, bu normal holatmi? – Sizni o‘ylantirayotgan savollarni Hamjamiyatdagi boshqa onalarga bering.'),
  ('c505d849-65c8-4ead-80b3-2648f5feaa49', 'Qorin bilan yotish mashqlari! 🐢', 'U endi boshini uzoqroq vaqt tik ushlab tura oladi. Bo‘yin mushaklarini rivojlantirish uchun bu mashqlarni har kuni takrorlang.'),
  ('65d67a55-0ffc-4c5f-8c78-443c16c7f697', 'Otalarni ham jarayonga jalb qilaylik. 👨‍🍼', 'Kechki ovqatlantirishdan keyin chaqaloqning kekirishiga yordam berish va uni uxlatish navbatini otasiga topshirib, o‘zingizga vaqt ajrating.'),
  ('c7ab2e50-8e71-4df1-97cc-6432f40c4349', 'Tabassumlar ko‘paymoqda! 😍', 'Uning sizga qarab gugurlagan o‘sha sehrli lahzasini o‘tkazib yubormang! Suratga oling va Chaqaloq albomining eng chiroyli sahifasiga joylang.'),
  ('dba00752-8e14-4710-8793-6a828172c915', 'Dugonalar bilan qahva tanaffusi? ☕', 'Chaqalog‘ingiz bilan birga borishingiz mumkin bo‘lgan eng yaqin va qulay kafelarni Onalar uchun qulay joylardan toping.'),
  ('503a0808-7061-4b7d-ae17-f65b9abb87de', 'Rivojlanishini bosqichma-bosqich kuzating. 📚', 'Yangi tug‘ilgan chaqaloqlar bu oyda qanday ko‘nikmalarni egallashini bilish uchun Bloglar bo‘limidagi eng so‘nggi maqolamizni o‘qing.'),
  ('aeea52a4-dd88-4cf1-a812-0c13b4f98004', 'Kunlik uyqu me’yori. 🛌', 'Chaqalog‘ingiz uxlayotganda uyqu taymerini ishga tushiring va u kunlik 14-17 soatlik me’yorni bajarayotganini tahlil qiling.'),
  ('c86bd995-9231-4eae-b8e0-8f84d6a46b62', 'Siz juda kuchlisiz! ✨', 'Ba’zan qiyin bo‘lsa-da, siz ajoyib onasiz!'),
  ('8e6d5e26-758c-4169-81b6-bd9cbcc10cc5', 'Go‘zal kunning shirin yakuni. 🌙', 'Xona yorug‘ligini pasaytiring, Oq shovqinlar orasidan ona qornidagi tovushni yoqing va chaqalog‘ingizning orom olib uxlashini kuzating.'),
  ('9d97fdbc-edef-4830-93ad-c388f586d909', 'Birga ekaningizga roppa-rosa 50 kun bo‘ldi! 🎈', 'Ushbu ajoyib sanani Chaqaloq fotosessiyasi vositasi yordamida maxsus surat yaratib nishonlang!'),
  ('cb1a5cad-e167-45a8-b0b1-4e8ebe455866', 'So‘nggi 50 kun tahlili. 📈', 'Rivojlanishni kuzatish va Oziqlanishni nazorat qilish bo‘limlarini ko‘rib, chaqalog‘ingiz shu 50 kun ichida qanchalik yaxshi ulg‘ayganini bilib oling.'),
  ('10f8db02-014b-4a08-8d7a-e5cbbb260125', 'Chuqur uyquga o‘tish. 😴', 'Oq shovqinlardan soch quritgich tovushini tanlang, chaqalog‘ingiz tinch uxlayotganda esa Kayfiyat kundaligiga his-tuyg‘ularingizni yozib, yengil torting.'),
  ('2cd12a68-4486-435f-ad24-55a11a2f62a2', 'Kundalik ovqatlanish tahlili. 🍼', 'Ilovadagi taymer yordamida emizish davomiyligini o‘lchang va Ovqatlanishni nazorat qilish bo‘limida me’yorga mosligini tekshiring.'),
  ('b67a89c9-d8cf-40c2-97a2-43b27081ed44', 'Ko‘rish doirasi kengaymoqda! 👀', 'U endi buyumlarni yaxshiroq kuzata oladi.'),
  ('917836b6-b023-4945-8e64-bc144ba97f42', 'Yangi tovushlarni kashf etmoqda! 🗣️', 'Uning yoqimli «agu»larini qayd eting. Nutq rivoji haqida ko‘proq bilish uchun Bloglarni o‘qing.'),
  ('d31b874f-e957-475e-a461-b294c96db59f', 'Tunda uyg‘onishlar davom etyaptimi? ⏱️', 'Har bir uyg‘onishni uyqu taymerida qayd etib, umumiy uyqu tartibi va kunlik me’yorni tahlil qiling.'),
  ('d491dc2d-f6b9-49dd-8461-5cbffee476e5', 'O‘zingizni unutmang! 🥗', 'Onaning quvvati juda muhim. Ayollar uchun foydali retseptlardan vitaminlarga boy taomni tanlab, kuchingizni tiklang.'),
  ('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c', 'Sizni nima bezovta qilmoqda? 🤖', 'Hatto tunda ham istalgan savolingizni Anacan AI yordamchimizga berib, mutaxassis ko‘magini oling.'),
  ('f710f746-b942-4fd7-a8ca-dd9b5a248195', 'Taglik kuzatuvchisini tekshirib ko‘raylik. 🧷', 'Kunlik tagliklar sonini Anacan-da qayd etib, chaqalog‘ingiz yetarli darajada oziqlanayotganiga ishonch hosil qiling.'),
  ('fa5fc8d8-4263-4a99-9f46-297b1d6ea219', 'Boshini yanada tik tutyapti! 🐢', 'Qorin bilan yotish mashqlarini qiziqarli o‘yinga aylantiring.'),
  ('42ca0f3b-8083-4338-bf16-9998a33b15c6', 'Toza havoga chiqish vaqti! 🌳', 'Onalar uchun qulay joylar xaritamizni oching va chaqalog‘ingiz bilan borishingiz mumkin bo‘lgan eng qulay joyni toping.'),
  ('7fc52d97-b36d-4c5e-a169-0eadba238b0e', 'Vazn va bo‘y nazorati. 📏', 'Chaqalog‘ingiz qanday o‘smoqda? Yangi ma’lumotlarni Vazn kuzatuvchisiga kiritib, uning shaxsiy o‘sish grafigini kuzating.'),
  ('df56b34d-b5f8-476f-a65e-11a244242a2f', 'Uxlashdan oldingi tartib. 🛁', 'Chaqalog‘ingizni cho‘miltiring, emizing va uyqu taymerini ishga tushiring. Hammasi rejali va xotirjam o‘tsin!'),
  ('2776b020-9972-4e23-acb7-6a529664582d', 'Ovozingizni izlayapti! 👂', 'U bilan ko‘proq gaplashing, ko‘z bilan aloqa o‘rnating. Uning rivojlanishi uchun turli mashg‘ulotlar haqida Bloglar bo‘limidan bilib oling.'),
  ('72abc90e-b301-468a-9629-3f3bb7949709', 'Chaqaloq parvarishi bo‘yicha savollaringiz bormi? 🤖', 'Anacan hamjamiyati sizni hukm qilmasdan tinglaydi va eng mos tavsiyalarni beradi.'),
  ('816ef2cf-32b6-4eba-b12b-4e8f7936a78f', 'Sut miqdorini oshiring. 🥛', 'Ko‘p suv ichishni unutmang! Shuningdek, Ayollar uchun foydali retseptlar bo‘limidan sutni ko‘paytiruvchi ichimlik tayyorlang.'),
  ('1501b0ff-9742-40e2-9aae-ff2e8f8e5188', 'Oilaviy sayr rejasi! ☕', 'Bo‘sh vaqtingizni mazmunli o‘tkazish uchun Onalar uchun qulay joylar bo‘limidan shinam kafe yoki restoran tanlang.'),
  ('427917df-21f2-46c9-a030-52d511e37ce5', 'Kundalik hisobot. 📊', 'Bugun chaqalog‘ingiz qancha uxladi, necha marta ovqatlandi? Ilovadagi grafiklar orqali bugungi umumiy statistikani ko‘rib chiqing.'),
  ('c555165e-a5c9-4e8c-9a72-cf4d0a16a367', 'Otalarni ham unutmaymiz! 👨‍🍼', 'Chaqalog‘ingizning dadasi bilan o‘ynagan yoqimli va quvnoq lahzalarini qadrlang.'),
  ('0c1e843a-b2dc-4995-89cf-7af4230d574e', 'Qo‘llarini kashf etmoqda! 👐', 'U endi barmoqlariga qaraydi va ularni og‘ziga olib boradi.'),
  ('3cf29d40-9703-4e58-8a17-b7e68f86c3fa', 'Parvarish vositasi yoki o‘yinchoq izlayapsizmi? 🧸', 'Uning rivojlanishini qo‘llab-quvvatlaydigan xavfsiz mahsulotlarni Tavsiya etilgan mahsulotlar ro‘yxatimizdan osongina toping.'),
  ('e6e49938-5987-45e7-8021-a8d016100be4', 'O‘zingizni qanday his qilyapsiz? 💖', 'Kun bo‘yi charchadingizmi yoki o‘zingizni tetik his qilyapsizmi? Kayfiyat kundaligini oching va bugungi kuningiz qanday o‘tganini qayd eting.'),
  ('814305c3-77b7-491e-ae0f-134875923d1a', 'Qaysi ko‘krakdan emizdingiz? 🤱', 'Anacan taymeri sizning o‘rningizga o‘ng yoki chap ko‘krakdan emizganingizni eslab qoladi. Emizishni hozir boshlang!'),
  ('910b6936-83b0-441d-abe5-33c85153dffe', 'Tonggi tabassum! 😊', 'Uning sizga ataylab qilgan tabassumlari kuningizni yanada go‘zal qiladi. Chaqaloq fotosessiyasi yordamida bu quvonchli lahzalarni xotiraga muhrlang.'),
  ('fcecf920-146e-4152-abc5-066ce8392fd8', 'Tinchlantiruvchi ovoz terapiyasi. 🎶', 'Agar chaqaloqning qorni dam bo‘lsa yoki u charchagan bo‘lsa, Oq shovqinlardagi yurak urishi ovozi uni bir zumda ona qornidagidek tinchlantiradi.'),
  ('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae', 'Kun charchog‘ini chiqaring. 🛁', 'O‘zingizga vaqt ajrating va bugungi ichki kechinmalaringizni Kayfiyat kundaligiga yozib, yengil torting.'),
  ('59aa01c0-7e8d-4375-9fcd-733a242d640c', 'Ovqatlanish tartibiga rioya qilamiz. 🍼', 'Chaqalog‘ingizning ishtahasi oshishi mumkin. Anacan taymerini ishga tushiring va ovqatlanish me’yorini Ovqatlanishni nazorat qilish vositasi yordamida tekshiring.'),
  ('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a', 'Uchinchi oyning ilk kuni! 🎉', 'Chaqalog‘ingiz endi atrofni yanada ongli ravishda kuzatmoqda.'),
  ('8d26cab1-ebfd-469f-9ae0-aa66e0f36761', 'Uxlab qolishi qiyinlashyaptimi? 🌙', 'Xonani qorong‘ilating va Oq shovqinlardan okean to‘lqinlari ovozini tanlab, chaqalog‘ingizni chuqur uyquga tayyorlang.'),
  ('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4', 'Toza havoda sayr qilish vaqti. 🌳', 'Toza havoda sayr qilish chaqalog‘ingizning rivojlanishi va xotirjamligi uchun juda muhim.'),
  ('b6825824-6eff-4740-b6c1-dc607b41b996', 'Qo‘llarini o‘yinchoqlarga uzatyapti! 🧸', 'Bu kichik kashfiyotlarni kuzatish naqadar zavqli! U bilan o‘ynayotganda olgan videolaringizni Chaqaloq albomiga yuklang.'),
  ('052bbdef-be6b-4b3f-bf88-905af0d4abc5', 'Ba''zan dam olish kerak. 🛋', '️ U uxlayotganda uyqu taymerini yoqing va hech qanday ish qilmay, shunchaki o''zingizga vaqt ajrating.'),
  ('1053981f-f622-407a-ade7-529fc27bb2ff', 'O''sish jarayonini kuzatamiz! ⚖️', 'Ikkinchi oy yakunlanmoqda. Ilovadagi Vazn kuzatuvi bo''limiga kirib, so''nggi ma''lumotlarni yangilaganingizga ishonch hosil qiling.'),
  ('8f5fde4a-3542-4bb1-be02-6df262d75b50', 'Hammasi joyidami? 📝', 'Kayfiyatingiz qanday? Charchaganmisiz yoki kuch-g''ayratga to''lamisiz? Anacan Kayfiyat kundaligi — sizning eng yaxshi raqamli sirdoshingiz.'),
  ('292a637a-a0ca-4e58-8523-7b2c8b754743', 'Ajoyib oyning yakuni. ✨', 'Xona chirog''ini xiralashtiring, Oq shovqinlarni yoqing va chaqalog''ingiz uxlayotganda u bilan faxrlaning. Siz mukammal onasiz!'),
  ('39c9a98b-8f4e-4896-9385-5588121bd72d', 'Tabriklaymiz, roppa-rosa 2 oylik bo''ldik! 🎈', 'Bu ajoyib lahzani nishonlash uchun Chaqaloq fotosessiyasida esdalik suratini yarating!'),
  ('3c5f5d9f-939f-4c7e-9bc8-1feef640d854', 'Ikki oylik rivojlanish hisoboti. 📈', 'Vazn kuzatuvi, taglik va ovqatlanish statistikasiga qarab, chaqalog''ingiz shu 60 kun ichida qanchalik sog''lom o''sganini ko''ring.'),
  ('1ed5f326-68dd-494e-a31c-2d3466644cd0', 'Onalar uchun energiya manbai! 🥗', 'Tiklanish va sut miqdorini ko‘paytirishga yordam berish uchun Sog‘lom retseptlar bo‘limidan vitaminlarga boy retseptni tanlang.'),
  ('59041ede-10ec-4754-8f5f-31f415db3701', '«A-gu» tovushlari ko‘paymoqda! 🗣️', 'Chaqalog‘ingizning siz bilan muloqot qilishga urinishlari ko‘paymoqda. Nutq rivojlanishini qo‘llab-quvvatlash uchun Bloglar bo‘limidagi maqolalarni o‘qing.'),
  ('d7b0c908-0d97-40c6-a82a-c5283f30a1d8', 'Uyqu me’yorlarini kuzating. ⏱️', 'Chaqalog‘ingiz uxlayotganda uyqu taymerini yoqing va uning kunlik uyqu me’yoriga rioya qilayotganini tahlil qiling.'),
  ('5309698d-6050-4993-9a68-ab592375ed60', 'So‘lak bezlari ishlay boshlaydi! 💧', 'Endi chaqalog‘ingizda ko‘proq so‘lak ajralishi mumkin.'),
  ('83d11db6-0443-4d69-8d55-9ea20f0cf905', 'O‘sish bosqichini kuzatamiz! 📏', 'Keyingi haftadagi vazn va bo‘y ma’lumotlarini Vazn kuzatuvchisiga kiritib, shaxsiy rivojlanish grafigini yangilang.'),
  ('ca5bc974-1377-4065-9dfa-50549135eb55', 'Sizni nimadir tashvishga solyaptimi? 🤖', '«Nega bugun uning uyqusi qisqa bo‘ldi?» kabi savollaringizni hatto tungi soatlarda ham Anacan AI yordamchimizga bering.'),
  ('149e95b1-a682-4369-8b74-5827cc5d31dc', 'His-tuyg‘ularingizni baham ko‘rishdan tortinmang. 📝', 'Charchadingizmi yoki kuchga to‘lamisiz? Farqi yo‘q, bugungi his-tuyg‘ularingizni Kayfiyat kundaligiga yozib, yengil torting.'),
  ('79b7fb29-fa37-4176-9ae5-409d73ee982e', 'Uydan tashqarida ham qulaylik. ☕', 'Do‘stlaringiz bilan qahva ichishni xohlaysizmi? Onalar uchun qulay joylar xaritamizni ko‘rmasdan uydan chiqmang.'),
  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'Ijtimoiy tabassumlar! 😊', 'Uning yoqimli tabassumi barcha charchog‘ingizni unutdiradi.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'Haftalik statistikangiz tayyor! 📊', 'So‘nggi kunlarda uyqu va ovqatlanish me’yorlariga qanday rioya qilganingizni tahlil qilish uchun ilovaga kiring.'),
  ('aba537d3-5a0f-4b17-b02b-4754b93f711f', 'Qaysi ko‘krak bilan emizganingizni unutdingizmi? 🤱', 'Taymer yordamida o‘ng yoki chap ko‘krakni belgilang, Anacan siz uchun hammasini eslab qolsin!'),
  ('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8', 'Kunduzgi uyqu tartibi o‘zgaradi. ⏱️', 'Uyg‘oq qolish vaqtini va tanaffuslarni Ovqatlanish nazorati hamda uyqu taymerlari yordamida o‘lchab, yangi tartib yarating.'),
  ('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc', 'Dada bilan birga parvarish qilish vaqti. 👨‍🍼', 'Kechki ovqatlantirishdan keyin chaqaloqning kekirishiga yordam berish va uni uxlatishni dadasiga topshiring, o‘zingiz esa dam oling.'),
  ('a6843443-e0f6-4ec7-a4ec-03cb5d81d392', 'Qorin bilan yotish mashqlari osonlashmoqda. 🐢', 'U endi boshini tikroq va uzoqroq vaqt ushlab tura oladi. Bu mashg‘ulotni kundalik tartibingizga kiriting.'),
  ('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d', 'Kundalik taglik holatini tekshiramiz. 🧷', 'Chaqaloq yetarlicha oziqlanayotganiga ishonch hosil qilish uchun Anacan-da har bir taglik almashtirishni qayd etishda davom eting.'),
  ('7764e41d-176a-41d8-8f87-2a21677a36ee', 'Kun tartibini shakllantiramiz. 🛁', 'Har oqshom bir xil vaqtda cho‘miltiring, emizing va uyqu taymerini ishga tushirib, sog‘lom uyqu tartibini shakllantiring.'),
  ('9754280d-c633-46e8-94c9-6f16ff032551', 'O‘zingizni unutmang, aziz ona! 🍲', 'Anacan ilovasidagi Sog‘lom retseptlar bo‘limini ko‘rib chiqing va bugun o‘zingiz uchun mazali taom tayyorlang.'),
  ('c1c4c9b0-cdd8-4321-a494-3bb43739df94', 'Sizni va ovozingizni taniydi! 😍', 'Xonaga kirganingizda u qanchalik quvonishiga e’tibor bering. 😊'),
  ('32ff20f3-f1f8-47fd-b3be-c14bea1452a2', 'Bezovtalikka qarshi ovoz terapiyasi. 🎶', 'Agar bu oqshom chaqalog‘ingiz bezovta bo‘lsa, diqqatini chalg‘itish uchun Oq shovqinlardan yurak urishi ovozini yoqing.'),
  ('a061022a-6a47-4aae-8590-2f0f328fbf09', 'O‘yin vaqti! 🎈', 'U bilan vaqtni qanday mazmunli o‘tkazishni bilish uchun Bloglar bo‘limidagi rivojlantiruvchi o‘yinlar bo‘yicha tavsiyalarni o‘qing.'),
  ('b95ca7be-8491-4bbc-afb0-321f795780ea', 'Xarid qilish kerakmi? 🛍', 'Chaqalog‘ingizning shu oyiga mos xavfsiz o‘yinchoqlar va vositalarni Tavsiya etilgan mahsulotlar ro‘yxatimizdan osongina toping.'),
  ('633e342d-82b1-442c-9da8-5c5326907322', 'Kun tahlili. 📈', 'Ovqatlanish kuzatuvi va uyqu jadvallaringiz tahlili orqali kun tartibingiz qanchalik yaxshi shakllanayotganini ko‘ring.'),
  ('8655d498-c5d9-40f8-bd47-346f815d3e75', 'Go‘zal kunning shirin yakuni. 🌙', 'Xona chirog‘ini xiralashtiring, Oq shovqinlardan ona qornidagi ovozni yoqing va chaqalog‘ingizning orom olib uxlashini kuzating.'),
  ('97e88a0b-26cf-486d-a17f-2c34cfc6b47d', 'Birga ekaningizga roppa-rosa 70 kun bo‘ldi! ✨', 'Siz ajoyib onasiz! Chaqaloq albomiga ilk kun bilan bugungi kun o‘rtasidagi farqni ko‘rsatuvchi kollaj qo‘shing.'),
  ('05925891-b678-4a87-8f54-39f692aa9143', 'Zaxiralar tugayaptimi? 🛒', 'Taglik yoki nam salfetkalar tugayaptimi? Hammasini yodda saqlashingiz shart emas. Hozir xaridlar ro‘yxatiga qo‘shing, turmush o‘rtog‘ingiz kechqurun uyga qaytayotganda olib kelsin.'),
  ('41007feb-f415-4088-b094-428b2275abbf', 'Sehrli ovozlar olami 📖', 'Kechki odatlaringizga yangilik kiriting. Aqlli ertaklar yordamida unga tinchlantiruvchi hikoya yarating va ikkalangiz uchun ham uyquga ketishni osonlashtiring.'),
  ('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03', 'Tonggi konsert 🎶', 'Ilk «a-gu»larini aytyaptimi? U bilan bir tilda gaplashing, chiqarayotgan tovushlariga javob bering. Bugun shunchaki shu yoqimli lahzadan zavqlaning va hech qayerga shoshilmang.'),
  ('62fbb893-6a1c-4847-a99e-981afea8fa87', 'Turlicha yig‘ilar 😭', 'Ochlikdanmi yoki uyqusi kelganidan yig‘layaptimi? Xavotir olmang, Yig‘i tahlili vositamiz yordamida bu tovushlar nimani anglatishini bir necha soniya ichida birgalikda bilib olamiz.'),
  ('83a0ab90-d44d-4758-bd3f-c7126ae6e20f', 'O‘zingizga nisbatan rostgo‘y bo‘ling 📝', 'Bugun juda charchadingizmi? Kayfiyat kundaligiga his-tuyg‘ularingizni samimiy yozing. Har kuni mukammal bo‘lishingiz shart emas, siz ham oddiy insonsiz.'),
  ('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c', 'Nima kiydirsam ekan? ⛅', 'Ob-havo o‘zgaruvchan bo‘lib, chaqaloq sovqotishi yoki terlashi sizni xavotirga solyaptimi? Darhol Ob-havo va kiyim vositasini oching va bugungi ob-havo uchun eng mos kiyimlar to‘plamini bilib oling.'),
  ('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a', 'Biz bir jamoamiz! 💪', 'Ba’zan o‘zingizni yolg‘iz va hech kim tushunmayotgandek his qilasizmi? Anacan hamjamiyatiga qo‘shiling. U yerda siz kabi hislarni boshdan kechirayotgan minglab onalar bor. Bugun ular bilan tajribangizdan birini baham ko‘ring.'),
  ('60059890-bf5b-4e0b-ba41-fedc82fa6a43', 'Dadaning navbati 👨‍🍼', 'Kun davomida to‘plangan charchoqni yelkangizdan soqit qiling. Chaqaloqni dadasiga bering, bu oqshom uni dadasi uxlatib qo‘ysin. Siz esa bir piyola issiq choy quyib, bu manzarani chetdan tomosha qiling.'),
  ('b1778419-cb70-4711-96e0-a612732e8575', 'So‘lakli tabassumlar 🤤', 'Chaqalog‘ingizning og‘zidan tez-tez so‘lak oqib, qo‘llari doim og‘zidami? Tish chiqishini kuzatish bo‘limiga dastlabki qaydlaringizni kirita boshlang. Ha, bu hayajonli tayyorgarliklar erta boshlanadi!'),
  ('0eb4da19-cb98-497a-a36b-a4934f47e071', 'Sokinlik nazorati 🤫', 'Chaqalog‘ingiz hozirgina uxlab qoldi, ammo uydagi shovqin uni uyg‘otishidan xavotirdamisiz? Shovqin o‘lchagichni faollashtiring, xonadagi detsibel darajasini nazorat qilib, uning uyqusini asrang.'),
  ('9cab0c58-8a4f-4869-b607-be3e284373f0', 'Savolingiz bormi? 🤖', 'Kundalik tashvishlar orasida biror savol xayolingizdan ketmayaptimi? Oziqlanish, uyqu yoki qorin dam bo‘lishi... Farqi yo‘q, darhol Anacan AI’dan so‘rang va aniq, ilmiy asoslangan javob oling.'),
  ('e6d33eab-abbe-4eca-94e9-c05138d06c07', 'Qarang, men shu yerdaman! 👀', 'Endi u hatto xonaning narigi burchagidan ham sizni diqqat bilan kuzatadi. Rivojlanishni kuzatish bo‘limida ko‘z bilan aloqa qilishdagi bu ajoyib yutuqni qayd eting va uning ulg‘ayayotganidan faxrlaning!'),
  ('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa', 'Yulduzli tushlar 🌌', 'Bolalar kun tartibini yaxshi ko‘radi. Aqlli ertaklar bo‘limida u uchun maxsus ertak yarating.'),
  ('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9', 'Siz ajoyibsiz! 🌸', 'Ba’zan hech narsani uddalay olmayotgandek his qilasizmi? Ammo chaqalog‘ingizning sog‘lom va sokin nafas olayotganiga qarang... Siz qo‘lingizdan kelganicha eng yaxshisini qilyapsiz!'),
  ('faace99e-5074-497e-b5c0-f25a9880f5b0', 'Ona uchun quvvat 🍲', 'Kundalik yugur-yugurda ovqatlanishni unutib qo‘ymadingizmi? Sog‘lom retseptlar bo‘limidan ham quvvatingizni tiklaydigan, ham sutingizni ko‘paytirishga yordam beradigan tez tayyorlanuvchi sho‘rva retseptini tanlang.'),
  ('1cd41578-3422-4bf8-9401-e9a058dcad6f', 'Atigi 15 daqiqa 🛁', 'Chaqaloq uxladimi? Endi Hamkor rejimida barcha bildirishnomalarni juftingizga yo‘naltiring. Siz esa vannaxonaga kirib, 15 daqiqa davomida iliq suv va sukunatdan bahramand bo‘ling.'),
  ('73a10da9-aef9-4c21-b8d7-bca1f62e8528', 'Tajriba almashish 💬', 'So‘nggi kunlarda uning qaysi harakati sizni eng ko‘p kuldirmoqda? Anacan hamjamiyatiga kiring va ushbu onni post sifatida ulashing. Boshqa onalarning hikoyalarini o‘qish sizga ham yaxshi ta’sir qiladi.'),
  ('acfd33be-87a0-41a3-858d-d5921f61d9a4', 'Qo‘llar bilan tanishuv 👋', 'O‘z qo‘llarini kashf etib, ularga soatlab qarayaptimi? Rivojlanishning bu kulgili va mo‘jizaviy onini o‘tkazib yubormang — darhol Chaqaloq fotosessiyasi yordamida suratga olib, abadiylashtiring!'),
  ('5543e602-8610-44ac-8995-56ec74a0576e', 'Aqlli sukunat 🤫', 'Kechki injiqliklarni imkon qadar kamaytirish uchun xonadagi shovqin darajasini nazorat qilish muhim. Ovoz o‘lchagichni yoqing, haddan tashqari shovqinli muhitdan saqlaning va chaqalog‘ingizni orom olishga tayyorlang.'),
  ('81600590-d6f0-495d-b852-9afcf35b137a', 'Kashfiyotchi kiyimi ⛅', 'Sayrga chiqmoqchisiz-u, ammo ob-havo qanday bo‘lishi aniq emasmi? Ob-havo va kiyim bo‘yicha yordamchingiz orqali bugungi haroratga eng mos kiyimlar uyg‘unligini bir necha soniyada toping.'),
  ('fbf2b91a-0a2a-4aa9-9404-589ba5628b25', 'Tonggi tabassum ☀️', 'Ko‘zlarini ochishi bilan sizga qarab, yuzida katta tabassum paydo bo‘ldimi? Siz dunyodagi eng qimmatbaho sovg‘ani oldingiz. Bugun shunchaki shu lahzani eslab, ijobiy kayfiyatda qoling.'),
  ('1f2c4967-df72-43b6-91d0-25ece4f2331b', 'Bayramga 10 kun qoldi! 🎂', 'Tayyorlaning, 3 oylik bo‘lishiga atigi 10 kun qoldi! Ilk katta sanalardan biri yaqinlashmoqda. Chiroyli konsepsiya o‘ylab topish va tort buyurtma qilish uchun ayni vaqt!'),
  ('488e046f-44fb-4fcc-80e0-064c20288a56', 'Jamoaviy tabrik 🥂', 'Bugun kechqurun juftingiz bilan 80 kunlik mehnatingiz uchun bir-biringizga minnatdorlik bildiring. Siz buni uddaladingiz!'),
  ('720785a0-3423-4036-a26d-bba9419b8cb2', 'Ajoyib 80-kun! 🎉', 'Birga ekaningizga roppa-rosa 80 kun bo‘ldi! Chaqaloq fotosessiyasi bo‘limiga kiring, 80-kunga bag‘ishlangan maxsus stikerlar bilan bu sanani abadiylashtiring va esdalik sifatida hamjamiyatda ulashing!'),
  ('36b1e2d3-b43a-467e-b08f-870a612d1bb5', 'Yig‘i kodi 🧩', 'Qorni och emas, tagligi toza, ammo baribir bezovtami? Sababini aniqlashga qiynalayotgan bo‘lsangiz, Yig‘i tahlilidan foydalanib, bu tovush ortidagi asl ehtiyojni bilib oling.'),
  ('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee', 'Charchoqning samimiyligi 💖', 'Uy tartibsiz, ovqat esa onlayn buyurtma qilinganmi? Hechqisi yo‘q. Siz bu yo‘lda yolg‘iz emassiz.'),
  ('8f6c6637-de06-4b9d-8e44-d9e85864f3c8', 'Ertalabki mashq 🐢', 'U endi boshini tikroq tutyapti! Qorin bilan yotish vaqtini qiziqarli mashg‘ulotga aylantiring. Uni ko‘zgu qarshisiga qo‘yib, o‘z aksiga qanday munosabat bildirishini kuzating.'),
  ('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74', 'Eslatmalar ro‘yxati 📝', 'Uyga kerakli narsalar hech tugamaydi. Ularni eslab qolishga urinib, miyangizni charchatmang: Xaridlar ro‘yxatini oching, kerakli narsalarni yozib qo‘ying va ro‘yxatni bir tegishda turmush o‘rtog‘ingiz bilan ulashing.'),
  ('12a076b6-d8dc-4bec-a8af-ddc523182bad', 'Ertak vaqti 📖', 'Chaqalog‘ingizning kelajakda buyuk xayolparast bo‘lishi hozirdan boshlanadi. Aqlli ertaklar yordamida sehrli ertak yarating, uni o‘qib bering va ko‘zlari asta-sekin yumilishini kuzating.'),
  ('58ce6bd9-90fd-4e98-a133-ddfda6d59177', 'Cho‘ntagingizdagi pediatr 🤖', 'Vazni yaxshi oshyaptimi? Najasining rangi o‘zgachami? Vahimaga tushishdan oldin Anacan AI’ga yozing, muammoning mohiyatini bilib oling va xotirjam qiluvchi ma’lumotga ega bo‘ling.'),
  ('7d54b8de-cc42-4891-b97a-5856eefffe9d', 'Shaxsiy ertagingiz yaratilmoqda 🪄', 'Bu oqshom bosh rolda chaqalog‘ingiz bo‘lsin! Aqlli ertaklar vositasiga kiring va mavzuni yozing: “Kechalari uxlashni istamaydigan kichkina ritsarning sarguzashti”. Sun’iy intellekt aynan siz uchun noyob va yoqimli hikoya yaratishiga imkon bering.'),
  ('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a', 'Muloqotga tayyormisiz? 🗣️', 'Endi u shunchaki tovush chiqarmayapti, balki ovozingizga turli ohanglarda javob berishga harakat qilmoqda! Rivojlanish kuzatuvchisini oching, muloqotdagi bu ajoyib sakrashni qayd eting va u bilan uning tilida suhbatlashing.'),
  ('f027a882-3827-4905-9807-216432d88e53', 'Onalikdagi xotira tumanligi 🌫️', 'Kecha nima yeganingizni eslay olmayapsizmi? Onalardagi unutuvchanlik (Baby brain) mutlaqo real holat. Miyangizni zo‘riqtirmang, uyga kerak bo‘lgan barcha narsani Xaridlar ro‘yxatiga yozing, qolganini juftingiz hal qilsin.'),
  ('2e536117-6f18-4388-b1bd-29587c89d3cb', 'To‘kilayotgan sochlar haqiqati 💇‍♀️', 'Oynaga qaraganingizda soch to‘kilishi sizni qo‘rqityaptimi? Bu tug‘ruqdan keyingi davrning eng yoqimsiz haqiqatlaridan biri! Siz yolg‘iz emassiz, hoziroq Anacan Hamjamiyatiga kiring va boshqa onalar bu inqirozni qanday yengayotganini o‘qing.'),
  ('41393920-01a7-42fe-a049-e26e1148a375', 'Sukunat izlab 🤫', 'Ba’zida uy ichidagi shovqin o‘zimiz sezmagan holda chaqaloqning uxlab qolishiga xalaqit beradi. Shovqin o‘lchagichni yoqing, xona akustikasini tekshiring va uning uchun eng maqbul sokin muhitni yarating.'),
  ('acb2ca22-b3e3-4ac0-b344-a63734056dfa', 'Milklari qichishyaptimi? 🦷', 'Chaqalog‘ingiz hamma narsani, ayniqsa o‘z qo‘llarini og‘ziga solyaptimi? So‘lagi ko‘p oqishni boshladimi? Darhol Tish chiqishi kuzatuvchisida dastlabki belgilarni qayd eting va bu uzoq jarayonga tayyor turing.'),
  ('357bed80-6ac0-481c-9f5b-22bc1c97e3fe', 'Qo‘llarini kashf etish 🤲', 'Osib qo‘yilgan o‘yinchoqlarga ataylab qo‘l uzatishga harakat qilyaptimi? Demak, uning harakat ko‘nikmalari rivojlanmoqda. Tavsiya etilgan mahsulotlar bo‘limidan uning bu yangi qiziqishini qo‘llab-quvvatlaydigan xavfsiz ushlash o‘yinchoqlarini ko‘rib chiqing.'),
  ('3c4bae00-6309-4214-a502-aa8dcb398a77', 'Ob-havo syurprizi ⛅', 'Tashqariga chiqmoqchisiz-u, ammo derazadan qarab qanday kiyinishni bilmayapsizmi? Chaqaloqni qavat-qavat kiyintirib, terlatib yubormang. Ob-havo va kiyim vositasi bugungi haroratga eng mos kiyimni bir necha soniyada tavsiya qilsin.'),
  ('42bfdf13-2735-49dc-b527-89506330c670', 'Dadaning yelkalari 👨‍👧', 'Sabringiz tugab, qo‘llaringiz tolib ketdimi? Bugun kechqurun Hamkor rejimini yoqing. Chaqaloqning kekirishiga yordam berish va uni xonada ko‘tarib aylantirish butunlay dadasining zimmasida. Siz esa divanda shunchaki dam oling.'),
  ('3d2a21ef-6e5b-4f36-9011-f9c3474762a4', 'Och emas, unda nega yig‘layapti? 🧩', 'Nima qilsangiz ham tinchimayaptimi va yig‘isi odatdagidan boshqachami? Taxmin qilishni bas qiling: uning ovozini Yig‘i tahliliga eshittiring va muammo qorin dam bo‘lishimi yoki uyqusizlikmi — darhol bilib oling.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('b092d275-f2d6-47ce-b8d0-3f8ced210589'::uuid, 'Quloqchinlar va qahva 🎧', 'Bugun haqiqatan ham juda og‘ir kun bo‘ldi. His-tuyg‘ular kundaligiga ichingizdagilarni yozib qoldiring. So‘ng quloqchinlarni taqing, sevimli musiqangizni yoqing va 10 daqiqa chinakam osoyishtalikda issiq qahvangizni iching.'),
  ('c6fb2576-7fa6-4e01-b8a4-ec89ac753089', 'Ertalabki toshqin 💩', 'Ko‘zingizni ochishingiz bilan bo‘ynigacha bulg‘angan chaqaloq va almashtirilishi kerak bo‘lgan choyshablarga duch keldingizmi? Taglik kuzatuvchisiga bu katta falokatni kulib qayd eting. Ha, onalikning shunday kunlari ham bo‘ladi!'),
  ('022a6d7a-76fe-47e7-aae6-a35dad3d3555', 'Vaqtni o‘lchang ⏱️', 'Tartibsiz emizish va ovqatlantirish sizni charchatyaptimi? Ovqatlanishni kuzatish taymeri yordamida chaqaloq ko‘krak emishga yoki butilkadan ichishga qancha vaqt sarflayotganini o‘lchang va uning endigina shakllanayotgan kun tartibini yaxshiroq tushunib oling.'),
  ('62da6149-1edf-4e2a-abc6-d69d21a43fa4', 'Ertalabki mashqqa qarshilik 🐢', 'Chaqaloq qornida yotishni (Tummy time) istamay, yig‘layaptimi? Uni majburlamang. Anacan AI’dan: “3 oylik chaqaloq uchun qornida yotish vaqtini qanday qilib qiziqarli qilishim mumkin?” deb so‘rang va tezkor maslahatlar oling.'),
  ('938dd21f-e30f-4b2b-b3e0-d79140f44b59', 'Yana bir ertak yarataylik! 🪄', 'Bu safar Aqlli ertaklarga yanada kulgiliroq topshiriq beraylik: “Dadasining soqoliga yashirinib olgan mittivoy haqida hikoya”. Sun’iy intellekt yaratgan bu hikoyani juftingiz ovoz chiqarib o‘qisin, xona kulgiga to‘lsin.'),
  ('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc', 'To‘rt devordan tashqariga 🏃‍♀️', 'Uyda siqilyapsiz-u, ammo chaqaloq bilan qayerga borishni bilmayapsizmi? Onalar uchun qulay joylar bo‘limidan bolalar aravachasi bilan bemalol kirish mumkin bo‘lgan va emizish xonasi mavjud eng yaqin kafeni topib, biroz odamlar orasiga chiqing.'),
  ('55bafaf5-82ef-4f88-880d-836cf89145d0', 'Tovushlar kuchi 🌊', 'Kechga yaqin boshlanadigan sababsiz yig‘i xurujlari juda charchatadi. Chaqaloqni xonaga olib kiring, Oq shovqinlardan okean to‘lqinlari yoki soch quritgich tovushini tanlab, muhitni bir zumda tinchlantiring.'),
  ('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87', 'Onaning quvvati qayerda? 🔋', 'Ko‘zgudagi charchagan ko‘zlaringizga qarab, o‘zingizni ayblamang. Ovqatlanishingizga e’tibor beryapsizmi? Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan, temirga boy ona smuzisini tanlab, quvvatingizni tiklang.'),
  ('13035ad4-af08-4b79-ba71-a42ceb60fe5b', 'Jamoaviy muhokama 🛋️', 'Farzandingiz uxlagandan so‘ng, Kayfiyat kundaligidagi haftalik statistikangizni turmush o‘rtog‘ingiz bilan birga ko‘rib chiqing. Qaysi kunlari ko‘proq stressni his qildingiz? Nimani boshqacha qilishingiz mumkin? Siz bir jamoasiz!'),
  ('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6', 'Pastga qarang! 👣', 'U allaqachon o‘z oyoqlarini kashf etmoqda! Oyoq barmoqlarini ushlashga urinadigan o‘sha kulgili va yoqimli lahzani o‘tkazib yubormang. Chaqaloq fotosessiyasini oching, stikerlar bilan bezating va rivojlanishdagi ushbu katta bosqichni qayd eting.'),
  ('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8', 'Tish qashlagich izlaymiz 🦷', 'So‘lagi tinmay oqyaptimi, hamma narsani kemiryaptimi? Tish chiqishini kuzatish vositasi ogohlantirmoqda. Tavsiya etilgan mahsulotlar bo‘limidan toza silikon yoki yog‘och tish qashlagichlarni izlashning ayni vaqti.'),
  ('0d132ba6-d6e9-44f6-a85d-e139c66b9760', 'Tezkor suhbat 🤖', 'Nega bola birdaniga kunduzgi uyqudan bosh tortmoqda? Uzun maqolalarni o‘qishga vaqtingiz yo‘q. Savolni to‘g‘ridan-to‘g‘ri Anacan AI''ga yozing va 3 oylik uyqu regressiyasi haqida aniq, qisqa javob oling.'),
  ('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198', 'Ertak falsafasi 🪄', 'Aqlli ertaklar yana ishga kirishdi! Tizimga shunday yozing: “Kunduzi o‘ynashdan charchab, kechalari chiroyli tushlar ko‘radigan pari haqidagi hikoya”. O‘qir ekansiz, balki o‘zingiz ham uxlab qolarsiz.'),
  ('6c6289cf-6e7c-4e83-a178-d01d67cef488', 'Mantiqqa zid kiyimlar 👗', 'Ba’zan bolani juda yupqa, ba’zan esa juda qalin kiyintirasizmi? Ikkilanmang. Derazadan qarash o‘rniga darhol Ob-havo va kiyim bo‘limini tekshiring, tizim tavsiya qilgan qavatma-qavat kiyimlar bilan xotirjam bo‘ling.'),
  ('132d4620-5085-4072-ac1e-81f46dc4e74c', 'Uyquni shovqin o‘lchagich bilan asrang 🤫', 'Hayajondasiz, uyda tayyorgarlik ketmoqda, ammo chaqaloqning uyqusi ham buzilmasligi kerak. Xonada shovqin o‘lchagichni yoqib qo‘ying va shovqin belgilangan chegaradan oshganini darhol ko‘ring.'),
  ('32bd9b1c-365c-405d-addd-9a30d6295abc', 'Bugun uy tozalanmaydi! 🛑', 'Hamma joyni yig‘ishtirishga majbur emassiz. Hamkor rejimini yoqing: bugun uyni tozalash va ovqat buyurtma qilish turmush o‘rtog‘ingiz zimmasida. Siz esa shunchaki ertangi 3 oylik fotosessiyani rejalashtiring.'),
  ('a4183b3c-1979-434f-a71f-64b50e2e618c', 'Tayyorgarlik vaqti! 🎂', 'Diqqat! Ertaga katta kun – roppa-rosa 3 oy bo‘ladi! 90-kunga o‘zgacha kayfiyat bag‘ishlash uchun tort buyurtma qilishni yoki kichik konsepsiya tayyorlashni unutmagandirsiz? Shoshiling!'),
  ('10a571b7-6bc2-4092-a70f-a265883d71ba', 'ROPPА-ROSA 3 OY! NAQD 90 KUN! 🎉', 'Siz buni uddaladingiz! Uyqusizlik, inqirozli davrlar va qo‘rquvlarga qaramay, 90 kun davomida ajoyib jamoa bo‘lib harakat qildingiz. Chaqaloq fotosessiyasini oching, 3 oylik stikerni tanlang va bu quvonchni Anacan hamjamiyatidagi boshqa onalar bilan darhol baham ko‘ring!'),
  ('9877e456-4a5e-45a3-aee9-e9703be5cf91', 'Tabriklaymiz! 🥂', 'Barcha qaydlaringiz va rivojlanish grafiklaringizni ortga qaytib ko‘rib chiqing. Chaqalog‘ingiz qanchalik ulg‘ayganini, siz esa qanchalik kuchli bo‘lib qolganingizni ko‘ring. O‘zingiz bilan faxrlanishning ayni vaqti!'),
  ('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e', 'Jamoaning g‘alaba lahzasi 💖', 'Chaqaloqni o‘sha maxsus uyqu taymeri yordamida uxlatdingiz. Endi esa turmush o‘rtog‘ingiz bilan yuzma-yuz o‘tiring. Shu 90 kunning har bir lahzasi uchun bir-biringizga minnatdorlik bildiring. Bu nafaqat farzandingizning, balki sizning ota-ona bo‘lganingizning ham 3 oyligidir!'),
  ('5c67089a-581e-455d-b113-f87f427babb2', 'O‘zingizga xos ertak 🪄', 'Bu oqshom Aqlli ertaklar vositasiga yoqimli bir mavzu beraylik: “Osmondan tushgan eng yoqimli yulduzning hikoyasi”. Xonani faqat shu ertakning ovozi va mutlaq sukunat qamrab olsin.'),
  ('66bd508e-0413-4d01-9ea7-c369b0d8cafa', 'Dada maydoni 👨‍👧', 'Sabringiz tugayaptimi? Bugun onalik navbatchiligini qisqa muddatga turmush o‘rtog‘ingizga topshiring. Ular ham biroz birga vaqt o‘tkazishsin, siz esa oyoqlaringizni uzatib, dam oling.'),
  ('8474a75e-7aaf-420e-b5ab-acd7d55ac51c', 'Qahqaha vaqti! 😂', 'Endi u shunchaki jilmaymaydi, ovoz chiqarib qahqaha otadi! U bilan o‘yinlar o‘ynang, qornini qitiqlang. Bu ovoz — uyqusiz o‘tgan barcha tunlarning eng ajoyib mukofotidir.'),
  ('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalayaptimi, qulog‘ini tortayaptimi yoki bir nuqtaga tikilib qolayaptimi? Kechki injiqlik boshlanishini kutmang. Bu belgilarni ko‘rishingiz bilan xonani qorong‘ilating va uyquga tayyorgarlik odatlarini boshlang.'),
  ('1867104a-7fa8-428a-ad5d-dd10e6890f0f', 'Og‘iz orqali kashf qilish 🤤', 'Qo‘llarini, o‘yinchoqlarini, topgan har bir narsasini to‘g‘ri og‘ziga solayaptimi? Bu uning dunyoni o‘rganish usulidir. Hamma narsani qo‘lidan tortib olmang, shunchaki atrofidagi buyumlar toza ekaniga ishonch hosil qiling.'),
  ('4ad3cf84-0aac-46cb-bfdf-5a928764105a', 'Nega uy bunchalik tartibsiz? 🌪️', 'Xona o‘rtasida uyilib yotgan o‘yinchoqlar va yuvilmagan idishlarga qarab, o‘zingizni ayblayapsizmi? Bugun o‘sha idishlar joyida qolaversin. Farzand tarbiyalashning o‘zi ham yetarlicha katta mehnat!'),
  ('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b', 'Ag‘darilish mashqlari 🤸‍♂️', 'U chalqancha yotgan holatdan qorniga ag‘darilishga harakat qilmoqda! Bu kichkina tana uchun katta kurash. Uning bu kulgili urinishlarini qo‘llab-quvvatlang, ammo karavot chetlarida albatta ehtiyot bo‘ling.'),
  ('91aad506-9119-4c1d-9011-ca750f77b2da', 'Siz yetarlisiz! 💖', 'Bugun ertalab oynaga qarab, o‘zingizni charchagan, balki hatto yetarlicha yaxshi emasdek his qildingizmi? Chuqur nafas oling. Chaqalog‘ingizning sizga boqayotgan beg‘ubor ko‘zlari uchun siz dunyodagi eng mukammal insonsiz. Siz yetarlisiz!'),
  ('cc5d4a21-5a6c-4726-9656-04a48085588c', 'Qanchalik charchadik? 🛋️', 'Bola uxlab qoldi, siz-chi? Kayfiyat kundaligini oching va turmush o‘rtog‘ingiz bilan bugungi tartibsizliklarni hazil bilan qayd eting. Og‘ir kunlar o‘tib ketadi, jamoaviy ruh esa qoladi.'),
  ('8557b605-4ddd-4ff9-9e9a-646d4a26ea63', 'Uyqu regressiyasi yaqinmi? 🤖', 'Bola birdan tunda tez-tez uyg‘ona boshladimi? Xavotir olmang, 4-oydagi uyqu regressiyasi yaqinlashmoqda. Bu biologik jarayon haqida Anacan AI’dan qisqa va tinchlantiruvchi ma’lumotni hoziroq oling.'),
  ('88a16b76-764f-4acc-b335-0aa3f126d25a', 'Tashqariga chiqish vaqti ⛅', 'Kiyinib tashqariga chiqish qiyindek tuyulishi mumkin, ammo 20 daqiqalik toza havo chaqaloqqa ham, ruhiy holatingizga ham juda yaxshi ta’sir qiladi. Ob-havoni tekshirib, mos kiyim tanlang va derazani emas, eshikni oching!'),
  ('bb5697de-df9c-4558-a606-a7acef72c755', 'Tunning qahramoni — dada 🦸‍♂️', 'Dastlabki oylarning eng yaxshi qoidasi: chaqaloqning gazini chiqarish va alla aytish navbat bilan bajarilishi kerak! Bu oqshom chaqaloq dadasining bag‘rida, siz esa quloqchinlaringizni taqib, musiqadan zavqlanasiz.'),
  ('4696c250-45bb-4765-b4bf-ee4e94f6361c', 'Onaning finjoni ☕', 'Bugun o‘zingiz uchun nima qildingiz? Hech narsa? Chaqaloq kunduzgi uyquga ketishi bilan telefonni chetga qo‘ying. O‘zingizga issiq qahva (yoki choy) quyib, 10 daqiqa hech narsani o‘ylamang.'),
  ('7831318d-6b24-4373-9578-2c2a43ef02bf', 'Soch yulish san’ati 💇‍♀️', 'Chaqalog‘ingiz qo‘llarini darrov sochlaringizga chirmab, qattiq-qattiq tortyaptimi? Ushlash refleksi kuchaygan! Kulgili, ammo og‘riqli bu rivojlanish bosqichini albatta videoga olib, xotira sifatida saqlab qo‘ying.'),
  ('d66ea07a-276e-489b-bd8f-3ff80abe7258', 'Tana bilan tegishish mo‘jizasi 🫂', 'Hech uxlagisi kelmayaptimi, yotog‘iga qo‘yishingiz bilan yig‘layaptimi? Ba’zan hech qanday vosita kerak emas. Uni ko‘ksingizga qo‘ying va teri bilan teri aloqasi ikkalangizni ham qanday tinchlantirishini his eting.'),
  ('a99309cf-e0e5-4d40-9004-a8b08226861a', 'Yoqasi har 10 daqiqada ho‘l bo‘lyaptimi?', 'Tish chiqishini kuzatuvchidagi ilk ogohlantirishlar endi ro‘yobga chiqmoqda. Pastki milklarini tez-tez tekshirib turing, balki birinchi oq marvarid chiqish arafasidadir!'),
  ('b14018ad-b2b5-4374-a785-9d281ebdd7e0', 'Atigi 15 daqiqa sukunat 🤫', 'Kun bo‘yi charchoqdan boshingiz yorilay deyaptimi? Chaqaloqni uxlatganingizda Ovoz o‘lchagichni yoqib, atrofdagi shovqinni nazorat qiling, uydagilardan jimlikni saqlashni so‘rang va miyangizga dam bering.'),
  ('c69510ed-a6e2-4456-a462-211d3917dec3', 'Boshqa onalar nima qilyapti? 💬', '“Faqat mening bolam shunday qiladimi?” deb o‘ylayapsizmi? Siz yolg‘iz emassiz! Anacan hamjamiyatiga kiring, u yerdagi onalarning hayotiy hikoyalarini o‘qib, yengil nafas oling.'),
  ('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'Ko‘zgudagi do‘st 👀', 'Uni ko‘zgu qarshisiga olib boring. U o‘z aksiga hayrat va tabassum bilan qanday qarayotganini kuzating. U hali ko‘zgudagi tasvir o‘zi ekanini bilmaydi, ammo bu o‘yin uning aqliy rivojlanishi uchun juda foydali.'),
  ('6f416e63-4acf-4dd2-8216-6601a8c26df5', 'Aybdorlik hissidan xalos bo‘ling 🛑', 'Bugun sabringiz chidamadi, balki biroz jahlingiz chiqdi va endi vijdoningiz qiynalyaptimi? To‘xtang. Siz robotmisiz? Yo‘q. His-tuyg‘ularingizni qabul qiling, o‘zingizni kechiring va ertaga yangi kunni boshlang.'),
  ('d584b1c4-e42a-483d-b585-e83a9ab20c88', 'Ona uchun quvvat manbai 🍲', 'Chaqaloqni to‘ydiraman deb, o‘zingiz och qolib ketdingizmi? Sog‘lom retseptlar bo‘limidan oson hazm bo‘ladigan, quvvat beruvchi yegulik tayyorlang. Unga ham kuch bera olishingiz uchun o‘zingiz baquvvat bo‘lishingiz kerak.'),
  ('014e3f07-72e8-47f8-b62e-ff583a9df29e', 'Men bilan gaplashing! 🗣️', 'U sizga qarab, g‘alati bo‘g‘inlarni aytyaptimi? Uning ovozi va pauzalariga javob qaytaring. U hozir siz bilan haqiqiy muloqot qilyapti! Bu nutq rivojlanishining eng asosiy bosqichidir.'),
  ('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef', 'Ko‘zga tashlanmaydigan ehtiyojlar 🛒', 'Kundalik yugur-yugurda biror narsa tugab qolayaptimi? Hojatxona qog‘ozi, taglik, shampun? Unutmasdan hoziroq xaridlar ro‘yxatiga qo‘shing — hamrohingizning telefoniga bildirishnoma bo‘lib borsin.'),
  ('e8ec2cd2-3417-4383-8892-bb623cb07365', 'Vaqtni to‘xtatish 📸', 'U shunchalik tez ulg‘ayyaptiki... Bugun kechqurun u uxlayotganda yuz chizgilariga diqqat bilan qarang. Uning mitti qo‘llari va yuzini Chaqaloq fotosessiyasi yordamida suratga olib, bu lahzani abadiylashtiring.'),
  ('2a23a61b-4ca6-48f6-8845-f47a357eed0f', 'Bu ovoz nimani anglatadi? 🧩', 'Ko‘zlarini ochishi bilan ham injiqlanib, ham yig‘layaptimi? Sababini topa olmayotgan bo‘lsangiz, bir necha soniya ichida Yig‘i tahlilidan foydalanib, bu holat ortidagi sirni aniqlang.'),
  ('43fbc1cb-7e93-4983-b59f-f5bc67650d3e', 'Ertakning oxiri yo‘q 📖', 'Bugun kechqurun Aqlli ertaklarga yanada ijodiy topshiriq bering: “Onasining hidini izlagan ayiqcha haqida hikoya”. Kunni mehrga to‘la va sokin yakun bilan tugating.'),
  ('b8cf3d8c-2c7c-497e-8657-18fd989a1928', 'Uydan chiqish rejasi! 🌳', 'Bola bilan qayerga borishni bilmayapsizmi? Parkda sayr qilish charchatadimi? Onalar uchun qulay joylar orasidan bolangiz bilan bemalol o‘tirib, qahva ichishingiz mumkin bo‘lgan maskanni toping.'),
  ('1c648ce0-799c-41f0-964a-90e59cbddc3d', 'Katta g‘alaba, umumiy faxr 🥂', '100 kecha, 100 kunduz... Bu katta mas’uliyatni siz bilan birga yelkasida ko‘tarayotgan juftingizga qarang. Kayfiyat kundaligiga 100-kunning faxrini yozing va bir-biringizni tik turib olqishlang. Bu jamoangizning g‘alabasi!'),
  ('52155593-73d7-4bb9-861d-d87a0ca100e9', '100 KUNLIK MO‘JIZA! 🎉', 'Ha, bugun hayotingiz tubdan o‘zgarganiga roppa-rosa 100 kun bo‘ldi! Siz aql bovar qilmas ishni uddalayapsiz.'),
  ('7c63492d-1515-406a-bd31-b41ece7e0412', 'O‘zingizni olqishlang 👏', 'Ortga nazar tashlasangiz, ilk kunlar qanchalik qo‘rqinchli bo‘lganini, hozir esa ular sizga qanchalik ko‘p narsani o‘rgatganini ko‘rasiz. O‘zingiz bilan faxrlaning. Faqat bolangiz emas, siz ham 100 kun davomida ulg‘aydingiz.'),
  ('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e', 'O‘zingizni unutmang 🍲', 'U to‘ydi, siz-chi? Quvvatingizni tiklash uchun yaxshi ovqatlanishingiz kerak. Bugun o‘zingiz uchun mazali va to‘yimli taom buyurtma qiling.'),
  ('957a90d0-61dc-45f5-a2da-ef7086521cd5', 'Xonada to‘satdan baland kulgi eshitdingizmi? 😂', 'Ha, u endi qah-qah otib kulmoqda! Bu ovoz barcha charchog‘ingizga arziydi.'),
  ('dd50206e-acee-43ac-8f19-c5dd29cf7e62', 'Teri bilan teri kontakti 🫂', 'Chaqaloq juda bezovtami? Hech narsa yordam bermasa, uni ko‘ksingizga qo‘ying. Yuragingiz urishi eng yaxshi tinchlantiruvchi vositadir.'),
  ('2c73f922-1b22-4eb6-922b-215d8e623242', 'Soch tortish o‘yini 💇‍♀️', 'Barmoqlarini sochingizga o‘rab, qattiq tortyaptimi? Ushlash refleksi rivojlanmoqda. Biroz og‘riqli bu rivojlanish lahzasini kulib qarshi olishga harakat qiling.'),
  ('f32eaadc-b85c-4f36-b182-6f6665e1eaae', 'Mutlaq sukunat 🤫', 'Uxlab qolishga qiynalyaptimi? Xonani butunlay qorong‘i qiling va shovqinni bartaraf eting. Qorong‘ilik va sukunat uning uyqu uchun eng yaxshi hamrohlaridir.'),
  ('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b', 'Birinchi tishlari chiqyaptimi? 🦷', 'So‘lak oqishi ko‘paydimi? Tish chiqishini kuzatish bo‘limiga qayd kiriting va toza tish qashlagichlarni doimo qo‘l ostingizda saqlang.'),
  ('724659ec-f59f-4bfe-b20d-efdd3d977217', 'Bo‘sh vaqt 🛋️', 'U o‘zi mustaqil o‘ynayotganida darhol ishga shoshilmang. O‘tirib, shunchaki 5 daqiqa uni uzoqdan kuzating va qahvangizni iching.'),
  ('aaed3963-e8dd-47d4-93bd-9b307c2b65fd', 'Tonggi energiya ⚡', 'Ko‘zini ochishi bilan g‘ug‘ulayaptimi? U siz bilan gaplashmoqchi. Tabassum qilib javob bering — bu uning nutqi rivojlanishiga asos bo‘ladi.'),
  ('d1e64fb7-d149-4fd0-afca-834eed2264d1', 'Uyqu regressiyasimi? 🌙', 'Kechalari tez-tez uyg‘ona boshladimi? Bu 4-oydagi uyqu regressiyasining belgilari bo‘lishi mumkin. Sabrli bo‘ling, bu ham o‘tkinchi bosqich.'),
  ('13cad6d0-aa0a-426b-9515-1e96e73e716a', 'Yangi kashfiyotlar 🤲', 'Qo‘liga tushgan hamma narsani og‘ziga solyaptimi? Vahimaga tushmang, bu uning dunyoni o‘rganish usuli. Faqat atrofni toza tuting.'),
  ('bfab4a59-c162-47a2-9035-51b03b7fe911', 'Uy ishlari kutib turishi mumkin 🛑', 'Tartibsiz xonaga qarab asabiylashmang. Siz bir insonni voyaga yetkazyapsiz, mukammal uy bekasi bo‘lishingiz shart emas.'),
  ('ca9affc4-d638-41a2-8dc7-75447d9ea222', 'Dadaning navbati 👨‍🍼', 'Bugun kechqurun chaqaloqning gazini chiqarish va alla aytish — dadasining vazifasi. Siz esa borib dam oling.'),
  ('1e555e61-fac2-4756-83d5-5c2a2ceaa400', 'O‘zingizga xos ertak 🪄', 'Aqlli ertaklar yordamida kechki uyquga yotishni osonlashtiring. Chaqalog‘ingiz uchun maxsus, yoqimli hikoya yaratib, o‘qib bering.'),
  ('a4146327-bb44-44e0-9860-d8e3c1abe5c4', 'Biz bir jamoamiz! 💪', 'O‘zingizni yolg‘iz va charchagan his qilyapsizmi? Chuqur nafas oling. Siz bu dolg‘ali kunlarning eng kuchli qahramonisiz.'),
  ('e3c0355b-40c6-476a-8c2d-f69c78debdb1', 'Ajoyib ag‘darilish 🤸‍♂️', 'Chalqancha yotgan holatdan qorniga ag‘darilishga harakat qilyaptimi? U juda tirishyapti! Bu urinishlarini kuzating, ammo uni yotoqda hech qachon yolg‘iz qoldirmang.'),
  ('532d58e2-50f3-422a-818a-36c88094bb87', 'Nima kiydirsam ekan? ⛅', 'Ko‘chaga chiqayotganda chaqalog‘ingizga nima kiydirish haqida bosh qotirmang. Ob-havo va kiyim vositasidan foydalanib, mos kiyimlar to‘plamini bir necha soniyada toping.'),
  ('f37039a0-f7af-487a-827e-622e2d9e4d05', 'Holdan toyish tabiiy 🔋', 'Sabringiz tugay boshlaganda o‘zingizni yomon ona deb hisoblamang. Bunday charchoq tabiiy. Juftingizdan yordam so‘rashdan tortinmang.'),
  ('f94cdd25-2b6b-47df-81dc-6e3cab221652', 'Sizning o‘zingiz yetarlisiz! 🌸', 'Bugun hamma ish teskarisiga ketyaptimi? Hechqisi yo‘q. Chaqalog‘ingizga sizdan boshqa hech kim kerak emas. Siz uning uchun to‘liq yetarlisiz.'),
  ('07f48fa2-56fd-416e-adda-88c824f2bd6f', 'Chuqur uyquga tayyorgarlik 🛀', 'Iliq vanna, yengil massaj va xonani qorong‘ilashtirish... Uyqu tartibiga rioya qilish — tun bo‘yi uzluksiz uyquning siri.'),
  ('828415f3-317f-4e76-8caf-753026dcf9f1', 'O‘zingizni aybdor his qilmang 💖', 'Farzandingizga kam vaqt ajratyapman, deb o‘ylaysizmi? Mazmunli va quvonchli 10 daqiqa stressga to‘la 1 soatdan qadrliroqdir.'),
  ('f4730701-e02f-4cf0-9730-df8b7e034297', 'O‘zim ushlayman! 🧸', 'Osib qo‘yilgan o‘yinchoqlarga aniq qo‘l uzatyaptimi? Ko‘z va qo‘l muvofiqligi rivojlanmoqda. Uni turli rangdagi buyumlar bilan rag‘batlantiring.'),
  ('70597740-ab51-4b20-b743-042bccb768a6', 'Ertalabki mashq 🐢', 'Qorni bilan yotish bo‘yin mushaklarini mustahkamlaydi. Yig‘lasa ham, har kuni hech bo‘lmaganda qisqa muddat bunga odatlantirishda davom eting.'),
  ('81a8fffa-561b-48b8-9be0-ff9b930a7bac', 'Hissiy yengillik 📝', 'Bugun barcha muammolar ustingizga yog‘ilayotgandek tuyulyaptimi? Kayfiyat kundaligiga barcha qiyinchiliklaringiz va charchog‘ingizni yozing. Hislaringizni ichingizga yutmang.'),
  ('87db18be-f6b3-443d-9d07-0e305836d90b', '110-kun g‘alabasi! 🥂', 'Mana, roppa-rosa 110 kundirki, yangi bir hayotni boshqaryapsiz. Juftingiz bilan bir-biringizga minnatdorlik bildirib, bu oqshom sukunatdan zavqlaning.'),
  ('18211145-ceeb-48f3-8053-1e2ff686e384', 'Tovushlar sehri 🌊', 'Kechqurun yig‘i xurujlari boshlansa, vahimaga tushmang. Chaqalog‘ingiz uchun Oq shovqinni yoqib, xona muhitini bir zumda o‘zgartiring.'),
  ('49d00520-8368-4f13-9074-fbe894888b76', 'Sun’iy intellektdan so‘rang 🤖', 'Xayolingizda minglab savollar bormi? Qidirishga vaqt sarflamang — darhol Anacan AI’dan so‘rab, aniq va ilmiy asoslangan javob oling.'),
  ('e6ea83f7-b8a5-46f7-ba44-81c58175071e', 'Pastga qarang! 👣', 'U allaqachon oyoq barmoqlarini kashf etmoqda! Bu kulgili va hayratlanarli lahzani diqqat bilan kuzatib, uning rivojlanishidan zavqlaning.'),
  ('53a91083-d8e0-4baf-9f90-46ce72a9291d', 'Ko‘zgudagi do‘st 👀', 'Uni ko‘zgu oldiga olib boring. O‘z aksiga hayrat bilan qarab, qanday kulishini kuzatish — ajoyib mashg‘ulot.'),
  ('96d4756e-270f-426b-9e78-f2a573accdac', 'Sayr vaqti 🌳', 'To‘rt devor orasida siqilib qoldingizmi? Uni aravachasiga yotqizing va hech bo‘lmasa 15 daqiqaga toza havoga chiqing. Bu ikkalangizga ham juda yaxshi ta’sir qiladi.'),
  ('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41', 'Tun qahramoni 🦸‍♂️', 'Tunda uyg‘onishlardan charchadingizmi? Dadasini uyg‘otishdan tortinmang. Bir jamoa bo‘lish — yukni teng bo‘lishish demakdir.'),
  ('1063f207-152c-4454-9267-2e05e30929d8', 'Aqlli sukunat 🤫', 'Uxlab qolayotganida to‘satdan chiqqan tovushlar uni uyg‘otadimi? Tovush o‘lchagich yordamida xonadagi detsibel darajasini nazorat qiling.'),
  ('17c1a37e-ab5c-4032-afa2-27e4d0964076', 'Ochmi yoki charchaganmi? 😭', 'Sababsiz yig‘layaptimi va ovozi odatdagidan boshqachami? Balki u och emasdir, shunchaki uyqusi yetmagandir. Uyqu rejimini diqqat bilan kuzating.'),
  ('93512cbe-adab-49c7-8e82-4466bf0e00ad', 'Ona uchun 10 daqiqa ☕', 'Bola uxlashi bilan uy ishlariga shoshilmang. Divanga o‘tiring, qahvangizni iching va 10 daqiqa shunchaki devorga qarab dam oling.'),
  ('8bc219eb-803c-491e-9625-0efec17a7dad', 'Navbatni topshiring 🛋️', 'Bola uxlaganida siz ham darhol uxlab qolishni istasangiz, uydagi boshqa ishlarni juftingizga topshiring. Sog‘lig‘ingiz hamma narsadan muhimroq.'),
  ('924ff591-18ec-4c20-80af-4008cda2fc41', 'Turli ohanglar 🗣️', 'Uning tovushlari tobora balandroq va rang-barangroq yangray boshladi. Uni tinglang, tovushlariga taqlid qilib kuldiring.'),
  ('be9ad5fd-195c-40e7-99c6-7f5f91e01526', 'Eslatma ro‘yxati 🛒', 'Uyqusizlik xotirangizni susaytirdimi? Uyga kerakli narsalarni eslab qolishga urinmang, ularni xaridlar ro‘yxatiga yozib qo‘ying.'),
  ('2226c745-19bb-4270-8e5c-a438c71816d4', 'Boshqa onalar nima qilyapti? 💬', 'Xavotirdamisiz? Anacan Hamjamiyatiga kirib, savolingizni bering. Ishoning, barcha onalar shunga o‘xshash yo‘llardan o‘tadi.'),
  ('31bb23a0-6713-4c06-9f74-65b7a51a3dd9', 'Tinchlantiruvchi ovoz 📖', 'Bugun kechqurun bolangizga shunchaki o‘z ovozingiz bilan qisqa bir ertak o‘qib bering. Hech qanday vosita kerak emas, ona ovozi — eng buyuk sehr.'),
  ('34253cb9-0e01-47a7-9def-03c3b3e05aba', 'Qiziqarli o‘yinlar 🎈', 'Yotgan holda oyoqlari bilan havoda velosiped haydayotgandek harakat qilyaptimi? Bu uning yangi ermagidir. Siz ham unga qo‘shilib, uni qitiqlang.'),
  ('4eb27952-4f25-4c0d-8e25-cf21169fe3eb', 'O‘zingizni asrang 🥑', 'Tug‘ruqdan keyingi davrda suyaklar va tishlar zaiflashishi mumkin. Ratsioningizga kalsiy qo‘shishni unutmang. O‘zingizga yaxshi g‘amxo‘rlik qiling.'),
  ('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c', 'Bugun ertalab hech narsadan ko‘ngli to‘lmayaptimi? ☁️', 'U jadal o‘sish davrida bo‘lishi mumkin. Uni ko‘proq bag‘ringizga bosib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('813f6345-1636-47fd-9a6b-aee16d069800', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalab, esnashini kutmang. Nigohi xiralashishi bilan darhol uyquga tayyorlash odatlarini boshlang.'),
  ('088b061c-e51f-4931-8636-b06152d7eaff', 'Nimadir xayolingizni band qilyaptimi? 🤖', 'Forumlarni soatlab o‘qish o‘rniga, savolingizni Anacan AI''ga berib, tezkor javob oling.'),
  ('5e878638-6613-43f0-b734-dd308940758d', 'To‘liq 4 oylik bo‘lishiga 5 kun qoldi! 🎂', 'Agar tort bilan suratga tushish an’anangiz bo‘lsa, ayni paytda tortga buyurtma berish kerak.'),
  ('616fd04c-b736-454a-9242-b3c011b0cdc5', 'Sab­ringiz tugab, qo‘llaringiz charchadimi? 👨‍👧', 'Bugun kechqurun bolani dadasiga berib, eshikni yoping va 15 daqiqa o‘zingiz bilan yolg‘iz qoling.'),
  ('232de7cd-2ff6-4b62-8cee-002063d545fd', 'Tartibsiz jannat 🌪️', 'Uyning hamma joyida bolalar buyumlari sochilib yotibdimi? Mayli. Uyning tartibsizligi sizning yomon ona ekaningizni emas, chaqalog‘ingiz siz uchun ustuvor ekanini ko‘rsatadi.'),
  ('2cbef83d-a5f1-4b69-858b-9d1310e2cac3', 'Uyda o‘tirishdan zerikdingizmi? ☕', 'Uyda o‘tirishdan zerikdingizmi? Onalar uchun qulay joylar orasidan yaqin atrofdagi bolalar aravachasi bilan bemalol kirish mumkin bo‘lgan kafeni tanlang.'),
  ('ff5950e2-aed4-41ca-bc9a-64a1b039968a', 'Aqlli ertak vaqti 🪄', 'Aqlli ertaklarda bugungi tun uchun maxsus hikoya yarating: Bulutlar ustida uxlaydigan jasur kichkintoy haqidagi hikoya.'),
  ('37346c6c-3239-4e07-bcc0-24af9be99f3f', 'So‘lak oqishi boshlandi 🤤', 'Kiyimining yoqasi bir necha soniya ichida shalabbo bo‘lib qoladimi? Milklar asta-sekin tish chiqishiga tayyorlanmoqda. Silikon ko‘krakpechlar eng yaxshi yordamchidir.'),
  ('86a98c8a-884a-4567-83c1-4d206dccead9', 'Toza havo — davo 🌳', 'Chaqaloq juda bezovta bo‘lsa, uni darhol toza havoga olib chiqing. Toza havo bezovtalik xurujlarini tinchlantirishning eng oddiy va samarali usulidir.'),
  ('ae291c04-b5c7-4ff1-937e-2b2b6d502624', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash yukni yengillashtiradi.'),
  ('5fcfd433-5086-40d6-89d5-0d756fb06e17', 'Musiqaning kuchi 🎶', 'Kechga yaqin boshlanadigan sababsiz yig‘ini sekin ohangdagi klassik musiqa bilan tinchlantirishga urinib ko‘ring. Bu ko‘pincha yordam beradi.'),
  ('b4113857-b164-4ab8-b41d-4e516341edad', 'Harakat qilyapti! 🤸‍♂️', 'Qorni bilan yotganida qo‘llariga tayanib, boshini ko‘tarishga harakat qiladi. Mushaklari kundan-kunga mustahkamlanmoqda, barakalla!'),
  ('ec61705b-0071-49b5-a6b0-3849dfa461ac', 'Vaqtni to‘xtatish 📸', 'U shunchalik tez ulg‘aymoqdaki... Chiroyli kiyintirib, chaqaloq fotosessiyasi orqali bu lahzani abadiylashtiring.'),
  ('72b166c9-a8f9-4dc5-be7f-5911ccda18ea', 'Kulishlar soni ortmoqda 😂', 'Siz qilgan har bir kulgili harakatga qahqaha bilan javob beradi. Bu ajoyib lahzani videoga olishni unutmang!'),
  ('968ec1c9-36e5-4127-8374-922149e153dc', 'Uyqu poydevori ⏱️', 'To‘rtinchi oyda to‘g‘ri uyqu rejimini yo‘lga qo‘yish juda muhim. Tunlaringiz osoyishta o‘tishi uchun tartibni aslo buzmang.'),
  ('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f', 'Hammasi joyida ✔️', 'Ba’zan hech narsani uddalay olmayotgandek his qilasiz. Ammo uning toza kiyimlari va to‘q qorniga qarang. Siz hammasini a’lo darajada uddalayapsiz!'),
  ('4f713889-2b51-4db7-8d5d-7ee8676555a4', 'AJOYIB 4 OY! 🎉', 'Ishona olasizmi? Mana, roppa-rosa 120 kundirki, bu sehrli yo‘lni birga bosib o‘tyapsiz! Chaqaloq fotosessiyasi bilan bu lahzani unutilmas xotiraga aylantiring!'),
  ('8d072236-96cb-4886-b83d-b2d8d6523abb', 'Ortga nazar tashlang 📈', 'Ilk kunlardagi qo‘rquvlaringizni eslang. Endi esa naqadar tajribali onaga aylanganingizga qarang. O‘zingiz bilan faxrlaning!'),
  ('cfb7b283-3b96-44ef-84b8-0eca1ae74852', '4 oylik faxrni his eting.  🥂', 'Bugun kechqurun chaqaloq uxlagach, turmush o‘rtog‘ingiz bilan jamoaviy g‘alabangizni nishonlashni unutmang!'),
  ('df219eb3-fe33-48d7-81df-3e2d39df4620', 'Siz juda ko‘p narsaga qodirsiz! 💖', 'Ko‘zgudagi charchagan ko‘zlaringizga qarab, tabassum qiling. Siz hech qanday qo‘llanmasiz bir mo‘jizani ulg‘aytiryapsiz!'),
  ('f8c399ff-a31e-4e77-a55d-5aab198bafaa', 'Sayr vaqti ⛅', 'Ob-havo va kiyim vositasi yordamida ob-havoga eng mos kiyimlar uyg‘unligini bir necha soniyada toping va toza havodan bahramand bo‘ling.'),
  ('fb3d810e-9135-4194-bb47-9ce9e588d70c', 'Dadaning yelkalari 👨‍👧', 'Bugun kechqurun chaqaloqni xonada ko‘tarib aylantirish va kekirtirib, gazini chiqarish butunlay dadasining zimmasida.'),
  ('09081d67-84a7-403e-b876-3cc97106eb52', 'Ushlash ustasi 🧸', 'Osib qo‘yilgan o‘yinchoqlarni endi aniq ushlayaptimi? Uning harakat ko‘nikmalari ajoyib rivojlanmoqda. Bu urinishlarini mehr bilan kuzating va rag‘batlantiring.'),
  ('15b0ec22-2156-4080-ad64-7a588de85fc5', 'Uy tartibsiz deb stressga tushmang. 🌪️', 'Siz uchun eng muhimi mukammal uy emas, balki sog‘lom va baxtli chaqaloqdir. Xotirjam bo‘ling.'),
  ('e8181dea-ccff-4ba2-ae33-93fa07ea8c28', 'Savolingiz bormi? 🤖', 'Uyqu, ovqatlanish yoki qorin dam bo‘lishi masalasida boshingiz qotdimi? Forumlarda vaqt yo‘qotmang, shunchaki Anacan AI’ga yozing va aniq, ilmiy asoslangan javob oling.'),
  ('0fa7eced-c60c-4055-8da1-5df4e54ec1ce', 'Men gapiryapman! 🗣️', 'Ba-ba, Ma-ma kabi bo‘g‘inlarni aytyaptimi? Rivojlanish kuzatuvchisini oching, nutq rivojidagi bu katta sakrashni qayd eting va u bilan ko‘proq suhbatlashing.'),
  ('19b9faef-1d59-42d5-bcb0-12290f627a1f', 'Sukunat lahzasi ☕', 'Xonadagi tartibsizlik hech qayerga qochib ketmaydi. Bola o‘zi mustaqil o‘ynayotganida, siz shunchaki qahvangizni iching va xonadagi osoyishtalikdan zavqlaning.'),
  ('65cb82a7-67e0-48b5-80b8-74e806b2980e', 'O‘zingizga xos ertak 🪄', 'Bugun kechqurun Aqlli ertaklarga kiring, u uchun maxsus ertak yarating va o‘qib bering.'),
  ('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62', 'Qorni bilan uzoqroq yotyaptimi?  🐢', 'Mushaklari kundan-kunga kuchayib bormoqda. Oldiga rangli o‘yinchoq qo‘yib, bu jarayonni yanada qiziqarli qiling.'),
  ('431c0c7a-2968-4edd-9882-df9a926adf72', 'So‘lak sharsharasi 🤤', 'Yoqasi tez-tez ho‘l bo‘la boshladimi? Qo‘l ostingizda albatta silikon tish qashlagich saqlang.'),
  ('5817fca0-3cbb-4276-a47d-9383c042597d', 'Detsibel nazorati 🤫', 'Bola uxlaganda uydagi har bir tovush sizni cho‘chitadimi? Tovush o‘lchagichni faollashtiring va xonaning akustikasini tekshirib, uning uyqusini asrang.'),
  ('0140116f-1e50-4656-93a0-277a1645b1ba', 'Hissiy yengillik 📝', 'Og‘ir kun bo‘ldimi? Kayfiyat kundaligiga barcha charchoq va his-tuyg‘ularingizni ochiqchasiga yozing.'),
  ('1f632261-0ec6-4f1f-be74-71aaaaf4c706', 'Zaxiralar tugayaptimi? 🛒', 'Taglik yoki nam salfetkalar tugayaptimi? Esingizdan chiqmasidan Xaridlar ro‘yxatiga qo‘shing, shunda turmush o‘rtog‘ingizning telefoniga bildirishnoma boradi.'),
  ('f2dc5d57-91a4-45de-b81b-0b2998a8593b', 'Quvnoq qahqahalar 😂', 'Sizning yoqimli harakatlaringizga ovoz chiqarib kulib javob beryaptimi? Bu kulgini albatta videoga yozib oling.'),
  ('1c68be5f-505e-4c46-be58-571a7196e98d', 'Tajribangizni ulashing 💬', '“Faqat men shundaymanmi?” deb o‘ylayapsizmi? Anacan hamjamiyatiga qo‘shiling va o‘xshash hislarni boshdan kechirayotgan onalar bilan dardlashing.'),
  ('4b6ccde7-7cce-4142-8822-fa952592f465', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalayaptimi, qulog‘ini tortyaptimi? Haddan tashqari charchab, injiqlik qilishini kutmang — darhol xonani qorong‘ilatib, kechki uyqu tartibini boshlang.'),
  ('7b3662bc-d715-468b-a32f-326c023ef66e', 'Ag‘darilish chempioni 🤸‍♂️', 'Chalqancha yotgan holatdan qorniga, qornidan esa chalqanchasiga ag‘darilishga urinyaptimi? Uni karavotda aslo yolg‘iz qoldirmang va bu serharakat davrdan zavqlaning.'),
  ('0aded6bb-b0fa-4cac-b297-4311bcd7f798', 'Hamma narsaga ulgurishingiz shart emas. 🌸', 'Sizga mehr bilan boqayotgan chaqalog‘ingiz uchun siz dunyodagi eng mukammal insonsiz.'),
  ('658bd674-cc84-4d51-8a7e-822b9255b9d7', 'Yangi ertak kashfiyoti 📖', 'Bu kechani boshqacha o‘tkazing. Aqlli ertaklarda suvosti olamini kashf etishga otlangan suv parisi haqida hikoya yarating va xonani sehrga to‘ldiring.'),
  ('b8b57297-f4b4-4473-87af-9acfeee74dd3', 'Qorni och emas, unda nega yig‘layapti? 🧩', 'Nima qilsangiz ham tinchimayaptimi? Taxmin qilishni bas qiling: yig‘i ovozini Yig‘i tahliliga eshittiring va muammo nimada ekanini darhol aniqlang.'),
  ('9ce62e84-5124-421b-bdd6-3fa7c590aa1a', 'Yangi ranglar olami 👀', 'U endi ranglarni yanada yorqin va aniqroq ko‘radi. Unga qarama-qarshi ranglardagi o‘yinchoqlarni ko‘rsating.'),
  ('b42e7a75-4fab-45bd-89fe-f334b8181757', 'O‘zingizni unutmang 🍲', 'Chaqaloq to‘ygan bo‘lsa, endi navbat sizda. Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan quvvatbaxsh tamaddini tanlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('cf65b961-f3be-4509-9af3-0b6c17f757e7', 'Ota-bola vaqti 🫂', 'Otalar ham chaqaloq bilan jismoniy yaqinlik o‘rnatishi kerak. Kechqurun ularni birga qoldiring — ular o‘zaro mehr rishtalarini mustahkamlasin, siz esa dam oling.'),
  ('0ed5ca13-9d93-489b-99e3-a198862dd467', 'Uyqu regressiyasimi? 🤖', 'Tunda uyg‘onishlar birdan ko‘paydimi? Balki bu rivojlanishdagi biologik sakrashdir. Anacan AI’dan 4-5 oylikdagi uyqu regressiyasi haqida ma’lumot oling.'),
  ('450e1ee4-0ee2-4568-acc9-22677b87903d', 'U menga qarayapti! 📸', 'Xonaning qayerida bo‘lsangiz ham, u sizni ko‘zlari bilan kuzatadi.'),
  ('696eaa28-30b3-4a02-87e3-0cd00d185f07', 'Atigi 10 daqiqa 🛀', 'Chaqaloq uxlab qoldi, siz ham sukunatga erishdingiz. Idish yuvish mashinasini bo‘shatish o‘rniga iliq dush qabul qilib, 10 daqiqa suvning ovozini tinglang.'),
  ('27873a53-69de-4c27-a20c-c15256739b9a', 'Biz bir jamoamiz! 🌟', 'Tunda uyg‘onishlardan charchadingizmi? Otasini uyg‘otishdan tortinmang. Jamoa bo‘lish — yukni mehr bilan bo‘lishishdir.'),
  ('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c', 'Ob-havo kutilmagan hodisalarga boy ⛅', 'Sayrga chiqqanda ob-havoga aldanib, chaqaloqni sovuq qotirmang. Ob-havo va kiyim bo‘yicha yordamchi orqali tashqaridagi sharoitga eng mos qarorni osonlik bilan qabul qiling.'),
  ('82b46290-c3d6-4ad5-8d94-600e0311ba33', 'Quchoqqa olishni talab qilyaptimi? 🛋️', 'Quchog‘ingizdan tushishni istamayaptimi? Bu erkalik emas, unga sizning hidingiz kerak. Uni mahkam quchoqlang, bu kunlar tez o‘tib ketadi.'),
  ('4a91e0c3-a4cb-4e5c-b68a-474b7d153369', 'Tagliklarni sanashda davom eting! 🧷', 'Har kuni almashtirilgan tagliklar sonini Anacan-da qayd etib, chaqalog‘ingiz yetarlicha oziqlanayotganiga ishonch hosil qiling.'),
  ('4d4822a8-2d08-4775-b1d8-71202fa22509', 'Ona uchun quvvat 🔋', 'Chaqaloq emganida siz ham kaloriya sarflaysiz. Hoziroq Sog‘lom retseptlar bo‘limidan sutni ko‘paytirishga yordam beradigan, ammo yengil sho‘rva retseptini sinab ko‘ring.'),
  ('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7', 'Bo‘y va vazn o‘sishini kuzatamiz! 📏', 'Rivojlanish kuzatuvchisi bo‘limida so‘nggi ko‘rsatkichlarni yangilang, chaqalog‘ingizning sog‘lom rivojlanish grafigiga qarab faxrlaning.'),
  ('648c9f9b-15f6-49e6-933c-3da395b58c88', 'Tirishqoq urinishlar 🐢', 'Qorni bilan yotganida oldinga siljishga urinib, jahli chiqyaptimi? U allaqachon harakatlanishni xohlayapti! O‘yinchoqlar yordamida uni oldinga intilishga undang.'),
  ('903de81c-9443-4b1e-8662-d8cbed1ca54e', 'Tish qashlagichlar ishga tushadi! 💧', 'U hamma narsani og‘ziga solishni xohlaydi. Xavfsizlik va rivojlanish haqida ko‘proq bilish uchun Bloglarni ko‘rib chiqing.'),
  ('9dd94bee-b76e-43ec-94c9-51937e10ad6e', 'Bugun uy yig‘ishtirilmaydi 🛑', 'Charchadingizmi? Juftingizga ayting. Bugun uy taomi ham, uy yig‘ishtirish ham yo‘q. Bugun shunchaki onaning dam olish kuni!'),
  ('132a3a1b-1001-4fec-a775-7883117a6988', 'Rejim qanday ketyapti? 📈', 'Ovqatlanish nazorati va uyqu taymeriga qarab, so‘nggi kunlar statistikasini tahlil qiling.'),
  ('61f15500-8617-42e1-b833-c482f6ae935c', 'O‘yinchoqlarini tez-tez yerga tashlayaptimi? 🧸', 'Shu tariqa u sabab-oqibat bog‘liqligini o‘rganmoqda. Yangi o‘yinchoqlar uchun Tavsiya etilgan mahsulotlarni ko‘rishingiz mumkin.'),
  ('92d9f590-3160-4e15-966d-3ee82f9db1d0', 'Og‘iz orqali kashf etish 🦷', 'U hamma narsani, ayniqsa o‘z barmoqlarini tinmay chaynayaptimi? Tish chiqishini kuzatish vositasi ogohlantirmoqda! Toza tishlash halqalarini tayyorlash vaqti keldi.'),
  ('02654c5d-e5dc-4168-b20f-e995771e2a24', 'Hamjihatlik kuchi 💬', 'Bugun kechqurun Anacan hamjamiyatiga kiring va siz bilan bir xil bosqichdagi onalar bilan rivojlanish jarayonini baham ko‘rib, muhokama qiling.'),
  ('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3', 'O‘zingiz bilan faxrlaning 👏', 'Xonaga nazar solib, qancha yo‘l bosib o‘tganingizni o‘ylang. Dastlabki haftalardagi qo‘rquv endi chinakam onalik ishonchiga aylandi. Siz ajoyibsiz!'),
  ('50a6a489-6955-49c4-9f2c-e768f813dd17', 'Oyoq barmoqlari og‘izda 👣', 'U oyoqlarini kashf etib, ularni og‘ziga olib borishga urinmoqda! Bu kulgili va ajoyib rivojlanish lahzasini albatta suratga olib, yaqinlaringizga yuboring.'),
  ('25015c8c-0ca6-43bc-a465-c8490ee6d808', 'U sizni juda yaxshi ko‘radi! 🥰', 'Emayotganda yoki ovqatlanayotganda ko‘zlarini sizdan uzmay qaraydimi? U yuzingizdagi chiziqlarni o‘rganmoqda va sizni juda yaxshi ko‘radi!'),
  ('565cbb4c-39dd-4c69-980a-b02d63f6cdb4', 'Biroz yengillik 🛋️', 'Og‘ir kundan so‘ng Kayfiyat kundaligiga his-tuyg‘ularingizni yozib qo‘ying. Unutmang, yozish va dardingizni to‘kib solish — eng yaxshi bepul psixologdir.'),
  ('f0338702-1ba5-495b-840d-9ad790085c24', 'Cho‘ntagingizdagi pediatr 🤖', 'Chaqaloq najasining rangi o‘zgarganmi yoki tanasida mayda toshma bormi? Vahimaga tushishdan oldin Anacan AI’ga yozing va buning asosiy sabablarini bilib oling.'),
  ('5996a5e8-c639-4f34-8f02-ccaebf8a96eb', 'Qo‘llar ishga kirishdi 👐', 'U bir vaqtning o‘zida ikki qo‘li bilan katta buyumlarni ushlashga harakat qilyaptimi? Bu tafsilotni rivojlanish kuzatuvchisida qayd eting va unga yumshoq to‘p berib, sinab ko‘ring.'),
  ('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee', 'Sovqotyaptimi yoki issiqmi? ⛅', 'Chaqaloqni qanday kiyintirish doim muammomi? Ob-havo va kiyim vositasi uni necha qavat kiyintirish kerakligini sizga aniq aytib bersin. Boshingizni qotirmang.'),
  ('a1ca42ca-05ed-42dc-af4a-99af31043623', 'Ona ovozining sehri 🎶', 'Hech bir ilova ona allasining o‘rnini bosa olmaydi. Bu oqshom uni shunchaki bag‘ringizga bosing va eng sevimli allasini ohista kuylang.'),
  ('b0613bc2-510c-4582-8829-fd09f1ed2898', 'Taomlarga qiziqish? 🍽️', 'Siz ovqatlanayotganingizda likopchangiz va og‘zingizga diqqat bilan qarayaptimi? Qattiq oziq-ovqatlarga (qo‘shimcha ovqatga) qiziqish asta-sekin boshlanmoqda!'),
  ('cd2a678b-9234-4910-9725-95b0b9e3443e', 'Kechki tartib — uyqu poyezdiga chipta.🚂', 'Iliq vanna, massaj va xonani qorong‘ilashtirish... Bu tartibni aslo buzmang.'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'Kundalik yugur-yugurda tushlikni oyoqda yemang. 🥑', 'Foydali retseptlardan foydalanib, oson salat tayyorlang va o‘tirib, maza qilib yeng.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'Qahqaha tushgan kadr 📸', 'U kundan-kunga ko‘proq kulmoqda! Chaqaloq fotosessiyasini oching va bugungi salbiy kayfiyatni tarqatib yuboradigan quvnoq qahqaha tushgan kadrni oling.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'Yupatuvchi ertak 🪄', 'Aqlli ertaklarda 5-oyga tayyorlanayotgan mitti qahramon haqida hikoya yarating va xonaga yoqimli muhit baxsh eting.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', '5-OY SARI! 🎂', 'Diqqat! Atigi 10 kundan keyin katta kun — 5-oy to‘ladi! Maxsus tort buyurtma qilishni yoki bayram mavzusini rejalashtirishni unutmagandirsiz? Tayyorgarlikni hozirdanoq boshlang!'),
  ('1a9e3246-5c48-4c5d-9be8-b35243065267', 'Uyda nima yetishmayapti? 🛒', 'Shampun tugadimi yoki bolalar yog‘imi? O‘ylab o‘tirishga hojat yo‘q. Xaridlar ro‘yxatini to‘ldiring, qolganini hamkoringizga qo‘yib bering.'),
  ('6e836ffa-475e-446a-bc5a-eddbd0eeeec4', 'Shovqinlarni filtrlang 🤫', 'Ko‘chadan kelayotgan shovqinlar chuqur uyquga xalaqit beradi. Shovqin o‘lchagichni tekshiring va zarur bo‘lsa, fon sifatida oq shovqindan foydalaning.'),
  ('e31b222d-5c34-45e3-b291-c3f8c8989d13', 'Go‘zal va haqiqiy 💇‍♀️', 'Ko‘ylagingizda dog‘, sochlaringiz esa to‘zg‘igan bo‘lishi mumkin. Ammo chaqalog‘ingiz uchun siz dunyodagi eng go‘zal insonsiz. O‘zingizni ayblamang.'),
  ('29aebaa9-a1ae-4a00-8854-a771800bf560', 'Tanaffuslarni tartibga solamiz. 🍼', 'Ovqatlanish va uyg‘oq qolish vaqtlarini Ovqatlanishni nazorat qilish vositasi yordamida kuzatib, mukammal kun tartibini yarating.'),
  ('3942c763-be60-481b-bb4e-1a53687a8d34', 'Dadaning fidoyiligi 💖', 'U ham kun bo‘yi ishladi, ammo endi dadalik navbati. Chaqaloqni qanchalik ehtiyotkorlik bilan uxlatayotganini chetdan kuzatib, baxtli onlardan zavqlaning.'),
  ('3cd07d9d-076c-4523-8ba1-47b8737d6bbf', 'Men shu yerdaman! 👀', 'Uni xonaning bir burchagidan ismi bilan chaqiring. U darhol ovoz kelgan tomonga o‘girilib, sizga qaraganini ko‘rasiz. Eshitish qobiliyati va diqqati a’lo darajada!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'Chaqaloq tinchimayapti, siz esa juda qattiq charchadingizmi?  🛑', 'Chaqaloqni beshikka xavfsiz tarzda yotqizib, 5 daqiqaga boshqa xonaga chiqing. Siz ham nafas rostlashga haqlisiz.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'Ovoz analizatori 😭', 'Xonaga qaytdingiz, u esa yana yig‘layapti. Tushkunlikka tushmang! Uning ovozini darhol Yig‘i tahliliga eshittiring va ehtiyojini to‘g‘ri aniqlab, uni tinchlantiring.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'Qo‘llari og‘zidan chiqmayapti 🦷', 'Hamma narsani qattiq chaynayaptimi? Iliq va toza matolar uning milklarini tinchlantiradi.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'Tun qahramonlari 🦸‍♀️', 'Tunda uyg‘onishlar sizni holdan toydirayotganini bilamiz. Kayfiyat kundaligiga charchog‘ingizni yozing va juftingizdan sizni qo‘llab-quvvatlashini so‘rang.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'Meni ko‘ryapsizmi? 🧸', 'O‘yinchoqning yarmini ko‘rpa ostiga yashiring. Chaqaloq uni qidirib topadimi? Bu predmetlar ko‘rinmasa ham mavjudligini anglash yo‘lidagi ajoyib rivojlanish bosqichidir!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'Sayr qilish shart ⛅', 'Ob-havo va kiyim vositasini tekshiring, chaqaloqni kiyintiring va parkda kamida 20 daqiqa sayr qiling. Bu sizga ham, unga ham juda zarur.'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'Shifokordek aqlli 🤖', 'Bolangizning harakatlarida sizga g‘alati tuyulgan biror narsa bormi? Internetda qo‘rqinchli xabarlarni o‘qish o‘rniga, Anacan AI’dan aniq javob oling.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'Dadaning allasi 👨‍🍼', 'Hamkor rejimida bildirishnomalar turmush o‘rtog‘ingizga yuborilsin. Bu kecha chaqaloqni uxlatish uchun ertak va allani u aytsin. Siz esa kuzatib turing.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'Tonggi konsert 🎶', 'Sizga qarab, yuzida katta tabassum bilan turli bo‘g‘inlarni talaffuz qilmoqda. Ayni paytda u xonadagi eng go‘zal tonggi konsertni namoyish etmoqda, diqqat bilan tinglang!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'Uyqu rejimi haqida ikkilanyapsizmi? 🤖', '5-oyga yaqin uyqudagi o‘zgarishlar haqidagi savollaringizni Anacan hamjamiyatida yozing va boshqa onalardan yordam oling.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'Shovqin nazorati 🤫', 'To‘rtinchi oyning oxirida uxlab qolish ba’zan qiyinlashadi. Shovqin o‘lchagichni yoqing, shovqin chegarasini tekshiring va xonani albatta qorong‘i qiling.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'Siz eng yaxshisiz! 💖', 'Mukammal inson bo‘lmaydi, ammo chaqalog‘ingiz uchun eng yaxshi ona aynan sizsiz.'),
  ('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9', 'Energiya to‘plang 🍲', 'Siz sog‘lom bo‘lsangiz, u ham sog‘lom bo‘ladi. Sog‘lom retseptlar orasidan sizga kuch beradigan mazali keks retseptini tanlang va uni qahva bilan maza qilib yeng.'),
  ('9ee15fcc-d37a-4d63-9556-1032868e91e8', 'TORTGA BUYURTMA BERDINGIZMI? 🎂', 'Atigi 5 kundan keyin kichkintoyingiz 5 oylik bo‘ladi! 5-oy mavzusidagi maxsus tort yoki kiyim uchun buyurtmangizni hoziroq rasmiylashtiring!'),
  ('d25e75e7-0029-43b9-b1e7-c401d6b9ca28', 'Aqlli hikoya ustasi 🪄', 'Bugun kechqurun Aqlli ertaklarda kichkintoyingiz 5 oylikkacha qanchalik tez ulg‘aygani haqida o‘ziga xos, ta’sirli hikoya yarating.'),
  ('6a21d9c4-96ab-4453-9d5f-d8979016e2cc', 'Mustaqillik sari 🤸‍♂️', 'U endi chalqancha yotgan holatdan qorniga bemalol ag‘darila olyaptimi? Mushaklari tez rivojlanmoqda. Erkin harakatlanishi uchun uni muntazam ravishda gilam ustiga yotqizing.'),
  ('c057830d-8790-40ec-a09d-53a252d3ee15', 'O‘zingizni ayblamang 🛑', 'Bugun sabringiz tugab, ovozingizni balandlatdingizmi? O‘zingizni yomon his qilmang. Siz charchamaydigan robot emassiz. Ertaga yana urinib ko‘rasiz.'),
  ('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a', 'Siz yolg‘iz emassiz 💬', 'Anacan hamjamiyatidagi boshqa 5 oylik chaqaloqlarning onalari nimalar yozayotganini ko‘rib chiqing. Har bir uyda bir xil tartibsizlik, bir xil uyqusizlik va bir xil mehr bor!'),
  ('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5', 'Uyqu belgilarini o''tkazib yubormang 🥱', 'Agar chaqaloq ko''zlarini bir nuqtaga tikib qolsa, darhol barcha ishni chetga suring. Uyqu vaqtini o''tkazib yubormasdan, uni yotog''iga olib boring.'),
  ('0ecae509-0e89-4406-80e4-d01161b92754', 'Tish qashlagich — najotkor 🦷', 'Hamma narsani tishlashga urinyaptimi? Sovutilgan silikon tish qashlagichlar uning milklarini tezda tinchlantiradi.'),
  ('60bbb8df-cb46-4930-8422-5f0c6fa7daad', 'Sizni taniyman! 🥰', 'Xonaga kirganingizda, u sizga o''zgacha, yanada hayajonli va boshqalardan farqli tarzda jilmayadimi? Ha, u sizni hammadan ajratib taniydi va hidingizni juda yaxshi ko''radi!'),
  ('adbfecc6-7186-41fe-a870-83cf6809ec00', 'O''zingizga vaqt ajrating 🛋️', 'Chaqaloq uxlaganida uy ishlariga emas, o''zingizga vaqt ajrating. Xona biroz tartibsiz qolishi mumkin, ammo kuchingizni tiklashingiz juda muhim.'),
  ('ba61a641-e703-4b01-b161-601cf36add7a', 'Tabiat sehri ⛅', 'Chaqaloq juda bezovtami? Hech bir o''yinchoq yordam bermayaptimi? Ob-havo va uning kiyimini tekshirib, darhol ochiq havoga olib chiqing. Tabiat — eng yaxshi tinchlantiruvchi.'),
  ('e97550d4-794b-4a9e-94da-881338077d81', 'Nega yana yig''layapti? 😭', 'Sababini topa olmayotgan yig''i xurujlari odamni holdan toydiradi. O''zingizni qiynamang, Yig''ini tahlil qilish funksiyasidan foydalaning va uning ovozidagi yashirin xabarni aniqlang.'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', 'Ona uchun 10 daqiqa ☕', 'Uydagi tartibsizlik hech qayerga qochib ketmaydi. Chaqaloq uxlaganda darhol ishga kirishmang. O‘zingizga bir finjon issiq qahva quyib, 10 daqiqa shunchaki devorga qarab o‘tiring.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'Qo‘ldan qo‘lga kashfiyot 🧸', 'O‘yinchoqni bir qo‘lidan ikkinchisiga o‘tkaza oladimi? Bu miya yarimsharlari a’lo darajada ishlayotganidan dalolat! Rivojlanish kuzatuvchisida bu muhim ko‘nikmani qayd eting.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'Kayfiyatingiz bilan o‘rtoqlashing 📝', 'Bugun juda charchadingizmi yoki o‘zingizni tetik his qilyapsizmi? Kayfiyat kundaligiga his-tuyg‘ularingizni samimiy yozing. Ichingizdagilarni yozib, yengil tortasiz.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'Ovozli hikoyalar 🪄', 'Keling, bugun kechqurun xonaga o‘zgacha sehr bag‘ishlaymiz. Aqlli ertaklarda Oyga uchgan jasur mushuk haqida hikoya yaratib, uyquga tayyorgarlikni maroqli qiling.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'Tabiiy tinchlantiruvchi ⛅', 'Chaqaloq juda bezovta bo‘lib, uyda qolishni istamayaptimi? Ob-havo va kiyimini tekshirib, darhol parkka chiqing. Toza havo ikkalangiz uchun ham eng yaxshi dori.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'Qo‘liga tushgan hamma narsani og‘ziga soladimi? 🤤', 'Bu uning dunyoni o‘rganish usuli. Faqat atrofidagi buyumlar toza va xavfsiz bo‘lishiga e’tibor bering.'),
  ('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed', 'Onalar kuchi 🤖', 'Atrofga nazar soling va shu 5 oygacha qanday yetib kelganingiz bilan faxrlaning. Agar biror xavotiringiz bo‘lsa, Anacan AI’ga yozing va yordam oling.'),
  ('792511a4-1d02-4324-a33c-59bacedb4645', 'YUBILEYGA 1 KUN QOLDI! 🎈', 'Ertaga katta kun! 5 oylik bayram uchun tort tayyormi, kiyimlar dazmollanganmi? Chaqaloq fotosessiyasi vositasini ochib, sinov suratlarini hozirdanoq oling!'),
  ('af763c83-7a14-4218-b3c2-49cdc7255b18', 'Juftingiz bilan dildan suhbatlashing 🥂', 'Bugun kechqurun juftingiz bilan ilk kunlarni eslab, birga kuling. Siz juda katta yo‘lni bosib o‘tdingiz!'),
  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', 'ROSA 5 OY! 🎉', 'Ishonish qiyin! Siz roppa-rosa 150 kundan, ya’ni to‘liq 5 oydan beri bir jamoa bo‘lib bu mo‘jizani ulg‘aytiryapsiz. Chaqaloq fotosessiyasi yordamida ushbu alohida kunni hoziroq abadiylashtiring!'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'O‘zingizni olqishlang 👏', 'Barcha qaydlaringiz va rivojlanish jadvallaringizga yana bir bor nazar soling. Chaqalog‘ingiz qanchalik ulg‘ayganini, siz esa naqadar tajribali bo‘lib qolganingizni ko‘ring!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'G‘alaba oqshomi 🪄', 'Bugun kechqurun Aqlli ertaklarda mehrga to‘la bir hikoyani tinglang va juftingiz bilan bir jamoa sifatida erishgan g‘alabangizni nishonlang!'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'Yig‘i kodi 😭', 'Ertalabki injiqlik ochlikdanmi yoki tish chiqishidanmi? Taxmin qilmang, ovozini Yig‘i tahliliga eshittirib, unga nima kerakligini darhol aniqlang.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'Sabringiz tugayaptimi?  👨‍👧', 'Bu oqshom chaqaloq bilan to‘liq dadasi shug‘ullansin, siz esa quloqchinlaringizni taqib, dam oling.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'Biz bir jamoamiz! 🌟', 'O‘zingizni yolg‘iz va tushunilmagandek his qilyapsizmi? Chuqur nafas oling. Siz bu notinch kunlarning eng kuchli qahramonisiz va hammasini a’lo darajada uddalayapsiz.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'Mutlaq sukunat 🤫', 'Uxlab qolish qiyinlashdimi? Ovoz o‘lchagich yordamida xonadagi detsibel darajasini tekshiring. Televizor ovozini o‘chiring va xonani butunlay qorong‘ilating.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'Milklari qichishyaptimi? 🦷', 'Barmoqlari doimo og‘zida va so‘lagi ko‘p oqyaptimi? Sovutilgan tish qashlagichlardan foydalanish vaqti keldi.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'O‘zingizni unutmang 🥑', 'Chaqaloqni to‘ydiraman deb, o‘zingiz och qoldingizmi? Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan to‘yimli taomni tanlang.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'Tungi alla 🎶', 'Hech bir ovoz ona ona ovozidek taskin bermaydi. Bu oqshom uni shunchaki bag‘ringizga bosing va sevimli allasini mayin ovozda ayting.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'Xonaning hamma joyi o‘yinchoqmi? 🌪️', 'Xonaning hamma joyi o‘yinchoqmi? Uyingiz tartibsiz deb asabiylashmang. Siz ajoyib onasiz, siz uchun eng muhimi — chaqalog‘ingiz, tozalik emas.'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'Boshqa onalar nima qilyapti? 💬', 'Xavotirdamisiz? Anacan hamjamiyatiga qo‘shiling. U yerdagi onalar ham xuddi shunday uyqusizlik va muammolarni boshdan kechirayotganini ko‘rish sizga taskin beradi.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'Zaxiralar tugayapti 🛒', 'Taglik yoki bolalar yog‘i tugadimi? Mayda-chuyda narsalar bilan miyangizni band qilmang, xaridlar ro‘yxatiga yozib qo‘ying, turmush o‘rtog‘ingiz kelayotganda olib kelsin.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'Savolingiz bormi? 🤖', 'Chaqaloqning rivojlanishi haqida xayolingizda minglab savollar bormi? Forumlarni soatlab o‘qish o‘rniga Anacan AI’ga yozing va qisqa, ilmiy asoslangan javob oling.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'Kunlik tagliklar sonini kuzatamiz. 🧷', 'Chaqaloq yetarlicha oziqlanayotganiga ishonch hosil qilish va ovqat hazm qilish tizimini nazorat qilish uchun Anacan’da har bir taglik almashtirilishini qayd eting.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'Birdamlik kuchi 🛋️', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash va o‘zingizni bir jamoa deb his qilish yukni yarmiga kamaytiradi.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'O‘zingiz bilan faxrlaning 👏', 'Ortga nazar tashlab, ilk haftalarda qanchalik qo‘rqqaningizni eslang. Endi esa hammasini naqadar mohirlik bilan uddalayapsiz! Siz ajoyibsiz!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'Mazali kashfiyotlarga oz qoldi! 🥦', 'Qo‘shimcha ovqat yeyishni boshlaydigan chaqaloqlar uchun Retseptlar bo‘limidagi ilk pyure g‘oyalarini o‘qib, kelasi oyga tayyorgarlik ko‘ring.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'Cho‘ntagingizdagi pediatr 🤖', 'Uyqu tartibi to‘satdan o‘zgardimi? Vahimaga tushishdan avval Anacan AI’dan 5 oylikdagi uyqu regressiyasi haqida ma’lumot va maslahat oling.'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'Mustaqil ag‘darilish 🤸‍♂️', 'U chalqancha yotgan holatdan qorniga bemalol ag‘dariladimi? Mushaklarini erkin harakatlantira olishi uchun uni keng gilam ustiga yotqizing.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'Vaqtni to‘xtatish 📸', 'U shunchalik tez ulg‘aymoqdaki... U uxlayotganida shirin va osoyishta yuz ifodasini Chaqaloq fotosessiyasi yordamida suratga olib, xotira sifatida saqlang.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'Tunda uyg‘onishlarni tartibga solamiz. 😴', 'Har safar uyg‘onganida chiroqlarni yoqmang. Anacan taymeri yordamida ovqatlantirib, Oq shovqinlar bilan yana uxlatib qo‘ying.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'Bugun uy tozalanmaydi 🛑', 'Charchadingizmi? Juftingizga ayting. Bugun uyda ovqat tayyorlanmaydi, uy tozalanmaydi. Bugun onaning dam olish va qahva ichish kuni!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'Men bilan gaplashing! 🗣️', 'Sizni diqqat bilan tinglab, turli tovushlar chiqaryaptimi? U siz bilan haqiqiy muloqot qilyapti. Uning tovushlariga javob qaytaring va bu muloqotni qo‘llab-quvvatlang.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'O‘tirishga ilk urinishlar 🪑', 'Uni suyab o‘tqazganingizda boshi va belini tikroq tutyaptimi? Bu mushaklari mustahkamlanayotganini ko‘rsatadi. Qisqa muddatli, suyab o‘tqazish mashqlarini boshlang.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'To‘rt devor orasidan chiqish ☕', 'Uyda siqilib ketdingizmi? Bolalar aravachasi bilan bemalol kirish mumkin bo‘lgan eng yaqin kafeni toping va boshqa muhitda qahva iching.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalab, bir nuqtaga tikilib qolsa, injiqlik qilishini kutmang. Darhol xonani qorong‘ilatib, uyqu tartibini boshlang.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'Qorni ochmi yoki charchaganmi? 🧩', 'Nima qilsangiz ham tinchimayaptimi? Balki u shunchaki juda charchagandir. Ishonch hosil qilish uchun Yig‘i tahlilidan foydalanib, yig‘i ortidagi sababni aniqlang.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'Shovqin nazorati 🤫', 'Uxlab qolganida to‘satdan chiqqan tovushlar uni uyg‘otadimi? Shovqin o‘lchagich yordamida xonadagi shovqin darajasini nazorat qiling.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'Onaning quvvati 🔋', 'Kun yarmidayoq quvvatingiz tugab qolyaptimi? Sog‘lom retseptlar orasidan sut miqdorini qo‘llab-quvvatlaydigan va sizga tetiklik beradigan smuzi retseptini ko‘ring.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'Musiqaning kuchi 🎶', 'Kechga yaqin boshlanadigan sababsiz yig‘ini sekin ohangdagi klassik musiqa yoki oq shovqin yordamida to‘xtatib ko‘ring.'),
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80', 'Ob-havo kutilmagan hodisalarga boy ⛅', 'Sayrga chiqqanda ob-havoga aldanib, chaqaloqni shamollatib qo‘ymang. Ob-havo va kiyim bo‘yicha yordamchi orqali tashqaridagi sharoitga mos qaror qabul qiling.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'Ta’mlarga qiziqyaptimi? 🍽️', 'Siz ovqatlanayotganingizda ko‘zini likopchangizdan uzmayaptimi? Qo‘shimcha ovqatga tayyorlik belgilari paydo bo‘la boshlagan. Ammo hozircha shoshilmang, 6-oygacha kuting.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'Tajriba almashish 💬', 'Farzandingizning yangi bir harakati sizni hayratda qoldirdimi? Anacan Hamjamiyatiga qo‘shiling va bu kashfiyotni boshqa onalar bilan muhokama qiling.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'Ertakning oxiri yo‘q 📖', 'Bugun kechqurun Aqlli ertaklarga ajoyib topshiriq bering: kamalak ustida uxlayotgan pari haqida hikoya.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'Siz yetarlisiz! 💖', 'Bugun hamma ish teskarisiga ketdimi? O‘zingizni ayblamang. Siz robotmisiz? Yo‘q. His-tuyg‘ularingizni qabul qiling, o‘zingizni kechiring va tabassum qiling.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'Yarim yoshga yaqinlashmoqda 📈', 'Ishonasizmi? 6-oy tugashiga juda oz qoldi! Rivojlanish kuzatuvchisini oching va shu oygacha bosib o‘tgan ajoyib yo‘lingizni faxr bilan ko‘zdan kechiring.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'Navbatni topshiring 🛋️', 'Farzandingiz uxlaganda siz ham yotib uxlashni istasangiz, uydagi boshqa ishlarni juftingizga topshiring.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'Xotira tumanligi 📝', 'Unutuvchanlik tug‘ruqdan keyingi davrning bir qismidir. Hech narsa yodingizdan chiqmasligi uchun xaridlar ro‘yxatidan faol foydalaning.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'Ko‘zgudagi do‘st 👀', 'Uni ko‘zgu oldiga olib boring. O‘z aksiga qarab, zavqlanib ovoz chiqarishi uning aqliy rivojlanishi uchun ajoyib va qiziqarli mashg‘ulotdir.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'Jamoaviy suhbat 🥂', 'Kayfiyat kundaligini oching, bugungi salbiy hislarni ortda qoldiring va juftingiz bilan bir jamoa bo‘lishdan zavqlaning.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'Tish qashlagich izlaymiz 🦷', 'So‘lak ajralishi va milk qichishishi kuchayadi. Toza tishlash halqalari sizning eng yaqin yordamchingizdir.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'Meni ko‘ryapsanmi? 🧸', 'O‘yinchoqni ko‘rpa ostiga yashiring. Chaqaloq uni izlab topadimi? Bu narsalar ko‘zdan g‘oyib bo‘lsa ham mavjudligini anglash yo‘lidagi ajoyib rivojlanish bosqichidir!'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'Tungi qahramon — dada 🦸‍♂️', 'Dastlabki oylarning eng yaxshi qoidasi: alla aytish navbat bilan bo‘lishi kerak! Bu oqshom chaqaloq dadasining bag‘rida, siz esa dam olasiz.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'Sayr vaqti 🌳', 'Uni aravachasiga yotqizing va atigi 15 daqiqaga bo‘lsa ham toza havoga chiqing. Toza havo ikkalangizga ham kerak.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'Tonggi konsert 🎶', 'Sizga qarab, yuzida katta tabassum bilan yangi tovushlar chiqaradi. Hozir u xonadagi eng ajoyib konsertni namoyish etmoqda, diqqat bilan tinglang!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'Uyqu poydevori ⏱️', 'Iliq vanna, massaj va xonani qorong‘ilashtirish... Tunalaringiz osoyishta o‘tishi uchun uyqu tartibini aslo buzmang.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('ddef2887-0bec-40c8-91a4-05edb188b86b'::uuid, 'Shifokordek aqlli 🤖', 'Internetda qo‘rqinchli xabarlarni o‘qish o‘rniga, qo‘shimcha ovqatga o‘tish haqidagi savollaringizni Anacan AI’ga bering va ko‘nglingizni xotirjam qiling.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'Aqlli sukunat 🤫', 'Uxlab qolayotganida to‘satdan chiqqan tovushlar uni uyg‘otib yuboradimi? Ovoz o‘lchagich yordamida xonadagi detsibel darajasini nazorat qiling.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'Mantiqqa zid kiyimlar 👗', 'Ba’zan juda yupqa, ba’zan esa juda issiq kiyintirasizmi? Ikkilanmang. Ob-havo va kiyimni tekshirib, ishonch bilan kiyintiring.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'Ona uchun ziyofat 🥑', 'Kundalik yugur-yugurda tushlikni oyoqda yemang. Sog‘lom retseptlardan foydalanib, oson salat tayyorlang, o‘tirib, maza qilib yeng.'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'O‘zingizni asrang 🛋️', 'Chaqaloq uxlaganda uy ishlariga emas, o‘zingizga vaqt ajrating. Xona yig‘ishtirilmay qolishi mumkin, ammo siz kuchingizni tiklab olishingiz kerak.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'O‘yinchoqlarini yerga tashlab, kuzatyaptimi? 🎯', 'Bu tortishish kuchi va sabab-oqibat bog‘liqligini o‘rganish uchun! Sabr bilan o‘yinchoqni qaytarib bering.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'Siz yolg‘iz emassiz 💬', 'Xavotirdamisiz? Anacan hamjamiyatiga qo‘shilib, savolingizni bering. Ishoning, barcha onalar o‘xshash yo‘llardan o‘tadi.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'Qo‘shimcha ovqatga tayyorgarlik 🥣', '6-oyga ham oz qoldi. Dastlabki pyurelar haqida bilishni xohlaysizmi? Anacan AI’dan qo‘shimcha ovqatga o‘tish bo‘yicha asosiy ma’lumotlarni so‘rang.'),
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776', 'Hamjihatlik kuchi 🥂', 'Bugun kechqurun juftingiz bilan ushbu katta bosqichgacha qanday yetib kelganingiz haqida suhbatlashing. Siz bir jamoa bo‘lib ajoyib ishni uddaladingiz.'),
  ('c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f', 'YARIM YOSHGA 10 KUN QOLDI! 🎂', 'Tayyorgarlik ko‘ring! Roppa-rosa 10 kundan so‘ng kichkintoyingiz 6 oylik – ya’ni yarim yoshga to‘ladi! Yarim yosh tortini buyurtma qilish va maxsus kiyim tanlashning ayni vaqti!'),
  ('3259939c-e2bd-4126-abc3-d15439051dda', 'Toza havoning kuchi 🌳', 'Bola juda bezovta bo‘lsa, uni darhol ochiq havoga olib chiqing. Toza havo bunday bezovtalikni bosishning eng oddiy va samarali vositasidir.'),
  ('382370f5-d970-4100-b0bc-f8460c0758ae', 'Ushlash ustasi 👐', 'U bir vaqtning o‘zida ikki qo‘li bilan katta buyumlarni ushlashga harakat qilyaptimi? Yumshoq to‘p berib, sinab ko‘ring.'),
  ('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d', 'Ovozli hikoyalar 🪄', 'Bugun kechqurun Aqlli ertaklarda 6 oylik bo‘lib ulg‘aygan jasur ritsar haqida hikoya yarating.'),
  ('0e21a1c5-4a15-41e9-abfe-8342adaebb92', 'Mukammallik bo‘lmaydi 🛑', 'Bugun sabringiz chidamadi, balki jahlingiz ham chiqdimi? O‘zingizni ayblamang. Kayfiyat kundaligiga his-tuyg‘ularingizni yozib, yengil torting.'),
  ('31e88909-0b90-49e0-8727-857efb6836f3', 'Dadaning allasi 👨‍🍼', 'Hamkor rejimida bildirishnomalar juftingizga yuborilsin. Bu kecha chaqaloqni uxlatish uchun allani u aytsin.'),
  ('a24757f2-97fa-405f-9959-e4c715aa8ed8', 'Sizni qidiryapman! 👀', 'Xonadan chiqqaningizda u sizni ko‘zlari bilan qidirib, yig‘laydimi? Unda asta-sekin ajralish xavotiri boshlanayotgan bo‘lishi mumkin. Unga o‘zini xavfsiz his qilishiga yordam bering.'),
  ('989db48b-e318-47e6-9019-f4f957b60d59', 'Sababini topa olmaydigan yig‘i xurujlari odamni holdan toydiradi. 😭', 'O‘zingizni qiynamang, Yig‘i tahlilidan foydalaning va uning ovozidagi xabarni aniqlang.'),
  ('a6d43603-e416-4760-8a3f-176e42bf2dc7', 'Ku-ku o‘yini uning eng sevimli o‘yini! 🙈', 'Yuzingizni qo‘llaringiz bilan berkitib, so‘ng oching va uning qanday quvonishini kuzating. Bu kabi ko‘proq o‘yinlar haqida Bloglar bo‘limidan bilib oling.'),
  ('a85c19d5-09d8-4302-9d52-6f63acdaebee', 'Tungi alla 🎶', 'Hech bir ovoz ona ovozidek tinchlantira olmaydi. Bugun kechqurun uni bag‘ringizga bosib, sekin kuylang.'),
  ('2fc6e816-81b8-4662-85f5-ea7fd4e748a8', 'Ona uchun 10 daqiqa ☕', 'Xonadagi tartibsizlik hech qayerga qochib ketmaydi. U uxlaganda darhol ishga kirishmang. O‘zingizga qahva quyib, 10 daqiqa shunchaki dam oling.'),
  ('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df', 'Shovqinlarni filtrlang 🤫', 'Ko‘chadan kelayotgan shovqinlar chuqur uyquga xalaqit beradi. Shovqin o‘lchagichga qarang va kerak bo‘lsa, oq shovqindan foydalaning.'),
  ('9bb7f096-5daa-4e1c-9f5e-688698945f7a', 'Tishlari chiqyaptimi? 🦷', 'Pastki milkida og‘riq yoki shish bormi? Ilk tishlar 6-oyga borib ko‘rinishi mumkin.'),
  ('2ecd0a8e-2817-4551-98e0-4276739c7da9', 'Biz bir jamoamiz! 💖', '6 oy davomida uyqusiz tunlarda bir-biringizni qo‘llab-quvvatladingiz. Kayfiyat kundaligini oching va bu jamoaviy mehnat uchun juftingizga minnatdorlik bildiring.'),
  ('ce877206-0633-48d8-aa8f-9241cfab27c3', 'Qo‘shimcha ovqat uchun stul 🪑', 'Ovqatlantirish stulini sotib olishni o‘ylayapsizmi? Tavsiya etilgan mahsulotlar bo‘limida ergonomik va oson tozalanadigan stullarni ko‘rib chiqing.'),
  ('e6e852b1-bfb4-4197-aa7b-70b6b2367f30', 'YARIM YOSHGA 5 KUN QOLDI! 🎈', 'Yarim yoshga atigi 5 kun qoldi! Tortga buyurtmangiz tayyormi? Chaqaloq fotosessiyasi vositasida 6 oylik uchun maxsus ramkalarni hozirdanoq tanlab, rejalashtiring.'),
  ('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd', 'Yangi ertak kashfiyoti 📖', 'Bu tunni o‘zgacha o‘tkazamiz. Aqlli ertaklarda maxsus hikoya yarating va xonani sehrga to‘ldiring.'),
  ('9d58451e-ede3-4a05-ba21-dd4e0b7f4086', 'Har kungi taglik holatini kuzatamiz. 🧷', 'Qo‘shimcha ovqatga o‘tishdan oldin ovqat hazm qilish tizimi yaxshi ishlayotganiga ishonch hosil qilish uchun Anacan-da har bir taglik almashtirilishini qayd eting.'),
  ('edc6faba-a997-408a-a40b-e590a39a3721', 'Men o‘tiraman! 🪑', 'Chaqalog‘ingiz ko‘mak bilan o‘tirganda o‘zini ancha ishonchli his qilyaptimi? Uni yostiqlar bilan suyab, qisqa muddat o‘tirishga undang.'),
  ('081951c6-0b7d-4045-b641-a4716f751a3d', 'Dadaning yelkasi 👨‍👧', 'Sabringiz tugayaptimi? Hamkor rejimini yoqing. Bugun kechqurun bola bilan to‘liq dadasi shug‘ullansin.'),
  ('b099b3d8-9148-450c-8795-4ab16ea72b2c', 'Yana savollaringiz bormi? 🤖', 'Avval qaysi sabzavot pyuresidan boshlash kerak? – Sizni o‘ylantirayotgan shu va boshqa savollarni Anacan AI-ga berib, aniq ma’lumot oling.'),
  ('e3aafd70-c5f0-4254-ba79-e24f4dca3567', 'So‘lak sharsharasi 🤤', 'Kiyimining yoqasi tez-tez ho‘l bo‘lyaptimi? Silikon tishlagichlarni tayyorlab qo‘ying.'),
  ('34eb8ef4-b7a5-4969-916d-abfccb27c775', 'Detsibel nazorati 🤫', 'Bola uxlayotganda uydagi har bir tovush sizni cho‘chityaptimi? Shovqin o‘lchagichni yoqing va xona akustikasini tekshiring.'),
  ('da48ef6d-1a19-4a32-9bdc-d912779edf22', 'Tartibsiz uy, baxtli bola 🌪️', 'Xonaning hamma joyi o‘yinchoqmi? Tozalikdan ko‘ra, u bilan quvnoq o‘tkazgan 10 daqiqangiz muhimroq.'),
  ('ec6f8334-a2ec-4274-9ce3-07c0a3276622', 'Mustaqil ag‘darilish 🤸‍♂️', 'Chalqancha yotgan holatdan qorniga, qornidan esa chalqanchasiga ag‘darilishni to‘liq o‘zlashtirdimi? Bu yutuqni rivojlanish kuzatuvchisida qayd eting!'),
  ('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalayaptimi? Uyqusi kelib injiqlashishini kutmang, darhol xonani qorong‘ilatib, kechki uyqu tartibini boshlang.'),
  ('a9165256-d8d7-431e-ac72-e7ef065f4e1f', 'Ona uchun quvvat 🍲', 'Ertangi muhim sana uchun sizga quvvat kerak. Foydali retseptlardan to‘yimli tamaddi tanlab, dam oling.'),
  ('febb037e-33e6-4760-bc42-cae9b6c70a8a', 'SO‘NGGI TAYYORGARLIKLAR! 📸', 'Ertaga katta kun! Yarim yoshga atalgan tort tayyormi? Chaqaloq fotosessiyasi uchun eng chiroyli kiyimlarni tayyorlab qo‘ying, ertaga ko‘p suratga tushamiz!'),
  ('1ac47b8c-1167-4ac1-a522-104b832c25b0', 'ROSA 6 OY! YARIM YOSH! 🎉', 'Tabriklaymiz! Siz bu mo‘jizani roppa-rosa 180 kundan beri ulg‘aytiryapsiz. Hoziroq Chaqaloq fotosessiyasida ushbu alohida kunga bag‘ishlangan surat yarating va Anacan hamjamiyatida ulashing!'),
  ('788697fe-7a57-4c4c-a3dc-514298d952ed', 'O‘zingizni olqishlang 👏', 'Barcha qaydlaringizni boshidan ko‘rib chiqing. Chaqalog‘ingiz qanchalik ulg‘ayganini, siz esa qanchalik tajribali bo‘lib qolganingizni ko‘ring! Siz ajoyib jamoasiz.'),
  ('7f7b88ee-089c-4ccc-9849-c2f4117d4833', 'G‘alaba oqshomi 🥂', 'Bugun kechqurun chaqaloq uxlagach, juftingiz bilan yuzma-yuz o‘tiring. Ushbu 180 kunlik yo‘l bilan faxrlaning va bir-biringizni quchoqlang!'),
  ('7d616a8c-c926-4291-9221-42ee50e15fd5', 'Yangi bosqich: Qo‘shimcha ovqat! 🥣', '6 oy to‘ldi! Endi sabzavot pyurelari bilan tanishish vaqti keldi. Allergiyani tekshirish uchun 3 kunlik sinov qoidasi haqida Anacan AI-dan ma’lumot oling.'),
  ('936424c3-1b30-4fc1-924e-920162d0d5bd', 'Mutlaq sukunat 🤫', 'Uxlab qolish qiyinlashdimi? Shovqin o‘lchagich yordamida xonadagi detsibel darajasini tekshiring va xonani butunlay qorong‘ilating.'),
  ('e0613a64-c64f-491d-8c87-72276f72849e', 'Dog‘ tushgan kiyimlar 👗', 'Qo‘shimcha ovqat — hamma joy iflos bo‘lishi degani. Bundan asabiylashmang, silikon ko‘krakpechlardan foydalaning va bu kulgili onlardan zavq oling.'),
  ('6dad4f0a-8c98-4797-a95f-50aab81d4662', 'Ob-havo syurprizi ⛅', 'Sayrga chiqqaningizda ob-havoga aldanib, sovqotib qolmang. Ob-havo va kiyim yordamchisi bilan tashqaridagi sharoitga mos qaror qabul qiling.'),
  ('affd2ecc-89d1-4649-8b63-63dfe9a1ced9', 'Sizni izlayapman! 👀', 'Xonadan chiqishingiz bilan yig‘lay boshlaydimi? Ayriliq xavotiri aynan shu davrda to‘liq shakllanadi. U shunchaki qaytib kelmasligingizdan qo‘rqadi. Ovozingiz bilan unga xotirjamlik va ishonch bering.'),
  ('c4e8f9e9-c94b-41fc-a23a-61a8c7026386', 'Ovqat hazm qilish tizimidagi o‘zgarishlar. 🧷', 'Qo‘shimcha ovqat bilan birga najas chiqarishi ham o‘zgaradi. Har safar taglikni almashtirganingizni Anacan-da qayd etib, holatni kuzatib boring.'),
  ('3bd59fce-abbd-4e13-ab2d-4379b5c89cac', 'Pyureni yemay, og‘zidan tupurib tashlayaptimi?', 'O‘zingizni eplolmayotgandek his qilmang. Bu uning uchun mutlaqo yangi tajriba, sabrli bo‘ling.'),
  ('48005ac4-750b-4fca-b0cd-2711d3eb3c21', 'Ovozli hikoyalar 🪄', 'Bugun kechqurun Aqlli ertaklarda ertak yaratib, kunni maroqli yakunlang.'),
  ('ae1cbea0-aaaf-49ff-9518-967813809e3b', 'Milklar qichishyaptimi? 🦷', 'Qo‘shimcha ovqat berish davrida tish chiqishi bilan bog‘liq og‘riqlar ham kuchayishi mumkin. Shifokor tavsiyasi bilan tish uchun geldan foydalaning.'),
  ('4beff801-d69f-40c0-bed1-2e8938edb5f2', 'Boshqa onalar nima qilishadi? 💬', 'Farzandingiz qovoq pyuresini yoqtirmaydimi? Anacan hamjamiyatiga qo‘shiling, onalarning tajribasi va turli retseptlar bilan tanishing.'),
  ('7df7f58f-05e6-4afb-aa2c-73438e6504d4', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalab, bir nuqtaga tikilib qolsa, injiqlik boshlanishini kutmang. Darhol xonani qorong‘ilatib, uyquga tayyorgarlik tartibini boshlang.'),
  ('8afe4995-9e98-44a1-a9cc-5c970d87a396', 'Tayanchsiz o‘tirishga urinishlar 🪑', 'Endi yostiqlarga kamroq suyanayaptimi? Juda tez orada hech qanday tayanchsiz o‘tira oladi!'),
  ('34c92908-0941-4c15-a946-75240f0ea7f7', 'Kayfiyatingizni ulashing 📝', 'Bugun juda charchadingizmi? Kayfiyat kundaligiga his-tuyg‘ularingizni samimiy yozing. Ko‘nglingizdagilarni yozib, yengil tortasiz.'),
  ('cd45d0d2-bf31-47be-adf8-84c3b1895339', 'Biror joyi og‘riyaptimi yoki qorni dam bo‘lganmi? 😭', 'Qo‘shimcha ovqatga o‘tish ich qotishi yoki qorin dam bo‘lishiga olib kelishi mumkin. Nima qilsangiz ham tinchimasa, Yig‘i tahlilidan foydalanib, yig‘i ortidagi sababni aniqlang.'),
  ('e67730b8-4981-4bba-b868-fe6cf9b7e3da', 'Zaxiralar tugayapti 🛒', 'Pyure uchun yangi sabzavotlar kerakmi? Xaridlar ro‘yxatiga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda yangi mahsulotlar olib kelsin.'),
  ('1f9cc7dc-a0b4-41a4-983b-794c5917ee08', 'Qo‘ldan qo‘lga kashfiyot 🧸', 'O‘yinchoqni bir qo‘lidan ikkinchisiga bemalol o‘tkazyaptimi? Demak, miya yarimsharlari juda yaxshi ishlayapti. Unga turli tuzilishga ega buyumlar bering.'),
  ('298934a2-9d12-42b8-8c9c-6098d3709ab4', 'Suhbatlar uzaymoqda! 🗣️', 'Da-da-da, ba-ba-ba tovushlari uyda aks-sado bermoqda. Uning nutqiy rivojlanishi haqida ko‘proq o‘qish uchun Bloglar bo‘limiga kiring.'),
  ('89ff16e6-d11a-4deb-ae4f-1ba03e76271d', 'Tunning qahramoni — dada 🦸‍♂️', 'Ilk oylarning eng yaxshi qoidasi: alla aytish navbat bilan bo‘lishi kerak! Bu oqshom chaqaloq dadasining bag‘rida, siz esa dam olasiz.'),
  ('5378180a-aa43-4728-9384-08bbcf8838ee', 'Men bilan gaplashing! 🗣️', '«Ba-ba», «Ma-ma» kabi bo‘g‘inlarni aniqroq aytyaptimi? Uning ovoziga javob qaytaring va bu muloqotni qo‘llab-quvvatlang.'),
  ('a4be80bb-cd06-42ba-b875-78d5a32af3ba', 'Juftlik suhbati 🛋️', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash yukni yengillashtiradi.'),
  ('efa880a4-37d0-4521-93db-df2495a01243', 'O‘zingiz bilan faxrlaning 👏', 'Ortga nazar solib, ilk haftalarda qanchalik qo‘rqqaningizni eslang. Endi esa siz pyure tayyorlash bo‘yicha haqiqiy mohir onasiz!'),
  ('5be2b9be-dabd-44b8-93f3-30aaaab56ccf', 'Tungi alla 🎶', 'Hech bir ovoz ona ovozidek tinchlantira olmaydi. Bu oqshom uni shunchaki bag‘ringizga bosib, mayin ovozda alla ayting.'),
  ('98621899-f977-46d0-ba01-3a49123c5aef', 'Emaklashga urinishlar! 🐢', 'U qorni bilan yotib aylanayaptimi, orqaga qarab sudralayaptimi yoki tizzalariga turishga urinayaptimi? Faol rivojlanishning ushbu lahzalarini darhol Chaqaloq albomiga qo‘shing.'),
  ('f5a121b8-a795-4ca6-87d9-f17351b40bec', 'Rivojlanish borasida xavotirlaringiz bormi? 🤖', 'Chaqalog‘im hali ham emaklamayapti, bu normalmi? – shu va boshqa savollaringizni Anacan AI’ga yo‘llab, mutaxassis javobini oling.'),
  ('6f0575b2-9379-4dca-bf05-d518a93aead1', 'Qaysi ko‘krak bilan emizganingizni unutdingizmi? 🤱', 'Taymerda o‘ng yoki chap ko‘krakni belgilang, Anacan sizning o‘rningizga hammasini eslab qolsin!'),
  ('a134dfa9-2e73-4246-a281-0577e4411534', 'Ovqat bilan o‘ynashiga ruxsat bering! 🥦', 'Ovqatga tegsin, uni ezsin va o‘rgansin. Bu yoqimli va biroz betartib lahzalarni Chaqaloq fotosessiyasi yordamida suratga olib, xotira sifatida saqlang!'),
  ('d9470e5a-6317-45d8-9bd1-419a7827e3e6', 'Tungi uyg‘onishlarni tartibga solamiz. 😴', 'Har uyg‘onganida chiroqlarni yoqmang. Anacan taymeri yordamida emizing va Oq shovqinlar bilan yana uxlatib qo‘ying.'),
  ('07efb31a-2639-41f8-b1c7-f3807d010a8f', 'Vaqtni to‘xtatish 📸', 'U shunchalik tez ulg‘aymoqdaki... Uxlayotganida uning yoqimli, sokin chehra chiziqlarini Chaqaloq fotosessiyasi yordamida suratga olib, xotira sifatida saqlang.'),
  ('7deb7b07-a963-4605-b27c-7714e980157d', 'Savolingiz bormi? 🤖', 'Qo‘shimcha ovqat va suv berish haqida xayolingizda minglab savollar bormi? Anacan AI-ga yozing va pediatrlarning aniq tavsiyalarini oling.'),
  ('ab8df92e-4241-44fb-8ac7-10559ea60a6f', 'Sizni taniyman! 🥰', 'Uyga notanish odam kelganda sizning bag‘ringizga kiradimi? Xavotir olmang, u shunchaki yaqinlarini begonalardan ajrata oladi. Bu sog‘lom aqliy rivojlanish belgisidir.'),
  ('0e6fe355-3307-4562-8e24-f479625f3ff6', 'Toza havo har ikkingizga ham foydali. 🌳', 'Eng yaqin bog‘ni tanlang va kuningizni maroqli o‘tkazing.'),
  ('4085929a-ec71-4c5c-a693-62bb796910ba', 'Ob-havoga mos kelmaydigan kiyimlar 👗', 'Ba’zan juda yengil, ba’zan esa juda issiq kiyintirib yuboryapsizmi? Ikkilanmang. Ob-havo va kiyimni tekshirib, ishonch bilan kiyintiring.'),
  ('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba', 'Aqlli sukunat 🤫', 'Uxlab qolganida to‘satdan chiqqan tovushlar uni uyg‘otadimi? Shovqin o‘lchagich yordamida xonadagi detsibel darajasini nazorat qiling.'),
  ('3e7220fc-a665-4ed2-8b95-f202d84e92a8', 'O‘zim ushlayman! 🧸', 'Osib qo‘yilgan o‘yinchoqlarga aniq qo‘l uzatyaptimi? Ko‘z va qo‘l muvofiqligi rivojlanmoqda. Uni turli rangdagi buyumlar bilan rag‘batlantiring.'),
  ('747238a1-853b-4e40-a51e-30b2b6d818ac', 'O‘zingizni aybdor his qilmang 💖', 'Farzandingizga kam vaqt ajratyapman, deb o‘ylaysizmi? Quvonch bilan mazmunli o‘tkazilgan 10 daqiqa stressli 1 soatdan qadrliroqdir.'),
  ('a8ca5021-abaf-413e-abe5-95d715e5127d', 'Chuqur uyquga tayyorgarlik 🛀', 'Iliq vanna, mayin massaj va xonani qorong‘ilashtirish... Uyqu tartibi — oltin qoida.'),
  ('17a57fd8-a4e1-4a40-b13f-cad6191dae2a', 'Yangi ta’m kashfiyotlari! 🍎', 'Bugun qaysi meva yoki sabzavotni sinab ko‘rasiz? Ilhom olish uchun qo‘shimcha ovqatni boshlayotgan chaqaloqlar uchun retseptlarni albatta ko‘rib chiqing.'),
  ('b98f5eb2-8b81-4c72-8526-61cc728e9e49', 'Ertakning oxiri yo‘q 📖', 'Bugun oqshom Aqlli ertaklarda jasur va aqlli bolaning hikoyasini yarating.'),
  ('baf623af-022a-4483-b233-e77e915f194b', 'Katta ishtaha 🥣', 'Pyureni endi mazza qilib yeyaptimi? U ulg‘aymoqda!'),
  ('0ced9920-5225-4ffc-81ba-de83e31f1bd2', 'Tonggi konsert 🎶', 'Sizga qarab, turli bo‘g‘inlarni o‘ylab topadi. U hozir xonadagi eng go‘zal tonggi konsertni bermoqda, diqqat bilan tinglang!'),
  ('db243270-0483-44d0-9aef-b63565c06a9e', 'Shifokordek aqlli 🤖', 'Qattiq ovqatga o‘tgandan keyin najasi o‘zgardimi? Vahimaga tushish o‘rniga, bu normal holat yoki yo‘qligini Anacan AI’dan so‘rang.'),
  ('f06a8dcb-51df-4b58-a9ac-01e5154e736a', 'Uyqu poydevori ⏱️', 'Iliq vanna, massaj va xonani qorong‘ilashtirish... Kechalaringiz osoyishta o‘tishi uchun uyqu tartibini aslo buzmang.'),
  ('19aba970-f2bf-4842-9b69-4aed1781aeec', 'Pastga qarang! 👣', 'U allaqachon oyoq barmoqlarini kashf etib, og‘ziga sola boshladi! Bu kulgili lahzani albatta kuzating va uning rivojlanishidan zavqlaning.'),
  ('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d', 'Ona suti hali ham asosiy ozuqa! 🍼', 'Qo‘shimcha ovqat berilayotganiga qaramay, ovqatlantirish taymerini ishga tushirib, chaqaloqning kunlik sutga bo‘lgan ehtiyoji qondirilayotganiga ishonch hosil qiling.'),
  ('c2924eec-8b24-41b0-b28a-f63497f548c2', 'Tajriba almashish 💬', 'Qo‘shimcha ovqat retseptlarini izlayapsizmi? Sog‘lom retseptlar bo‘limiga kiring va ulardan foydalaning.'),
  ('2d910805-1ce0-44fc-88f6-f3f6dfe16cea', 'Emaklashga urinishlar ko‘paymoqda! 🐢', 'U qorni bilan yotgan holda orqaga emaklayaptimi yoki tizzalariga turishga harakat qilyaptimi? Ushbu faol rivojlanish lahzalarini Chaqaloq albomida abadiylashtiring.'),
  ('8f5769c4-aeb4-4cd1-acf0-052c7e0df753', 'Aqlli ertak vaqti 🪄', 'Aqlli ertaklar bo‘limida bu kecha uchun maxsus hikoya yarating.'),
  ('f175db80-862d-40e7-9aed-5b0a0c4423e3', 'Suv ichish odatini shakllantiramiz. 💧', 'Qo‘shimcha ovqat bilan birga suv taklif qilishni unutmang.'),
  ('14f79c92-38f1-4965-a9d0-fbcb8e236840', 'So‘lak oqishi avj oldimi? 🤤', 'Kiyimining yoqasi bir necha soniyada ho‘l bo‘lib qolyaptimi? Milklar tish chiqishiga tayyorlanyapti. Silikon ko‘krakpechlardan foydalaning.'),
  ('173f7149-2567-449f-9693-a462d1148849', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dildan suhbatlashing. Bir-biringizni qo‘llab-quvvatlash yukni yengillashtiradi.'),
  ('1af66eec-0d7d-4dcd-9326-d4155d237a55', 'Begonalardan qo‘rqish boshlandimi? 🙈', 'Sizni ko‘rmay qolganda yoki notanish odamni ko‘rganda yig‘lasa, bu rivojlanishning bir qismidir. Bu haqda Anacan AI bilan maslahatlashing.'),
  ('23068177-6d18-4649-91f5-5ac9ecb37933', 'Tezkor javoblar 🤖', 'Biror narsa sizni o‘ylantiryaptimi? Forumlarni soatlab o‘qish o‘rniga, savolingizni Anacan AI’ga berib, tezkor javob oling.'),
  ('52b2efdc-0a49-4bfa-8a7e-21a3342254cb', 'Harakat qilyapti! 🤸‍♂️', 'Qorni bilan yotganda oldinga siljishga urinadi. Mushaklari kundan-kunga mustahkamlanmoqda — oldiga o‘yinchoq qo‘yib, uni rag‘batlantiring.'),
  ('97716c97-1bb3-4784-acfc-a5f0354d1864', 'Musiqaning kuchi 🎶', 'Kechga yaqin boshlanadigan sababsiz yig‘ini sekin tempdagi klassik musiqa yordamida tinchlantirishga urinib ko‘ring.'),
  ('21fef948-0fab-41a2-932d-5efc89cc4b78', 'Uyqu poydevori ⏱️', 'To‘g‘ri uyqu tartibini yo‘lga qo‘yish juda muhim. Kechalaringiz osoyishta o‘tishi uchun bu tartibni aslo buzmang.'),
  ('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352', '200 KUNGA 1 KUN QOLDI! 🎂', 'Ertaga chaqalog‘ingiz 200 kunlik bo‘ladi! Bu ulkan va ajoyib sanani qanday nishonlashni o‘ylab ko‘rdingizmi? Tayyorgarlikni boshlang!'),
  ('76b44761-7bef-4f9c-b984-97e78f4d78cb', 'Hammasi joyida ✔️', 'Ba’zan qo‘lingizdan hech narsa kelmayotgandek tuyuladi. Ammo uning toza kiyimlariga va to‘q qorniga qarang. Siz hammasini a’lo darajada uddalayapsiz!'),
  ('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2', 'Ortga qarang 📈', 'Ilk kunlardagi qo‘rquvlaringizni eslang. Endi esa qo‘shimcha ovqat berishni puxta o‘zlashtirgan onaga aylanganingizga qarang. O‘zingiz bilan faxrlaning!'),
  ('87133947-89a5-414b-a6d4-637285ff301e', 'AJOYIB 200 KUN! 🎉', 'Ishona olasizmi? Mana, roppa-rosa 200 kundirki, bu sehrli yo‘lni birga bosib kelyapsiz! Chaqaloq fotosessiyasida ushbu lahzani maxsus stiker bilan yanada bayramona qiling va Hamjamiyatda ulashing!'),
  ('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169', '200 kunlik quvonch va faxrni his eting. 🥂', 'Bugun kechqurun chaqaloq uxlagach, turmush o‘rtog‘ingiz bilan jamoaviy mehnatingizning bu katta g‘alabasini nishonlashni unutmang!'),
  ('05e938a0-adb4-413b-992b-19bbd78f0925', 'YUBILEYGA TAYYORGARLIK! 🎂', 'Atigi 9 kundan keyin 7 oylik bo‘ladi! Bu oy uchun o‘zgacha mavzu yoki maxsus tort haqida o‘ylab ko‘rdingizmi? Oxirgi kunga qolib ketmasligi uchun tayyorgarlikni hozirdanoq boshlang.'),
  ('9c5c6958-af17-4420-aa80-95cd295c8995', 'Qo‘llar erkin 👐', 'Qorni bilan yotganida bir qo‘li bilan o‘yinchoqqa cho‘zilib, ikkinchi qo‘liga tayanadimi? Mushaklar muvozanati tobora mukammallashmoqda!'),
  ('acd2495b-eae5-4005-8f31-3fdfdc4738aa', 'Dadasining navbati 👨‍👧', 'Bugun onalik navbatchiligini qisqa muddatga juftingizga topshiring. Ular birga o‘ynasin, siz esa oyoqlaringizni uzatib, bemalol dam oling.'),
  ('094a764e-f3f1-4dd1-8a87-04126b16323f', 'O‘zingizni unutmang 🍲', 'U pyuresini yedi, siz-chi? Quvvatingizni tiklash uchun yaxshi ovqatlanishingiz kerak. Bugun o‘zingiz uchun to‘yimli taom buyurtma qiling.'),
  ('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6', 'Seni taniyman 👀', 'Uyga mehmon kelganida sizga yopishib olib, unga begonasirab qaraydimi? Ayriliq xavotiri boshlanmoqda. U shunchaki onasining yonida o‘zini xavfsiz his qiladi, bunga hurmat bilan yondashing.'),
  ('740c028d-4797-4507-a894-816747e5301d', 'O‘zingizga xos ertak 🪄', 'Bugun kechqurun Aqlli ertaklar vositasiga yoqimli bir mavzu beramiz: “Osmondan tushgan eng shirin yulduzning hikoyasi”. Xonada faqat shu ertakning ovozi yangrasin.'),
  ('1175cce8-f8b8-4dcc-a8b2-c864d9349ad6', '7 OYLIK BO‘LISHIGA ATIGI 3 KUN! 🎂', 'Tortga buyurtma berildimi? Kiyimlar tanlandimi? 7 oylik bo‘lishiga juda oz qoldi. Bu quvonchli sanani uyda kichik fotosessiya bilan nishonlashni rejalashtiring!'),
  ('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf', 'Ko‘zgudagi do‘st 👀', 'Uni ko‘zgu oldiga olib boring. O‘z aksiga hayrat bilan qarab, kulishini kuzatish juda yoqimli va tinchlantiruvchi mashg‘ulotdir.'),
  ('f998fac0-0a6b-42d2-b200-7a956f147c9a', 'Dadasining navbati 👨‍🍼', 'Bu oqshom chaqaloqni cho‘miltirish va uxlashga tayyorlash dadasining vazifasi.'),
  ('06cfdff1-da31-4945-b562-a0c104f43d15', 'Sizni eshityapman 🗣️', 'U sizni diqqat bilan tinglab, o‘xshash bo‘g‘inlarni (ma-ma, ba-ba) aytishga harakat qilyaptimi? U siz bilan gaplashyapti! Unga ko‘p tabassum qilib javob bering.'),
  ('83caf542-3e86-4833-b9bd-0befb15b04d7', 'Sayr vaqti 🌳', 'Uni aravachasiga o‘tqazing va 20 daqiqaga toza havoga chiqing. Bu ikkingizga ham juda yaxshi ta’sir qiladi.'),
  ('fca627d6-9c72-4d82-999a-3b13347100cd', 'Tun qahramoni 🦸‍♂️', 'Tunda uyg‘onishlardan charchadingizmi? Dadasini uyg‘otishdan tortinmang. Jamoa bo‘lish — yukni teng bo‘lishish demakdir.'),
  ('21f7df85-0fd1-4e90-a27b-52045487116f', 'Tunda uyg‘onishlar 🌙', 'Tish chiqishi arafasida chaqaloq tunda tez-tez uyg‘ona boshladimi? Sabrli bo‘ling, milklaridagi og‘riq uni bezovta qilmoqda. Yonida ekaningizni his qildiring.'),
  ('3ad2c870-178d-449f-aabd-6c01acacefd8', 'Emaklashga urinishlar 🐢', 'Tizzalariga turib, oldinga-orqaga tebranyaptimi? U emaklashga tayyorlanyapti!'),
  ('b80481ba-8798-458c-83d8-f359b3802548', 'Sokinlik lahzasi ☕', 'Xonadagi tartibsizlik hech qayerga qochib ketmaydi. Bola o‘zi o‘ynab turganida darhol tozalashga shoshilmang. Divanga o‘tirib, 10 daqiqa hech narsa qilmang.'),
  ('104420b5-a415-4abb-81d8-7f7b520d18bd', 'Milklarni tekshirish 🦷', 'Hamma narsani qattiq tishlayaptimi va og‘zidan so‘lak oqyaptimi? Tish chiqishini kuzatish bo‘limida jarayonni nazorat qiling. Sovituvchi tishlash halqalari shu kunlarda haqiqiy najotkor bo‘ladi.'),
  ('c9c8946d-7797-4bd6-8476-9f649f770a6e', 'Biz bir jamoamiz! 💪', 'O‘zingizni yolg‘iz va charchagan his qilyapsizmi? Chuqur nafas oling. Siz va turmush o‘rtog‘ingiz ushbu og‘ir kunlarning eng kuchli qahramonlarisiz.'),
  ('f8790842-2782-419a-aaaa-3c8c1fc497de', 'Ob-havo va kiyim ⛅', 'Ko‘chaga chiqishda bolaga nima kiydirish haqida bosh qotirmang. Ob-havo va kiyim vositasiga qarab, bir necha soniya ichida eng mos kiyimlar uyg‘unligini toping va toza havoga chiqing.'),
  ('125f59de-0644-435e-8593-de05b7cc7065', 'Ovozli ertaklar 🎶', 'Hech bir ilova ona allasining o‘rnini bosa olmaydi. Bugun kechqurun uni bag‘ringizga bosib, eng sevimli allasini ohista kuylang.'),
  ('63093c63-3ea0-4bb2-90bb-318617d51b7e', 'Pyure festivali 🥣', 'Yuzi, burni, hatto sochlari ham ovqatga belandimi? Jahlingiz chiqishining o‘rniga, bu yoqimli lahzani Chaqaloq fotosessiyasi bilan abadiylashtiring.'),
  ('9ff73499-a2bd-41b7-96fa-1ec2d780279f', 'O‘zingizni aybdor his qilmang 💖', 'Farzandingizga kam vaqt ajratyapman yoki uy ishlariga ulgurmayapman, deb o‘ylaysizmi? O‘zingizni ayblashni bas qiling. Siz hammasini a’lo darajada uddalayapsiz.'),
  ('5cafdda5-c60b-4328-9530-450093ed8026', 'Mutlaq sukunat 🤫', 'Uxlab qolishga qiynalyaptimi? Xonani butunlay qorong‘ilashtiring va shovqinni bartaraf eting. Qorong‘ilik va sukunat — uning yaxshi uxlashiga eng yaqin yordamchilar.'),
  ('8ee71700-bb17-4782-940b-c0fc02328f1a', 'Najasining rangi o‘zgardimi? 💩', 'Qo‘shimcha ovqatga o‘tilganda najasning turli rangda bo‘lishi odatiy hol. Ammo xavotirga tushgan bo‘lsangiz, buning sababini Anacan AI’dan bilib oling.'),
  ('9240cd01-c58e-42aa-be44-a4d2ac461bc2', 'Holdan toyish — odatiy hol 🔋', 'Sabringiz tugay boshlaganda o‘zingizni yomon ona deb his qilmang. Bunday charchoq tabiiy.'),
  ('4335b974-a43c-4ba3-b369-2006056301ed', 'Tayanchsiz o‘tirish 🪑', 'Endi yostiqlarga ehtiyoj sezmay, qisqa vaqt bo‘lsa ham tik o‘tira olyaptimi? Uni ehtiyotlab, xavfsizligini ta’minlagan holda mushaklari rivojlanishini diqqat bilan kuzating.'),
  ('5bc047d7-1539-47af-a21f-c1df4aa3461d', 'Tushlikni oyoqda va shoshilib yemang. 🥑', 'O‘zingiz uchun mazali salat tayyorlang va 15 daqiqani faqat o‘zingizga ajrating.'),
  ('8d02cce6-aec5-439c-aadf-52670f1abd08', 'Chuqur uyquga tayyorgarlik 🛀', 'Iliq vanna, mayin massaj va xonani qorong‘ilashtirish... Uyqu tartibiga rioya qilish — tun bo‘yi uzluksiz uxlashning siri.'),
  ('347526cf-7568-4464-ab1e-f2a4e4f4b799', 'ROSA 7 OY! 🎉', 'Ishonib bo‘lmaydi! Siz roppa-rosa 7 oydan beri bir jamoa bo‘lib bu mo‘jizani ulg‘aytiryapsiz. Bu kunni hoziroq Chaqaloq fotosessiyasida abadiylashtiring va Hamjamiyatda ulashing!'),
  ('a649650d-baa3-4dab-9158-780252d27ef4', 'Ajoyib kunning yakuni. ✨', 'Siz juda kuchli onasiz! Kayfiyat kundaligiga o‘zingiz bilan faxrlanishingizni yozing, Oq shovqinlar yordamida xotirjamlik topib, oromli uyquga keting.'),
  ('f5e18de7-aba2-4bda-84e9-b3a568ce950b', 'Ortga nazar soling 📈', 'Dastlabki kunlardagi tajribasizligingizni eslang. Endi esa qanchalik mohir onaga aylanganingizga qarang. O‘zingiz bilan faxrlaning!'),
  ('4650c8e1-3011-45f0-9997-0c6decd79a65', 'Ro‘yxat — haqiqiy najotkor 🛒', 'Kundalik shoshilinch ishlar orasida nimanidir unutdingizmi? Boshingizni qotirmang, uy uchun kerakli barcha narsalarni Xaridlar ro‘yxatiga yozib qo‘ying.'),
  ('8c057f2d-32f2-4561-9ca5-5bc651edddcc', 'Hazm jarayonini kuzatamiz. 🧷', 'Qattiq ovqatlar najas kelishini o‘zgartiradi. Har safar taglikni almashtirganingizni Anacan ilovasida qayd etib, chaqalog‘ingizning yangi ovqatlarga munosabatini tahlil qiling.'),
  ('9fc39323-52a1-4045-aa65-bf5c16fac78f', 'Ochmi yoki charchaganmi? 😭', 'Sababsiz yig‘layaptimi va ovozi odatdagidan boshqachami? Vahimaga tushmang. Ovozini darhol Yig‘ini tahlil qilish funksiyasiga eshittiring va muammoning asl sababini aniqlang.'),
  ('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6', 'Uyda xavfsizlik choralarini ko‘ring! 🛡', '️ U harakatlana boshlagani sari xavflar ham ortadi. Bolalar uchun qulflar va burchak himoyachilarini topish uchun Tavsiya etilgan mahsulotlar ro‘yxatimizni ko‘ring.'),
  ('a0d08200-8263-43d9-90a3-313dda8dadc9', 'Qo‘lda yeyiladigan ovqatlarga o‘tish vaqti keldimi? 🥦', 'U endi ovqatni o‘zi ushlashni xohlayaptimi? Xavfsiz variantlar uchun Qo‘shimcha ovqat yeyishni boshlagan chaqaloqlarga mo‘ljallangan retseptlarni ko‘rib chiqing.'),
  ('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96', 'Emaklash mashqlari! 🐢', 'U qorni bilan yotgan holda orqaga sudralyaptimi yoki tizzalariga turishga urinayaptimi? Emaklashni rivojlantiradigan foydali mashqlar haqida Anacan AI-dan so‘rang.'),
  ('52134c06-b272-4f5f-93b6-cf014fc0e867', 'Ona suti hali ham asosiy ozuqa! 🍼', 'Qo‘shimcha ovqat berayotgan bo‘lsangiz ham, ovqatlanish taymerini ishga tushirib, chaqaloqning kunlik sut ehtiyoji qondirilayotganiga ishonch hosil qiling.'),
  ('62cb9c93-e0de-4d15-8d33-e81c1723d1db', 'Onalar uchun energiya bombasi! 🥗', 'Sizning ham sog‘lom ovqatlanishingiz juda muhim! Sog‘lom retseptlardan energiyangizni oshiradigan vitaminlarga boy salat yoki smuzi tayyorlang.'),
  ('f25f7637-e945-4232-a1c1-f7594c81a0b3', 'Tinchlantiruvchi ovoz 📖', 'Bugun kechqurun bolaga o‘z ovozingizda qisqagina ertak o‘qib bering. Ona ovozi — bolaning eng sevimli musiqasi.'),
  ('2a37fc3a-8b98-420a-99ba-c491a8c0f435', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalab, esnashini kutmang. Nigohi xiralashishi bilan darhol uyqu tartibiga o‘ting.'),
  ('74e14338-c8e1-4b5c-b426-24332f30b919', 'Ona uchun 10 daqiqa ☕', 'Bola uxlashi bilan uy ishlariga shoshilmang. Divanga o‘tiring, qahvangizni iching va 10 daqiqa shunchaki devorga qarab, xotirjam nafas oling.'),
  ('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f', 'Injiq tonglar ☁️', 'Bugun ertalab hech narsadan ko‘ngli to‘lmayaptimi? Bunga tish chiqishi og‘rig‘i yoki rivojlanishdagi sakrash sabab bo‘lishi mumkin. Uni ko‘proq bag‘ringizga bosib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('4d7eb303-e249-46ed-8460-db2f0a519240', 'Tabiat — eng yaxshi dori ⛅', 'Juda bezovta va hech narsa bilan chalg‘itib bo‘lmayaptimi? Ob-havo va kiyim vositasini oching, ob-havo sharoitiga mos kiyintiring va darhol uni parkda 20 daqiqalik sayrga olib chiqing.'),
  ('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7', 'Sokin ko‘z yoshlar 📝', 'Bugun hamma narsa ustingizga yopirildi va yig‘laggingiz kelyaptimi? Bu juda tabiiy... Kayfiyat kundaligiga barcha charchoqlaringizni yozing. Ichingizdagilarni to‘kib solish sizga yengillik beradi.'),
  ('e8e53d71-abc7-400d-80a7-8cf91f3339ab', 'Ilk bo‘g‘inlarni takrorlash 🗣️', '«Da-da», «ba-ba» kabi tovushlarni tez-tez takrorlayaptimi? U nutq apparatini sinab ko‘rmoqda. Muloqot qilishni o‘rganishi uchun u aytgan har bir bo‘g‘inni jilmayib takrorlang.'),
  ('27772b37-d653-4081-a4d8-e2d8e3036d19', 'Pediatriyaga oid savollar 🤖', '8-oyga kelib uyqu tartibining buzilishi odatiymi? Internetda soatlab izlash o‘rniga, Anacan AI orqali 8-oydagi uyqu regressiyasi haqida aniq ilmiy ma’lumotlarni bilib oling.'),
  ('e5b5ed3f-01d7-4566-8860-0dc049a710b5', 'Kechki ohang 🎶', 'Bola uxlashga qarshilik qilganda, xonada sokin klassik musiqa qo‘ying. Musiqa to‘lqinlari uning taranglashgan asab tizimini osongina tinchlantiradi.'),
  ('ea452c1a-6484-41b5-9042-60a3abcf409d', 'Tasavvuriy o‘yinlarning boshlanishi 🧸', 'O‘yinchoq ayig‘i yoki qo‘g‘irchog‘iga suv ichirishga urinayaptimi? Uning tasavvuri rivojlanmoqda va ramziy o‘yinlar boshlanmoqda. Bu yoqimtoy rejissyorni chetdan kuzatishdan zavqlaning.'),
  ('6ac03f7c-34a8-46f5-96a4-c1aa521476a5', 'Obyekt doimiyligi o‘yini! 🧸', 'O‘yinchog‘ini biror yopinchiq ostiga yashiring va uni topishiga imkon bering. Bu aqlni charxlovchi o‘yinni o‘ynayotganda, Chaqaloq fotosessiyasi yordamida uning quvonchini suratga oling.'),
  ('746b1115-b7ff-4fd7-b04a-46935d1a6f43', 'Uyning hamma joyida bolalar buyumlari bormi? 🌪️', 'Uyning hamma joyida bolalar buyumlari bormi? Mayli, bo‘lsin. Uyning tartibsizligi sizning yomon ona ekaningizni emas, chaqalog‘ingiz siz uchun ustuvor ekanini ko‘rsatadi.'),
  ('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292', 'Bezovtalikka qarshi ovoz terapiyasi. 🎶', 'Agar bu oqshom chaqalog‘ingiz yangi ko‘nikmalar hayajoni tufayli uxlay olmasa, Oq shovqinlar bo‘limidan ona qornidagi tovushni qo‘ying.'),
  ('5b09b018-664d-4b58-86b9-31b6e1d3baf2', '“Bu meniki” qaysarligi 🛑', 'Qo‘lidan biror xavfli buyumni olganingizda jahli chiqadimi? Taqiqlash o‘rniga, uning e’tiborini ovozi balandroq va rang-barang boshqa o‘yinchoqqa qarating va shu tariqa bu kichik injiqliklarni yengib o‘ting.'),
  ('698ffa60-da73-4003-9656-db865993d1b5', 'Likopchadagi san’at asari 🥦', 'U pyureni yemayaptimi? Ba’zan muammo ta’mda emas, ko‘rinishda bo‘ladi. Sog‘lom retseptlardan foydalanib, rang-barang sabzavotlardan qiziqarli yuzchalar yasang va uning ishtahasini oching.'),
  ('eec20c49-b219-4211-8916-1e602a8ceafb', 'Uyquning o‘ta sezgirligi 🤫', 'Uyquga ketishi bilan eng mayda taqillashdan ham cho‘chib uyg‘onadimi? Shovqin o‘lchagich yordamida xonaning akustikasini tekshiring va derazadan kelayotgan tovushlarni neytrallash uchun oq shovqinni qo‘ying.'),
  ('a2641bfd-0346-425a-86be-0a5a6822a3d8', 'Otaning ovoz ohangi 📖', 'Bu oqshom xonada o‘zgacha muhit yarataylik. Aqlli ertaklarda jasur o‘rmon jonzoti haqida hikoya yarating va uni otaning yo‘g‘on, ishonch bag‘ishlovchi ovozida o‘qib berishini so‘rang.'),
  ('ba28583a-a3f1-40f6-9657-b7b38af17c60', 'To‘rt devordan tashqariga ☕', 'Uydagi bir xil yumushlar sizni zeriktira boshladi. Bugun biroz o‘zgarish qiling. Yaqin atrofdagi chaqaloq aravachasi bilan bemalol kirish mumkin bo‘lgan kafeni tanlab, qahvadan zavqlaning.'),
  ('ea94213c-026e-4de0-be12-a192e4d22b19', 'Farzandingiz kundan-kunga rivojlanmoqda🤏', 'U yerdagi eng mayda dog‘ yoki ushoqni ham bosh va ko‘rsatkich barmoqlari bilan ushlashga harakat qilyaptimi? Nozik motorikasi ayni avjida!'),
  ('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911', 'Mebel ustiga chiqish 🧗‍♂️', 'U divan yoki stuldan ushlab, o‘zini yuqoriga tortyaptimi? Oyoq mushaklari mustaqil turishga tayyorlanmoqda. Uni ehtiyot qiling, ammo bu kichik alpinistning urinishlariga to‘sqinlik qilmang.'),
  ('82e71311-374a-4306-bcfc-4f69bc54da1b', 'Tungi bo‘ron 😭', 'U yarim tunda hech qanday sababsiz yig‘lab uyg‘ondimi? Yig‘ini tahlil qilish yordamida sababini aniqlab, uni tinchlantiring.'),
  ('c7aadd23-e889-42f2-a761-3f955cb9600f', 'Miyangizni zo‘riqtirmang 🛒', 'Uyqusizlik xotirangizni susaytirib, do‘kondan olinadigan narsalar esingizdan chiqyaptimi? Hammasini Xaridlar ro‘yxatiga yozib qo‘ying, turmush o‘rtog‘ingiz qaytayotganda xarid qilib kelsin.'),
  ('3f339310-d600-43dc-81a3-1b609288885e', 'Ketishi qiyin dog‘lar 👗', 'Qo‘shimcha ovqatlantirish davrida uy ham, kiyimlar ham doimo dog‘ bo‘lishi tabiiy. Bundan jahlingiz chiqmasin. Silikon ko‘krakpechlardan foydalaning va bu kulgili, rang-barang lahzalardan shunchaki zavq oling.'),
  ('60071670-7fa4-4f9f-829f-892d281a9741', 'O‘zingizni ayblashni bas qiling. 🛑', 'Bugun ekran qarshisida ko‘p vaqt o‘tdimi yoki uy yig‘ishtirilmay qoldimi? Siz shunchaki charchagan insonsiz va qo‘lingizdan kelganicha harakat qilyapsiz.'),
  ('fe5cb47e-9f22-41f9-a236-1db4b224e518', 'Buyumlarni yerga tashlash o‘yini 🥄', 'Chaqaloq ovqatlanish stulidan o‘yinchoqni yerga tashlab, uni olib berishingizni kutyaptimi? U tortishish kuchi va sabab-oqibat bog‘liqligini o‘rganmoqda. Sabrli bo‘ling va tabassum qiling.'),
  ('28d590c8-c8a6-4c89-b78b-e70f2f482c0d', 'Qorong‘ilikka ko‘nikish 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlar va ekranlarni o‘chiring. Melatonin gormoni faqat tinch va qorong‘i muhitda tezroq ishlab chiqariladi.'),
  ('31783568-6230-449d-98c8-e7b1b046a34e', 'Injiq tonglar ☁️', 'Ko‘zini ochishi bilan hamma narsaga yig‘lab, hech narsadan ko‘ngli to‘lmayaptimi? Balki u ayni o‘sish davrining o‘rtasidadir. Uni ko‘proq bag‘ringizga bosib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('38c7f3dd-4cf4-4758-8006-37d59832bac8', 'Bola uxlashi bilan idish yuvish mashinasini bo‘shatishga shoshilmang! 🛋️', 'Divanga cho‘ziling, ko‘zlaringizni yuming va 15 daqiqa davomida uydagi o‘sha noyob, mutlaq sukunatga singib keting.'),
  ('3a7b24a5-41c6-4c5d-a602-8a4582791ae2', 'Kundalik yugur-yugurda tushlikni oyoq ustida qilmang. 🥑', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi? O‘zingiz uchun to‘yimli, temirga boy alohida bir likopcha tayyorlang.'),
  ('61d3770b-ac23-4b61-a0c4-be4c333cc55a', 'Sirlarni bo‘lishamiz 💬', '«Nega mening bolam hali emaklamayapti?» deb xavotirdamisiz? Darhol Anacan Hamjamiyatiga qo‘shiling. Minglab onalarning haqiqiy hikoyalarini o‘qing yoki savol berib, har bir bolaning o‘ziga xos ekanini ko‘ring.'),
  ('a8ecb50a-232f-401a-97bc-3fbfc63cc92b', 'Ajralish xavotiri 🥺', 'Siz xonadan chiqqaningizda ortingizdan yig‘laydimi? U siz boshqa qaytib kelmaysiz deb o‘ylaydi. «Men doim shu yerdaman», deb ovozingiz orqali unga ishonch hissini bering.'),
  ('6666dee6-8da7-4982-b6e5-9cdc982b4a75', 'Milk qichishishi davom etmoqda 🦷', 'Hamma narsani qattiq tishlayaptimi va og‘zidan so‘lak oqyaptimi? Muzlatkichda sovutilgan tishlagichlar bu kunlarda haqiqiy najotkor bo‘ladi.'),
  ('bedd9e86-f764-4777-9e49-e315e75433fd', 'Otaning mas’uliyati 👨‍🍼', 'Tunda uyg‘onishlar yukini butunlay yolg‘iz o‘zingiz ko‘tarmang. Juftingizni ham uyg‘oting, chunki bir jamoa bo‘lish bu mas’uliyatni teng bo‘lishish demakdir.'),
  ('c36dcca2-2b51-424c-b39c-c98f7988d549', 'Seni topdim! 🙈', 'Qo‘llaringiz bilan yuzingizni berkitib, «ku-ku» desangiz, ovoz chiqarib kuladimi? Unda narsalar ko‘rinmasa ham mavjud bo‘lishda davom etishi haqidagi tushuncha to‘liq shakllanmoqda. Bu o‘yinni kundalik tartibingizning bir qismiga aylantiring.'),
  ('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d', 'Jamoa yig‘ilishi 🥂', 'Og‘ir kunni ortda qoldirdingiz. Bola uxlagach, turmush o‘rtog‘ingiz bilan bir piyola choy quyib, «Biz haqiqatan ham ajoyib jamoamiz», deya bir-biringizni qadrlashni unutmang.'),
  ('579d5966-d49f-4125-a264-8acd785d0a8d', 'Ko‘zgudagi do‘st 👀', 'Uni ko‘zgu oldiga olib boring. O‘z aksiga qanday hayrat bilan qarashini va unga tegishga urinishini kuzating. Bu uning o‘zini anglashiga yordam beradigan ajoyib mashg‘ulotdir.'),
  ('9099f274-aa9c-4fe9-8624-5cd611699d2d', 'Tezkor ta’minot 🛒', 'Chaqaloq moyi yoki nam salfetkalaringiz tugayaptimi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni u yerga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda olib kelsin.'),
  ('1d706879-d02b-44cf-bac5-4f53776477d3', 'Ob-havo kutilmagan hodisalarga boy ⛅', 'Sayrga chiqqanda ob-havoga aldanib, uni sovqotib qo‘ymang. Faqat derazadan qarab qaror qilmang — Ob-havo va kiyim yordamchisi orqali tashqaridagi sharoitga eng mos kiyimni aniq tanlang.'),
  ('acd7fb31-0c36-4f0b-9849-cf983e0b0e95', 'O‘zim yeyman! 🥦', 'U endi pyureni qoshiq bilan emas, sabzavotlarni o‘z qo‘li bilan ushlab yeyishni xohlayaptimi? Uning mustaqilligini qo‘llab-quvvatlang. Ha, atrof iflos bo‘ladi, ammo uning rivojlanishi tezlashadi.'),
  ('e1819391-1d2d-450e-ac14-9ecfa65465d4', 'Ertaklarning sehrli olami 🪄', 'Bugun kechqurun Aqlli ertaklarda butunlay boshqacha usulni sinab ko‘ring. Ovoz ohangingizni ertak ritmiga moslashtiring.'),
  ('aff9ba8d-8d8a-4d80-9363-09474c73609e', 'Kichkina kashfiyotchi 👣', 'U oyoq barmoqlarini allaqachon kashf etdi va ularni og‘ziga solishga harakat qilyapti!'),
  ('d79d065c-4399-4ac9-8bd9-d4970a686fba', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechqurun chaqaloqni uxlashga tayyorlash va unga pijama kiydirishni dadasiga topshirib, o‘zingiz shunchaki chetdan kuzating.'),
  ('ea309314-6720-4ddf-9fe1-7a4fb805b43f', 'Savolingiz bormi? 🤖', '8-oyga yaqinlashganda chaqaloqning bo‘yi va vazni grafigi sizni tashvishga solyaptimi? Internetdagi qo‘rqinchli maqolalarni o‘qish o‘rniga, Anacan AI-dan aniq va ilmiy asoslangan jadval so‘rang.'),
  ('1c1e068a-2609-422f-991f-68ad50839ea3', 'Quvvatingizni tiklang 🍲', 'Charchoqdan tinka-madoringiz quridimi? Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan, ko‘krak suti ishlab chiqarilishini qo‘llab-quvvatlaydigan va sizga tetiklik baxsh etadigan maxsus smuzi tanlang.'),
  ('51badc42-c8bc-4aa3-b0b8-ec576b19fa07', 'Shovqinlarni nazorat qiling 🤫', 'Chaqaloq uxlab qolganidan keyingi dastlabki yarim soat eng nozik davrdir. Shovqin o‘lchagich yordamida muhitni tekshiring va qo‘shni xona yoki televizordan keladigan kutilmagan shovqinlarning oldini oling.'),
  ('69f05aef-6a67-462b-8173-638d2cb174d5', 'Maqsad sari emaklash 🐢', 'Endi u nishonini tanlab, unga tomon tez emaklaydi. Xonadagi yutib yuborish mumkin bo‘lgan barcha mayda va xavfli buyumlarni darhol poldan olib tashlang.'),
  ('7405692f-45e1-45fa-9dd9-b527045b5e7d', 'Tajriba almashish 💬', 'Bolangizning yangi bir xatti-harakati (masalan, boshini devorga urishi) sizni qo‘rqitdimi? Anacan Hamjamiyatiga yozing va boshqa onalar ham bu bosqichdan qanday o‘tganini o‘qing.'),
  ('cad415e5-9ff2-468b-bfee-aaed538d25a0', 'Dadillik bilan tashlangan qadamlar 🧗‍♂️', 'Divanga suyanib, bir qo‘lini qo‘yib yuborishga urinmoqdami? Muvozanatni saqlash qobiliyati jadal rivojlanmoqda. Uning bu qo‘rqmas urinishlarini masofadan turib ehtiyotlab, tabassum bilan kuzating.'),
  ('e2523211-afd7-48c7-8227-2ec7b0b2f0f7', 'His-tuyg‘ularingizni erkin ifoda eting 📝', 'O‘zingizni juda yolg‘iz va hech kim tushunmayotgandek his qilyapsizmi? Bu mutlaqo tabiiy tuyg‘u. Kayfiyat kundaligiga his-tuyg‘ularingizni hech qanday cheklovsiz, samimiy tarzda yozib qo‘ying.'),
  ('16c8c619-fdcd-4a82-a21a-ff965106a15f', 'Uydagi tartibsizlik 🌪️', 'Xonaning hamma joyida o‘yinchoqlarmi? Tozalikdan ko‘ra, u bilan quvonchli o‘tkazgan 10 daqiqangiz muhimroq. O‘yinchoqlar ertaga ham o‘sha yerda bo‘ladi, o‘zingizni charchatmang.'),
  ('4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773', '8-oyga tayyorgarlik! 🎂', 'Diqqat! Atigi 10 kundan keyin kichkintoyingiz roppa-rosa 8 oylik bo‘ladi! Rivojlanish kuzatuvchisida bosib o‘tgan yo‘lingizga nazar soling. Ushbu kichik yubiley uchun Anacan-dan hozirdanoq kichkina tort buyurtma qilishni o‘ylab ko‘ring.'),
  ('724d9097-f64c-406e-8895-2982258b710d', 'Musiqa sadolari ostida uyquga tayyorgarlik 🛀', 'Kechki tartib qiyinlashdimi? Iliq vanna paytida fonda tinchlantiruvchi musiqa qo‘ying. Suv va ohang uyg‘unligi hatto eng qaysar bolani ham tinchlantiradi.'),
  ('12b2ddaa-17a1-4692-8574-725c962b0e1b', 'Sababini topa olmayotgan yig‘i xurujlari odamni holdan toydiradi. 😭', 'Sababini topa olmayotgan yig‘i xurujlari odamni holdan toydiradi. Taxmin qilishni bas qiling, Yig‘i tahlilidan foydalanib, ovoz ortidagi yashirin xabarni (og‘riq, charchoq) darhol aniqlang.'),
  ('19b095ff-5334-4011-abd1-b8df6c79520c', 'Sayr qilish vaqti 🌳', 'To‘rt devor orasida siqilib qolyapsiz. Uni aravachasiga yotqizing va hech bo‘lmasa 20 daqiqaga toza havoga chiqing. Tabiatning osoyishtaligi chaqaloqqa ham, ruhiy holatingizga ham juda yaxshi ta’sir qiladi.'),
  ('b6194099-d4e6-4061-b3f2-d6bc5cce0529', 'Ko‘rsatkich barmoq ☝️', 'Uzoqdagi buyumni barmog‘i bilan ko‘rsatib, sizga qarayaptimi? U sizga menga qara yoki buni xohlayman demoqda. Bu muloqotdagi katta sakrash! Unga buyumning nomini ayting.'),
  ('b78498d9-706c-458c-aa0f-d6081c7746c6', 'Tungi alla 🎶', 'Hech qanday ilova yoki ovoz ona allasining o‘rnini bosa olmaydi. Bu oqshom uni shunchaki bag‘ringizga bosing va eng sevimli, unga ishonch bag‘ishlaydigan allasini mayin ovozda kuylang.'),
  ('d08b308d-00d3-45c9-9840-df7ac1047703', 'Qarsaklar jamoasi 👏', 'Quvonchini qarsak chalib ifodalayaptimi? Bu ajoyib harakat ko‘nikmasini ko‘rgan zahotingiz uyda kichik g‘alaba raqsini tushib, unga qo‘shiling!'),
  ('dd6cc7ba-db6f-403b-93e6-2447dbb967dc', 'Ro‘yxat shunchaki kerak emas, u juda zarur 🛒', '8 oylik bayram uchun kerakli bezaklar unutilmasin! Miyangizni zo‘riqtirmang, hammasini darhol Xaridlar ro‘yxatiga yozing va juftingiz bilan hamjihatlikda ish tuting.'),
  ('7227b833-2ecd-472c-a074-7273a66732d9', 'Tanish chehralar 🥰', 'Xonaga kirganingizda uning yuzidagi o‘sha katta va o‘zgacha tabassumni ko‘rdingizmi? U sizni va juftingizni boshqalardan ajratib taniydi. Uning bu cheksiz mehri — eng katta motivatsiya.'),
  ('90341333-a47d-4dc8-b1bb-8fcf07c769b0', 'Dadaning kulgili qiyofalari 🤡', 'Chaqaloqni kuldirishning eng tezkor usuli — dadasining g‘alati tovushlar chiqarib, kulgili qiyofalar ko‘rsatishi. Bu oqshom quvnoq qahqahalarni tinglab, bir chetda dam oling.'),
  ('d4f1084b-2a25-422f-954c-038d4cf53bd2', 'Forumlarda adashib qolmang 🤖', 'Qo‘shimcha ovqat haqida «Buni bersa bo‘ladimi?» degan shubhangiz bormi? Soatlab ma’lumot qidirmang — cho‘ntagingizdagi raqamli pediatr kabi Anacan AI savollaringizga javob bersin.'),
  ('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc', 'Onalar uchun maskan ☕', 'Uyda qolaverib, quvvatingiz tugadimi? Onalar uchun qulay maskanlar orasidan bolalar aravachasi bilan bemalol joylashishingiz mumkin bo‘lgan sokin kafeni tanlab, o‘zingiz uchun kichik uchrashuv uyushtiring.'),
  ('66c8660e-b8ca-4046-9e3f-578e25572ec7', 'Chiqindilar tadqiqotchisi 🗑️', 'Yerda yoki gilam chetida nima topsa, katta qiziqish bilan o‘rganadi. Hamma narsani qo‘lidan tortib olib, jahlingiz chiqmasin — u kichkina tadqiqotchi. Faqat yutib yuborishi mumkin bo‘lgan buyumlardan ehtiyot bo‘ling.'),
  ('8d417480-194b-431c-987a-b0b5216ea151', 'Bugun Aqlli ertaklarda 🪄', 'Aqlli ertaklarda atigi bir necha kundan keyin 8 oylik bo‘ladigan buyuk qahramon haqida hikoya yarating. Tun sukunatini faqat shu sehrli hikoya to‘ldirsin.'),
  ('5d8608e7-e1cb-4a71-9c73-7f6dde65adfe', '8 oyga 5 kun qoldi! 🎈', 'Hayajon ortmoqda! Atigi 5 kundan keyin kichkintoyingiz 8 oylik bo‘ladi! Agar maxsus tort buyurtma qilish yoki bayram mavzusini rejalashtirishni o‘ylayotgan bo‘lsangiz, buni so‘nggi kunga qoldirmang.'),
  ('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05', 'Sukunat va qahva 🤫', 'U uxlab qoldi! Endi kir yuvish mashinasini bo‘shatish o‘rniga, qorong‘i xonada biroz o‘tiring. Ovoz o‘lchagichni yoqib, vaziyatni nazoratga oling va 15 daqiqalik sukunatning qadriga yeting.'),
  ('f72fbb7e-431d-4f4b-9a73-06637ff7bd68', 'Mukammallik bo‘lmaydi 🛑', 'Bugun hech narsa reja bo‘yicha ketmadimi? O‘zingizni ayblamang. Siz haqiqiy onasiz, ijtimoiy tarmoqlardagi filtrlangan xayolot emassiz. Farzandingizga faqat siz keraksiz.'),
  ('61ffa498-18cc-4858-987c-676f525f467c', 'Hissiy yukdan xalos bo‘ling 📝', 'Kun og‘ir o‘tdimi? Kayfiyat kundaligiga bugungi barcha salbiy kechinmalaringizni yozib, ko‘nglingizni bo‘shating. Barcha onalar bunday qiyin davrlarni boshdan kechiradi, siz aslo yolg‘iz emassiz.'),
  ('856b771b-5997-4eed-bc26-8b35541184c6', 'Ob-havoni tekshiring ⛅', 'Tashqaridagi ob-havo qandayligi aniq emasmi? Ob-havo va kiyim tanlash vositasi sizga derazadan sezilmaydigan shamol tezligi va mos kiyimlarni darhol ko‘rsatsin — hech ikkilanmay sayrga chiqing.'),
  ('c82d9568-ae94-4492-9789-4621c2dbcabc', 'O‘yinchog‘imni bermayman! 🧸', 'Qo‘lidan biror narsani olganingizda qarshilik ko‘rsatib, baland ovozda yig‘laydimi? Unda egalik va o‘ziga xoslik hissi rivojlanmoqda. Bu juda tabiiy psixologik bosqich, bunga qarshi kurashmang.'),
  ('bc11c415-3d46-43c3-a8ed-0a204516e9ce', 'Sog‘lom ona, sog‘lom chaqaloq 🥑', 'Temir va kalsiy zaxiralaringiz kamayib ketgan. Sog‘lom retseptlardan tez tayyorlanadigan, kun davomida tetik turishingizga yordam beradigan quvvatga boy taom pishirib, o‘zingizni siylang.'),
  ('e386c8f2-240d-4f0f-adaf-e43ea496b8b2', 'Kitob varaqlaydigan zehn 📖', 'Qalin sahifali kitoblarni mustaqil varaqlab, rasmlarga munosabat bildiryaptimi? Demak, ko‘rish xotirasi a’lo darajada ishlayapti. U bilan birga kitob o‘qing va rasmdagi hayvonlarning nomlarini ayting.'),
  ('e418c384-8ae3-455b-af14-a223e6595751', 'Vaqtni to‘xtatuvchi kadr 📸', 'U xonada shirin o‘ynab yurganida darhol Chaqaloq fotosessiyasini oching va 8 oylikka yaqinlashayotgan, ancha ulg‘aygan bu o‘zgacha chehrani maxsus mavzu yordamida xotiraga muhrlang.'),
  ('4068a45c-e5fe-4a82-8c4b-a81d556f97cc', 'Dardlashishga ehtiyoj bor 💬', '«Uning 8 oylik bo‘layotganiga ishonolmayapman», degan o‘y sizni hayajonga solyaptimi? Bu go‘zal va nozik tuyg‘uni Anacan hamjamiyatidagi onalar bilan baham ko‘ring.'),
  ('90c5ba08-9d91-4669-8b26-99e0b48d4cf2', 'Sinov va xato 🧱', 'Ikkita o‘yinchoq kubikni ustma-ust qo‘yishga urinadi, ammo ular yiqilib tushadi. U diqqat bilan yana qayta sinab ko‘radi. Uning bu kichik muhandislik tajribalari va urinishlarini indamay, faxr bilan kuzating.'),
  ('ed75b4ae-9703-498c-a857-64016faef6cc', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yoritilgan muhitda tez ajraladi.'),
  ('075bea5d-3ab7-4404-af70-89a3de20a0ff', 'Tezkor ro‘yxat 🛒', 'Kecha uydagi barcha zaxiralar tugab qoldimi? Xaridlar ro‘yxatini oching, sut, meva va boshqa yetishmayotgan mahsulotlarni bir necha soniyada yozib, turmush o‘rtog‘ingizning telefoniga yuboring.'),
  ('3c7f679a-b11a-4f67-a3ae-5f350e93a451', 'Maxsus ertak 🪄', 'Aqlli ertaklar yordamida bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating.'),
  ('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8', 'Bayramdan keyingi tartibsizlik 🌪️', 'Kechagi 8 oylik bayramdan keyin uy ag‘dar-to‘ntar bo‘lib ketdimi? Darrov tozalashga shoshilmang. Bugungi kunni endigina 8 oylik bo‘lgan kichkintoyingiz bilan shunchaki dam olishga va yangi o‘yinchoqlarni o‘rganishga bag‘ishlang.'),
  ('2c9fa500-5618-49b8-a232-965da7b82ef7', 'Shovqinni nazorat qilish 🤫', 'Chaqaloq uxlab qolganidan keyingi dastlabki yarim soat eng nozik davrdir. Shovqin o‘lchagich yordamida muhitni tekshiring va to‘satdan chiqadigan shovqinlar, televizor yoki ko‘cha ovozlaridan saqlaning.'),
  ('87a20850-e59a-4ee2-81e8-79c4b5808e7b', 'Sizni eshityapman 🗣️', 'Sizni diqqat bilan tinglab, o‘xshash bo‘g‘inlarni aytishga urinyaptimi? U siz bilan gaplashyapti! Unga ko‘p jilmayib javob bering va bu muloqotni rag‘batlantiring.'),
  ('9c963f32-b147-4e84-aa9a-af699e50681f', 'Bugun sabringiz tugab, balki jahlingiz chiqdimi?  🛑', 'O‘zingizni ayblamang. Internetdagi soxta tasavvurlardan uzoqlashing. Siz haqiqiy onasiz va his-tuyg‘ularingizni yashashga haqqingiz bor.'),
  ('695238eb-b88d-4ffe-800b-82d23636ceb9', 'Uy ishlarini kim qiladi? 🌪️', 'Ertangi kichik bayram uchun hali ishlar qoldimi? Qolaversin. Juftingizdan bugun uy ishlarini o‘z zimmasiga olishini so‘rang. Siz esa ertangi kun uchun dam oling.'),
  ('c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8', 'Massaj vaqti 💆‍♂️', 'Chaqaloq uxlagach, kun davomida yig‘ilgan stressdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Ertangi ajoyib g‘alabani nishonlash uchun, albatta, kuchga to‘lib oling!'),
  ('d3b0f81b-e9b4-4b00-883d-9e8bb86131bc', 'Ertaga 8 oy bo‘ladi! 📸', 'Tayyormisiz? Ertaga katta kun! Rosa 8 oy! Telefoningiz xotirasini bo‘shating, ertangi chaqaloq fotosessiyasi uchun juda ko‘p joy kerak bo‘ladi. Kiyimlarni hozirdanoq dazmollab qo‘ying.'),
  ('393a7a2a-b162-45e4-9577-0e4f2d088bf3', 'G‘alaba raqsi 🥂', '8 oy davomida boshdan kechirgan charchoq, ko‘z yoshlar va quvonchni bugun kechqurun juftingiz bilan birga nishonlang. Dasturxonga sham qo‘yib, mustahkam jamoangizning g‘alabasini olqishlang!'),
  ('4419f2fd-8e6f-4837-aa0e-9d571aac3895', 'Ortga nazar 📈', 'Chaqalog‘ingiz qanchadan-qancha yo‘lni bosib o‘tdi! Ilk kunlardagi o‘sha nozik xavotir endi ulkan ishonchga aylandi. Siz bu 8 oyni katta g‘urur bilan bosib o‘tdingiz! Siz haqiqatan ham ajoyibsiz!'),
  ('b4769acb-82a0-480e-b58f-3017d46b37a4', 'Ajoyib 8 oy! 🎉🎂', 'TABRIKLAYMIZ! Siz mana rosa 240 kundirki, bu mo‘jizaviy yo‘lni birga bosib kelyapsiz! Chaqalog‘ingiz endi roppa-rosa 8 oylik. Bu alohida kunni hoziroq bayram qiling va Anacan hamjamiyatida faxr bilan ulashing!'),
  ('0cf5cff8-d958-4ec0-b6df-6f78457976fd', 'Shifokordek aqlli 🤖', '8 oydan keyingi rivojlanish me’yorlari haqida savollaringiz bormi? Internetda adashib qolmang, Anacan AI’dan ishonchli, ilmiy asoslangan va pediatrlar tasdiqlagan javob oling.'),
  ('77b45217-21e4-402a-b5dd-d0ee28c29f05', 'Barmoqlar bilan ovqatlanish 🥦', 'U endi pyureni emas, sabzavotlarni o‘z qo‘li bilan ushlashni xohlaydi! Mustaqil ovqatlanishga urinishlarini qo‘llab-quvvatlang, atrof iflos bo‘lsa ham, albatta yonida qolib kuzating.'),
  ('dd6d5f01-5a48-4f85-953e-c5e21662ae95', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarning barcha yukini yolg‘iz o‘zingiz ko‘tarmang. Juftingizni ham uyg‘oting — jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir. Bu kecha chaqaloqni uxlatish navbati uniki.'),
  ('918fe7fd-3c85-49ee-b337-c52aba217614', 'Yarim tunda qichqirib uyg‘onib, hech tinchimayaptimi?  😭', 'Ovozini Yig‘i tahliliga eshittirib, muammo shunchaki tungi vahimami yoki jismoniy og‘riqmi, aniqlang.'),
  ('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b', 'Musiqaga raqs 🎶', 'Quvnoq musiqa yangraganda ritmga mos tebranadimi? Eshitish va harakatlanish o‘rtasidagi aloqa ajoyib rivojlanmoqda! Quvnoq qo‘shiqni qo‘yib, u bilan birga xonada raqsga tushing.'),
  ('deba3d42-726a-4e83-bbbd-900d2aee20ad', 'U to‘ygan bo‘lsa, navbat sizniki.', 'Sog‘lom retseptlardan quvvat beruvchi tamaddi tanlang va hech bo‘lmasa 10 daqiqa divanda yotib, kuchingizni tiklang.'),
  ('31a887b1-fde3-4a67-a32c-13cc6764d41e', 'Birgalikda kitob o‘qing! 📖', 'Ovozli va rang-barang kitoblar uning e’tiborini juda tortadi. Kitob o‘qish orqali o‘rgatadigan lahzalaringizni Bloglardagi tavsiyalar bilan yanada boyiting.'),
  ('a82a604d-9504-4486-86ea-c38998236871', 'Qaysi ko‘krak bilan emizganingizni unutdingizmi? 🤱', 'Anacan taymeri sizning o‘rningizga o‘ng/chap ko‘krakni eslab qoladi. Emizishni hoziroq taymer bilan boshlang!'),
  ('d7cab28d-37d6-4301-8e4d-28dfd96b83ab', 'Suv ichish odatini shakllantiramiz. 💧', 'Qo‘shimcha ovqat bilan birga suv taklif qilishni unutmang. Qaysi ichimlik idishlari mosroq ekanini Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('6122dba2-692e-45e2-8027-9ab67ba2bf07', 'Kel, kel 👏', 'U qo‘llarini chapak chalyaptimi yoki sizga qarab quchoq ochyaptimi? Bu ajoyib muloqot usuli. Uni bag‘ringizga bosing.'),
  ('a73ae95c-98a0-4201-9af1-960893ecd116', 'Vaqtni to‘xtatish 📸', 'U shunchalik tez ulg‘aymoqdaki... Uxlayotganida uning yoqimtoy va sokin yuzini suratga olib, xotira sifatida saqlang.'),
  ('b8c9eaea-1257-487d-8647-7c1cb6d70a3a', 'Savolingiz bormi? 🤖', 'Chaqaloqning rivojlanishi haqida xayolingizda minglab savollar bormi? Anacan AI’ga yozing va pediatrning aniq tavsiyalarini oling.'),
  ('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6', 'Hissiyotlar kundaligi 📝', 'O‘zingizni yolg‘iz va charchagan his qilganingizda, his-tuyg‘ularingizni Kayfiyat kundaligiga yozing. Barcha ayollar bu notinch yo‘llardan o‘tadi, siz kuchlisiz va buni uddalaysiz!'),
  ('90ae683e-61a6-4dd5-b894-186c95367ff3', 'Milklar qichishishi davom etyaptimi? 🦷', 'Barmoqlari doim og‘zidami va ko‘p so‘lak ajratyaptimi? Muzlatkichda sovitilgan tish qashlagichlarni yana ishlatish vaqti keldi.'),
  ('b9bfa71c-cf95-4768-adc9-c82fe1e676ac', 'Toza havo — davo 🌳', 'Kun bo‘yi yig‘lab, bezovta bo‘ldimi? Yechimi juda oddiy: ob-havoni tekshiring, mos kiyintiring, aravachaga o‘tqazing va darhol parkka chiqing. Tabiat — eng tez tinchlantiruvchi vosita.'),
  ('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d', 'Obyektning doimiyligi o‘yini! 🧸', 'O‘yinchog‘ini biror yopqich ostiga yashiring va uni topishiga imkon bering.'),
  ('2e5279b4-ad3c-4da7-866e-49a5932c0601', 'Qo‘lidan o‘yinchog‘ini olsangiz, qichqiradimi?🧸', 'Egalik hissi kuchaymoqda. Bu xarakter shakllanishining muhim qismidir.'),
  ('d2ac515d-c34a-47d7-a082-82f89c2863e8', 'Ona suti hali ham asosiy ozuqa! 🍼', 'Qo‘shimcha ovqat berilayotganiga qaramay, oziqlantirish taymerini ishga tushirib, chaqaloqning sutga bo‘lgan kunlik ehtiyoji qondirilayotganiga ishonch hosil qiling.'),
  ('19dff725-11f8-467a-b784-f2971b302ba0', '250-kunga tayyorgarlik! 🌟', 'Ertaga katta sana! Rosa 250 kun! Uyda kichik bayramona muhit yarating va bu raqamdan faxrlanishga tayyorlaning.'),
  ('c304b9f3-2045-4d2f-b423-1096223f0f83', 'Bugun tozalik yo‘q 🛑', 'Charchadingizmi? Juftingizga ayting. Bugun uy ovqati yo‘q. Bugun onaning dam olish kuni!'),
  ('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d', 'Ertakning oxiri yo‘q 📖', 'Bugun kechqurun Aqlli ertaklarda jasur va aqlli bola haqida hikoya yaratib, sokin muhit hosil qiling.'),
  ('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2', '250 kunlik faxrni his eting🥂', 'Bugun kechqurun bola uxlagach, juftingiz bilan jamoangizning bu ulkan g‘alabasini nishonlashni unutmang!'),
  ('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218', 'AJOYIB 250 KUN! 🎉', 'Ishona olasizmi? Rosa 250 kundan beri bu jo‘shqin va sehrli yo‘lni birga bosib kelyapsiz! Chaqaloq fotosessiyasida maxsus stiker bilan bu onni yanada bayramona qiling!'),
  ('e0e283b4-8f62-4d84-98d9-c186d1f67042', 'Ortga nazar tashlang 📈', 'Dastlabki kunlardagi qo‘rquvlaringizni eslang. Endi esa oyoqqa turishga urinayotgan bolaning onasisiz! O‘zingiz bilan faxrlaning!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('01890bf6-ab5a-403c-96d2-696020ff0863'::uuid, 'Yerdagi xavflar 🧸', 'Endi xonalar uning uchun kashfiyot maydoniga aylandi. Emaklab, hamma joyga yetib boradi. Uy xavfsizligini ko‘zdan kechirishning ayni vaqti.'),
  ('64b9a99f-59f6-4495-b5ab-9a4825037afc', 'Tortishish kuchi sinovi 🥄', 'Qo‘lidagi narsani ataylab yerga tashlab, sizga qarayaptimi? U shunchaki sabab-oqibat bog‘liqligini o‘rganmoqda. Sabrli bo‘ling va o‘yinga qo‘shiling.'),
  ('b34bf0e6-4ffb-4b59-90eb-68d99299dee1', 'Sovib qolgan qahva haqiqati ☕', 'Bugun ham qahvangiz sovib qoldimi? Hechqisi yo‘q, siz tinmay harakat qiladigan qahramonsiz. Kayfiyat kundaligiga bugungi tartibsizlikni hazil bilan yozib qo‘ying.'),
  ('026d603e-c612-41a2-9525-f4d00f730669', 'Yolg‘iz dush qabul qilish hashamati 🛀', 'Kun bo‘yi uning ortidan yugurib, qo‘llaringiz holdan toydi. Navbatni juftingizga topshiring va o‘zingizga 15 daqiqalik uzluksiz suv muolajasini sovg‘a qiling.'),
  ('1c49ef6a-c84a-47c7-a1bc-352a17833a3d', 'Divan bo‘ylab sayrlar 🛋️', 'Mebellardan ushlab o‘rnidan turib, yon tomonga qadam tashlayaptimi? Bu mustaqillik sari qo‘yilgan eng katta qadamdir. Rivojlanish kuzatuvchisida bu lahzani albatta qayd eting.'),
  ('b5c1158f-415c-414a-b3ec-c9879bf6e9d9', 'Ismini taniydi! 🗣️', 'Boshqa xonadan ismini aytib chaqirganingizda, o‘girilib qaraydimi? Eshitish va tushunish qobiliyati takomillashmoqda. U bilan gaplashganda ismini tez-tez ayting.'),
  ('bb4b0ba8-0880-4332-8a97-7715f01a7ba8', 'Shkaf izquvarlari 🕵️‍♂️', 'Oshxona shkaflari uning eng sevimli nishonimi? Xavfsiz idish-tovoqlarni pastki shkafga joylang, u o‘z xazinasini kashf etib, soatlab o‘ynasin.'),
  ('bf07c6c2-b84c-44ed-9459-f26c37f0e099', 'Bekinmachoq ustasi 🙈', 'Qo‘llari bilan yuzini berkitib, ku-ku o‘ynash uning eng sevimli kechki mashg‘ulotidir.'),
  ('c24149f4-cca2-46bd-ba68-2442b259ab90', 'Siz ham ayolsiz 💄', 'Siz onasiz, himoyachisiz, ammo ayni paytda alohida shaxssiz. Oynaga qarab, o‘zingizga tabassum qiling va bugun o‘zingiz uchun kichik bir yaxshilik qiling.'),
  ('4283eae1-f0b6-489a-be21-28cec6201152', 'Forumlarda adashib qolmang 🤖', 'Ovqatlanish tartibida biror narsadan shubhangiz bormi? Soatlab javob izlamang, Anacan AI cho‘ntagingizdagi pediatr kabi fikrlab, savollaringizga javob bersin.'),
  ('743ea03a-9755-40d4-b4aa-1eb6cf8a7495', 'Otaning kitob o‘qish vaqti 📖', 'Bu oqshom Aqlli ertaklarda Tog‘larga tirmashgan jasur echki haqidagi hikoyani yarating. Otasi o‘qib bersin, siz esa bu osoyishtalikdan bahra oling.'),
  ('fc594ad6-91bd-4ee2-a759-0d1e76e468c0', 'Barmoqlar bilan ovqatlanish 🥦', 'U endi pyureni emas, sabzavotlarni o‘z qo‘li bilan ushlamoqchi! Mustaqil ovqatlanishga urinishlarini qo‘llab-quvvatlang, ammo albatta yonida bo‘ling.'),
  ('2e4d0e7a-db8d-4408-9d88-01d37ed8b303', 'Uyqu oralig‘i qisqarmoqda 🥱', 'Tunda uyg‘onishlar sizni holdan toydirdimi? Balki bu 3 mahal uyqudan 2 mahal uyquga o‘tish davridir. Kunduzgi uyqular orasidagi vaqtni qayta ko‘rib chiqing.'),
  ('b19774b6-01ed-4a77-8052-5a03aef4ba22', 'Sochidagi pyure 🤦‍♀️', 'Ovqatlanish vaqti jang maydoniga aylanadimi? Bolaning ovqatga tegishi va uni o‘rganishi sensor rivojlanishning bir qismidir. Dog‘larga e’tibor bermang.'),
  ('f1d99477-a71b-4368-b9eb-c5c699e49b39', 'Tabiat yordamga keladi 🌳', 'Juda injiqlik qilyaptimi va uyda o‘tira olmayaptimi? Ob-havo va kiyim yordamchisidan maslahat olib, darhol parkda 20 daqiqalik sayrga chiqing.'),
  ('2958c07b-39da-4ecb-ac79-c0f1640a7d1a', 'O‘zingizni solishtirmang 🛑', '“Falonchining bolasi allaqachon yuribdi” degan gapni unuting. Har bir bolaning rivojlanish sur’ati o‘ziga xos. Anacan Hamjamiyatida siz kabi fikrlaydigan onalar bilan dardlashing.'),
  ('da431940-9d6b-4ed8-a933-fd80b83687d9', '“Ona” so‘zini intiqlik bilan kutish 🥰', 'U turli bo‘g‘inlarni talaffuz qilyapti. Ilk bor ongli ravishda “Ona” yoki “Dada” deyishi juda yaqin! Ovoziga mehr bilan javob berib, uni ruhlantiring.'),
  ('f40e6c18-873e-481a-ba28-76a5634b977a', 'Musiqa — ruh ozig‘i 🎶', 'Kechga yaqin hech qanday sababsiz boshlanadigan injiqlikni mayin klassik musiqa bilan tinchlantirib ko‘ring. Ko‘pincha bu oddiy usul mo‘jiza yaratadi.'),
  ('288682cf-7f40-402e-a594-adaf2cbbed34', 'Yalangoyoq kashfiyotlar 👣', 'Uyda paypoq kiyib yurishni yoqtirmaydimi? Oyoq tagidagi nervlarning yer bilan tegishishi miya rivoji uchun juda foydali. Oyoqlari erkin bo‘lsin!'),
  ('2951ca5f-9454-4562-9820-3bfb3531edfd', 'Ro‘yxat hayotni osonlashtiradi 🛒', 'Xotira xiralashuvi sizni hamon tark etmayaptimi? Sovun tugadimi, mevalar kamayib qoldimi? Unutmasdan Xaridlar ro‘yxatiga yozing, qolganini juftingiz hal qilsin.'),
  ('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13', 'Jamoaviy yig‘ilish 🥂', 'Bugun kechqurun chaqaloq uxlagach, juftingiz bilan Kayfiyat kundaligini oching va bu haftadagi tartibsizliklar ustidan birga kuling.'),
  ('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1', 'Tishlar yana hujumda 🦷', 'Sababsiz yig‘lash milkdagi bosim tufayli bo‘lishi mumkin. Tish chiqishi kuzatuvchisini yangilang va muzlatilgan tishlash halqalarini oling.'),
  ('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af', 'Xona akustikasi 🤫', 'Uxlayotganda hatto kichik shovqindan ham uyg‘onib ketadimi? Shovqin o‘lchagich yordamida muhitni tekshiring va bir maromdagi oq shovqin bilan uyqusini qo‘llab-quvvatlang.'),
  ('cefb8b22-0318-4268-adf8-8f7052ad66cc', 'Uzoqdagi buyumni barmog‘i bilan ko‘rsatib, tovush chiqaryaptimi? ☝️', 'U sizga «menga qarang» yoki «buni xohlayman» demoqda. Bu muloqot rivojidagi katta sakrash!'),
  ('0c385e87-5c02-4870-85f8-9ab052891af8', 'Ona uchun vitamin 🥑', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi? Sog‘lom retseptlar bo‘limidan temir va kalsiyga boy yengil tushlikni tanlang.'),
  ('bda4f100-98ac-4f09-9fa3-a50d4e42eedd', 'Diqqat! 9 oy to‘lishiga atigi 10 kun qoldi!  🎂', 'Ushbu o‘zgacha sana uchun hozirdanoq kichik tort yoki oilaviy bayram g‘oyasini o‘ylab qo‘yish vaqti keldi.'),
  ('effeac28-8d9e-4d0e-b754-fb4004990432', 'Ekranlardan uzoqlashing 📱', 'Tungi uyqudan 1 soat oldin uydagi barcha televizor va ekranlarni o‘chiring. Melatonin ajralishi faqat tinch va qorong‘i muhitda tezlashadi.'),
  ('47fc8d5e-d99d-4104-9258-c8e18ad15266', 'Bu oqshomgi mavzu nima?🪄', 'Bu oqshom ertakni sun’iy intellekt yozsin: O‘yinchoqlarini izlayotgan mitti olmaxon. Tun sukunatini faqat sizning mehribon ovozingiz buzsin.'),
  ('856e1374-a46f-4ac4-b093-11e46392180f', 'Taqlidchi to‘tiqush 🦜', 'Sizning yo‘talishingiz, kulishingiz yoki qo‘l harakatlaringizga taqlid qilyaptimi? Xonadagi eng yaxshi ko‘zgu — sizsiz. Unga eng chiroyli yuz ifodalarini o‘rgating!'),
  ('e263bb82-67f5-4f23-9107-f117b8634a27', 'His-tuyg‘ularingizni erkin qo‘yib yuboring 📝', 'Ba’zan shunchaki eshikni yopib, yig‘lashni istaysizmi? Bu mutlaqo tabiiy... Yozish sizga yengillik beradi. His-tuyg‘ularingizni Kayfiyat kundaligiga yozing.'),
  ('73d0b947-9db1-4d57-a222-c8c22a2a895b', 'Xarakteri shakllanmoqda 🌟', 'U nimani yoqtirishi va nimani aslo istamasligini endi aniq ko‘rsatmoqda. Qaysarligi sizni charchatganda, bu aslida uning shaxsiyati shakllanayotganidan dalolat ekanini eslang.'),
  ('9596d063-607c-465f-9e92-b73f9f6f0ece', 'Onalar do‘stligi 💬', 'Qiyinchiliklarni baham ko‘rish yukni yengillashtiradi. Anacan hamjamiyatida siz bilan bir xil hislarni boshdan kechirayotgan minglab ayollar bor. Dardlashish bepul.'),
  ('fb27143e-60bd-4519-b45e-80c5584417a4', 'Dadaning taskini 🫂', 'Tungi injiqliklarni yolg‘iz hal qilishga urinmang. Turmush o‘rtog‘ingizni ham bu jarayonga jalb qiling. Ba’zan boshqa hid va quchoq chaqaloqni bir zumda tinchlantiradi.'),
  ('4e869b86-0b42-4c4a-86f7-22a0999a3387', 'Qarsaklar jamoasi 👏', 'Quvonchini qarsak chalib ifodalayaptimi? Bu ajoyib motorika yutug‘ini Rivojlanish kuzatuvchisiga qayd etib, uyda kichik g‘alaba raqsini ijro eting.'),
  ('72a32149-c4d7-4a45-b296-5cc7c5b673ad', 'Tezkor tekshiruv 🤖', '9 oylik chaqaloq rivojlanishidan nimalar kutiladi? Uzun maqolalarni qo‘ya turing. Savolingizni to‘g‘ridan-to‘g‘ri Anacan AIga bering va pediatr aniqligidagi javobni oling.'),
  ('df74b674-d83b-4306-a6c3-1477bd965efe', 'Uyquga tayyorgarlik 🛀', 'Iliq vanna har doim yordam beradi. Kechki tartibni aslo buzmang, chunki u chaqaloq miyasiga uxlash vaqti kelganini bildiradi.'),
  ('3c29a397-ae21-4b66-9ae6-c3001d2f3e36', 'U sizga qarayapti 👀', 'Xonaning qayerida bo‘lmang, uning nigohi sizda. Siz uning uchun xavfsiz panohsiz. Sabringiz tugaganda, uning mana shu cheksiz mehrini eslang.'),
  ('b3560b09-ab82-494c-a5e9-d6be5d4cb35a', 'Tartibsizlik san’ati 🌪️', 'O‘ynagan barcha narsasini atrofga sochib tashlaydi. Hozir tozalik emas, sizning dam olishingiz muhim. O‘yinchoqlar ertaga ham o‘sha yerda bo‘ladi, ammo tetik ona hozir kerak.'),
  ('fe563692-e0de-40b2-aa34-9d6335348a54', 'Tun sukunati 🤫', 'Mashinalar yoki tashqaridan kelayotgan tovushlar uni bezovta qilsa, fonda doimiy oq shovqin manbai bo‘lishini ta’minlang.'),
  ('268d0edd-f8c9-45fd-af24-4b1bd27e458d', 'Dadaning massaj saloni 💆‍♀️', 'Turmush o‘rtog‘ingiz bolani uxlatib, so‘ng taranglashgan bo‘yin mushaklaringiz uchun 5 daqiqalik massaj uyushtirsin!'),
  ('38581365-03a6-48aa-a7b4-923dde40764d', 'Zinapoyaga qiziqish 🧗‍♂️', 'Uyda zinapoya yoki baland joylar bo‘lsa, u o‘sha tomonga intiladi. Xavfsizlik to‘siqlarini o‘rnatishning ayni vaqti keldi.'),
  ('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf', 'Ovqatlanish janglari 🥣', 'Pyureni chetga suryaptimi? Majburlab yedirmang. Uning ovqatga munosabatini buzmaslik uchun jarayonni o‘yinga aylantiring va hamjamiyatdagi muqobil retseptlarni o‘qing.'),
  ('5626563e-1119-4751-a2d2-ad651cb7961b', '9 oy-u 5 kun! 🎈', 'Bir yoshga to‘lishiga juda oz qoldi! Tort, kichik bezaklar yoki shunchaki uydagi eng chiroyli kiyimlar... Chaqaloq fotosessiyasiga tayyorgarlikni tezlashtiring.'),
  ('5e8f6838-89c2-40a6-940e-2ef8b752a179', 'Birgalikdagi xotiralar 📸', 'Shunchalik chiroyli jilmayadi-ya! Uxlashidan oldin uning beg‘ubor yuzini suratga oling, bu lahzalar boshqa qaytib kelmaydi.'),
  ('912ca02c-47d0-4e27-8bdb-7afe9ba868be', 'Temir zaxirasi 🥩', 'Kamqonlik bolaning ishtahasi va quvvatini pasaytirishi mumkin. Ovqatlanish tartibini ko‘rib chiqing va zarur bo‘lsa, Anacan AI’dan temirga boy oziq-ovqatlar haqida so‘rang.'),
  ('0135df6f-fe6e-4faf-9136-dc65b2b29e33', 'Xayrlashish vaqti 👋', 'Kimdir uydan ketayotganda qo‘l silkitib xayrlashadimi? Bu ijtimoiy rivojlanishning juda yoqimli belgisidir! Uni ko‘proq rag‘batlantiring.'),
  ('44260d05-153e-4b6b-b9dd-6f07fb02c462', 'Sokinlik izlab ⛅', 'Zo‘riqish kuchayganda eng yaxshi yechim — tashqariga chiqish. Ob-havoni tekshiring, chaqaloqni aravachaga joylashtiring va shunchaki sayr qilib, fikringizni tiniqlashtiring.'),
  ('67247d93-ddf7-4fcc-adef-5828dde725b4', 'Mukammallik illyuziyasi 🛑', 'Bugun hech narsa reja bo‘yicha ketmadimi? O‘zingizni ayblamang. Siz haqiqiy onasiz, ijtimoiy tarmoqlardagi filtrlangan illyuziya emassiz.'),
  ('4e8edba3-fd16-4c28-a7ff-08ff9853211e', 'Kundalik mayda ehtiyojlar unutilib qoladi. 🛒', 'Taglik tugadimi yoki nam salfetkami? Xaridlar ro‘yxatiga qo‘shing, turmush o‘rtog‘ingiz marketdan qaytayotganda olib kelsin.'),
  ('5f49ad4f-107b-4550-adae-e4aab3aa9d5b', 'Ikki mahal kunduzgi uyquga o‘tish 🥱', 'Kunduzi 3 marta uxlaydigan bolangiz endi oxirgi uyquga qarshilik qilyaptimi? U ulg‘aymoqda! Uyqu jadvalini 2 mahal kunduzgi uyquga moslashtirish vaqti keldi.'),
  ('8750f5ee-e089-418c-9d9b-a881ca3441c3', 'Sehrli ertaklar olami 🪄', 'Aqlli ertaklarda atigi 5 kundan keyin 9 oylik bo‘ladigan katta qahramoningiz haqida hikoya yarating.'),
  ('7ee44a70-ee6e-4b49-a487-76ff5581f580', 'Jasoratli qadamlar 🧗‍♂️', 'Mebeldan ushlab, bir qo‘lini qo‘yib yuborishga urinyaptimi? Uning muvozanatni saqlash qobiliyati rivojlanmoqda. Qo‘lidan tuting va unga biroz ishonch bag‘ishlang.'),
  ('97d44a72-2ca4-4c0f-b997-91c31aeabbef', 'Birdamlik suhbati 🥂', 'Kayfiyat kundaligini oching va turmush o‘rtog‘ingiz bilan bu oylar sizlarni qanday o‘zgartirganini muhokama qiling. Bir jamoa bo‘lish — eng katta kuch.'),
  ('ff86bc54-face-4f54-a1de-cc0ec9cccbc2', 'Hammasi joyida ✔️', 'Ba’zan qo‘rquvlar sizni yengib qo‘yadimi? Chaqalog‘ingizning toza kiyimiga, to‘q qorniga va sizga kulib boqayotgan ko‘zlariga qarang. Siz hammasini ajoyib uddalayapsiz!'),
  ('00632cb5-4d20-4f2d-9bf8-82242042667b', 'Sehrli ertak vaqti 🪄', 'Bu oqshom boshqacha ertak ayting: uxlashni yaxshi ko‘radigan sehrli bulut haqida. Ovozingizni pasaytirib, ertakona muhit yarating.'),
  ('61c9e192-532e-41bc-9ebb-f2c296bb0670', 'Ruhiy yukingizni bo‘lishing 💬', 'Anacan hamjamiyatiga qo‘shiling. Ba’zan notanish onaning izohini o‘qish qahvadan ham ko‘proq quvvat beradi.'),
  ('92c6be75-a837-4908-b755-b4ae97896380', 'Xavfli joylarga qiziqish ⚡', 'Rozetkalar va kabellar uning e’tiborini tortadi. Uydagi taqiqlangan joylarni aniq belgilab, xavfsizlik choralarini yana bir bor tekshiring.'),
  ('159ac401-c76f-42ec-b9e1-bb1a6d73130e', 'Pinsetsimon ushlash bilan kashfiyotlar 🤏', 'U yerdagi eng mayda chiqindini ham barmoq uchlari bilan topib oladi! Uning nozik motorikasi juda yaxshi rivojlangan.'),
  ('306f7e64-ae54-408a-95b9-ac4f9c3c6684', 'Tungi orom 🛀', 'Kundalik tartibni o‘zgartirmang. Har doimgidek bir xil vanna, bir xil massaj moyi va o‘sha qorong‘i xona — yaxshi uyquning oltin kalitidir.'),
  ('f3512bb1-5e87-4250-8249-5c396829b593', 'To‘rt devor sindromi ☕', 'Uyda siqilyapsizmi? Onalar uchun qulay joylar orasidan siz toza havodan bahramand bo‘ladigan, chaqaloq esa o‘zini qulay his qiladigan eng yaqin maskanni toping.'),
  ('55476184-e000-441a-91f6-32b219ce5489', 'Ertaga katta kun! 🎉', 'Roppa-rosa 9 oy! Kiyimlarni tayyorlab qo‘ydingizmi? Telefon xotirasini bo‘shating, ertaga chaqaloq fotosessiyasi uchun juda ko‘p joy kerak bo‘ladi!'),
  ('801186a2-f617-44a4-bfbe-39fa8b84707d', 'Tungi alla 🎶', 'Bugun kechqurun xonani butunlay qorong‘i qiling. Hech qanday texnologiyasiz, faqat sizning mayin ovozingiz.'),
  ('bcabe7b8-3e78-42a9-bdf0-3f1883219079', 'Og‘riyaptimi yoki charchaganmi? 😭', 'Chaqaloq sababsiz yig‘laganda o‘zingizni yo‘qotib qo‘ymang. Yig‘i tahlilidan yordam oling, muammoni tezda aniqlab, hal qiling.'),
  ('327e6e73-14c5-44c7-86f9-1b01671cc4cc', 'Ortga nazar 📈', 'Farzandingiz qancha yo‘l bosib o‘tdi? Ilk kunlardagi hayajon o‘rnini ishonch egalladi. Siz bu yo‘lni katta muvaffaqiyat bilan bosib o‘tdingiz!'),
  ('4b865d9a-0f66-4cb0-98d0-deaa6f061766', 'Biroz romantika 💖', '9 oyning charchog‘i va faxrini bugun kechqurun turmush o‘rtog‘ingiz bilan sham yorug‘ida nishonlang. Siz mukammal jamoasiz!'),
  ('8be43b5a-b4b9-49ba-b74f-59b204783156', 'Roppa-rosa 9 oy! 🎂', 'Tabriklaymiz! Tug‘ruqdan beri roppa-rosa 9 oy o‘tdi. U 9 oy qorningizda, 9 oy bag‘ringizda ulg‘aydi! Bu ajoyib lahzani nishonlang va xotirangizni hamjamiyatda ulashing!'),
  ('334b387f-4019-4208-b951-95f53c679a8b', 'Energiyaga ehtiyoj 🍲', 'Charchoq butun vujudingizni qamrab oladi. Sog‘lom retseptlardan 10 daqiqada tayyorlanadigan, temir va oqsilga boy tushlikni tanlab, kuch to‘plang.'),
  ('495a74f3-0952-464a-80e0-08b1cc46205c', 'Shovqinni nazorat qiling 🤫', 'Uydagi shovqin uning chuqur uyqusini buzadi. Siz ham bemalol dam olishingiz uchun shovqin o‘lchagich yordamida fon tovushini bir maromda saqlang.'),
  ('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1', '«Yo‘q» so‘zining kuchi 🛑', 'Endi yoqtirmagan ovqatini chetga surib, boshini chayqagancha «yo‘q» deyaptimi? Uning shaxsiyati shakllanmoqda! Irodasini hurmat qiling.'),
  ('5238f2b7-2892-49ff-9220-f07d0cf3221d', 'Kunduzgi charchoqning o‘zi sizga yetadi. 👨‍🍼', 'Kechga yaqin chaqaloq bilan xonada dumalab, o‘yin o‘ynash — faqat dadasining vazifasi.'),
  ('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede', 'Xazina izlash 🧺', 'Kir savatini bo‘shatish yoki shkaflarni titkilash uning eng sevimli mashg‘uloti. Bemalol o‘ynashiga imkon bering, bu uning harakat ko‘nikmalarini rivojlantiradi.'),
  ('f0057ec1-cc62-4ea5-9364-5327660ddc30', 'So‘rashdan tortinmang 🤖', 'Bolalar ovqatiga qaysi ziravorlarni qo‘shish mumkin? Ikkilanayotgan barcha savollaringizni Anacan AI’dan darhol so‘rab, ko‘nglingizni xotirjam qiling.'),
  ('1835b0bb-3338-4b12-9da9-167cd1643dc6', 'Uy ishlarini kim qiladi? 🌪️', 'Changyutgichning ovozi uni qo‘rqityaptimi, ishlar qolib ketyaptimi? Qolaversin. Juftingizdan bugun uy ishlarini o‘z zimmasiga olishini so‘rang.'),
  ('be2205ed-6711-45b7-b2f3-ab21216eef54', 'Hissiyotlar kundaligi 📝', 'O‘zingizni yolg‘iz his qilganingizda, Kayfiyat kundaligiga his-tuyg‘ularingizni yozing. Barcha ayollar bu yo‘llardan o‘tadi, siz kuchlisiz.'),
  ('cd0245fe-8c0d-4f3e-ad23-05cff2186013', 'Chiqindilar tadqiqotchisi 🗑️', 'U polda nima topsa, katta qiziqish bilan o‘rganadi. Hamma narsani qo‘lidan olib, jahlingiz chiqmasin — u tadqiqotchi. Shunchaki uni nazorat qilib turing.'),
  ('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638', 'Dadaning taskini 🫂', 'Chaqaloq tunda uyg‘onganida bir safar siz, keyingi safar juftingiz tursin. Ba’zan chaqaloqqa faqat dadasining bir maromdagi silashi yaxshi ta’sir qiladi.'),
  ('77c04114-1662-45d9-9778-494a99f15f4f', 'Ob-havoga aldanmang ⛅', 'Sayrga chiqishda derazadan qarab qaror qilmang. Ob-havo va kiyim vositasi yordamida chaqaloqni qatlamlab kiyintirishda eng maqbul me’yorni toping.'),
  ('b630415b-1d8a-4088-bd37-659e6494cb2c', 'O‘yinchog‘imni bermayman! 🧸', 'Qo‘lidan biror narsani olganingizda qarshilik ko‘rsatib, yig‘laydimi? Unda egalik va o‘ziga xoslik hissi rivojlanmoqda. Bu juda tabiiy psixologik bosqich.'),
  ('5c4470d4-31c9-42e6-98b2-6ebad58cdce5', 'Ovozidagi g‘alati ohang sababini tushunmayapsizmi?  😭', 'Darhol Yig‘i tahliliga eshittiring va muammo tish chiqishidami yoki qorin dam bo‘lishidami — bilib, xotirjam bo‘ling.'),
  ('906becee-91c7-4860-a453-bec23a80f855', 'Sokinlik zarurati 🤫', 'Xonadagi sokinlikni Ovoz o‘lchagich yordamida saqlang. Tunda bo‘lingan uyqu chaqalog‘ingizning ham, sizning ham ertalabki kayfiyatingizni buzadi.'),
  ('93f3b238-cc16-44a9-888c-f9d77043f372', 'Musiqaga raqs 🎶', 'Quvnoq musiqa yangraganda ritmga mos tebranadimi? Bu eshitish qobiliyati va harakat ko‘nikmalari o‘rtasidagi bog‘liqlik shakllanayotganidan darak! Quvnoq qo‘shiq qo‘yib, u bilan raqsga tushing.'),
  ('334464c1-4599-4dd4-83dd-d57c384eb650', 'Kitob sahifalarini varaqlaydi 📖', 'Qalin sahifali kitoblarning varaqlarini ochishga harakat qiladimi? Unga ko‘plab rang-barang va paypaslab ko‘rish mumkin bo‘lgan ertak kitoblarini olib bering.'),
  ('d7009029-eb30-44cd-bedc-77f2ddcbdbe4', 'Pyuredan bo‘lakchali ovqatlarga! 🍲', 'U endi chaynashni talab qiladigan ovqatlarni yeya oladimi? Ilovamizdagi pyure va sho‘rvalarning turli tuzilishga ega retseptlarini Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar bo‘limidan sinab ko‘ring.'),
  ('f5716668-d412-4d80-9c29-0a69a23f4f4e', 'Xaridlar ro‘yxati 🛒', 'Ovqat tayyorlash uchun brokkoli yoki suli tugadimi? Xaridlar ro‘yxatini darhol to‘ldiring va kerakli mahsulotlar ro‘yxatini turmush o‘rtog‘ingizning telefoniga yuboring.'),
  ('16369cf1-7620-428e-8c38-c6f5104fb5ab', 'O‘yinchoqlarini qutidan chiqaradi! 🧸', 'U buyumlarni qutidan birma-bir chiqarib, uloqtirishni yaxshi ko‘radi. Bu quvnoq va biroz tartibsiz kashfiyot lahzasini Chaqaloq fotosessiyasi yordamida suratga olib, keyin kulib eslang.'),
  ('912a7ba7-5cb9-41f1-9daa-dc1c800036eb', 'Ilk qadamlar yaqinmi? 🧗‍♂️', 'U divandan ushlab o‘rnidan turish bilan cheklanmay, devor bo‘ylab yurayaptimi? Xavfsizlik choralarini ikki barobar kuchaytiring.'),
  ('ec70551b-eda4-4e87-86a9-151235d2eb3e', 'Ertak tinglab uxlaydi 🪄', 'Aqlli ertaklarda jasur va yoqimtoy hayvonlar haqida hikoya yarating va xonani sehrli makonga aylantiring.'),
  ('39498b75-8a2a-463e-a232-aa6ed7188810', 'Ovoz ohangingizni tushunadi 🗣️', 'Jiddiy ohangda «yo‘q» desangiz, to‘xtab, sizga qaraydimi? U endi his-tuyg‘ular va taqiqlarni anglay boshlagan!'),
  ('6d030e22-f99a-4fa8-829a-d62a50ce76e0', 'Rivojlanishni tekshirish 🤖', 'Farzandingizning jismoniy harakatlari rivojlanishida kechikish bor deb o‘ylaysizmi? Anacan AI’dan 9 oylik chaqaloqning motorika ko‘nikmalari haqida aniq ma’lumot oling.'),
  ('e607d1aa-9be0-4388-9790-764a5c1e94da', 'Hazm jarayonini kuzatamiz. 🧷', 'Qattiq ovqatlar ich kelishini o‘zgartiradi. Har bir taglik almashtirishni Anacan’da qayd etib, chaqalog‘ingiz salomatligini tahlil qiling.'),
  ('57fa0aeb-432f-4b34-915b-98422c100236', 'Tish chiqishidagi og‘riqlar 🦷', 'Milklari yana qizarib, so‘lagi tinmay oqyaptimi? Sovutilgan tishlagichlarni tayyorlab qo‘ying.'),
  ('bda23a3e-0646-4246-a5dc-febd245b2bb1', 'Qaysi ko‘krakdan emizganingizni unutdingizmi? 🤱', 'Anacan taymeri o‘ng yoki chap ko‘krakdan emizganingizni siz uchun eslab qoladi. Emizishni hoziroq taymer bilan boshlang!'),
  ('e2296439-aad7-4bdf-a627-05d1e066a3d8', 'Uyqu me’yorlarini kuzatib boring. ⏱️', 'Chaqalog‘ingiz uxlayotganda uyqu taymerini yoqing va grafik orqali uning 9 oylik chaqaloqlar uchun kunlik uyqu me’yoriga amal qilayotganini tekshiring.'),
  ('13322f59-d734-452d-8178-1ffb4e5e9f78', 'Kresloga tirmashish 🧗‍♂️', 'Polda yurish unga kamlik qilib, mebellar ustiga chiqishga urinyaptimi? Harakat ko‘nikmalari jadal rivojlanyapti! Uni albatta nazorat ostida saqlang.'),
  ('b349c13b-d822-42ec-876c-d41ccb790846', 'Toza havo — davo 🌳', 'Kun bo‘yi yig‘lab, bezovta bo‘ldimi? Yechimi juda oddiy: ob-havoni tekshiring, mos kiyintiring, aravachaga o‘tqazing va darhol parkka chiqing.'),
  ('e46eb59c-0196-4f8a-b3f3-e86458e1f828', 'Xona akustikasi 🤫', 'Uyqu paytida hatto kichik bir qirsillagan tovush ham uni uyg‘otadi. Shovqin o‘lchagich yordamida muhitni tahlil qiling va uzluksiz sokinlikni ta’minlang.'),
  ('1b15944e-9198-4fc4-b86d-0b17af6cdd00', 'Shifokordan nimalarni so‘rashim kerak? 🤖', 'Oylik ko‘rikka borishdan oldin nimalarni so‘rashni bilmayapsizmi? Anacan AI’dan 9 oylik tekshiruvlar ro‘yxatini so‘rang.'),
  ('1eda7621-0a6a-4ff0-8efe-ec931b28a106', 'Uyning kichkina yordamchisi 🧺', 'Siz kiyimlarni taxlayotganingizda, u ham kelib ularni sochib, yordam beradimi? Uni bu jarayondan chetlatmang, qo‘liga bitta sochiq bering.'),
  ('59e058ca-af20-4537-9c74-8aa7eb175af6', 'Tuyg‘ularingizni erkin qo‘yib yuboring 📝', 'Kechki payt qahvangizni olib, Kayfiyat kundaligiga o‘tgan oylardagi va hozirgi his-tuyg‘ularingizni taqqoslab, kichik bir qayd yozing.'),
  ('30a7e68c-862a-436f-a801-8270fce13b90', 'O‘zingizni asrang 🍲', 'Siz sog‘lom bo‘lsangiz, u ham sog‘lom bo‘ladi. Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan yengil ona salatini tanlang va tanovul qiling.'),
  ('32607011-b168-4558-b64b-8c8947e8d9a9', 'Iliq vanna, massaj va xonani qorong‘ilashtirish. 🛀', 'Uyqu tartibiga rioya qilish — tun bo‘yi uzluksiz uxlashning eng asosiy siridir.'),
  ('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08', 'Turli bo‘g‘inlar va to‘liq gapirishga urinishlar 🗣️', 'U xuddi to‘liq gap tuzayotgandek, o‘z tilida uzoq-uzoq gapiradi. Xonadagi eng yoqimtoy suxandonni diqqat bilan tinglang!'),
  ('3ab1636f-ed5f-47f5-93d7-4ac521edd386', 'O‘zingizni yetarlicha yaxshi emasdek his qilyapsizmi? 💬', 'Darhol Anacan hamjamiyatiga kiring, boshqa onalarning qo‘llab-quvvatlovchi izohlarini o‘qib, ko‘nglingizni tinchlantiring.'),
  ('62964d86-1e07-4c7f-a135-52c48581ffc5', 'Bugun hammasi ostin-ustun bo‘ldimi?', 'Hechqisi yo‘q, farzandingizning qorni to‘q va ust-boshi toza bo‘lsa, siz dunyodagi eng yaxshi onasiz.'),
  ('fa0817a9-00d2-41fc-bdcb-8fdae95932ff', 'Buyumlarning nomini o‘rganmoqda 🧸', '“To‘p qayerda?” deb so‘raganingizda, uni ko‘zlari bilan izlab topadimi? Anglash qobiliyati rivojlanmoqda! U bilan buyumlarning nomini aytib, o‘yinlar o‘ynang.'),
  ('93f4fd0f-1f45-436c-b46b-7acc69d1b899', 'Ikki oyoqda muvozanat saqlash 🤸‍♂️', 'Qo‘ltiqlaridan tutganingizda oyoqlarida yanada tik va mustahkam turadimi? Rivojlanish kuzatuvchisida ushbu asosiy qadam tashlash refleksini albatta qayd eting!'),
  ('b0bdf4f4-2902-43a5-876f-e99b39aef4f9', 'Sehrli ertak vaqti 🪄', 'Aqlli ertaklardagi “Kichkina qahramonning uxlab qolish sirlari” hikoyasi bilan kechki tartibingizga rang-baranglik qo‘shing.'),
  ('c6da7887-a402-4a11-8fbf-8de4d7696325', 'Ro‘yxat — haqiqiy najotkor 🛒', 'Kundalik uy-ro‘zg‘or ehtiyojlari tugamaydi. Boshingizni qotirmang, Xaridlar ro‘yxatini to‘ldiring va ishdan qaytayotgan dadasi najotkoringiz bo‘lishini kuting.'),
  ('72b7b721-7f37-4054-90fd-05ac29f9ff3c', 'Bezovtalikka qarshi ovoz terapiyasi. 🎶', 'Agar bu oqshom chaqalog‘ingiz bezovta bo‘lsa, Oq shovqinlar ichidan ona qornidagi tovushni yoqib, uni darhol tinchlantiring.'),
  ('761f9ba9-87d1-4b16-a40a-f1ec2385a5fd', '10 oylikka tayyorgarlik! 🎂', 'Diqqat! Atigi 10 kundan keyin kichkintoyingiz 10 oylik bo‘ladi! Ikki xonali oyga o‘tish munosabati bilan maxsus tort buyurtma qilishni unutmang!'),
  ('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9', 'Ertak tinglab uxlaymiz 🪄', 'Aqlli ertaklarda jasur va yoqimtoy hayvonlar haqida hikoya yarating va xonani sehrli makonga aylantiring.'),
  ('19eac11a-ecf7-498d-85e1-95d4f484d466', '10 oylikka 10 kun qoldi! 🎈', 'Muhim sanaga 10 kun qoldi! Chaqaloq fotosessiyasi vositasida maxsus ramkalarni hozirdanoq tanlab, fotosessiyani rejalashtiring.'),
  ('36d1de0a-5eb5-4e0f-98ce-a583a10b254e', 'Ob-havoga aldanmang ⛅', 'Sayrga chiqayotganda faqat derazadan qarab qaror qilmang. Ob-havo va kiyim vositasi yordamida chaqaloqni qatlamlab kiyintirishda me’yorni toping.'),
  ('ea9b5851-8f4a-4a19-990c-97e725808bb5', 'Dadaning allasi 👨‍🍼', 'Bu kecha uxlash oldidan aytiladigan barcha allalar va ertaklar dadasining zimmasida.'),
  ('3908e4ee-6364-4b5e-bf19-9883638e23db', 'Xonadagi ovoz 🤫', 'Uxlab qolish qiyinlashdimi? Ovoz o‘lchagich yordamida xonadagi desibel darajasini tekshiring va televizor ovozini fon darajasigacha pasaytiring.'),
  ('ce7b77f8-95b5-4071-bf35-61b06d785d85', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dildan suhbatlashing. Bir-biringizni qo‘llab-quvvatlash yukni yengillashtiradi.'),
  ('fab0e5e3-a0d0-40d0-843b-ff548b4b816f', '“Kel-kel” jamoasi 👏', 'Qo‘llari bilan “kel-kel” ishorasini qilishni o‘rgandimi? Bu yoqimli taqlidni albatta videoga olib, xotiralar albomingizga qo‘shing.'),
  ('0b91a5b0-1518-4473-b0bb-59cec89d7f6f', 'Suhbatlar yanada rang-barang bo‘lmoqda! 🗣', '️ “Ma-ma”, “ba-ba” bo‘g‘inlari bilan tuzayotgan yoqimli suhbatlarini yanada foydali qilish uchun Bloglardagi nutq rivoji bo‘yicha tavsiyalarni o‘qing.'),
  ('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5', 'Sut miqdorini oshirishga yordam beradigan mahsulotlar. 🍲', 'Ayollar uchun sog‘lom retseptlar bo‘limidagi sutni ko‘paytirishga yordam beruvchi sho‘rvalarni bugun tayyorlab ko‘ring va quvvatga to‘ling.'),
  ('db929314-83ca-4372-8890-03ef676e68e5', 'Sababini topa olmayotgan yig‘i xurujlari odamni holdan toydiradi. 😭', 'O‘zingizni qiynamang, Yig‘i tahlilidan foydalaning va muammoning asl sababini aniqlang.'),
  ('14c6187e-df8b-47e8-b44f-9bc87c4b9143', 'Tun sukunati 🤫', 'Mashina yoki tashqaridagi tovushlar uni bezovta qilsa, orqa fonda doimiy oq shovqin manbaini albatta yoqib qo‘ying.'),
  ('36c8e54c-04ef-4b47-9a2f-c0754b0990c9', 'Yiqilib-turib o‘rganish 🧗‍♂️', 'Divandan ushlab yurganida dumbasi bilan yiqilib, yana turadimi? U qiyinchiliklarni yengishni o‘rganmoqda. Xavotirga tushmasdan, unga dalda bering.'),
  ('c0c6e209-b8c8-4325-bc8e-9d4231949abd', 'Tish chiqishidagi og‘riqlar 🦷', 'Milklari yana qizarib, so‘lagi tinmay oqyaptimi? Sovuq tish qashlagichlarni tayyorlab qo‘ying.'),
  ('65f53c0c-e8ea-4257-8798-e79b9ed847be', 'Siz nima yesangiz, u ham shuni xohlaydi 🥣', 'Likopchangizdagi hamma narsaga qo‘l uzatyaptimi? Uning ovqatga qiziqishi eng yuqori darajada. Unga o‘zi qo‘lida ushlab yeyishi mumkin bo‘lgan kichik bo‘lakli taomlar bering.'),
  ('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4', 'Hissiyotlar kundaligi 📝', 'O‘zingizni yolg‘iz his qilganingizda, Kayfiyat kundaligiga his-tuyg‘ularingizni yozing. Yozish o‘zingizni yaxshiroq his qilishingizga yordam beradi.'),
  ('d2c3bcc6-5492-42b4-857f-d6ad8a442199', 'Rivojlanishni tekshirish 🤖', 'Qo‘shimcha ovqatlantirish haqida savollaringiz bormi? Anacan AI-dan 9 oylik chaqaloq menyusi haqida ma’lumot so‘rang.'),
  ('3995ea79-4422-4b71-b376-6426966b7d85', 'Toza havo — davo 🌳', 'Kun bo‘yi yig‘lab, bezovta bo‘ldimi? Yechimi juda oddiy: ob-havoni tekshiring, mos kiyintiring, aravachaga o‘tqazing va darhol parkka chiqing.'),
  ('b67edfc6-e141-41a3-866c-78583fe5c77b', '10 oylikka atigi 5 kun qoldi! 🎂', 'Muhim sanaga juda oz qoldi! 10 oylik torti va kiyimlarini tayyorlashning ayni vaqti. Bir yoshga qadamma-qadam yaqinlashyapsiz!'),
  ('da354848-a7ac-41ba-9616-ccf0b8799a86', 'Uyqu belgilari 🥱', 'Ko‘zlarini ishqalab, bir nuqtaga tikilib qolsa, injiqlik xuruji boshlanishini kutmang. Darhol xonani qorong‘ilating va uyquga tayyorlash odatlarini boshlang.'),
  ('049b837c-5a26-4c32-95e4-e745b4a3443b', 'Qo‘lidan biror narsani olganingizda qarshilik qilib, yig‘layaptimi? 🧸', 'Unda egalik va o‘ziga xoslik hissi rivojlanmoqda. Bu mutlaqo tabiiy psixologik bosqich.'),
  ('06a37325-84f4-4012-b4a0-ff317ba78e4c', 'Xayr-xayr deymiz! 👋', 'Ketayotganlarning ortidan qo‘l silkitishni o‘rgandimi? Uning bu anglangan va yoqimli harakatini chaqaloq fotosessiyasi orqali darhol xotiraga muhrlang.'),
  ('69b02f6b-1a0a-4f09-860a-f56dfb370b0a', 'Uyda xavfsizlik choralarini ko‘ring! 🛡', '️ U oyoqqa turishga uringani sari xavf-xatarlar ortadi. Bolalar uchun xavfsizlik qulflari va burchak himoyalagichlarini topish uchun Tavsiya etilgan mahsulotlar ro‘yxatimizni albatta ko‘rib chiqing.'),
  ('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6', 'O‘zingizga vaqt ajrating. 🛁', 'Farzandingiz uxlayotganda, soch va teringizni parvarish qilib, dam oling.'),
  ('87dbc3cb-466d-4628-b1df-07cce718a3ab', 'Mustaqil ovqatlanishdan zavqlanadi! 🥦', 'Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan ushlash oson bo‘lgan foydali tamaddilar tayyorlang.'),
  ('9b804616-ae80-4d37-b6a9-76004e3e5506', 'Oddiy ko‘rsatmalarni tushunadi! 🧠', '“Buni menga ber” desangiz, o‘yinchoqni sizga uzatadimi? Tafakkur rivojidagi bu sakrashni qo‘llab-quvvatlash uchun Bloglardagi rivojlantiruvchi maqolalarni o‘qing.'),
  ('dffa4555-16c2-4705-a09e-e04f9ae6d25d', 'Ishlar qolib ketyaptimi? Qolaversin.  🌪️', 'Turmush o‘rtog‘ingizdan bugun uy ishlarini o‘z zimmasiga olishini so‘rang. Siz esa dam oling.'),
  ('f2c9cd05-6f08-42dc-b88f-310abadaba89', 'Tun osoyishtaligi 🛀', 'Iliq vanna, massaj va xonani qorong‘ilashtirish. Uyqu tartibiga rioya qilish — tun bo‘yi uyg‘onmasdan uxlashning eng asosiy siridir.'),
  ('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85', 'Yerdan topgan har bir narsani katta qiziqish bilan o‘rganadi.  🗑️', 'Hamma narsani qo‘lidan olib, jahlingiz chiqmasin — u kichkina tadqiqotchi. Shunchaki uni nazorat qilib turing.'),
  ('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6', 'Aqlli ertak vaqti 🪄', 'Bu oqshom boshqacha ertak ayting: uxlashni yaxshi ko‘radigan sehrli bulut haqida. Ovozingizni pasaytirib, ertaknamo muhit yarating.'),
  ('ae31e811-95f5-438c-9d8f-7b39b14eed84', 'Buyumlarni joyiga qo‘yishga urinish 🧸', 'O‘yinchoqni qutiga solib, yana chiqaradimi? U «ichida» va «tashqarisida» tushunchalarini o‘rganmoqda.'),
  ('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981', 'Suv ichish odatini shakllantiramiz. 💧', 'Qo‘shimcha ovqat bilan birga suv taklif qilishni unutmang. Qaysi suv ichish idishlari mosroq ekanini Tavsiya etilgan mahsulotlar bo‘limidan osongina toping.'),
  ('0b7b3ea8-6539-4606-ac0b-b0428466ace0', 'Taqlidchi to‘tiqush 🦜', 'Yo‘talishingiz yoki kulishingizga taqlid qiladimi? Xonadagi eng yaxshi ko‘zgu — siz. Unga eng chiroyli yuz ifodalarini o‘rgating!'),
  ('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2', 'Onalar uchun quvvat bombasi! 🥗', 'Harakatchan chaqaloq ortidan yugurish kuch talab qiladi! Ayollar uchun sog‘lom retseptlardan foydalanib, vitaminlarga boy salat yoki smuzi tayyorlang.'),
  ('a261deac-e213-48df-a6bd-e43793de79c9', 'Dadaning massaj saloni 💆‍♀️', 'Juftingiz bolani uxlatib qo‘ysin, keyin esa taranglashgan bo‘yin mushaklaringiz uchun yelkangizni 5 daqiqa massaj qilsin!'),
  ('249e422f-5203-4598-a063-3032744aab4c', 'Suv ichishga o‘jarlik 💧', 'O‘z piyolasini mustaqil ushlab ichmoqchi, ammo suvning ko‘pini ustiga to‘kib yuboryaptimi? Uning mustaqil bo‘lishga urinishlarini qo‘llab-quvvatlang, nam salfetkalar shunday vaziyatlar uchun-da.'),
  ('88ed955b-e80f-4226-9234-7112a99a4951', 'Juftingizning quvvat olish vaqti 🔋', 'Kunduzi butun kuchingizni bolaga berdingiz. Bugun kechqurun bolaga juftingiz qarasin, siz esa oflayn rejimga o‘ting.'),
  ('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb', 'Tayanchsiz ilk soniyalar 🧗‍♂️', 'Divandan ushlab turganida birdan qo‘llarini qo‘yib yuboryaptimi? U muvozanatni saqlashni o‘rganyapti! Qisqa, ammo hayajonli bu soniyalarda yiqilib ketmasligi uchun diqqat bilan yonida turing.'),
  ('80ecdccb-340a-49ab-94a9-ff073855c0a0', 'Nima pishirsam ekan? 🍲', 'Qo‘shimcha ovqat menyusi uchun g‘oyalaringiz tugadimi? Internetda ovora bo‘lmang. Anacan AI’dan 10 oylik chaqaloq uchun oson yeb olish mumkin bo‘lgan taomlar ro‘yxatini so‘rang.'),
  ('b8e6e605-baf6-44b6-9e44-842e0b7a0af0', 'Suhbatga qo‘shilyapti 🗣️', 'Siz telefonda gaplashayotganingizda u ham o‘z tilida nimalarnidir aytib, ovozini balandlatyaptimi? Muloqot ko‘nikmalari jadal rivojlanyapti — xonada endi ikkinchi notiq bor!'),
  ('c9db13f9-8aff-4b71-a7fa-bdce47336917', 'Birdan qichqirib uyg‘ondimi? 😭', 'Tungi vahima boshlanayotgan bo‘lishi mumkin. Ovozini Yig‘i tahliliga eshittirib, muammo jismoniy yoki ruhiy ekanini aniqlashtiring.'),
  ('7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'Ochmi yoki charchaganmi? 😭', 'Chaqaloq sababsiz yig‘laganda o‘zingizni yo‘qotib qo‘ymang. Yig‘ini tahlil qilish funksiyasidan yordam oling, muammoni tezda aniqlab, hal qiling.'),
  ('cc7b8905-a439-46c1-8d92-ea81667052be', 'Dadaning taskini 🫂', 'Tunda chaqaloq uyg‘onganda bir safar siz, bir safar juftingiz tursin. Mas’uliyatni bir jamoa bo‘lib teng taqsimlang.'),
  ('df82eb33-3f1e-407f-b436-e4b5c122a87e', '300 kunlik hayajon! 🌟', 'Ertaga katta, qo‘shaloq yubiley! Ham 10 oy, ham 300 kun! Uyda kichik bayram muhitini yarating, telefoningiz xotirasini bo‘shating.'),
  ('19b97cb2-c4a1-4649-a316-a7b34bb3eed4', 'Farzandingiz qanchalik katta yo‘lni bosib o‘tdi!  📈', 'Ilk kunlardagi hayajon o‘rnini ishonch egalladi. Siz bu yo‘lni katta g‘alaba bilan bosib o‘tdingiz, siz ajoyibsiz!'),
  ('1d119442-bc5b-4f46-a607-68533220e425', 'Savolingiz bormi? 🤖', 'Sizni tashvishga solayotgan rivojlanishga oid har qanday tafsilotni hatto tunda ham Anacan AI yordamchimizdan so‘rab, mutaxassis yordamini olishingiz mumkin.'),
  ('dd2f968e-d28b-4ab1-9758-59cda94c35f6', 'Ajoyib 10 oy va 300 kun! 🎉', 'Tabriklaymiz! Siz bu mo‘jizani roppa-rosa 300 kundan, to‘liq 10 oydan beri ulg‘aytirib kelmoqdasiz.'),
  ('63090d6e-b5fb-4db8-bce4-2e5749468a34', 'Kitoblarga qiziqish 📖', 'Kechki tartibingizga bosma kitoblarni ham kiriting. U endi sahifalarni o‘zi varaqlashga harakat qilmoqda. Ovoz ohangingizni ertak sur’atiga moslashtiring.'),
  ('64ab60a5-a744-4f7e-a8a1-28b04eede9d6', 'Ovqat minorasi quladi 🥣', 'U o‘rindig‘idan qoshiq yoki ovqatni ataylab yerga tashlab, keyin sizga qaraydimi? U chegaralar va tortishish kuchini sinab ko‘rmoqda. Sabrli bo‘ling.'),
  ('cd288f90-d6da-4851-9b9a-2a8e15ba81fb', 'O‘zgarayotgan tanangiz 👗', 'Ko‘zgudagi tana qiyofangizga qarab xafa bo‘lyapsizmi? Siz shu tanangiz bilan bir insonni dunyoga keltirdingiz. Kayfiyat kundaligingizga o‘zingizga minnatdorlik bildiruvchi xabar yozing.'),
  ('0e1a794c-f019-4037-b108-0a10db7b5f9f', 'Jimjitlik qahramoni 🤫', 'U uxlab qolgan zahoti uydagi har bir tovush bomba portlashidek tuyuladi. Shovqin o‘lchagich yordamida xona uchun me’yorni belgilayotganda, o‘zingiz ham yengil qadam tashlang.'),
  ('cb2d76e0-4e92-41f1-9153-3b4a29404a17', 'Shkaf izquvari 🕵️‍♀️', 'Oshxonadagi barcha qozonlar yerdami? Mayli, o‘ynayversin: xavfsiz buyumlar bilan o‘ynash uning mantiqiy fikrlashini rivojlantiradi. Faqat o‘tkir buyumlarni uzoqroqqa olib qo‘ying.'),
  ('d194240e-ae66-4f32-83ef-39ade449ccb6', 'Onalarning dardlashuvi 💬', '“Nega mening bolam hali ham emaklamayapti?” kabi savollar sizni tinch qo‘ymayaptimi? Anacan hamjamiyatida yozing. Har bir bolaning o‘ziga xos mukammal rivojlanish sur’ati borligini ko‘rasiz.'),
  ('29cc3dd1-d28b-45c9-93d7-58bfda48629c', 'Ko‘rsatkich barmoq faol ☝️', 'U uzoqdagi mushuk yoki o‘yinchoqni barmog‘i bilan ko‘rsatib, unga munosabat bildiradi. Bu diqqatni yo‘naltirishning eng yuqori bosqichidir.'),
  ('6eab5294-c731-4890-971d-ad01e35f7d7c', 'Sayr bog‘imi yoki uymi? ⛅', 'Tashqariga chiqishni xohlaysiz, ammo shamol bor. Ob-havo va kiyim yordamchisi sizga nafaqat havo necha daraja ekanini, balki shamol o‘tkazmaydigan qanday kiyim kiydirish kerakligini ham aytsin.'),
  ('edfb2fd4-70c3-4b15-b2d1-0fc891b31501', 'Dadaning kulgili yuz ifodalari 🤡', 'Chaqaloqni kuldirishning eng yaxshi usuli — dadasining g‘alati tovushlar chiqarishi. Bugungi kechadagi quvnoq lahzalarni Chaqaloq fotosessiyasi yordamida xotiraga muhrlang.'),
  ('9b064bbe-67b8-4d62-b3a0-30f79dc81515', 'Onasidan ajralmaslik istagi 🥰', 'Hatto hojatxonaga kirganingizda ham eshik ortida sizni kutib, yig‘laydi. Ajralish xavotiri eng yuqori darajada. Har safar unga «Men shu yerdaman», deb dalda bering.'),
  ('e77deeee-d612-4dac-bea4-ec9f16608958', 'Bugun Aqlli ertakda 🪄', 'Aqlli ertaklarda qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: kunduzi charchab, kechasi yulduzlar sari uchadigan kichkintoy.'),
  ('f0ba97cb-8dd2-4486-865e-1d22a5e551a6', 'Cho‘ntagingizdagi ro‘yxat 🛒', 'Meva pyuresini tayyorlash uchun olma qolmadimi? Ro‘yxat bo‘yicha xarid qilishni juftingizga topshiring. Xaridlar ro‘yxatiga yozing, marketga borish uning vazifasi.'),
  ('12c2a250-54bd-4e0d-a366-20c820596148', 'Tezkor pediatr 🤖', 'Bolangizning tanasida mayda qizarishlar bormi? Shifokorga borishdan oldin Anacan AI orqali oziq-ovqat allergiyasi belgilari haqida tezkor ma’lumot oling.'),
  ('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec', 'Ismiga javob qaytaradi 🗣️', 'Chaqirganingizda nafaqat sizga qaraydi, balki qilayotgan ishini tashlab, oldingizga kelishga ham harakat qiladi.'),
  ('c7423d2f-6f9f-452c-9de2-5dea29b29f93', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yoritilgan muhitda ishlab chiqariladi.'),
  ('100bd53c-84e3-4c7e-8a31-2a287a02c440', 'O‘zingizni ayblamang 📝', 'Bugun u bilan kam o‘ynadim, deb o‘ylayapsizmi? Mazmunli o‘tkazilgan 10 daqiqa charchoq bilan o‘tgan 1 soatdan qadrliroq.'),
  ('42ea49cf-0e72-4699-aaf4-7633e9ea6a82', 'Vaqtni to‘xtatuvchi kadr 📸', 'U kundan-kunga bolaga ko‘proq o‘xshab bormoqda, chaqaloqlik qiyofasi esa asta-sekin yo‘qolmoqda. Hoziroq Chaqaloq fotosessiyasini ochib, undagi bu o‘zgarishni suratga oling.'),
  ('a0c5dfe0-02f0-4961-8b06-219cd57dde9d', '11 oylikka yaqinlashishning ilk belgilari! 🎈', 'Diqqat! Atigi 20 kundan keyin u 11 oylik bo‘ladi va biz 1 yoshga qadar katta sanoqni boshlaymiz. Tabassum qiling!'),
  ('26bb2530-b202-43eb-9226-30863365843e', 'Hazm jarayonini kuzatamiz. 🧷', 'Turli qattiq ovqatlar ich kelishini o‘zgartiradi. Har safar taglikni almashtirganingizni Anacan-da qayd etib, chaqalog‘ingiz salomatligini kuzatib boring.'),
  ('32966fee-53d4-4975-ad1e-195457a2fa5c', 'Qaysar tunlar 🥱', 'Uxlamaslik uchun bor kuchi bilan qarshilik qilyaptimi? Kunduzgi uyqulardan birini qisqartirish vaqti kelgan bo‘lishi mumkin. Kun tartibini qayta ko‘rib chiqing.'),
  ('b5660557-30c8-45a9-9c75-69616076d9ce', 'Onalar uchun maskan ☕', 'Uyda qolaverib, kuchingiz tugadi. Onalar uchun qulay maskanlar orasidan bolalar menyusi bor va bemalol o‘tirishingiz mumkin bo‘lgan kafeni tanlab, o‘zingizga vaqt ajrating.'),
  ('221ab24d-c8af-4cca-b9d8-b4eae15499d0', 'O‘zingizni qadrlang 👏', 'Xonaning tartibsizligiga emas, uning bugun qanchalik baxtli ekaniga qarang. Siz — hech bir kitob o‘rgata olmaydigan darajada ajoyib onasiz.'),
  ('cdf44716-8a24-472d-9ff5-449bcc14a7fe', 'Musiqaga raqs tushayotgan tana 🎶', 'Televizor yoki telefondan ritmik ovoz eshitishi bilan dumbasini likillatishni boshlaydi. Musiqani his qilish qobiliyati rivojlanmoqda, unga qo‘shilib raqsga tushing!'),
  ('d3e69c0c-c087-4266-8819-3e9aa9fc132a', 'Massaj vaqti 💆‍♂️', 'Bola uxlagach, kun davomida to‘plangan stressdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz — bir jamoasiz!'),
  ('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777', 'Ertak bilan uyquga ketish 🪄', 'Aqlli ertaklarda faqat musiqa va tabiat tovushlaridan iborat maxsus fon yarating. So‘zlar yo‘q, faqat huzur bor.'),
  ('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac', 'Park bilan do‘stlashish 🌳', 'Bolalar aravachasida sayr qilish unga zerikarli tuyulyaptimi? Ob-havo va kiyimini tekshirib, parkda uni yerga tushiring va maysa hamda barglarga bemalol tegishiga imkon bering.'),
  ('d3bac322-3971-4b22-8636-d789ac7ce8db', 'Devordan ushlab yuradi 🧗‍♀️', 'Mebel chetidan ushlab, yonma-yon qadam tashlash — uning sevimli mashqi. Himoya moslamalari va o‘tkir burchaklarni yana bir bor tekshirishning ayni vaqti.'),
  ('6498b35b-aa8e-416f-9da1-2596c74b14d0', 'Xayr-xayr qilamiz 👋', 'Kimdir eshikdan chiqayotganda, o‘z tashabbusi bilan qo‘l silkitib xayrlashadi! Bu ajoyib ijtimoiy refleks.'),
  ('b49f5612-c3e4-4568-8a0e-3494499a88d1', 'Yarim tunda sababsiz va tinmay yig‘lab uyg‘ondimi? 😭', 'Uni xotirjam quchoqlang, uyg‘otishga urinmang. Ovozini Yig‘i tahliliga eshittirib, ishonch hosil qiling.'),
  ('fd05df6d-36c8-4c59-9212-7542837f9f4c', 'Dardlashishga ehtiyoj bor 💬', '«Men endi hech qachon avvalgi o‘zim bo‘la olmayman», degan fikr sizni qiynayaptimi? Bu o‘tkinchi tuyg‘uni Anacan hamjamiyatidagi onalar bilan bo‘lishing — siz yolg‘iz emassiz.'),
  ('188836b2-55a8-4b14-87fe-653f4e05ae3e', 'Bugun hamma narsadan jahlingiz chiqdimi?', 'Bolangiz uxlaganda Kayfiyat kundaligiga his-tuyg‘ularingizni yozing. Ertaga yangi va yanada go‘zal kun bo‘ladi.'),
  ('4d566d24-14b9-45b0-be5d-1940c1563ed9', 'Tezkor xarid 🛒', 'Juftingiz ishdan chiqyaptimi? Darhol Xaridlar ro‘yxatini oching va sut, meva hamda uy uchun kerakli boshqa narsalarni bir necha soniya ichida unga yuboring.'),
  ('fd0252a6-07bf-4750-bd4b-be91888e16f6', 'Kattalarga taqlid qilish 🧹', 'Siz uyni artayotganingizda u ham qo‘liga latta olib, xuddi shunday qilishga urinadimi? U sizning ko‘zgungiz! Har bir harakatingizni takrorlaydi.'),
  ('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75', 'Jamoaviy ko‘mak 🥂', 'Kun bo‘yi to‘plangan charchoqni yengillashtirish uchun juftingiz bilan birga choy ichib, bir-biringizga: «Bugun ham uddaladik», deb ayting.'),
  ('ac527e8b-ca16-4272-b6ba-964f15ba419b', 'Pediatriyaga oid savollar 🤖', '10 oylik bolaning bir porsiyasi qancha bo‘lishi kerak? O‘zingizni qiynamang, Anacan AI’dan aniq va pediatr tomonidan tasdiqlangan jadvalni so‘rang.'),
  ('e38208ca-c817-4de4-ba96-5a5ca4752901', 'Milk qichishishi davom etmoqda 🦷', 'Barmoqlari doim og‘zidami va hamma narsani kemiryaptimi? Orqa tishlari chiqayotgan bo‘lishi mumkin. Holatni Tish chiqishini kuzatish bo‘limiga qayd eting.'),
  ('6032f94e-69e7-4802-b291-44567c9f71d1', 'Dadaning allasi 👨‍🍼', 'Bu oqshom chaqaloqni xonada bir o‘zi uxlatib ko‘rish navbati juftingizda.'),
  ('7b460d4a-b37e-465f-9c70-e137f59bcc07', 'Tozalashmi yoki dam olishmi? 🛋️', 'Chaqaloq uxlaganda idish yuvish mashinasi tomon shoshilmang. Divanga cho‘ziling, ko‘zlaringizni yuming va 15 daqiqa shunchaki nafas oling. Siz robotmisiz? Yo‘q.'),
  ('a1392cb5-508d-45a8-9d3d-1985c8d19958', '«Yo‘q» jangi boshlanmoqda 🛑', 'Endi u yoqtirmaydigan narsani bersangiz, boshini chayqab, uni itaradi. Uning irodasi shakllanmoqda. Kichik qarorlariga hurmat bilan munosabatda bo‘lishga harakat qiling.'),
  ('2cc5ac97-f2b1-4c92-8852-fec32f54b311', 'Tovushlarni nazorat qilish 🤫', 'U uxlab qolganidan keyingi dastlabki yarim soat — eng nozik vaqt. Tovush o‘lchagich yordamida xonadagi shovqin darajasini tekshiring va to‘satdan chiqadigan shovqinlardan ehtiyot bo‘ling.'),
  ('e0b42cd5-f681-4866-a7ec-b0b890444381', 'Sog‘lom ona, sog‘lom chaqaloq 🥑', 'Temir va kalsiy zaxiralaringiz kamaygan. Sog‘lom retseptlardan foydalanib, tez tayyorlanadigan va sizga tetiklik beradigan energiyaga boy salat tayyorlang.'),
  ('e83a5069-7214-47ea-9051-6406495d5723', '«O‘yinchog‘imni ber!» qaysarligi 🧸', 'Qo‘lidan biror narsani olsangiz, keskin munosabat bildiradi va yig‘laydi. Unda egalik hissi to‘liq shakllanmoqda. Taqiqlash o‘rniga e’tiborini boshqa narsaga qarating.'),
  ('0535564e-f2c8-4264-bd71-a94e3154d928', 'Ob-havo ma’lumoti ⛅', 'Tashqarida havo qandayligi aniq emasmi? Ob-havo va kiyim vositasi derazadan bilib bo‘lmaydigan shamol tezligi va mos kiyimni sizga darhol aytib beradi.'),
  ('51cec612-e243-435d-9b60-1e3269d69cee', 'Musiqali oqshomlar 🎶', 'Kechga yaqin boshlanadigan injiqliklarni bartaraf etishning eng oson yo‘li — uning sevimli qo‘shig‘ini qo‘yib, bag‘ringizga bosgancha birga raqsga tushish.'),
  ('533a4ec1-68c0-4cf3-92cd-723b3f8c0979', 'Oyoq kiyimini o‘zi yechadi 👟', 'Uni kiyintirish endi kurashga aylanib qoldimi? U paypoq va oyoq kiyimini o‘zi tortib yechadi. Uning harakat ko‘nikmalariga qoyil qoling!'),
  ('7bbccad8-a83a-493c-82e1-d823d261e04b', 'Mantiqiy o‘yinlar 🧩', 'O‘yinchoqlarni qutiga solib, keyin hammasini to‘kib tashlayaptimi? Uning ichkari va tashqari haqidagi mantiqiy tushunchasi rivojlanmoqda. Bu mashg‘ulotiga xalaqit bermang.'),
  ('84cdedf9-5de5-49c9-887b-6f8ccc988990', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda chaqaloq uyg‘onishining barcha tashvishini yolg‘iz o‘zingiz ko‘tarmang. Juftingizni ham uyg‘oting — bir jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('a4c45285-b9cc-4763-a80c-d694137bbb6a', 'Onalar uchun joy toping ☕', 'Shuncha charchoq orasida siz ham biroz toza havodan bahramand bo‘lishingiz kerak. Onalar uchun qulay joylar orasidan yaqin atrofdagi tinch kafeni topib, borib dam oling.'),
  ('16cae145-7589-4ff6-ae2c-368fe115d232', 'His-tuyg‘ularni boshqarish 📝', 'Asablaringiz taranglashib, har lahzada portlab ketishga tayyormisiz? Barcha stressingizni kayfiyat kundaligiga yozib, chuqur nafas oling.'),
  ('9b99e928-dd9a-40d6-9254-12459dac4a3d', 'Qorong‘ilik bilan do‘stlashish 🌙', 'Tezroq uxlab qolishi uchun kechki tartibga qorong‘ilik bilan tanishishni ham qo‘shing. Xonadagi barcha ortiqcha chiroqlarni o‘chiring.'),
  ('ee2e2e79-277e-4a7f-9473-05aa36068880', 'Tana a’zolarini taniydi 👀', '«Burning qayerda?» deb so‘raganingizda, barmog‘i bilan tegib ko‘rsatadimi? Uning anglash qobiliyati ayni cho‘qqisida!'),
  ('2cb20f11-aee5-456a-b969-c87733104c72', 'G‘alaba oqshomi 🥂', 'Bugun kechqurun chaqaloq uxlagach, juftingiz bilan «Biz ajoyib jamoamiz!» deb qadah ko‘taring. Siz haqiqatan ham juda yaxshi uddalayapsiz!'),
  ('57b926b9-28cb-4c4e-8863-8ce72241c9fe', 'Allergiyadan shubhalanish 🤖', 'Yangi ovqat berdingiz va yonoqlarida qizarish paydo bo‘lganini ko‘rdingizmi? Vahimaga tushishdan oldin Anacan AI yordamida dastlabki qadamlarni bilib oling.'),
  ('9c11d140-acfd-48e4-9fef-141a9e34586d', '«O‘zim yeyman» degan qaysarlik 🥦', 'Qoshiqni qo‘lingizdan olmoqchi. Olishiga ruxsat bering. Ust-boshi kir bo‘ladi, ammo bu mustaqillik hissi uning uchun juda muhim.'),
  ('37e8bf23-2dc4-4b8c-8c8f-49146922ba57', 'Urinish va xato 🧱', 'U ikkita o‘yinchoq kubikni ustma-ust qo‘yishga harakat qiladi, ammo ular yiqilib tushadi. So‘ng diqqat bilan yana urinib ko‘radi. Uning bu kichik muhandislik urinishlarini indamay kuzating.'),
  ('732cb07a-0e5f-4dc9-9d15-78470db05396', 'Taom g‘oyalari 🍲', 'Bir xil taomlarni tayyorlashdan charchadingizmi? Sog‘lom retseptlar orasidan 10 oylik bolalar uchun yangi va mazali, qo‘lda yeyiladigan taomlarni ko‘rib chiqing.'),
  ('a387d51e-9e9d-455a-be61-4650ee6ffa63', 'Tinch xona, xotirjam miya 🤫', 'Uyquga tayyorlanayotganda xonadagi shovqin darajasini pasaytirish kerak. Shovqin o‘lchagich yordamida ovozingiz va atrofdagi shovqin darajasini tekshiring.'),
  ('439ac8e3-ab5f-434a-bb69-d98dee8208cd', 'Shaxsiy ertak 🪄', 'Aqlli ertaklarda atigi 10 kundan so‘ng ulg‘ayadigan qahramon haqida hikoya yaratib, xonani sehrli muhitga burkang.'),
  ('e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769', '11 oylikka atigi 10 kun qoldi! 🎂', 'Ishonish qiyin! Roppa-rosa 10 kundan so‘ng kichkintoyingiz 11 oylik bo‘ladi. Endi uning 1 yoshga to‘lish bayramini rejalashtirish haqida o‘ylashni boshlashning ayni vaqti!'),
  ('ff800946-b6d3-4e88-8699-fe114e37b692', 'Tabassumlar surati 📸', 'U kundan kunga o‘ziga xos va yanada yoqimtoy bo‘lib bormoqda. Hoziroq Chaqaloq fotosessiyasini oching, suratni stikerlar bilan bezatib, bu quvonchli lahzani abadiylashtiring.'),
  ('361e96e8-a6ed-4fdf-a7bb-50e07abcec66', 'Tun osoyishtaligi 🪄', 'Aqlli ertaklarda jasur va yoqimtoy hayvonlar haqida hikoya yarating va xonani sehrli makonga aylantiring.'),
  ('a4baaa67-c9fb-4208-aab7-e7515b21f64f', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi?', 'Sog‘lom retseptlar bo‘limidan temir va oqsilga boy tushlikni tanlab, kuch to‘plang.'),
  ('c58c8b30-4c95-4f60-98d7-d9580eb48a38', 'Kitob sahifalari varaqlanmoqda 📖', 'Qalin sahifali kitob varaqlarini butunlay o‘zi aylantiryaptimi? Bu motorika yutug‘ini rivojlanish kuzatuvchisida qayd eting.'),
  ('2631ed9f-967a-4f12-9097-1f619f7f1e5f', 'Bugun hech narsa reja bo‘yicha ketmadimi?', 'Bolangiz uxlaganda o‘zingizni aybdor his qilmang. Siz haqiqiy onasiz, siz mukammalsiz.'),
  ('34415812-3e31-43f2-99de-a1dd76bb1d9e', 'Nishonga otish ⚾', 'Qo‘lidagi o‘yinchoqni ataylab muayyan nishonga otishga urinmoqda. Ko‘z va qo‘l muvofiqligi jadal rivojlanmoqda.'),
  ('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4', 'Tezkor pediatr 🤖', '11 oylik chaqaloqning kunduzgi uyqusi qancha davom etishi kerak? Ikkilanayotgan barcha savollaringizni darhol Anacan AI’dan so‘rab, ko‘nglingizni tinchlantiring.'),
  ('09817e37-4e65-43f6-968c-dd333358e01e', 'Ehtiyojlar ro‘yxati tugamaydi 🛒', 'Kundalik yumushlar orasida shampunmi yoki taglikmi tugaganini unutib qo‘yyapsizmi? Yodda saqlashga urinmang, Xaridlar ro‘yxatiga yozing va uni juftingiz bilan sinxronlashtiring.'),
  ('1f244347-1957-4238-988d-4563adba7bcd', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechqurun chaqaloqni uyquga tayyorlash va unga ertak o‘qib berish — faqat dadasining vazifasi.'),
  ('9f618083-9332-44d7-8a8f-8ad3af6c22ac', 'Uydagi hamma narsa — o‘yinchoq 🥄', 'Plastik idishlar va yog‘och qoshiqlar unga eng qimmat o‘yinchoqdan ham qiziqroq. Oshxona buyumlarini bemalol o‘rganishiga imkon bering.'),
  ('354e039c-3978-4aa3-a008-1a3a7bbe85a3', 'Yig‘i tahlili yordamga keladi 😭', 'Yarim tunda uyg‘onib, hech tinchimayaptimi? Taxmin qilishni bas qiling, Yig‘i tahlilidan foydalanib sababini darhol aniqlang.'),
  ('8fb53566-815d-4365-b87c-c14288ebb122', 'Toza havo — najotkor 🌳', 'Uyda vaziyat keskinlashayotgan bo‘lsa, Ob-havo va kiyimni tekshiring, chaqaloqni aravachaga o‘tqazing va darhol parkka chiqing. Tabiat — uni tinchlantirishning eng tezkor yo‘li.'),
  ('c87df5f1-fbe2-4462-a617-a6649445ce77', 'Injiqlik avjida ☁️', 'Hech narsadan ko‘ngli to‘lmay, hamma narsaga yig‘layaptimi? Bunga o‘sishdagi keskin sakrash yoki tish chiqishidagi bezovtalik sabab bo‘lishi mumkin. Uni shunchaki ko‘proq bag‘ringizga bosing.'),
  ('7fd53d22-26ef-4c4c-83bb-d44647b94560', 'Birgalikda yechim topamiz 💬', '“Farzandim nega bunday qilyapti?” degan savoldan charchadingizmi? Anacan Hamjamiyatiga kiring va minglab oilalarda aynan shu holat yuz berayotganini ko‘ring!'),
  ('a6ef3f7c-7550-4712-8fc9-23c742a51744', 'Uyquga tayyorgarlik 🛀', 'Iliq vanna har doim yordam beradi. Kechki tartibni aslo buzmang, chunki u chaqaloq miyasiga hozir uxlash vaqti bo‘lganini bildiradi.'),
  ('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb', 'Yiqilib-turib o‘rganish 🧗‍♂️', 'Oyoqda turganida dumbasi bilan yerga tushadi, kuladi va yana turadi. Bunday yiqilishlar mushak xotirasini shakllantiradi, ortiqcha aralashmang.'),
  ('25903ac8-0fd6-44f0-92d8-c3e1bee035e5', 'Sukunatga ehtiyoj 🤫', 'Uyquga ketayotganida kichik bir qirsillagan tovush ham uni uyg‘otadimi? Shovqin o‘lchagich yordamida muhitni tahlil qiling va uzluksiz sukunatni ta’minlang.'),
  ('3a5c700f-e10c-4819-bba1-cddd9f951f4f', 'Ro‘yxatlar va unutuvchanlik 🛒', 'Xotira xiralashishi sizni hamon tark etmayaptimi? Uy uchun kerakli mayda-chuydalarni eslab yurishga urinmang, darhol Xaridlar ro‘yxatiga kiriting, qolganini juftingiz hal qilsin.'),
  ('47b342b1-9525-44b6-b917-2eb642240cb2', '“Sizni sevaman” quchog‘i 🫂', 'U kutilmaganda kelib bo‘yningizdan quchadimi yoki yuzingizni silaydimi? U endi o‘z mehrini jismonan namoyon qilmoqda. Bu lahzadan zavqlaning.'),
  ('23c2a94e-cf0d-4f81-9604-79b4dcfb2460', 'To‘rt devor orasidan chiqish ⛅', 'Uyda siqilyapsizmi? Ob-havoni tekshirib, mos kiyim kiydiring va bog‘da maysa hamda barglarga tegib ko‘rishi uchun unga erkinlik bering.'),
  ('77a8c135-4a26-4877-9f24-fc51c941fb7a', 'Kiyinishda yordam beradi 👕', 'Ko‘ylagini kiydirayotganingizda qo‘llarini o‘zi uzatadimi yoki oyog‘ini ko‘taradimi? U siz bilan hamkorlik qilyapti. Rivojlanish kuzatuvchisida bu kichik yordamini qayd eting.'),
  ('9df28291-b590-4e7d-a861-feb0732398b2', 'Qorong‘ilik bilan do‘stlashish 🌙', 'Tezroq uxlab qolishi uchun kechki tartibga qorong‘ilik bilan tanishishni qo‘shing. Xonadagi barcha ortiqcha chiroqlarni o‘chiring.'),
  ('72f5aeb4-94f9-40bc-943e-fa87664da32b', 'Forumlarda adashib qolmang 🤖', 'Bolangizning harakatlarida g‘alati holatni sezdingizmi? Internetda soatlab qidirmang, savolingizni to‘g‘ridan-to‘g‘ri Anacan AI’ga bering va xotirjam bo‘ling.'),
  ('c8b05bf8-0ed8-4eec-86f7-4cba168167e1', 'So‘zlarning ma’nosini biladi 🗣️', '“To‘pni olib kel”, desangiz, haqiqatan ham borib to‘pni qidiradi. Lug‘at boyligi (tushunadigan so‘zlari) tez oshib bormoqda. U bilan murakkabroq jumlalarda gaplashing.'),
  ('f8aae6d9-1b70-4333-a55c-1937c871c533', 'Aqlli ertak vaqti 🪄', 'Aqlli ertaklarda atigi 1 oydan keyin 1 yoshga to‘ladigan qahramon haqida hikoya yarating. Tun sukunatini faqat shu ertak buzsin.'),
  ('932e2f32-ffee-4b5c-9d10-16c135453b42', 'Ertaga katta kun! 🎉', 'Tayyormisiz? Ertaga chaqalog‘ingiz roppa-rosa 11 oylik bo‘ladi! 1 yoshga to‘lishiga atigi 1 oy qoldi! Chaqaloq fotosessiyasi uchun o‘zgacha joy va kiyim tayyorlang.'),
  ('aac354e5-8061-403a-8cf7-d00ce05e4093', 'Birdamlik ruhi 🥂', 'Kayfiyat kundaligini oching va juftingiz bilan ilk kunlarni eslab, birga kuling. Bu 11 oy davomida qancha mashaqqatni yengib o‘tganingizni unutmang!'),
  ('d24d332c-e00e-4b7f-8dac-28439e172c26', 'Onaning qahva tanaffusi ☕', 'Xonadagi tartibsizlik hech qayerga qochib ketmaydi, ammo sizning quvvatingiz tugashi mumkin. Chaqaloq mustaqil o‘ynayotganida darhol ishga shoshilmang. O‘tiring va qahvangizni iching.'),
  ('6ef8817b-2854-4da4-969a-fe13d344017a', 'G‘alaba raqsi 💖', '11 oylik charchoq va faxrni bugun kechqurun juftingiz bilan birga nishonlang. 1 yosh sari so‘nggi marraga chiqdingiz!'),
  ('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b', 'Ona suti hali ham asosiy ozuqa! 🍼', '1 yoshgacha ona suti muhim. Oziqlantirish taymerini ishga tushirib, chaqalog‘ingizning kunlik sutga bo‘lgan ehtiyoji qondirilayotganiga ishonch hosil qiling.'),
  ('ad9c3e79-16bb-44a7-9f37-6f5935a4494c', 'Roppa-rosa 11 oy! 🎂', 'Tabriklaymiz! Tug‘ruqdan beri roppa-rosa 11 oy o‘tdi! Darhol Chaqaloq fotosessiyasidan 11 oylik stikerni tanlang va bu quvonchni Anacan hamjamiyatida ulashing!'),
  ('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f', 'Xavfli joylarga yetib borish ⚡', 'Bo‘yi yanada o‘sdi va ilgari qo‘li yetmagan javonlarga endi yetadi. Uydagi xavfsizlik choralarini (o‘tkir burchaklar, og‘ir buyumlar) qayta ko‘rib chiqing.'),
  ('8a4a7da2-606f-4fbb-8668-101f2d47c03c', 'Musiqaning kuchi 🎶', 'Kechga yaqin sababsiz boshlanadigan injiqliklarni yengil klassik musiqa bilan tinchlantirib ko‘ring. Ko‘pincha bu oddiy usul mo‘jiza yaratadi.'),
  ('a70ebacf-44d0-4367-babf-09742bda8fa8', 'Bir yosh hayajoni boshlanmoqda! 🎈', '11 oy ortda qoldi. Atigi 30 kundan so‘ng birinchi tug‘ilgan kun! Mavzuli bayrammi, maxsus joymi yoki shunchaki uyda nishonlaysizmi? Rejalashtirishni asta-sekin boshlang.'),
  ('0387bc9b-1c64-4eae-ac49-660cb56552f8', 'O‘yinchog‘imni o‘zim topaman 🧸', 'Ko‘zidan uzoqlashtirgan o‘yinchoqni borib, yashirgan joyingizdan topyaptimi? Demak, u buyum ko‘rinmasa ham mavjud bo‘lishini to‘liq anglayapti!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d'::uuid, 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarning barchasini yolg‘iz zimmangizga olmang. Turmush o‘rtog‘ingizni ham uyg‘oting — jamoa bo‘lish mas’uliyatni teng taqsimlashdir.'),
  ('89a2b668-b451-4cfe-a183-3183fc159297', 'Hislaringizga erk bering 📝', '1 yoshga yaqinlashgani sari ichingizda g‘alati bir qayg‘u, «Qanday tez ulg‘aydi!» degan tuyg‘u paydo bo‘ldimi? Bu hislarni Kayfiyat kundaligiga yozib qo‘ying.'),
  ('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1', '1 yoshga tayyorgarlik uchun kerakli bezaklar va sharlar? 🛒', 'Boshingizni qotirmang, xaridlar ro‘yxatini hozirdanoq tuzishni boshlang.'),
  ('519cad33-f5e8-4169-8f1d-93f4343568db', 'Qat’iyatli urinishlar 🧗‍♂️', 'Qo‘lida o‘yinchoq bo‘lsa ham, mebeldan ushlab o‘rnidan turishga harakat qiladi. Muvozanatni saqlash qobiliyati nihoyatda kuchaygan. Aralashmasdan, uni chetdan kuzating.'),
  ('aa2fb7c9-acf7-4050-9102-4f2927091b95', 'Sokin qahramon 🤫', 'U uxlab qolishi bilan uydagi har bir tovush bomba portlashidek eshitiladi. Tovush o‘lchagich yordamida xona uchun chegarani belgilash bilan birga, qadamlaringizni ham yengillashtiring.'),
  ('9cba5d69-92c6-472c-bb83-c5522d806018', 'Onalarning sirdoshligi 💬', '“Tug‘ilgan kunini qanday o‘tkazsam ekan?” degan o‘y sizni charchatyaptimi? Anacan hamjamiyatiga yozing va onalardan kreativ, hamyonbop g‘oyalar oling.'),
  ('f558e782-e140-4835-8b11-1d5f01a717bf', 'Vaqtni to‘xtatuvchi kadr 📸', 'U kundan-kunga chaqaloqdan ko‘ra bolaga ko‘proq o‘xshab bormoqda. Darhol Chaqaloq fotosessiyasini ochib, uning beg‘ubor raqs tushayotgan onini xotiraga muhrlang.'),
  ('f56842a9-3a83-4016-8e93-a096810c45d3', 'Raqs va ritmlar 🎶', 'Televizor yoki telefonda ritmik tovush eshitishi bilan raqsga tushadimi? Uning musiqani idrok etish qobiliyati to‘liq ishga tushgan, siz ham unga qo‘shilib raqsga tushing!'),
  ('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e', 'Sog‘lom ona, sog‘lom chaqaloq 🥑', 'Temir va kalsiy zaxiralaringiz kamaygan. Sog‘lom retseptlardan tez tayyorlanadigan va sizga tetik turishga yordam beradigan quvvatga boy salat tayyorlang.'),
  ('7883fd83-494d-41a3-b42d-58d452de13d7', 'Dadaning kulgili qiliqlari 🤡', 'Chaqaloqni kuldirishning eng yaxshi yo‘li — dadasining g‘alati tovushlar chiqarishidir. Bugungi quvnoq oqshomni farzandingiz bilan birga maroqli o‘tkazing.'),
  ('981d8d60-ab26-4f64-a20b-eee1dc2fed12', 'Mayda to‘g‘ralgan ovqatlarga to‘liq o‘tish! 🍲', 'U endi chaynashni talab qiladigan ovqatlarni yeya oladi. Ilovamizdagi qo‘shimcha ovqatni boshlagan chaqaloqlar uchun retseptlar yordamida yangi teksturalarni sinab ko‘ring.'),
  ('74f02405-1cdd-401e-bb47-01d87997f231', 'Mustaqil o‘yin vaqti 🧸', 'Endi u 10-15 daqiqa davomida o‘yinchoqlari bilan mustaqil ravishda mashg‘ul bo‘la oladi. Bu uning diqqatni jamlash muddati uzayayotganini anglatadi. Uni uzoqdan kuzatib, sokinlikdan bahramand bo‘ling.'),
  ('8d91b32b-a0f2-4a07-a181-da0b746268bc', 'Parkmi yoki uymi? ⛅', 'Tashqariga chiqmoqchisiz, ammo havo shamolli. Ob-havo va kiyim bo‘yicha yordamchi sizga nafaqat haroratni, balki shamol o‘tkazmaydigan qanday kiyim kiydirish kerakligini ham aytsin.'),
  ('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e', 'Qaysarlik bilan o‘tadigan tunlar 🥱', 'U uxlamaslik uchun bor kuchi bilan qarshilik ko‘rsatyaptimi? Kunduzgi uyqu vaqtlarini va uyqu tartibini qayta ko‘rib chiqing.'),
  ('2f4fbaac-dfe4-48b5-b844-6636c2bc201a', 'Cho‘ntagingizdagi ro‘yxat 🛒', '1 yoshga to‘lish tortiga buyurtma berish uchun Anacan-dagi tort variantlarini ko‘rib chiqing.'),
  ('395ddd9b-9009-4fec-ba6f-816d156ad432', 'Katta his-tuyg‘ular, kichkina tana 🛑', 'Istagi amalga oshmasa, o‘zini yerga tashlaydimi yoki yig‘laydimi? U hali his-tuyg‘ularini boshqara olmaydi. Uning bo‘yi darajasigacha egilib, xotirjam gapirish orqali bu injiqliklarni yengib o‘ting.'),
  ('d824145b-4905-49d1-9f4f-46ade8a730f8', 'To‘satdan qichqirib uyg‘ondimi? 😭', 'Bu tungi vahima bo‘lishi mumkin. Ovozini Yig‘i tahliliga eshittirib, muammo jismoniy yoki ruhiy ekanini aniqlang.'),
  ('a7923459-9b74-4330-949d-00e94d185768', '«Yo‘q» so‘zining ma’nosi! 🛑', 'Qilmasligi kerak bo‘lgan ishni qilayotganda endi reaksiyangizni kuzatyaptimi? Intizomning ilk qadamlari haqida Anacan AI bilan maslahatlashing.'),
  ('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1', 'Massaj vaqti 💆‍♂️', 'Bola uxlagach, kun davomida yig‘ilgan stressdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz bir jamoasiz!'),
  ('ef821341-2506-439d-8346-fbafb2b792ff', 'Bir yoshga atigi 25 kun qoldi! 🎈', 'Sanoq rasman boshlandi! 1 yosh fotosessiyasi uchun joy va kiyim haqida o‘ylab ko‘rdingizmi? Tayyorgarlikni tezlashtiring!'),
  ('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea', 'Uyda xavfsizlik choralarini ko‘ring! 🛡', '️ U mustaqil yura boshlagani sari xavflar ham ortadi. Bolalar uchun himoya qulflari va zinapoya to‘siqlari bo‘yicha Tavsiya etilgan mahsulotlar ro‘yxatimizni albatta ko‘rib chiqing.'),
  ('959729c5-8ab6-4053-99ca-82aa5fdabc7e', 'Otalar bilan birga parvarish qilish vaqti. 👨‍🍼', 'Kechki ovqatlantirishdan so‘ng kitob o‘qish va uxlatish navbatini dadasiga bering, o‘zingiz esa biroz mizg‘ib oling.'),
  ('a478b2eb-eaec-4b54-813a-6f2ba55a5d14', 'Hamma narsani ko‘rsatkich barmog‘i bilan ko‘rsatadi! ☝', '️ «Bu nima?» deyish o‘rniga hamma narsani barmog‘i bilan ko‘rsatadi. Uning bu qiziquvchanligini Chaqaloq albomida abadiylashtiring.'),
  ('97023662-0ba2-4bcd-aff7-bc7adf5883ba', 'Shovqinni nazorat qilish 🤫', 'U uxlab qolganidan keyingi dastlabki yarim soat eng nozik vaqt hisoblanadi. Shovqin o‘lchagich yordamida xonadagi shovqin darajasini tekshiring va to‘satdan chiqadigan shovqinlardan ehtiyot bo‘ling.'),
  ('d02f135b-16bc-4fa9-978f-0e7d992c1ba4', 'Tozalashmi yoki dam olishmi? 🛋️', 'Chaqaloq uxlaganda idish yuvish mashinasi tomon yugurmang. Divanga cho‘ziling, ko‘zlaringizni yuming va 15 daqiqa davomida shunchaki nafas oling.'),
  ('f12c7751-b89f-4d12-a843-8e331c338393', 'Kublardan qal’a quradi 🧱', 'Ikki yoki uchta o‘yinchoq kubni ustma-ust qo‘yishga harakat qiladi. Uning bu kichik muhandislik urinishlarini jimgina kuzating va olqishlang.'),
  ('35ab2e31-1937-4e58-b764-83729c6e330a', 'Tana tili bilan javob 🗣️', '“Ketdikmi?” desangiz, qo‘llarini ko‘taradi yoki “Yo‘q” desangiz, boshini chayqaydi. Tushunish qobiliyati hayratlanarli darajada rivojlangan.'),
  ('65a36f4e-0f24-45fe-a038-a2e61c778c81', 'O‘zingizni qadrlang 👏', 'Xonaning tartibsizligiga emas, bugun uning naqadar baxtli ekaniga qarang. Siz hech bir kitob o‘rgata olmaydigan darajada ajoyib onasiz.'),
  ('7b75b0ec-d253-4e5a-bfac-9ff801269b5f', 'Bugun aqlli ertakda 🪄', 'Aqlli ertaklarda bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: Bir yoshga to‘lishga tayyorlanayotgan mitti sher.'),
  ('01302c3b-60e6-4b0a-8a88-e63349585527', 'Bir yoshga oid xavotirlar? 💬', '“Farzandim hali yurmayapti, rivojlanishi kechikyaptimi?” kabi savollar sizga tinchlik bermayaptimi? Anacan hamjamiyatida yozing. Har bir bolaning o‘ziga xos mukammal rivojlanish sur’ati borligini va yolg‘iz emasligingizni ko‘rasiz.'),
  ('51d3f88a-4baa-4ed5-b62c-e84a750f8166', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda chaqaloq uyg‘onganda barcha mas’uliyatni yolg‘iz o‘z zimmangizga olmang. Turmush o‘rtog‘ingizni ham uyg‘oting — bir jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('984d2a76-5fec-4059-86ef-85671516c9b6', 'Ob-havoni o‘rganish ⛅', 'Tashqaridagi ob-havo qandayligi aniq emasmi? Ob-havo va kiyim tanlash vositasi sizga shamol tezligi hamda mos kiyimlar to‘plamini bir zumda ko‘rsatadi.'),
  ('063ccb8e-7bd6-43e4-9c41-f30c172e10a7', 'Sog‘lom ona, sog‘lom chaqaloq 🥑', 'Temir va kalsiy zaxiralaringiz kamaygan. Sog‘lom retseptlardan tez tayyorlanadigan va sizga kuch beradigan salat tayyorlang.'),
  ('1bed0d5c-444a-48fc-8e21-35fd8fff35b5', '1 yoshga atigi 20 kun qoldi! 🎂', 'Vaqt qanday tez uchadi! Tug‘ilgan kun taklifnomalari, ro‘yxatlar va kichik syurprizlar uchun qaydlar yozishni boshlang.'),
  ('caa0a9a0-1a0d-4362-a446-9f103d33e564', 'Vaqtni to‘xtatuvchi kadr 📸', 'U xonada zavq bilan o‘ynayotganida darhol Chaqaloq fotosessiyasini oching va uning katta bolalardek fe’l-atvorini suratga oling.'),
  ('3cc5a97d-281f-41bf-8747-fbb71f040e65', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yoritilgan muhitda ishlab chiqariladi.'),
  ('528b02c4-9d93-4cda-add4-eb9a04a4395a', 'Sut ajralishini qo‘llab-quvvatlovchi mahsulotlar. 🍲', 'Ayollar uchun sog‘lom retseptlar bo‘limidagi sutni ko‘paytiruvchi sho‘rvalarni bugun sinab ko‘ring va kuch-quvvatga to‘ling.'),
  ('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d', 'Qaysi ko‘krak bilan emizganingizni unutdingizmi? 🤱', 'Anacan taymeri sizning o‘rningizga o‘ng/chap ko‘krakni eslab qoladi. Emizishni hoziroq taymer bilan boshlang!'),
  ('5c42ea20-5a84-467a-b408-412bcaaf8374', 'Kunduzgi uyqusi o‘zgaryaptimi? 🥱', 'Kunduzgi ikki uyqudan biriga qarshilik qilyaptimi? 1 yoshga yaqinlashganda uyqu jadvalini qayta tartibga solish vaqti kelgan bo‘lishi mumkin.'),
  ('b5252c17-b36e-4334-8221-0dc9210bbc77', 'Oilaviy dasturxonda uning ham o‘z joyi bor! 🍲', 'U endi siz bilan bir vaqtda ovqatlanishni yoqtiradi. Ilovamizdagi qo‘shimcha ovqatni boshlagan chaqaloqlar uchun retseptlardan butun oilaga manzur taomlarni kashf eting.'),
  ('ee88eee3-00d7-4463-b0db-60b939d85d4e', 'Savolingiz bormi? 🤖', '1 yoshdan keyin sigir sutiga qanday o‘tish kerak? kabi muhim savollaringizni hatto tunda ham Anacan AI yordamchimizdan so‘rab, ko‘mak olishingiz mumkin.'),
  ('48047d55-0e81-4b9a-976d-56b580b1a7b7', 'Pediatriyaga oid savollar 🤖', '1 yoshga yaqinlashganda ovqatlanishda nimalar o‘zgaradi? O‘zingizni qiynamang, Anacan AI-dan aniq va pediatr tasdiqlagan ro‘yxatni so‘rang.'),
  ('56284941-dca4-4067-9e31-d61fc4ebeb63', 'Jamoaviy qo‘llab-quvvatlash 🥂', 'Kun bo‘yi to‘plangan charchoqni yengillatish uchun juftingiz bilan birga choy ichib, bir-biringizga bugun ham uddaladik, deng.'),
  ('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e', 'Oddiy ko‘rsatmalarni to‘liq bajara oladi! 🧠', 'To‘pni menga ber, bu yerga kel, deganingizda sizni tushunadi. Bu aqliy rivojlanish bosqichini Bloglardagi maqolalar yordamida yanada qo‘llab-quvvatlang.'),
  ('152edc3c-3a8c-41ee-81bb-0df222f2c1ea', 'Atigi 2 hafta! 🎈', 'Tug‘ilgan kunigacha atigi 14 kun qoldi! Nostalgiya shamoli esmoqda... Chaqaloq fotosessiyasini oching, tug‘ilgan kunidagi suratini bugungi surati bilan yonma-yon qo‘yib, uning naqadar ulg‘ayganini tomosha qiling.'),
  ('87c2d4c6-8130-43a1-8ff7-fa406c018013', 'Otaning tungi vazifasi 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechqurun chaqaloqni uxlashga tayyorlash va ertak o‘qib berish — otaning vazifasi. Siz esa shunchaki quloqchinlaringizni taqing.'),
  ('d1325a58-5701-4db5-a92f-ca67116c5c21', 'Tayanchsiz soniyalar 🧗‍♂️', 'Divandan ushlab turganida qo‘llarini qisqa muddatga qo‘yib yuboryaptimi? Demak, u muvozanatni saqlashni o‘rganmoqda.'),
  ('3beff563-1e72-4a1f-8490-4e977c8b0b7a', 'Nima pishirsam ekan? 🍲', '1 yoshga yaqinlashganda menyu uchun g‘oyalaringiz tugadimi? Anacan AI’dan bola o‘zi ushlab yeyishi mumkin bo‘lgan oson gazaklar ro‘yxatini so‘rang.'),
  ('eebfea92-7f8e-43d7-a45c-4a10e720b24c', 'Qorong‘ilik bilan do‘stlashish 🌙', 'Tezroq uxlab qolishi uchun kechki tartibga qorong‘ilikni ham qo‘shing. Xonadagi barcha ortiqcha chiroqlar va ekranlarni o‘chiring.'),
  ('f8f9e691-e184-414d-9abe-ae0a3969929a', 'Suhbatga qo‘shilmoqda 🗣️', 'Siz gapirayotganingizda u ham o‘z tilida nimalarnidir aytib, ovozini balandlatyaptimi? Muloqot qilish qobiliyati jadal rivojlanmoqda — xonada ikkinchi notiq paydo bo‘ldi, uni albatta tinglang!'),
  ('20db1e8e-1980-431d-800c-b7aa4ccf158b', 'O‘z qoshig‘i bilan ovqatlanishga urinishlar! 🥄', 'U allaqachon qoshiqni ushlab, og‘ziga olib borishga harakat qilyaptimi? Bu qiziqarli lahzalarni qo‘llab-quvvatlash uchun qo‘shimcha ovqatni boshlagan chaqaloqlarga mos taomlarni tanlang.'),
  ('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6', 'Ertak bilan uyquga ketish 🪄', 'Aqlli ertaklarda faqat musiqa va tabiat tovushlaridan iborat maxsus fon yarating. Hech qanday so‘z yo‘q, faqat xotirjamlik bor.'),
  ('eca3e78d-00de-4e77-bade-43808f152e4f', 'Mehrga to‘la bo‘salar 🥰', 'Siz uni o‘pganingizda, u ham sizga egilib, lablarini cho‘zadimi yoki yuzingizni ho‘l qilib yuboradimi? Uning mitti bo‘salari barcha charchog‘ingizni unutishga yetadi.'),
  ('863a6afb-427b-4143-a527-2e01fe303116', 'Dadaning kulgili qiliqlari 🤡', 'Chaqaloqni kuldirishning eng yaxshi yo‘li — dadasining g‘alati tovushlar chiqarishidir. Bu oqshomdagi quvnoq lahzalardan chaqalog‘ingiz bilan birga zavqlaning.'),
  ('b4676fcf-2967-4b49-adbd-12ebe6a54334', 'Dardlashishga ehtiyoj bor 💬', '«Uning allaqachon 1 yoshga to‘lganiga ishona olmayapman», degan o‘y sizni hayajonga solyaptimi? Bu go‘zal tuyg‘uni Anacan hamjamiyatidagi onalar bilan baham ko‘ring.'),
  ('b86239c1-4a1c-48b3-b49a-3fd4a012ebae', '1 yoshga to‘lishiga atigi 15 kun qoldi! 🎈', 'Nostalgiya shamollari esmoqda! Tug‘uruqxonadan chiqqan ilk kuningizni eslaysizmi? Endi esa 1 yoshga tayyorgarlik ko‘ryapsiz! Chaqaloq fotosessiyasida uning ilk va hozirgi suratini yonma-yon joylashtiring!'),
  ('222d12a8-4347-4dce-afd7-4a0890721d0b', 'Qaysar tunlar 🥱', 'Uxlamaslik uchun bor kuchi bilan qarshilik qilyaptimi? Kunduzgi uyqulardan birini qisqartirish vaqti kelgan bo‘lishi mumkin. Kun tartibini ko‘rib chiqing.'),
  ('5047e51c-64dc-4fe5-bc38-0409a743d0f6', 'Bo‘yi va vazni o‘sishini tekshiramiz! 📏', '1 yoshdagi ko‘rikka oz qoldi. Rivojlanishni kuzatish bo‘limidagi so‘nggi ma’lumotlarni yangilang, sog‘lom rivojlanish grafigini ko‘rib, faxrlaning.'),
  ('873f2996-36df-4d67-a2df-ec60f668be2f', 'Ovqat minorasi quladi 🥣', 'Qoshiqni ataylab yerga tashlab, sizga qarayaptimi? U tortishish kuchi va sizning munosabatingizni sinab ko‘ryapti. Sabrli bo‘ling, bu o‘yinning bir turi.'),
  ('8cd57628-b75f-4445-8bc9-6b180e6572dc', 'Bugun aqlli ertakda 🪄', 'Aqlli ertaklarda qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating.'),
  ('94b60a89-bc34-41d8-818c-174aa7ed663b', 'Tozalashmi yoki dam olishmi? 🛋️', 'Bola uxlaganda idish yuvish mashinasi tomon yugurmang. Divanga yoting, ko‘zlaringizni yuming va 15 daqiqa shunchaki nafas oling. Siz robotmisiz? Yo‘q.'),
  ('c7b84129-89ab-4610-b19f-84959d6194f9', 'Shkaf izquvari 🕵️‍♀️', 'Oshxonadagi barcha qozonlar yerdami? Xavfsiz buyumlar bilan o‘ynash uning mantiqiy fikrlashini rivojlantiradi. Xazinani bemalol izlashiga imkon bering.'),
  ('03283459-7c0f-4d41-9c06-406552e1c477', 'Mukammallik illyuziyasi 🛑', 'Bugun hech narsa reja bo‘yicha ketmadimi? O‘zingizni ayblamang. Siz haqiqiy onasiz, ijtimoiy tarmoqlardagi filtrlangan illyuziya emassiz.'),
  ('3843a02f-a85f-47a9-97ba-0e63677749e2', 'Jimjitlik qahramoni 🤫', 'Chaqaloq uxlagan paytda uydagi har bir tovush bombadek tuyuladi. Shovqin o‘lchagich yordamida xonadagi tovush chegarasini belgilash bilan birga, qadamlaringizni ham yengillashtiring.'),
  ('fde65599-b651-49fa-a50a-5b78bed58d9f', 'Ko‘rsatkich barmoq faol ☝️', 'U uzoqdagi buyumni barmog‘i bilan ko‘rsatib, unga munosabat bildiradi. Bu diqqatni yo‘naltirishning eng yuqori bosqichidir. U bilan birga o‘sha buyumga qarang.'),
  ('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6', 'Sigir sutini bersam bo‘ladimi? 🥛', '1 yoshga yaqinlashganda menyu o‘zgaradi. Sigir sutiga o‘tish yoki asal kabi oziq-ovqatlar haqida savollaringiz bo‘lsa, darhol Anacan AI’dan so‘rang.'),
  ('6b37b92f-5c61-4852-9ace-caab2bda465b', 'Oilaviy sayr va rejalar! ☕', 'Tug‘ilgan kunga oz qoldi! Do‘stlar va oila a’zolari bilan uchrashish uchun bolalar aravachasi bilan bemalol kira oladigan kafelarni Onalar uchun qulay joylardan toping.'),
  ('fedb8c6b-7722-4e20-9134-1af5ae254e85', 'Massaj vaqti 💆‍♂️', 'Bola uxlagach, kun davomida to‘plangan stressdan xalos bo‘lish uchun hamrohingiz bilan bir-biringizning yelkangizni massaj qiling. Siz bir jamoasiz!'),
  ('11e743be-fb20-462f-8c74-07c143992d51', '1 yoshga to‘lishiga 10 kun qoldi! 🎂', 'Hayajon ortmoqda! Tug‘ilgan kun torti, kiyimlar, mehmonlar ro‘yxati... Barcha fikrlaringizni Kayfiyat kundaligining maxsus qaydlar bo‘limiga yozib, tartibga soling.'),
  ('15436a4e-52bb-4539-9146-377403746da0', 'Onalarning dildoshligi 💬', '“Mening bolam nega hali ham yurmayapti?” kabi savollar sizni charchatyaptimi? Anacan hamjamiyatiga qo‘shiling va har bir bolaning rivojlanish sur’ati o‘ziga xos ekanini ko‘ring.'),
  ('21394622-dd96-488a-a90a-b8f72d718390', 'Birinchi oyoq kiyim tanlovi! 👟', 'Qadamlar tezlashmoqda! Uning oyoqlari rivojlanishini qo‘llab-quvvatlaydigan, ortopedik va tagcharmi yumshoq ilk oyoq kiyimlarini tanlash uchun Tavsiya etilgan mahsulotlar ro‘yxatimizni albatta ko‘rib chiqing.'),
  ('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1', 'Uyda xavfsizlik choralarini ko‘ring! 🛡', '️ U mustaqil yura boshlagani sari xavflar ham ortadi. Bolalar uchun xavfsizlik qulflari va zina to‘siqlarini Tavsiya etilgan mahsulotlar bo‘limidan ko‘rib chiqing.'),
  ('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b', 'O‘zgarayotgan tanangiz 👗', 'Ko‘zgudagi qomatingizga qarab xafa bo‘lyapsizmi? Siz shu tanangiz bilan bir insonni dunyoga keltirdingiz. O‘zingizni quchoqlang va qanchalik kuchli ekaningizni eslang.'),
  ('f38aba52-8d3a-44ad-96bf-7d9de570ef68', 'Onadan ajralishni istamaslik 🥰', 'Hatto hojatxonaga kirganingizda ham eshik ortida sizni kutib yig‘laydi. Ajralish xavotiri eng yuqori darajaga yetgan. Har safar unga “Men shu yerdaman”, deb ishonch bering.'),
  ('51bb1e4c-965f-4d69-b6e7-c79da0dce45c', 'Onalar uchun maskan ☕', 'Uyda qolaverib, quvvatingiz tugadi. Onalar uchun qulay maskanlar orasidan bolalar menyusi bor va bemalol o‘tirishingiz mumkin bo‘lgan kafeni tanlab, o‘zingizga vaqt ajrating.'),
  ('814176f3-c727-409b-b14a-fa62636170f1', 'Kitoblarga qiziqish 📖', 'Kechki tartibingizga qog‘oz kitoblarni ham kiriting. U endi sahifalarni o‘zi varaqlashga urinmoqda. Ovoz ohangingizni ertak sur’atiga moslashtiring.'),
  ('f73c2769-0def-42bc-93e0-9a021c41b271', 'Musiqaga raqs tushayotgan tana 🎶', 'Televizordan ritmik ovoz eshitishi bilan dumbasini qimirlatadi. Uning musiqani idrok etish qobiliyati rivojlanmoqda — unga qo‘shiling va bu ajoyib lahzani birga zavqlanib o‘tkazing.'),
  ('4c628627-3074-421f-9cfc-318df363eaf0', 'Qaysi ko‘krak bilan emizganingizni unutdingizmi? 🤱', 'Anacan taymeri sizning o‘rningizga o‘ng/chap ko‘krakni eslab qoladi. Emizishni hoziroq taymer yordamida boshlang!'),
  ('99abcc3d-bec9-4537-89f9-92bfe6f4056c', 'Ajoyib kunning yakuni. ✨', 'Siz ajoyib onasiz va 1 yildan beri chinakam qahramonlik ko‘rsatib kelmoqdasiz! Kayfiyat kundaligiga o‘zingiz bilan faxrlanishingizni yozing va xotirjam uxlang.'),
  ('d58a373d-b464-4fff-9b8e-74a104499618', '1 yoshga to‘lishiga atigi 5 kun! 🎈', 'Sanoqli kunlar qoldi! Birinchi tug‘ilgan kun! Bezакlar, jajji mehmonlar... Anacan hamjamiyatiga kirib, onalardan 1 yosh bayrami uchun kreativ g‘oyalar oling.'),
  ('0549edc6-63d2-4caa-a43c-f029f7f39465', 'Tish chiqish og‘riqlari 🦷', 'Milklari yana qizarib, so‘lagi tinmay oqyaptimi? Balki birinchi oziq tishlari chiqayotgandir.'),
  ('1c81021a-496b-49c0-86bc-4bde92ff779d', 'Shovqinni nazorat qilish 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — eng nozik vaqt. Shovqin o‘lchagich yordamida atrof-muhitni tekshiring va to‘satdan chiqadigan shovqinlardan ehtiyot bo‘ling.'),
  ('262cbb13-eb12-4831-9fe5-37ece168bdfa', 'Tana tili bilan javob beradi 🗣️', '“Ketdikmi?” desangiz, qo‘llarini ko‘taradi yoki “Yo‘q” desangiz, boshini chayqaydi. Uning tushunish qobiliyati hayratlanarli darajada oshdi!'),
  ('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8', 'Toza havo — najotkor 🌳', 'Uyda injiqligi kuchaysa, ob-havo va kiyimini tekshiring, uni aravachaga o‘tqazing va darhol bog‘ga chiqing. Tabiat — uni tinchlantirishning eng tezkor yo‘li.'),
  ('39697061-01f6-4b41-8098-183a43f25058', 'Kublardan qal’a qurmoqda 🧱', 'Ikki yoki uchta o‘yinchoq kubni ustma-ust qo‘yishga urinmoqda. Uning bu kichik muhandislik urinishlarini xotirjam kuzating va olqishlang.'),
  ('c5294433-a84c-4be9-ad57-5744718366c9', 'Bugun hamma narsadan jahlingiz chiqdimi? 📝', 'Bolangiz uxlaganda, kayfiyat kundaligiga his-tuyg‘ularingizni yozing. Ertaga yangi va yanada go‘zal kun bo‘ladi.'),
  ('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a', 'Juftingiz bilan ilk kunlarni eslab, birga kuling.', 'Siz bu 1 yoshga osonlikcha yetib kelmadingiz! Bu — jamoa sifatidagi g‘alabangiz.'),
  ('5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf', 'Katta kungacha 2 kun qoldi! 🗣', '️ Sizni «Ona» yoki «Dada» deb chaqirishi — eng ajoyib sovg‘a. Ilk so‘zlarning rivojlanishini qo‘llab-quvvatlash uchun bloglardagi tavsiyalarni o‘qing.'),
  ('e7879bf6-3dca-4f0b-9981-d7f119d39235', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yoritilgan muhitda ajraladi.'),
  ('14e209af-2489-4eb6-a1f0-be21be617768', 'Ertak bilan uyquga o‘tish 🪄', 'Aqlli ertaklarda faqat musiqa va tabiat tovushlaridan iborat maxsus fon yarating. So‘zlar yo‘q, faqat xotirjamlik va yoqimli intizorlik bor.'),
  ('a6e2ed87-38de-413e-9884-cda9afcbb191', 'So‘nggi tayyorgarliklar 📸', 'Shamlar, tort va kiyimlar tayyormi? Telefon xotirasini bo‘shating, ertaga chaqaloq fotosessiyasi uchun juda ko‘p joy kerak bo‘ladi!'),
  ('c639a352-3f59-4488-9ce0-2ba361a4790c', 'Ertaga 1 yosh! 🎉', 'Nostalgiya onlari! Tug‘ruqxonadan chiqqan o‘sha ilk kuningizni eslaysizmi? Kayfiyat kundaligini oching va bugun kechqurun unga kelajakda o‘qiydigan, his-tuyg‘ularga boy maktub yozing.'),
  ('0eb89ca2-1605-4f92-8c61-0198a966afb1', 'G‘alaba raqsi 💖', 'Bir yillik charchoq va faxrni bugun kechqurun turmush o‘rtog‘ingiz bilan sham yorug‘ida nishonlang. Siz mukammal jamoasiz!'),
  ('2e46d431-01ee-479e-a146-2b349cd7f234', 'BIR YOSH! ILK TUG‘ILGAN KUN! 🎂🎉', 'SIZ AJOYIBSIZ! Naqd 365 kun, uyqusiz tunlar, ilk qahqahalar, ilk qadamlar! U endi 1 yoshda! Chaqaloq uchun fotosessiya uyushtirib, ushbu tarixiy kunni eng chiroyli kadrlar bilan abadiylashtiring!'),
  ('3c2fa886-d095-424c-ad68-b439a1ffc0b9', 'O‘zingizni olqishlang 👏', 'U qorningizda 9 oy, bag‘ringizda esa 1 yil ulg‘aydi! Bugun nafaqat uning, balki sizning ham onalik tug‘ilgan kuningiz. O‘zingiz bilan faxrlaning!'),
  ('0944c4dc-3e95-4efb-97dc-8b4809d96d45', 'Kichkintoylik (Toddler) davri boshlanmoqda 🌟', 'Chaqaloqlik davri ortda qoldi! Endi u rasman o‘z shaxsiyatini namoyon qiladigan va hamma narsani «o‘zim» deydigan bolakay. Sabr va mehrga to‘la yangi sarguzasht boshlanmoqda!'),
  ('569602c0-f0cf-4229-b498-984bfdabf097', 'Aqlli ertak vaqti 🪄', 'Aqlli ertaklarda 1 yoshga to‘lgan va dunyoni kashf etayotgan katta qahramon haqida hikoya yaratib, odatingizni davom ettiring.'),
  ('ae6d1371-ca56-433f-b6db-9c70c59094fb', 'Injiqliklar o‘zgarmoqda 🛑', 'O‘zini yerga tashlash kabi yangi jazava xurujlari (tantrumlar) boshlandimi? U hali his-tuyg‘ularini boshqara olmaydi. Uning ko‘zlari bilan bir balandlikda bo‘lish uchun egilib, xotirjam gapirish orqali bu xurujlarni yengib o‘ting.'),
  ('6e25898e-24d8-4ca6-8cbe-71a271993d6f', 'Tovushlarni boshqarish 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — eng nozik vaqt. Shovqin o‘lchagich yordamida atrof-muhitni tekshiring va to‘satdan chiqadigan shovqinlardan ehtiyot bo‘ling.'),
  ('d5e35c42-03ad-4068-b27d-3efca55a35ad', 'Qoshiqni o‘zi ushlash istagi 🥄', 'U qoshiqni o‘zi ushlab, pyureni mustaqil yeyishni xohlaydi. To‘kadi, ust-boshini kir qiladi, ammo bu harakat ko‘nikmalari uchun juda muhim. Unga ruxsat bering.'),
  ('f93e7290-30ca-44fe-a1e4-55044619c9a6', 'Energiyaga ehtiyoj 🍲', 'Yugur-yugurlar yanada ko‘paydi. Sog‘lom retseptlardan sizga kuch beradigan, temir va oqsilga boy tushlikni tanlab, quvvat to‘plang.'),
  ('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarning barcha yukini yolg‘iz o‘zingiz ko‘tarmang. Juftingizni ham uyg‘oting: bir jamoa bo‘lish — mas’uliyatni teng taqsimlash demakdir.'),
  ('50b26349-9946-4708-aec2-e87f1b15952f', 'Ilk mustaqil qadamlar? 🧗‍♂️', 'Balki bugun, balki ertaga... U endi hech narsadan ushlamasdan bir-ikki qadam tashlashga urinmoqda. Rivojlanish kuzatuvchisiga qayd etishga tayyor turing!'),
  ('9407d96f-ca5a-4378-a7c6-ee00256c457a', 'Ob-havoni o‘rganish ⛅', 'Sayrga chiqayotganda derazadan qarab qaror qilmang. Ob-havo va kiyim tanlash vositasi sizga shamol tezligi hamda mos kiyimlar uyg‘unligini bir zumda aytib bersin.'),
  ('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2', 'Dardlashishga ehtiyoj bormi? 💬', '“1 yoshdan keyin yanada qiyinlashadi”, deganlar sizni qo‘rqityaptimi? Anacan hamjamiyatida yozing va onalarning haqiqiy, ijobiy tajribalarini o‘qing.'),
  ('4c27d203-23f5-4e87-918e-d40df5e30875', 'Tungi orom 🛀', 'Iliq vanna, massaj va xonani qorong‘ilashtirish. Uyqu tartibiga rioya qilish — tun bo‘yi uzluksiz uyquning eng asosiy siridir.'),
  ('6ad316f8-edd9-4dff-aac4-f3492d4a602a', 'Oddiy ko‘rsatmalarni bajaradi 🧸', '“To‘pni menga ber”, desangiz, uni rostdan ham topib olib keladimi? So‘zlarni tushunish qobiliyati ayni cho‘qqisida! Uni o‘yinlarga ko‘proq jalb qiling.'),
  ('028a5b0d-04de-43dc-984d-eaf6e3427904', 'Birinchi oyoq kiyimni tanlash 👟', 'U yurishga tayyorlanyapti, ammo uyda oyoq kiyim kiyishi kerakmi? Anacan AI-dan ilk qadamlar uchun oyoq kiyimlar va yalangoyoq yurishning foydalari haqida so‘rang.'),
  ('5d68d6d5-05d2-43b4-bd93-e3f95983e445', 'Ro‘yxat hayotni qutqaradi 🛒', '1 yoshdan keyin menyu o‘zgaradi. Uyga sigir suti yoki boshqa mahsulotlar kerakmi? Darhol Xaridlar ro‘yxatini to‘ldirib, juftingizga yuboring.'),
  ('9a073421-3e36-4699-bbbd-50a69e46f431', 'O‘zingizga vaqt ajrating. 🛁', 'Kun bo‘yi yuradigan bolaning ortidan yugurish oson emas. Charchog‘ingizni Kayfiyat kundaligiga yozib, yengil torting va dam oling.'),
  ('2cdeb7df-f4f5-4a75-ae9b-552210a168fe', 'Kitoblarni varaqlayapti 📖', 'Qalin sahifali kitoblarning sahifalarini o‘zi mustaqil varaqlab, rasmlarga munosabat bildiryaptimi? Unga ko‘plab rang-barang ertak kitoblarini o‘qib bering.'),
  ('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd', 'Ilk mustaqil qadamlar! 🧗‍♂', '️ Mebelni qo‘yib yuborib, mustaqil turibdimi va balki o‘sha uzoq kutilgan ilk qadamini tashlayaptimi? Bu unutilmas tarixiy lahzani o‘tkazib yubormang va videoni darhol Chaqaloq albomiga yuklang.'),
  ('beccb06c-7cf4-4f1a-9455-17d5b952ad96', 'Musiqali oqshomlar 🎶', 'Kechga yaqin boshlanadigan injiqlikni yengishning eng oson yo‘li — uning sevimli qo‘shig‘ini qo‘yib, uni bag‘ringizga bosgancha birga raqsga tushishdir.'),
  ('0c97760a-2746-4ddf-ad12-5f44e1960612', 'Sukunatga ehtiyoj 🤫', 'Ovoz o‘lchagich yordamida xonadagi sokinlikni saqlang. Tunda bo‘lingan uyqu uning ham, sizning ham ertalabki kayfiyatingizni buzadi.'),
  ('61d67656-ab73-4417-b42d-5e55ecf64b87', '“Yo‘q” so‘zining kuchi 🛑', 'Biror narsa taklif qilganingizda boshini chayqab, “yo‘q” deyishni o‘rganibdi! Bu qaysarlik emas, balki o‘z fikrini ifodalashdir. Unga tanlash imkonini berib, tinchlantiring.'),
  ('b58ae5cb-ec5b-400f-b490-16ff65c6cead', 'Mantiqiy o‘yinlar 🧩', 'O‘yinchoqlarni qutiga solib, keyin yana hammasini tashqariga chiqaradimi? Shu tariqa unda “ichida” va “tashqarisida” tushunchalari rivojlanmoqda. Bu mashg‘ulotiga xalaqit bermang.'),
  ('6b997061-a83d-4040-b848-d55a40a87a1a', 'Sog‘lom ona 🥑', 'Chaqaloq to‘ygan bo‘lsa, endi navbat sizda. Foydali retseptlar orasidan quvvat beruvchi yegulik tanlang va hech bo‘lmasa 10 daqiqa divanda yotib dam oling.'),
  ('8d89c421-922f-4b8a-bc83-525a380ead88', 'Zinapoyaga qiziqish 🧗‍♂️', 'Pastda yurish unga kamlik qilib, zinapoyalar va mebellar ustiga chiqishga urinyaptimi? Harakat ko‘nikmalari jadal rivojlanmoqda! Uni albatta nazorat ostida saqlang.'),
  ('dacf6637-c6dd-4427-9e89-1dc06f453ae5', 'Sehrli ertak vaqti 🪄', 'Aqlli ertaklardagi «Eng kichkina qahramonning uxlab qolish sirlari» hikoyasi bilan kechki tartibingizni yanada qiziqarli qiling.'),
  ('2d2e06b1-2d94-4883-a675-93637a17ca98', 'Injiqlik avjida ☁️', 'Hech narsadan ko‘ngli to‘lmay, hamma narsaga yig‘layaptimi? Balki orqa jag‘ tishlari chiqayotgandir. Sovuq tishlagichlarni tayyorlab qo‘ying.'),
  ('2eeb1f61-7042-48aa-9ecc-41443c68b4a8', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda chaqaloq uyg‘onganida bir safar siz, keyingi safar juftingiz tursin. Ba’zan bolani faqat dadasining bir maromdagi silashi tinchlantiradi.'),
  ('d1cf73d9-421b-4ad1-b114-e5025146d5b2', 'Uy ishlarini kim qiladi? 🌪️', 'Ishlar qolib ketyaptimi? Qolaversin. Bugun uy ishlarini juftingiz o‘z zimmasiga olishini so‘rang. Siz esa dam oling.'),
  ('18cb3df2-de24-43c0-a3d0-160051dc5202', 'Hissiyotlar kundaligi 📝', 'O‘zingizni yolg‘iz his qilganingizda, his-tuyg‘ularingizni Kayfiyat kundaligiga yozing. Barcha ayollar bu yo‘llardan o‘tadi, siz kuchlisiz.'),
  ('19c626ef-26a5-49ef-921f-4577f35ab653', 'So‘rg‘ich/butilkadan voz kechish? 🍼', '1 yoshdan keyin so‘rg‘ichdan chiqarish haqida o‘ylayapsizmi? Buning eng muloyim usullarini Anacan hamjamiyatidagi onalardan so‘rang.'),
  ('c6a284e9-0bba-433f-9823-bcc74708dbd9', 'Toza havo — davo 🌳', 'Chaqaloq kun bo‘yi yig‘lab, bezovta bo‘ldimi? Yechimi juda oddiy: ob-havo va kiyimini tekshiring, uni aravachaga o‘tqazing va darhol parkka chiqing.'),
  ('5f3d97d0-e211-488f-bb05-dd9ccce213a3', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng juftingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash yukni yengillashtiradi.'),
  ('92cb503c-c013-47cb-ab12-416c047b2693', 'Rivojlanishni tekshirish 🤖', '12 oylik bolaning harakat ko‘nikmalari haqida ma’lumot kerakmi? Anacan AI-dan qisqa, aniq va pediatr tasdiqlagan ro‘yxatni so‘rang.'),
  ('f20aef27-fde2-489c-9dd8-fe28386cf1db', 'Geometrik shakllar va zehn o‘yinlari! 🧩', 'U doira yoki kvadratni mos teshiklardan o‘tkazishga harakat qilmoqda. Bu o‘rgatuvchi kashfiyotlarni Chaqaloq albomida abadiylashtiring.'),
  ('0955065c-ecf1-48ed-9f6f-735958386a41', 'Ona uchun vitamin 🥑', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi? Sog‘lom retseptlar bo‘limidan temir va kalsiyga boy yengil tushlikni tanlang.'),
  ('1d781ae8-7800-48ae-b0ee-fe44c7f13291', 'Kunduzgi uyqu o‘zgaryaptimi? 🥱', 'Kunduzgi ikki uyqudan biriga butunlay qarshilik qilyaptimi? 1 yoshdan keyin bir mahal uyquga o‘tish boshlanadi. Kun tartibini asta-sekin qayta moslashtiring.'),
  ('61536a43-b97b-4fe8-8f6a-f358141baefc', 'Ertak tinglab uxlaydi 🪄', 'Aqlli ertaklarda jasur va yoqimtoy hayvonlar haqida hikoya yarating va xonani sehrli makonga aylantiring.'),
  ('76e3844a-efe7-4daa-855a-4cfd4d92bfc9', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yoritilgan muhitda ajraladi.'),
  ('8b586560-e2d2-46b0-ba82-419bb7b56682', 'Xotira tumanligi 🛒', 'Unutuvchanlik sizni tark etmayaptimi? Uy uchun mayda-chuyda xaridlarni yodda saqlashga urinmang, darhol Xaridlar ro‘yxatiga qo‘shing, qolganini juftingiz hal qilsin.'),
  ('b87394f8-5f2b-4eb7-a491-26b80560c8a3', 'Nishonga uloqtirish ⚾', 'Qo‘lidagi o‘yinchoqni ataylab muayyan nishonga uloqtirishga harakat qiladi. Ko‘z va qo‘l muvofiqligi jadal rivojlanmoqda. Birgalikda to‘p otib, tuting.'),
  ('159279c3-df89-49cf-a71c-bb577a8dd0c3', 'Xavfli joylarga yetib borish ⚡', 'Bo‘yi yanada o‘sib, avval qo‘li yetmagan javonlarga ham yeta boshladi. Uydagi xavfsizlik choralarini zudlik bilan qayta ko‘rib chiqing.'),
  ('3b6ac273-a759-45de-9492-87af2df8cac9', 'Tun sukunati 🤫', 'Mashina yoki tashqaridagi tovushlar uni bezovta qilsa, albatta Ovoz o‘lchagich yordamida muhitni tekshiring va fonda oq shovqinni yoqib qo‘ying.'),
  ('bc24cbab-3bcd-4b5b-92fb-249b861079c2', 'O‘ynagan narsalarini hamma yoqqa sochadi.  🌪️', 'Hozir tozalik emas, sizning dam olishingiz muhim. O‘yinchoqlar ertaga ham o‘sha yerda bo‘ladi, ammo chaqaloqqa hozir tetik ona kerak.'),
  ('0693172d-9675-431e-ae2b-b1d735f8da0f', 'Barcha charchoqni bir chetga surib qo‘ying.', 'Bugun kechqurun bola uxlagach, turmush o‘rtog‘ingiz bilan jamoaviy g‘alabangizni nishonlashni unutmang!'),
  ('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125', 'O‘zingizni boshqalar bilan solishtirmang 🛑', '“Falonchining bolasi ertaroq gapirgan” degan gapni unuting. Har bir bolaning rivojlanish sur’ati o‘ziga xos. Siz unga shunchaki mehr bering.'),
  ('b9520b22-b9b3-4ca3-a219-de05702404a8', 'Bir yarim yosh sari! 📸', 'U allaqachon 12.5 oylik! Chaqaloq fotosessiyasini oching va bolalikning ushbu serharakat, jo‘shqin davridagi eng kulgili lahzalarni suratlarda muhrlab qo‘ying.'),
  ('078c86a9-a3c8-4f20-a27a-3aa00d3961ad', 'Ovqatlanish vaqtini maroqli qiling! 🥦', 'Agar chaqalog‘ingiz ishtahasiz bo‘lsa, qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan foydalanib, rang-barang va qiziqarli porsiyalar tayyorlang.'),
  ('3b7df91a-7022-4a50-9438-82f89b2240b8', 'Tana a’zolarini taniydi 👀', '“Ko‘zing qayerda?” deb so‘raganingizda, barmog‘i bilan tegib ko‘rsatadimi? Uning anglash qobiliyati ayni cho‘qqisida! Buni Rivojlanish kuzatuvchisida faxr bilan qayd eting.'),
  ('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56', 'Siz qo‘lingizdan kelganicha harakat qilyapsiz! 💖', 'Farzand tarbiyalash marafonga o‘xshaydi. Bugun kechqurun o‘zingizga biroz vaqt ajrating, sevimli filmingizni tomosha qiling yoki shunchaki dam oling.'),
  ('18eaf932-80c3-47ae-a394-f6ce083ef215', '“O‘zim yeyman” degan qaysarlik 🥦', 'U qoshiqni qo‘lingizdan olmoqchi. Olishiga ruxsat bering. Ust-boshi kir bo‘ladi, ammo bu mustaqillik hissi uning uchun juda muhim.'),
  ('b55b3812-173b-489f-a2ae-d2c78611fd35', 'Qorong‘ilik bilan do‘stlashish 🌙', 'Tezroq uxlab qolishi uchun kechki tartibga qorong‘ilik bilan tanishishni ham kiriting. Xonadagi barcha qo‘shimcha chiroqlarni o‘chiring.'),
  ('c9fb44a1-ad82-4f16-a316-50d99863130e', 'Allergiyaga shubha 🤖', '1 yoshdan keyin yangi oziq-ovqatlarni bera boshladingizmi? Agar biror xavotiringiz bo‘lsa, darhol Anacan AI yordamida qanday dastlabki choralarni ko‘rish kerakligini bilib oling.'),
  ('0c105765-0e1a-42dd-bd14-0ca4153705c0', 'Nozik motorika rivojlanmoqda. 🖍', '️ U qalam bilan qog‘ozga chizishdan zavqlanishi mumkin. Unga mos yo‘g‘on rangli qalamlar bering va ijodkorligini kuzating.'),
  ('1b77ed52-4cf2-48a6-98fc-53d0a94dc968', 'Uyqu tartibi xotirjamlik beradi. 🌙', 'Har oqshom bir xil ketma-ketlikda bajariladigan ishlar (cho‘milish, ertak, chiroqlarni xiralashtirish) uning osonroq uxlab qolishiga yordam beradi.'),
  ('795996e4-e3e1-4fa7-b442-27c8ffa35bff', 'Tish chiqishidagi og‘riqlar 🦷', 'Milklari yana qizarib, so‘lagi tinmay oqyaptimi? Tish chiqishini kuzatish bo‘limida jarayonni qayd eting va sovutilgan tishlagichlarni tayyorlab qo‘ying.'),
  ('452e9fa3-8dba-4774-8bfe-d6afa50d161c', 'Ro‘yxat juda asqatadi 🛒', 'Ovqat uchun meva yoki suli yormasi tugadimi? Xaridlar ro‘yxatini darhol to‘ldiring va kerakli mahsulotlarni turmush o‘rtog‘ingizning telefoniga yuboring.'),
  ('8c12c251-a9b5-45cb-92ff-f145e2484025', 'Devorni ushlab yurmoqda 🧗‍♀️', 'Mebel chetlaridan ushlab yonlama qadam tashlash uning sevimli mashg‘ulotidir. Mustaqil qadamlar tashlashiga juda oz qoldi! Rivojlanishni kuzatish bo‘limiga qarang.'),
  ('c7e52a2b-46d5-4446-b455-907f7523256e', 'Shovqinni nazorat qilish 🤫', 'U uxlab qolganidan keyingi dastlabki yarim soat eng sezgir davrdir. Shovqin o‘lchagich yordamida muhitni tekshiring va to‘satdan yuzaga keladigan shovqinlardan ehtiyot bo‘ling.'),
  ('9dd82a43-7f3a-4a5e-9d01-a99d7d738015', 'Mustaqil kiyinishga urinishlar. 👕', 'U endi paypog‘ini o‘zi yechishga yoki kiyishga urinyaptimi? Uning mayda motorika ko‘nikmalarini sabr bilan qo‘llab-quvvatlang.'),
  ('ccf44d60-2dc0-447f-b1ea-dd06a80f0324', 'Suv ichish juda muhim. 💧', 'Faol bolalar tez chanqaydi. Kun davomida, ayniqsa, kechki ovqatdan keyin unga suv taklif qilishni unutmang.'),
  ('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d', 'Yangi o‘yinchoq kerakmi? 🛒', 'Bolangizning rivojlanishiga mos, tafakkurini charxlaydigan o‘rgatuvchi o‘yinchoqlar izlayotgan bo‘lsangiz, Tavsiya etilgan mahsulotlar ro‘yxatimizni ko‘rib chiqing.'),
  ('10934358-ef97-4dab-87ad-73a62aee1231', 'Tozalashmi yoki dam olishmi? 🛋️', 'Bolangiz uxlaganda idish yuvish mashinasi tomon shoshilmang. Divanga yonboshlang, ko‘zlaringizni yuming va 15 daqiqa shunchaki nafas oling.'),
  ('58866969-75c5-44cd-a308-210945d7a2af', 'Sinov va xato 🧱', 'U ikkita o‘yinchoq kubikni ustma-ust qo‘yishga urinadi, ammo ular qulab tushadi. U diqqat bilan yana urinib ko‘radi. Uning muhandislikka oid urinishlarini jimgina kuzating.'),
  ('94a9a306-04fb-42bb-9962-95b473b02f89', 'Hissiyotlar kundaligi 📝', 'O‘zingizni yolg‘iz his qilganingizda, his-tuyg‘ularingizni Kayfiyat kundaligiga yozing. Barcha ayollar bu yo‘llardan o‘tadi, siz kuchlisiz.'),
  ('56403a92-c6d5-492f-b073-20bcd436f218', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarni butunlay yolg‘iz o‘zingiz zimmasiga olmang. Turmush o‘rtog‘ingizni ham uyg‘oting — jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('763e2885-6f82-4d6b-8ec4-680155ad7a5f', 'Onalarning dardlashuvi 💬', 'Bolangizning jazava xurujlarini yenga olmayapsizmi? Darhol Anacan hamjamiyatiga kiring, boshqa onalarning qo‘llab-quvvatlovchi izohlarini o‘qib, yengil torting.'),
  ('f47e2fcf-5030-43a8-a77b-79834cb3f95a', 'Katta his-tuyg‘ular, kichik tana 🛑', 'Istagi amalga oshmasa, o‘zini yerga tashlaydimi? U bilan bir balandlikda bo‘lish uchun egilib, xotirjam gapiring va bu xurujlarni birga yengib o‘ting.'),
  ('a0e7f0f6-1438-4f75-acb4-559e4df47974', 'Sukunatga ehtiyoj 🤫', 'Ovoz o‘lchagich yordamida xona tinchligini saqlang. Tunda bo‘linadigan uyqu ham uning, ham sizning ertalabki kayfiyatingizni buzadi.'),
  ('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95', 'Onalar uchun joy ☕', 'Uyda qolaverib, quvvatingiz tugadi. Onalar uchun qulay joylar orasidan bemalol o‘tira oladigan kafe tanlab, o‘zingizga vaqt ajrating.'),
  ('f34137b7-333a-47bb-8fab-66dd8be52bfb', 'Raqs va ritmlar 🎶', 'Televizor yoki telefonda ritmik ovoz eshitishi bilan raqsga tushadimi? Uning musiqani idrok etish qobiliyati to‘liq ishga tushgan — unga qo‘shilib, birga raqsga tushing!'),
  ('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5', 'Kechki ertak sehrlidir. 📖', 'Uxlashdan oldin o‘qilgan qisqa hikoya bolaning tasavvurini rivojlantiradi va orangizdagi hissiy rishtani mustahkamlaydi.'),
  ('b28c4699-a204-48ae-80c2-bef5008fdffd', 'Mustaqil o‘ynash ko‘nikmasi. 🧩', 'Qisqa vaqt bo‘lsa-da, o‘zi mustaqil o‘ynay olishi uning diqqat-e’tibori rivojlanayotganini ko‘rsatadi. Bunday paytlarda uni uzoqdan mehr bilan kuzating.'),
  ('e6b48652-88e0-49d8-b2cc-654a9f8eb626', 'O‘sishini kuzatamiz. 📏', 'Farzandingizning kiyimlari kichik bo‘lib qolyaptimi? Vazn kuzatuvchisi bo‘limiga yangi ko‘rsatkichlarni qo‘shib, uning sog‘lom rivojlanishini qayd eting.'),
  ('05e8d5ea-453b-4a35-a697-81e0b9ca911a', 'Kattalarga taqlid qilish 🧹', 'Siz uyni artayotganingizda, u ham qo‘liga latta olib, xuddi shunday qilishga urinadimi? U sizning ko‘zgungiz! Qilayotgan har bir ishingizni takrorlaydi.'),
  ('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0', 'Parkmi yoki uymi? ⛅', 'Tashqariga chiqmoqchisiz, ammo havo shamolli. Ob-havo va kiyim bo‘yicha yordamchi sizga mos kiyimlar to‘plamini darhol tavsiya qilsin.'),
  ('ecb2b9d1-a640-4303-b570-f3c7f463e0ab', 'Injiqlik bilan o‘tadigan tunlar 🥱', 'Uxlamaslik uchun bor kuchi bilan qarshilik qilyaptimi? Kunduzgi uyqu vaqtlarini va uyqu tartibini qayta ko‘rib chiqing.'),
  ('8a5f3751-2bcd-4454-bfef-74c90f1c3f85', 'Kun oxiri — o‘zingiz uchun vaqt. 🛁', 'Bugun juda charchadingizmi? Iliq dush qabul qiling, dam oling va qilgan barcha ishlaringiz uchun o‘zingizga minnatdorlik bildiring.'),
  ('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8', 'Tana a’zolarini o‘rganamiz! 👃', '«Burning qayerda?» deb so‘raganingizda, kichkina barmog‘i bilan ko‘rsatadimi? Bu yoqimli kashfiyotlarni ko‘zgu qarshisida o‘yinga aylantirib, birga zavqlaning.'),
  ('e70adad3-3a0b-4d15-ab3c-9f286916a872', 'Foydali tamaddi vaqti. 🍎', 'Energiyasi tugamaydigan bolalar uchun meva bo‘laklari yoki sabzavot tayoqchalari ajoyib tanlovdir. Ularni o‘zi ushlab yeyishiga imkon bering.'),
  ('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3', 'Kichkina rassom ish ustida! 🖍', '️ Yo‘g‘on rangli qalamlar bering va qog‘ozda erkin chizishiga ruxsat bering. Bu mayda motorika va ijodkorlikni rivojlantirish uchun juda foydali.'),
  ('ccb3a3d0-8dc5-450a-b184-37cf81a39c01', 'Toza havo ikkingizga ham yaxshi ta’sir qiladi. 🌳', 'Onalar uchun qulay joylar xaritamizdan bolalar aravachasi bilan bemalol sayr qilishingiz mumkin bo‘lgan yangi bog‘ni topib, sayrga chiqing.'),
  ('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5', 'Uyqu tartibi xotirjamlik bag‘ishlaydi. 🌙', 'Har oqshom bir xil ketma-ketlikda bajariladigan ishlar (cho‘miltirish, ertak aytish, chiroqlarni xiralashtirish) uning tezroq uxlab qolishiga yordam beradi.'),
  ('04429520-36d1-489e-8ec7-309a2c08ae92', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng turmush o‘rtog‘ingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash yukni yengillashtiradi.'),
  ('05fff0e7-029c-401c-bfab-497bbc099997', 'So‘zlarning ma’nosini biladi 🗣️', '«To‘pni olib kel», desangiz, u haqiqatan ham borib, to‘pni qidiradi. So‘z boyligi tez oshmoqda. U bilan murakkabroq jumlalar tuzib gaplashing.'),
  ('ec4b2f26-3631-4fed-9578-c9539a35a5c0', 'Cho‘ntagingizdagi ro‘yxat 🛒', 'Kundalik yugur-yugurda shampun tugadimi yoki taglikmi? Buni eslab yurishga urinmang, xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan sinxronlashtiring.'),
  ('663824a2-b8fe-471a-b981-3eb69f3a2c7f', 'Katta his-tuyg‘ular, kichkina tana. 🌪', '️ O‘zini ifoda eta olmaganda jahli chiqib yig‘lashi tabiiy. Uning bo‘yi darajasigacha egilib, hislarini tushunayotganingizni sokin ovozda ayting.'),
  ('8be96289-58a8-4a48-89ec-c4ba0488e973', 'Suv bilan o‘ynash tinchlantiradi. 💧', 'Kichik tog‘orachaga suv solib, ichiga plastik idishlarni tashlang. Suv bilan o‘ynash bolalarga ortiqcha energiyasini chiqarish va tinchlanishga yordam beradi.'),
  ('a70fb0ff-98b0-4735-ac10-846168dd5d60', 'Savolingiz bormi? 🤖', '«1 yosh inqirozini qanday boshqarish kerak?» kabi muhim savollaringizni hatto tunda ham Anacan AI yordamchimizdan so‘rab, mutaxassis maslahatini oling.'),
  ('12139491-dd07-42f8-b056-98645d9880be', 'Vaqtni to‘xtatuvchi kadr 📸', 'U har kuni biroz ulg‘aymoqda. Darhol Chaqaloq fotosessiyasini ochib, uning bu samimiy lahzasini xotiraga muhrlang.'),
  ('302d3885-ce15-4277-a0cf-d95f95d7ed63', 'Yorug‘likni pasaytiring 🌙', 'Uyquga 1 soat qolganda uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch muhitda ajraladi.'),
  ('78f8f713-17f3-46f4-83f8-9cdbfd0c9894', 'Mustaqil o‘yin vaqti 🧸', 'Endi u 10-15 daqiqa davomida o‘yinchoqlari bilan mustaqil shug‘ullana oladi. Uni chetdan kuzatib, sukunatdan zavqlaning.'),
  ('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd', 'Ob-havoni tekshirish ⛅', 'Tashqaridagi ob-havo unchalik aniq emasmi? Ob-havo va kiyim vositasi sizga shamol tezligi hamda mos kiyimlar to‘plamini bir zumda tavsiya etsin.'),
  ('bac8ff9b-6338-4b34-a5d6-84b7aefd251c', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda chaqaloq uyg‘onishlarining barcha yukini yolg‘iz ko‘tarmang. Juftingizni ham uyg‘oting — jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('c1daed2c-e22f-4c5a-8534-4ff90b6b866e', 'O‘yinchog‘imni o‘zim topaman 🧸', 'Ko‘zidan uzoqlashtirib, biror narsaning orqasiga yashirgan o‘yinchoqni borib topyaptimi? Demak, u narsalar ko‘rinmasa ham mavjud bo‘lishini anglayapti!'),
  ('2a991705-4255-4931-9ad5-cef8eb9bf0dd', 'Kichik yordamchingiz! 🧹', 'Sizga taqlid qilib, qo‘liga latta olib chang artishga urinyaptimi? Bu yoqimli va ibratli lahzalarni kelajak uchun Chaqaloq albomiga video sifatida albatta qo‘shing.'),
  ('813ebcca-fa4c-42de-926c-6ca1c1526de6', 'Musiqa bilan sokinlik. 🎶', 'Kechki payt harakatli o‘yinlar o‘rniga sokinroq musiqa tinglab, uni uyquga, o‘zingizni esa xotirjamlikka tayyorlang.'),
  ('ce071e13-068a-4c5a-8d4c-437e6f25658d', 'Ovqat tanlash. 🍲', 'Ayrim mahsulotlarni rad etsa, xavotir olmang. Ularni boshqa kunlari turli ko‘rinishlarda (masalan, pyure emas, balki qo‘lda ushlab yeyiladigan ovqat sifatida) yana taklif qiling.'),
  ('502b8118-151f-47c7-9476-eb53fa55cfd0', 'Minoralar qad rostlamoqda! 🧱', 'U endi 3-4 ta kubikni ustma-ust qo‘ya oladi. Diqqat va ko‘z-qo‘l muvofiqligini talab qiladigan bu o‘yinini olqishlab, uni qo‘llab-quvvatlang.'),
  ('af470a51-532a-4658-877a-26e61845210a', 'Ijtimoiylashish vaqti. 👶', 'U bog‘da boshqa bolalarni diqqat bilan kuzatyaptimi? Hali birga o‘ynamasalar ham, yonma-yon o‘ynash (parallel o‘yin) davri ijtimoiylashishning ilk katta qadamidir.'),
  ('ceb1c77d-c486-4755-b204-47ec200fcd34', 'U ovoz ohangingizni tushunadi 🗣️', 'Jiddiy ohangda «yo‘q» desangiz, to‘xtab, sizga qaraydimi? U endi his-tuyg‘ular va taqiqlarni tushuna boshlayapti!'),
  ('53cb1b60-78f0-41c1-a42e-b48a4324533b', '400 kunlik hayajon! 🌟', 'Ertaga katta kun — to‘rt yuzinchi kun! Bu 1 yoshu 1 oydan ham ko‘p! Uyda kichik bayram muhitini yarating, telefoningiz xotirasini bo‘shating.'),
  ('9e145532-f5a6-48ed-a07c-a3e9fc574858', 'Massaj vaqti 💆‍♂️', 'Bola uxlagach, kun davomida to‘plangan stressni chiqarish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz bir jamoasiz!'),
  ('fab52013-4ea8-458f-b397-01341fb91dad', 'O‘zingizni kechirish oqshomi 📝', 'Bugun hamma narsa asabingizga tegdimi? Bola uxlagach, his-tuyg‘ularingizni Kayfiyat kundaligiga yozing. Ertaga yangi va yanada go‘zal kun bo‘ladi.'),
  ('165064a6-acf5-4848-b342-4a3782635921', 'Ajoyib 400 kun! 🎉', 'Tabriklaymiz! Siz mana shu jo‘shqin yo‘lni roppa-rosa 400 kundan beri birga bosib kelyapsiz! Bu alohida kunni hoziroq nishonlang!'),
  ('894151c3-97b8-419f-9602-aa08da619716', 'Mustaqil ovqatlanishda davom etamiz. 🥄', 'Ust-boshi kir bo‘lsa ham, o‘z qoshig‘i bilan ovqatlanishga harakat qilishiga imkon bering. Bu uning o‘ziga bo‘lgan ishonchi va mushaklar muvofiqligini rivojlantiradi.'),
  ('8c8e0b49-c38c-485a-b336-5facb1258a02', 'Siz eng yaxshisiz! ✨', '400 kun davomida ko‘rsatgan fidoyiligingiz beqiyosdir. Endi chuqur nafas oling, orqaga suyaning va xotirjam dam oling.'),
  ('05dbf09b-2a49-4886-a4e4-6f85e7cbea42', 'To‘rt devordan tashqariga ⛅', 'Bola uyda energiyasini sarflay olmay, injiqlik qilyaptimi? Tabiat — eng yaxshi tinchlantiruvchi. Ob-havoni hisobga olib, mos kiyimlarni tanlang va darhol parkka yo‘l oling.'),
  ('3cf4affc-53f5-4c77-84f1-006d5732e36a', 'Dada bilan o‘yin vaqti 👨‍👧', 'Kun bo‘yi uning ortidan yugurib, oyoqlaringiz toliqqan. Endi Hamkor rejimi vaqti. Polda dumalash va ot bo‘lib o‘ynashni dadasiga qo‘yib bering. Siz esa dam oling.'),
  ('f1269e86-21d6-4d2f-83e1-31926957408a', 'Xonalararo marafon 🏃‍♂️', 'Yurish unga kamlik qilyapti, endi xonadan xonaga yugurish boshlandi! Tik turgan holda muvozanat saqlashi tobora yaxshilanmoqda. Rivojlanish kuzatuvchisida yirik motorika bo‘yicha bu katta yutuqni qayd eting.'),
  ('7df527b0-7bf7-42d6-b9f4-0f231186e70c', 'Menyu diktatori 🥣', 'Kecha yoqtirgan taomini bugun chetga suryaptimi? 1 yoshdan keyin ovqat tanlash odatiy hol. Vahimaga tushmay, Sog‘lom retseptlardan boshqa muqobillarni izlang.'),
  ('85bb394b-b9a2-4a30-a34a-98479663ff2d', '“Bu nima?” davri ☝️', 'U hamma narsani barmog‘i bilan ko‘rsatib, o‘ziga xos tovush chiqaradi. U sizdan atrofdagi narsalarning nomini aytishingizni istayapti. U ko‘rsatgan har bir narsaning nomini sabr bilan ayting.'),
  ('f78a5d11-ba9f-41e9-8557-2840d12964be', 'Aybdorlik hissini qo‘yib yuboring 📝', 'Bugun unga kam kitob o‘qidim, ekranga ko‘p qaradi... Bu ovozlarni jim qiling! Siz qo‘lingizdan kelganini qilyapsiz. Kayfiyat kundaligiga o‘zingizga mehr bilan yozilgan bir qayd qoldiring.'),
  ('1167974e-3206-4f0f-b4e8-4d14f35444b6', 'Bir mahal uxlashga o‘tish 🥱', 'Ertalab uxlashni istamayaptimi va butun jadval buzilib ketdimi? U ulg‘aymoqda! Bu kunduzgi ikki mahal uyqudan bir mahal uyquga o‘tish davri bo‘lishi mumkin. Kun tartibini asta-sekin qayta moslashtiring.'),
  ('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2', 'Sehrli xona 🪄', 'Aqlli ertaklarda jasur qahramonning dunyoni kashf etishi haqida o‘ziga xos hikoya yarating. Ushbu yoqimli ertak bilan tungi uyquga o‘tishni osonlashtiring.'),
  ('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c', 'Onalar uchun yangi joy ☕', 'Uyda bir xil devorlarga qarayverish sizni charchatdi. Onalar uchun qulay joylar orasidan bolalar o‘yin burchagi bor kafeni toping. U o‘ynasin, siz esa qahvadan zavqlaning.'),
  ('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b', 'Birgalikda kitob o‘qing. 📖', 'U endi sahifalarni o‘zi varaqlashni xohlaydi. Qalin sahifali kitoblar va ovozli ertaklar bu davr uchun juda mos.'),
  ('d29d33a4-aed4-4635-9f37-3a7a39a378b0', 'Chegaralarni sinab ko‘rmoqda. 🛑', 'Siz yo‘q deganingizga qaramay, ko‘zingizga tik qarab, yana o‘sha buyumga qo‘l uzatyaptimi? Bu o‘jarlik emas, shunchaki chegaralarni o‘rganish uchun ularni sinab ko‘rishdir. Sabrli va izchil bo‘ling.'),
  ('f3355fe9-0c3b-41e2-9043-0a5cb8a61740', 'Tunda uyg‘onishlar. 😴', 'Tish chiqishi yoki o‘sishdagi keskin davr uyquni buzishi mumkin. Zarur bo‘lganda uyqu taymerini kuzatib, rejimdagi o‘zgarishlarni qayd eting.'),
  ('2e0b0129-5a3d-466c-a35f-ef4707dea065', 'Dadaning ovunchog‘i 🫂', 'Tunda uyg‘onganda, albatta, navbat bilan qarang. Ba’zan qorong‘ida aynan dadasining bir maromda silashi va hidi bolani bir zumda tinchlantiradi.'),
  ('812159bf-a0a9-4bf9-8e7b-97d82abbaa80', 'Kattalarga taqlid qiluvchi ko‘zgu 🧹', 'Siz uyni artayotganingizda, u ham qo‘liga latta olib, xuddi shunday qilishga urinadi. U sizning kichkina nusxangiz! Qo‘liga xavfsiz biror buyum berib, uni uy ishlariga jalb qiling.'),
  ('9510e83b-c10c-4166-b921-d1cd3c8f203c', 'Unutuvchanlikka qarshi kurash 🛒', 'Xotirangiz yana pand berdimi? Uyda tugagan har bir mayda narsani darhol Xaridlar ro‘yxatiga kiriting, turmush o‘rtog‘ingiz ishdan qaytayotganda olib kelsin.'),
  ('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c', 'Mantiqiy o‘yinlar 🧩', 'O‘yinchoqlarni qutiga solib, keyin hammasini yana chiqarib tashlayaptimi? Shu tariqa u «ichida» va «tashqarisida» tushunchalarini anglaydi. Uning bu takroriy urinishlarini indamay kuzating.'),
  ('302bafdb-c5ca-4389-a56e-16a2ddd6812b', 'Kechki tartibning kuchi 🛀', 'Iliq vanna har doim yordam beradi. Kechki tartibni aslo buzmang, chunki u chaqaloq miyasiga hozir uxlash vaqti bo‘lganini aniq bildiradi.'),
  ('309b39de-d5f5-4702-93e1-596dca9c9021', 'Quvvatingizni tiklang 🥑', 'U to‘ygan bo‘lsa, endi navbat sizniki. Kundalik yugur-yugurda tushlikni oyoq ustida yemang. Sog‘lom retseptlardan quvvat beruvchi yengil tamaddi tanlang va divanda cho‘zilib dam oling.'),
  ('66b4bd9b-8226-4190-94c7-9d50f8db6c34', 'Dardlashishga ehtiyoj bor 💬', '“Nega mening bolam bunday qilyapti?” degan o‘y sizga tinchlik bermayaptimi? Anacan hamjamiyatiga qo‘shiling, boshqa onalarning o‘xshash hikoyalarini o‘qib, ko‘nglingizni tinchlantiring.'),
  ('80e6be85-6917-46a0-b283-acc653cca6c1', 'Kitob varaqlaydigan zehn 📖', 'Qalin sahifali kitoblarni varaqlab, rasmlarga munosabat bildiryaptimi? Uning ko‘rish xotirasi rivojlanmoqda. Unga ko‘plab rangli ertak kitoblarini o‘qib bering.'),
  ('df1f7c26-41ff-4081-9b25-dae8d38c75e8', 'Siz bilan o‘tgan vaqt go‘zal. ✨', 'Har bir kun — o‘zgacha sarguzasht. U uxlayotganida mitti qo‘llariga qarab, bugungi kichik yutuqlarini o‘ylab tabassum qiling.'),
  ('52e92eba-b885-4c30-891d-aa6e5379acf9', 'Mustaqil ovqatlanishga intilish 🥄', 'Qoshiqni qo‘lingizdan olib, o‘zi ovqatlanishni xohlaydi. Ovqatni to‘kadi, ust-boshini iflos qiladi, ammo bu uning harakat ko‘nikmalari rivoji uchun muhim. Mustaqil bo‘lishiga imkon bering.'),
  ('a26c1e0d-7872-4f7e-9268-2fba22c9203a', 'Savolingiz bormi? 🤖', '13-14 oylik bolaning xulq-atvori yoki rivojlanishi haqida sizni o‘ylantirayotgan savollar bo‘lsa, Anacan AI yordamchimizdan darhol maslahat olishingiz mumkin.'),
  ('eb8ab523-6225-489f-8a09-0f37ba40956a', 'Energiyani sarflash! 🏃‍♂', '️ Kunduzgi uyqudan oldin uni biroz charchatadigan harakatli o‘yinlar (quvlashmachoq, to‘p otish) o‘ynab, osongina uxlab qolishiga yordam bering.'),
  ('5d99a4ad-d33f-448d-9f7c-32943cbfa648', 'Jag‘ tishlari chiqyaptimi? 🦷', 'Milklar shishib, hamma narsani kemiryaptimi? Orqa tishlari chiqayotgan bo‘lishi mumkin. Sovuq tish qashlagichlarni muzlatkichga qo‘ying.'),
  ('70d7d4ed-5c06-44bc-99e5-3871d07a9510', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yorug‘likli muhitda ishlab chiqariladi.'),
  ('aa9c9479-f8d5-4149-b7c4-99976958a17c', 'Xavfli joylarga yetib borish ⚡', 'Bo‘yi o‘sib, ilgari qo‘li yetmagan tokchalarga endi yetyapti. Televizor tagligi, burchaklar... Uy xavfsizligini zudlik bilan qayta ko‘rib chiqing.'),
  ('0872925d-e2d7-471e-ba13-22ee468f0a1f', 'To‘satdan uyg‘onishlar 😭', 'Yarim tunda qichqirib uyg‘onib, tinchimayaptimi? Ovozini Yig‘i tahliliga eshittirib, muammoning sababini aniqlang.'),
  ('1fe0720b-91d5-4dc9-ad61-71e5ff522246', 'O‘sish sur’ati. 📏', 'Uning tez o‘sayotganini kiyimlaridan ham sezishingiz mumkin. Kuzatuvchiga vazni va bo‘yini kiritib, sog‘lom o‘sayotganiga ishonch hosil qiling.'),
  ('ca5a420a-5b8f-49ce-b884-6a219b8b71aa', 'Katta his-tuyg‘ular, kichik tana 🛑', 'Istagi amalga oshmasa, o‘zini yerga tashlayaptimi? Bu ilk yoshdagi bolalarga xos mashhur jazava xurujlari. Xotirjamlikni saqlang, u bilan ko‘z orqali aloqa o‘rnating va yonida ekaningizni his qildiring.'),
  ('aa01a859-3ad0-4c64-9ef3-4423ccf76d24', '«Yo‘q» deyishni yaxshi ko‘radimi? 🛑', 'Sizning e’tirozlaringizga taqlid qilib, u ham hamma narsaga «yo‘q» deyishi mumkin. Bu davrda sabrli bo‘lish va unga kichik tanlovlar taklif qilish muhim.'),
  ('b8b7257f-64c5-46a3-b958-ded901da8e8d', 'Suv ichishni qiziqarli qiling. 💧', 'Faol harakatlardan keyin tanasi suvsizlanib qolmasligi uchun unga rangli idishda muntazam ravishda suv taklif qiling.'),
  ('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c', 'Dada bilan ertak vaqti. 👨‍🍼', 'Bugun kechki ertakni o‘qish va uxlatish navbatini dadasiga topshirib, o‘zingizga biroz dam olish imkonini bering.'),
  ('4484d3ee-8677-4454-8e65-371ba851a267', 'Oq shovqinning kuchi. 🎶', 'Agar serharakat kun ta’sirida uxlay olmayotgan bo‘lsa, Oq shovqinlardan okean yoki yomg‘ir ovozini yoqib, xonada sokin muhit yarating.'),
  ('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd', 'Shirin quchoqlar! 🤗', 'Uning sizni kutilmaganda quchoqlashi va o‘pishga intilishi — sevgisini ifodalash usuli. Bu betakror mehr onlaridan zavqlaning!'),
  ('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21', 'Suhbatga jalb qiling. 🗣', '️ Xonadagi buyumlarning nomini ayting va uning takrorlashini kuting. So‘z boyligi aynan shunday kichik o‘yinlar orqali ortadi.'),
  ('005096a2-1549-4208-a331-7e39e1da9587', 'Tezkor pediatr 🤖', '13.5 oylik rivojlanish sakrashlari haqida ma’lumot kerakmi? O‘zingizni qiynamang, Anacan AI’dan aniq va pediatrlar tasdiqlagan ro‘yxatni so‘rang.'),
  ('7de487db-11d1-4c22-8b8d-e58adb31344a', 'Oddiy ko‘rsatmalarni bajaradi 🧸', 'Oyoq kiyimini olib kel desangiz, rostdan ham borib olib keladimi? So‘z boyligi va tushunish qobiliyati ayni cho‘qqisida! Uni o‘yinlarga ko‘proq jalb qiling.'),
  ('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec', 'Dadaning quvnoq qiyofasi 🤡', 'Chaqaloqni kuldirishning eng yaxshi usuli — dadasining g‘alati tovushlar chiqarishi. Bu oqshomgi quvnoq onlardan bolangiz bilan birga zavqlaning.'),
  ('3170ad10-66c6-4ca0-bf72-80b0daf91373', 'Kechki tartib uyquga tayyorlaydi. 🌙', 'Har kuni bir xil vaqtda bajariladigan kichik odatlar (tish yuvish, ertak o‘qish) uning uyquga ketishini ancha osonlashtiradi.'),
  ('64832db8-28ac-41fb-8d33-21a72b48fa8c', 'Sinchkov tadqiqotchi! 🔍', 'Uydagi har bir burchak, har bir shkaf uning uchun yangi bir dunyo. Xavfsiz muhit yaratib, uy ichini erkin o‘rganishiga imkon bering.'),
  ('f283f219-7efa-4926-a360-3fb653057b9b', 'Toza havo va mo‘l-ko‘l energiya! 🌳', 'Bolalarning tashqarida energiyasini sarflashi kunduzgi uyquga osonroq ketishiga yordam beradi. Birga bog‘ga boring.'),
  ('35a5e175-d9f9-4d9a-9445-a523d64bc595', 'O‘zi ovqatlanishni xohlayapti. 🥦', 'Ust-boshi iflos bo‘lsa ham, qoshiqni o‘zi ushlashiga imkon bering. Bu uning mustaqillik hissi va ko‘z-qo‘l muvofiqligini rivojlantiradi.'),
  ('66beeaaa-0b78-4114-b41f-8d7e6f407c55', 'Dam olish — sizning haqqingiz. 🛁', 'Kun bo‘yi oyoqda bo‘ldingiz. Bola uxlagach, o‘zingizga issiq choy quyib, shunchaki sokinlikdan zavqlaning.'),
  ('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6', 'Tezkor qadamlar! 🏃‍♂', '️ U endi xonalar orasida bemalol yuradi, hatto yugurishga ham urinadi. Uning ortidan yetib olish onalar uchun haqiqiy mashq!'),
  ('1008f62b-ef11-490d-886c-a80a06e64454', 'Ko‘zing qani? 👀', 'Tana a’zolarini topish o‘yini hamon uning eng sevimli o‘yinlaridan biri. Uni ko‘zgu qarshisida o‘ynab, yanada qiziqarli qiling.'),
  ('2ca5e024-95be-449a-af7e-ee34228f8bca', 'Rejali bo‘lish ko‘ngilni tinchlantiradi. 📝', 'Ertangi ishlaringiz yoki taomlar rejasini qisqacha yozib qo‘ying va xotirjam holda uyquga yoting.'),
  ('efb1280f-e8f0-4ecf-bb77-385f667aff5d', 'Huzur izlab. ☕', 'Ba’zan uydan chiqib, boshqa muhitda bo‘lishni xohlaysiz. Onalar uchun qulay joylar orasidan bolangiz bilan bemalol borish mumkin bo‘lgan yaqin atrofdagi kafeni toping va qahvadan zavqlaning.'),
  ('47368a03-c0f0-4e5c-a343-b4577d2ffa64', 'Tungi osoyishtalik 🛀', 'Iliq vanna, massaj va xonani qorong‘ilashtirish. Uyqu tartibiga rioya qilish — tun bo‘yi uzluksiz uyquning eng asosiy siridir.'),
  ('8edf71cc-a90b-4465-947f-070adc35b5f7', 'Musiqa ostida raqs 🎶', 'Televizordan ritmik ovoz eshitishi bilan dumbasini qimirlatadi. Musiqani his qilish qobiliyati faollashmoqda, siz ham unga qo‘shilib raqsga tushing!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8'::uuid, 'Onalar dardlashuvi 💬', 'O‘zingizni yetarlicha yaxshi ona emasdek his qilyapsizmi? Darhol Anacan hamjamiyatiga kiring, boshqa onalarning qo‘llab-quvvatlovchi izohlarini o‘qib, ko‘nglingizni tinchlantiring.'),
  ('4a0eb59e-113c-42ab-af5f-e0f64f837b44', 'Yangi joylarni kashf eting. ☕', 'Kundalik tartibdan zerikdingizmi? Ilovamiz orqali bolalar aravachasi bilan bemalol kirish mumkin bo‘lgan kafeni topib, qahva ichish uchun tanaffus qiling.'),
  ('4c4da832-707f-472e-a209-374acff11d94', 'Uy ishlarida yordamchi! 🧹', 'Qo‘liga latta olib chang artishga yoki supurgi bilan o‘ynashga oshiqyaptimi? Sizga taqlid qilishi — uning rivojlanishi yaxshi kechayotganining ajoyib belgisidir.'),
  ('ca45e311-dc2b-43fe-aa24-08a197d26f0a', 'Bola rivojlanishi haqida savollaringiz bormi? 🤖', '13-14 oylik davr haqida sizni o‘ylantirayotgan biror narsa bo‘lsa, hatto tunda ham Anacan AI yordamchimizga yozing.'),
  ('0ffbde04-3193-4b21-aa17-136db5de3c72', 'Hissiyotlar kundaligi 📝', 'O‘zingizni yolg‘iz his qilganingizda, his-tuyg‘ularingizni Kayfiyat kundaligiga yozing. Barcha ayollar bu yo‘llardan o‘tadi, siz kuchlisiz.'),
  ('7cdfa7f4-2c92-497d-9290-43caf53d8a56', 'Sokinlik ehtiyoji 🤫', 'Xonadagi sokinlikni Shovqin o‘lchagich yordamida saqlang. Tunda bo‘linadigan uyqu uning ham, sizning ham ertalabki kayfiyatingizni buzadi.'),
  ('f39f5c34-c612-4758-a438-ed52b2d49ba8', 'Xayr deymiz 👋', 'Kimdir eshikdan chiqayotganida, u o‘z tashabbusi bilan qo‘l silkitib xayrlashadi! Bu ajoyib ijtimoiy refleks. Uni ko‘proq rag‘batlantiring.'),
  ('0dcb1657-4eeb-47c5-a193-84ed106d43bc', 'So‘rashdan tortinmang 🤖', 'Uyqu tartibida nimanidir noto‘g‘ri qilayotganingizni o‘ylayapsizmi? Sizni ikkilantirayotgan barcha savollarni darhol Anacan AI’dan so‘rab, ko‘nglingizni tinchlantiring.'),
  ('10d800e4-c6bd-4325-b22e-385edaca8f7f', 'Tunda uyg‘onishlar davom etyaptimi? 😴', 'Agar so‘nggi kunlarda uning uyqusi yana buzilgan bo‘lsa, Anacan uyqu taymeri yordamida jadvalni tahlil qilib, rejimdagi kamchiliklarni aniqlang.'),
  ('319cae50-0492-468a-98e4-1b38563ab7ea', '14 oylikka yaqinlashyapmiz! 10 kun qoldi! 🎂', 'Ishonish qiyin! Rosa 10 kundan keyin kichkintoyingiz 14 oylik bo‘ladi. U kun sayin yanada mustaqil shaxsga aylanib bormoqda.'),
  ('2064ec2b-0483-4d3b-9453-106b6b9f32f8', 'Qalam bilan ilk tajribalar. 🖍', '️ Unga mos yo‘g‘on rangli qalamlar bering va qog‘ozga chizib-qoralashini mehr bilan kuzating. Balki kelajak rassomi ulg‘ayayotgandir!'),
  ('7f86b541-f24f-46cc-bf72-a538c8e62fa0', 'O‘z o‘yinchoqlari bilan mustaqil o‘ynash. 🧩', 'Qisqa muddat bo‘lsa ham, o‘zi mustaqil o‘ynay olishi — mustaqillik sari katta qadam. Uni uzoqdan kuzating.'),
  ('f945146d-2bbb-40d9-95f6-29bdc7f3be6d', 'O‘sishda davom etmoqda. 📏', 'Farzandingizning kiyimlari kichrayib qolyapti! Rivojlanishni kuzatish bo‘limiga yangi bo‘y va vazn ko‘rsatkichlarini qo‘shib, uning rivojlanishini kuzating.'),
  ('241a81f3-8158-4d3c-a8b2-640a1b060696', 'Ovqat tanlash odatini yengish. 🍲', 'Ba’zi kunlari u hatto eng sevimli taomini ham rad etishi mumkin. Majburlamang, shunchaki turli muqobil taomlarni taklif qiling.'),
  ('4716a93b-966d-4c69-b174-c2a48e9a09fa', 'Kechki vanna. 🛁', 'Iliq vanna kun davomida to‘plangan chang-g‘uborni yuvishning maroqli usuli bo‘lishi bilan birga, bolani tinchlantirib, uyquga ajoyib tarzda tayyorlaydi.'),
  ('dbbcb16c-cf48-47f7-92ab-992ed2fab247', 'Tana a’zolarini taniydi. 👃', '«Burning qayerda?» yoki «Qulog‘ing qayerda?» o‘yinini o‘ynang. To‘g‘ri topganida uni olqishlab, rag‘batlantiring.'),
  ('0cc0cda4-4fef-4e92-9af2-cd065cfee008', 'Siz eng yaxshisiz! 💖', 'Farzand tarbiyalash marafonga o‘xshaydi. Bugun kechqurun o‘zingizga biroz vaqt ajrating, sevimli filmingizni tomosha qiling yoki shunchaki xotirjam dam oling.'),
  ('781ac9f7-7fd3-4466-9d70-0b41dd1e954a', 'O‘yinchoqlarini sudrab yuribdi! 🧸', 'Ipidan tortiladigan o‘yinchoqlar yoki itarib yurish mumkin bo‘lgan kichik aravachalar hozir uning eng sevimli mashg‘ulotidir. Bu muvozanatni saqlash uchun ajoyib mashq!'),
  ('7dec83e1-5089-42b4-a2b5-f3d997eb1138', 'O‘zingizni ham oziqlantiring. 🥗', 'Serharakat bolaga yetishib yurish qiyin. Ayollar uchun foydali retseptlardan energiyangizni tiklaydigan mazali va vitaminlarga boy taom tayyorlang.'),
  ('6942d3e7-d39d-4aee-b8a0-ef2313920693', '“O‘zim!” degan qaysarlik. 🧦', 'Paypog‘ini o‘zi kiyishga yoki mustaqil ovqatlanishga urinayotgan bo‘lsa, unga xalaqit bermang. Mustaqillik hissi aynan mana shunday kichik urinishlar orqali rivojlanadi.'),
  ('c0c8236b-5e7c-45b1-a5c1-d45f005b603c', 'Hissiy yengillik. 📝', 'Ba’zan hammasi haddan tashqari og‘ir tuyulishi mumkin. Kayfiyat kundaligiga ichingizdan kechayotgan hislar va charchog‘ingiz haqida yozib, kun davomida yig‘ilgan stressdan xalos bo‘ling.'),
  ('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb', 'Toza havodagi kashfiyotlar. 🌳', 'Bog‘da barglarga tegish va toshlarni yig‘ish uning sezgi a’zolarini rivojlantiradi. Sayr qilish uchun yangi bog‘ni tanlang.'),
  ('96b02483-42a2-4868-a751-d817b0144951', 'Suv ichishni unutmang. 💧', 'U ham, siz ham! Serharakat o‘yinlardan keyin va ovqatlanish oralig‘ida albatta suv ichib, organizmingizda yetarli suyuqlik miqdorini saqlang.'),
  ('d89100dc-a7f8-49dd-8358-e3c63248fa5d', 'Kichkina yordamchi ish boshida! 🧹', 'Sizga taqlid qilib, qo‘liga sochiq olib chang artyaptimi yoki supurgi bilan o‘ynayaptimi? Bolalar ko‘proq kuzatish orqali o‘rganadi.'),
  ('eea0806e-a72b-42f1-b1c3-b7a791619a96', 'Uyqu tartibida o‘zgarish bormi? 😴', 'Kunduzgi uyqusi bir martaga kamayishni boshlagan bo‘lsa, o‘tish davrida tungi uyqusi uzayishi mumkin. Uyqu taymeri yordamida so‘nggi kunlardagi jadvalni kuzating.'),
  ('15bfc39a-e833-4e38-b7fc-bc13ef473b00', 'Mustaqil o‘yin vaqti 🧸', 'Endi u 10-15 daqiqa davomida o‘yinchoqlari bilan mustaqil ravishda mashg‘ul bo‘la oladi. Bu diqqatni jamlash muddati uzayayotganini bildiradi. Sukunatdan zavqlaning.'),
  ('99045f34-6450-4abd-856c-64fd61405e7b', 'Ovoz ohangingizni tushunadi 🗣️', 'Jiddiy ohangda yo‘q desangiz, to‘xtab sizga qaraydimi? U endi his-tuyg‘ular va taqiqlarni tushuna boshlayapti!'),
  ('dc953aca-0624-4e7e-a96b-11f2b35b9a14', 'Musiqaning kuchi 🎶', 'Kechga yaqin boshlanadigan sababsiz injiqliklarni yengil klassik musiqa bilan tinchlantirib ko‘ring. Ko‘pincha bu oddiy usul mo‘jiza yaratadi.'),
  ('1eee6b26-c3fa-460c-8e48-030eb1e5a77c', 'Rang-barang chizgilar! 🖍', '️ Xonaning bir burchagida unga mos yo‘g‘on rangli qalamlar va katta qog‘oz bering. Uning ilk san’at asarlarini Chaqaloq albomida abadiylashtirishni unutmang!'),
  ('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69', 'Mutaxassis yordamiga ehtiyojingiz bormi? 🤖', '“14 oylik bolaning nutqini qanday rivojlantirsam bo‘ladi?” kabi savollaringizni hatto tunda ham Anacan AI yordamchimizdan so‘rashingiz mumkin.'),
  ('f1854aec-f168-4789-a191-8a1fa96c3cd8', 'Xavfsizlik choralarini yangilash kerak. 🛡', '️ U mustaqil yura va shkaflarni ocha boshlagani sari xavf-xatarlar ortadi. Bolalar uchun himoya qulflarini Tavsiya etilgan mahsulotlar ro‘yxatimizdan ko‘rib chiqing.'),
  ('02d67440-3e37-4d1c-99f8-cbfa7aadda52', 'Foydali tamaddi vaqti. 🍎', 'Quvvati tugamaydigan bolalar uchun meva bo‘laklari yoki uzunchoq qilib kesilgan sabzavotlar ajoyib tanlovdir. Ularni o‘zi ushlab yesin.'),
  ('4a197291-3001-4afb-9a70-d4320bd260b2', '“Bu nima?” davri. ☝', '️ U hamma narsani barmog‘i bilan ko‘rsatib, nomini so‘raydi. Sabr bilan har bir narsaning nomini ayting — bu uning lug‘at boyligini tez oshiradi.'),
  ('8938f1b0-220a-48ac-b5f5-33db3613995c', 'Dada bilan ertak vaqti. 👨‍🍼', 'Bugun kechki ertakni o‘qish va bolani uxlatish navbatini dadasiga topshirib, o‘zingizga biroz dam bering.'),
  ('47ea2f2a-adf0-473a-a6a2-47218a354bbd', 'Maymunchadek tirmashadi! 🧗‍♂', '️ Divan yoki past mebellarga mustaqil ravishda tirmashib chiqishga urinadi. Atrofni xavfsiz holga keltiring va bu dadil harakat ko‘nikmalarini sizning nazoratingiz ostida sinab ko‘rishiga imkon bering.'),
  ('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d', 'Havoyi bo‘salar! 👋', 'U endi ketayotganlar ortidan ongli ravishda qo‘l silkitib, bo‘sa yuboryaptimi? Uning bu yoqimli va ijtimoiy harakatidan zavqlaning.'),
  ('ea4bc86f-6869-478f-98a6-52bb8dc4c40f', 'Uyquga ketish osonlashadi. 🌙', 'Har oqshom bir xil ketma-ketlikda bajariladigan ishlar (cho‘milish, ertak aytish, chiroqlarni xiralashtirish) uning osonroq uxlab qolishiga yordam beradi.'),
  ('3d197dae-8e31-468d-8d92-41ba68985a62', 'ROSA 14 OY! 🎉', 'Tabriklaymiz! Tug‘ruqdan beri roppa-rosa 14 oy o‘tdi! Hoziroq Chaqaloq fotosessiyasida maxsus mavzuli surat yarating va bu quvonchni Anacan hamjamiyatida ulashing!'),
  ('9052004a-46e9-4652-8de2-61f2a8f774d7', 'Charchoq va faxr💖', '14 oylik charchoq va faxrni bugun oqshom turmush o‘rtog‘ingiz bilan birga nishonlang. Sizlar ajoyib jamoasiz!'),
  ('dde3a118-6b4b-4b86-b077-744218b7fcd7', 'Farzandingiz qanchalik katta yo‘lni bosib o‘tdi! 📈', 'Ilk kunlardagi qo‘rquv o‘rnini kuchli onalik ishonchi egalladi. O‘zingiz bilan faxrlaning!'),
  ('44b33bc4-3602-4265-9fe5-30b5609015de', 'Otalar bilan birga g‘amxo‘rlik qilish vaqti. 👨‍🍼', 'Kechki o‘yinlar juda serharakat bo‘ladi. Bugun kechqurun bolangiz bilan quvlashmachoq o‘ynash va uni uxlatish navbatini dadasiga topshirib, o‘zingiz dam oling.'),
  ('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95', 'Hamdardlik hissi uyg‘onmoqda! 💖', 'Kimdir yig‘lasa yoki xafa bo‘lsa, bolangiz uning yoniga borib, silab ovutishga harakat qiladimi? Farzandingizning hissiy intellekti juda yaxshi rivojlanmoqda.'),
  ('e569bdf3-a845-44dc-852b-5318a0cf6a72', 'Ochiq havoda tuganmas quvvat! 🌳', 'Erkin sayr qilayotgan bolangiz quvvatini sarflashi uchun bemalol borishingiz mumkin bo‘lgan xavfsiz va yangi bog‘larni Onalar uchun qulay joylar bo‘limidan toping.'),
  ('381afc75-3dbd-4716-b5ea-3af987c642dc', 'Kunduzgi uyquga qarshilik. 😴', 'O‘ynash uxlashdan ko‘ra qiziqroq! Yotishdan yarim soat oldin serharakat o‘yinlarni to‘xtatib, tinchroq mashg‘ulotlarga o‘ting.'),
  ('3ed2bd45-e711-4e56-bdc9-29b31e605069', 'Savolingiz bormi? 🤖', '“Nega bolam ba’zi kunlari hech narsa yemaydi?” kabi muhim savollaringizni hatto tunda ham Anacan AI yordamchimizdan so‘rab, yordam oling.'),
  ('718ac202-3ddd-463e-90fd-d1367161e2b5', 'Ovqat tanlash odatini yengish. 🍲', 'Ba’zi kunlari bolangiz hatto eng sevimli taomini ham rad etishi mumkin. Uni majburlamang, shunchaki ilovamizdagi turli muqobil retseptlarni sinab ko‘ring.'),
  ('33a2089a-67cc-4441-bb79-483ad77a1a42', 'O‘zingizga vaqt ajrating. 🛁', 'Kun bo‘yi oyoqda bo‘ldingiz. Charchog‘ingizni Kayfiyat kundaligiga qayd etib, yengil torting va bir piyola issiq choy bilan dam oling.'),
  ('625bdfef-2359-4843-aaac-6c8411b1963b', 'Buyumlarni otish san’ati. 🎾', 'O‘yinchoq yoki ovqatni yerga tashlab, uning ortidan qarashi sho‘xlik emas, balki gravitatsiyani o‘rganishdir. Sabrli bo‘ling va unga sinmaydigan buyumlar bilan o‘ynashga ruxsat bering.'),
  ('ee0ba9ab-4b88-462e-aae9-f9a207218204', 'Orqaga va yon tomonga qadamlar! 🦀', 'U endi nafaqat oldinga, balki orqaga va yon tomonlarga ham qadam tashlab ko‘rmoqda. Bu muvozanat va harakat ko‘nikmalari uchun ajoyib mashq!'),
  ('21478892-353c-43fd-ba31-59c9aeb8255d', 'Onalar uchun quvvat bombasi! 🥗', 'Harakatchan bolalar onalardan ikki karra ko‘proq kuch talab qiladi! Sog‘lom retseptlardan qiziqarli taom tanlab, uni tayyorlang va o‘zingizni siylang.'),
  ('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e', 'Allo, bu kim? 📱', 'Pult yoki telefonni qulog‘iga tutib, siz kabi gapirishga urinyaptimi? Bu yoqimli taqlid onlaridan bahramand bo‘ling.'),
  ('ab819835-a2e1-481b-91b5-5391eb6051e8', 'Uyqu me’yorlarini kuzatib boring. ⏱️', 'Kunduzgi uyqular soni butunlay bittaga tushdimi? Chaqalog‘ingiz uxlayotganda uyqu taymerini yoqing va uning yangi tartibga moslashishini grafik orqali kuzating.'),
  ('356f85b5-b941-4e2e-8218-18498e652ff8', 'Kublardan qal''a quradi 🧱', 'Ikki yoki uchta o‘yinchoq kubini ustma-ust qo‘yishga harakat qiladi. Uning bu kichik muhandislik urinishlarini jimgina kuzating.'),
  ('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3', 'Oq shovqinning kuchi. 🎶', 'Agar serharakat kun ta’siridan yoki tishlari chiqayotgani sababli uxlay olmasa, Oq shovqinlardan yomg‘ir tovushini yoqib, xonada sokin muhit yarating.'),
  ('f73e2678-7057-466b-a01a-218bff7ab963', 'Tish yuvish zavqi. 🪥', 'Tish cho‘tkasini o‘zi ushlashni xohlayaptimi? Unga mos yumshoq cho‘tkalardan foydalanib, ko‘zgu qarshisida birga tishlaringizni yuving va unda bu odatni shakllantiring.'),
  ('58b586ed-1396-42c6-81f5-29f087488332', 'Uyquga oson o‘tish. 🌙', 'Faol kundan so‘ng xona chiroqlarini xiralashtiring, ovozingizni pasaytiring va unga mayin ovozda ertak o‘qib, uyquga tayyorlang.'),
  ('82b39d0a-8bac-4430-a17f-2937f0af35e1', 'Sizning ham quvvatingiz tugashi mumkin. 🥗', 'Juda charchadingizmi? Ayollar uchun foydali retseptlardan quvvatingizni tezda tiklaydigan vitaminli smuzi tayyorlang va o‘zingizni siylang.'),
  ('917ef6a5-ae0d-4133-b145-53d60f762945', 'To‘pni menga olib kel! 🧠', 'Endi u oddiy ko‘rsatmalarni juda yaxshi tushunadi. Siz undan biror narsa so‘raganingizda, uni xursand bo‘lib olib kelib berishi aql-zakovati tez rivojlanayotganini ko‘rsatadi.'),
  ('1bf6a974-24ed-47b3-8587-a38235ea120e', 'Oshxona kashfiyoti! 🍳', 'Qozonlar, qoshiqlar va plastik idishlar uning eng sevimli o‘yinchoqlariga aylandi. Xavfsiz shkaflarni uning o‘rganishi uchun ochiq qoldiring.'),
  ('88b4c840-5c20-4f9f-8b89-4530da60297b', 'Xavfsizlikni yangilash kerak! 🛡', '️ U mustaqil yurib, shkaflarni ocha boshlagani sari xavflar ortadi. Bolalar uchun qulflar va burchak himoyachilarini tanlash uchun Tavsiya etilgan mahsulotlar ro‘yxatimizni albatta ko‘rib chiqing.'),
  ('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3', 'Tinchlantiruvchi vanna. 🛁', 'Iliq vanna kun davomida to‘plangan energiyani chiqarish uchun qiziqarli bo‘lishi bilan birga, mushaklarni bo‘shashtirib, uyquga ajoyib tayyorlaydi.'),
  ('409e6b49-8ccb-4975-92b1-c12021092540', 'Kechki ertakning sehri bor. 📖', 'Uyqudan oldin o‘qilgan qisqa hikoya tasavvurini rivojlantiradi va orangizdagi hissiy rishtani mustahkamlaydi.'),
  ('6b7d6637-7328-44aa-b6c8-47c73df3a6f3', 'O‘sish sur’ati tez. 📏', 'Farzandingizning kiyimlari yana kichik kelishni boshladi! Rivojlanishni kuzatish bo‘limiga bo‘yi va vaznining yangi ko‘rsatkichlarini qo‘shib, sog‘lom rivojlanishini qayd eting.'),
  ('807127b9-417f-43a0-9bca-9ef33fbdadb8', 'Tana tili bilan javob 🗣️', 'Ketdikmi? deganingizda qo‘llarini ko‘taradi yoki Yo‘q deganingizda boshini chayqaydi. Tushunish qobiliyati hayratlanarli darajada rivojlandi!'),
  ('9693a098-adc4-4d19-ab73-4c5cc195a25e', 'O‘zim artaman! 🧽', 'Siz stolni artayotganingizda, u ham latta so‘raydimi? Kichik yordamchingizga xavfsiz bir vazifa bering. Bu uning o‘ziga bo‘lgan ishonchini nihoyatda oshiradi.'),
  ('98ba1e51-63c6-4c73-891d-99f1b14f3495', 'Oq shovqinning kuchi. 🎶', 'Agar serharakat kun ta’sirida yoki tishlari chiqayotgani sababli uxlay olmasa, oq shovqinlardan yomg‘ir ovozini yoqib, xonada tinch muhit yarating.'),
  ('f5a87b81-5f64-4d75-abaf-6fd718e53fc5', 'Foydali tamaddilar. 🍎', 'Meva bo‘laklari yoki yogurt bu yosh uchun ajoyib tamaddi hisoblanadi. Ilovamizdagi bolalar retseptlaridan turli xil mazali g‘oyalarni toping.'),
  ('0b365564-8d23-4572-9881-7a4b9e2159bf', 'Ilk san’at asarlari! 🖍', '️ U yo‘g‘on rangli qalamlar bilan qog‘ozga chizishni juda yaxshi ko‘radi. Uning ilk san’at asarlarini kelajak uchun Chaqaloq fotosessiyasi bo‘limida saqlang.'),
  ('c0638659-03fe-4ca5-b078-76057498811f', 'Onaga yopishib olish davri 🥰', 'Hatto hojatxonaga kirganingizda ham eshik ortida sizni kutib, yig‘laydi. Ajralish xavotiri eng yuqori darajada. Har safar unga o‘zini xavfsiz his qilishiga yordam bering.'),
  ('f2ba1614-ef41-4060-97ee-0fe66e58b884', 'Suv ichish odati muhim. 💧', 'Faol harakat qilgani sari chanqog‘i ham ortadi. O‘yin paytida va ovqatdan keyin unga suv taklif qilishni unutmang.'),
  ('2cca6125-c540-4b9b-9a06-6121b60507e5', 'Ochiq havodagi sarguzasht! 🌳', 'Uyda energiyasini sarflay olmayaptimi? Bolalar aravachasi bilan bemalol sayr qilishingiz mumkin bo‘lgan xavfsiz bog‘ni tanlang va birgalikda toza havodan bahramand bo‘ling.'),
  ('73b001a8-93ab-4798-bca3-094a519e468a', 'His-tuyg‘ularingizni erkin ifoda eting. 📝', 'Har kun ham oson o‘tmaydi, ba’zida hammasi ortiqcha yuk bo‘lib tuyulishi mumkin. Ichingizdagi his-tuyg‘ularni Kayfiyat kundaligiga yozib, kun davomida yig‘ilgan stressdan xalos bo‘ling.'),
  ('d452b163-e134-4c64-90b8-7e561b20c6f9', 'So‘zlarga taqlid qilamiz! 🗣', '️ Siz aytgan so‘zlar yoki hayvonlarning ovozlariga taqlid qilishga urinyaptimi? O‘zini ifoda etish istagi ortishi uchun bu urinishlarini ishtiyoq bilan qo‘llab-quvvatlang.'),
  ('80913e3b-4640-4efe-ae49-ce789db16fd1', 'Ajoyib kunning yakuni. ✨', 'Bugun ham ona sifatida qo‘lingizdan kelgan eng yaxshi ishni qildingiz. Ko‘zlaringizni yuming, o‘zingizdan faxrlanib, oromli uyquga keting.'),
  ('8e332da4-937a-4f7f-af67-edbe9e325d0e', 'Qadamlar tobora dadil! 🏃‍♂', '️ U endi uy bo‘ylab mustaqil yurib, ba’zida hatto yugurishga ham urinmoqda. Uning bu dadil harakatlari sizni ham faxrlantiradi, ham doimo hushyor turishga undaydi!'),
  ('b5982bde-910f-4d42-bc5f-8e5e9b2e683f', 'Allergiyadan shubhalanyapsizmi? 🤖', 'Yangi taom berdingiz va yonoqlarida qizarish paydo bo‘lganini ko‘rdingizmi? Vahimaga tushishdan oldin Anacan AI’dan dastlabki choralar haqida bilib oling.'),
  ('0deab7a8-9a3b-4827-969f-f24303c70419', 'Tish chiqishidagi og‘riqlar 🦷', 'Milklar yana qizarib, so‘lak oqishi to‘xtamayaptimi? Sovuq tish qashlagichlarni tayyorlab qo‘ying.'),
  ('46166e0f-606a-46ff-86d4-07304bc93180', 'Suv ichish odati muhim. 💧', 'Faol harakat qilgani sari chanqog‘i ham ortadi. O‘yin paytida va ovqatdan keyin unga suv taklif qilishni unutmang.'),
  ('9e232723-1401-4819-8b29-1e4636b3edc3', 'Ilk san’at asarlari! 🖍', '️ Yo‘g‘on rangli qalamlar bilan qog‘ozga chizishni juda yaxshi ko‘radi. Uning ilk san’at asarlarini kelajak uchun Chaqaloq fotosessiyasi bo‘limida saqlab qo‘ying.'),
  ('2423bd81-d7d2-4b3e-b97a-32a10186bc3d', 'Rolli o‘yinlar boshlanmoqda. 🧸', 'O‘yinchoq ayiqchasini ovqatlantirishga yoki unga suv berishga urinyaptimi? Bu sizni qanchalik diqqat bilan kuzatishi va sizga taqlid qilishining eng yoqimli isbotidir!'),
  ('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc', 'Savolingiz bormi? 🤖', '“Bolamning ovqat tanlashi normalmi?” kabi sizni tashvishga solayotgan istalgan savolni hatto tunda ham Anacan AI yordamchimizdan so‘rashingiz mumkin.'),
  ('d4f6586e-25f9-4dd3-9a6b-1408627d49eb', 'Kunduzgi uyquga qarshilik. 😴', 'O‘ynash har doim uxlashdan ko‘ra qiziqarliroq. Agar uxlab qolishi qiyin bo‘lsa, Anacan uyqu taymeri yordamida so‘nggi kunlardagi jadvalini kuzatib, uyqu rejimini moslashtiring.'),
  ('13b16a71-31e8-44cf-bbf4-b97f55c8f45e', 'Tashqarida havo unchalik aniq emasmi? ⛅', 'Ob-havo va kiyim vositasi derazadan bilib bo‘lmaydigan shamol tezligini sizga bir zumda aytib beradi.'),
  ('807a2e9f-2fb3-4378-94cf-0ad756854f25', 'Shaxsiy ertak 🪄', 'Aqlli ertaklarda bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: Yulduzlarga ko‘tarilgan jasur bola.'),
  ('d08fdb3f-542d-478d-95e6-72b2d85a8a9a', '15 oylikka 5 kun qoldi! 🎈', 'Sanoqli kunlar qoldi! Endi siz uyda bemalol yuradigan, hamma narsani tushunadigan mitti bir shaxs bilan birga yashayapsiz. Tabassum qiling!'),
  ('25f37869-be99-4918-83ae-dd5fecd2f5ce', 'Oshxonada birga. 🥦', 'Ovqat tayyorlayotganda unga sinmaydigan plastik idish va yog‘och qoshiq bering, u ham o‘z ovqatini tayyorlasin.'),
  ('c0b75b28-86cb-44ea-8bc4-de62c31fae30', 'Rejali bo‘lish xotirjamlik beradi. 📝', 'Ertangi ishlaringiz yoki taomlar rejasini qisqacha yozib qo‘ying va xotirjam holda uxlashga yoting.'),
  ('e47ea433-71bf-4c11-8e6e-6edbaec03292', 'Hamma narsani barmog‘i bilan ko‘rsatadi. ☝', '️ Bu «Bu nima?» savolining ovozsiz ko‘rinishidir. Uning qiziqishini so‘ndirmaslik uchun u ko‘rsatgan har bir narsaning nomini sabr bilan takrorlang.'),
  ('09564db7-642f-496e-b113-4fd15ad5aefe', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarning barcha og‘irligini yolg‘iz o‘zingiz ko‘tarmang. Juftingizni ham uyg‘oting — bir jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir.'),
  ('30d6fd90-986c-491d-9a4a-39c6c9f48f69', 'Rivojlanishni tekshirish 🤖', '15 oylik davrdagi rivojlanish sakrashlari haqida ma’lumot kerakmi? Inqirozlar taqvimiga nazar tashlang.'),
  ('661b0ef0-cce8-4702-8d5a-2f90901198ad', 'Kitob o‘qishga qiziqish. 📖', 'Rasmli kitoblarning sahifalarini varaqlash va sizning o‘qishingizni tinglash so‘z boyligini oshirishning ajoyib usulidir. Har kuni hech bo‘lmasa 10 daqiqa birga kitob o‘qing.'),
  ('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2', 'Ovoz ohangingizni tushunadi 🗣️', 'Jiddiy ohangda «yo‘q» deganingizda to‘xtab, sizga qaraydimi? U endi his-tuyg‘ular va taqiqlarni tushuna boshlayapti!'),
  ('553f302d-8ba0-44d9-9d9d-e356d494f003', 'Tungi tartib. 😴', 'Iliq vanna va toza pijama uni tinchlantirib, uyquga ajoyib tarzda tayyorlaydi.'),
  ('ed9814d4-d919-40b0-833b-d118d90c1727', 'Mustaqillikka intilish. 🥣', 'Idishi yoki qoshig‘ini o‘zi ushlamoqchi bo‘lsa, unga imkon bering. Atrofning iflos bo‘lishi — o‘rganish jarayonining eng yaxshi qismidir.'),
  ('157a98b7-1825-4699-b38d-85781cd21cf3', 'Xonalararo marafon 🏃‍♂️', 'U endi shunchaki yurmayapti, deyarli yuguryapti! Muvozanati kundan-kunga yaxshilanmoqda. Rivojlanish kuzatuvchisida ushbu serharakat davrni faxr bilan qayd eting.'),
  ('47ea1c98-c71a-45d9-b06c-d95aa3da437b', 'Dadaning o‘yin maydonchasi 👨‍👧', 'Kun bo‘yi uning ortidan yugurib, holdan toyibsiz. Kechki navbat dadasiniki! Polda dumalash va quvlashmachoq o‘yinlarini unga qo‘yib bering.'),
  ('9b3b08e6-de82-413f-9e4b-6da904b304a3', 'Bugun uy juda tartibsiz deb xavotirlanmang.', 'Bolalar saranjom uylarni emas, baxtli onalarni eslab qoladi. Qahvangizni damlab, dam oling.'),
  ('67b35eea-eab9-41c5-88b7-f31e283eddd9', 'Bola uyda energiyasini sarflay olmay, injiqlik qilyaptimi?  ⛅', 'Tabiat — eng yaxshi tinchlantiruvchi vosita. Ob-havoga mos kiyim tanlang-da, darhol parkka yo‘l oling.'),
  ('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9', '“Bu nima?” davri ☝️', 'U hamma narsani barmog‘i bilan ko‘rsatib, o‘ziga xos tovush chiqaradi. U sizdan atrofidagi narsalarning nomini aytishingizni istaydi. Ko‘rsatgan har bir buyumining nomini unga sabr bilan ayting.'),
  ('d4a833e4-9676-4c95-baa2-923b9117c325', 'Sukunat kerak 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — eng nozik vaqt. Shovqin o‘lchagich yordamida muhitdagi detsibel darajasini tekshiring va to‘satdan chiqadigan shovqinlardan ehtiyot bo‘ling.'),
  ('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e', 'Sizga ham energiya kerak. 🥗', 'Kun bo‘yi oyoqdasiz. Ayollar uchun foydali retseptlardan foydalanib, kuchingizni tiklaydigan mazali tamaddi tayyorlang.'),
  ('6df61827-7605-47d2-aeef-a4e811b4d8c8', 'Tezkor kashfiyotlar! 🏃‍♂', '️ U endi xonalar orasida ishonch bilan yurib, hamma narsaga tegishni xohlaydi. Uyingiz xavfsiz ekaniga ishonch hosil qiling va uning bu faolligidan zavqlaning.'),
  ('c9b2a6a2-258b-4f8c-96f9-86282d8d8145', 'Hissiy yengillik. 📝', 'Charchatgan kundan so‘ng Kayfiyat kundaligiga his-tuyg‘ularingizni yozib, kun davomida to‘plangan stressdan xalos bo‘ling. Siz ajoyib onasiz!'),
  ('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267', 'Siz qahramonsiz! ✨', '450 kun davomida ko‘rsatgan mehringiz va g‘amxo‘rligingiz beqiyos. Endi bemalol dam oling va ushbu ajoyib kun ortidan sokin uyquga keting.'),
  ('4df5ec18-5365-45c2-a49d-90ce26310b0b', 'Roppa-rosa 15 oy! 🎉', 'Vaqt qanday tez o‘tadi! Kichkintoy dunyoga kelganiga roppa-rosa 1 yil 3 oy bo‘ldi. Tabriklaymiz.'),
  ('a50254b7-b2f0-44b3-8ee9-5246bba08038', 'Oila davrasidagi baxt. 🍲', 'U endi siz bilan bir xil taomlarni yeyishi mumkin. Ilovamizdagi retseptlardan butun oila uchun mazali taomlarni kashf etib, ushbu kichik yubileyni nishonlang.'),
  ('63bf2d84-bd96-49e0-9c51-b1f59bd85995', 'Meva vaqti! 🍎', 'Quvvatini tiklashi uchun mavsumiy mevalardan rang-barang va ishtaha ochar likopcha tayyorlang.'),
  ('72ba71ca-1652-48f5-bc29-c321459f659a', 'Oq shovqin kuchi. 🎶', 'Agar faol kun taassurotlari tufayli uxlay olmayotgan bo‘lsa, xonada Oq shovqinlardan okean yoki yomg‘ir ovozini qo‘yib, tinch muhit yarating.'),
  ('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea', 'Menyu diktatori 🥣', 'Kecha yoqtirgan taomini bugun chetga suryaptimi? Bu yoshda ovqat tanlash odatiy hol. Vahimaga tushmasdan, Sog‘lom retseptlardan boshqa muqobillarni izlang.'),
  ('54788c72-cfe2-4f75-82f0-ba29d942e404', 'Hayvonlarning ovoziga taqlid! 🐱', '“Mushuk qanday ovoz chiqaradi?” o‘yinini o‘ynang. Bu oddiy va qiziqarli taqlidlar uning gapira boshlashi uchun ajoyib poydevor yaratadi.'),
  ('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa', 'Quvvatingizni tiklang 🥑', 'U to‘ygan bo‘lsa, endi navbat sizniki. Kundalik yugur-yugurda tushlikni oyoqda yemang. Sog‘lom retseptlardan quvvat beruvchi tamaddi tanlang va divanga cho‘ziling.'),
  ('f3a87482-9f2e-4700-94d8-d413093ea00a', 'Kechki tartibning kuchi 🛀', 'Iliq vanna har doim yordam beradi. Kechki tartibni aslo buzmang, chunki bu uning miyasiga hozir uxlash vaqti bo‘lganini bildiradi.'),
  ('088ce5b1-9a8e-4d7d-8f55-017e0cc63605', 'Savolingiz bormi? 🤖', '15 oylik bolaning rivojlanishida sizni o‘ylantirayotgan jihatlar bormi? Internetda javob izlab ovora bo‘lmang, to‘g‘ridan-to‘g‘ri Anacan AI’ga yozing va ilmiy asoslangan javob oling.'),
  ('b6c6ae0a-2aaa-45b3-b8de-d4785923503c', 'Sehrli ertak 🪄', 'Aqlli ertaklarda jasur qahramonning dunyoni kashf etishi haqida o‘ziga xos hikoya yarating. Uyquga ketishni yanada yoqimli qiling.'),
  ('c4cd946e-4029-4937-a10b-6f87983c2067', 'Bir mahal kunduzgi uyquga o‘tish 🥱', 'Ertalab uxlashni istamayaptimi va uyqu tartibi buzildimi? U ulg‘aymoqda! Kunduzgi ikki mahal uyqudan bir mahal uyquga o‘tish davri boshlanmoqda. Kun tartibini asta-sekin moslashtiring.'),
  ('2517046a-f369-483a-b1e2-38f6320720ad', 'Iliq vanna tinchlantiradi. 🛁', 'Kun davomida to‘plangan chang va charchoqdan xalos bo‘lish uchun suv bilan o‘ynash uni ham xursand qiladi, ham uyquga ajoyib tarzda tayyorlaydi.'),
  ('258818a7-034e-4b93-86ea-97e8e01d3126', 'Jahldorlik xurujlari? 🌪', '️ O‘zini ifoda eta olmaganida jahli chiqib, yig‘lashi mumkin. Bu borada yordamga muhtoj bo‘lsangiz, Anacan AI bilan maslahatlashib, to‘g‘ri yondashuvni o‘rganing.'),
  ('ca5a1958-0c22-4c62-874b-c3b801f70118', 'So‘zlarni tushunish qobiliyati. 🧠', 'Oyoq kiyimini olib kelishini aytganingizda, uni topib olib keladimi? Bu uning aql-zakovati jadal rivojlanayotganini ko‘rsatadi. Uni ko‘proq maqtang!'),
  ('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981', 'Kunning shirin lahzalari. 📸', 'Uning bugun qilgan biror kulgili harakati yoki yangi o‘rgangan ko‘nikmasini Chaqaloq fotosessiyasi yordamida abadiylashtiring.'),
  ('21100889-9857-4170-a0a6-59c3dec113f8', 'Chegaralarni sinayapti. 🛑', '«Yo‘q» deganingizga qaramay, yana o‘sha buyumga qo‘l uzatyaptimi? Bu qaysarlik emas, u shunchaki qoidalarni shu tariqa o‘rganmoqda. Sabrli bo‘ling.'),
  ('66da2b8a-fe86-40dc-b027-d36d46f5091a', 'Kitob varaqlaydigan zukkocha 📖', 'Qalin sahifali kitoblarni varaqlab, rasmlarga munosabat bildiryaptimi? Uning ko‘rish xotirasi rivojlanmoqda. Unga ko‘plab rang-barang ertak kitoblarini o‘qib bering.'),
  ('5991e165-7b36-40d5-be3a-c6729cd8e924', 'Tozalashmi yoki dam olishmi? 🛋️', 'Bola uxlaganda idish yuvish mashinasi tomon shoshilmang. Divanga yoting, ko‘zlaringizni yuming va 15 daqiqa shunchaki nafas olib dam oling. Siz robotmisiz? Yo‘q.'),
  ('67273a71-3d6d-40e2-b209-34b098335818', 'U har kuni biroz ko‘proq ulg‘aymoqda.📸', 'Darhol Chaqaloq fotosessiyasini ochib, uning ushbu samimiy lahzasini xotiraga muhrlang.'),
  ('d17f36fc-9cb8-4df2-a29e-60891f565b13', 'Mustaqil ovqatlanishga intilish 🥄', 'Qoshiqni qo‘lingizdan olib, o‘zi ovqatlanishni xohlaydi. Ovqatni to‘kadi, ust-boshini kir qiladi, ammo bu uning motorikasi rivoji uchun muhim. Mustaqil bo‘lishiga imkon bering.'),
  ('145c55e0-770c-4adc-a15b-4bd94389378f', 'Xavfli hududlarga yetib borish ⚡', 'Bo‘yi o‘sib, ilgari yetolmagan tokchalarga ham yetadigan bo‘ldi. Televizor tagligi, burchaklar... Uy xavfsizligini zudlik bilan qayta ko‘rib chiqing.'),
  ('b6ac32de-f983-4a93-89fc-cb209586570b', 'Oziq tishlari chiqyaptimi? 🦷', 'Milklari shishib, qo‘lini og‘ziga solyaptimi? Orqa tishlari chiqayotgan bo‘lishi mumkin. Tish chiqishi kuzatuvchisini tekshiring va sovutilgan tishlagichlar bering.'),
  ('d2fd7757-cdd9-4cc6-b45c-347ada81b748', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yorug‘likdagi muhitda ajraladi.'),
  ('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182', 'To‘satdan uyg‘onishlar 😭', 'Yarim tunda qichqirib uyg‘onib, tinchimayaptimi? Ovozini Yig‘i tahliliga eshittirib, bunga tungi qo‘rquv yoki og‘riq sabab bo‘layotganini aniqlang.'),
  ('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1', 'Katta his-tuyg‘ular, kichik tana 🛑', 'Istagi amalga oshmasa, o‘zini yerga tashlayaptimi? Bu toddler davriga xos mashhur injiqlik xurujlari. Xotirjamlikni saqlang, u bilan ko‘z orqali aloqa qiling va yonida ekaningizni ayting.'),
  ('d33491b0-9722-4db2-ae48-c019740b7411', 'Birdamlik ruhi 🥂', 'Turmush o‘rtog‘ingiz bilan ilk kunlarni, o‘sha uyqusiz tunlarni eslab, birga kuling. Siz bu kunlarga osonlikcha yetib kelmagansiz! Bu jamoaviy g‘alaba.'),
  ('138aeaf3-e845-4d03-b6db-2a04410076a7', 'Ovqat tanlash hali ham davom etyaptimi? 🥦', 'Agar chaqalog‘ingiz ayrim taomlarni rad etsa, xavotir olmang. Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidagi taomlarni turlicha va qiziqarli tarzda taqdim etib ko‘ring.'),
  ('2f302f24-3142-4182-84a0-2782c5ce8394', 'Hissiy yengillik. 📝', 'Bugun juda charchatadigan kun bo‘ldimi? Bola uxlagach, his-tuyg‘ularingizni Kayfiyat kundaligiga yozib, kun davomida to‘plangan stressdan xalos bo‘ling.'),
  ('8b269aa5-a26e-4c52-b247-14a7194a3d35', 'Uy ichida marafon! 🏃‍♂', 'U endi shunchaki yurish bilan cheklanmay, xuddi yugurishga urinayotgandek. Mitti oyoqchalarining pitir-pitir ovozidan zavqlaning, ammo undan ko‘zingizni uzmang!'),
  ('8ee97257-b3d6-4144-ad9a-91e2e54c967a', 'Ochiq havoda quvlashmachoq. 🌳', 'U uyda energiyasini sarflay olmayaptimi? Birga toza havoga chiqing, parkda erkin sayr qilib, maza qilib charchashiga imkon bering.'),
  ('e84402f2-45d4-40ce-ae96-610f12a3e06b', 'Kichik yordamchi ishga kirishdi! 🧹', 'Qo‘liga latta olib chang artishga yoki supurgi bilan o‘ynashga oshiqyaptimi? Sizga taqlid qilishi — uning o‘rganish jarayonidagi eng yoqimli bosqichlardan biridir.'),
  ('ed63e2e3-10b5-4bd6-9b06-a81622e913eb', 'Uyqu tartibi ishonch hissini beradi. 🌙', 'Har oqshom bir xil ketma-ketlikda bajariladigan odatlar (cho‘milish, ertak aytish, chiroqlarni xiralashtirish) uning osonroq uxlab qolishiga yordam beradi.'),
  ('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35', 'So‘zlarni tushunish qobiliyati. 🧠', '«Oyoq kiyimingni olib kel», deganingizda uni topib olib keladimi? Bu uning aqliy qobiliyati jadal rivojlanayotganini ko‘rsatadi. Uni ko‘proq maqtang va rag‘batlantiring!'),
  ('ce1fc21a-8f96-4c92-b928-5126f2240b1d', 'Sizga ham energiya kerak. 🥗', 'Kun bo‘yi oyoqdasiz. O‘zingiz uchun vitaminlarga boy va mazali tamaddi tayyorlashni unutmang.'),
  ('d8cf1dda-3655-48e8-9316-6481b7ea82ba', 'Jahl xurujlari? 🌪', '️ O‘zini ifoda eta olmaganda jahli chiqib, yig‘lashi mumkin. Bu borada yordamga muhtoj bo‘lsangiz, Anacan AI bilan maslahatlashib, qanday to‘g‘ri yondashish kerakligini bilib oling.'),
  ('2b9c6af1-1706-4704-b2ce-29e57d4866f4', 'Endi navbat dadasiga. 👨‍🍼', 'Bugun kechki ertakni o‘qish va uxlatishni dadasiga topshirib, o‘zingizga biroz dam bering.'),
  ('8db205c2-0561-48d8-8b6c-61fc68065e2a', 'Minora qurish san’ati. 🧱', '3-4 ta kubikni ustma-ust qo‘yib, keyin qulatish — eng sevimli mashg‘ulotlardan biri. Bu o‘yin ko‘z va qo‘l muvofiqligini jadal rivojlantiradi.'),
  ('e513a042-7558-4dae-8bc5-5e2b5e5d74fa', 'Uydan tashqarida ham qulaylik. ☕', 'Kundalik yumushlardan zerikdingizmi? Bolalar aravachasi bilan bemalol kira oladigan kafeni Onalarga do‘stona maskanlardan topib, qahva ichish uchun tanaffus qiling.'),
  ('1cb9115d-9cf4-466e-adbe-8fa808d6b45c', 'Uyqu tartibini kuzatamiz. ⏱️', 'Agar kunduzgi uyqusi bir martaga kamaygan bo‘lsa, kechqurun tezroq charchaydi. Tungi uyquga yotqizish vaqtini biroz ertaroqqa surishingiz mumkin.'),
  ('42c60ff7-6aed-4b88-96d2-512be311f08c', 'Suv ichishni unutmang. 💧', 'Faol harakat qilgani sari chanqog‘i ham ortadi. O‘yin paytida va ovqatdan keyin unga muntazam ravishda suv taklif qiling.'),
  ('9a860f2e-97a8-4151-9a68-ed86235ecd75', '“Bu nima?” davri. ☝', '️ Hamma narsani barmog‘i bilan ko‘rsatib, sizdan uning nomini so‘raydi. Sabr bilan har bir narsaning nomini ayting — bu uning atrofdagi olamni o‘rganish usulidir.'),
  ('09bd2033-24ed-4376-ba68-6795f9e6d0fa', 'Musiqaga raqs tushadi! 🎶', 'Ritmik ovozni eshitishi bilan u yoqdan bu yoqqa tebranib, raqsga tushadimi? Bu jo‘shqin lahzalarni videoga olib, Chaqaloq albomiga yuklang.'),
  ('899ab05b-717c-4e03-b941-aadf4ad85007', 'Mustaqil o‘ynash ko‘nikmasi. 🧩', 'Qisqa muddat bo‘lsa ham, o‘zi mustaqil o‘ynay olishi uning diqqat-e’tibori rivojlanayotganini ko‘rsatadi. Bunday paytlarda uni uzoqdan mehr bilan kuzating.'),
  ('98938324-49d8-43fc-bdde-202849487b20', 'Iliq vanna tinchlantiradi. 🛁', 'Kun davomida yig‘ilgan chang va charchoqdan xalos bo‘lish uchun suv bilan o‘ynash uni ham zavqlantiradi, ham uyquga a’lo darajada tayyorlaydi.'),
  ('6537418f-2c88-443b-b40f-e07f0ccd5801', 'Oq shovqinning kuchi. 🎶', 'Agar faol o‘tgan kun ta’sirida uxlay olmasa, xonada Oq shovqinlardan okean yoki yomg‘ir ovozini qo‘yib, tinch muhit yarating.'),
  ('c45968e1-c58f-48dd-a705-2dc4c22325e0', 'O‘sish sur’ati. 📏', 'Kiyimlari yana kichik bo‘lib qolyapti! Rivojlanishni kuzatish bo‘limiga bo‘yi va vaznining yangi ko‘rsatkichlarini qo‘shib, sog‘lom rivojlanish grafigini yangilang.'),
  ('f13027ff-0446-4962-9c51-398d40234b5a', 'Ilk san’at asarlari! 🖍', '️ Yo‘g‘on rangli qalamlar bilan qog‘ozga chizishni yaxshi ko‘radi. Uning ilk san’at asarlarini katta mehr bilan kuzating.'),
  ('3b86e3a2-b53e-4603-a4b1-a57fc531000c', 'O‘zi ovqatlanishni xohlaydi! 🥄', 'Ust-boshi va atrof iflos bo‘lsa ham, qoshiqni o‘zi ushlashiga ruxsat bering. Bu uning mushaklar muvofiqligi va mustaqilligi uchun juda muhim.'),
  ('ce4d24a9-fdbd-44df-93c0-058cf5d834aa', 'Shirin quchoqlar! 🤗', 'To‘satdan sizni quchoqlashi va o‘pishga urinishi — uning sevgi izhoridir. Bu betakror lahzalardan zavqlaning va ularni Chaqaloq fotosessiyasida abadiylashtiring.'),
  ('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7', 'Kitob o‘qishga qiziqish. 📖', 'Rasmli kitoblar sahifalarini o‘zi varaqlashiga ruxsat bering. Sizning ovozingizda ertak tinglash uning lug‘at boyligini oshiradi.'),
  ('67d07afb-a906-4267-ae07-195da32a67d1', 'Chegaralarni sinab ko‘ryapti. 🛑', '«Yo‘q» deganingizga qaramay, yana o‘sha buyumga qo‘l uzatyaptimi? Bu o‘jarlik emas, balki qoidalarni o‘rganish uchun sinovdir. Izchil va sabrli bo‘ling.'),
  ('71f533be-645b-4990-ac46-86ad77f1a038', 'Meva vaqti! 🍎', 'Quvvatini tiklashi uchun mavsumiy mevalardan rang-barang va ko‘zni quvontiradigan likopcha tayyorlang.'),
  ('cbf7129c-f3df-44ab-928f-9f74910675e9', 'O‘zingizni unutmang! 💖', 'Farzandingiz uxlagandan keyingi ilk soat faqat sizniki bo‘lsin. Hech qanday ish qilmang, shunchaki sevimli mashg‘ulotingiz bilan shug‘ullanib, dam oling.'),
  ('569d0003-c871-435a-ae9b-f4e977441a16', '16 oylik bo‘lishiga atigi 10 kun qoldi! 🎂', 'Ishonish qiyin! Rosa 10 kundan keyin kichkintoyingiz 16 oylik bo‘ladi. Ushbu sana uchun kichik tort yoki fotosessiya rejalashtirishni boshlang.'),
  ('6f0da037-da86-424d-bd6d-1e6d3aefe4db', 'So‘rashdan tortinmang 🤖', 'Uyqu tartibida nimanidir noto‘g‘ri qilayotganingizni o‘ylayapsizmi? Ikkilanayotgan barcha savollaringizni darhol Anacan AI’dan so‘rab, ko‘nglingizni xotirjam qiling.'),
  ('b0d45a27-101a-4c13-b494-715c8c48dda4', 'Barcha charchoqni bir chetga suring. 🥂', 'Bugun kechqurun farzandingiz uxlagach, juftingiz bilan jamoaviy g‘alabangizni nishonlashni unutmang!'),
  ('8bf81bea-dee2-4f82-9f28-f1e6a128a812', 'Sabr kosasi to‘lganda. 📝', 'Ba’zan bolaning energiyasi sizni butunlay holdan toydirishi mumkin. Kayfiyat kundaligingizni oching va bugun sizni eng ko‘p nima charchatganini erkin yozing.'),
  ('977f5267-192c-40d2-9215-420a5a54d255', 'Sanchqidan foydalanishga o‘tish. 🍴', 'U endi ovqat bo‘laklarini sanchqi bilan sanchib yeyishga urinmoqda. Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan sanchqi bilan olish oson bo‘lgan taomlarni tayyorlang.'),
  ('c22aaf03-7bb2-467b-9c9d-ca82637af893', 'Oyoq kiyimini o‘zi yechadi 👟', 'Uni kiyintirish endi kurashga aylanib qoldimi? U paypoq va oyoq kiyimini o‘zi tortib yechadi. Uning harakat ko‘nikmalariga qoyil qoling!'),
  ('3f154cd8-81d2-425b-aa71-ec2864247772', 'U meniki! 🧸', 'Qo‘lidan biror narsani olsangiz, norozilik bildirib yig‘laydimi? Egalik hissi kuchaymoqda. Bu xarakter shakllanishining muhim qismidir.'),
  ('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27', 'Bugun cho‘miltirish navbati dadasida. 👨‍🍼', 'Bugun kechqurun uni suv o‘yinlari va ko‘pikli vannada cho‘miltirishni, so‘ng uxlatishni dadasiga topshirib, dam oling.'),
  ('b60defb6-6a44-41ab-8087-7dec23cd3f5c', 'Nima pishirsam ekan? 🍲', 'Qo‘shimcha ovqat menyusi uchun g‘oyalaringiz tugadimi? Internetdan izlab ovora bo‘lmang, Sog‘lom retseptlar bo‘limidan yangi mazalarni kashf eting.'),
  ('8878ea41-701a-4729-9437-858b0e0448ae', 'To‘p otish o‘yini! ⚽', 'U to‘pni shunchaki yumalatmayapti, balki qo‘llarini ko‘tarib, siz tomonga otishga harakat qilyapti! Uning bu sportchiga xos urinishlarini darhol Chaqaloq albomiga video sifatida qo‘shing.'),
  ('d2eace3f-d381-45ba-bfbb-2db61f670769', 'Oila albomida kimlar bor? 🖼', '️ Rasmlarni ko‘rayotganda «Buvi qayerda?» deb so‘rasangiz, barmog‘i bilan to‘g‘ri ko‘rsatadimi? Uning xotirasi va yuzlarni tanish qobiliyati jadal rivojlanmoqda.'),
  ('f2055f25-61d4-4680-83b3-954a3f1a9671', 'Muhandislikka ilk urinishlar 🧱', 'U ikkita o‘yinchoq kubikni ustma-ust qo‘yishga harakat qiladi, ammo ular qulab tushadi. So‘ng diqqat bilan yana urinib ko‘radi. Uning urinishlarini indamay kuzating.'),
  ('458a103b-d07a-4e59-ac24-1d9dafc323f0', 'Onalar uchun joy ☕', 'Uyda qolaverib, quvvatingiz tugagan. Onalar uchun qulay joylardan bemalol o‘tira oladigan kafeni tanlab, o‘zingizga vaqt ajrating.'),
  ('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e', 'Injiqlik avjida ☁️', 'Hech narsadan ko‘ngli to‘lmay, hamma narsaga yig‘layaptimi? Balki orqa oziq tishlari chiqayotgandir. Bu jarayonni tish chiqishini kuzatish bo‘limida qayd eting.'),
  ('ed11b132-51fc-4e86-99e0-021b6675020e', 'Tungi alla 🎶', 'Hech bir tovush ona ovozidek tinchlantira olmaydi. Bugun kechqurun uni shunchaki bag‘ringizga bosib, past ovozda kuylang.'),
  ('07f52bf7-1174-455b-9c35-8391687a69fe', 'Rivojlanishni tekshirish 🤖', '16 oylik davrdagi rivojlanish sakrashlari haqida ma’lumot kerakmi? Anacan AI-dan pediatrlar tasdiqlagan qisqa va aniq ro‘yxatni so‘rang.'),
  ('c016a9a1-5e0d-434a-ba4b-907c1125a45a', '16 oylikka atigi 5 kun qoldi! 🎈', 'Sanoqli kunlar qoldi! Tortga buyurtma berdingizmi, kiyimlar tayyormi? Chaqaloq fotosessiyasi uchun quvnoq g‘oyalarni hozirdanoq ko‘rib chiqing.'),
  ('d94026ce-ef2a-4e93-b559-9f926c9f245d', 'Tinchlantiruvchi tovushlar. 🎶', 'Faol kashfiyotlarga boy kundan so‘ng bolangiz tinchlana olmasa, xonada Oq shovqinlardan yomg‘ir tovushini yoqib, osoyishta muhit yarating.'),
  ('523911e7-6ac9-424d-9f11-0729711fb179', 'Sensor o‘yinlar. 🌾', 'Katta idishga biroz guruch yoki makaron solib, ichiga o‘yinchoqlarni yashiring. Bolangiz ularni qo‘llari bilan topib, teginish hissini rivojlantirsin.'),
  ('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533', 'Mustaqil o‘yin vaqti 🧸', 'Endi u 10-15 daqiqa davomida o‘yinchoqlari bilan mustaqil shug‘ullana oladi. Bu diqqatni jamlash davomiyligi ortayotganini bildiradi. Sukunatdan zavqlaning.'),
  ('adb7bf26-343c-4ba5-8233-149cdef6b1f2', 'Musiqaning kuchi 🎶', 'Kechga yaqin hech bir sababsiz boshlanadigan injiqliklarni mayin klassik musiqa bilan bosishga urinib ko‘ring. Ko‘pincha bu oddiy usul mo‘jiza yaratadi.'),
  ('35d30a24-8966-43d1-afce-6f79d49ebcec', 'Mutaxassis yordami. 🤖', '“Farzandim meni tishlayapti, qanday munosabat bildirishim kerak?” kabi xulq-atvorga oid sizni tashvishga solayotgan yangi savollarni Anacan AI yordamchimizdan so‘rang.'),
  ('5c715c5a-b613-43a0-9f22-5f59af3ae1fc', 'Yechinish san’ati. 🧦', 'Kiyinish qiyin, ammo yechinish juda qiziqarli! Bosh kiyimi, paypog‘i yoki oyoq kiyimini o‘zi yechishga urinib ko‘rishiga ruxsat bering.'),
  ('d3844bde-9596-474d-adfe-9c81a7e0ff26', 'Kattalarning buyumlari qiziq. 👜', 'Sizning sumkangizni titkilash yoki dadasining oyoq kiyimini kiyishga urinish — uning eng sevimli mashg‘ulotlaridan. Xavfsiz buyumlaringizni o‘rganishiga ruxsat bering.'),
  ('17b19954-1449-474d-a0b9-d199021947cc', 'Sog‘lom ona — sog‘lom chaqaloq 🥑', 'Temir va kalsiy zaxiralaringiz kamaygan. Sog‘lom retseptlardan tez tayyorlanadigan va sizga quvvat beradigan salat tayyorlang.'),
  ('68c3e726-41d6-481a-91d7-a89fa5795172', 'Chizib-bo‘yash san’ati 🖍️', 'Qo‘liga qalam berganingizda, qog‘ozga chizib-bo‘yashga urinadimi? Bu nozik motorika uchun ajoyib mashq. Qalamlar xavfsiz ekaniga ishonch hosil qiling.'),
  ('ab2f1bd1-caf0-41b5-b8ae-89ec60663539', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda chaqaloq uyg‘onganida barcha mas’uliyatni yolg‘iz o‘z zimmangizga olmang. Turmush o‘rtog‘ingizni ham uyg‘oting: jamoa bo‘lish — mas’uliyatni teng taqsimlash demakdir.'),
  ('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26', 'Dardlashishga ehtiyoj bor 💬', '«Men endi hech qachon avvalgi o‘zimdek bo‘la olmayman», degan o‘y sizni qiynayaptimi? Bu o‘tkinchi tuyg‘uni Anacan hamjamiyatidagi onalar bilan bo‘lishing.'),
  ('2980029e-45df-4043-851c-f7839d81a721', 'Ertaga 16 oy! 🎉', 'Tayyormisiz? Ertaga roppa-rosa 16 oy! Telefoningiz xotirasini bo‘shating — ertaga Chaqaloq fotosessiyasida uning eng yoqimli yuz ifodalarini suratga olish uchun joy kerak bo‘ladi.'),
  ('5d958416-87e8-44f2-8b6e-cde98e63822d', 'Bugun aqlli ertaklarda 🪄', 'Aqlli ertaklarda jasur va yoqimtoy hayvonlar haqida hikoya yarating va xonani sehrli makonga aylantiring.'),
  ('679e2936-6a93-4a92-9069-b372c4d3f661', 'Kechki ertakning sehri bor. 📖', 'Endi u ham kitobdagi rasmlarni sizga ko‘rsatadi. Uyqudan oldin birga o‘qigan kichik hikoyangiz orangizdagi rishtani nihoyatda mustahkamlaydi.'),
  ('86b4bb0f-0f98-485c-9149-10540747f598', 'ROppa-ROSA 16 OY! 🎂', 'Ishonish qiyin, shunday emasmi? Uni ilk bor bag‘ringizga olgan hayajonli kundan beri roppa-rosa 16 oy o‘tdi! Bu ajoyib ulg‘ayishni nishonlashning ayni vaqti. Chaqaloq fotosessiyasidan mavzu tanlab, eng yoqimli lahzani abadiylashtiring va bu faxrni Anacan hamjamiyatidagi boshqa onalar bilan albatta bo‘lishing!'),
  ('fbb768fe-d41f-4451-8978-b683840f7855', 'To‘ldirib-bo‘shatish davri! 📦', 'O‘yinchoqlarni katta qutiga yig‘ish, keyin esa hammasini birdan polga to‘kish! Bu sabab-oqibat o‘yini uning mantiqiy fikrlashini rivojlantiradi.'),
  ('24b47242-9a10-48f7-a928-0a19449b984a', 'Chiroqlarni xiralashtiring 🌙', 'Uxlashga 1 soat qolganda uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch muhitda ajralib chiqadi.'),
  ('2d66c314-cb67-48c8-93d1-be3249bad125', 'Tabiat qo‘ynida xazina ovi. 🍂', 'Parkda sayr qilayotganda turli barglar yoki qubbalarni to‘plang. Onalar uchun qulay joylar orasidan tabiat manzaralari turlicha bo‘lgan yangi parklarni kashf eting.'),
  ('98db8b9f-36cd-4968-86c5-ed66999457de', 'Hayvonlarning ovozlari 🐶', 'Mushukni ko‘rganda miyovlashga, itni ko‘rganda vov-vov deyishga harakat qiladimi? So‘z boyligi hayvonlarning ovozlaridan boshlanadi. U bilan bu o‘yinni o‘ynang.'),
  ('8e91be33-56a9-43aa-bf49-8aa525510abf', 'Tabiat qo‘ynida xazina ovi. 🍂', 'Parkda sayr qilayotganda turli barglar yoki qubbalarni to‘plang. Onalar uchun qulay joylar orasidan tabiat manzaralari turlicha bo‘lgan yangi parklarni kashf eting.'),
  ('a9e6c327-e70b-4cd7-9bed-cb9d250622ba', 'Tinchlantiruvchi tovushlar. 🎶', 'Faol kashfiyotlarga boy kundan keyin farzandingiz tinchlana olmasa, xonada Oq shovqinlar orasidan yomg‘ir tovushini yoqib, osoyishta muhit yarating.'),
  ('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8', 'To‘ldirib-bo‘shatish davri! 📦', 'O‘yinchoqlarni katta qutiga yig‘ish, keyin esa hammasini birdan polga to‘kish! Bu sabab-oqibat o‘yini uning mantiqiy fikrlashini rivojlantiradi.'),
  ('1705b7a5-fb30-4cc3-974a-91a4210ec2a2', 'Bu vaqt faqat siz uchun. 🛁', 'U uxlab qoldi, uy tinchlandi. Endi telefoningizni bir chetga qo‘ying, sevimli filmingizni yoqing va shunchaki hech narsa qilmaslikdan zavqlaning.'),
  ('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb', 'Orqaga va yon tomonga yurish! 🦀', 'U endi faqat oldinga emas, orqaga va yon tomonga qadam tashlab, muvozanatini sinab ko‘rmoqda. Bu quvnoq lahzalarni albatta suratga oling.'),
  ('f05a8717-d544-48fb-a529-17361118fee2', 'O‘sish davri! 📏', 'Farzandingizning bo‘yi o‘sayotganini sezyapsizmi? «Vazn kuzatuvchisi» bo‘limiga uning yangi ko‘rsatkichlarini kiriting va rivojlanish grafigi qanday ko‘tarilayotganini kuzating.'),
  ('75798a4e-e59c-4911-827e-b1622b37ae33', 'Soch tarash va tish yuvish. 🪥', 'U sizni kuzatib, taroqni sochiga olib boradi yoki tish cho‘tkasini og‘ziga soladi. O‘ziga g‘amxo‘rlik qilish odatlarini o‘yin orqali singdirish uchun ayni payt.'),
  ('784b1d1b-2c53-42bf-a43b-d6b6e3121aba', 'Oilaviy kechki ovqat. 🍲', 'Bugun kechqurun uyda ovqat pishirishni xohlamayapsizmi? Farzandingiz uchun alohida menyu va bolalar o‘rindig‘i mavjud restoranlarni ilovamizdagi xaritadan toping.'),
  ('b328273f-0602-46a6-a82b-54d47ec1b77d', 'Chuqur nafas oling. ✨', 'Har bir kun ham rejangizdagidek o‘tmasligi, uy esa ba’zan tartibsiz bo‘lib qolishi mumkin. Mukammal bo‘lishingiz shart emas, siz uning uchun eng yaxshisiz.'),
  ('714f8ced-9ccc-40ff-a807-9428279f86d4', 'Oson uyquga ketish. 🌙', 'Faol o‘tgan kundan so‘ng xona chiroqlarini xiralashtiring va unga past ovozda alla aytib, chuqur uyquga ketishi uchun sharoit yarating.'),
  ('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4', 'Tanlash imkonini bering. 👕', 'Qizil ko‘ylakni kiyasizmi yoki ko‘kini? – Unga kichik tanlovlar berish qaysarlikni kamaytiradi va o‘zlik hissini mustahkamlaydi.'),
  ('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe', 'Murakkab bekinmachoq! 🙈', 'O‘yinchog‘ini ikki xil yopqich ostiga yashirsangiz ham, uni osongina topa oladimi? Demak, predmetlarning doimiy mavjudligi haqidagi tushuncha to‘liq shakllangan.'),
  ('373a30b7-4c10-4d16-b029-a2c123ab28b9', 'Yugurish mashqlari boshlanmoqda! 🏃‍♂', '️ Tez qadamlar endi kichik yugurishlarga aylanmoqda. Tizzalarini himoya qilish qiyinlashsa-da, uning bu erkinlik quvonchini kuzatish barcha qiyinchiliklarga arziydi!'),
  ('5a23341a-91f5-4bdf-a760-e7b99f610283', 'Turli teksturalarni sinab ko‘rishga tayyor. 🥦', 'Taomlaridagi rang va shakllarni o‘zgartirib, ishtahasini oshiring. G‘oyalar uchun «Qo‘shimcha ovqatni boshlagan chaqaloqlar uchun retseptlar» bo‘limidan ilhom oling.'),
  ('6581c209-98c5-4f79-adf1-c7b985567899', 'Siz haqiqiy qahramonsiz. 🛁', 'Kun bo‘yi tinmay yugurib yurgan bolani epladingiz. Endi issiq choyingizni quyib oling va hech narsani o‘ylamasdan shunchaki dam oling.'),
  ('bf80d71f-c8bb-4983-b046-1ee91c367f20', 'Mutaxassis ko‘magi. 🤖', 'So‘zlarni tushunadi, lekin nega kam gapiradi? kabi sizni o‘ylantirayotgan savollarni Anacan AI yordamchimizga berib, ko‘nglingizni xotirjam qiling.'),
  ('cd0e822c-b843-41fa-9a3e-f4b682a848ae', 'Qoshiqdan mustaqil foydalanish. 🥄', 'Qoshiqni og‘ziga olib borayotganda ovqatni kamroq to‘kadi. Uning mayda motorika borasidagi bu yutug‘ini olqishlang va mustaqil harakat qilishiga imkon bering.'),
  ('d6374c1a-94a0-4de3-855d-6a8d4e9a29af', 'O‘yinchoqlarga hamdardlik. 🧸', 'O‘yinchoq ayig‘ini silaydimi, uni ovqatlantiradimi yoki ustini yopadimi? Bunday yoqimli rolli o‘yinlar uning hissiy intellekti naqadar yaxshi rivojlanayotganini ko‘rsatadi.'),
  ('299405ea-50dc-48c1-ba2a-233941bf627c', 'Dada bilan ertak vaqti. 👨‍🍼', 'Bugun kechki ertakni o‘qish va uxlatish navbatini dadasiga topshirib, o‘zingizga biroz dam bering.'),
  ('7ad6ef35-e677-498c-8bc2-cc3e84535415', 'Xavfsizlik choralarini yangilash kerak. 🛡️', 'Shkaflar va tortmalarni ochish uning eng sevimli mashg‘ulotiga aylangan. Bolalar uchun himoya qulflarini tanlashda Tavsiya etilgan mahsulotlar ro‘yxatimizni albatta ko‘rib chiqing.'),
  ('ec2361c8-31f7-458e-ad6e-506355b447a5', 'Yangi marralar zabt etilmoqda! 🧗‍♂', '️ U endi balandroq joylarga qo‘lini yetkaza oladi va mebellar ustiga osonroq chiqadi. Uydagi xavfsizlik choralarini yana bir bor ko‘zdan kechirish vaqti keldi.'),
  ('755229fb-26a0-4a27-af2c-49bb6a367386', 'Tinchlantiruvchi odat. 🌙', 'Tungi uyqudan oldin xona chiroqlarini xiralashtirib, pichirlab gapirish chaqaloqni ham tinchlantiradi va uyquga tayyorlaydi.'),
  ('ae949749-3a87-49dc-a4ae-057b9e3594b1', 'Chizgilardan maqsadli chiziqlargacha! 🖍', '️ Qo‘liga qalam olganda, shunchaki nuqtalar emas, uzun chiziqlar chizishga harakat qiladi. Ushbu kichik san’at asarini suratga olib, darhol Chaqaloq albomiga qo‘shing.'),
  ('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9', 'Tabiat qo‘ynida xazina izlash. 🍂', 'Hovli yoki bog‘da barglar va mayda toshlarni yig‘ib, ularni o‘rganish chaqaloqning sensor (sezgi) rivojlanishi uchun ajoyib mashg‘ulotdir.'),
  ('1b65f6b1-f423-43f5-bc48-5ffb574c7c74', 'Suvli o‘yinlar bilan hordiq. 🛁', 'Iliq vannada cho‘milayotganda suvga tashlagan o‘yinchoqlari bilan o‘ynash kun davomida to‘plangan zo‘riqishni kamaytiradi va juda maroqli bo‘ladi.'),
  ('bc0b7dcc-fdc0-4664-bff5-56183ea22258', 'Ikki bosqichli ko‘rsatmalarni tushunadi! 🧠', '«Oyoq kiyimingni ol va menga ber», deganingizda ikkala harakatni ham ketma-ket bajaryaptimi? Bu uning aqliy rivojlanishidagi ajoyib sakrash belgisidir!'),
  ('c18b2eee-ba78-43cc-89fd-423a464819d2', 'Onaning quvvati juda muhim. 🥗', 'Tinimsiz yugurib, charchadingiz. Ayollar uchun foydali retseptlardan foydalanib, o‘zingizga mazali va vitaminlarga boy taom tayyorlang.'),
  ('21888245-7cf1-48e4-a08b-53389aa39131', 'Suv ichishni qiziqarli qiling. 💧', 'Faol yugurish va o‘yinlar chanqoqni keltirib chiqaradi. Rangli idishida unga tez-tez suv taklif qilib, organizmidagi suyuqlik miqdorini me’yorda saqlang.'),
  ('4595ac68-2033-4a66-a4d9-1146030382ed', 'Kun sarhisobi. ✨', 'Har kuni mukammal bo‘lishingiz shart emas. Bugun nimanidir qilishga ulgurmagan bo‘lsangiz, hechqisi yo‘q. Siz uning uchun eng yaxshisisiz.'),
  ('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85', 'Ritmni his qilish qobiliyati kuchaymoqda! 🎶', 'Sevimli qo‘shig‘ining ilk soniyalarini eshitishi bilan harakatga tushib, jilmayadimi? Bu zavqli lahzalarni Chaqaloq fotosessiyasi orqali suratga olib, oilaviy guruhga yuboring.'),
  ('33b8d80d-5434-483c-b198-c7b20c73321d', 'Tana a’zolarini yanada batafsil taniydi. 👂', 'Qorning qayerda?, Qulog‘ing qayerda? kabi yangi savollarga to‘g‘ri javob berishi uning o‘rganish qobiliyati jadal rivojlanayotganini ko‘rsatadi.'),
  ('87029bf7-0808-4eac-a180-0abfa62f0b48', 'Birgalikda kitob o‘qing. 📖', 'Endi u sahifalarni varaqlashdan tashqari, kitobdagi hayvonlar yoki buyumlarni barmog‘i bilan ko‘rsatib, ularning nomini aytishingizni kutadi.'),
  ('cc468aff-f9d2-4961-b955-bf2eaa13f7ef', 'O‘sish sur’ati qanday? 📏', 'Kiyimlarining yenglari va pochalari yana kalta bo‘lib qolmoqda! Vazn kuzatuvchisi bo‘limiga yangi ko‘rsatkichlarini kiriting va rivojlanish grafigidagi o‘sishni kuzating.'),
  ('069cc383-0002-41b5-ba19-4172c6d6b10f', 'Uxlab qolish qiyinlashyaptimi? 😴', 'Faol kashfiyotlar ba’zan bolani hayajonda ushlab turadi. Uyqu taymerini yoqing, uxlashdan oldin xona yorug‘ligini minimum darajaga tushirib, ertak o‘qib bering.'),
  ('1beeca23-44cf-48f8-9b07-fc08412e7809', 'Rahmat va iltimos. 🙏', 'U biror narsani berayotganda yoki olayotganda bosh ishorasi bilan yoki o‘z tilida minnatdorlik bildira boshladi. Ijtimoiy odob qoidalarini o‘rgatishning ayni vaqti!'),
  ('eb807359-495c-4338-a628-e4dd3e405226', 'Bo‘y va vazn o‘sishini kuzatamiz. 📏', 'Kiyimlari yana kichik bo‘lib qoldimi? Vazn kuzatuvchisi bo‘limida yangi ko‘rsatkichlarni kiriting va 500-kun uchun rivojlanish grafigini tayyorlang.'),
  ('158d01ac-e4e7-4be6-959c-37e93007ee0b', 'Kitobdagi hayvonlarni taniydi. 🐶', '«Kuchuk qayerda?» deb so‘raganingizda, barmog‘i bilan ko‘rsatadimi? So‘z boyligini oshirish uchun kitobdagi buyumlarning ranglarini ham ayta boshlang.'),
  ('9e266e10-1251-4668-af5f-a58fe3b3f537', 'Xavfsizlik choralarini yangilash kerak. 🛡️', 'U endi balandroq joylarga qo‘lini yetkaza oladi. Stol ustidagi yopqichlar va o‘tkir burchaklarni yana bir bor tekshiring. Zarur bo‘lsa, Tavsiya etilgan mahsulotlar bo‘limini ko‘rib chiqing.'),
  ('ca40c713-93a7-4e51-9b1b-8465a3151e1f', 'Dada bilan sho‘xlik vaqti. 👨‍🍼', 'Kechki paytdagi serharakat vaqtni dadasiga topshiring. Ularning birgalikdagi quvnoq o‘yinlari o‘zaro mehrini kuchaytiradi va sizga dam olish imkonini beradi.'),
  ('308b629a-7190-416d-8240-7f61a2fe4d68', 'O‘zini ifoda eta olmaganda paydo bo‘ladigan jahldorlik. 🌪', '️ Istagan narsasi bo‘lmaganda yoki o‘z fikrini tushuntira olmaganda jahli chiqib, yig‘lashi odatiy hol. Uning bo‘yi darajasigacha egilib, his-tuyg‘ularini tushunishingizni ayting.'),
  ('78541e65-2128-40ff-8cb4-1e0d54454519', 'His-tuyg‘ularingizni erkin ifoda eting. 📝', 'Kun juda charchatdimi? Bola uxlagach, Kayfiyat kundaligiga his-tuyg‘ularingizni yozib, kun davomida yig‘ilgan stressdan xalos bo‘ling.'),
  ('7ea95622-1f8d-4996-8638-aeeafe28a802', 'Yangi joylarni kashf eting. ☕', 'Kundalik tartibdan zerikdingizmi? Bola bilan bemalol borishingiz mumkin bo‘lgan, bolalar menyusiga ega kafelarni Onalar uchun qulay joylar bo‘limidan toping.'),
  ('58ff14f8-978e-4eec-8b86-a777de1b33ba', 'Yig‘ish va tartibga keltirish o‘yini. 🧺', 'O‘yinchoqlarni qutidan sochib tashlashni yaxshi ko‘radigan kichkintoyingiz endi ulardan ayrimlarini qayta joyiga solishni ham o‘rganmoqda. Birgalikda yig‘ishtirish haqida qo‘shiq kuylab, bu ishni maroqli o‘yinga aylantiring.'),
  ('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81', 'Uyqu tartibi o‘zgaryaptimi? ⏱️', 'Agar kunduzgi uyqu butunlay bir martaga tushgan bo‘lsa, tungi uyquga o‘tish vaqti biroz o‘zgarishi mumkin. Anacan uyqu taymeri yordamida bugungi jadvalni kuzatib, yangi tartibni moslashtiring.'),
  ('e71126af-730c-4cca-8daa-1682609e21a1', 'Shakllarni joylashtirish (Pazllar). 🧩', 'U doirani dumaloq teshikka, kvadratni esa kvadrat teshikka joylashtirishga urinadi. Bunday mantiqiy o‘yinlar uning sabr-toqati va diqqatini oshiradi.'),
  ('17791a06-d7d3-466d-acee-c2689fa82589', 'Sensor o‘yinlar. 🌾', 'Katta idishga guruch yoki qum solib, ichiga o‘yinchoqlarni yashiring. Ularni qo‘llari bilan qidirib topishi barmoqlarning mayda motorikasini rivojlantirish uchun juda foydali.'),
  ('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3', 'Kiyim tanlash huquqi. 👕', 'Ko‘k ko‘ylakni kiymoqchimisiz yoki yashilini? Bolaga ikkita variant taklif qilish uning o‘zligini anglash tuyg‘usini kuchaytiradi va qaysarligini biroz kamaytiradi.'),
  ('e6632c98-233d-431d-adc3-c5f78c1c7a37', 'Suvli o‘yinlar bilan hordiq. 🛁', 'Iliq vanna va suvning shildirashi kun davomida to‘plangan barcha charchoqni ketkazadi. Suvga turli o‘lchamdagi idishlarni solib, bolaga hajm tushunchasini o‘rgating.'),
  ('148de716-5fb6-4776-96cc-81e2d00b53b8', 'His-tuyg‘ularingizni baham ko‘ring. ✨', 'Ba’zan hamma muammolar bir paytda ustma-ust kelishi mumkin. Kun oxirida ruhiy xotirjamlikni his qilish uchun sevimli mashg‘ulotingiz bilan shug‘ullaning.'),
  ('b3ddea65-cbd9-4fdd-900d-8914e021db1f', 'To‘pni nishonga otmoqda! ⚽', 'U endi to‘pni shunchaki yumalatmaydi, balki uni muayyan yo‘nalishga otishga harakat qiladi. Bu ko‘z va qo‘l muvofiqligi rivojlanayotganining yaqqol belgisidir.'),
  ('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3', 'Suv ichishni maroqli qiling. 💧 A', 'Faol bolalar tez chanqaydi. Organizmi suvsizlanmasligi uchun unga rang-barang va qiziqarli idishda muntazam ravishda suv taklif qiling.'),
  ('2f67b26a-192a-4bd5-87f9-5f376ff164e3', 'Ikki bosqichli topshiriqlar. 🧠', 'O‘yinchoqni ol va qutiga sol. Bunday murakkab topshiriqlarni bajara olishi uning idrok etish qobiliyati yuqori ekanini ko‘rsatadi.'),
  ('bf0e882a-2f6d-4439-b170-c9adaeed59cd', 'Musiqaga o‘z ritmida raqs tushadi. 🎶', 'Endi u shunchaki tebranmaydi, balki musiqa sur’atiga mos ravishda qarsak chaladi yoki aylanadi.'),
  ('c522fcf6-60fc-463a-b943-7933f5ac5c70', 'Kechki ertak sehrlidir. 📖', 'Rasmlarga qarab, ertakni o‘z tilida aytib berishiga imkon bering. Bu kelajakda kitob o‘qish odatining poydevoridir.'),
  ('19e05272-ac3b-430f-bbad-b5c770118fd3', 'Yubiley bayrami! 🎈', 'Kichkina tort yoki uning sevimli mevasi bilan bu kunni nishonlang. Uning qanchalik tez ulg‘ayayotganini ko‘rish — siz uchun eng katta mukofotdir.'),
  ('52e84dda-8f2e-4dce-9b8e-b095190c1816', 'O‘zingizga minnatdorlik bildiring. ✨', '500 kun davomida ko‘rsatgan fidoyiligingiz, mehringiz va sabringiz uchun o‘zingizga minnatdorlik bildiring. Endi xotirjam uxlang, ertaga yangi davr boshlanadi!'),
  ('7cc24719-4bcf-403b-9178-3f6a80317c26', 'Ajoyib 500 kun.🎉', 'Ishona olasizmi?! Tug‘ruqdan beri roppa-rosa 500 kun o‘tdi!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid, 'Ona uchun quvvatlanish 🔋', 'Kun bo‘yi yugurib yurish butun quvvatingizni so‘rib oldimi? O‘zingizni unutib, bola katta qilish qahramonlik emas. Uni xavfsiz joyga qo‘yib, 10 daqiqalik qahva tanaffusi qiling.'),
  ('dcf8f474-5360-4c6f-ac54-ecde70444961', 'Tezlik chegarasi oshib ketdi 🏃‍♂️', 'U endi yurmayapti, deyarli yuguryapti! Unga yetib olish tobora qiyinlashmoqda. Rivojlanish kuzatuvchisiga bu yangi tezlik rekordini qayd eting va uydagi to‘siqlarni olib tashlang.'),
  ('fb70ef32-f9e7-42c7-9f54-302457a506bf', 'So‘zsiz tushunish 🫂', 'Bugun juda charchadingiz. Chaqaloq uxlagach, turmush o‘rtog‘ingiz bilan hech narsa demay, shunchaki divanda yonma-yon o‘tirib, sukunatdan zavqlaning.'),
  ('19f5918f-33f2-423f-ba32-d0be2a6bca2a', 'Tanangizning ehtiyoji 🥑', 'Qo‘llaringiz va belingiz og‘riyaptimi? U ancha og‘irlashdi. Foydali retseptlar orasidan kalsiy va oqsilga boy yengil tushlikni tanlab, mushaklaringizni qo‘llab-quvvatlang.'),
  ('3ddcf967-26bf-4c82-a9be-ef2d0c28d637', 'Tasavvurga boy o‘yinlar boshlanmoqda 🧸', 'O‘yinchoq ayiqchasiga ovqat yedirishga yoki uni uxlatishga urinyaptimi? Uning tasavvuri uyg‘onmoqda! Hamdardlikning bu ajoyib ilk ko‘rinishlarini chetdan faxr bilan kuzating.'),
  ('c178ee13-258d-408c-8a70-3133436f4f3b', 'Dada bilan o‘yin vaqti 👨‍👧', 'Sabringiz tugab boryaptimi? Bu oqshom polda dumalash va qitiqlash o‘yinlarini dadasiga topshiring.'),
  ('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785', 'Tajribangiz bilan bo‘lishing 💬', '“Mening bolam ham shundaymi?” degan o‘y sizni bezovta qilyaptimi? Anacan hamjamiyatiga qo‘shiling, 16 oylik bolasi bor boshqa onalarning hikoyalarini o‘qib, yengil torting.'),
  ('61b42915-8f61-46a7-b887-07cc8998e71f', 'Tinchlantiruvchi vanna. 🛁', 'Uxlashdan oldin iliq suvda o‘ynash kun davomida to‘plangan barcha taranglikni ketkazadi. Suvga biroz efir moyi qo‘shib, osoyishta muhit yarating.'),
  ('f5e358ba-f868-4a50-851c-6980fa2b0075', 'Zinadan mustaqil chiqishga urinish. 🪜', 'Endi qo‘lingizdan ushlab, zinadan ancha ishonchli chiqadi. Oyoq mushaklarini mustahkamlashi uchun unga xalaqit bermang, faqat xavfsizligini ta’minlang.'),
  ('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6', 'Cho‘ntagingizdagi ro‘yxat 🛒', 'Kundalik tashvishlar orasida shampun tugadimi yoki nam salfetkami? Barchasini yodda saqlashga urinmang, xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan sinxronlashtiring.'),
  ('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7', 'Savolingiz bormi? 🤖', '“Nega kechasi uyg‘onishlar ko‘paydi?” kabi savollarni hatto tunda ham Anacan AI yordamchisidan so‘rab, darhol javob oling.'),
  ('c67019a7-8ef8-4eef-bcc7-41d6f859382f', 'Sizni topdim! 🙈', 'Ko‘zlarini qo‘llari bilan berkitib, ku-ku o‘ynayaptimi? Unda obyektlar ko‘rinmasa ham mavjud bo‘lishini anglash qobiliyati takomillashmoqda.'),
  ('05b16636-3744-4ea1-b6f2-f3824e51cd2d', 'Oshxonadagi kashfiyotlar. 🍎', 'Mevalarni yuvayotganda uning ham yordam berishiga ruxsat bering. Suvning shovullashi va mevalarning ranglari uning qiziqishini saqlab turadi.'),
  ('3fd7287e-bc6f-49d6-a94b-292122e10559', 'So‘zlardan gap tuzishga urinishlar. 🗣', '️ “Ona, ber” yoki “Dada, qara” kabi ikkita so‘zni birlashtirishga harakat qilyaptimi? Bu nutq rivojlanishidagi ajoyib sakrashdir!'),
  ('d3ed901e-4f05-435d-a1d6-02b2847be818', 'Sehrli tungi fon 🪄', 'Uxlab qolishga qiynalyaptimi? Oq shovqin sifatida faqat daryo shovqinidan iborat tinchlantiruvchi fonni yoqing.'),
  ('9884e1c4-18cf-4fce-b89d-ae4f4603110b', 'Kichkina rassom ish ustida 🖍️', 'Qo‘liga qalam bersangiz, qog‘ozga (yoki devorga) chizib tashlayaptimi? Uning mayda motorikasi jadal rivojlanmoqda. Yuviladigan bo‘yoqlar sotib olish vaqti keldi.'),
  ('cbbf4112-6812-4999-b3bd-fe378d632205', 'Dadaning ertak aytish vaqti. 👨‍🍼', 'Kechqurungi so‘nggi serharakat o‘yinlarni dadasiga topshiring. Ularning birgalikdagi kulgisi siz uchun eng yoqimli hordiq foniga aylanadi.'),
  ('fcd25c40-af67-4335-a70a-9d6c3e016480', 'Ob-havoni o‘rganamiz ⛅', 'Tashqarida shamolmi yoki shunchaki salqinmi? Derazadan qarab adashmang. Ob-havo va kiyim vositasi sizga mos aniq kiyim kombinatsiyasini bir necha soniyada ko‘rsatadi.'),
  ('45bc547e-6211-4178-aad6-4266015ca9cf', 'Biz bir jamoamiz! 💖', 'Og‘ir kundan so‘ng turmush o‘rtog‘ingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash jismoniy va ruhiy yukni teng yarmiga bo‘lishga yordam beradi.'),
  ('89373578-8a41-4cd9-bcef-3a5786b1f576', 'Pediatriyaga oid savollar 🤖', '16–18 oylik rivojlanish davrida nimalarni kutish kerak? Internetda qo‘rqinchli xabarlarni o‘qish o‘rniga, Anacan AI’dan mutaxassisning aniq xulosasini so‘rang.'),
  ('daea63ca-66de-40da-bafb-c740af314d06', 'Kitobga mehr 📖', 'Kitob varaqlarini mustaqil aylantirib, rasmlarga barmog‘i bilan tegayaptimi? Kitob o‘qish odati hozirdanoq shakllanmoqda. U bilan birga rasmlardagi narsalarni nomlang.'),
  ('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d', 'To‘satdan qichqirib uyg‘ondimi?', 'Bu uyqu dahshati bo‘lishi mumkin. Ovozini Yig‘i tahliliga eshittirib, muammo jismoniy yoki psixologik ekanini aniqlang.'),
  ('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c', 'Uy yumushlari kutib turishi mumkin 🛑', 'Pol artilmadimi? Mayli, qolaversin. Iflos uyni tozalash mumkin, ammo holdan toygan onaning tiklanishi uzoq davom etadi. Divanga yotib, shunchaki sokinlikka quloq tuting.'),
  ('fba2093e-fbf1-4663-b05f-7071650fd43f', 'Mantiqiy o‘yinlar 🧱', '3–4 ta kubikni ustma-ust qo‘yib, minora quryaptimi? Rivojlanish kuzatuvchisida mayda motorikadagi bu yutug‘ini qayd eting! Uning bu kichik muhandislik urinishlarini olqishlang.'),
  ('0fea9ae7-0132-47ff-9282-adcf39bd128b', 'Uxlab qolish osonlashsin. 🌙', 'Xona yorug‘ligini imkon qadar pasaytirib, sekin pichirlab gapiring. Bu uning asab tizimiga dam olish vaqti kelganini bildiradi.'),
  ('449d1eaf-e90d-45bb-8ac5-83cc8e44397d', 'Quvvatni tiklash vaqti. 🍎', 'Bola uxlayotganda siz ham 20 daqiqaga ko‘zingizni yuming. Uy ishlari tugamaydi, ammo sizning quvvatingiz tugashi mumkin. O‘zingizni asrang.'),
  ('eb955e5b-023a-4e67-ac53-d6ab712c507e', 'Kichkina yordamchi. 🧺', 'O‘yinchoqlarni qutiga yig‘ayotganingizda u ham bittasini olib kelib qo‘yadimi? Bunday kichik yordamini albatta olqishlang va unga minnatdorlik bildiring.'),
  ('49fd2511-4696-40ce-a9eb-8140a6570163', 'Aqlli ertak sehri 🪄', 'Aqlli ertaklarda bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: Sehrli o‘rmonda sayr qilayotgan jasur kichkintoy.'),
  ('f03e45ee-5599-42df-9ad9-5c86e351f328', 'Onaning shaxsiy vaqti 🎧', 'Bola uxlashi bilan oshxonaga yugurmang. Quloqchiningizni taqing, sevimli qo‘shig‘ingizni qo‘ying va 15 daqiqa faqat o‘zingizga vaqt ajrating.'),
  ('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9', 'O‘zi ovqat yeyishni talab qilmoqda. 🥄', 'Qoshiqni qo‘lingizdan olsa, to‘sqinlik qilmang. Ust-boshi kir bo‘lsa ham, mustaqil ovqatlanishi uning o‘ziga ishona boshlaganining eng katta dalilidir.'),
  ('59f57b09-3fb4-490e-8cae-41edccebdd18', 'Shirin tushlar 🌙', 'Bugun juda charchadingiz. Chaqalog‘ingiz uxlayotganda Oq shovqinlardan okean to‘lqinlari ovozini yoqing — u ham tinch uxlasin, siz ham dam oling.'),
  ('69941885-7481-4f3d-83b9-75392ac8bf14', 'Ovqatlanish taymeri ⏱️', 'Ovqatlanish vaqtini kuzatish endi yanada oson! Ovqatlanish taymerini yoqing va chaqalog‘ingizning kunlik me’yorini diqqat bilan nazorat qiling.'),
  ('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954', 'Yugur-yugur boshlandi! 🏃‍♀️', '17 oylik kichik kashfiyotchingiz uyni ostin-ustun qilyaptimi? Energiyasini sarflashi uchun Onalar uchun qulay joylar bo‘limidan yaqin atrofdagi yangi bog‘ni toping.'),
  ('310b35fd-56c2-4e43-bf45-49c975449bf2', 'Mazali va noodatiy! 🥦', 'Bugun unga qanday noodatiy taom tayyorlashni o‘ylayapsizmi? Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limida mazali g‘oyalar bor.'),
  ('9477e55c-8f99-4ea9-8c87-38780aa67baa', 'His-tuyg‘ularingizni yozing 📝', 'Onalik ba’zan charchatadi va bu mutlaqo tabiiy. Kayfiyat kundaligiga bugun sizni eng ko‘p nima charchatganini yozing va yengil torting.'),
  ('bd556eab-5192-450f-94ce-a80cdc85557b', 'Tonggi syurpriz 💩', 'Kunning birinchi tagligini almashtirdingizmi? Ilovadagi taglik kuzatuvchisiga qayd etishni unutmang, shunda gigiyena tartibini osongina nazorat qilib boramiz!'),
  ('09e40e6a-1b4a-402d-88ca-e9d2b030ae96', 'Menga qara! ☝️', 'E’tiboringizni jalb qilish uchun tovush chiqaradi va barmog‘i bilan o‘zini qiziqtirgan narsani ko‘rsatadi. Uning kashfiyotlariga sherik bo‘ling va «Ha, bu to‘p», deb tasdiqlang.'),
  ('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3', 'Qoshiqni o‘zim ushlayman 🥄', 'O‘zi ovqatlanishni xohlab, ovqatning yarmini ustiga to‘kyaptimi? Tozalikka e’tibor qaratmang. Bu kunlar uning mustaqil ovqatlanish ko‘nikmasiga poydevor bo‘ladi.'),
  ('c62d64af-c28e-4bfc-82ce-a73c5d55fd91', 'Kun hisoboti 📝', 'O‘zingizni yetarlicha yaxshi ona emasdek his qilganingizda, Kayfiyat kundaligiga bugungi kichik yutuqlaringizni yozing. (Masalan: Uni kuldirdim, qornini to‘ydirdim). Siz ajoyibsiz.'),
  ('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22', 'Suhbat yanada jiddiylashmoqda 🗣️', 'Tushunarsiz so‘zlar bilan sizga nimanidir aytib, hatto qo‘l harakatlarini ham qilyaptimi? U bilan xuddi shunday jiddiy ohangda muloqot qiling — bu uning nutqi rivojlanishi uchun juda muhim.'),
  ('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c', 'Toza havoning kuchi 🌙', 'Uxlashni istamayaptimi? Derazani ochib, xona havosini to‘liq almashtiring. Salqin va toza havo uxlab qolishni har doim osonlashtiradi.'),
  ('66766839-1404-43e5-8e4f-02d3ea6ce97c', 'Allergiyadan shubhalanyapsizmi? 🤖', 'Yangi meva berdingiz va terisida qizarish paydo bo‘ldimi? Vahimaga tushishdan oldin Anacan AI yordamida bolalarda oziq-ovqat allergiyasi kuzatilganda ko‘riladigan dastlabki choralarni bilib oling.'),
  ('86fd1056-7ec6-4295-9ae9-cce90735b8fe', 'Kunduzgi uyqu 😴', 'Uyqu taymerini ishga tushiring! 17 oylik bolaning kunduzgi uyqu davomiyligini tahlil qilib, kechqurun uxlatish rejasini yanada aniqroq tuzing.'),
  ('88975ce2-bde2-4036-a81f-ecfc994e6ec7', 'Qulaylik izlab 🍼', 'Uning mustaqil ichishi uchun eng yaxshi to‘kilmaydigan ichimlik idishini izlayapsizmi? Tavsiya etilgan mahsulotlar bo‘limida onalar eng ko‘p yoqtirgan variantlarni ko‘rib chiqing.'),
  ('b24e422c-33a1-4394-8c5a-e6048392180c', 'O‘zingizni unutmang! ☕', 'Sizning quvvatingiz chaqalog‘ingiz uchun eng muhim shartdir. Sog‘lom retseptlardan foydalanib, o‘zingiz uchun mazali va quvvat beruvchi smuzi tayyorlang.'),
  ('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d', 'Blog va qahva 📖', 'Bolangiz uxlab qoldi, endi vaqt sizniki! Yangi blog maqolamizni o‘qib, faol bolalar psixologiyasi haqida juda qiziqarli ma’lumotlarni bilib oling.'),
  ('92227c75-1f64-4b68-adfc-1f2f5187c456', 'Qulay sayr 👟', 'Bog‘da uning ortidan yugurish uchun sizga ham, unga ham qulay poyabzal kerakmi? Tavsiya etilgan mahsulotlar bo‘limidagi eng yaxshi variantlarni ko‘rib chiqing.'),
  ('ee92e380-b93d-467f-ae59-b65756c20e29', 'Savolingiz bormi? 🤔', 'Bolangizning tobora kuchayib borayotgan qaysarligini qanday yengish haqida o‘ylayapsizmi? Anacan AI mutaxassislar tavsiyalari asosida darhol javob berishga tayyor!'),
  ('0d93db4a-8b6f-404c-af2e-d97c0d79adf5', 'Chuqur nafas oling ✨', 'Hamma narsa mukammal bo‘lishi shart emas. Siz shundoq ham eng yaxshi onasiz! Kayfiyat kundaligida kun davomida yig‘ilgan stressdan xalos bo‘lib, dam oling.'),
  ('c34d441d-5c3c-48a4-9477-974b42412b6e', 'Bo‘yi o‘sdimi? 🦒', 'Kiyimlari torayib qolganini sezyapsizmi? Rivojlanish kuzatuvchisiga yangi ko‘rsatkichlarni kiriting va o‘sish grafigi qanday yuqorilayotganini tekshiring.'),
  ('d37162b5-bdeb-4abc-8206-52d2382cc6de', 'Ovqatlanish me’yori 🥣', 'U bugun yetarli miqdorda oqsil oldimi? Ovqatlanishni nazorat qilish vositasi yordamida chaqalog‘ingizning kundalik menyusini tahlil qiling va yetishmayotganlarini to‘ldiring.'),
  ('06c24f98-8519-42a4-86d5-14e6b430bf94', 'Tinchlantiruvchi ovoz 🌧️', 'Kun davomida hayajonlanganidan uxlay olmayaptimi? Oq shovqinlar orasidan yomg‘ir ovozini tanlang va uning asab tizimi tabiiy ravishda tinchlanishiga yordam bering.'),
  ('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc', 'Bugun boshqacha bo‘lsin 🌟', 'Uydagi bir xil kundalik tartib sizni zeriktirdimi? Onalar uchun qulay joylar xaritasini oching va chaqalog‘ingiz bilan birga bemalol o‘tirishingiz mumkin bo‘lgan yangi kafe toping.'),
  ('ea228eca-a9dc-4d32-bfab-5af38c95cc81', 'Chaqaloq — yulduz! 📸', 'Uning yoqimli tabassumi dunyolarga arziydi! Chaqaloq fotosessiyasi funksiyasidagi turli ramkalardan foydalanib, bu kunni abadiylashtiring.'),
  ('5124c8a0-ed5f-4aa8-8203-12fc951409c5', 'Oshqozon-ichak tekshiruvi ⏱️', 'Kunlik taglik sarfini kuzatish ovqatlanish sifatini baholashga yordam beradi. Bugungi taglik almashtirishlarini ilovamizga qayd etdingizmi?'),
  ('9c188bf4-4509-4c22-a2b7-a1a25cc28562', 'Oila davrasidagi dasturxon 🍲', 'Kechki ovqatga unga nima berasiz? Qo‘shimcha ovqat retseptlarida butun oila sevib iste’mol qiladigan umumiy va foydali taom g‘oyalari bor.'),
  ('dab8f6cb-2ef5-454d-85b6-120c0f7644eb', 'Onalik hikoyangiz 📝', 'Har bir onaning hikoyasi o‘ziga xos. Bloglarimizdagi boshqa onalarning hayotiy tajribalari va hikoyalarini o‘qib, ilhom oling.'),
  ('2522685d-511e-40e4-ab2a-4b34a238936c', 'Parkda yugurish 👟', 'Ilk qadamlardan so‘ng yugurishlar boshlanadi. Birinchi poyabzalni tanlash uchun Tavsiya etilgan mahsulotlar bo‘limidagi sog‘lom modellarga qarang.'),
  ('4b619580-dcf5-4c3a-a584-37bd74dfbaba', 'Xonadagi osoyishtalik 🌊', 'Bugun uxlab qolish qiyinmi? Oq shovqinlardan okean to‘lqinlari ovozini yoqing — u asab tizimini tinchlantirib, uyquga ketishni osonlashtiradi.'),
  ('7ae22b42-7e16-455e-8d98-b410c2cd5c7a', 'Oqsil yetarlimi? 🍗', 'Bolaning o‘sishi uchun oqsil zarur! Ovqatlanishni nazorat qilish vositasi yordamida uning kundalik oziq-ovqat muvozanatini baholang va yetishmayotganlarini to‘ldiring.'),
  ('2c591870-5eb2-4029-b209-ea812c8276ab', 'Uyqu taymeri yoqilganmi? ⏳', 'Chaqalog‘ingizni uxlatishni boshlayapsizmi? Taymerni yoqing va uxlab qolish uchun ketgan vaqtni tahlil qilib, bu tartibni qanday yaxshilash mumkinligini bilib oling.'),
  ('9c6e1121-6b3a-4988-b52a-daff7cb47017', 'Aqlli yordamchingiz 🤖', 'Nega bolaning ishtahasi birdan yo‘qoldi? Shu va boshqa tashvishli savollaringizni Anacan AI’ga yozing va darhol ilmiy asoslangan javob oling.'),
  ('fb78ab52-3c7a-4706-adfa-55485f38dc6d', 'Quvvat to‘plang 🔋', 'Kunning shiddatli sur’atiga tayyormisiz? Ayollar uchun foydali retseptlar orasidan o‘zingizga mazali va vitaminlarga boy nonushta tanlang.'),
  ('543206e3-a734-4c0f-89e0-a5bb0b8f6100', 'Qulaylik izlab 🍼', 'Farzandingiz mustaqil ichishi uchun eng yaxshi to‘kilmaydigan ichimlik idishini izlayapsizmi? Tavsiya etilgan mahsulotlar bo‘limida onalarga eng ko‘p yoqqan variantlarni ko‘ring.'),
  ('70ce55d5-f110-4637-a672-3efae4b7e852', 'Siz uddalaysiz! 💪', 'Kuningiz og‘ir o‘tdimi? Kayfiyat kundaligida ichki ovozingizga quloq tuting. Unutmang, bu shunchaki og‘ir kun, yomon hayot emas.'),
  ('787e9318-ea30-497d-9a1a-d3de64060a9d', 'Ovqatlanish hisoboti 📊', 'Farzandingizning bugungi ovqatlanishini Ovqatlanishni kuzatish vositasiga kiriting. Qani, bugun u kerakli vitaminlarni to‘liq ola bildimi?'),
  ('15793f9f-2b07-4de4-817b-a555822e7e8e', 'Kunning mo‘jizasi 🖼️', '520-kunga o‘zgacha ruh bag‘ishlang! Eng qadrli va kulgili suratlarni Chaqaloq albomiga yuklang va yillar o‘tib, ularni tabassum bilan eslang.'),
  ('58bde9b3-f42d-49ca-ae5b-48563d307555', 'Rivojlanish sakrashi? 📈', 'Ko‘p yig‘layaptimi yoki uyqusi buzildimi? Anacan AI bilan maslahatlashib, bu 17-oydagi rivojlanish sakrashi haftasi ekanini aniqlang.'),
  ('7771d800-de2f-41eb-8bd6-431add8986fe', 'Tinchlantiruvchi odat 🌙', 'Ajoyib kunning yakuni. Uyqu taymerini ishga tushiring, Oq shovqinlardan alla tanlang va kunning sokin yakunidan zavqlaning.'),
  ('b9d3a084-eae2-4a4a-af8c-e99d02752f66', 'Toza havo izlab 🌳', 'Uyda zerikdingizmi? Onalar uchun qulay joylar xaritasini oching va chaqalog‘ingiz bilan bemalol sayr qilishingiz mumkin bo‘lgan yangi bog‘ni kashf eting.'),
  ('c7d9bc7f-54a9-4f50-9876-80c78adff647', 'Uyqu vaqti keldi ⏱️', 'Uni uxlatishni boshlayapsizmi? Uyqu taymerini yoqing, rejimga qay darajada amal qilayotganingizni qayd eting va uyqu me’yorini tahlil qiling.'),
  ('e064d0bf-455a-4252-9305-e3585f5b88ac', 'Ertalab ishtahasi qanday? 🥣', 'Kunni sog‘lom boshlash muhim! Ovqatlanishni nazorat qilish vositasi yordamida bugungi vitaminlarga bo‘lgan ehtiyojni hisoblang va menyuni rejalashtiring.'),
  ('0d268555-6803-4b45-adab-7558434a3d7b', 'Ertalabki odat 💩', 'Kunning birinchi tagligini almashtirdingizmi? Najasning rangi va quyuqligi ichaklar salomatligi haqida ma’lumot beradi. Darhol taglik kuzatuvchisiga qayd eting!'),
  ('7d0a17bf-475f-48d2-9838-14918053b021', 'Ayollar uchun quvvat 🥗', 'Kundalik yugur-yugurlar charchatadi. O‘zingizni unutmang! Ayollar uchun foydali retseptlardan bir zumda quvvat beradigan mazali salat tayyorlang.'),
  ('b2894838-9e87-4d9f-80b1-63a311667ac3', 'Oq shovqin sehri 🌧️', 'Kun juda serharakat o‘tdimi? Xonada Oq shovqinlardan yomg‘ir ovozini yoqing — chaqalog‘ingiz osongina uxlab qolsin, siz esa biroz yengil nafas oling.'),
  ('0b41a1b3-ce5c-4804-b352-c95cc9725120', 'Kunning eng shirin lahzasi 📸', 'Bugun noodatiy va kulgili harakat qildimi? Chaqaloq fotosessiyasidagi quvnoq ramkalar yordamida o‘sha lahzani muhrlab, uni bir umrlik xotiraga aylantiring.'),
  ('136efb64-ddf1-465d-be06-c1f4f0ca13f2', 'O‘zi ovqatlanishni xohlayapti! 🥦', 'Mustaqil bo‘lishga intilyaptimi? Qo‘shimcha ovqatni boshlagan chaqaloqlar uchun Retseptlardan ushlash oson va to‘kilmaydigan mazali porsiyalarni tanlang.'),
  ('37e233ca-794d-4595-8c1d-115d93279302', 'Qaysarlikni yengish 🤖', 'Hamma narsaga «yo‘q» deyaptimi? Bu davrdagi injiqliklarni qanday boshqarishni bilmasangiz, darhol Anacan AI bilan maslahatlashing.'),
  ('256bddeb-107b-434f-9688-0c6670394bc8', 'Kiyimlar torayib qoldimi? 📏', 'Farzandingiz birdan bo‘y cho‘zganini sezyapsizmi? Vazn kuzatuvchisiga yangi ko‘rsatkichlarni kiriting va sog‘lom o‘sish grafigini ko‘ring.'),
  ('ac852fa3-348f-43fe-9321-7b4e3e9f3af1', 'Ovqatlanish taymeri ⏱️', 'Ovqatlanish qancha vaqt oladi? Ovqatlanish taymerini ishga tushiring va ovqat to‘liq hazm bo‘lishi uchun tartibni nazorat qiling.'),
  ('f78fdccc-68a3-4827-b309-2accfb39bff1', 'Foydali mutolaa 📖', 'Bola uxlab qoldi, siz-chi, nima qilyapsiz? Onalik borasidagi bilimingizni oshirish uchun Bloglar bo‘limimizdagi eng yangi maqolalarni o‘qing.'),
  ('0a2bf8ce-6e82-41df-9345-19718f7bde4c', 'Ideal suv idishini izlash 🥤', 'Suv to‘kilmaydigan va qulay idish qidiryapsizmi? Tavsiya etilgan mahsulotlar bo‘limida onalar eng ko‘p sinab ko‘rgan mahsulotlar bilan tanishing.'),
  ('12fa87ff-96f2-48c2-a70c-da7757524f9b', 'Qahva tanaffusi ☕', 'Bugun uydan chiqishni xohlaysizmi? Onalar uchun qulay joylar orasidan bolalar burchagi bor kafeni topib, o‘zingizga vaqt ajrating.'),
  ('5bd8188b-93fc-435a-8a33-b488c4ecc902', 'Hissiy yengillik 📝', 'Bugun hammasi reja bo‘yicha ketmadimi? O‘zingizni ayblamang. Ichingizdagi kechinmalarni Kayfiyat kundaligiga yozib, fikringizni yengillashtiring.'),
  ('30a82706-c2b4-4804-8bf8-50b827b59af2', 'Uyqu me’yorini tekshiramiz 😴', 'Kechasi qanday uxladi? Uyqu taymeridagi qaydlarni ko‘rib, chaqalog‘ingiz kunlik uyqu me’yorini bajargan-bajarmaganini tahlil qiling.'),
  ('63599f1b-cfac-43fe-af30-fa096e5c9039', 'Sizni nima tashvishga solmoqda? 🤖', 'Farzandingizning rivojlanishi haqida xavotirlaringiz bormi? Anacan AI ekspert yordamchimizga yozib, ilmiy asoslangan javoblar oling va ko‘nglingizni xotirjam qiling.'),
  ('c29b8ee7-5a3e-484e-b3fb-fba482038bb2', 'Har taomda o‘zgacha ta’m 🍲', '“Bugun nima pishirsam ekan?” degan tashvish endi yo‘q. Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limida rang-barang va foydali menyular mavjud.'),
  ('0c8639eb-e97c-4e44-a8d2-900ea16527d9', 'Kunlik ajralmalar hisoboti 💩', 'Ertalab taglikni almashtirganda qayd etishni unutmang! Kun davomida taglik almashtirishlarni kuzatib borish bolaning yetarli miqdorda suyuqlik olayotganini ko‘rsatadi.'),
  ('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364', 'Sizning ham ehtiyojlaringiz bor 🥗', 'Quvvatingiz tugab boryaptimi? Ayollar uchun foydali retseptlardan foydalanib, vitaminlarga boy smuzi tayyorlang. Siz kuchli bo‘lishingiz kerak!'),
  ('d0842140-92ca-41c9-be61-ea76700b043c', 'Unutilmas xotiralar 🖼️', 'Kelajakda bugungi shirin qiliqlarini ko‘rib kulish uchun uning eng chiroyli suratlarini Chaqaloq albomiga yuklang va xavfsiz joyda saqlang.'),
  ('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e', 'Bugun nimalarni his qildingiz? 💖', 'Juda charchagan bo‘lsangiz ham, uni hidlaganingizda barcha charchoq unutiladi, shundaymi? Bugungi his-tuyg‘ularingizni Kayfiyat kundaligiga yozib qo‘ying va dam oling.'),
  ('965bee4a-5d90-4c53-aa89-40a47df609d3', 'Taymer bilan ovqatlanish ⏱️', 'Ovqat stolida juda uzoq o‘tiradimi? Ovqatlanish taymerini yoqing, me’yorga rioya qiling va ishtahasizlikning oldini oling.'),
  ('ff2d08b5-7a14-4db2-985e-1998a959811b', 'Ertalabki o‘yinlar 🧩', 'Birgalikda o‘rganamiz! 17.5 oylik bolalarning aqliy rivojlanishini qo‘llab-quvvatlaydigan o‘yinlar haqidagi Bloglar bo‘limidagi maqolamizni albatta o‘qing.'),
  ('276fc8e9-ee3f-4392-a41a-de859475f6f7', '“Sizni yaxshi ko‘raman” quchog‘i 🫂', 'Kutilmaganda yoningizga kelib, bo‘yningizdan quchadimi yoki yuzingizni silaydimi? U endi sevgisini jismoniy harakatlar orqali ko‘rsatmoqda. Bu ondan zavqlaning.'),
  ('6d6ea5dd-3811-42ae-a92c-4f0473fafb88', 'Otadan keladigan taskin 🫂', 'Chaqaloq tunda uyg‘onganida bir safar siz, keyingi safar esa turmush o‘rtog‘ingiz tursin. Yukni bir jamoa sifatida teng bo‘lib oling.'),
  ('87b2db95-d589-400c-8cce-c78da82f0fee', 'Allergiyaga shubha 🤖', 'Yangi ovqat berdingiz va uning yonoqlarida qizarish paydo bo‘lganini ko‘rdingizmi? Vahimaga tushishdan oldin ilk qadamlar haqida Anacan AI’dan so‘rang.'),
  ('85d64887-6099-4720-8a44-11c6766f10bb', 'Uyda siqilyapsizmi?☕', 'Onalar uchun qulay maskanlar orasidan siz toza havodan bahramand bo‘ladigan, chaqaloq esa maroqli vaqt o‘tkazadigan eng yaqin kafeni toping.'),
  ('aa709e76-dc89-4447-b36a-69ce62fbdfe6', 'Ovoz ohangingizni tushunadi 🗣️', 'Jiddiy ohangda «yo‘q» desangiz, to‘xtab sizga qaraydimi? U endi his-tuyg‘ular va taqiqlarni to‘liq anglaydi. Chegaralarni saqlang.'),
  ('d09c606d-f7bf-4df1-900d-b7cc38d34313', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch muhitda ajraladi.'),
  ('7c968d48-84d9-4e6e-9f71-708f424d13fc', 'Uyqu me’yori ⏱️', 'Uxlash vaqti! Uyqu taymerini faollashtiring. Kundalik uyqu me’yoriga rioya qilayotganiga ishonch hosil qilish uchun jadvalni tahlil qiling.'),
  ('83a23b90-6573-48f0-bd8e-9924821c611c', 'O‘zingizga g‘amxo‘rlik qiling 🥗', 'Bolaning ortidan yugurib charchadingizmi? Ayollar uchun foydali retseptlar orasidan darhol quvvat beradigan mazali salatni kashf eting.'),
  ('e949f663-9f46-4fb4-8e24-07f0556f19ea', 'Ertalabki tozalik 🧻', 'Kunning ilk taglik almashtirishi qanday o‘tdi? Najas haqidagi ma’lumotlarni ilovaga kiritib, uning oshqozon-ichak tizimi faoliyatini osonlik bilan kuzating.'),
  ('23c1e329-cee4-4d43-89e7-04f3883f2a24', 'Vitaminlar manbai 🥦', 'Oziqlanishni nazorat qilish vositasi yordamida bugungi menyuni tekshiring. Yetishmayotgan vitaminlarni to‘ldirish uchun Chaqaloq retseptlarida rang-barang porsiyalar sizni kutmoqda!'),
  ('2450b85b-f956-4dd3-b9ad-11b269818238', 'Juda qaysarmi? 🤖', 'Og‘zidan «yo‘q» so‘zi tushmayaptimi? 17.5 oylik bolaning injiqliklarini boshqarish uchun Anacan AI yordamchimizdan ilmiy asoslangan psixologik maslahatlar oling.'),
  ('91b9e4eb-ca6a-4a90-94bc-2abf486852f9', 'Osoyishta oqshom 🌊', 'Xonada sokin muhit yaratish vaqti keldi. Oq shovqinlardan okean to‘lqinlari ovozini yoqing va uning asab tizimiga chuqur uyquga ketishda yordam bering.'),
  ('60f75637-7bb2-4f09-8e04-1616cc3f6b3a', 'Ovqatlanish sinovi ⏱️', 'Ovqatlanish juda cho‘zilib ketyaptimi? Oziqlanish taymerini yoqing, me’yorga rioya qiling va ishtahasizlik sabablarini tahlil qiling.'),
  ('8773c2dd-9938-4a61-a038-72940b1c0339', 'Kundalik terapiya 📝', 'Onalik ba’zan hissiyotlarga to‘la sayohatga o‘xshaydi. Kayfiyat kundaligini oching, bugungi charchog‘ingizni qog‘ozga tushirib, yengil torting.'),
  ('da198266-6b56-4801-ac35-87e201ed0cda', 'Qahva vaqti keldi ☕', 'Uyning to‘rt devoridan zerikdingizmi? Onalar uchun qulay joylar orasidan bolangiz bilan bemalol borishingiz mumkin bo‘lgan kafeni toping va o‘zingizni xursand qiling.'),
  ('317a6a9f-9ea0-4356-ac6b-713b806d7195', 'Shirin xotiralar 📸', 'Bugun qilgan eng kulgili harakatini Chaqaloq albomiga qo‘shing. Yillar o‘tib, bu suratlarni tomosha qilib rosa kulasiz.'),
  ('c56a5aef-ad55-4a58-b85d-04ee040e2457', 'To‘kilmaydigan idish 🥤', 'Yugurib yurib suv ichishni yaxshi ko‘radi-yu, lekin kiyimlarini ho‘l qiladimi? Tavsiya etilgan mahsulotlar bo‘limida onalar tanlagan eng qulay suv idishlarini ko‘rib chiqing.'),
  ('e0699b25-a664-453e-b3a5-a31644bae458', 'Kiyimlar kichrayib qolyapti! 📏', 'Kichkintoyning yenglari yana kalta bo‘lib qoldimi? Vazn kuzatuvchisiga yangi ko‘rsatkichlarni kiriting va bo‘yi hamda vazni o‘sishini rivojlanish grafigida faxr bilan kuzating.'),
  ('281783cf-f4b1-478b-9c23-4859307143e4', 'Mustaqil o‘yin vaqti 🧸', 'Endi u 10-15 daqiqa davomida o‘yinchoqlari bilan mustaqil shug‘ullana oladi. Bu diqqatini jamlash vaqti uzayayotganini anglatadi. Sokinlikdan zavqlaning.'),
  ('64f775c3-f09d-4993-a954-437681ccf730', 'Tashqaridagi ob-havo noaniqmi? ⛅', 'Ob-havo va kiyim vositasi derazadan sezilmaydigan shamol tezligini ko‘rsatib, mos kiyimlar to‘plamini bir zumda tavsiya qiladi.'),
  ('6ca7a3a7-3202-4bdf-87de-b43d04388374', 'Massaj vaqti 💆‍♂️', 'Bola uxlagach, kun davomida yig‘ilgan stressdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz bir jamoasiz!'),
  ('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7', 'Tovushlarni nazorat qilish 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat eng nozik vaqtdir. Tovush o‘lchagich yordamida atrof-muhitni tekshiring va to‘satdan chiqadigan shovqinlardan ehtiyot bo‘ling.'),
  ('cee8912e-bf87-4d52-b0d0-309e7583f3e5', 'Tezkor pediatr 🤖', '18 oylik bolaning nutq rivoji sizni tashvishlantiryaptimi? Anacan AI’dan so‘rab, bu yoshda qaysi so‘zlarni aytishi me’yor ekanini bilib oling.'),
  ('dd84435f-c5e3-4339-9062-61f9c8648898', 'Oddiy topshiriqlarni bajaradi 🧸', 'Oyoq kiyimini olib kel desangiz, rostdan ham borib olib keladimi? Uning so‘z boyligi va tushunish qobiliyati ayni rivojlanish cho‘qqisida! Uni o‘yinlarga ko‘proq jalb qiling.'),
  ('52450380-67b2-4414-9193-af2b18f7264a', 'O‘zingizni maqtang 👏', 'Xonaning tartibsizligiga emas, bugun uning qanchalik baxtli ekaniga qarang. Siz hech bir kitob o‘rgata olmaydigan darajada ajoyib onasiz.'),
  ('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d', 'Taymer yordamida uyqu tahlili ⏱️', 'Kunduzgi uyqusi qisqaryaptimi? Uyqu taymerini ishga tushiring va shu haftadagi jadvalni tahlil qilib, kechki uyqu vaqtini qayta sozlang.'),
  ('fda065c2-2893-4c1e-858b-19c095a29529', 'Bir-biringizni qo‘llab-quvvatlang! 💖', 'Og‘ir kundan so‘ng turmush o‘rtog‘ingiz bilan yuzma-yuz o‘tirib, dardlashing. Bir-biringizni qo‘llab-quvvatlash yukni teng yengillashtiradi.'),
  ('4f770f32-235d-4481-acc9-8a3353f11910', 'Sizni nima o‘ylantiryapti? 🤔', 'Birdan ovqat yemay qo‘ydimi? Onalik haqidagi istalgan savolingizni Anacan AI’ga yo‘llang va darhol ekspert aniqligidagi javobni oling.'),
  ('996b9423-cc50-4ec2-bbf6-02866083bb10', 'Oson uyquga ketish 🎶', 'Faol kashfiyotlarga boy kundan keyin uxlay olmayaptimi? Oq shovqinlardan alla ovozini tanlang va xonada sehrli sokinlik yarating.'),
  ('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b', 'Tabiatni kashf etish 🍂', 'Toza havo ikkingizga ham foydali. Onalar uchun qulay joylardan yangi bog‘ toping, chaqaloq erkin yugurib, energiyasini sarflasin.'),
  ('19f1aa58-50a6-4acf-b375-1d03850cfcb6', 'Ichki ovozingiz 💖', 'Mukammal ona bo‘lishingiz shart emas, siz uning uchun eng yaxshi onasiz. Kayfiyat kundaligiga bugungi his-tuyg‘ularingizni yozib, yengil torting.'),
  ('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98', 'Mustaqil ovqatlanish sinovi ⏱️', 'O‘zi ovqatlanishga urinyaptimi? Atrofni iflos qilishiga ko‘z yuming! Ovqatlanish taymerini ishga tushirib, bu mustaqillik qancha vaqt olishini tahlil qiling.'),
  ('f869363f-52a1-4240-a759-b2b999d347e4', 'Foydali shirinlik 🍪', 'Do‘kondagi shirinliklarga hojat yo‘q. Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlardan oson, shakarsiz va mazali pechenye tayyorlang.'),
  ('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b', 'Tushlikdagi ishtaha 🥣', 'Farzandingiz bugun yetarlicha oqsil iste''mol qildimi? Ovqatlanishni kuzatish vositasiga yeguliklarni kiritib, kunlik me''yorni bajarganingizga ishonch hosil qiling.'),
  ('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b', 'Aqliy rivojlanishdagi sakrash 🧠', 'Chaqalog''ingizning miyasida nimalar yuz bermoqda? Bloglar bo''limida 17-18 oylik bolalarning bilish qobiliyati rivojlanishi haqidagi eng so''nggi maqolani o''qing.'),
  ('87dc449d-a56d-419b-bdab-000fd5ed38fd', 'Uyqu jadvali ⏱️', 'Uyg''onish vaqtlari o''zgardimi? Uyqu taymeri statistikasini ko''rib, kunduzgi va tungi uyqu o''rtasidagi muvozanatni aniq tahlil qiling.'),
  ('4c6d197d-5cde-42e9-b88b-05a62b37e397', 'Ertalabki hisobot 💩', 'Salomatlikning dastlabki ko''rsatkichi — hazm qilish tizimi. Taglikni almashtirish paytida najas haqidagi qaydlarni ilovaga kiritib, kun davomidagi o''zgarishlarni kuzating.'),
  ('e59af63b-a407-459e-a6f1-a0263d9f74f5', 'Kichkina yulduz 🌟', 'Bu yoqimli tabassumni o''tkazib yubormang! Chaqaloq fotosessiyasi vositasidagi qiziqarli mavzular yordamida uning bugungi kayfiyatini suratga muhrlang.'),
  ('f71b2bf0-976d-4844-8538-db17781ce999', 'O''zingizga vaqt ajrating 🍵', 'Bola uxlab qoldi, endi tanangizni tiklash navbati sizda. Sog''lom retseptlardan foydalanib, tinchlantiruvchi giyohli choy damlang.'),
  ('91d67474-6689-4302-b69e-a9b260aedef7', 'To‘g‘ri o‘yinchoq 🧩', 'Mantiqiy fikrlashini rivojlantiradigan o‘yinchoq izlayapsizmi? Tavsiya etilgan mahsulotlar bo‘limida yoshiga mos va foydali pazllarni ko‘rib chiqing.'),
  ('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2', 'Tungi tartib 🌙', 'Har kuni bir vaqtda uxlatish odatni shakllantiradi. Uyqu taymerini yoqing, me’yorini tekshiring va oson uyquning huzurini his qiling.'),
  ('e8b020dc-c4fe-4f5b-946a-28ae84382a39', 'Sog‘lom ulg‘ayayapmiz 📈', '18-oyga oz qoldi! Rivojlanish sur’atini Vazn kuzatuvchisi vositasida tahlil qiling, bo‘yi va vazni me’yorga mosligini tekshiring.'),
  ('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17', 'Ajoyib kunning yakuni 🖼️', 'Birga tushgan eng quvnoq va samimiy suratingizni Chaqaloq albomiga qo‘shib, ushbu alohida kunni (540 kun!) abadiylashtiring.'),
  ('c1dc4453-41a2-40e6-812c-73fb934ccc70', 'Siz qahramonsiz! ✨', 'Onalik sayohatining 540-kuni! Anacan AI’ga bugungi yutug‘ingizni yozing, u kuningizni yanada go‘zal qiladigan maxsus motivatsiya bersin.'),
  ('fa1d5820-5e14-435d-81d1-df116bd7de6f', 'Oila dasturxoni 🍲', 'U endi siz bilan bir xil taomlarni yeyishi mumkin. Ovqatlanishni nazorat qilish vositasi yordamida birga iste’mol qiladigan taomlaringizning oziqaviy qiymatini osongina hisoblang.'),
  ('ae531928-8e01-4e71-961a-63a517eaee5a', 'Chuqur uyquga o‘tish 🌙', 'Uyqu taymerini yoqing. Agar tunda uyg‘onishlar ko‘paysa, Oq shovqinlardagi okean to‘lqinlari ovozi bilan uning asab tizimini tinchlantiring.'),
  ('bacdcc71-8211-4dd5-b3af-c5af34fb468a', 'Tonggi syurpriz 💩', 'Kunning birinchi tagligini almashtirganda qayd eting! Bu o‘sib borayotgan chaqaloqning ovqat hazm qilish tizimi va suyuqlik iste’molini kuzatishning eng yaxshi usulidir.'),
  ('e207d666-c361-4203-8076-7ba835d4f015', 'Qoshiq qo‘lidan tushmayaptimi? 🥄', 'Ovqatlanish taymerini yoqing. Mustaqil ovqatlanish urinishlari qancha davom etishini tahlil qiling va kunlik ovqatlanish me’yorini ko‘rib chiqing.'),
  ('35587de2-b62b-435c-aca4-01e72314423a', 'Ichingizdagini yozib tashlang 📝', 'Har bir kun ham mukammal bo‘lavermaydi va bu normal holat. Kayfiyat kundaligiga bugungi his-tuyg‘ularingizni yozing, stressdan xalos bo‘lib, xotirjam dam oling.'),
  ('6dca6700-52a0-4818-812b-80dcc5c42de9', 'Rasman 1.5 yosh! 🎈', 'Farzandingiz bu oylarda tez sur’atda ulg‘ayadi. Rivojlanish kuzatuvchisiga so‘nggi ko‘rsatkichlarni kiriting va rivojlanish grafigiga faxr bilan nazar soling.'),
  ('da88924f-9b7a-4cc5-9b9e-429e9d903edd', 'O‘zingizni mukofotlang ☕', '18 oylik onalik aslo oson emas! Onalar uchun qulay joylar xaritamizdan shinam kafe toping va o‘zingizga issiq qahva buyurtma qiling.'),
  ('6b77a02d-8882-4aed-be91-5f8ce3841671', 'Yugurishga tayyormisiz? 👟', 'Ilk ishonchli yugurishlar uchun to‘g‘ri poyabzal juda muhim! Tavsiya etilgan mahsulotlar bo‘limida onalar eng ko‘p yoqtirgan ortopedik modellarni ko‘rib chiqing.'),
  ('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e', 'Shirin lahzalar 📸', 'Yugurayotib yiqilib, kulib yubordimi? Bu yoqimli lahzani darhol Chaqaloq albomiga qo‘shing va kelajak uchun rang-barang, bir umrlik xotiraga aylantiring.'),
  ('e2aefd08-9263-41a3-87d4-c2d0378c7526', 'Temir zaxirasi qanday? 🥩', 'Ovqatlanishni nazorat qilish vositasi yordamida bugun u yetarli miqdorda temir olganini tekshiring. Yetishmovchilik bo‘lsa, Chaqaloq retseptlarini ko‘rib chiqing.'),
  ('48983c78-1769-4320-a7cf-ba470eef1415', 'Maxsus ertak 🪄', 'Aqlli ertaklarda bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: 1.5 yoshli kashfiyotchining sarguzashtlari.'),
  ('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0', 'O‘sishda davom etamiz! 🌟', 'U endi 18 oylikdan katta! Mustaqil yuradigan, his-tuyg‘ularini namoyon etadigan, qaysar, ammo mehrga to‘la bolakay bilan yangi davr boshlanmoqda!'),
  ('cdca9fee-71e1-4e46-aea7-41734d6fa68a', '18 oylikdagi uyqu regressiyasimi? 🥱', 'Uxlashga qarshilik qilyaptimi yoki kechasi uyg‘onyaptimi? Bu aynan shu davrga xos mashhur uyqu regressiyasidir. Ushbu biologik jarayon haqida Anacan AI’dan ilmiy ma’lumot oling.'),
  ('1bf2c33f-3711-4208-8da6-0a931502b566', 'Mutlaq qorong‘ilik 🌙', 'Uxlashga qarshilik qilyaptimi? Xonadagi kichkina yorug‘lik ham uning diqqatini chalg‘itadi. Ekranlarni o‘chiring, xonani butunlay qorong‘i qilib, melatonin ajralishini tezlashtiring.'),
  ('5f000b16-6031-438b-92a6-3ea1d69ae68b', 'Xotirangiz yana pand berdimi? 🛒', 'Taglik tugadimi yoki qatiqmi? Miyangizni zo‘riqtirmang, darhol Xaridlar ro‘yxatiga qo‘shing, turmush o‘rtog‘ingiz ishdan qaytayotganda olib kelsin.'),
  ('8593e3b3-5794-49a0-a5ef-d04af1bd53a7', 'Kitoblardagi detallar 📖', 'Kitobni varaqlab, rasmdagi eng kichik detalni (masalan, kichkina qushni) barmog‘i bilan ko‘rsatyaptimi? Rivojlanish kuzatuvchisiga bu kognitiv diqqatni qayd eting. Ko‘rish xotirasi a’lo darajada ishlayapti!'),
  ('5df90283-8938-4f2c-bc5d-95fad0d0249f', 'Uyqu rejimini tekshiramiz ⏱️', 'Kechqurun uxlashni istamayaptimi? Uyqu taymeri grafigini tahlil qiling. Balki kunduzgi uyqusini biroz qisqartirish kerakdir.'),
  ('eb685812-a20b-4dfa-8dcd-a8c0865f1a25', 'Onaning energiyasi 🔋', 'O‘zingizni unutmang! Retseptlardan nonushta uchun tez tayyorlanadigan, oqsilga boy mazali taomni tanlang.'),
  ('f80fa225-e7f6-4b7d-a7da-b651f5688ba0', '“Yo‘q!” injiqliklari 🛑', 'Hamma narsaga qarshilik qilyaptimi? 1.5 yoshdagi qaysarlik haqida Anacan AI yordamchimiz bilan maslahatlashib, psixologik ko‘mak va yechim toping.'),
  ('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03', '“O‘zim!” degan qaysarlik 🛑', 'Hamma narsani, hatto xavfli buyumlarni ham o‘zi olishni xohlaydi. Qo‘lidan olib qo‘ysangiz, ko‘tariladigan to‘fonga tayyor turing. Taqiqlash o‘rniga, uning diqqatini qiziqroq narsaga yo‘naltirib ko‘ring.'),
  ('d6508b29-e914-4995-93c3-58c73e271159', 'Massaj va sukunat 💆‍♀️', 'Kun bo‘yi yugurib, belingiz og‘rib ketdimi? Farzandingiz uxlagach, juftingizdan yelkangizni 10 daqiqa massaj qilib berishini so‘rang. Siz bunga loyiqsiz!'),
  ('dd068a2e-5d54-49f1-be6d-02db7c690974', 'Yugurish yo‘lagidasiz 🏃‍♂️', 'U xonadan xonaga tez yugurib, to‘xtashni bilmayaptimi? Shu kunlarda uning tik turgandagi muvozanati to‘liq shakllanmoqda. Uydagi mayda xavf manbalarini bartaraf etib, bu jo‘shqin damlarni chetdan kuzating.'),
  ('d14775e1-8a41-4689-87c3-351bcaa01c87', 'Dadaning maydonchasi 👨‍👧', 'Sabringiz tugadimi? Xona eshigini yoping va bolani dadasi bilan yolg‘iz qoldiring. Bugun kechqurun uydagi o‘yin maydonchasiga u rahbarlik qilsin.'),
  ('e1121d1f-a680-4fb9-9a1f-6792cb16e172', 'Meva bilan adovat 🍎', 'Kecha yaxshi ko‘rgan olmasini bugun yerga otyaptimi? Ovqat tanlash bu yoshdagi eng odatiy muammolardan biridir. Internetda adashib yurmasdan, Sog‘lom retseptlardagi mevalarni qiziqarli tortish usullarini ko‘ring.'),
  ('ef76ecee-5471-407a-a72c-9593be1406af', 'Suhbat uzoq davom etadi 🗣️', 'Ertalab uyg‘onishi bilan o‘z tilida uzoq vaqt nimalarnidir gapiradimi? Uning nutq markazi jadal rivojlanmoqda. Uni jiddiy tinglang va “Rostdanmi?”, “Keyin nima bo‘ldi?” deb javob bering.'),
  ('bd224607-0812-4b81-8b5d-af59d7d7cc10', 'Vitaminlar bombasi 🥗', 'Onaning quvvati tugamasligi kerak! Ayollar uchun foydali retseptlardan tezda energiya beradigan mazali smuzi tayyorlang.'),
  ('c9435c7a-e56d-449f-9eb8-fae0dc263176', 'Uyquga tayyorgarlik marosimi 🌙', 'Uyqu taymerini yoqing va xonani qorong‘ilating. Grafikni tahlil qilib, chaqaloqni har oqshom bir vaqtda uxlatish odatini osonlik bilan shakllantiring.'),
  ('ffe1377d-426e-4c3f-a06d-3551b2ee446b', 'Aqlni rivojlantiruvchi o‘yinchoqlar 🧩', '18 oy — mantiqiy o‘yinlar uchun ayni muddao. Tavsiya etilgan mahsulotlar bo‘limidan yoshiga mos pazl va kubiklarni topib, uning zehnini charxlang.'),
  ('10d89b1a-052c-42d7-9604-a8aa080e3159', 'Oila dasturxonining fayzi 🍲', 'Endi u siz bilan bir xil taomlarni bemalol yeyishi mumkin! Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan butun oila uchun mos va foydali kechki ovqatni tanlang.'),
  ('25077620-39e7-49c9-abd7-7ee3d4c9f4a5', 'Ichak faoliyatini tekshirish ⏱️', 'Taglik kuzatuvchisida kun davomida yuz bergan o‘zgarishlarni qayd etib, chaqaloq yetarli miqdorda suyuqlik va kletchatka olayotganini osonlik bilan tahlil qiling.'),
  ('94fb4891-ca2e-4e41-b663-ea23a832df89', 'Yomg‘ir ovozining oromi 🌧️', 'Faol kun miyani charchatishi mumkin. Oq shovqinlar bo‘limidan yomg‘ir ovozini yoqib, xonada tinchlantiruvchi va uyqu keltiruvchi mukammal fon yarating.'),
  ('02d8aef9-6d63-4748-9f41-c063ee842eb2', 'Siz uddalaysiz! 💖', 'Charchaganingizni his qilganingizda Kayfiyat kundaligini oching. U yerga shunchaki Men hammasini uddalayapman deb yozing va dam oling.'),
  ('04fca8dd-97bb-4af2-93b5-030f318cd3da', 'Tabiatni kashf etish 🌳', 'Uy devorlari unga torlik qilyaptimi? Onalar uchun qulay joylar orasidan keng va xavfsiz bog‘ topib, unga energiyasini sarflashga yordam bering.'),
  ('7306940e-101e-4de4-af72-da4ab6736ad8', 'Ovqatlanish taymeri ⏱️', 'Ovqat bilan ko‘p o‘ynaydimi? Ovqatlanish taymerini yoqing hamda dasturxon atrofida o‘tkazilgan vaqt me’yorga mosligini va uning ishtahasini tahlil qiling.'),
  ('07b5d33a-c674-4dcc-a023-81e3746cb054', 'Mantiqiy o‘yinlar 🧱', '4-5 ta kubikni ustma-ust qo‘yib, minora quryaptimi? Rivojlanish kuzatuvchisida bu motorika yutug‘ini qayd eting! Uning bu kichik muhandislik urinishlarini olqishlashni unutmang.'),
  ('be5acfb3-03f0-4bea-9e14-40b38bca8262', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Tunda uyg‘onishlarning barcha yukini yolg‘iz o‘zingiz ko‘tarmang. Turmush o‘rtog‘ingizni ham uyg‘oting: jamoa bo‘lish mas’uliyatni teng taqsimlash demakdir. Bu kecha chaqaloqni tinchlantirish navbati uniki.'),
  ('fa9c7680-afc6-4095-9ec3-d56ad432d989', 'Bog‘mi yoki uymi? ⛅', 'Tashqariga chiqmoqchisiz, ammo ob-havo o‘zgaruvchan. Ob-havo va kiyim yordamchisi sizga nafaqat haroratni, balki shamol o‘tkazmaydigan qanday kiyim kiydirish kerakligini ham aytsin.'),
  ('22efa7bf-186e-41c7-b46c-b75ce17b0a09', 'Ertalabki tozalik 💧', 'Kunning birinchi tagligini almashtirdingizmi? Hojat haqidagi ma’lumotlarni ilovaga kiritib, chaqaloq yetarli miqdorda suyuqlik olayotganini osongina kuzating.'),
  ('37e7b0b1-141f-488d-99c8-a87bde73955f', 'Ovqatlanishdagi injiqliklar 🥣', 'Ovqat yeyishdan bosh tortyaptimi? Majburlab yedirish o‘rniga, likopchasiga turli rangdagi sabzavotlarni solib, qiziqishini uyg‘oting. Foydali retseptlardan yangi g‘oyalar oling.'),
  ('5ae1647c-ec81-4db7-838c-66f57619dd06', 'Shovqinni nazorat qilish 🤫', 'Uyquga tayyorlanayotganda xonadagi shovqin darajasini Ovoz o‘lchagich yordamida nazorat qiling. Tunda bo‘linadigan uyqu uning rivojlanishiga ham, sizning ertalabki kayfiyatingizga ham salbiy ta’sir qiladi.'),
  ('2e177a88-e995-4df3-ae19-8a1044979006', 'Musiqali oqshomlar 🎶', 'Kechga yaqin boshlanadigan injiqliklarni bartaraf etishning eng oson yo‘li — uning sevimli qo‘shig‘ini qo‘yib, bag‘ringizga bosgancha birga raqsga tushish.'),
  ('82b5cb21-ea7e-4957-9166-81471c0b098a', 'Nega bunday qilyapti? 🤖', 'Sababsiz g‘azab xurujlari (tantrum) boshlandimi? Anacan AI bilan darhol maslahatlashib, mutaxassislarning psixologik yondashuvlarini o‘rganing.'),
  ('8aa141ab-420e-4a45-9eba-7dddd2430cb1', 'Shakarsiz quvvat 🍌', 'Tushdan keyin shirinlik xohlayaptimi? Chaqaloqlar uchun retseptlardagi banan va suli qo‘shilgan foydali tamaddilar bilan sog‘lom ovqatlanish me’yorini saqlang.'),
  ('b62665c0-5b12-4c5d-adfa-7b34000204cf', 'Kulgi sadolari 📸', 'Bugun sizni eng ko‘p kuldirgan o‘sha yoqimli lahzani eslang va uni albatta Chaqaloq albomiga kichik video yoki surat sifatida qo‘shing.'),
  ('e16b58bb-af8f-43a3-bf1f-c1d132a221a5', 'Vahimaga tushmang 🤖', 'Farzandingizda g‘alati xatti-harakatni payqadingizmi? Kech bo‘lishini kutmay, darhol Anacan AI’ga yozing va xavotiringizni bartaraf eting.'),
  ('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4', 'Kalsiyga ehtiyoj 🦷', 'Ovqatlanishni nazorat qilish vositasi yordamida farzandingiz bugun qancha kalsiy olganini hisoblang. Suyaklar va tishlar uchun sut mahsulotlari me’yoriga e’tibor bering.'),
  ('72bb2391-6fc4-4ef8-9352-3ae963d61f5b', 'Endi navbat sizda 🥗', 'Bolangiz uxladimi? Unda oshxonaga yo‘l oling! Ayollar uchun foydali retseptlar orasidan bir zumda quvvat beradigan, oqsilga boy salatni toping.'),
  ('7c893844-8335-47b4-baf7-b21329be4554', 'Ko‘nglingizdagini yozing 📝', 'Juda shovqin-suronli kun bo‘ldimi? Kayfiyat kundaligiga his-tuyg‘ularingizni yozish xayolingizdagi yukni yengillashtiradi.'),
  ('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a', 'Kiyimlar yana kichrayib qoldimi? 📏', '18 oydan keyin bo‘y o‘sishida keskin sakrash kutiladi. Vazn kuzatuvchisiga yangi ko‘rsatkichlarni kiriting va rivojlanish egri chizig‘iga faxr bilan qarang.'),
  ('2d802010-e9c4-4370-b595-862f19214f3d', 'Kalsiy zaxirasi 🧀', 'Tishlar va suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi orqali bugungi sut mahsulotlari me’yoriga rioya qilganingizni tekshiring.'),
  ('739069ab-a4c7-4cc9-ae84-572e67836bd2', 'Kunning eng shirin lahzasi 🖼️', 'Bugun sizni eng ko‘p kuldirgan o‘sha harakatini eslaysizmi? Uni hoziroq Chaqaloq albomiga yuklab, kelajak uchun saqlab qo‘ying.'),
  ('faac9718-e68e-455d-90e4-e34b7b38a24e', 'Aql rivoji 🧠', 'Bloglar bo‘limidagi 1.5 yoshli bolalar miyasida kechadigan ajoyib jarayonlar haqidagi yangi maqolani albatta o‘qing.'),
  ('2155f722-dd8c-49ec-a515-ecee85476474', 'Ertalabki nazorat 🧻', 'Kunning birinchi tagligini ilovaga qayd qildingizmi? Ajralmaning rangi va quyuqligi bola yetarli miqdorda suyuqlik olayotganini aniq ko‘rsatadi.'),
  ('67ef78f2-7b35-47be-a6f4-6368c3a37a84', 'Ovqatlanish stolidagi sinov ⏱️', 'Stol atrofida uzoq o‘tirib, ovqat bilan o‘ynaydimi? Ovqatlanish taymerini yoqing va ishtahasizlik sabablarini tahlil qilishni boshlang.'),
  ('d9b69a33-09da-4d7d-98e9-ac3acd553715', 'Uyqu regressiyasimi? 🤖', 'Kechasi tez-tez uyg‘onadimi? Bu o‘sish sakrashi bilan bog‘liq yoki yo‘qligini Anacan AI ekspertiga yozib, darhol bilib oling.'),
  ('283507fe-ca12-4764-a828-61d9a9f30424', 'Siz qahramonsiz 💖', 'Mukammal bo‘lishingiz shart emas. Kayfiyat kundaligiga shunchaki Men hammasini uddalayapman deb yozing va dam oling.'),
  ('290e0f59-3a24-4f74-9a01-c478f55efce5', 'Toza havodagi sarguzasht 🌳', 'Uy devorlari unga torlik qilyapti. Onalar uchun qulay joylar orasidan keng va xavfsiz bog‘ topib, ortiqcha energiyasini sarflashiga yordam bering.'),
  ('d9528425-30f7-4a4a-ac0d-053206658d00', 'Quvvatingiz tugamasin 🔋', 'Yugurib-yelib charchadingizmi? Ayollar uchun foydali retseptlar orasidan bir zumda quvvat beradigan mazali nonushtani tanlang.'),
  ('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b', 'Kunduzgi uyqu ⏱️', 'Uyqu taymerini yoqing. Kunduzgi uyqu vaqtlarini aniq belgilab, kechki uyquga o‘tishni osonlik bilan tartibga soling.'),
  ('1b9ea296-6f6b-4447-9f45-4c6548d5e543', 'Oilaviy dasturxon 🍲', 'U endi siz bilan bir xil taomlarni yeyishi mumkin. Ovqatlanishni nazorat qilish vositasi yordamida birgalikda iste’mol qiladigan taomlaringizning oziqaviy qiymatini osongina hisoblang.'),
  ('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0', 'Tinchlantiruvchi to‘lqinlar 🌊', 'Faol kashfiyotlarga boy kundan keyin uxlay olmayaptimi? Oq shovqinlar orasidan okean to‘lqinlari ovozini tanlang va xonada sehrli sokinlik yarating.'),
  ('284e490f-ef18-407e-b320-432395edf56f', 'Kerakli narsalar ro‘yxati tugamaydi 🛒', 'Shampun, taglik yoki suli yormasi tugadimi? Barchasini eslab qolishga urinmang — Xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan sinxronlashtiring.'),
  ('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd', 'Uydan chiqish vaqti ☕', 'Kundalik bir xillikdan zerikdingizmi? Onalar uchun qulay maskanlardan bolalar burchagi bor kafeni toping va bir finjon issiq qahvadan zavqlaning.'),
  ('ee049a04-c690-49d6-a1c7-d2c603be49d5', 'Ertak bilan uyquga 🪄', 'Aqlli ertaklarda maxsus ertak yarating. Farzandingizga o‘qib bering.'),
  ('46fbf80f-0604-494d-b68e-60f85488090d', 'O‘zi ovqatlanyapti! 🥣', 'Qoshiqni qo‘lidan qo‘ymayaptimi? Ovqatlanish taymerini ishga tushiring, jarayon davomiyligini kuzating va me’yoriga mosligini tekshiring.'),
  ('5174db8a-22d1-41db-af86-5a575522337a', 'Ilk rasmlar 🖍️', 'Qog‘ozga chizgilar tushira boshladimi? Zararsiz va yuviladigan bo‘yoqlarning eng yaxshi variantlarini Tavsiya etilgan mahsulotlar bo‘limidan ko‘ring.'),
  ('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b', 'Kichkina rassom 📸', 'Usti-boshi bo‘yoq bo‘lib ketdimi? Jahlingiz chiqmasin — bu kulgili lahzani Chaqaloq fotosessiyasidagi quvnoq ramkalar bilan abadiylashtiring.'),
  ('1e433a5c-ee68-4089-bf86-5ce74fde7136', 'Mantiqiy o‘yinchoqlar 🧩', '18.5 oylik davrga yaqinlashganda mantiqiy o‘yinlar ayni muddao. Tavsiya etilgan mahsulotlar bo‘limida yoshiga mos pazl va kubiklarni toping.'),
  ('9d69d283-cfae-47a2-a874-8fabcc20a7f1', 'O‘sish sur’ati 📈', 'Rivojlanish sur’atini Rivojlanishni kuzatish vositasida tahlil qiling. Bo‘yi va vazni me’yorga mosligini grafik orqali kuzating.'),
  ('a242b14e-b434-493a-ab87-b2064aedfc9e', 'Haqiqiy sarguzashtchi 📸', 'Tirmashib chiqayotganida yoki yugurib o‘ynayotganida olgan eng quvnoq suratini Chaqaloq albomiga qo‘shib, unutilmas xotiraga aylantiring.'),
  ('465d0258-9df5-4a0a-9902-79a09218dcc5', 'ROSA 19 OYLIK! 🎂', 'Tabriklaymiz! Tug‘ilganidan beri roppa-rosa 19 oy o‘tdi! Darhol Chaqaloq fotosessiyasidan maxsus stikerni tanlang va bu quvonchni Anacan hamjamiyatida ulashing!'),
  ('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4', 'Quvnoq kulgilar 📸', 'Tirmashib chiqayotganida yoki yugurib o‘ynayotganida olgan eng quvnoq suratini Chaqaloq albomiga qo‘shib, kun charchog‘ini tabassumga aylantiring.'),
  ('ccbbf1c0-789d-4a84-96bd-cdb04c618d13', 'O‘sishini kuzataylik 📈', 'Jismoniy faolligi oshdi. Ammo vazn ortishi me’yordami? Rivojlanish sur’atini Vaznni kuzatish vositasida tahlil qilib, xavotirlardan xalos bo‘ling.'),
  ('0671a41f-8a24-4dff-87f0-008aa3abfc3d', 'Ovqat hazm qilish tizimi qanday? 💩', 'Taglikni almashtirganda najas haqidagi ma’lumotlarni ilovaga kiriting. Kun davomida tolaga boy mahsulotlarning ovqat hazm qilishga ta’sirini osongina kuzating.'),
  ('d414aad6-2d3e-4a62-a555-9241874e68b3', 'Uyqu jadvali ⏱️', 'Uxlash vaqti keldi! Uyqu taymerini ishga tushiring va chaqalog‘ingiz kunlik uyqu me’yoriga rioya qilayotganiga ishonch hosil qilish uchun uning rejimini tahlil qiling.'),
  ('fbbb1355-d1ac-4efe-b9c7-1746b97b1656', 'Bo‘lishishni istamayaptimi? 🤖', 'Bog‘da o‘yinchog‘ini bo‘lishmay, baqiryaptimi? Anacan AI yordamida bunday vaziyatda qanday yo‘l tutish kerakligini bilib oling va amalda qo‘llang.'),
  ('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e', 'Tonggi syurpriz 💩', 'Kunning birinchi tagligini almashtirdingizmi? Najas haqidagi ma’lumotlarni ilovaga kiritib, oshqozon-ichak tizimi faoliyati va suyuqlik iste’molini yaqindan kuzating.'),
  ('b32e8863-be99-483a-aff4-94fc82f554bc', 'Uyqu taymeri ishga tushdi! ⏱️', 'Kechki odatlar boshlanmoqda. Taymerni yoqing va faol kun uyquga ketish vaqtini qanday o‘zgartirganini osongina tahlil qiling.'),
  ('f0fc96ac-776c-4e66-bacf-461eff128cbc', 'Rang-barang likopchalar 🥦', 'Sabzavot yemayaptimi? Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlardagi qiziqarli bezash usullaridan foydalanib, Oziqlanish nazorati vositasidagi me’yorni quvnoq tarzda bajaring.'),
  ('4673b81e-675b-4232-a5ca-c06aa26d504d', 'Onaning energiyasi 🔋', 'Yugur-yugurlar holingizni oldimi? O‘zingizni ham unutmang! Sog‘lom retseptlardan bir zumda quvvat beradigan, oqsilga boy smuzi tayyorlang.'),
  ('7a2ab463-526e-46c6-a246-3494b6c46fa9', 'Og‘ir tongmi? 🌪️', 'Injiqlik xurujlari juda charchatadi. Chuqur nafas oling va bu vaziyatda qanday yo‘l tutish kerakligini darhol Anacan AI’dan so‘rang.'),
  ('c995af30-30f9-4eaf-a66c-3d0d65fc825b', 'Ichki ovozingizga quloq soling 📝', 'Bola uxlab qoldi. Endi Kayfiyat kundaligini oching va hech kim o‘qimaydigan o‘sha satrlarga bugungi his-tuyg‘ularingizni yozib, yengil torting.'),
  ('0aa2cefc-f18c-4c10-98d6-e4dfda22198e', 'Tinchlantiruvchi ovoz 🌧️', 'Yangi kashfiyotlarga boy kundan keyin uxlay olmayaptimi? Oq shovqinlar orasidan yomg‘ir ovozini yoqib, uning asab tizimini tabiiy ravishda tinchlantiring.'),
  ('a57c041d-751b-4413-a98e-ee1564a86127', 'Toza havo, mo‘l-ko‘l energiya 🌳', 'Uy devorlari siqib qo‘yayaptimi? Onalar uchun qulay joylar bo‘limidan turli o‘yin qurilmalari bor yangi parkni topib, bolangizga energiyasini chiqarishga yordam bering.'),
  ('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc', 'Aqliy rivojlanish sakrashi 🧠', '18.5 oylik chaqaloqning miyasida nimalar yuz bermoqda? Bloglar bo‘limidagi eng yangi maqolani o‘qib, rivojlanish jarayonlarini o‘rganing.'),
  ('58a79bee-96dd-429b-a570-14dc6d97d91a', 'Tinchlantiruvchi to‘lqinlar 🌊', 'Haddan tashqari ta’sirlangan miyani tinchlantirish kerak. Xonada Oq shovqinlar bo‘limidan okean to‘lqinlari ovozini yoqib, uni tinchlantiring.'),
  ('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1', '“Bu nima?” bosqichi 🤖', 'Farzandingizning tuganmas savollari va kashf etishga bo‘lgan qiziqishi sizni hayratga solyaptimi? Bu kognitiv rivojlanishdagi sakrash haqida Anacan AI yordamchimizdan ma’lumot oling.'),
  ('f8ad5a51-f4c3-4fc4-8170-0775df79fe84', 'O‘zi ovqatlanishni xohlaydi 🥣', 'Qoshiqni qo‘lidan qo‘ymayaptimi? Ovqatlanish taymerini yoqing, jarayon davomiyligini kuzating va Chaqaloq retseptlaridan ushlash oson bo‘lgan taomlarni tanlang.'),
  ('995604f6-97b2-4fe5-91ea-98f2248c1b28', 'Oqsil zaxirasi 🥚', 'Harakatchan kichkintoyning mushaklari uchun oqsil juda zarur! Ovqatlanishni nazorat qilish vositasi yordamida uning kundalik oziq-ovqat muvozanatini baholang va yetishmayotganlarini to‘ldiring.'),
  ('ec6ff433-9523-4a66-a427-b2548807345b', 'Diqqat va xotira 🧠', 'Chaqalog‘ingiz qanday o‘rganadi? Ilovamizning Bloglar bo‘limida 1.5 yoshdan keyin diqqat va xotiraning rivojlanishi haqidagi maqolani o‘qing.'),
  ('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855', 'Kun yakuni 🌙', 'Uxlash vaqti keldi! Uyqu taymerini yoqing, kundalik uyqu me’yoriga rioya qilayotganiga ishonch hosil qilish uchun uning rejimini qayd eting va dam oling.'),
  ('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7', 'Uyqu regressiyasimi? ⏱️', 'Kechalari tez-tez uyg‘onadimi? Uyqu taymeri grafigini ko‘rib chiqing. Kunduzgi uyqu juda uzoq davom etsa, uni biroz qisqartirish vaqti kelgan bo‘lishi mumkin.'),
  ('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9', 'Kalsiy zaxirasi 🧀', 'Tishlar va suyaklar uchun kalsiy zarur. Ovqatlanishni kuzatish vositasi orqali bugun sut mahsulotlari me’yorini iste’mol qilganingizni tekshiring.'),
  ('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11', 'Kundalik muvozanat 💧', 'Tush payti taglikni almashtirganda qayd etishni unutmang! Ajralmalar tez-tezligi bolaning faolligiga bog‘liq suyuqlik ehtiyoji va hazm jarayoni haqida ma’lumot beradi.'),
  ('44008632-a96c-4f5e-a936-9b65273a2264', 'Endi navbat sizda 🥗', 'Bola kunduzgi uyquga ketdimi? Oshxonaga o‘ting! Ayollar uchun foydali retseptlardan foydalanib, o‘zingizga mazali taom tayyorlang.'),
  ('868f8ace-292a-4cf1-9abe-4b2da08aca3f', 'Qahva tanaffusi ☕', 'Uy yumushlari va kundalik ishlar sizni charchatdimi? Onalar uchun qulay joylar orasidan bolalar burchagi bor kafeni toping. Bir finjon issiq qahva ichish — sizning tabiiy haqqingiz.'),
  ('f7b08a7d-5067-40df-81d3-421be952c00e', 'Mukammal ona bo‘lmaydi 💖', 'Bugun hammasi reja bo‘yicha ketmagan bo‘lsa, o‘zingizni ayblamang. Kayfiyat kundaligiga ichingizdagi tashvishlarni yozing va yengil nafas oling.'),
  ('108adc32-ab84-4dcd-be8c-e7597e84aa99', 'Stolda uzoq o‘tiradimi? ⏱️', 'Ovqat bilan o‘ynash davri boshlandi. Ovqatlanish taymerini yoqing va ishtahasizlikning oldini olish uchun ovqatlanish davomiyligini tahlil qiling.'),
  ('36ae8436-7cda-46ec-b16d-44295bf2f7bc', 'Kiyimlari yana kichrayib qoldimi? 📏', 'Birdan bo‘yi o‘sganini sezyapsizmi? Rivojlanish kuzatuvchisiga yangi ko‘rsatkichlarni kiriting va rivojlanish grafigining yuqorilashini faxr bilan kuzating.'),
  ('909b1a9f-36d9-4ba3-a481-ae0e711ea145', 'Shirin kadrlar 📸', 'Sakrashga yoki raqsga tushishga urinyaptimi? Bu lahzani Chaqaloq fotosessiyasidagi quvnoq ramkalar bilan bezatib, bir umrlik xotira yarating.'),
  ('049ab226-ff27-4f2f-a64f-85d2b588c035', 'Tishi og‘riyotgan bo‘lishi mumkinmi? 🤖', 'Sababsiz ishtahasizlik yoki yig‘lash kuzatilyaptimi? Oziq tishlar chiqishining belgilari haqida Anacan AI’dan ekspert fikrini so‘rang.'),
  ('0e73fb38-1702-4d44-8a47-bf821e795ce5', 'Xavfsiz qadamlar 👟', 'Endi yanada tez yuguryapti! Ilk ishonchli qadamlar uchun Tavsiya etilgan mahsulotlar bo‘limidagi eng yaxshi ortopedik oyoq kiyim modellarini ko‘rib chiqing.'),
  ('2606521b-da76-4e40-8b9b-74eaed8f4900', 'Kelajakka meros 🖼️', 'Bugun sizni eng ko‘p kuldirgan o‘sha harakatini Chaqaloq albomiga qo‘shdingizmi? Telefon xotirasi to‘lib qolsa ham, xotiralar doimo xavfsiz saqlansin.'),
  ('0bcc42e9-f88e-427d-8d6d-562c3e7e7138', 'Brokkoli operatsiyasi! 🥦', 'Sabzavotlarni rad etyaptimi? Xavotir olmang. Chaqaloqlar uchun retseptlarda brokkolini mazali quymoqchalar ichiga qanday yashirish mumkinligini bilib oling.'),
  ('2e502c2f-240e-4506-a102-a80013f7742b', 'O‘zingizga tan oling 🛋️', 'Bugun juda charchadingiz va hammasini tashlab qo‘ygandek bo‘ldingizmi? Bu normal holat! Kayfiyat kundaligini ochib, Menga dam olish kerak deb yozing va bu oqshomni faqat o‘zingizga bag‘ishlang.'),
  ('530196ff-adb2-4ae9-a06d-67bb4bfd998f', 'Quruq tagliklar ko‘paydimi? 🧻', 'Ertalabki taglikni tekshiring. Agar u 2 soatdan ortiq quruq qolsa, bu tuvakka o‘rgatish uchun ilk belgi bo‘lishi mumkin! Qaydlaringizni taglik kuzatuvchisiga kiriting va statistikani tekshiring.'),
  ('057998e1-6566-4f75-aa40-70a38d334aee', 'Onaning suv muvozanati 💧', 'Bolangizning ortidan yugurib, suv ichishni unutdingizmi? Bosh og‘rig‘ining sababi shu bo‘lishi mumkin. Sog‘lom retseptlar bo‘yicha detoks suvlari tayyorlab, quvvatingizni tiklang.'),
  ('29452fba-ed37-4bde-8e72-45e1f9c46d4d', 'Uyqugacha 10 daqiqa... ⏱️', 'Uyqu taymerini yoqing va xonani qorong‘ilating. Oq shovqinlardan o‘rmon shovqinini qo‘yib, uyquga ketish jarayonini u uchun ham, o‘zingiz uchun ham sehrli lahzaga aylantiring.'),
  ('fa637a9e-0a58-4301-a5dd-89fb27cdb46b', 'Makaron mahluqi! 🍝', 'Mustaqil ovqatlanayotganda kiyimlari, hatto sochlari ham iflos bo‘ldimi? Bu kulgili lahzani o‘tkazib yubormang! Suratni chaqaloq fotosessiyasidagi quvnoq ramkalar bilan bezab, albomga qo‘shing.'),
  ('031932e3-d91b-494c-9f35-dc03d53026b4', 'Oyoq kiyimi siqayaptimi? 👟', 'So‘nggi paytlarda yugurayotganda tez-tez qoqilib ketyaptimi? Balki oyog‘i o‘sgandir! Vazn kuzatuvchisiga yangi oyoq kiyimi o‘lchami va bo‘yini kiriting hamda o‘sish sur’atini tahlil qiling.'),
  ('db0a30ff-e18a-4830-abdc-881dc8827a75', 'Miya uchun ozuqa: Omega-3 🐟', 'Miya rivoji uchun baliq juda muhim. Qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan suyaksiz, pechda pishiriladigan mazali baliq kotletini tayyorlang.'),
  ('eb71840a-d8fc-43f9-897d-715c008b72b7', 'Sekinlashish vaqti! 🌙', 'Faol kun nihoyasiga yetdi. Uyqu taymerini yoqing, yugurib-o‘ynashni to‘xtatib, tinchlantiruvchi mashg‘ulotlarga (masalan, pazl yig‘ishga) o‘ting.'),
  ('36d9b82f-d63f-40d9-bafa-df3b3dc844b9', '5 daqiqada mazali taom! 🥗', 'Tushlikda yo‘l-yo‘lakay tamaddi qilyapsizmi? Ayollar uchun sog‘lom retseptlar bo‘limidan sizni uzoq vaqt to‘q tutadigan va quvvat beradigan avokado hamda tuxumli tost tayyorlang.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('5db92d40-f36e-4671-8f65-a3cb3f1c91ed'::uuid, 'Vannadagi fizika kashfiyotlari 🛁', 'Suvni bir plastik stakandan boshqasiga quyayotgandagi jiddiy va diqqatli qiyofasini Chaqaloq albomiga qo‘shing — bunday kichik kashfiyot onlari unutilmasdir!'),
  ('e18f3a19-4a7e-44e4-9703-5c88f6dda037', 'Ekran qarshisida ko‘p qolayaptimi? 📱', 'Telefonni qo‘lidan olish kuchli injiqlikka sabab bo‘lyaptimi? Ekran vaqtini stresssiz cheklash va sog‘lom chegaralarni belgilashni Anacan AI’dan o‘rganing.'),
  ('44418a3d-932e-44e2-832c-c9fdeea34df1', 'Urish va tishlash? 🛑', 'Ifoda eta olmaydigan his-tuyg‘ulari ba’zan tajovuzkorlikka aylanadi. Bu yoshda tishlash va urish holatlariga qanday munosabat bildirish kerakligini Anacan AI’dan so‘rang.'),
  ('4a287257-0f36-49cd-93f7-28a1154386a6', 'Kitobga muhabbat qanday paydo bo‘ladi? 📖', 'Uyqudan oldin kitob o‘qiysizmi? Bloglar bo‘limimizda bolaga kitobni sevdirish va uning diqqatini sahifalarda ushlab turishning oltin qoidalarini o‘qing.'),
  ('f9f77164-bd35-4d6c-83ca-1991fcf7701a', 'Yangi kashfiyotlar, xavf-xatarlar ⚠️', 'U endi hamma joyga tirmashib chiqadi! Uyingiz xavfsizligini oshirish uchun Tavsiya etilgan mahsulotlar bo‘limidagi mebel qirralari uchun yumshoq himoya vositalarini albatta ko‘rib chiqing.'),
  ('66297752-072e-4e90-afa0-bfdfc587176c', 'Temir zaxirasi qanday? 🥩', 'Serg‘ayrat kichkintoyda kamqonlik yuzaga kelmasligi va u quvvatga to‘la bo‘lib qolishi uchun Oziqlanishni nazorat qilish vositasida bugungi temir iste’molini tekshiring va yetishmayotgan miqdorni to‘ldiring.'),
  ('802d0f46-e525-43d0-8f5c-440b82228035', 'Qum va barg terapiyasi 🍂', 'Uyning to‘rt devori orasidan tashqariga chiqing! Onalar uchun qulay joylar orasidan qum maydonchasi yoki keng yashil hududi bor parkni topib, bolaning sensor rivojlanishini qo‘llab-quvvatlang.'),
  ('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618', 'Mukammallikka intilishdan voz keching ✨', 'Bugun bolangizga ovozingizni balandlatdingizmi? O‘zingizni aybdor his qilmang. Kayfiyat kundaligiga ichki kechinmalaringizni yozing, o‘zingizni kechiring va ertangi yangi kunga tayyorlaning.'),
  ('2c1e9be8-ccf0-412a-a942-30cea5075e5b', 'Ijtimoiylashish vaqti! 👶', 'U endi boshqa bolalar bilan birga bo‘lishga intilmoqda. Onalar uchun qulay joylar orasidan bolalar o‘yin markazi bor joyni topib, uni xursand qiling.'),
  ('cb4b4d68-2b36-4d3f-aa77-92d10314464f', 'Yangi ovqat, yangi reaksiya 💩', 'Kecha odatdagidan boshqacha yoki allergiya keltirib chiqarishi mumkin bo‘lgan biror narsa yedimi? Ertalab tagligini almashtirayotganda najasini kuzating, rangi yoki konsistensiyasidagi o‘zgarishlarni ilovaga qayd etib, holatini nazorat qiling.'),
  ('fec1f9db-8b95-410a-b753-aded5a7dc606', 'Qorong‘ilikdan qo‘rqadimi? 🌌', 'Xona chirog‘ini o‘chirganingizda yig‘laydimi yoki bezovta bo‘ladimi? Oq shovqinlar orasidan ona qornidagi tovushni (yurak urishini) yoqib, unga avvalgi iliq va xavfsiz muhitni his qildiring.'),
  ('5c635a69-e5ff-42eb-9277-29e39d9986fa', 'Tish yuvish maroqli! 🪥', 'Tish cho‘tkasini og‘ziga yaqinlashtirishga qo‘ymaydimi? Tavsiya etilgan mahsulotlar orasidan barmoqqa kiyiladigan cho‘tkalar yoki chiroqli va musiqali modellarni ko‘rib, bu gigiyena jarayonini o‘yinga aylantiring.'),
  ('f2a19104-ece3-4a8f-9966-8cad392a68af', 'Tun sukunati 🍵', 'Bola uxladi, taymer to‘xtadi. Endi yugurib-yelish emas, dam olish vaqti. Sog‘lom retseptlar bo‘limidan moychechak choyini damlab, mutlaq sokinlikdan bahramand bo‘ling.'),
  ('f524b282-4173-4386-b8dd-255261b77d1d', 'O‘zim kiyinaman! 👕', 'Ertalab kiyinish paytida katta janjal chiqadimi? Bloglar bo‘limida bolaga tanlash imkonini berish orqali kiyinish injiqliklarini bartaraf etishning amaliy usullarini o‘qing.'),
  ('46919051-4727-4a43-8ba3-d5a1f5451c16', 'Do‘konda katta janjal? 🛒', 'Istagan narsasi olib berilmagani uchun jamoat joyida o‘zini yerga tashlayaptimi? Atrofdagilarning qarashlariga e’tibor bermang, o‘sha paytda xotirjam qolish uchun Anacan AI bilan dardlashib, yordam oling.'),
  ('874df706-e26e-4b72-a02c-7f8309fc95d5', 'Ikki so‘zli gaplar! 🗣️', 'Bugun Ona, kel yoki To‘pni ot kabi yangi birikma tuzdimi? Til rivojlanishidagi bu ajoyib yutuqni ovozli video shaklida darhol Chaqaloq albomiga saqlang.'),
  ('af368cd3-f751-4611-9e47-9c8fda037ebd', 'Barmoqlarning mayda motorikasi ishda! 🧩', 'No‘xat, makkajo‘xori yoki to‘g‘ralgan mevalarni mustaqil yeyishiga ruxsat bering. Bu mayda motorikani rivojlantiradi. Ovqatlanish nazorati orqali porsiya miqdorini kuzating.'),
  ('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323', 'Immunitetni qo‘llab-quvvatlang! 🍊', 'Ob-havo o‘zgarayaptimi? Ovqatlanish nazorati vositasi yordamida bugun qabul qilingan C vitamini miqdorini hisoblang va menyuga sitrus mevalar, kivi yoki rangli bulg‘or qalampirini qo‘shing.'),
  ('28cf8172-0a76-4afd-b2de-765879c7939a', 'O‘zingizga minnatdorlik bildiring! 💖', 'Siz shunchalik fidoyi va ajoyib onasiz! Kayfiyat kundaligini oching, bugun farzandingiz uchun qilgan eng kichik yaxshiligingizni ham yozib qo‘ying va o‘zingiz bilan faxrlaning.'),
  ('f00a5e44-ed12-4c77-9249-e4246b2b108d', 'Tuvak bilan ilk tanishuv 🚽', 'Hali erta bo‘lsa-da, tuvakni hammomda saqlash bolani unga ko‘nikishga tayyorlaydi. Tavsiya etilgan mahsulotlar orasidan uning e’tiborini tortadigan qulay va qiziqarli modellarni ko‘rib chiqing.'),
  ('6d72635f-ba12-4c8b-b7ef-f626dd634dce', 'Tonggi energiya o‘zgacha! ⚡', 'Suli bo‘tqasini yeyishni istamayaptimi? Chaqaloqlar uchun retseptlardan meva va yeryong‘oq pastali smuzi toping va Ovqatlanishni nazorat qilish vositasidagi kaloriya maqsadiga osonlik bilan erishing.'),
  ('9867089b-80a4-4895-985d-1e1d5fa3df95', 'Ko‘zlaringiz yumilib ketyaptimi? 😴', 'Bolangiz uxlaganda siz ham yotib dam oling. Agar uxlay olmasangiz, Ayollar uchun foydali retseptlardan antioksidantlarga boy ko‘k choy tayyorlab, tetiklaning.'),
  ('a5fedf21-2dca-46ed-9476-0b415ced68a5', 'Uxlashga qarshilik qilyaptimi? 🛌', '19-oy uyqudagi keskin o‘zgarishlar bilan mashhur. Uyqu taymerini ishga tushirib, jadvalni tekshiring — balki kunduzgi uyquni qisqartirishning ayni vaqtidir!'),
  ('39db43fc-07a0-417e-90da-c0bbbd5f14a4', 'Qorni og‘riyaptimi? 💩', 'Ertalab tagligini almashtirayotganda najas haqidagi ma’lumotlarni kiriting. Ich qotishi xavfi bo‘lsa, Anacan AI’dan tezkor tabiiy yechimlar va massaj usullarini so‘rab, ularni qo‘llang.'),
  ('613cd9e2-958a-41bd-b191-0de3ff8ec07f', 'Necha marta «Yo‘q» deganini eshitdingiz? 🙉', 'Qaysar kichkintoy bilan murosa qilish sabr-toqat talab etadi. Kayfiyat kundaligiga ichki zo‘riqishingizni yozing va o‘zingizni ayblamasdan his-tuyg‘ularingizni bo‘shating.'),
  ('e893b0aa-e3fc-4f78-a970-b681a0ed0450', 'Tirmashish chempioni! 🧗', 'Uydagi mebellar unga kamlik qilyaptimi? Onalar uchun qulay joylardan yumshoq to‘siqlar yo‘lagi bor yopiq ko‘ngilochar markazni toping va uning bu istagini xavfsiz tarzda qondiring.'),
  ('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee', 'Dizayner ish boshida! 👗', 'Kiyimlarini o‘zi tanlashni xohlab, bir-biriga mos kelmaydigan ranglarni kiyadimi? Bu kulgili obrazni Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomdagi eng qiziqarli kadrga aylantiring.'),
  ('f830cd97-a8bb-4789-bdc5-7806bcd89cfe', 'Haddan tashqari sergaklik 🎇', 'Kunduzi juda faol bo‘lgan miya kechasi tinchlana olmaydi. Oq shovqinlar bo‘limidan soch quritgich yoki ventilyator ovozini yoqib, bir maromdagi tovush uni qanday tinchlantirishini kuzating.'),
  ('f8565841-4602-47d5-af45-99f7dea5b129', 'Chapaqaymi yoki o‘naqay? 🤚', 'Qoshiqni qaysi qo‘li bilan ushlaydi? Yetakchi qo‘l qanday va qachon shakllanishi haqida Bloglar bo‘limidagi yangi ilmiy maqolamizni albatta o‘qing.'),
  ('1915583e-53f5-46af-8212-835dfd587e22', 'Soch to‘kilishi davom etyaptimi? 💇‍♀️', 'Tanangiz hali ham tiklanish jarayonida. Ayollar uchun foydali retseptlar orasidan rux va biotinga boy nonushta menyusini tanlab, bugun o‘zingizga g‘amxo‘rlik qiling.'),
  ('cfbeabf3-def0-4cbe-a106-fd34987dd776', 'Musiqa asboblari davri 🥁', 'Yog‘och qoshiqlar bilan qozonlarni urib o‘ynashni yoqtiradimi? Tavsiya etilgan mahsulotlar bo‘limida ovoz balandligi bolalar qulog‘i uchun xavfsiz bo‘lgan ksilofon va nog‘oralarni ko‘rib chiqing.'),
  ('daa6a0d6-25d4-401e-ba81-8a8ca5108695', 'Hayvonlarning ilk tovushlari 🐮', 'It yoki mushukni ko‘rganda ularning ovoziga taqlid qilishga urinadimi? Bu ajoyib aqliy rivojlanish lahzasini qisqa video shaklida Chaqaloq albomiga qo‘shib, xotiraga muhrlang.'),
  ('2ed7fd17-90ba-451d-9c88-a1f94a180fe0', 'Ishtahasi pasaydi, vazni-chi? 📉', 'Bu oylarda ovqat tanlash odati kuchayadi. Vazn kuzatuvchisiga joriy ko‘rsatkichlarni kiriting, rivojlanish aslida me’yorida ekanini ko‘rib, darhol xotirjam bo‘ling.'),
  ('50209dd4-d2d7-4719-bf4e-21df8c72686a', 'Uyquga tayyorgarlik odatlari 🧸', 'Har oqshom bir xil ketma-ketlikka amal qiling! Uyqu taymerini yoqing, sevimli ayiqchasiga xayrli tun tilating va bu barqarorlik uxlab qolishni qanchalik osonlashtirayotganini qayd eting.'),
  ('cc01349a-6eef-4c61-aa08-b3f505c2eb5f', 'O‘zim yeyman! jangi 🥣', 'Ruxsat bersangiz, ovqat hamma yoqqa sochiladi, bermasangiz, baqiradi. Bu inqirozni stresssiz qanday boshqarishni Anacan AI’ning psixologik tavsiyalari orqali hoziroq bilib oling.'),
  ('3abde512-ebd4-4cf1-986e-fb1953695f78', 'Rang-barang immunitet qalqoni 🛡️', 'Ovqatlanishni nazorat qilish vositasi yordamida bugun yetarli miqdorda C vitamini olganini tekshiring. To‘q sariq va qizil sabzavotlar uchun Chaqaloq retseptlariga murojaat qiling.'),
  ('56129e04-2f90-42b1-b51e-b835940e284e', 'Aqliy yukdan xalos bo‘ling 🧘‍♀️', 'Buni ham qilishim, uni ham pishirishim kerak, deb miyangiz tinmayaptimi? Kayfiyat kundaligiga barcha rejalaringiz va xavotirlaringizni yozing. Ularni ro‘yxat qilish stressni darhol kamaytiradi.'),
  ('deb6cbd4-3a89-4915-9bdf-626d87829918', 'Suv va loyga muhabbat 💦', 'Ust-boshini kir qilishidan cho‘chimang! Onalar uchun qulay joylar orasidan ochiq havodagi maskanni toping, tabiat bilan muloqot qilib, sensor rivojlanish imkoniyatlaridan to‘liq foydalansin.'),
  ('1576f605-27d8-4159-b3bd-3dd9e63c91dd', 'Ko‘proq suyuqlik, oson hazm 💧', 'Quyuq ovqatlarga to‘liq o‘tish ba’zan hazm qilishni qiyinlashtiradi. Taglik kuzatuvchisida qaydlar yuritib, suyuqlik iste’molini oshirish zarur yoki yo‘qligini osongina aniqlang.'),
  ('93141c59-a17f-414d-9f6c-c865a0650eeb', 'Soyalar teatri boshlanadi! 🐰', 'Xona chirog‘ini o‘chirib, fonar yordamida devorda soyali shakllar yarating. Chaqalog‘ingizning bu mo‘jizani hayrat bilan tomosha qilayotgan yoqimli ifodasini Chaqaloq albomi uchun albatta videoga oling.'),
  ('a14c30d1-ff1f-46da-8b1e-98116e38ee0d', 'Sahifalarni yirtishni yoqtiradimi? 📖', 'Kitoblarni o‘qish o‘rniga ularni yirtishni xohlaydimi? Bu yoshda karton va paypaslab ko‘rish mumkin bo‘lgan kitoblarning ahamiyati haqida Bloglar bo‘limidagi yangi tavsiyalarni o‘qing.'),
  ('8e7d531f-d445-43eb-a4d5-05ffff377c4f', 'Shovqindan sukunatga 🎶', 'Televizor yoki o‘yinchoqlar tovushidan birdan sukunatga o‘tish bolalarni qo‘rqitishi mumkin. Xonada Oq shovqinlar bo‘limidan poyezd tovushini yoqib, uyqu muhitiga asta-sekin o‘tishiga yordam bering.'),
  ('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf', 'Bo‘lishishni istamayaptimi? 🧸', 'Bog‘da boshqa bolalarning o‘yinchog‘i tomon yuguradi-yu, ammo o‘zinikini bermaydimi? Anacan AI’dan 1.5 yoshli bolaga navbat bilan o‘ynash tushunchasini qanday o‘rgatishni bilib oling.'),
  ('ca671510-91c4-4377-9f69-b4bd47b292a2', 'Bir finjonlik tanaffus ☕', 'Quvvatingiz qanday? Uy ishlarini bir chetga qo‘ying. Ayollar uchun foydali retseptlardan quvvat beruvchi yeryong‘oq pastali keks tayyorlab, shunchaki qahvangizni xotirjam iching.'),
  ('38141003-a43c-4589-a477-21da541a08db', 'Kinetik qum sehri 🏖️', 'Uyda kichik plyaj yaratamizmi? Barmoq mushaklarini mustahkamlaydigan va tozalash oson bo‘lgan kinetik qum to‘plamlarini Tavsiya etilgan mahsulotlar bo‘limidan ko‘rib chiqing.'),
  ('75f9f2e1-a04a-4711-9125-3d8c610326d9', 'O‘z tanasini taniydi! 👃', '“Burning qayerda?” deb so‘rasangiz, faxr bilan ko‘rsatadimi? Chaqaloq fotosessiyasi uchun xonada kichik suratga olish jarayonini tashkil qiling va o‘sha yoqimli holatni darhol albomga saqlang.'),
  ('ae036003-f237-47e6-8031-7feeb47126cc', 'To‘yganini qanday bilamiz? ⏱️', 'Ovqatni otishni yoki tupurishni boshlasa, bu uning to‘yganini anglatadi. Ovqatlantirish taymerini to‘xtating, me’yor bajarilganini qayd etib, ishtahasini tahlil qiling.'),
  ('05bc3cfd-c566-4963-b6b2-87889d369e27', 'Sizga ham muloqot kerak 💬', 'Boshqa onalar bilan muloqot qilish sizga ham yaxshi ta’sir qiladi! Ona uchun qulay joylar orasidan o‘yin guruhlari mavjud markazni tanlang va ikkovingizga ham muloqot quvonchini tuhfa eting.'),
  ('5b6366a9-6eb4-4593-8335-c41fd3447da1', 'Bugungi g‘alabangiz nima? 🏆', 'Uni yig‘latmasdan uxlatdingizmi? Yoki bir kosa ovqatni to‘liq yedirdingizmi? Eng kichik yutug‘ingizni ham Kayfiyat kundaligiga yozing va o‘zingizni tik turib olqishlang.'),
  ('98a39354-24f3-4f3c-9cfb-1e084764a56b', 'O‘sish oyoq kiyimdan boshlanadi 📏', 'Oyoq kiyimini kiyishni istamayotgani, ehtimol, u tor bo‘lib qolganidandir! O‘lcham jadvalini Vazn kuzatuvchisi vositasida tekshiring va jismoniy rivojlanishini kuzatib boring.'),
  ('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1', 'Soch va teri uchun 🥑', 'Kundalik yumushlardan charchagan tanangizga g‘amxo‘rlik qiling. Ayollar uchun foydali retseptlardan antioksidantlarga boy avokado va yong‘oqli yoshlik salatini tayyorlang.'),
  ('a832a387-bccf-4a1a-823c-3930e73e4c07', 'Suv ber, ona kel 🗣️', 'Endi ikkita so‘zni birlashtirib, kichik gaplar tuzishga harakat qilyaptimi? Bu nutq rivojidagi ajoyib sakrash! Uning bunday urinishlarini doimo qo‘llab-quvvatlang va gapirishga undang.'),
  ('d1f9f7f1-6831-4583-9dbd-fab805703b8d', 'Tugamaydigan energiya 🔋', 'Yugurishdan charchamayaptimi? Uyqu taymerini yoqing va xona chiroqlarini xiralashtiring. Oq shovqinlardan o‘rmon shivirini qo‘yib, uni asta-sekin uyqu rejimiga tayyorlang.'),
  ('34104368-1e25-46df-8c68-910d16cd40b1', 'Hazm jarayoni qanday? 🚽', 'Ich qotishi muammosi bormi? Ertalab tagligini almashtirganda buni qayd eting va Ovqatlanishni nazorat qilish vositasi yordamida uning menyusiga kletchatkaga boy mahsulotlarni (nok, suli yormasi) albatta qo‘shing.'),
  ('79b083b6-1c72-4250-a120-ca8846206ce5', 'O‘zingizni qanday his qilyapsiz? 🧘‍♀️', 'Bugun juda ko‘p «yo‘q!» dedingizmi? O‘zingizni aybdor his qilmang. Kayfiyat kundaligiga ichingizdagilarni yozing va ona sifatida qanchalik fidoyi ekaningizni eslang.'),
  ('bfb35c45-0163-48f3-be24-eff4697cb9e8', 'Tabiat san’atkorlari 🍂', 'Barglar, toshlar va shoxlar — eng yaxshi o‘yinchoqlar! Ona uchun qulay joylardan yashillikka boy bog‘ni toping va ochiq havoda haqiqiy kashfiyotga otlaning.'),
  ('01861a89-1cc1-4443-8c58-c79d90402305', 'Do‘kondagi injiqliklar 🛒', 'Do‘konda xohlagan narsasini olib bermaganingiz uchun o‘zini yerga tashladimi? Vahimaga tushmang. Atrofdagilarning qarashlariga e’tibor bermay, xotirjamlik bilan uning ko‘zlari darajasigacha egiling.'),
  ('32e724db-ca0f-4d6b-9d07-716443a9dcdd', 'Hissiy yukdan xalos bo‘ling 📝', 'Kun og‘ir o‘tdimi? Kayfiyat kundaligiga bugungi stressingiz haqida yozib, ko‘nglingizni bo‘shating. Barcha onalar bu yo‘llardan o‘tadi, siz yolg‘iz emassiz.'),
  ('a0570819-b575-49b5-bbf4-bc21cf5fc939', 'Ikki oyoqda sakrash 🦘', 'Turgan joyida ikki oyog‘i bilan bir vaqtda sakrashga urinayaptimi? Juda kulgili ko‘rinadi, shunday emasmi? Bu lahzani albatta Chaqaloq fotosessiyasi bilan abadiylashtiring.'),
  ('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d', 'Uxlashni istamayaptimi? 🥱', 'Kunduzgi uyquga yotishni istamay, qarshilik ko‘rsatyaptimi? Anacan AI-dan 20 oylik bolalarning uyg‘oqlik oralig‘i haqida aniq ma’lumot va kun tartibi jadvalini so‘rang.'),
  ('2edb626b-eafe-49c0-a743-e6dae9f9eddd', 'Musiqali orom 🎶', 'Kechga yaqin boshlanadigan injiqliklarni bartaraf etishning eng oson yo‘li — uning sevimli kuyini qo‘yib, bag‘ringizga bosgancha asta raqsga tushishdir.'),
  ('b174df30-8e63-488e-ae9b-4d227f3136f1', 'Ona uchun ziyofat 🥑', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi? Sog‘lom retseptlar orasidan sizga kuch beradigan, temirga boy tushlikni tanlab, xotirjam o‘tirib tanovul qiling.'),
  ('5d951093-5ada-49f6-9750-d303bcf8d918', 'Katta oziq tishlarimi? 🦷', 'Hech bir sababsiz hamma narsani tishlab, yig‘layaptimi? Eng orqa oziq tishlari chiqayotgan bo‘lishi mumkin. Tish chiqishi kuzatuvchisida jarayonni qayd etib, sovuq tishlagichlarni tayyorlab qo‘ying.'),
  ('9fe66081-4fad-49c8-891d-2ca85484f87d', 'Ertak qahramoni 🪄', 'Bugun kechqurun Aqlli ertaklarda qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: tishlarini tozalashni yaxshi ko‘radigan jasur kichkintoy.'),
  ('c638741f-2af1-4bf3-a4de-09ffcb406144', 'Ko‘chaga chiqishga jur’at ⛅', 'Ob-havo g‘alati bo‘lgani uchun uyda qolib ketdingizmi? Ob-havo va kiyim tanlash vositasi derazadan bilib bo‘lmaydigan shamol tezligini va mos kiyimlar uyg‘unligini sizga darhol ko‘rsatsin — parkka dadil chiqing.'),
  ('3d75b744-8440-4e62-83c6-4a08b865c0f7', 'Qatiqli niqob! 🥣', 'Ovqatni yuzi va sochiga surtib oldimi? Jahlingiz chiqishi o‘rniga, bu noyob san’at asarini Chaqaloq albomiga qo‘shing, ustiga qiziqarli stikerlar yopishtirib, uni unutilmas xotiraga aylantiring.'),
  ('69c1e419-f8f2-4b2f-90e3-9b51e78ff197', 'Taymer to‘xtadi, siz esa dam oling 🍵', 'Uyqu taymerini to‘xtatib, xonadan chiqdingiz. Endi uy ishlariga qo‘l urmang! O‘zingizga moychechak choyi damlab, kun davomida to‘plangan charchoqni iliq bug‘ bilan tarqating.'),
  ('934796d5-42af-4c49-9cb9-67f18b657e36', 'Tishlari qichishyaptimi? 🦷', 'Oxirgi oziq tishlari chiqayotgan bo‘lishi mumkin. Milk qichishishini kamaytirish uchun Chaqaloq retseptlaridan foydalanib, salqin, shakarsiz va foydali mevali muzqaymoq (popsicles) tayyorlang.'),
  ('06d75280-127a-43d4-a7f0-42d2871b24c5', 'Mustaqil oshpaz! 👨‍🍳', 'Qoshiqni sizga berishni istamayaptimi? Chaqaloqlar uchun retseptlardan qo‘lda ushlash oson bo‘lgan kotletchalar tayyorlang. Ovqatlanish taymeri yordamida mustaqil ovqatlanish vaqtini tahlil qilib, ishtahasini kuzating.'),
  ('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb', 'Kulgili yuz ifodalari 🤪', 'Ko‘zgu qarshisida aftini burishtiryaptimi? Bu quvnoq lahzani o‘tkazib yubormang! Chaqaloq fotosessiyasidagi kulgili stikerlar bilan bezatib, uni albomdagi eng quvnoq suratga aylantiring.'),
  ('739af07d-8466-4c3f-a164-5e408385ca93', 'Hamma narsaga tirmashadimi? 🧗‍♀️', 'Divan, stol, shkaf... U haqiqiy alpinist! Bloglar bo‘limida bu xavfli, ammo zarur harakat ehtiyojini uyda qanday xavfsiz qondirish mumkinligini o‘qing.'),
  ('8ac7016a-7613-48aa-a952-59cc5f8a6354', 'Shimining pochasi kalta bo‘lib qoldimi? 👖', 'O‘sish sakrashi jadal davom etmoqda! Vazn kuzatuvchisiga hozirgi bo‘yi va vaznini kiriting hamda rivojlanish grafigi qanday yuqorilayotganini faxr bilan kuzating.'),
  ('db467018-0ec9-41a9-a3a3-3ef1c48cda53', 'Rivojlantiruvchi o‘yinchoq izlayapsizmi? 🧩', 'Shunchaki ovoz chiqaradigan emas, fikrlashga undaydigan o‘yinchoqlar kerak. Tavsiya etilgan mahsulotlar bo‘limida 1.5 yoshdan katta bolalar uchun mantiqiy va shaklli boshqotirmalarni (puzzle) albatta ko‘rib chiqing.'),
  ('df8f7402-1277-45bd-a743-5c24bdaf48e1', 'Jahli chiqqanda tishlaydimi? 🦖', 'Jahli chiqqanda uradimi yoki tishlaydimi? Bu — uning so‘z bilan ifodalay olmaydigan his-tuyg‘ulari. Anacan AI’dan bu xatti-harakatni qanday qilib muloyimlik bilan o‘zgartirish mumkinligini bilib oling.'),
  ('45af46ac-18bf-499b-a5c7-56bbe71e4564', 'Sokinlikka o‘tish 🎶', 'Kun bo‘yi yugurgan mitti oyoqchalarning dam olish vaqti keldi. Oq shovqinlar orasidan avtomobil saloni ovozini yoqib, bir maromdagi tovush yordamida uxlash uchun mukammal muhit yarating.'),
  ('47b68bdb-a1fd-4da7-9316-dcca5fdae94f', 'Sizga ham do‘stlar kerak 👯‍♀️', 'Farzandingiz bog‘da o‘ynayotganida siz ham boshqa onalar bilan suhbatlashishni istaysizmi? Onalar uchun qulay maskanlar orasidan o‘yin guruhlari mavjud markazlarni toping va yangi tanishlar orttiring.'),
  ('49af58d4-c188-43d7-a0b2-43f4cd255337', 'Ertalabki qahvaning o‘zi kamlik qiladi! ☕', 'Kunni och qoringa qahva ichish bilan boshlash quvvatingizni tezda tugatadi. Ayollar uchun foydali retseptlar orasidan 5 daqiqada tayyorlanadigan, quvvatga boy suli keksini tanlang.'),
  ('869af623-de96-421f-808b-d64172a8f765', 'Sizga qoyil! 👏', 'Bugun uy yig‘ishtirilmay qoldimi? Hech ham tashvishlanmang! Farzandingiz bilan o‘tkazgan quvonchli onlar bundan qadrliroq. Kayfiyat kundaligida o‘zingizni albatta maqtang.'),
  ('aaf473f6-79bc-44cf-97f4-687dfa4eb293', 'Suv ichishni yoqtirmaydimi? 💧', 'Ertalab tagligi juda quruq edimi? Suyuqlik iste’molini oshirish kerak. Buni taglik kuzatuvchisiga qayd eting va ilovadan mevali suv retseptlari hamda turli ichimlik idishlari modellarini ko‘rib chiqing.'),
  ('ff614b36-4091-473e-b7fa-91411bd4e2a9', 'Suyaklari mustahkamlanmoqda! 🦴', 'Ovqatlanishni nazorat qilish vositasi yordamida bugun yetarli miqdorda kalsiy va D vitamini olganini hisoblang. Jadal jismoniy rivojlanish uchun bu ikki modda bir-biridan ajralmasdir.'),
  ('348430a9-4730-49e1-90ac-91076b5c5d7c', 'Ranglarni ajratamiz! 🔴🔵', 'Qizil o‘yinchoqlarni bir tomonga, ko‘klarini boshqa tomonga ajrating. Bloglar bo‘limida 19.5 oylik bolalarning diqqatini va mantiqiy fikrlashini rivojlantiradigan uy o‘yinlari haqida o‘qing va ularni sinab ko‘ring.'),
  ('907f2a4d-a45c-43e1-8024-d6c91a18d072', 'Do‘konda qattiq baqiryaptimi? 🛒', 'Jamoat joyida o‘zini yerga tashlab yig‘ladimi? Boshqalarning qarashlariga e’tibor bermang. Bunday injiqlik xurujlarini xotirjam boshqarish usullarini o‘rganish uchun Anacan AI bilan dardlashing.'),
  ('e6ec7f70-00dc-438b-af17-5f764a9d8216', 'Kunduzgi uyqu qisqaryaptimi? ⏱️', 'Tushlikdan keyin uxlashni istamayaptimi? Uyqu taymeri statistikasini kuzating. Balki bitta kunduzgi uyqu rejimiga to‘liq o‘tib, kechki uyqu vaqtini ertaroqqa surishingiz kerakdir.'),
  ('46ef9700-c667-4312-ac63-98bd03625249', 'Oyoq kiyim borasidagi qaysarlik 👟', 'Tashqariga chiqayotganda yozda ham aynan o‘sha qishki oyoq kiyimini kiyishni talab qiladimi? Ba’zan unga o‘zi tanlashiga ruxsat bering — bu uning irodasini mustahkamlaydi.'),
  ('5541587a-ad73-4e1d-9174-d4fe1c028c3e', 'Uxlashga qarshilik qilyaptimi? 🛌', 'O‘ynash uxlashdan ko‘ra qiziqroq bo‘lgani uchun yotishni istamayapti! Uyqu taymerini yoqing va Oq shovqinlardan okean to‘lqinlari ovozini qo‘yib, uni asta-sekin tinchlantiring.'),
  ('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6', 'Hojatxonaga qiziqish boshlandimi? 🚽', 'Siz bilan birga hojatxonaga kirishni xohlayaptimi? Bu kuzatish orqali tayyorlanish bosqichidir. Bloglar bo‘limida tuvakka o‘rgatishni qachon va qanday boshlash kerakligi haqida o‘qing va bunga tayyor bo‘ling.'),
  ('3b603489-95c3-4a32-b0e0-5191fc844b75', 'O‘zi kiyinish jangi 👕', '“Bu ko‘ylakni xohlamayman!” degan qaysarlik boshlandimi? Ertalabki kiyinish injiqliklarini kamaytirish va unga mustaqil tanlash imkonini berish yo‘llarini Anacan AI-dan so‘rang.'),
  ('89933e6a-484e-4f2e-bf20-8262f6a74c72', 'Omega-3 zaxirasi 🐟', 'Miya rivojlanishi to‘xtamaydi. Ovqatlanishni nazorat qilish vositasida bu hafta yetarlicha baliq yoki yong‘oq iste’mol qilganini tekshiring, yetishmovchilik bo‘lsa, albatta qayd eting.'),
  ('fa46cf0a-85f0-484c-8aa5-b60eb52b320b', 'Uyda energiyani qanday sarflaymiz? 🏃‍♂️', 'Tashqariga chiqa olmayapsizmi? Tavsiya etilgan mahsulotlar bo‘limidagi yopiq joylar uchun mo‘ljallangan mini-batut yoki sirpanma tepaliklarni ko‘rib chiqing va uning energiyasini to‘g‘ri yo‘naltiring.'),
  ('00691751-d785-4fc6-8036-d313adccdad6', 'Ertalabki kutilmagan holatni tekshirish 🧻', 'Quruq tagliklar ko‘payyaptimi yoki hazm qilish sekinlashyaptimi? Ertalabki taglik almashtirishni taglik kuzatuvchisiga qayd etib, kichkintoyning suyuqlik va tolaga bo‘lgan ehtiyojini darhol tahlil qiling.'),
  ('0bde6683-6d18-4d98-bc39-b122396c0b17', 'Endi dam olish vaqti 🍵', 'Yugur-yugur tugadi! Foydali retseptlardan biror ichimlik tayyorlang, divanga cho‘zilib, shunchaki sukunatdan zavqlaning.'),
  ('0eecf770-9ba2-463c-9b39-bbe24d01b4e1', '“Meniki!” degan qichqiriqlar 🧸', 'Bog‘da boshqalarning o‘yinchog‘ini tortib olyaptimi? Bu yoshga xos egotsentrik injiqliklarni boshqarish uchun Anacan AI-dan eng samarali psixologik usullarni o‘rganing.'),
  ('0a81bd63-014b-4d25-b347-1808455aea49', 'To‘rt devor orasidan chiqish 🏃‍♀️', 'Uyda to‘plangan energiyani chiqarish qiyin. Onalar uchun qulay joylar orasidan siz qahva ichishingiz, u esa bemalol yugurishi mumkin bo‘lgan xavfsiz o‘yin markazini toping.'),
  ('657f4585-c7bb-41c0-9574-51e8f943398b', 'Tartibsiz, ammo mustaqil! 🥣', 'O‘zi ovqat yeyishni talab qilyaptimi? Ovqatlanish taymerini yoqing, jarayon qancha davom etishini kuzating va bu mustaqillik uning mayda motorikasiga qanday foyda berayotganini qayd eting.'),
  ('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4', 'Tunda uyg‘onishlar qaytdimi? ⏱️', 'Bu 20 oylik davrdagi uyqu regressiyasi bo‘lishi mumkin. Uyqu taymeri grafigini ko‘rib chiqing va kunduzgi uyquni 15 daqiqaga qisqartirish vaqti kelgan-kelmaganini tekshiring.'),
  ('385a8205-8e28-4c23-94fa-a2a8fe32e28c', 'O‘zingizni aybdor his qilmang 📝', 'Bugun ovozingizni biroz balandlatdingizmi? O‘zingizni ayblamang. Ichingizdagi kechinmalarni Kayfiyat kundaligiga yozing va farzandingiz uchun sizdan yaxshiroq ona yo‘qligini unutmang.'),
  ('49b18c8f-b30b-4368-9445-6af88b1d8115', 'Ikki so‘zli gaplar! 🗣️', 'Ona kel, To‘pni ber – uning so‘z boyligi tez kengaymoqda. Bu yoqimli gapirish urinishlarini ovozli video sifatida darhol Chaqaloq albomiga qo‘shib, umrbod xotiraga aylantiring.'),
  ('5d516faa-7c77-4db9-b201-49bff969e3d8', 'Suyaklar uchun kalsiy 🦴', 'Ko‘p yuguradigan kichkintoyning suyaklari mustahkam bo‘lishi kerak. Ovqatlanishni nazorat qilish vositasida bugungi kalsiy (pishloq, qatiq) iste’molini tekshirib, me’yorni to‘ldiring.'),
  ('ad033330-a436-4b30-84e7-2df370198c16', 'Aqlli o‘yinchoq izlayapsizmi? 🧩', 'Shakllarni teshiklarga joylashni yoqtiradimi? Tavsiya etilgan mahsulotlar bo‘limidan uning zehnini yanada charxlaydigan, yoshiga mos yog‘och pazllarni toping.'),
  ('d22a5573-d857-4918-90d2-9def6a084f6f', 'Miyani tinchlantirish san’ati 🎶', 'Haddan tashqari ko‘p taassurot olgan bola kechasi uxlay olmaydi. Xonani qorong‘ilating va Oq shovqinlar bo‘limidan okean to‘lqinlari ovozini yoqib, uni asta-sekin chuqur uyquga tayyorlang.'),
  ('fb035079-cf24-4146-9049-8d721e68f53f', 'Bo‘yoqqa belangan rassom! 🎨', 'Rasm chizayotib kiyimlarini bo‘yab tashladimi? Jahlingiz chiqmasin — bu kulgili lahzani Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomga yuklang.'),
  ('0b2c56b1-a7a8-4553-8880-13254eeb155b', 'Kiyimlari kichik bo‘lib qoldimi? 📏', 'Shimining pochasi kalta bo‘lib qolgan bo‘lsa, demak, o‘sish sakrashi boshlangan! Vazn kuzatuvchisiga joriy o‘lchovlarni kiriting va rivojlanish grafigidagi o‘sishni faxr bilan kuzating.'),
  ('9f2ceaa6-0d99-46a0-884c-3460db78351b', 'Sizni tushunadi, ammo gapirmaydimi? 🧠', 'Passiv lug‘at faol lug‘atga qaraganda tezroq rivojlanadi. Bloglar bo‘limida 20 oylik bolaning nutqini rivojlantiradigan uy o‘yinlari haqidagi maqolani albatta o‘qing.'),
  ('f641f443-9a8d-4060-a2b5-fe5d5562fa9d', 'Yashirin vitamin operatsiyasi 🥕', 'Ko‘kat va sabzavotlarni bir chetga surib qo‘yadimi? Chaqaloq retseptlari bo‘limida ismaloq va sabzini mazali blinchiklar ichiga qanday ustalik bilan yashirishni o‘rganing.'),
  ('68ef19de-c144-4be9-8878-9cc1b34a6483', 'Uxlab qolish qancha vaqt oladi? ⏱️', 'To‘shakda uzoq vaqt ag‘darilib yotadimi? Uyqu taymerini yoqib, uxlab qolish uchun qancha vaqt ketishini qayd eting. Balki kechki o‘yinlarni ertaroq tugatish kerakdir.'),
  ('70a3e410-6335-466b-99bc-28ac0c3d913f', 'Nega birdan yig‘laydi? 🤖', 'Kechasi baqirib uyg‘onib, tinchlanmayaptimi? Tungi qo‘rquv haqidagi shubhalaringizni darhol Anacan AI ekspertiga yozing va qanday to‘g‘ri yo‘l tutishni bilib oling.'),
  ('80e71246-05ae-4bc6-857d-5ce3af704b5e', 'Onaning quvvat manbai 🥗', 'Yugurib-yelib, holdan toydingizmi? Shirinlikka emas, oqsilga yuzlaning! Ayollar uchun foydali retseptlardan bir zumda quvvat beradigan yeryong‘oq pastali smuzi tayyorlang.'),
  ('145211fa-74d2-4e28-8a64-c14921db5185', 'O‘zingizni maqtang! 🌟', 'Bugun uni yig‘latmasdan ovqatlantira oldingizmi? Kayfiyat kundaligiga eng kichik yutug‘ingizni ham yozib, onalik mahoratingizni tik turib olqishlang.'),
  ('4f60f5e8-df5e-4892-aa2e-dcffda8f877b', 'Suv muvozanati hayotiy ahamiyatga ega 💧', 'Faol yugurib-o‘ynash tanani suvsizlantiradi. Taglik kuzatuvchisiga ertalabki qaydni kiriting va Tavsiya etilgan mahsulotlar bo‘limida u oson ocha oladigan sport suv idishlarini ko‘rib chiqing.'),
  ('edd993f1-ac76-4300-8ed0-6009d7897f2b', 'Boshqa onalar bilan suhbat ☕', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay joylardan onalar ko‘p yig‘iladigan bolalar kafelarini topib, o‘zingizga ham muloqot qilish imkonini bering.'),
  ('18518788-d8e2-4971-93f7-6fbf0592ca33', 'Urish yoki itarish 🛑', 'Jahli chiqqanda to‘satdan qo‘l ko‘taradimi? 20 oylik davrga xos bu xatti-harakatni o‘yinlar yordamida qanday bartaraf etishni bilish uchun Anacan AI’ga murojaat qiling.'),
  ('a6200253-33e2-4142-a4a9-811aa67d4feb', 'Bugunning qahramoni — sizsiz 🧘‍♀️', 'Bola uxlab qoldi. Barcha uy ishlarini to‘xtating. Kayfiyat kundaligiga his-tuyg‘ularingizni yozing, sokin musiqa qo‘ying va bu oqshomni faqat o‘zingizga bag‘ishlang.'),
  ('eefd67fd-3835-4f65-abf3-9ced6b705e30', 'Ovqatlanish paytidagi sabr sinovi ⏱️', 'Bir qoshiq ovqatni 5 daqiqada yeydimi? Ovqatlanish taymerini yoqing, sabrli bo‘ling va ishtaha dinamikasini ilovadagi hisobot orqali aniq tahlil qiling.'),
  ('070b2f75-0440-4e85-b828-292900301f9e', 'Tasavvurga asoslangan o‘yinlar boshlandi 🧸', 'Ayiqchasiga suv beryaptimi yoki sizni davolayaptimi? Mehr va hamdardlikka to‘la bu ajoyib lahzalarni ovozli video shaklida Chaqaloq albomiga qo‘shib, kelajak uchun saqlang.'),
  ('388f83f4-0bb5-4306-abf6-b75f9dc65017', 'Temir zaxirasini tekshirish 🥩', 'Faol mushaklar va sog‘lom rivojlanish uchun kamqonlik bo‘lmasligi kerak. Ovqatlanishni nazorat qilish vositasi yordamida bugungi temir iste’molini (go‘sht, dukkaklilar) tekshiring va yetishmayotgan miqdorni darhol to‘ldiring.'),
  ('9cb7efe6-c6c0-4032-89de-12eeec5119ee', 'Shovqindan sukunatga o‘tish 🎶', 'Televizor va o‘yinchoqlar shovqinidan keyingi to‘satdan yuzaga kelgan sukunat uni qo‘rqitadi. Xonada Oq shovqinlar bo‘limidan soch quritgich ovozini yoqing va bir maromdagi tovush uyqu muhitiga qanday ijobiy ta’sir qilishini kuzating.'),
  ('6f516c4d-5db5-4d3e-8fca-8c461e614752', 'Temir zaxirasi yetarlimi? 🥩', 'Harakatchan kichkintoyda kamqonlik yuzaga kelmasligi uchun Ovqatlanishni nazorat qilish vositasida bugungi temir iste’molini (go‘sht, dukkaklilar) tekshirib, menyuni moslashtiring.'),
  ('b003834c-8ce3-4da4-a17e-0b837c04f7f7', 'Kalsiy zaxirasini tekshiramiz 🧀', 'Tez o‘sayotgan suyaklarga kalsiy kerak! Ovqatlanishni nazorat qilish vositasi orqali bugun iste’mol qilingan pishloq va qatiq miqdorini tekshirib, yetishmaganini to‘ldiring.'),
  ('b5cae897-2c37-4223-8c5a-201bd9d0229a', 'O‘rmonning sirli tovushlari 🍃', 'Bugun juda shovqinli va injiqliklarga boy kun bo‘ldimi? Oq shovqinlardan barglar shitirlashini yoqib, ham uning, ham o‘zingizning asab tizimingizni tinchlantiring.'),
  ('20cf6725-2fdc-45bb-965b-09069424fe0a', 'Shakarsiz tamaddi 🍪', 'Do‘kondagi pechenyelarga hojat yo‘q. Chaqaloqlar uchun retseptlar orasidan uyda 10 daqiqada tayyorlanadigan xurmo va suli qo‘shilgan foydali shirinliklarni toping.'),
  ('9a0a29d7-d513-4158-b204-99c831639c23', 'Birga, ammo alohida 👶', 'Bog‘da bolalar bilan o‘ynamay, ularni chetdan kuzatyaptimi? Bu parallel o‘yin! Anacan AI’dan ijtimoiylashuvning ushbu bosqichi haqida qiziqarli ma’lumotlarni so‘rang.'),
  ('f527de5c-afa8-4884-a173-da37070a2826', 'Kichkina uy yordamchisi 🧹', 'Siz uyni supurayotganingizda, u ham latta bilan stolni artyaptimi? Bu yoqimli mas’uliyatli lahzani darhol videoga olib, Chaqaloq albomining eng faxrli lavhalaridan biriga aylantiring.'),
  ('847e9a71-981a-4920-b6be-a1986674dd92', 'Stol atrofidagi tugamaydigan tomosha ⏱️', 'Ovqat bilan o‘ynaydi, yerga tashlaydi, ammo yemaydi. Ovqatlanish taymerini yoqing, sabrli bo‘ling va ushbu mustaqillik davrida ishtaha o‘zgarishini ilovadagi grafik yordamida aniq tahlil qiling.'),
  ('890ee8d7-3315-4b7a-994a-c41900d8c960', 'Aqlli o‘yinchoq izlayapsizmi? 🧩', 'Shakllarni mos teshiklarga joylashni o‘rganib oldimi? Tafakkurini yanada charxlaydigan, yoshiga mos pazllarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('8ad462c4-33b5-4c76-be29-aa192feb14a1', 'Oyoq kiyimi siqyaptimi? 📏', 'So‘nggi paytlarda yugurayotganda tez-tez qoqilyaptimi? Oyog‘i o‘sgan bo‘lishi mumkin! Rivojlanish kuzatuvchisiga hozirgi bo‘yi va o‘lchamlarini kiriting hamda jismoniy rivojlanishini kuzatib boring.'),
  ('2e662854-2d0b-4e0d-be84-f71f33b1ed5b', 'Nega birdan yig‘layapti? 🤖', 'Yaxshigina o‘ynab turganida birdan kayfiyati o‘zgarib, yig‘lay boshladimi? Hissiy o‘zgarishlarning sababini aniqlash uchun Anacan AI ekspert yordamchimizga yozing.'),
  ('b30cbe06-794a-4924-bc78-63ebe289b716', 'Tafakkur rivoji to‘xtamaydi 🧠', 'U hamma narsani saralashni yaxshi ko‘radi! Bloglar bo‘limida 20-21 oylik bolalarning rang va shakllarni idrok etishini rivojlantiradigan uy o‘yinlari haqidagi maqolani albatta o‘qing.'),
  ('dcfe0150-6b59-46be-be17-cba289272768', '5 daqiqalik quvvat 🔋', 'Och qoringa qahva ichsangiz, tush paytiga borib quvvatingiz tugaydi. Sog‘lom retseptlar orasidan tez tayyorlanadigan, uzoq vaqt to‘q tutadigan mazali suli keksini tanlang.'),
  ('41523bc6-ac22-4b48-a7b5-8663ed9c74c3', 'Qum terapiyasi 🏖️', 'Kir bo‘lib qolishdan qo‘rqmang! Onalar uchun qulay joylar orasidan qum maydonchasi bor joyni toping. Qumga teginish sensor rivojlanish uchun qimmat o‘yinchoqlardan ko‘ra foydaliroq.'),
  ('863859ae-c920-41fe-b876-915ee50bba17', 'Bo‘yoqqa belangan rassom! 📸', 'O‘zini ham, devorni ham bo‘yab tashladimi? Jahlingiz chiqishi o‘rniga, bu kulgili chizgi-chizgi lahzasini Chaqaloq albomiga yuklang va ustiga qiziqarli stikerlar yopishtiring.'),
  ('af623bf2-6a45-452d-a9c0-bd16d67bf74d', 'Pankeyk mahluqi 🥞', 'Nonushta qilishni istamayaptimi? Chaqaloqlar uchun retseptlar bo‘limidagi shakarsiz bananli pankeyk retseptini sinab ko‘ring. Uni qo‘liga olib o‘zi yeydi, ishtahasi ham ochiladi.'),
  ('a7786d73-a362-4a32-a77f-3c09e4ab2ffb', 'Suv bilan fizika darsi 🛁', 'Vannada suvni bir stakandan boshqasiga quyishdan charchamayaptimi? Ushbu qiziqarli va tinchlantiruvchi suv o‘yinchoqlarini Tavsiya etilgan mahsulotlar bo‘limidan ko‘ring.'),
  ('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793', 'Kalsiy qalqoni 🦴', 'Tishlar va suyaklar uchun kalsiy zarur. Ovqatlanishni kuzatish vositasi yordamida bugungi yogurt va pishloq me’yoriga rioya qilganingizni tekshiring.'),
  ('e8d46282-de1c-4981-9242-f0dff7014b1d', 'Tartibni tahlil qilamiz ⏱️', 'Kechqurun uyg‘oq qolish vaqti juda cho‘zilib ketdimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. Balki kunduzgi uyquni 15 daqiqaga qisqartirishning ayni paytidir.'),
  ('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f', 'Oshqozon-ichak signallari 💩', 'Quyuq ovqatlarga to‘liq o‘tish hazm qilishni qiyinlashtirishi mumkin. Taglik kuzatuvchisiga ertalabki qaydni kiriting va suyuqlik hamda kletchatka muvozanatini to‘g‘rilash zarurligini osongina tekshiring.'),
  ('c4d895de-4842-4a9b-ae46-1557c6e3d2cc', 'Tabiiy tinchlantiruvchi 🍃', 'Kun juda injiqlik va shovqin-suronga boy bo‘ldimi? Oq shovqinlar bo‘limidan barglar shitirlashini yoqib, uning ham, o‘zingizning ham asab tizimingizni tinchlantiring.'),
  ('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3', 'Kiyinish jangi 👗', 'Bu ko‘ylakni xohlamayman! degan qaysarlik tugamayaptimi? Ertalabki kiyinish injiqliklarini kamaytirish uchun Chaqaloq fotosessiyasida uni suratga olishingizni aytib, kiyinishni o‘yinga aylantiring.'),
  ('0daafb47-5c27-4a37-935b-b3612abf5506', 'Kunning qahramoni 🌟', 'U har kuni o‘rganayotgan har bir yangi ko‘nikma — sizning mehnatingiz samarasidir. Kayfiyat kundaligini oching, bugun u uchun qilgan eng kichik yaxshiligingizni ham yozib, o‘zingizdan faxrlaning!'),
  ('3b1eb831-8b25-40be-89a6-b50384eeb49b', 'Gapirmoqchi, ammo... 🗣️', 'Passiv so‘z boyligi faol so‘z boyligidan ko‘pmi? So‘zlarni to‘g‘ri talaffuz qilmasa ham, til rivojidagi bu ajoyib sakrashni qanday qo‘llab-quvvatlash kerakligini Bloglar bo‘limidan o‘qing.'),
  ('a4477b67-ebfc-489b-b2e5-165c0ebb273f', 'Mustaqillikka intilish 🥣', 'Qoshiqni sizga bermayaptimi? Ovqatlanish taymerini ishga tushirib, bu mustaqillik sinovi qancha vaqt olayotganini tahlil qiling. Sochilib ketgan ovqatlarga esa shunchaki tabassum qiling.'),
  ('527e5a17-444d-47c4-8578-4ebb1ee870b1', 'Shirin uyqumi yoki jangmi? 🛌', 'Uxlashga yotish katta inqirozga aylangan bo‘lsa, Anacan AI-dan 21 oylik bolalarni uyquga tayyorlash marosimlari va psixologik usullar haqida darhol so‘rang.'),
  ('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6', 'Tun qanday o‘tdi? 🌙', 'Ertalab taglik juda og‘ir bo‘lsa, tunda suyuqlik ichishini tartibga solish kerak bo‘lishi mumkin. Buni Taglik kuzatuvchisiga qayd etib, kun davomidagi suv muvozanatini tekshiring.'),
  ('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4', 'Barmoqlarning mayda motorikasi 🧩', 'Shakllarni o‘z joyiga qo‘yishni yaxshi o‘zlashtirib oldi. Tafakkurini yanada rivojlantiradigan, yoshiga mos pazllarni Tavsiya etilgan mahsulotlar bo‘limida hoziroq ko‘ring.'),
  ('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60', 'Tinchlanish vaqti 🎶', 'Faol kun miyani charchatishi mumkin. Oq shovqinlar bo‘limidan o‘rmon shitirlashini yoqib, xonada tinchlantiruvchi va uyqu keltiradigan mukammal muhit yarating.'),
  ('d93eedfc-78de-4d26-810d-89c2b8c71690', 'O‘zingizni qahva bilan siylang ☕', 'Kun bo‘yi yugurib, holdan toyibsiz! Onalar uchun qulay joylar xaritasidan bolalar o‘yin maydonchasi bor kafeni topib, o‘zingizga kichik bir yaxshilik qiling.'),
  ('fcfa5044-061e-4832-8787-ddd94f46ab93', 'Yangi so‘z kashfiyoti 🗣️', 'Bugun qanday yangi so‘z aytdi?'),
  ('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94', 'Bo‘y o‘sishi! 📏', 'Farzandingiz birdan bo‘y cho‘zganini sezyapsizmi? Rivojlanish kuzatuvchisiga yangi raqamlarni kiriting va sog‘lom o‘sish grafigiga faxr bilan qarang.'),
  ('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677', 'Quvvat to‘plash vaqti 🔋', 'O‘zingizni unutmang! Sog‘lom retseptlar bo‘limidan ertalab tez tayyorlanadigan, oqsilga boy mazali smuzi tayyorlab, kuchga to‘ling.'),
  ('e61cda6e-e7ca-46f3-a40c-42185a9f8216', '5 daqiqada quvvat ⚡', 'Kunduzi bola uxlaganda uy ishlariga shoshilmang. Sog‘lom retseptlar bo‘limidan antioksidantlarga boy smuzi tayyorlab, tanangizga kuch bering.'),
  ('733a062a-9528-4b89-8399-8894cdcd37ab', 'Birgalikda kitob o‘qish 📖', 'Kitob sahifalarini o‘zi varaqlamoqchimi? Bloglar bo‘limida bu yoshda kitob o‘qishga mehrni o‘yin orqali qanday uyg‘otish haqida ajoyib maqolani o‘qing.'),
  ('840a48c0-60b0-4169-a7a4-bfd97c049d9d', 'Tabiatni kashf etish 🌳', 'Uy devorlari unga torlik qilyaptimi? Ona va bola uchun qulay joylar bo‘limidan keng va xavfsiz bog‘ topib, tabiat qo‘ynida energiyasini sarflashiga yordam bering.'),
  ('fc70b034-70d7-48ac-b093-b541c3d08e54', 'Ertalabki tekshiruv va tahlil 💧', 'Kunning birinchi tagligini almashtirdingizmi? Ajralmalar haqidagi ma’lumotlarni ilovaga kiriting va suyuqlik iste’moli hamda hazm jarayoni yetarli ekanini oson kuzating.'),
  ('205f33e0-59b6-4cce-bdf2-72feb1805167', 'Foydali shirinlik izlayapsizmi? 🍪', 'Shakarsiz, ammo mazali yegulik xohlaysizmi? Chaqaloqlar uchun retseptlar bo‘limida 10 daqiqada tayyorlanadigan bananli va xurmoli pechenyelarni kashf eting.'),
  ('db60a4c8-3ab7-4727-9545-2ff3fea13946', 'Qaysarona «Yo‘q!» 🛑', 'Hamma narsaga qarshilik qilib, baqiryaptimi? 21 oylik davrdagi qaysarlik haqida Anacan AI yordamchimiz bilan maslahatlashing va hissiy xurujlarni boshqarishni o‘rganing.'),
  ('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36', 'Uyqu rejimini tekshiramiz ⏱️', 'Kechasi tez-tez uyg‘onadimi? Uyqu taymeridagi jadvalni tahlil qiling. Balki kunduzgi uyquni biroz qisqartirib, kechga borib ko‘proq charchashiga yordam berish kerakdir.'),
  ('87662f03-ab51-47a9-bb0d-dc1172cdf859', 'Vitaminlar manbai 🥗', 'Ovqatlanishni nazorat qilish vositasi yordamida bugungi vitamin ehtiyojini hisoblab, menyuni rejalashtiring. Omega-3 va D vitamini muvozanatini albatta tekshiring.'),
  ('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7', 'Mantiqiy o‘yinchoqlar 🧩', 'Bu yosh mantiqiy o‘yinlar uchun ayni muddao. Tavsiya etilgan mahsulotlar bo‘limida yoshiga mos pazllar va shakllarni saralash o‘yinchoqlarini topib, zehnini charxlang.'),
  ('b4b68202-2497-420c-9cf0-d0f43130a249', 'Ko‘nglingizdagilarni yozing 📝', 'Har bir kun mukammal bo‘lavermaydi va bu tabiiy. Bugungi ichki kechinmalaringizni Kayfiyat kundaligiga yozing, stressdan xalos bo‘lib, xotirjam dam oling.'),
  ('8139b24d-f8c3-4b60-b4f1-38bd25e609a6', 'Qoshiq qo‘lidan tushmayaptimi? 🥄', 'Ovqatlanish taymerini yoqing. Mustaqil ovqatlanishga urinishlari qancha davom etishini tahlil qiling va ilovada kunlik ovqatlanish me’yorini tekshiring.'),
  ('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91', 'Qum terapiyasi 🏖️', 'Kir bo‘lishdan qo‘rqmang! Kinetik qum yoki sensor o‘yinlar uchun eng yaxshi vositalarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('f71cc78c-d1eb-4694-b94a-1843f80e2db1', 'Tinchlantiruvchi to‘lqinlar 🌊', 'Faol kashfiyotlarga boy kundan keyin uxlay olmayaptimi? Oq shovqinlardan okean to‘lqinlari ovozini tanlang, xonada sehrli osoyishtalik yaratib, uni uyquga tayyorlang.'),
  ('3787f491-d618-4351-acd6-86ff87689c17', 'Urish va itarish 🛑', 'Jahli chiqqanda birdan qo‘l ko‘taradimi yoki tishlaydimi? 21-oyga xos bu xatti-harakatni mehr bilan qanday hal qilish mumkinligini Anacan AI’dan so‘rang.'),
  ('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce', 'Oqsil zaxirasi qanday? 🍗', 'Bolaning o‘sishi uchun oqsil juda muhim! Ovqatlanishni nazorat qilish vositasi yordamida uning kundalik oziq-ovqat muvozanatini baholang va yetishmayotganlarini to‘ldiring.'),
  ('e90a6ec1-ff62-4f86-8635-bb93512c7c35', 'Taymer yordamida uyqu tahlili ⏱️', 'Uxlash vaqti bo‘ldi! Uyqu taymerini ishga tushiring, kunlik uyqu me’yoriga amal qilayotganiga ishonch hosil qilish uchun uning rejimini tahlil qiling va dam oling.'),
  ('03d03133-0370-4630-9d2e-153f9459d86d', 'Uyqudan qichqirib uyg‘onadimi?', 'Xona chirog‘ini yoqmasdan, Oq shovqinlardan ona qornidagi tovushni qo‘yib, unga o‘zini xavfsiz his qilishiga yordam bering va yana uxlatib qo‘ying.'),
  ('8ed6f8ef-f210-4aaa-96f8-4667b80d657e', 'Hamma narsaga Yo‘q! 🛑', 'Barcha takliflaringizga qarshilik qiladimi? O‘jarligi bilan kurashish o‘rniga, unga to‘g‘ri tanlovlarni qanday taklif qilish haqida Anacan AI’dan darhol so‘rang.'),
  ('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c', 'Tunda suyuqlik ichish 🚰', 'Ertalab tagligi juda og‘ir bo‘lsa, kechqurun suv ichishini tartibga solish kerak bo‘lishi mumkin. Taglik kuzatuvchisiga qayd etib, kundalik statistikani ko‘rib chiqing.'),
  ('0b3896bc-de1d-4dd2-b68d-bd0aa3890750', 'Kunduzgi uyqu cho‘zilyaptimi? ⏱️', 'Kechqurun uxlashga qarshilik qiladimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. Balki kunduzgi uyqudan juda kech uyg‘onayotgandir?'),
  ('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d', 'Kalsiy va suyaklar 🦴', 'Jadal jismoniy rivojlanish uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida pishloq va qatiqqa bo‘lgan ehtiyojni hisoblang, yetishmasa, Chaqaloq retseptlarini ko‘rib chiqing.'),
  ('c7f42861-81dc-4ed2-b93f-7c30709d92ed', 'Holdan toyganingizni his qilyapsizmi? 🔋', 'Quvvatingiz tugadimi? Shirinlikka yopishmang. Ayollar uchun sog‘lom retseptlardan shakarsiz, tezda quvvat beradigan energetik sharchalar tayyorlab, o‘z batareyangizni quvvatlang.'),
  ('0ac93f21-93e2-449d-b93b-ae00befc33f7', 'Qorong‘ilikdan qo‘rqadimi? 🌌', 'Xona chirog‘ini o‘chirganingizda bezovta bo‘ladimi? Oq shovqinlardan ona qornidagi tovushni (yurak urishini) yoqib, unga iliqlik va xavfsizlik hissini bering.'),
  ('5831d6e0-9735-485f-be90-56915bc7047f', 'Endi navbat sizda 🥗', 'Bola uxlagan bo‘lsa, oshxonaga o‘ting! Ayollar uchun foydali retseptlardan bir zumda quvvat beradigan oqsilli salat yoki detoks ichimligini kashf eting.'),
  ('5c1e8139-b38e-4666-8558-f6706af826d7', 'Kichkina rassom ish ustida 🖍️', 'Chizishni yaxshi ko‘radimi? Kiyimlari bo‘yoq bo‘lib ketsa ham, jahlingiz chiqmasin! Ushbu ijodiy lahzani darhol Chaqaloq albomiga qo‘shib, umrbod xotiraga aylantiring.'),
  ('04f3e5a5-25b9-471b-9c8e-e6c96050313b', 'Rang-barang immunitet qalqoni 🛡️', 'Ovqatlanishni nazorat qilish vositasi yordamida bugun yetarli miqdorda C vitamini olganini tekshiring. Rang-barang sabzavotli taomlar uchun Chaqaloq retseptlariga murojaat qiling.'),
  ('41231bd2-e2dd-4432-bc31-3952982f012e', 'Tishlar tozalanyaptimi? 🪥', 'Tish cho‘tkasini ko‘rishi bilan qochadimi? Tavsiya etilgan mahsulotlar bo‘limidan musiqali yoki barmoqqa kiyiladigan cho‘tkalarni ko‘rib, bu muhim gigiyena jarayonini qiziqarli o‘yinga aylantiring.'),
  ('9603c325-693c-472c-b02b-2c75bd255571', 'Kunning qahramoni — sizsiz! 🌟', 'Barcha injiqliklar va charchoqqa qaramay, siz ajoyibsiz! Kayfiyat kundaligini oching va bugun o‘zingizni olqishlashga arziydigan qayd yozing.'),
  ('2ecfbac7-2e44-4661-8705-95fe2f59e9a9', 'Mukammallikka intilishni qo‘yib yuboring 🧘‍♀️', 'Uy tartibsizmi? Hechqisi yo‘q! Kayfiyat kundaligiga his-tuyg‘ularingizni yozing. Unutmang, baxtli ona mukammal uydan muhimroq.'),
  ('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1', 'Sizga ham tanaffus kerak ☕', 'Uydan chiqib, biroz toza havodan nafas oling! Ona uchun qulay joylar bo‘limidan yaqin atrofdagi bolalar burchagi bor kafeni toping va issiq qahvangizni xotirjam iching.'),
  ('f9b61a4f-eba1-4cee-bf4a-958278a9300c', 'Uyning kichkina bosh oshpazi 👩‍🍳', 'Oshxonada sizga yordam berib, qozonlarni aralashtiryaptimi? Ust-boshi unga belangan bu kulgili lahzani Chaqaloq fotosessiyasidagi oshpaz stikerlari bilan bezang.'),
  ('2c0cd78a-df37-49ab-8eae-44063551c7d9', 'Pazl ustasi 🧩', 'Shakllarni moslashtirishni o‘zlashtiryaptimi? Zehnini charxlash uchun Tavsiya etilgan mahsulotlar bo‘limida 21 oylik bolalarga mo‘ljallangan geometrik boshqotirmalarni toping.'),
  ('eeefba30-2a67-4d29-87df-2dbd7f03271f', 'Kitob yirtishga ishtiyoq 📖', 'O‘qish o‘rniga sahifalarni yirtyaptimi? Bloglar bo‘limida kitob o‘qish odatiga zarar yetkazmasdan bu muammoni qanday hal qilish mumkinligini hoziroq o‘qing.'),
  ('f7f548f7-29ae-4098-8eb1-12f16f94c4b9', 'Ovqat bilan o‘ynash bosqichi 🥣', 'Qoshiqni chetga uloqtirib, ovqatni qo‘li bilan ushlayaptimi? Ovqatlanish taymerini yoqing, ishtaha dinamikasini tahlil qiling va bu sensor rivojlanish bosqichiga sabr bilan yondashing.'),
  ('3512adbc-96b2-42e9-8a54-b673dc404876', 'Kechki qahqahalar 📸', 'Uxlashdan oldin qiladigan o‘sha kulgili harakatini o‘tkazib yubormang! Darhol videoga olib, Chaqaloq albomiga qo‘shing va kun charchog‘ini tabassumga aylantiring.'),
  ('42cda594-bd4d-4a45-a1f6-1f894ad11fe7', 'Yangi so‘zlar kelmoqda! 🗣️', 'Ko‘p tovush chiqaradi-yu, ammo hali to‘liq so‘z aytmayaptimi? Anacan AI orqali passiv lug‘atni faollashtirish uchun eng samarali uy o‘yinlari va bo‘g‘in mashqlarini o‘rganing.'),
  ('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54', 'Oyoq kiyimi tor bo‘lib qoldimi? 👟', 'So‘nggi paytlarda yugurayotganda tez-tez qoqilyaptimi? Oyog‘i o‘sgan bo‘lishi mumkin! Joriy o‘lchamlarni Rivojlanish kuzatuvchisiga kiriting va o‘sishini kuzatib boring.'),
  ('8ae66558-ee37-4cd1-9102-46bab1a97b21', '5 daqiqalik mazali tamaddi! 🥗', 'Tushlikda yo‘l-yo‘lakay biror narsa yeb olyapsizmi? Ayollar uchun sog‘lom retseptlardan sizni to‘q tutadigan va tezda quvvat beradigan avokadoli tost tayyorlang.'),
  ('a3eb6f02-e9da-422e-a243-1f395cf4661e', 'Uyqu vaqti surilyaptimi? ⏱️', 'Kechqurun uyg‘oq qolish muddati uzaydimi? Uyqu taymerini ishga tushiring va jadvalni tahlil qilib, uyqu oraliqlarini qayta hisoblang.'),
  ('aac102d8-edd5-4708-bab2-8cf3fcc9802c', 'Ovqat hazm qilish sekinlashdimi? 🚽', 'Ertalab tagligini almashtirayotganda najasini kuzating. Ich qotishi bo‘lsa, buni ilovada qayd eting va menyuga tolaga boy mahsulotlar (nok, suli) qo‘shishni unutmang.'),
  ('5bf406ee-d6c9-4691-8b5e-2df617ed2939', 'Tabiatni kashf etish 🌳', 'Uy devorlari unga torlik qilyaptimi? Onalar uchun qulay joylar orasidan katta qum maydonchasi va arg‘imchoqlari bor xavfsiz bog‘ni topib, toza havoga chiqing.'),
  ('ad873c49-3118-429c-a9cf-3328699e514f', 'Makaronlar qochishi! 🍝', 'Ovqatlanish stolida o‘tirishni istamayaptimi? Chaqaloqlar uchun retseptlardagi rang-barang, sabzavotli makaron g‘oyalarini ko‘rib, uning e’tiborini yana likopchaga qarating.'),
  ('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42', 'Bir maromdagi tovushning kuchi 🌬️', 'Sukunat uni qo‘rqityaptimi? Xonada Oq shovqinlar orasidan soch quritgich yoki ventilyator tovushini yoqib, bu tovush uyqu muhitida qanday qilib xavfsizlik hissini yaratishini kuzating.'),
  ('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5', 'O‘zingizni maqtang! 🌟', 'Bugun uni yig‘latmasdan kiyintira oldingizmi? Kayfiyat kundaligiga eng kichik yutug‘ingizni ham yozib, onalik mahoratingiz uchun o‘zingizni olqishlang.'),
  ('5d85dda7-f62e-4490-8b4e-2ca037fd60ac', 'Immunitet qalqoni 🛡️', 'Fasl almashishiga tayyormisiz? Ovqatlanishni nazorat qilish vositasi orqali u bugun yetarli miqdorda Vitamin C olganini tekshiring va menyuni yangilang.'),
  ('680f971c-231a-40e8-a772-413975915698', 'Urish va itarish 🛑', 'Birdan jahli chiqqanida qo‘l ko‘taradimi yoki itaradimi? 21.5 oylik davrdagi bu qiyin xatti-harakatni o‘yinga aylantirib qanday yengish mumkinligini Anacan AI-dan so‘rang.'),
  ('4bdcd931-fb36-41ca-9759-7a92226d97f9', 'To‘yganini qanday bilamiz? ⏱️', 'Ovqatni tashlay yoki tupura boshlasa, demak, to‘ygan. Ovqatlantirish taymerini to‘xtating, me’yor bajarilganini qayd etib, ishtahasini tahlil qiling.'),
  ('be36c558-6f81-4ee5-9a59-f79497bbff2d', 'Tish yuvish janjali 🪥', 'Tish cho‘tkasini ko‘rishi bilan qochadimi? Tavsiya etilgan mahsulotlar bo‘limidan musiqali yoki barmoqqa kiyiladigan cho‘tkalarni tanlab, bu muhim gigiyena jarayonini qiziqarli o‘yinga aylantiring.'),
  ('cd9296b3-74e7-4229-8871-9f5ee4fe977a', 'Onaning suv muvozanati 💧', 'Boshingiz og‘riyaptimi? Bolaning ortidan yugurib, suv ichishni unutgansiz. Ayollar uchun foydali retseptlar bo‘yicha detoks suvlari tayyorlab, tanangizni tetiklashtiring.'),
  ('2fbfd933-5095-452a-808e-4209aab75b80', 'Sizga ham muloqot kerak 👯‍♀️', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay maskanlar bo‘limidan o‘yin guruhlari mavjud markazlarni topib, boshqa onalar bilan tanishing.'),
  ('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc', 'Kichkina taqlidchi 📱', 'Siz kabi telefonda gaplashib, harakatlaringizga taqlid qiladimi? Bolalar — eng yaxshi ko‘zgu!'),
  ('bf157f3f-185f-45b5-aae0-091b2cf00653', 'Birga, ammo alohida 👶', 'Bog‘da boshqa bolalar bilan o‘ynamay, faqat kuzatadimi? Bu parallel o‘yin! Bloglar bo‘limida ijtimoiylashuvning ushbu bosqichi haqida qiziqarli ma’lumotlarni bilib oling.'),
  ('9faf82e4-78ff-4782-a4bb-0d745a808c97', 'Yashil rangga qarshilik 🥦', 'Sabzavotlarni rad etyaptimi? Qo‘shimcha ovqatni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan sabzavotlarni mazali quymoq ichiga qanday yashirish mumkinligini bilib oling.'),
  ('c2142ff9-9553-4737-9602-95ee907b4599', 'Charchoqqa taslim bo‘lmang 🛋️', 'Bugun hamma narsani tashlab qo‘ygichingiz keldimi? Bu normal holat! Kayfiyat kundaligini oching, ichingizdagi siqilishni yozib, bu oqshomni faqat o‘zingizga bag‘ishlang.'),
  ('cc7b1b1f-1c7c-4424-996a-a223a00c890e', 'Tagligi quruq qolyaptimi? 🧻', 'Ertalabki tekshiruv! Agar tagligi uzoq vaqt quruq qolsa, tuvakka o‘rgatish vaqti yaqinlashgan bo‘lishi mumkin. Taglik kuzatuvchisiga qayd etib, statistikani tekshiring.'),
  ('3e9ffaf8-f631-4e99-946e-651b683eab7f', '“Ona, keling!” kabi gaplar 🗣️', 'Endi ikkita so‘zni birlashtirib, gap tuzishga urinayaptimi? Bu — nutq rivojlanishidagi katta sakrash! Rivojlanish kuzatuvchisiga uning ilk kichik gaplarini esdalik sifatida qayd eting.'),
  ('473def83-9d3b-4698-becd-a16f81aed11d', 'Do‘kondagi janjallar 🛒', 'Do‘konda xohlagan narsasini olib bermaganingiz uchun o‘zini yerga tashladimi? Vahimaga tushmang. Atrofdagilarning nigohlariga e’tibor bermay, xotirjamlik bilan uning ko‘zlari darajasigacha egiling.'),
  ('fdbb311e-3b42-4723-986f-c65a632fb53e', 'Hissiy yukdan xalos bo‘ling 📝', 'Kun og‘ir o‘tdimi? Bugungi stressingizni Kayfiyat kundaligiga yozib, ko‘nglingizni bo‘shating. Barcha onalar jamoat joylarida bunday janjallarga duch keladi, siz yolg‘iz emassiz.'),
  ('6b045729-7aac-44f1-99aa-a2dbeb7985f2', 'Ro‘yxat hayotni qutqaradi 🛒', 'Xotirangiz yana pand berdimi? Uyda tugagan har bir mayda narsani eslab yurishga urinmang, darhol Xaridlar ro‘yxatiga qo‘shing, qolganini turmush o‘rtog‘ingiz hal qilsin.'),
  ('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba', 'To‘p tepish ⚽', 'Yerdagi to‘pni oyog‘i bilan tepishga urinyaptimi? Muvozanatni saqlash va oyoq harakatlarini muvofiqlashtirish qobiliyati takomillashmoqda. U bilan kichik pas berish o‘yinini o‘ynang.'),
  ('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1', 'Sehrli tun muhiti 🪄', 'Uxlab qolishga qiynalyaptimi? Aqlli ertaklar bo‘limida o‘ziga xos ertak yarating va o‘qib bering.'),
  ('51155148-f9ec-40a7-99a1-3f09cffe59c1', 'Dadaning maydonchasi 👨‍👧', 'Sabringiz tugadimi? Xona eshigini yoping va bolani dadasi bilan yolg‘iz qoldiring. Bu oqshom uydagi o‘yin maydonchasiga dadasi boshchilik qilsin.'),
  ('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739', 'Kiyim tanlashdagi qaysarlik 👗', 'Yozda qalin sviter, qishda esa yozgi ko‘ylak kiyishni xohlayaptimi? Uning irodasi shakllanmoqda. Mos keladigan ikkita kiyimni chiqarib, «Qaysi birini xohlaysan?» deb tanlovni unga qoldiring.'),
  ('c6ce4007-ba3b-4772-8fba-7c4797ad17dd', 'Toza havo — davo 🌳', 'Bola juda bezovta bo‘lib, uyda turolmayaptimi? Ob-havo va kiyimini tekshirib, darhol parkka yo‘l oling. Tabiat uning uchun eng tez ta’sir qiladigan tinchlantiruvchi vositadir.'),
  ('02902252-366d-405a-a62b-9c6f129b4a84', 'Aql-zakovat qanday rivojlanadi? 🧠', 'Bloglar bo‘limida 21.5 oylik bolalarning rang va shakllarni idrok etishini yaxshilaydigan, miyani rag‘batlantiradigan uy o‘yinlari haqidagi maqolani albatta o‘qing.'),
  ('08bbbba1-9e53-4379-a09e-82d1079f7df6', 'Temir zaxirasini tekshirish 🥩', 'Mushaklar faol harakatlanishi uchun qon kamligi bo‘lmasligi kerak. Ovqatlanishni nazorat qilish vositasi yordamida bugun qancha temir qabul qilinganini tekshiring va yetishmovchilikni darhol to‘ldiring.'),
  ('cd9b8bec-56d4-42a3-a245-f71b148a61ef', 'Shovqindan sukunatga o‘tish 🎶', 'Shovqinli o‘yinlardan keyingi to‘satdan sukunat uni qo‘rqitadi. Xonada Oq shovqinlar bo‘limidan fen ovozini yoqing va bir maromdagi tovush uyquga qanday ijobiy ta’sir qilishini kuzating.'),
  ('54f26234-4c50-45b3-9088-6a5b0c08fcd2', 'Onaning suv muvozanati 💧', 'Boshingiz og‘riyaptimi? Bolaning ortidan yugurib, yetarli suv ichmagan bo‘lishingiz mumkin. Foydali retseptlar bo‘yicha detoks suvlari tayyorlab, organizmingizni tetiklashtiring.'),
  ('a27861d3-4efc-4b58-bec5-f3117fe589e3', 'Saralash o‘yinlari 🔴🔵', 'Qizil narsalarni bir tomonga, ko‘klarini boshqa tomonga yig‘ishni yoqtiradimi? Mantiqiy rivojlanishni yanada qiziqarli qilish uchun Anacan AI’dan o‘yin g‘oyalarini so‘rang.'),
  ('d5617275-bfe2-4829-8f3f-d3b94dc34cfe', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechqurun uyg‘oq qolish vaqti juda uzayib ketdimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. Balki kunduzgi uyquni 15 daqiqaga qisqartirishning ayni vaqtidir.'),
  ('53a89401-1ea0-43b5-9469-65a0d422f72c', 'Stol atrofidagi tugamaydigan tomosha 🥣', 'Ovqat bilan o‘ynaydi, yerga tashlaydi, ammo yemaydi. Ovqatlanish taymerini yoqing va ishtaha dinamikasini ilovadagi grafik orqali aniq tahlil qiling.'),
  ('86da0f7a-f021-4c65-aed2-e8e15433a92d', 'Aylantirishga qiziqish 🌀', 'G‘ildiraklar yoki qopqoqlarni tinmay aylantiradimi? Bu o‘ziga xos motorika ehtiyoji va uning aqliy rivojlanishdagi o‘rni haqida Bloglardan o‘qing.'),
  ('9ea6bc21-5003-4afe-8fca-e2eebb549250', 'Qum terapiyasi 🏖️', 'Kir bo‘lishdan qo‘rqmang! Onalar uchun qulay joylar orasidan qum maydonchasi bor joyni toping. Qumga teginish sensor rivojlanish uchun juda foydali.'),
  ('081299bb-b5c9-4af5-8361-9fa39bbdf0bf', 'Qabziyat muammosi bormi? 🚽', 'Ertalab tagligini almashtirayotganda najasini kuzating. Qabziyat bo‘lsa, ilovaga qayd eting va qo‘shimcha ovqatlanishni boshlagan chaqaloqlar uchun Retseptlardan tolaga boy mahsulotlarni (nok, suli yormasi) tanlang.'),
  ('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb', 'Rassom ish ustida 🎨', 'Chizib-bo‘yayotganda o‘zini ham bo‘yab tashlaydimi? Zararsiz, yuviladigan bo‘yoqlarni Tavsiya etilgan mahsulotlar bo‘limida onalar eng ko‘p tanlaydigan mahsulotlar orasidan toping.'),
  ('f9d59314-c8fe-45fa-9d77-efb82ec57626', 'Kechki qahqahalar 📸', 'Uxlashdan oldin qiladigan o‘sha kulgili harakatini o‘tkazib yubormang!'),
  ('34d9fbb9-7747-4964-9067-399afa7f0a7c', 'Tabiiy tinchlantiruvchi 🍃', 'Bola uxlab qoldi. Uy ishlarini unuting! Ayollar uchun sog‘lom retseptlardan melissa choyini damlang, divanga cho‘zilib, shunchaki sukunatdan zavqlaning.'),
  ('e79393de-a250-4c25-b9a8-93a1bc3692aa', 'C vitamini qalqoni 🍊', 'Immunitet kuchli bo‘lishi kerak. Ovqatlanishni nazorat qilish vositasi yordamida bugun yetarli miqdorda C vitamini olganingizni hisoblang va menyuingizga rang-baranglik qo‘shing.'),
  ('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7', 'Kiyinish jangi 👗', '“Bu ko‘ylakni xohlamayman!” degan qaysarlik boshlandimi? Ertalabki kiyinish injiqliklarini kamaytirish va unga mustaqil tanlash huquqini berish yo‘llarini Anacan AI’dan bilib oling.'),
  ('2a640acf-5bf6-44d4-b56f-00e902c2ddd2', 'Mustaqillikka intilish 🥣', 'Qoshiqni sizga bermayaptimi? Ovqatlanish taymerini ishga tushirib, bu mustaqillik sinovi qancha vaqt olishini tahlil qiling. Sochilib ketgan ovqatlarga esa shunchaki jilmaying.'),
  ('cb94164a-0ea2-471c-9c17-a09778ea707c', 'Ajralishdan qo‘rqyaptimi? 🌌', 'Xonadan chiqishingiz bilan ortingizdan yig‘laydimi? Oq shovqinlardan ona qornidagi yurak urishi tovushini yoqib, unga avvalgi iliq va xavfsiz tuyg‘uni qaytaring.'),
  ('d3ae908a-552f-4504-a171-436173eaeceb', 'Tish yuvish janjali 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini mahkam yumib oladimi? Tavsiya etilgan mahsulotlardan musiqali yoki barmoqqa kiyiladigan cho‘tkalarni ko‘rib, bu gigiyena odatini qiziqarli o‘yinga aylantiring.'),
  ('4932b8a8-d024-498c-ba06-d790b59bc198', 'O‘zingizga mehribon bo‘ling 🧘‍♀️', 'Bugun hamma narsa teskari ketdimi? Kayfiyat kundaligiga ichki kechinmalaringizni yozing, o‘zingizni kechiring, chuqur nafas oling va dam oling.'),
  ('ed014436-2469-48a6-b579-7bce93de1ae7', 'So‘z boyligi kengaymoqda 🗣️', 'Ikki so‘zli gaplari ko‘payyaptimi? Uning bu ajoyib nutqiy rivojlanishini qanday qo‘llab-quvvatlash va u bilan muloqot qilish kerakligini hoziroq Anacan AI’dan so‘rang.'),
  ('ed579060-f78c-4890-b8e4-2bb0c7729792', 'Najasning rangi 💩', 'Taglikni almashtirganda qayd eting! Suyuqlik va kletchatka muvozanatini kuzatib, qabziyatning oldini olish uchun Ovqatlanishni nazorat qilish vositasidan foydalaning.'),
  ('15f9bb81-a16f-4753-a3f5-a2b604b16a46', 'Ochiq havoda uxlash 🌳', 'Uyda uxlay olmayaptimi? Onalar uchun qulay joylar orasidan sokin, daraxtzor bog‘ toping. Toza havo uning ham ishtahasini ochadi, ham uyqusini yaxshilaydi.'),
  ('1e63b6e0-14e2-4999-89f7-2f0db3539031', 'Tunda uyg‘onishlar ⏱️', 'Uyqu taymerini ishga tushiring! Bu tungi vahima yoki uyqu regressiyasi ekanini taymerning statistik grafigi orqali darhol tahlil qiling.'),
  ('8665ce13-4bbc-4643-86cd-402909af004b', 'Temirga ehtiyoj 🥩', 'Harakatchan mushaklarini oziqlantiring! Ovqatlanishni nazorat qilish vositasi yordamida bugun yetarli miqdorda temir olganini tekshirib, menyusini moslashtiring.'),
  ('2097babe-f9a8-45d7-927c-24d3ef08f38a', 'Kulgi sadolari 📸', 'Yuzini burishtiryaptimi yoki sizga qarab qah-qah otib kulyaptimi? Bu shirin lahzani Chaqaloq fotosessiyasidagi stikerlar bilan bezatib, albomga abadiy xotira sifatida qo‘shing.'),
  ('3d45eb72-a379-4b0c-95b5-43a9f90cd232', 'Bir maromdagi tovushning kuchi 🎶', 'Shovqinli kundan keyin to‘satdan cho‘kkan sukunat uni qo‘rqitadi. Oq Shovqinlardan fen tovushini yoqib, uxlash muhitida xavfsizlik hissini yarating.'),
  ('af588f6b-bdb1-4b34-b380-81bc42d5db3f', 'Onaning quvvati 🔋', 'Quvvatingiz tugadimi? Shirinlikka yopishmang! Ayollar uchun foydali retseptlardan tezda quvvat beradigan, oqsilga boy yeryong‘oq pastali smuzi tayyorlang.'),
  ('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248', 'Kiyimlar yana torayaptimi? 📏', 'Jismoniy o‘sish sakrashi boshlandi! Rivojlanish Kuzatuvchisiga uning hozirgi bo‘yi va oyoq kiyim o‘lchamini kiriting hamda o‘sish egri chizig‘i qanday yuqorilayotganini faxr bilan kuzating.'),
  ('5bace5b1-8b66-491f-869e-157ff26e9bbf', 'Mantiqiy izlanish 🧩', 'Bir xil o‘yinchoqlardan zerikdimi? Tafakkurini charxlaydigan, yoshiga mos va xavfsiz pazllarni Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('e03c5d95-be6c-414b-b518-86431da64323', 'To‘satdan urish va tishlash 🦖', 'Jahli chiqqanda tajovuzkor bo‘lib qoladimi? Anacan AI yordamida bu xatti-harakatni o‘yinga aylantirib, uni qanday qilib muloyimlik bilan o‘zgartirishni o‘rganing.'),
  ('53335520-c239-4dc6-bb98-8950aeac052d', 'Sabzavotlar bilan yashirin o‘yin 🥕', 'Sabzi va ismaloqni rad etyaptimi? Chaqaloq retseptlarida bu vitaminlarga boy mahsulotlarni mazali blinchiklar ichiga qanday mahorat bilan yashirish mumkinligini bilib oling.'),
  ('9cc1439a-0d58-4e5e-94b1-3125467bf825', 'O‘zingizni aybdor his qilmang 💖', 'Bugun ovozingizni balandlatib yubordingizmi? O‘zingizni ayblamang. His-tuyg‘ularingizni Kayfiyat kundaligiga yozing — siz baribir uning uchun eng yaxshi onasiz.'),
  ('bd4e1f9a-2949-4f64-b861-47344e3cdbfc', 'Stol atrofidagi tuganmas tomosha ⏱️', 'Ovqat bilan o‘ynaydi-yu, lekin yemaydimi? Ovqatlanish taymerini yoqing, jarayon qancha davom etishini kuzating va ishtahadagi o‘zgarishlarni aniq tahlil qiling.'),
  ('31a9cc16-de41-4012-b357-b74232182120', 'Kunning qahramoni — sizsiz 🌟', 'U har kuni o‘rganayotgan har bir yangi ko‘nikma — sizning mehnatingiz samarasi. Kayfiyat kundaligini oching va bugun o‘zingizni tik turib olqishlashga arziydigan qayd yozing!'),
  ('39267d40-2480-48f4-9716-e425031ba3b3', 'Birga, ammo alohida 👶', 'Bog‘da boshqa bolalar bilan o‘ynamay, faqat kuzatyaptimi? Bu parallel o‘yin! Bloglar bo‘limida ijtimoiylashuvning ushbu sog‘lom bosqichi haqida o‘qing.'),
  ('7ae07c2d-565f-4b45-bebf-b9e3ab799a99', 'Shakarsiz gazak 🍪', 'Do‘kondagi pechenyelar shart emas. Chaqaloq retseptlarida uyda 10 daqiqada tayyorlanadigan, xurmo va olmali foydali shirinliklarni kashf eting.'),
  ('4c3b97db-69e0-4349-8a8d-b599fed49f3d', 'Tungi taglik to‘lib qoladimi? 🧻', 'Ertalab taglik juda og‘ir bo‘lsa, tungi uyqu buzilishi mumkin. Taglik kuzatuvchisiga ajralmalarni qayd eting va kechki payt suyuqlik iste’molini tartibga solish uchun statistikani tahlil qiling.'),
  ('c15f640c-d99c-497d-be3f-c7f256e90fd8', 'Oshxonadagi kashfiyotchi 🥦', 'U ham siz bilan birga ovqat tayyorlashni xohlayaptimi? Qo‘shimcha ovqat yeyishni boshlagan chaqaloqlar uchun Retseptlar bo‘limidan birgalikda tayyorlashingiz mumkin bo‘lgan oson, sabzavotli va mazali keks retseptlarini toping.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('e02612f3-415f-450d-9411-e60c3bd32d09'::uuid, 'Sukunat sadosi 🌧️', 'Juda serharakat kundan keyin miyani tinchlantirish kerak. Xonada Oq shovqinlar bo‘limidan yomg‘ir ovozini yoqib, uyqu muhitini tabiiy ravishda osoyishta qiling.'),
  ('3dca59c4-0add-4ccb-919d-3806c0dfdbf4', 'Tabiiy tinchlantiruvchi 🍃', 'Kun juda injiqlik va shovqin-suronga boy bo‘ldimi? Oq shovqinlar bo‘limidan barglar shitirlashini yoqib, uning ham, o‘zingizning ham asab tizimingizni tinchlantiring.'),
  ('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8', '5 daqiqalik quvvat ⚡', 'Ertalab uy ishlariga shoshilmang. Sog‘lom retseptlar bo‘limidan antioksidantlarga boy rezavorli suli bo‘tqasini tayyorlab, tanangizga quvvat bering.'),
  ('e5117ef0-d242-45f1-b114-50b3bfca72d9', 'Sizga ham davra kerak ☕', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay joylar bo‘limidan onalar ko‘p yig‘iladigan bolalar kafelarini topib, yangi tanishlar orttiring.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'Ertakni o‘zi aytib bersin 📖', 'Kitobdagi rasmlarga qarab, o‘z tilida nimalarnidir gapirib beryaptimi? Tasavvurga boy bu ajoyib lahzani darhol ovozli video tarzida Chaqaloq albomiga qo‘shib, kelajak uchun saqlab qo‘ying.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'To‘rt devor orasidan chiqing 🌳', 'Uyda kuch-quvvatini sarflay olmay, hamma narsani ag‘dar-to‘ntar qilyaptimi? Ona uchun qulay joylar xaritasini oching, xavfsiz yugurish maydoni bor bog‘ni topib, toza havoga chiqing.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'Bo‘lishishni istamayaptimi? 🧸', 'Bog‘da o‘yinchog‘ini hech kimga bermayaptimi? Bloglar bo‘limida 22 oylik bolalarga navbat bilan o‘ynash tushunchasini o‘rgatishga bag‘ishlangan amaliy maqolani albatta o‘qing.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'Kalsiy qalqoni 🦴', 'Suyaklar va tishlar uchun kalsiy juda zarur. Ovqatlanishni nazorat qilish vositasi orqali bugungi qatiq va pishloq me’yoriga rioya qilganingizni tekshiring.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'Oyoq kiyimi siqyaptimi? 📏', 'So‘nggi paytlarda yugurayotganda tez-tez qoqilyaptimi? Oyog‘i o‘sgan bo‘lishi mumkin! Vazn kuzatuvchisiga hozirgi bo‘yi va o‘lchamlarini kiritib, jismoniy rivojlanishini kuzatib boring.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'Ovqatni yerga tashlayaptimi? 🥣', 'Qoshiq va ovqatni stoldan pastga tashlay boshlagan bo‘lsa, qorni to‘ygan yoki zerikkan bo‘lishi mumkin. Ovqatlanish taymerini to‘xtating, ishtaha o‘zgarishini grafik orqali tahlil qilib, ovqatlanishni yakunlang.'),
  ('622216cc-100d-4e85-95dc-7d70e41c5761', 'O‘zi ovqatlanmoqchi 🥣', 'Qoshiqni sizga bermayaptimi? Ovqatlanish taymerini ishga tushirib, bu mustaqillik sinovi qancha vaqt olishini tahlil qiling. To‘kilib-sochilgan ovqatlarga esa shunchaki tabassum qiling.'),
  ('9387504c-dde1-4fdb-977d-53c3dfbb83a2', 'Xavfsiz kashfiyotlar ⚠️', 'Shkaflar, tortmalar... Yosh tadqiqotchi uchun xavfli! Tavsiya etilgan mahsulotlar bo‘limida mebel himoyachilari va xavfsizlik qulflarini ko‘rib chiqing.'),
  ('bdef77ef-7476-4b14-a4a3-51d31635951f', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechqurungi uyg‘oqlik vaqti juda cho‘zilib ketdimi? Uyqu taymerini ishga tushiring. Balki kunduzgi uyquni 15 daqiqaga qisqartirishning ayni vaqtidir.'),
  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'Onaning bel og‘rig‘i 🧘‍♀️', 'Uni ko‘taraverib belingiz og‘riyaptimi? Sog‘lom retseptlardan yallig‘lanishga qarshi va tiklanishga yordam beruvchi zanjabilli ko‘k choy damlab, tanangizga g‘amxo‘rlik qiling.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'Noto‘g‘ri stakan mojarosi? 🥤', 'Suvni qizil emas, ko‘k stakanda berganingiz uchun qiyomat qoyim bo‘ldimi? Bema’ni tuyuladigan bunday injiqliklarni qanday xotirjam hal qilishni darhol Anacan AI’dan so‘rang.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'Ichingizdagini yozib tashlang 📝', 'Bugun u tinmay yig‘ladi va siz juda charchadingiz. O‘zingizni ayblamang. Kayfiyat kundaligiga barcha charchoqlaringizni yozib, xayolingizni bo‘shating va dam oling.'),
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182', '5 daqiqalik quvvat ⚡', 'Ertalab uy ishlariga shoshilmang. Ayollar uchun foydali retseptlardan antioksidantlarga boy rezavorli suli bo‘tqasini tayyorlab, tanangizga tetiklik baxsh eting.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'Tunda uyg‘onishlar ⏱️', 'Uyqu taymerini ishga tushiring! Tungi vahima yoki uyqu regressiyasi bor-yo‘qligini taymerning statistik grafigi orqali aniq tahlil qiling va uyqu tartibini moslashtiring.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'Aql rivojlanishda davom etadi 🧠', 'U hamma narsani saralashni yaxshi ko‘radi! Rang va shaklni idrok etishni rivojlantiradigan, miyani faollashtiradigan geometrik boshqotirmalarni (puzzle) Tavsiya etilgan mahsulotlar bo‘limida hoziroq kashf eting.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'Kunning qahramoni — sizsiz 🌟', 'U har kuni o‘rganayotgan har bir yangi ko‘nikma — sizning mehnatingiz samarasi. Kayfiyat kundaligini oching va bugun o‘zingizni tik turib olqishlashga arziydigan qayd yozing!'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'Bo‘yoqqa belangan rassom! 📸', 'O‘zini ham, devorni ham bo‘yab tashladimi? Jahlingiz chiqishi o‘rniga, bu kulgili chizmachilik lahzasini Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, abadiy xotira sifatida albomga yuklang.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'Ich qotishi muammosi bormi? 💩', 'Ertalab tagligini almashtirayotganda najasini kuzating. Ich qotishi bo‘lsa, buni ilovaga qayd eting va Ovqatlanishni nazorat qilish vositasi yordamida taomnomasiga albatta tolaga boy mahsulotlarni qo‘shing.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'Shakarsiz tamaddi 🍪', 'Do‘kon pechenyelariga hojat yo‘q. Chaqaloqlar uchun retseptlar bo‘limida uyda 10 daqiqada tayyorlanadigan, xurmo va olmali foydali shirinliklarni topib, uning ishtahasini oching.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'Bo‘y o‘sishidagi sakrash! 📏', 'Ko‘ylaklarining yenglari yana kalta bo‘lib qoldimi? Jismoniy rivojlanish tezlashmoqda. Rivojlanish kuzatuvchisiga joriy o‘lchamlarni kiriting va o‘sish grafigini faxr bilan kuzating.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'Yangi so‘zlar paydo bo‘lmoqda! 🗣️', 'Ko‘p tovush chiqaradi-yu, ammo hali to‘liq so‘z aytmayaptimi? Passiv lug‘atini faollashtirish uchun bu kulgili bo‘g‘in aytish urinishlarini audio shaklida Chaqaloq albomiga qo‘shib, kuzatib boring.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'Tozalik yordamchisi 🧹', 'U endi uy ishlarida qatnashishni xohlaydi. Bloglar bo‘limida 22.5 oylik bolada mas’uliyat hissini o‘yin orqali qanday shakllantirish mumkinligini o‘qing va amalda qo‘llang.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'Tasavvur chegara bilmaydi 🧸', 'Ayiqchasini ovqatlantiryaptimi yoki sizni davolayaptimi? Empatiya rivojlanishining ushbu lahzalarini qisqa video shaklida Chaqaloq albomiga qo‘shib, bir umrlik xotira yarating.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'Xavfsiz kashfiyotlar ⚠️', 'Shkaflar, tortmalar... Kichik kashfiyotchi uchun ular xavfli! Tavsiya etilgan mahsulotlar bo‘limida mebel himoyalagichlari va xavfsizlik qulflarini albatta ko‘rib chiqing.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'Xavfsizlik hissi 🌌', 'Xona chirog‘ini o‘chirganingizda qo‘rqadimi? Oq shovqinlardan ona bachadonidagi tovushni (yurak urishini) qo‘yib, unga tanish, iliq xavfsizlik hissini baxsh eting va uyquga sozlang.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'Sizga ham muloqot kerak ☕', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay maskanlardan onalar ko‘p yig‘iladigan bolalar kafelarini topib, o‘zingiz uchun ham yangi muhit yarating.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'Urish yoki itarish 🛑', 'Jahli chiqqanda to‘satdan qo‘l ko‘taradimi? Bu yoshda tajovuzkor tus oladigan his-tuyg‘ularni o‘yinga aylantirib, ularni qanday qilib muloyimlik bilan o‘zgartirishni o‘rganish uchun Anacan AI''ga murojaat qiling.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'Mantiqdagi katta qadam 🧩', 'U sabab va oqibat o‘rtasidagi bog‘liqlikni tushuna boshladi. Bloglar bo‘limida 22 oylik bolalarning idroki rivojlanishini tezlashtiradigan eng yaxshi uy o‘yinlari haqida o‘qing va ularni sinab ko‘ring.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechki uyg‘oqlik vaqti juda uzayib ketdimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. Ehtimol, kunduzgi uyquni 15 daqiqaga qisqartirishning ayni vaqtidir.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'Temir zaxirasini tekshirish 🥩', 'Mushaklar faol harakatlanishi uchun kamqonlik bo‘lmasligi kerak. Ovqatlanishni kuzatish vositasi yordamida bugun qancha temir qabul qilinganini tekshiring va yetishmayotgan miqdorni darhol to‘ldiring.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'Kun charchog‘ini chiqaring 🛋️', 'Uning ortidan yugurib, holdan toyibsiz. Bola uxlab qoldi, endi Kayfiyat kundaligiga barcha stressingizni yozing va o‘zingizga bir piyola o‘simlik choyi quying.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'Tuvakka tayyorlik belgilari? 🚽', 'Ertalab tagligi butunlay quruqmi? Tuvakka o‘rgatishni boshlash uchun ayni payt bo‘lishi mumkin. Buni Taglik kuzatuvchisiga qayd eting va ilovadagi tayyorgarlik haqidagi maqolalarni ko‘rib chiqing.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'Go‘sht yeyishni istamayaptimi? 🥩', 'Oqsilga ehtiyoji bor, ammo go‘shtdan bosh tortyaptimi? Chaqaloq retseptlaridagi chaynash oson va mazali tovuq go‘shtli teftelilar yordamida Ovqatlanishni nazorat qilish vositasidagi me’yorni to‘ldiring.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'Yotoqdan qochish rejasi 🏃‍♂️', 'Uxlash vaqti kelganda xonadan qochadimi? Uyqu taymerini yoqing, Oq shovqinlardan o‘rmon shovqinini qo‘yib, xonani sokin g‘orga aylantiring.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'Ertalabki injiqlik 🛑', '“Buni kiymayman, uni yemayman!” degan injiqliklar ertalabingizni qiyinlashtiryaptimi? Darhol Anacan AI’ga yozib, bu yoshdagi chegaralarni sinash holatlarini qanday boshqarishni bilib oling.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'Devordan divanga sakrash! 🧗‍♂️', 'U haqiqiy kaskadyor! Uydagi ortiqcha energiyasini chiqarishi uchun Onalar uchun qulay joylardan keng o‘yin zallari bor markazlarni toping va unga erkin o‘ynash imkonini bering.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'Devordagi san’at asari 🎨', 'Qo‘liga qalam olib, devorni bo‘yab tashladimi? Jahlingiz chiqmasin! Bu yoqimli sho‘xlikni Chaqaloq fotosessiyasidagi kulgili ramkalar bilan albomga qo‘shing va shunchaki tabassum qiling.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'To‘satdan uyg‘onishlar qaytdimi? ⏱️', 'Yarim tunda yig‘lab uyg‘onyaptimi? Uyqu taymeridagi jadvalga qarang. Kunduzgi uyqu juda kech tugasa, kechqurun chuqur uyquga ketish qiyinlashadi.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'Onaning qahva tanaffusi ☕', 'O‘zingizni unutmang! Ayollar uchun foydali retseptlardan quvvat beruvchi suli gazagini tayyorlab, qahvangizdan zavqlaning.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'Tuvakni to‘g‘ri tanlash 🚽', 'Hojatxonaga o‘rgatishga ko‘rgazmali tayyorgarlik boshlansin! Tavsiya etilgan mahsulotlar bo‘limida onalar sinab ko‘rgan eng qulay va jozibali tuvak modellarini albatta ko‘rib chiqing.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'Omega-3 zaxirasi qanday? 🐟', 'Miyaning jadal rivojlanishi uchun baliq yoki yong‘oq juda muhim! Ovqatlanishni nazorat qilish vositasi orqali bu haftadagi Omega-3 iste’molini tekshiring va menyuni darhol yangilang.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'Mukammal bo‘lishingiz shart emas 💖', 'Bugun uy tartibsiz bo‘lib, ovqat kechikdimi? Hechqisi yo‘q! Kayfiyat kundaligiga ichki kechinmalaringizni yozing va farzandingiz sizni har qanday holatingizda ham sevishini eslang.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'Ayriliq qo‘rquvi qaytdimi? 🌌', 'Xonadan chiqishingiz bilan ortingizdan yig‘laydimi? Oq shovqinlar bo‘limidan yurak urishi ovozini yoqib, unga xavfsizlik hissini bering va uyquga tayyorlang.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'Shimlar yana kalta bo‘lib qoldi! 📏', 'Ko‘ylaklarining yenglari torayaptimi? Bu jismoniy rivojlanishdagi keskin o‘sishdir. Joriy o‘lchamlarni Vazn kuzatuvchisiga kiriting va o‘sish grafigini faxr bilan kuzating.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'Kulgili talaffuzlar 🗣️', 'Ba’zi so‘zlarni shu qadar yoqimli va noto‘g‘ri aytadiki! Bu bebaho lahzalarni o‘tkazib yubormang. Chaqaloq albomiga ovozli video sifatida yuklang va kelajakda birga kuling.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'Oqsil zaxirasi yetarlimi? 🍗', 'Faol mushaklar uchun oqsil zarur. Ovqatlanishni nazorat qilish vositasi yordamida uning kundalik oziq-ovqat muvozanatini baholang va menyusini boyiting.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'Buni o‘zim qilaman! 👕', 'Ertalab kiyinish katta mojaroga aylanadimi? Qaysarlikni yengish va unga tanlash huquqini berish sirlarini hoziroq Anacan AI-dan bilib oling.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'Kitobni yirtmaymiz, o‘qiymiz 📖', 'Kechki ertak paytida sahifalarni yirtadimi? Mutolaa odatiga zarar yetkazmasdan bu muammoni qanday hal qilishni Bloglar bo‘limida hoziroq o‘qing.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'Ko‘p suv, oson hazm 💧', 'Faol kichkintoyingizning ichaklari qanday ishlayapti? Tagligini almashtirganda kuzatuvlaringizni kiriting. Agar qabziyat xavfi bo‘lsa, ilovadagi tabiiy tolaga boy oziq-ovqatlar bo‘yicha tavsiyalarni ko‘rib chiqing.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'Ovqat uchun kurash tugadi ⏱️', 'Stolda qoshiqni chetga uloqtiryaptimi? Ovqatlanish taymerini to‘xtating — bola to‘ygan. Ishtaha grafigini tahlil qilib, majburlab ovqatlantirishdan saqlaning.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'Boshqa onalar bilan tanishuv 👯‍♀️', 'Bolangiz o‘ynasin, siz esa suhbatlashing! Onalar uchun qulay joylar xaritasidan o‘yin guruhlari mavjud markazni topib, uydan chiqing.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'Tishlar yuvilyaptimi? 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini mahkam yopib oladimi? Bu gigiyena odatini qanday qilib qiziqarli o‘yinga aylantirishni bilish uchun Anacan AI’dan amaliy maslahatlar oling.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'Tabiiy tinchlantiruvchi 🍃', 'Bugun juda shovqinli kun bo‘ldimi? Taymer to‘xtadi. Uy ishlarini unuting, Sog‘lom retseptlardan melissa choyini damlab, shunchaki sukunatdan zavqlaning.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'Foydali shirinlik izlab 🍎', 'Do‘kondagi pechenyelarga xayr! Chaqaloqlar uchun retseptlardan uyda 10 daqiqada tayyorlanadigan, xurmo va olmali foydali pechenyelarni topib, uning ishtahasini oching.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechqurun uyg‘oq qolish vaqti juda cho‘zilib ketdimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. Balki kunduzgi uyquni 15 daqiqaga qisqartirishning ayni paytidir.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'Qum va loy terapiyasi 🏖️', 'Kir bo‘lishdan qo‘rqmang! Kinetik qum yoki sensorli o‘yinlar uchun eng yaxshi vositalarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'Bu sizning mehnatingiz samarasi 🌟', 'Har kuni o‘rganayotgan yangi ko‘nikmasi, har bir dadil qadami — sizning mehnatingiz samarasi. Kayfiyat kundaligini oching va bugun o‘zingizdan faxrlanishingizga sabab bo‘ladigan qayd yozing!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'Bugun necha marta Yo‘q dedingiz? 💆‍♀️', 'Juda charchadingiz, shundaymi? Chuqur nafas oling. Barcha his-tuyg‘ularingizni Kayfiyat kundaligiga yozing, o‘zingizni ayblashni bas qilib, shunchaki dam oling.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'Tagligi quruq holda uyg‘ondimi? 🩲', 'Ertalab tagligini almashtirayotganda uning quruqligini payqadingizmi? Tuvakka o‘rgatishni boshlash uchun eng maqbul vaqt va psixologik usullar haqida hoziroq Anacan AI’dan so‘rang.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'Keksga muhabbat 🧁', 'Shirinlik xohlayaptimi? Do‘konga shoshilmang. Chaqaloqlar uchun retseptlar bo‘limidagi shakarsiz, banan va suli qo‘shilgan, 10 daqiqada tayyor bo‘ladigan uy keksini pishiring va Ovqatlanishni nazorat qilish vositasidagi salomatlik balini saqlab qoling.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'Kiyinish janjali! 👗', 'Ertalab kiyinish katta muammoga aylanadimi? Unga ikki xil ko‘ylakni taklif qilib, tanlash imkonini bering.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'Ko‘zlarini ishqalayaptimi? 🥱', 'Uyqu belgilari paydo bo‘ldi! Uyqu taymerini ishga tushiring, Oq shovqinlardan o‘rmon shovullashini yoqib, uni asta-sekin uyquga tayyorlang va jadvalni kuzatib boring.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'Onaning qahva vaqti ☕', 'Endi tanaffus qilish vaqti. Bola mustaqil o‘ynayotganida, Ayollar uchun foydali retseptlar bo‘limidagi antioksidantlarga boy ko‘k choy yoki yengil qahva bilan quvvatingizni tiklang.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'Uyda devorlarga tirmashyaptimi? 🧗', 'Ortiqcha energiyasini sarflashi kerak! Onalar uchun qulay joylar xaritasini oching, xavfsiz yugurish maydoni va sirpanchig‘i bor yangi bog‘ni topib, unga erkin o‘ynash imkonini bering.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'Stoldan qochish! 🏃‍♂️', 'Ovqatini yarimta qoldirib, qochib ketyaptimi? Ovqatlanish taymerini to‘xtating. Majburlab yedirish o‘rniga, Bloglar bo‘limida ishtahani tabiiy ravishda ochish sirlarini o‘qing.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'Oyoq kiyimi nega siqyapti? 👟', 'Yugurayotganda tez-tez qoqiladimi? Oyog‘i o‘sgan bo‘lishi mumkin! Rivojlanish kuzatuvchisiga joriy o‘lchamlarni kiriting, o‘sish davrini darhol tekshiring va rivojlanishini tahlil qiling.'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'Shakllarni to‘g‘ri topa oladimi? 🧩', 'Mantiqiy rivojlanishini qo‘llab-quvvatlash uchun yoshiga mos geometrik pazllar va rivojlantiruvchi yog‘och o‘yinchoqlarni hoziroq Tavsiya etilgan mahsulotlardan qidiring.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'Oqsil zaxirasi yetarlimi? 🥚', 'Tez o‘sayotgan mushaklar uchun oqsil zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugungi me’yorni hisoblang va oqsil yetishmasa, menyuni moslashtiring.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'Ilk jiddiy suhbatlar 🗣️', 'Siz bilan o‘z tilida uzoq vaqt nimalarnidir muhokama qiladimi? Bu kulgili va oltinga teng lahzani ovozli video shaklida Chaqaloq albomiga saqlab qo‘ying.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'To‘satdan boshlanadigan qiyqiriqlar! 🛑', 'Istagi bajarilmasa, o‘zini yerga tashlaydimi? 23-oyga yaqin ko‘payadigan bunday hissiy injiqliklarni o‘yinga aylantirish usullarini Anacan AI ekspert yordamchimizdan so‘rang.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'Suv ichishni unutmasin 💧', 'Tinmay yuguradigan kichkintoyning ichaklari qanday ishlayapti? Tagligini almashtirganda najasini qayd eting. Ich qotishi xavfi bo‘lsa, ilovadagi tabiiy tolaga boy oziq-ovqatlar bo‘yicha tavsiyalarni albatta ko‘rib chiqing.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'Qorong‘ilikdan qo‘rqadimi? 🌌', 'Xona chirog‘ini o‘chirganingizda yig‘laydimi? Oq shovqinlar bo‘limidan ona qornidagi tovushni (yurak urishini) yoqib, unga avvaldan tanish bo‘lgan mutlaq xavfsizlik hissini bering.'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'Jahl bilan tishlayaptimi? 🦖', 'Jahli chiqqanda do‘stlarini yoki sizni tishlaydimi? Bu qiyin xulq-atvorni mehr bilan qanday bartaraf etishni Anacan AI ekspert yordamchimizdan hoziroq so‘rang.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'Faqat non yeydimi? 🍞', 'Oqsil va sabzavotlarni chetga surib, faqat uglevodli ovqatlarni xohlaydimi? Ovqatlanishni kuzatish vositasi yordamida bugun qancha foydali oziq modda olganini hisoblang va me’yorni tartibga soling.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'Sahifalarni yirtishga qiziqadimi? 📖', 'Kechki ertak paytida kitob sahifalarini yirtmoqchimi? Bloglar bo‘limida kitob o‘qish odatiga zarar yetkazmasdan bu muammoni qanday hal qilish mumkinligini o‘qing.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'Devordagi san’at asari 🎨', 'Qo‘liga qalam olib, devorni chizib tashladimi? Jahlingiz chiqmasin! Bu yoqimli sho‘xlikni Chaqaloq fotosessiyasidagi kulgili ramkalar bilan albomga qo‘shib, shunchaki jilmaying.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'Belingiz og‘riyaptimi? 🧘‍♀️', '12+ kg vaznli kichkintoyni tinmay ko‘tarish oson emas. Sog‘lom retseptlar bo‘limidan mushaklarni bo‘shashtiradigan, yallig‘lanishga qarshi zanjabil choyini damlab, dam oling.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'Yotoqdan qochish rejasi 🏃‍♂️', 'Uxlash vaqti kelganda karavotidan tirmashib chiqadimi? Uyqu taymerini yoqing, Oq shovqinlar orasidan bir maromdagi poyezd ovozini qo‘yib, uni asta-sekin uyquga tayyorlang.'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'Urish yoki itarish 🦖', 'Jahli chiqqanda to‘satdan qo‘l ko‘taradimi yoki do‘stlarini itaradimi? Bu yoshda kuchayadigan tajovuzkor his-tuyg‘ularni qanday qilib muloyimlik bilan o‘zgartirishni Anacan AI’dan bilib oling.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'Suyaklar mustahkamlanmoqda 🦴', 'Jadal rivojlanish uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugungi pishloq va qatiq me’yoriga amal qilganingizni tekshiring hamda yetishmaganini to‘ldiring.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'Tabiiy tinchlantiruvchi 🍃', 'Bugun juda shovqinli kun bo‘ldimi? Taymer to‘xtadi. Uy ishlarini unuting, Oq shovqinlar bo‘limidan soy shildirashini yoqing va dam olish uchun divanga yonboshlang.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'Kitobni yirtish emas, o‘qish 📖', 'Kechki ertak paytida sahifalarni yirtadimi? Bloglar bo‘limida kitob o‘qish odatiga zarar yetkazmasdan bu muammoni qanday hal qilish mumkinligini hoziroq o‘qing.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'Yotoqdagi tugamaydigan tomosha 🛌', 'Uxlash o‘rniga yotoqda sakraydimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. U energiyasini to‘liq sarflamaganmi yoki haddan tashqari charchaganmi — tahlil qiling.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'Tish yuvish janjali 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini mahkam yopadimi? Tavsiya etilgan mahsulotlar bo‘limidagi musiqali yoki barmoqqa kiyiladigan cho‘tkalarni ko‘rib, bu muhim odatni qiziqarli o‘yinga aylantirish yo‘lini kashf eting.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'Ertalabki quvvatingizni asrang ⚡', 'Kunni och qoringa boshlamang! Ayollar uchun foydali retseptlar orasidan 5 daqiqada tayyor bo‘ladigan, to‘yimli va mazali suli keksini tanlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'Sizga ham do‘stlar kerak 👯‍♀️', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay joylar orasidan o‘yin guruhlari mavjud markazlarni toping, boshqa onalar bilan muloqot qiling va tajriba almashing.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'Kunduzgi uyqu qisqaryaptimi? ⏱️', 'Kechasi uxlab qolish uzoq vaqt oldimi? Uyqu taymerini yoqing va jadvalni kuzating. Balki kunduzgi uyquni 15-20 daqiqaga qisqartirishning ayni vaqtidir.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'Kunning qahramoni — sizsiz 🌟', 'Har kuni o‘rganayotgan yangi ko‘nikmasi, har bir dadil qadami — sizning mehnatingiz samarasidir. Kayfiyat kundaligini oching va bugun o‘zingizdan faxrlanishingizga arziydigan bir qayd yozing!'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'Ko‘katlarni ko‘rsa, qochadimi? 🥦', 'Ovqatni rangiga qarab tanlay boshladimi? Chaqaloqlar uchun retseptlarda ismaloq va sabzini mazali pankeyklar ichiga qanday ustalik bilan yashirishni bilib oling va uning ishtahasini oching.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'Kichkina rassom ish ustida 🎨', 'Ust-boshi bo‘yoq bo‘lsa ham, jahlingiz chiqmasin! Bu ijodiy lahzani darhol Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezang, albomga qo‘shing va tabassum qiling.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'Gorshokka tayyorlik belgilari? 🚽', 'Ertalab tagligi butunlay quruqmi? Hojatxonaga o‘rgatishni boshlash uchun ayni payt bo‘lishi mumkin. Buni Taglik kuzatuvchisiga qayd eting va Tavsiya etilgan mahsulotlar bo‘limidan ergonomik gorshok tanlang.'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'Yolg‘iz o‘ynashni xohlayaptimi? 👶', 'Bog‘da boshqa bolalarga qo‘shilmay, ularni chetdan kuzatyaptimi? Bu sog‘lom parallel o‘yin haqida eng qiziqarli va ilmiy faktlarni Bloglar bo‘limida bilib oling.'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'Mukammal ona bo‘lish istagi 💖', 'Bugun ovozingizni biroz balandlatib yubordingizmi? O‘zingizni aybdor his qilmang. His-tuyg‘ularingizni Kayfiyat kundaligiga yozing — siz baribir farzandingiz uchun eng yaxshi onasiz.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechqurungi uyg‘oqlik vaqti juda cho‘zilib ketdimi? Uyqu taymerini ishga tushiring va jadvalni kuzating. Balki kunduzgi uyquni 15 daqiqaga qisqartirishning ayni paytidir.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'Qum va loy terapiyasi 🏖️', 'Kiyimlari kir bo‘lishidan qo‘rqmang! Sensor rivojlanish uchun Onalar uchun qulay joylar bo‘limidan qum maydonchasi bor xavfsiz bog‘ni toping va bolangizga tabiat bilan erkin tanishish imkonini bering.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'Temirning eng yaxshi do‘sti 🥩', 'Temir organizmga yaxshi singishi uchun C vitamini zarur! Ovqatlanishni nazorat qilish vositasi orqali bugungi menyuni tekshiring va go‘sht yoniga limonli salat qo‘shing.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'Faqat non yeyaptimi? 🍞', 'Oqsil va sabzavotlarni chetga surib, faqat uglevodlarni xohlayaptimi? Ovqatlanishni nazorat qilish vositasi yordamida bugun qancha foydali ozuqa olganini hisoblang va me’yorni muvofiqlashtiring.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'Sahifalarni yirtishga ishtiyoq 📖', 'Kechki ertak paytida kitob sahifalarini yirtmoqchimi? Bloglar bo‘limida kitob o‘qish odatiga zarar yetkazmasdan bu muammoni qanday hal qilish mumkinligini bilib oling.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'Jahl ustidagi tishlashlar 🦖', 'Jahli chiqqanda do‘stlarini yoki sizni tishlayaptimi? Bu murakkab xulq-atvorni mehr bilan qanday yengish mumkinligini Anacan AI ekspert yordamchisidan hoziroq so‘rang.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'Belingiz og‘riyaptimi? 🧘‍♀️', '12+ kq vaznli kichkintoyni tinmay ko‘tarish oson emas. Ayollar uchun sog‘lom retseptlardan mushaklarni bo‘shashtiruvchi, yallig‘lanishga qarshi zanjabil choyini damlab, dam oling.'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'Devordagi san’at asari 🎨', 'Qo‘liga qalam olib, devorni bo‘yab tashladimi? Jahlingiz chiqmasin! Bu yoqimli sho‘xlikni Chaqaloq fotosessiyasidagi kulgili ramkalar bilan albomga qo‘shib, shunchaki jilmaying.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'Yotoqdan qochish rejasi 🏃‍♂️', 'Uxlash vaqti kelganda karavotchasidan oshib tushyaptimi? Uyqu taymerini ishga tushiring, Oq shovqinlardan bir maromdagi poyezd tovushini yoqib, uni asta-sekin uyquga tayyorlang.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'Ikki oyoqda sakrash 🦘', 'Bir joyda turib, ikki oyog‘i bilan bir vaqtda sakrashga harakat qilyaptimi? Juda kulgili ko‘rinadi, shunday emasmi? Bu lahzani albatta abadiylashtiring.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'Musiqali orom 🎶', 'Kechga yaqin boshlanadigan injiqliklarni tinchlantirishning eng oson yo‘li — uning sevimli kuyini qo‘yib, bag‘ringizga bosgancha asta raqsga tushishdir.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'Uyqudan bosh tortyaptimi? 🥱', 'Kunduzgi uyquga yotishni istamay, qarshilik qilyaptimi? Anacan AI-dan 2 yoshga yaqin davrdagi uyqu oralig‘i haqida aniq ma’lumot va rejim jadvalini so‘rang.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'Foydali shirinlik izlaymiz 🍎', 'Do‘kon pechenyelariga bas! Chaqaloqlar uchun retseptlar orasidan uyda 10 daqiqada tayyorlanadigan, xurmo va olmali foydali shirinliklarni topib, uning ishtahasini oching.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'Tish yuvish janjali 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini mahkam yopib oladimi? Ushbu muhim gigiyena odatini qanday qilib qiziqarli o‘yinga aylantirishni bilish uchun Anacan AI-dan amaliy maslahatlar oling.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'Kulgili talaffuzlar 🗣️', 'Ba’zi so‘zlarni shunchalik yoqimli va noto‘g‘ri aytadiki! Bu bebaho lahzalarni o‘tkazib yubormang. Chaqaloq Albomiga ovozli video sifatida yuklang va kelajakda birga kuling.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'Tasavvur chegara bilmaydi 🧸', 'Ayiqchasini ovqatlantiryaptimi yoki sizni davolayaptimi? Ajoyib empatiya rivojini qo‘llab-quvvatlaydigan shifokor yoki oshxona to‘plamlarini Tavsiya etilgan mahsulotlar bo‘limidan ko‘ring.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'Ayriliq qo‘rquvi qaytdimi? 🌌', 'Xonadan chiqishingiz bilan ortingizdan yig‘laydimi? Oq shovqinlar bo‘limidan yurak urishi ovozini yoqib, unga xavfsizlik hissini bering va uyquga tayyorlang.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'Shimlar yana kalta bo‘lib qoldi! 📏', 'Ko‘ylaklarning yenglari torayaptimi? Bu jismoniy rivojlanishdagi keskin o‘sishdir. Rivojlanish kuzatuvchisiga joriy o‘lchamlarni kiriting va o‘sish grafigiga faxr bilan qarang.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'Onaning oqsil zaxirasi ⚡', 'Harakatchan kichkintoyning ortidan yugurish oson emas. Ayollar uchun sog‘lom retseptlardan oqsil va mevalarga boy energetik smuzi tayyorlab, quvvatingizni tiklang.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'Buni men qilaman! 👕', 'Ertalab kiyinish katta injiqlikka aylanadimi? Qaysarlikni yengish va unga tanlash huquqini berish sirlarini hoziroq Anacan AI’dan bilib oling.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'To‘yganini qanday bilamiz? ⏱️', 'Ovqatni otish yoki tupurishni boshlagan bo‘lsa, bu «to‘ydim» degani. Ovqatlanish taymerini to‘xtating, me’yor bajarilganini qayd eting va ishtahasini tahlil qiling.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'Kitoblarga mehr 📖', 'Sevimli ertak kitobini olib kelib, bag‘ringizga o‘tiradimi? Uning diqqatini jamlash muddati uzaymoqda. U bilan birga o‘qing va rasmdagi narsalarni nomlang.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'Qo‘rquvlar boshlandimi? 👻', 'Avval qo‘rqmagan changyutgichdan endi qo‘rqyaptimi? Tasavvuri rivojlangan sari asossiz qo‘rquvlar paydo bo‘ladi. Uni quchoqlang va xavfsiz ekanini ayting.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'Toza havoga ehtiyoj 🌳', 'Bola juda bezovta bo‘lib, uyda o‘tira olmayaptimi? Ob-havo va kiyimini tekshirib, darhol parkka yo‘l oling. Tabiat uni eng tez tinchlantiradigan vositadir.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'Sizga ham do‘stlar kerak 👯‍♀️', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay joylar orasidan o‘yin guruhlari bor markazlarni toping, boshqa onalar bilan muloqot qiling va tajriba almashing.'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'Tozalikdagi yordamchi 🧹', 'U endi uy ishlarida qatnashishni xohlaydi. Bloglar bo‘limida taxminan 2 yoshli bolaga mas’uliyat hissini o‘yin orqali qanday singdirish mumkinligini o‘qing va amalda qo‘llang.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'O‘zingiz bilan faxrlaning! 🌟', 'U har kuni o‘rganayotgan yangi ko‘nikma va har bir ishonchli qadami — sizning mehnatingiz samarasidir. Kayfiyat kundaligini oching va bugun o‘zingiz bilan faxrlanishingiz uchun bir g‘ururbaxsh qayd yozing!'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'Ob-havo g‘alati deb uyda qolib ketdingizmi?', 'Ob-havo va kiyim vositasi sizga shamol tezligi va mos kiyim kombinatsiyasini bir zumda ko‘rsatsin, siz esa bemalol parkka chiqing.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'Eng oxirgi oziq tishlarimi? 🦷', 'Hech bir sababsiz hamma narsani kemirib, jahldor bo‘lib qoldimi? Eng orqa oziq tishlari chiqayotgan bo‘lishi mumkin. Tish chiqishi kuzatuvchisida jarayonni qayd etib, sovuq tish qashlagichlarni tayyorlab qo‘ying.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'Ertak qahramoni 🪄', 'Bugun kechqurun Aqlli ertaklarda qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: Tishlarini yuvishni yaxshi ko‘radigan jasur kichkintoy.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'O‘zingizga vaqt ajrating 🛋️', 'Uning ortidan yuguraverib tinkangiz quridi. Bola uxlab qoldi, endi Kayfiyat kundaligiga barcha stressingizni yozib, o‘zingizga bir piyola melissa choyi quying.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'Qorni ochmi yoki chanqadimi? 💧', 'Ba’zan chanqoq ishtaha yo‘qligi bilan adashtiriladi. Taglik kuzatuvchisidagi ajralmalar haqidagi qaydlarni tekshirib, bola yetarli miqdorda suyuqlik olayotganiga tezda ishonch hosil qiling.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'Kichkina xonanda 🎤', 'Bir xil qo‘shiqni tinmay kuylayaptimi? Bu ritmni his qilish va nutq rivojlanishini qo‘llab-quvvatlaydi.'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'Sabzavotlarni yashirish amaliyoti 🥦', 'Brokkolini ko‘rishi bilan likopchani surib qo‘yadimi? Chaqaloqlar uchun retseptlarda bu vitaminli sabzavotni mazali quymoqlar ichiga mohirona yashirish usulini bilib oling va uning ishtahasini oching.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'O‘yin tugay demaydi ⏱️', 'Uxlashga yotish o‘rniga qochib, yashirinadimi? Uyqu taymerini yoqing, Oq shovqinlardan okean to‘lqinlari ovozini tanlab, xonani sokin uyqu maskaniga aylantiring.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'Ertalab juda erta uyg‘onadimi? 🌅', 'Quyosh chiqmasidan uyg‘onib, tetik yuradimi? Uyqu rejimini qanday qilib qulayroq vaqtga surishni bilish uchun hoziroq Anacan AI ekspert yordamchimizdan tavsiyalar oling.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'Mantiqiy o‘yinlar 🧩', 'O‘yinchoqlarni qutiga solib, keyin hammasini yana bo‘shatadimi? Unda «ichida» va «tashqarisida» tushunchalari shakllanmoqda. Bu kognitiv ko‘nikmani Rivojlanish kuzatuvchisiga qayd eting.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'Oyoq kiyim borasidagi qaysarlik 👟', 'Ko‘chaga chiqayotganda yozda ham aynan o‘sha qishki oyoq kiyimini kiyishni talab qiladimi? Ba’zan unga o‘zi tanlashiga imkon bering — bu uning irodasini mustahkamlaydi.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'Savolingiz bormi? 🤖', '2 yosh inqirozi haqida o‘qiganlaringiz sizni qo‘rqityaptimi? Internetda adashib qolmang, to‘g‘ridan-to‘g‘ri Anacan AI-ga yozing va bu davrni qanday osonroq o‘tkazishni bilib oling.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'Divan alpinisti! 🧗', 'Mebellar ustida yurish uning eng sevimli mashg‘ulotimi? Uning bu jasur va kulgili harakatlar tomoshasini Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomga yuklang.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'Onaning quvvati tugayaptimi? 🔋', 'Kunduzi tik turgancha mudrab qolyapsizmi? Ayollar uchun foydali retseptlardan kofeinsiz ham bir zumda quvvat beradigan, oqsilga boy yeryong‘oq pastali smuzi tayyorlang.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'Bugun hammasi qiyin bo‘ldimi? 💆‍♀️', 'Tinimsiz qichqiriq va yig‘i eshitdingizmi? Chuqur nafas oling, o‘zingizni ayblashni bas qiling — siz ajoyibsiz!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'Oshxonadagi barcha qozonlar yerdami?', 'Xavfsiz buyumlar bilan o‘ynash uning mantiqiy fikrlashini rivojlantiradi. Xazinasini erkin o‘rganishiga imkon bering.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'Sukunatga ehtiyoj 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat eng nozik vaqtdir. Ovoz o‘lchagich yordamida muhitdagi shovqin darajasini desibellarda tekshiring va to‘satdan chiqadigan shovqinlardan saqlaning.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'Mukammallik illyuziyasi 🛋️', 'Ijtimoiy tarmoqlardagi doimo xushchaqchaq onalarga qarab, o‘zingizni ayblamang. Charchaganingiz ham, xonangizning tartibsizligi ham mutlaqo tabiiy holat.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'So‘zlardan gaplarga 🗣️', 'U 3 so‘zli kulgili gaplar tuza boshladimi? Bu ajoyib nutqiy sakrashni va uning yoqimli talaffuzini ovozli video shaklida yozib, kelajak uchun saqlab qo‘ying.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'Sahifalar jonlanadi 📖', 'Ertak o‘qiyotganda kitobdagi hayvonlarning ovoziga taqlid qiladimi? Bloglar bo‘limida tasavvur rivojini qo‘llab-quvvatlaydigan interaktiv o‘qish usullari haqida albatta o‘qing.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'Energiya portlashi 💥', 'Uning yugurishlariga uyning to‘rt devori torlik qilyaptimi? Onalar uchun qulay joylar xaritasini oching, yumshoq qoplamali va katta sirpanchig‘i bor xavfsiz bog‘ni topib, unga erkin harakatlanish imkonini bering.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'O‘zim tishimni yuvaman! 🪥', 'Tish cho‘tkasini qo‘lingizdan olib, tishini o‘zi yuvmoqchi bo‘ladi-yu, aslida yaxshilab tozalamaydimi? Bu jarayonni osonlashtiradigan musiqali va ergonomik modellarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan qidiring.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'Suyuqlik iste’moli va qabziyat 💧', 'Ko‘p yugurib, kam suv ichadimi? Tagligini almashtirganda najasini kuzating. Qabziyat xavfi bo‘lsa, buni ilovaga qayd eting va Ovqatlanishni nazorat qilish vositasi yordamida ratsioniga darhol tolaga boy mahsulotlarni qo‘shing.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'Dasturxon atrofida sabr sinovi 🥣', 'Ovqat bilan o‘ynab, hamma joyni iflos qiladimi? Ovqatlanish taymerini yoqing, ishtaha dinamikasini grafik orqali tahlil qiling va jarayon qancha davom etishini aniq kuzating.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'Tungi odatlar 🧸', 'Har oqshom bir xil o‘yinchoqni quchoqlab uxlaydimi? Bu yoqimli xotirjamlik onini suratsiz, shunchaki tasvirlab, Chaqaloq albomining qaydlar bo‘limiga yozing va unutilmas qiling.'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'Do‘stlashishga ilk urinishlar 👶', 'Bog‘da boshqa bolaning o‘yinchog‘iga qiziqib, tovushlar chiqaryaptimi? Ijtimoiylashuvning ushbu bosqichini qanday qo‘llab-quvvatlashni Onalar do‘stligi makonlarida boshqa onalar bilan suhbatlashib bilib oling.'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'Kichkina shifokor ish ustida 🩺', 'Ayiqchasiga ukol qilyaptimi yoki qornini eshityaptimi? Tasavvurga asoslangan o‘yinlar ayni avjida! Bloglar bo‘limida rolli o‘yinlarning aqliy rivojlanishga ajoyib ta’siri haqida o‘qing.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'Tagligi butunlay quruq holda uyg‘ondimi? 🩲', 'Ertalab tagligini almashtirayotganda uning quruqligini payqadingizmi? Bu bolaning jismonan tuvakka tayyor ekanini ko‘rsatuvchi asosiy belgidir! Buni taglik kuzatuvchisiga qayd etib, statistikani diqqat bilan kuzating.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'Shakarsiz, ammo shirin 🍪', 'Kunduzi tamaddi qilishni xohlayaptimi? Do‘kondagi pechenyelarga hojat yo‘q. Chaqaloq retseptlari bo‘limida 10 daqiqada tayyorlanadigan xurmo va suli qo‘shilgan foydali shirinliklarni kashf eting.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'Kun tartibini to‘liq tahlil qilamiz ⏱️', 'Kechqurun uxlab qolishi 40 daqiqa davom etdimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyquni 20 daqiqaga qisqartirish va kechki uyqu vaqtini oldinroqqa surishning ayni paytidir.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'Hamma narsani yerga otish istagi 🛑', 'Jahli chiqqanda yoki zerikkanda qo‘lidagi narsani aylantirib otadimi? Bu hissiy reaksiyalarni qanday qilib muloyimlik bilan to‘g‘ri yo‘naltirish mumkinligini Anacan AI-dan so‘rang.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'Ko‘ylaklar kalta bo‘lib qolyapti! 📏', 'Kiyintirayotganda yenglari torayib qolganini sezdingizmi? 2 yoshga yaqinlashganda jismoniy o‘sish jadallashadi! Rivojlanish kuzatuvchisiga hozirgi bo‘yini kiriting va o‘sish egri chizig‘iga faxr bilan qarang.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy yumushlariga shoshilmang! Ayollar uchun foydali retseptlardan melissa choyini damlang va Kayfiyat kundaligida bugungi kichik yutuqlaringizni qayd eting.'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'Temirning kuchi 🥩', 'Faol kichkintoyda kamqonlik yuzaga kelmasligi va u doimo tetik bo‘lishi uchun Ovqatlanishni nazorat qilish vositasida bugungi temir iste’molini tekshiring, agar yetishmovchilik bo‘lsa, menyuni moslashtiring.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'Bir maromdagi tovushlar sehri 🌬️', 'Televizor o‘chirilgach, to‘satdan cho‘kkan sukunat uni bezovta qiladi. Xonada Oq shovqinlardan ventilyator yoki soch quritgich tovushini yoqib, uyqu muhitida qanday qilib xavfsizlik hissi paydo bo‘lishini kuzating.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'Bo‘yoqli qo‘llar san’ati 🎨', 'Ranglar bilan o‘ynayotib, butun yuz-ko‘zini bo‘yab tashladimi? Jahlingiz chiqishi o‘rniga, bu kulgili va ijodiy lahzani darhol suratga olib, albomga eng rang-barang xotira sifatida qo‘shing.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'Ertalabki injiqliklar 👗', '“Bu oyoq kiyimni xohlamayman!” degan qaysarlik tongingizni qiyinlashtiryaptimi? Unga muqobil variantlarni taklif qilib, tanlash erkinligini berishning eng samarali psixologik usullarini Anacan AI’dan o‘rganing.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'Onaning oqsil zaxirasi ⚡', 'Tinib-tinchimas bolakayning ortidan yugurish oson emas. O‘zingizni holdan toydirmang! Sog‘lom retseptlardan foydalanib, oqsil va mevalarga boy energetik smuzi tayyorlang va quvvatingizni tiklang.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'Tabiiy tinchlantiruvchi 🍃', 'Bugun juda shovqinli va yugur-yugurlarga boy kun bo‘ldimi? Taymer to‘xtadi. Xonani qorong‘ilating, Oq shovqinlardan soy shildirashini yoqing va bolakay bilan birga o‘zingizga ham ruhiy orom bering.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'Mustaqillik kurashi! 👕', 'O‘zi kiyinishni xohlayaptimi va yordamingizni rad etyaptimi? Bu qaysarlikni qanday qilib sog‘lom rivojlanishga yo‘naltirish mumkinligini hoziroq Anacan AI ekspert yordamchimizdan so‘rang.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'Temir zaxirasini tekshirish 🥩', 'Faol bolakayda kamqonlik yuzaga kelmasligi uchun Ovqatlanishni nazorat qilish vositasida uning bugungi temir iste’molini (go‘sht, dukkaklilar) tekshiring va menyuni yangilang.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'Tungi sekinlashuv 🎶', 'Yugurishdan charchamayaptimi va yotishni istamayaptimi? Uyqu taymerini ishga tushiring, Oq shovqinlardan okean to‘lqinlari ovozini yoqing va xonada sokin, uyquga chorlovchi muhit yarating.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'Ertakni uning o‘zi aytsin 📖', 'Kitobdagi rasmlarga qarab, o‘z tilida nimalarnidir gapiryaptimi? Tasavvurining bu ajoyib lahzasini darhol ovozli video shaklida Chaqaloq albomiga qo‘shib, kelajak uchun saqlab qo‘ying.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'Xavfsiz yugurish maydoni 🏃‍♀️', 'Uyda energiyasini sarflay olmay, hamma narsani to‘zg‘ityaptimi? Onalar uchun qulay joylar xaritasini oching, xavfsiz yugurish maydoni bor parkni topib, toza havoga chiqing.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'Boshqa stakan deb janjal qilyaptimi? 🥤', 'Suvni qizil emas, ko‘k stakanda berganingiz uchun qiyomat ko‘tardimi? Bema’nidek tuyuladigan bunday injiqlik xurujlarini qanday xotirjam boshqarishni Anacan AI’dan o‘rganing.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'Tunda uyg‘onishlar ⏱️', 'Uyqu taymerini ishga tushiring! Taymerning statistik grafigi orqali bu tungi vahima yoki uyqu regressiyasi ekanini aniq tahlil qilib, uyqu tartibini moslashtiring.'),
  ('91af8067-4bf1-4cab-af7f-58a96c7e04b3', 'Sizga ham tanaffus kerak ☕', 'Uydan chiqib, biroz nafas rostlang! Onalar uchun qulay joylar orasidan yaqin atrofdagi bolalar burchagi bor kafeni toping va issiq qahvangizni xotirjam iching.'),
  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'Ich qotishi muammosi bormi? 🚽', 'Ertalab taglikni almashtirayotganda najasini kuzating. Ich qotishi bo‘lsa, buni ilovaga qayd eting va Oziqlanishni nazorat qilish vositasi orqali ratsionga darhol tolaga boy mahsulotlarni qo‘shib, muvozanatni saqlang.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'Ekran qarshisidagi injiqlik 📱', 'Telefonni qo‘lidan olganingizda o‘zini yerga tashlaydimi? Ekran vaqtini stresssiz cheklash va sog‘lom chegaralar o‘rnatishni Anacan AI’dan o‘rganing.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'Kunning qahramoni — sizsiz 🌟', 'U har kuni o‘rganayotgan yangi ko‘nikma — sizning mehnatingiz samarasidir. Kayfiyat kundaligini oching va bugun o‘zingizni tik turib olqishlashga arziydigan qayd yozing!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'Tish yuvish janjali 🪥', 'Tish cho‘tkasini ko‘rishi bilan qochadimi? Tavsiya etilgan mahsulotlar bo‘limidagi musiqali yoki aylanadigan bolalar tish cho‘tkalarini ko‘rib chiqing va bu muhim gigiyena jarayonini qiziqarli o‘yinga aylantiring.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'Tabiiy tinchlantiruvchi 🍃', 'Bugun juda shovqinli va yugur-yugurga boy kun bo‘ldimi? Taymer to‘xtadi. Xonani qorong‘ilating, Oq shovqinlar bo‘limidan soy shildirashini yoqing va uning ham, o‘zingizning ham miyangizga orom bering.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'Mantiqiy sakrash 🧩', 'U sabab va oqibat o‘rtasidagi bog‘liqlikni tushuna boshladi. Bloglar bo‘limida taxminan 2 yoshli bolalarning bilish qobiliyatini rivojlantiradigan eng yaxshi uy o‘yinlari haqida o‘qing va ularni amalda sinab ko‘ring.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'Kalsiy qalqoni 🦴', 'Tishlar va suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugun yogurt va pishloq me’yoriga rioya qilganingizni tekshiring.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'Pankeyk mahluqi 🥞', 'Nonushta qilishdan bosh tortyaptimi? Chaqaloq retseptlari bo‘limidagi shakarsiz, bananli pankeyk retseptini sinab ko‘ring. Uni qo‘liga olib o‘zi yeydi, ishtahasi ham ochiladi.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'Dasturxon atrofida sabr sinovi 🥣', 'Ovqat bilan o‘ynab, hamma joyni iflos qilyaptimi? Ovqatlanish taymerini yoqing, ishtaha jarayonini grafik orqali tahlil qiling va ovqatlanish qancha davom etayotganini aniq kuzating.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'Qum va loy terapiyasi 🏖️', 'Iflos bo‘lishdan qo‘rqmang! Kinetik qum yoki sensor o‘yinlar uchun eng yaxshi vositalarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'Energiyani chiqarish san’ati 🧗', 'Unga uyning devorlari torlik qilyapti. Onalar uchun qulay joylar xaritasini oching va sakrab-yugurishi uchun yumshoq qoplamali, xavfsiz o‘yin maydonchasi bor joyni toping.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'Tanlab ovqatlanish 🥦', 'Faqat makaron yoki non xohlayaptimi? Ovqatlanishni nazorat qilish vositasi yordamida menyuni tahlil qiling va yetishmayotgan vitaminlarni Chaqaloq retseptlaridagi qiziqarli taomlar bilan to‘ldiring.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'Chiroqlarni xiralashtiring 🌙', 'Uyqudan 1 soat oldin uydagi barcha yorqin chiroqlar va ekranlarni o‘chiring. Melatonin faqat tinch va xira yoritilgan muhitda ajralib chiqadi.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'Aqlli o‘yinchoqlar 🧩', '2 yoshli bolakayning tafakkurini rivojlantirish uchun shunchaki ovoz chiqaradigan emas, balki o‘rgatuvchi o‘yinchoqlar kerak. Tavsiya etilgan mahsulotlar bo‘limida mantiqiy fikrlashni rivojlantiruvchi yog‘och pazllarni kashf eting.'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'Shakarsiz tort tayyorlaymiz 🎂', 'Ertangi alohida kun uchun foydali tort kerak! Chaqaloqlar uchun retseptlar bo‘limida tozalangan shakarsiz, mevali va bolalar uchun mutlaqo mos tort retseptlarini kashf eting.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'Onaning quvvat manbai 🥗', 'O‘z quvvatingizni tiklashni unutmang! Foydali retseptlar bo‘limidan yeryong‘oq pastasi va oqsil qo‘shilgan, bir zumda quvvat beruvchi smuzi tayyorlang.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'Mana, rasman 2 yosh! 🎈', '2 yil tinimsiz mehnat, mehr va uyqusiz tunlar. Kayfiyat kundaligiga shu 730 kun davomida his qilgan barcha faxringizni yozing. Siz haqiqatan ham ajoyib onasiz!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'Siz buni uddaladingiz 🥂', 'Ikki yillik fidoyilik! Bola uxlagan bo‘lsa, uy ishlarini qo‘ya turing. Kayfiyat kundaligini oching, o‘zingizga minnatdorlik bildiring va shunchaki dam oling.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', '2 yosh inqirozi? 🌪️', '«Yo‘q»lar va qichqiriqlar ko‘paydimi? Ushbu mashhur davrni yengil o‘tkazish uchun hoziroq Anacan AI’dan hissiy inqirozlarni boshqarish usullarini oling.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'Stolda o‘tirishni istamaydi 🥣', 'Ovqatdan tez zerikib, qochib ketadimi? Ovqatlanish taymerini yoqing, jarayon davomiyligini qayd eting va majburlab ovqatlantirishdan butunlay voz keching.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'Sokinlikka ehtiyoj 🤫', 'Kechagi shovqin-surondan keyin Ovoz o‘lchagich yordamida xonadagi sokinlikni saqlang. Kechasi bo‘linadigan uyqu uning ham, sizning ham kayfiyatingizga salbiy ta’sir qiladi.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'Tug‘ilgan kundan keyingi tartibsizlik 🌪️', 'Kechagi bazmdan keyin uy ag‘dar-to‘ntar bo‘lib yotibdimi? Darrov tozalashga shoshilmang. Bugunni endigina 2 yoshga to‘lgan kichkintoyingiz bilan shunchaki dam olishga bag‘ishlang.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'Tabiat san’atkori 🍂', 'Uydan chiqing! Bog‘dagi barglar va toshlar sezgilarni rivojlantirish uchun eng yaxshi materiallardir. Onalar uchun qulay joylar orasidan ko‘kalamzor hududi keng bo‘lgan maskanni toping.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'Ko‘proq suv, oson hazm 💧', 'Yugurib-o‘ynab, suv ichishni unutadimi? Taglik kuzatuvchisiga ertalabki qaydni kiriting va qabziyat xavfini kamaytirish uchun suyuqlik hamda kletchatka muvozanatini darhol tahlil qiling.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'Kechki ertak odati 📖', 'Siz o‘qib bergan ertakni o‘z so‘zlari bilan takrorlayaptimi? Nutq rivojidagi bu ajoyib sakrashni darhol ovozli video sifatida Chaqaloq albomiga qo‘shing va kelajak uchun saqlab qo‘ying.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', '“Meniki!” davri 🧸', 'Bog‘da o‘yinchog‘ini boshqalar bilan bo‘lishmay, baqiryaptimi? 2 yoshdagi egotsentrizmni tajovuzkorlikka aylantirmasdan, qanday qilib to‘g‘ri boshqarishni Anacan AI-dan bilib oling.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'Yallig‘lanishga qarshi kuch 🍵', 'Bolani ko‘taraverib belingiz va qo‘llaringiz og‘riyaptimi? Ayollar uchun foydali retseptlardan biri — zanjabil va limonli choy damlab, tanangizning tiklanishiga yordam bering.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechqurungi uyg‘oqlik vaqti juda cho‘zilib ketdimi? Uyqu taymerini yoqing va jadvalni kuzating. Balki kunduzgi uyquni 20 daqiqaga qisqartirish vaqti kelgandir!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'Taqlid qilishda davom etadi 🦜', 'Siz telefonda gaplashganingizda, u ham pultni olib qulog‘iga tutadimi? U sizni 100% takrorlayapti! Unga yaxshi namuna bo‘lishga harakat qiling.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', '“Yo‘q” so‘zining kuchi 🛑', 'Biror narsa taklif qilsangiz, boshini chayqab “yo‘q” deydimi? Bu qaysarlik emas, balki o‘z fikrini ifodalashdir. Unga tanlash imkonini berib, tinchlantiring.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'Dadaning kulgili qiliqlari 🤡', 'Chaqaloqni kuldirishning eng yaxshi usuli — dadasining g‘alati tovushlar chiqarishi. Bu oqshomdagi quvnoq lahzalardan farzandingiz bilan birga zavqlaning.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'Shakarsiz, ammo mazali 🥞', 'Shirinlik xohlayaptimi? Do‘konga bormang. Chaqaloq retseptlaridagi atigi 10 daqiqada tayyorlanadigan bananli va olmali pankeyklarni sinab ko‘rib, ishtahasini oching.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'Tish cho‘tkasi jangi 🪥', 'Tishlarini tozalash katta jangga aylanadimi? Tavsiya etilgan mahsulotlardan musiqali yoki sevimli multfilm qahramoni tasvirlangan cho‘tkalarni topib, bu jarayonni darhol o‘yinga aylantiring.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'Tabiiy tinchlantiruvchi 🍃', 'Bugun juda shovqinli va yugur-yugurga boy kun bo‘ldimi? Taymer to‘xtadi. Xonani qorong‘ilating, Oq shovqinlardan soy shildirashini yoqing va miyangizga ham orom bering.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'Temir qalqoni 🥩', 'Quvvati pasaydimi yoki shunchaki charchadimi? Ovqatlanishni nazorat qilish vositasi yordamida bugun qancha temir (go‘sht, dukkaklilar) iste’mol qilganini tekshiring va yetishmaganini darhol to‘ldiring.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'Shifokor o‘yini boshlandi 🩺', 'Ayiqchasiga ukol qilyaptimi? Tasavvurga boy o‘yinlar ayni avjida. Bu yoqimli lahzani Chaqaloq fotosessiyasi bilan suratga olib, unutilmas xotira sifatida saqlang.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'Sizga ham tanaffus kerak ☕', 'Boladan bir zumga uzoqlashib, nafas rostlang! Onalar uchun qulay joylardan bolalar burchagi bor kafe toping va issiq qahvangizni xotirjam iching.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'Yotoqdan qochish rejasi 🏃‍♂️', 'Uyqu vaqti kelganda qochib yashirinadimi? Uyqu taymerini yoqing, Oq shovqinlardan o‘rmon shovqinini qo‘yib, xonani sokin g‘orga aylantiring.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'Parallel o‘yindan birgalikdagi o‘yinga 👶', 'Boshqa bolalar bilan bir muhitda o‘ynashga qiziqishi ortadi. Bloglar bo‘limida 2 yoshli bolalarning ijtimoiylashuv sirlari va bolalar maydonchasidagi xulq-atvor psixologiyasi haqida bilib oling.'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'Kiyinishdagi qaysarlik 👗', '“Bu shimni xohlamayman!” deb yig‘layaptimi? Ertalabki kiyinish injiqliklarini kamaytirish va unga mustaqil tanlash imkonini berish yo‘llarini Anacan AI’dan o‘rganing.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'Kichkina oshpaz ish boshida 👨‍🍳', 'Oshxonada sizga yordam berib, xamir qoryaptimi? Ust-boshi unga belangan bu kulgili lahzani ovozli video qilib yozib oling va bir umrlik xotira yarating.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'Do‘kondagi qiy-chuv 🛒', 'Jamoat joyida xohlagan narsasi olib berilmagani uchun o‘zini yerga tashladimi? Atrofdagilarning nigohlarini unuting va 2 yosh injiqliklarini xotirjam boshqarish uchun Anacan AI bilan dardlashing.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'Tunda uxlay olmadingizmi? ☕', 'Tunda qayta-qayta uyg‘onish quvvatingizni tugatdimi? Ayollar uchun foydali retseptlar orasidan kofeinsiz ham bir zumda quvvat beradigan, oqsilga boy yeryong‘oq pastali smuzi tayyorlab, tetiklaning.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'To‘satdan uyg‘onishlar 🌌', 'Yarim tunda yig‘lab uyg‘onib, tinchlanmayaptimi? Tungi vahima va dahshatli tush o‘rtasidagi farqni tushunish hamda to‘g‘ri yo‘l tutish uchun Anacan AI ekspertiga yozing.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'Tish cho‘tkasi uchun kurash tugaydi 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini ochmay qo‘yadimi? Bu jarayonni osonlashtiradigan musiqali va ergonomik modellarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan topib, kundalik odatni o‘yinga aylantiring.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'Temir qalqoni 🥩', 'Harakatchan kichkintoyda kamqonlik yuzaga kelmasligi va u doimo tetik bo‘lishi uchun Chaqaloq retseptlari bo‘limidan chaynash oson, mazali sabzavotli go‘shtli köftalarni topib, ishtahasini oching.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'Sahifalarni yirtishga ishtiyoq 📖', 'O‘qish o‘rniga kitob sahifalarini yirtyaptimi? Kitob o‘qish odatiga zarar yetkazmasdan bu muammoni qanday hal qilish mumkinligini hoziroq Anacan AI-dan so‘rang.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', '5 daqiqalik quvvat ⚡', 'Kunduzi oyoqda turgancha mudrayapsizmi? Ayollar uchun foydali retseptlar bo‘limidan bir zumda quvvat beradigan, antioksidantlarga boy rezavorli suli bo‘tqasini tayyorlab, tanangizga tetiklik baxsh eting.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'So‘zlardan gaplargacha 🗣️', 'Kichkintoyingiz 3-4 so‘zdan iborat kulgili gaplar tuza boshladimi? Nutq rivojidagi bu ajoyib sakrashni qo‘llab-quvvatlaydigan eng yaxshi uy o‘yinlari va bo‘g‘in mashqlari haqida Bloglar bo‘limida o‘qing.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'Massaj vaqti 💆‍♂️', 'Bola uxlagach, kun davomida to‘plangan stressdan xalos bo‘lish uchun juftingiz bilan bir-biringizning yelkangizni massaj qiling. Siz bir jamoasiz!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'Xayolan mashina haydash 🚗', 'Bo‘sh quti yoki o‘yinchoqni olib, uni rul kabi aylantirib, tovushlar chiqaryaptimi? Ramziy o‘yinlar (xayoliy o‘yinlar) ayni paytda faol rivojlanmoqda!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'Onalarning dardlashuvi 💬', '«Nega mening bolam bunday qilyapti?» degan o‘y sizni tinch qo‘ymayaptimi? Anacan Hamjamiyatiga kiring va boshqa onalarning o‘xshash hikoyalarini o‘qing.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'Kalsiy zaxirasi 🦴', 'Tishlar va suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugun qatiq va pishloq me’yorini iste’mol qilganingizni tekshiring hamda yetishmagan miqdorni to‘ldiring.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', '«O‘zim yeyman» degan qat’iyat 🥦', 'Qoshiqni qo‘lingizdan olmoqchi. Olishiga ruxsat bering. Ust-boshi kir bo‘ladi, ammo bu mustaqillik hissi uning uchun juda muhim.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'Kunning qahramoni — sizsiz 🌟', 'U har kuni o‘rganayotgan yangi ko‘nikma, mustaqil tashlayotgan har bir qadam — sizning mehnatingiz samarasidir.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'Aqlli o‘yinchoqlar 🧩', '2 yoshli bolaning tafakkurini rivojlantirish uchun shunchaki ovoz chiqaradigan emas, balki o‘rgatuvchi o‘yinchoqlar kerak. Tavsiya etilgan mahsulotlar bo‘limida mantiqiy fikrlashni rivojlantiruvchi yog‘och pazllar va shakllarni toping.'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'Ich qotishi muammosi bormi? 🚽', 'Yugurib-o‘ynab, suv ichishni unutib qo‘yadimi? Tagligini almashtirganda najasini kuzating. Ich qotishi xavfi bo‘lsa, buni ilovaga qayd eting va darhol Ovqatlanishni nazorat qilish vositasi yordamida ratsioniga kletchatkaga boy mahsulotlarni qo‘shing.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'Kun tartibini tahlil qilamiz ⏱️', 'Kechqurun uxlab qolishi 40 daqiqa davom etdimi? Uyqu taymeri grafigini ko‘ring. Balki kunduzgi uyqusini 20 daqiqaga qisqartirib, kechki uyqu vaqtini ertaroqqa surishning ayni paytidir.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'Shakarsiz, ammo shirin 🍪', 'Tushlikdan keyin tamaddi qilishni xohlayaptimi? Do‘kondagi pechenyelar shart emas. Chaqaloq retseptlari bo‘limidagi 10 daqiqada tayyorlanadigan xurmo va suli qo‘shilgan foydali shirinliklarni pishiring.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'Kulgili yuz ifodalari 🤪', 'Ko‘zgu qarshisida turli qiyofalar qilyaptimi? Bu quvnoq lahzani o‘tkazib yubormang! Darhol Chaqaloq fotosessiyasidagi kulgili ramkalar bilan bezatib, albomga qo‘shing.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'Sizga ham tanaffus kerak ☕', 'Uydan chiqib, biroz nafas rostlang! Onalar uchun qulay joylar bo‘limidan yaqin atrofdagi bolalar burchagi bor kafeni toping, issiq qahvangizdan xotirjam bahramand bo‘ling va boshqa onalar bilan tanishing.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'Likopchaning rangi noto‘g‘ri! 🎨', 'Ovqatni yashil emas, qizil likopchada berganingiz uchun janjal boshlandimi? Bu yoshga xos mantiqsiz qaysarliklarni boshqarish bo‘yicha tavsiyalarni Bloglar bo‘limida o‘qing.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'Onaning bel og‘rig‘i 🧘‍♀️', '13+ kg vaznli kichkintoyingizni ko‘taraverib belingiz og‘riyaptimi? Ayollar uchun foydali retseptlardan mushaklarni bo‘shashtiruvchi zanjabil choyini damlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696', 'Yashirin taqlidchi 📸', 'U ham sizga o‘xshab telefonda gaplashyaptimi yoki harakatlaringizni takrorlayaptimi? Bu kulgili lahzani Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomga qo‘shing.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'Hamma narsani yerga otish ishtiyoqi 🛑', 'Jahli chiqqanda yoki zerikkanda qo‘lidagi narsani uloqtiradimi? Bunday hissiy reaksiyalarni qanday qilib muloyimlik bilan to‘g‘ri yo‘naltirish mumkinligini Bloglar bo‘limidagi maqolalardan o‘qing.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'Bo‘yoqli qo‘llar san’ati 🎨', 'Ranglar bilan o‘ynab, yuz-ko‘zini bo‘yab tashladimi? Jahlingiz chiqishi o‘rniga bu kulgili va ijodiy lahzani darhol suratga olib, Chaqaloq albomiga eng rang-barang xotira sifatida qo‘shing.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'Tabiiy tinchlantiruvchi 🍃', 'Taymer to‘xtadi. Bola uxladi. Endi o‘zingizni qadrlang! Ayollar uchun foydali retseptlardan melissa choyini damlang, divanga yoting va shu charchatgan kundan keyin sukunatga sho‘ng‘ing.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', 'O‘zim yuvinaman! 🧽', 'Vannada cho‘tka yoki mochalkani qo‘lingizdan tortib oladimi? Uning mustaqil bo‘lish istagini qo‘llab-quvvatlaydigan, bolalar uchun xavfsiz cho‘milish vositalarini Tavsiya etilgan mahsulotlardan izlang.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', '5 daqiqalik quvvat ⚡', 'Yugurib-yelib holdan toydingizmi? Ayollar uchun foydali retseptlardan bir zumda quvvat beradigan, oqsilga boy yeryong‘oq pastali smuzi tayyorlab, kuchingizni tiklang.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'Uyqu rejimi tahlili ⏱️', 'Kechqurun yotoqda uzoq vaqt ag‘darilib yotadimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyqusini 20 daqiqaga qisqartirib, kechki uyqu vaqtini oldinroqqa surish ayni muddaodir.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'Sokinlikning sehrli foni 🌊', 'Kun juda injiqlik va shovqinga to‘la bo‘ldimi? Oq shovqinlardan okean to‘lqinlari ovozini yoqib, uning ham, o‘zingizning ham asab tizimingizni tinchlantiring.'),
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2', 'Sabzavotlar bilan o‘yin 🥦', 'Ismaloqni rad etadimi? Chaqaloqlar uchun retseptlarda bu vitaminlarni mazali quymoqchalar ichiga qanday mahorat bilan yashirish mumkinligini bilib, uning ishtahasini oching.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'Bo‘y o‘sishidagi sakrash! 📏', 'Shimlari yana kalta bo‘lib qoldimi? 25-oyga yaqin jismoniy rivojlanish tezlashadi. Joriy o‘lchamlarni Rivojlanish kuzatuvchisiga kiriting va o‘sish grafigiga faxr bilan qarang.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'Toza havoni kashf etish 🌳', 'Uy devorlari unga torlik qilmoqda. Onalar uchun qulay joylar orasidan keng va xavfsiz bog‘ toping, u erkin yugurib, bor kuchini sarflasin.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'Dasturxon atrofida sabr sinovi ⏱️', 'Ovqat bilan o‘ynaydi-yu, lekin yemaydimi? Ovqatlanish taymerini yoqing, jarayon davomiyligini kuzating va ishtaha dinamikasini ilovadagi grafik yordamida tahlil qiling.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'Nega to‘satdan uradi? 🛑', 'Jahli chiqqanda qo‘l ko‘taradimi? Bu yoshga xos tajovuzkor his-tuyg‘ularni o‘yinga aylantirib, ularni qanday yumshoq yo‘l bilan o‘zgartirish mumkinligini Anacan AI ekspertidan bilib oling.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'Qahva tanaffusi ☕', 'Uy yumushlari va bolaga qarash... Endi tanaffus vaqti! Onalar uchun qulay joylar orasidan bolalar burchagi bor kafe toping va issiq qahvangizni xotirjam iching.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'Kunning qahramoni — sizsiz 🌟', 'U har kuni o‘rganayotgan yangi ko‘nikma — sizning mehnatingiz samarasidir.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'C vitamini muvozanati 🍊', 'Immunitet kuchli bo‘lishi kerak. Ovqatlanishni nazorat qilish vositasi yordamida u bugun yetarli miqdorda C vitamini olganini hisoblang va menyuni yangilang.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45'::uuid, 'Tugamaydigan «Nega?» davri 🤔', 'Bu nima? Nega bunday?... U endi butun dunyoni savolga tutmoqda! Sabr bilan javob bering, chunki ayni shu paytda uning miyasidagi neyronlar bayram qilmoqda.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'Mukammallik zanjirini uzing 🛑', 'Bolangiz bugun tushlikdan keyin uxlamadi, uy esa ag‘dar-to‘ntarmi? Hechqisi yo‘q! Chuqur nafas oling, siz hamma narsani bir vaqtning o‘zida nazorat qila olmaysiz. Qo‘yib yuboring.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'Sabru toqatingiz tugayaptimi?', 'Xona eshigini yoping va bolani dadasi bilan yolg‘iz qoldiring. Bugun kechqurun uydagi o‘yin maydonchasiga dadasi boshchilik qilsin.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'Uy devorlari ustingizga bostirib kelayotgandekmi?', 'Onalar uchun qulay joylar orasidan bolalar o‘yin burchagi bor kafeni toping. U o‘ynasin, siz esa qahvangizdan zavqlaning.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'O‘zim kiyinaman 👕', 'Hatto shimini boshiga kiyishga urinsa ham, uning mustaqil kiyinishiga to‘sqinlik qilmang. Mustaqil bo‘lish istagi eng yuqori cho‘qqida! Bu kichik g‘alabani Rivojlanish kuzatuvchisida qayd eting.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'Musiqali orom 🎶', 'Kechga yaqin boshlanadigan injiqliklarni tinchlantirishning eng oson yo‘li — uning sevimli kuyini qo‘yib, bag‘ringizga bosgancha sekin raqsga tushish.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'Oshqozon-ichak signallari 💩', 'Taglikni almashtirayotganda qaydlarni kiriting. Ich qotishi xavfi bo‘lsa, ilovadagi tabiiy tolaga boy ovqatlar bo‘yicha tavsiyalar va mevali suv retseptlarini albatta ko‘rib chiqing.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'Ajralishdan qo‘rqyaptimi? 🌌', 'Xonadan chiqishingiz bilan ortingizdan yig‘laydimi? Oq shovqinlardan ona qornidagi tovushni yoqib, unga avvalgi iliq xavfsizlik hissini bering va uxlashiga yordam bering.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'Shakarsiz, ammo shirin 🍪', 'Do‘kondagi pechenyelarga xayr! Chaqaloqlar uchun retseptlar bo‘limida uyda 10 daqiqada tayyorlanadigan xurmo va suli yormasidan foydali shirinliklarni kashf eting.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', '«Yo‘q!» deyish san’ati 🛑', 'Hamma narsaga «yo‘q» deyaptimi? Bu sizga qarshi chiqish emas, balki o‘zligini kashf etishidir. Unga yopiq savollar berish o‘rniga ikkita variantdan birini tanlash imkonini berib, qaysarligini yumshating.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'Xotirangiz yana pand berdimi?', 'Uyda tugab qolgan har bir mayda-chuydani yodda saqlashga urinmang, darhol Xaridlar ro‘yxatiga qo‘shing — qolganini turmush o‘rtog‘ingiz hal qilsin.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'Yarim tunda qichqirib uyg‘onib, tinchimayaptimi?', '2 yosh inqirozi uyquga ham ta’sir qiladi. Ovozini Yig‘i tahliliga eshittirib, muammo nimada ekanini aniqlang.'),
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df', 'G‘ordagi sokinlik 🌌', 'Yugurishdan charchamayapti va uxlashga yotmayaptimi? Uyqu taymerini ishga tushiring, Oq shovqinlardan o‘rmon shovqinini yoqib, xonani sokin uyqu g‘origa aylantiring.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'Sakrash vaqti 🦘', 'Uyda divanlar ustida sakrayaptimi? Onalar uchun qulay joylardan trampolin va yumshoq qoplamali ko‘ngilochar markazni toping, toki u energiyasini xavfsiz sarflasin.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'Juda erta uyg‘onishlar! 🌅', 'Quyosh chiqmasidan uyg‘onib ketyaptimi? Bu uyqu ritmini qanday tartibga solishni o‘rganish uchun hoziroq Anacan AI ekspert yordamchimizdan amaliy tavsiyalar oling.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'Yangi so‘zlar kashfiyoti 🗣️', 'Bugun qanday kulgili so‘z o‘ylab topdi? Til rivojlanishidagi bu ajoyib lahzani ovozli video sifatida Chaqaloq albomiga saqlang — yillar o‘tib uni ko‘rib, rosa kulasiz.'),
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40', 'Tush payti tik turgancha mudrayapsizmi?', 'Sog‘lom retseptlardan kofeinsiz ham bir zumda quvvat beradigan yeryong‘oq pastali smuzi tayyorlang.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'Yotoqda tugamaydigan tomosha 🛌', 'Uxlash o‘rniga yotoqda sakrayaptimi? Uyqu taymeri grafigini kuzating. U energiyasini yetarlicha sarflamaganmi yoki haddan tashqari charchaganmi — darhol tahlil qiling.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy ishlariga shoshilmang! Melissa choyini damlab, shunchaki sukunatdan zavqlaning.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'Kalsiy qalqoni 🦴', 'Tishlar va suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi orqali bugun qatiq va pishloq me’yorini iste’mol qilganingizni tekshiring va yetishmaganini to‘ldiring.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'Kichkina shifokor ish ustida 🩺', 'Ayiqchasiga ukol qilyaptimi yoki qornini tinglayaptimi? Tasavvurga asoslangan o‘yinlar ayni avjida! Bu yoqimli lahzani darhol Chaqaloq fotosessiyasi yordamida suratga olib, unutilmas xotiraga aylantiring.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'Sukunatga ehtiyoj 🤫', 'Xonadagi osoyishtalikni Ovoz o‘lchagich yordamida asrang. Tunda bo‘linadigan uyqu ham uning rivojlanishiga, ham sizning ertalabki kayfiyatingizga salbiy ta’sir qiladi.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'Oxirgi oziq tishlarmi? 🦷', 'Hech bir sababsiz hamma narsani kemiryaptimi va qo‘llari doim og‘zidami? Eng orqa oziq tishlari (ikkinchi oziq tishlar) chiqayotgan bo‘lishi mumkin. Tish chiqishini kuzatish vositasini albatta tekshiring.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'Uy ishlari kutib turishi mumkin 🛑', 'Pol artilmaganmi? Mayli, qolaversin. Kir uyni tozalash mumkin, ammo holdan toygan onaning tiklanishi uzoq davom etadi. Divanga yotib, shunchaki osoyishtalikni tinglang.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'Mevaga qarshilik 🍎', 'Kecha sevib yegan mevasini bugun yerga otayaptimi? Ovqat tanlash bu yoshga xos odatiy muammodir. Sog‘lom retseptlardan qiziqarli va noodatiy taqdimot usullarini ko‘rib chiqing.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'Tasavvuriy o‘yinlar murakkablashmoqda 🧸', 'O‘yinchoqlariga ovqat yedirib, ularni uxlatayaptimi? Bu tasavvur rivojlanishining eng yuqori bosqichi! Empatiyaga oid bu urinishlarni Rivojlanish kuzatuvchisiga qayd eting.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'Kuch — birlikda🥂', 'Bola uxlagach, kun davomida yig‘ilgan stressni yengillatish uchun juftingiz bilan bir piyola choy iching va «biz ajoyib jamoamiz» deb, bir-biringizni qadrlang.'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'Uyqu rejimini tahlil qilamiz ⏱️', 'Kechqurun uxlab qolishi 40 daqiqa davom etdimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyquni 20 daqiqaga qisqartirib, kechki uyqu vaqtini ertaroqqa surish ayni muddaodir.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'Jamoat joyidagi qaysarlik 🛒', 'Do‘konda xohlagan narsasi olib berilmagani uchun o‘zini yerga tashladimi? Atrofdagilarning nigohlariga e’tibor bermang va bunday injiqliklarni xotirjam boshqarish uchun Anacan AI bilan dardlashing.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'Kir bo‘lishdan qo‘rqmang!', 'Kinetik qum yoki sensorli o‘yinlar uchun eng yaxshi vositalarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping va uyingizga buyurtma bering.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'Onaning energiya bombasi ⚡', 'Yugurib-yelishdan ko‘zlaringiz yumilib ketyaptimi? Shirinlikka emas, oqsilga shoshiling! Ayollar uchun foydali retseptlar orasidagi 5 daqiqada tayyor bo‘ladigan yeryong‘oq pastali smuzi bilan quvvat oling.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'Soyalar qo‘rqityaptimi? 🌌', 'Xonani qorong‘ilatganingizda devordagi soyalar uni bezovta qiladimi? Tasavvur rivojlanishi turli qo‘rquvlarni keltirib chiqarishi mumkin. Oq shovqinlar bo‘limidan ona qornidagi tovushni yoqib, xonada xavfsizlik hissini yarating.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'Hojatxonaga ilk qadam? 🧻', 'Ertalab tagligi butunlay quruq qolib, bundan o‘zi bezovta bo‘ladimi? Bu juda yaxshi belgi. Taglik kuzatuvchisiga qayd eting va Bloglar bo‘limida tuvakka o‘rgatishga tayyorgarlik bosqichlari haqida o‘qishni boshlang.'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', '«Yo‘q!» bo‘roni 🛑', 'Har bir taklifingizga baqirib qarshilik qiladimi? Ikki yosh inqirozining shunday qiyin paytlarida xotirjam qolish va jazavalarni o‘yinga aylantirish sirlarini Anacan AI ekspertimizdan hoziroq bilib oling.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'Mantiq izlab 🧩', 'U endi oddiy o‘yinchoqlardan tez zerikadi. Aqlini charxlaydigan va diqqatini jamlashga yordam beradigan yog‘och pazllar hamda geometrik o‘yinlarni Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'Tugamaydigan quvlashmachoq 🏃‍♂️', 'Uxlash o‘rniga divanlar ustida sakrayaptimi? Uyqu taymerini yoqing, jarayon davomiyligini qayd eting va grafik asosida kechki tartibni biroz ertaroq boshlashni o‘ylab ko‘ring.'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'O‘qish emas, hikoya qilish 📖', 'Kechki ertak paytida u sizga rasmlarni tasvirlab beradimi? Bu ajoyib tasavvur lahzasini ovozli yozib oling.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'Suyaklar mustahkamlanmoqda 🦴', 'Jadal rivojlanish uchun kalsiy zarur. Ovqatlanishni kuzatish vositasi yordamida bugun pishloq va qatiq me’yoriga rioya qilganingizni tekshiring va yetishmaganini to‘ldiring.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'Bo‘lishishni istamayaptimi? 🧸', 'Bog‘da boshqa bolalarning o‘yinchog‘i tomon yuguradi, ammo o‘zinikini bermaydimi? Bloglar bo‘limida 2 yoshli bolaga navbat bilan o‘ynashni qanday o‘rgatish mumkinligini bilib oling.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'Kun tartibini to‘liq tahlil qilaylik ⏱️', 'Kechqurun uxlab qolishi 40 daqiqa davom etdimi? Uyqu taymeri grafigini ko‘rib chiqing. Balki kunduzgi uyquni 20 daqiqaga qisqartirib, kechki uyqu vaqtini ertaroqqa surishning ayni paytidir.'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'Sizning kichik nusxangiz 📸', 'Siz xonani supurganingizda u ham latta bilan artadimi yoki sizga o‘xshab yuradimi? Taqlid qilish avjida!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'Shakarsiz, ammo shirin 🍪', 'Do‘kon pechenyelariga xayr! Chaqaloqlar uchun retseptlar orasidan uyda 10 daqiqada tayyorlanadigan xurmo va olmali foydali shirinliklarni topib, uni xursand qiling.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'Kulgili gaplar 🗣️', 'Shirin xatolar bilan tuzgan o‘sha 3–4 so‘zli gaplari oltinga teng! Bu ajoyib rivojlanish davrini o‘tkazib yubormang — darhol ovozli video shaklida Chaqaloq albomiga qo‘shib, xotiraga muhrlang.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'Energiyasini sarflay olmay, hamma narsani buzayaptimi?', 'Onalar uchun qulay joylar xaritasini oching, yumshoq qoplamali va sirpanchig‘i bor xavfsiz parkni topib, unga erkin o‘ynash imkonini bering.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'Oqsil zaxirasini tekshirish 🥚', 'Tez o‘sayotgan mushaklar uchun oqsil juda zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugungi me’yorni (tuxum, go‘sht, dukkaklilar) hisoblang va yetishmovchilik bo‘lsa, menyuni moslashtiring.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'Barmoq bo‘yoqlari san’ati! 🎨', 'Ranglar bilan o‘ynab, yuz-ko‘zini bo‘yoqqa belab oldimi? Jahlingiz chiqishi o‘rniga, bu kulgili va ijodiy lahzani darhol Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomga yuklang.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'Tunda uyg‘onishlar yana boshlandimi? ⏱️', 'Yarim tunda yig‘lab uyg‘onib, qayta uxlashi qiyin bo‘lyaptimi? Uyqu taymeri statistikasini tahlil qiling. Balki kunduzgi uyqu juda cho‘zilib, kechki uyquga xalaqit berayotgandir?'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'To‘satdan tajovuzkorlik 🛑', 'Jahli chiqqanda do‘stlarini itaradimi yoki sizga qo‘l ko‘taradimi? Bu yoshda kuchayadigan tajovuzkor his-tuyg‘ularni qanday qilib muloyimlik bilan to‘g‘ri yo‘naltirish mumkinligini darhol Anacan AI-dan so‘rang.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'Belingiz og‘riyaptimi? 🧘‍♀️', '13+ kg vaznli kichkintoyingizni ko‘taraverib, belingiz zirqirayaptimi? Sog‘lom retseptlar bo‘limidan mushaklarni bo‘shashtiruvchi va yallig‘lanishga qarshi zanjabilli choy damlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'Sukunat uni qo‘rqitadimi?', 'Xonada Oq shovqinlar bo‘limidan ventilyator yoki soch quritgich ovozini yoqib, u uyqu muhitida qanday qilib mukammal xavfsizlik hissini yaratishini ko‘ring.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'Miya tumanligi 🌫️', 'Juda charchadingizmi va hamma narsani unutib qo‘yyapsizmi? Ayollar uchun sog‘lom retseptlar bo‘limidan Omega-3 ga boy yong‘oqli tamaddi tayyorlang va Kayfiyat kundaligiga fikrlaringizni yozib, miyangizni bo‘shating.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'Tuvakka o‘tirishga qarshilik? 🚽', 'Hojatxonaga borishni istamay, yig‘layaptimi? O‘rgatishda tanaffus qilish yoki boshqa usulni sinab ko‘rish kerakligini darhol ekspert yordamchimiz Anacan AI-dan so‘rang.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'Faqat meva yeyaptimi? 🍎', 'Oqsilga boy mahsulotlar yoki sabzavotlarni rad etyaptimi? Ovqatlanishni nazorat qilish vositasi yordamida bugun qancha foydali ozuqa olganini hisoblang va mevali yogurt kabi mazali kombinatsiyalar yarating.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'Onaning suv balansi 💧', 'Bolangizning ortidan yugurib, suv ichishni unutdingizmi? Bosh og‘rig‘ining sababi shu bo‘lishi mumkin. Ayollar uchun foydali retseptlardan foydalanib, yalpiz va limonli detoks suvi tayyorlang va tetiklaning.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'Ertalab ovqat hazmini tekshirish 💩', 'Taglikni almashtirganda najasni kuzating. Qattiq ovqatlar ko‘paygani sari qabziyat xavfi ortadi. Buni ilovaga qayd etib, Oziqlanishni nazorat qilish vositasi yordamida darhol tolaga boy mahsulotlarni (nok, suli) ratsionga qo‘shing.'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'To‘satdan chiqqan tovushlardan qo‘rqish 🌪️', 'Changyutgich yoki blender tovushidan qo‘rqadimi? Xonada Oq shovqinlar bo‘limidan soch quritgich tovushini yoqib, uning qo‘rquvini kamaytiring va asta-sekin uyquga tayyorlang.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'Ranglarni saralash 🔴🔵', 'Mantiqiy rivojlanishini qo‘llab-quvvatlash uchun yoshiga mos geometrik boshqotirmalar (puzzle) va rangli yog‘och o‘yinchoqlarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan qidirib, zehnini charxlang.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'Tishlash va urish 🦖', 'Jahli chiqqanda to‘satdan qo‘l ko‘taradimi yoki tishlaydimi? Bu yoshda kuchayadigan tajovuzkor hissiyotlarni qanday qilib muloyimlik bilan o‘zgartirish mumkinligini Bloglar bo‘limidagi psixologik maqolalardan o‘qing.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'Oyoq kiyimi birdan siqib qoldimi? 👟', 'Yugurayotganda tez-tez qoqiladimi? Oyog‘i o‘sgan bo‘lishi mumkin! Vazn kuzatuvchisiga hozirgi bo‘yi va oyoq kiyimi o‘lchamini kiriting hamda jismoniy rivojlanishini kuzatib boring.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'Suyaklar mustahkamlanmoqda 🦴', 'Jadal rivojlanish uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugungi pishloq va yogurt me’yorini bajargan-bajarmaganingizni tekshiring va yetishmaganini darhol to‘ldiring.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'Siz allaqachon ajoyibsiz 🌟', 'Bugun kun bo‘yi uning ortidan yugurib, charchadingiz. Kayfiyat kundaligini oching, bugun u uchun qilgan eng kichik yaxshiligingizni ham yozing va o‘zingizni tik turib olqishlang!'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'O‘zi ovqat yeyishga qaysarlik 🥄', 'Qoshiqni qo‘lingizdan olib, hamma joyni iflos qilyaptimi? Ovqatlanish taymerini ishga tushirib, bu mustaqillik sinovi qancha vaqt olishini tahlil qiling. Sochilgan ovqatlarga esa shunchaki tabassum qiling.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'Bu shimni xohlamayman! 👗', '“O‘zim kiyinaman!” degan qaysarlik boshlandimi? Ertalabki kiyinish injiqliklarini kamaytirish va unga mustaqil tanlash imkonini berish yo‘llarini Anacan AI’dan o‘rganing.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'Sizga ham do‘stlar kerak 👯‍♀️', 'Faqat bola bilan gaplashishdan charchadingizmi? Onalar uchun qulay joylar bo‘limidan o‘yin guruhlari mavjud markazlarni toping, boshqa onalar bilan muloqot qiling va tajriba almashing.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'Kitobni yirtmaymiz, o‘qiymiz 📖', 'Kechki ertak paytida sahifalarni yirtyaptimi yoki o‘qishingizga xalaqit beryaptimi? Kitob o‘qish odatiga zarar yetkazmasdan bu muammoni qanday hal qilishni darhol Anacan AI’dan so‘rang.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'Sakrash san’ati 🦘', 'Endi divanlar unga kamlik qilyaptimi? Trampolini bor xavfsiz yopiq ko‘ngilochar markazni topib, energiyasini chiqarishiga yordam bering.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'Kichkina rassom ish ustida 🎨', 'Bo‘yoqlar bilan o‘ynab, yuz-ko‘zini bo‘yab tashladimi? Jahlingiz chiqmasin, aksincha, bu quvnoq va ijodiy ondan zavqlaning.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'Tungi uyg‘onishlar qaytdimi? ⏱️', 'Yarim tunda yig‘lab uyg‘onib, qayta uxlashi qiyin bo‘lyaptimi? Uyqu taymeri statistikasini tahlil qiling. Bunga 2 yoshdagi uyqu regressiyasi yoki tish chiqishi sabab bo‘lishi mumkin.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'Tabiiy tinchlantiruvchi 🍃', 'Kun juda shovqinli va yugur-yugur bilan o‘tdimi? Xonani qorong‘ilating, Oq shovqinlardan soy shildirashini yoqing va uning ham, o‘zingizning ham miyangizga orom bering.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'Oqsil zaxirasi qanday? 🍗', 'Faol mushaklar uchun oqsil zarur. Ovqatlanishni nazorat qilish vositasi yordamida uning kundalik oziq-ovqat muvozanatini baholang va menyusini boyiting.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'Sevimli qo‘shiqlar 🎤', 'Bir xil qo‘shiqni tinmay kuylaydimi yoki xirgoyi qiladimi? Uning ritmni his qilishi va nutq rivojlanishini Chaqaloq fotosessiyasidagi musiqa stikerlari bilan albomga qo‘shib, saqlab qo‘ying.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'Rejimni batafsil tahlil qilamiz ⏱️', 'Kechqurun uxlab qolish 40 daqiqa davom etdimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyquni 20 daqiqaga qisqartirib, kechki uyqu vaqtini ertaroqqa surishning ayni paytidir.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'Tugamaydigan «Nega?» savollari 🤔', 'Savol berishdan charchamayaptimi? «Bu nima? Nega?» bosqichi rasman boshlandi! Bolaning bu kashfiyotga bo‘lgan qiziqishiga qanday qilib sabr bilan javob berishni Bloglardan bilib oling.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'Shakarsiz, ammo shirin 🍪', 'Do‘kon pechenyelarini unuting! Chaqaloq retseptlaridan uyda 10 daqiqada tayyorlanadigan foydali shirinliklarni topib, uni xursand qiling.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy ishlariga shoshilmang! Sog‘lom retseptlardan maxsus qahva tayyorlab, divanga yonboshlang va shunchaki sukunatdan zavqlaning.'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'Tozalik yordamchisi 🧹', 'Siz xonani supurayotganingizda, u ham latta bilan artadimi yoki changyutgichga tashlanadimi? Bu kulgili taqlidni darhol Chaqaloq fotosessiyasidagi stikerlar bilan bezatib, albomga yuklang.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'Temir zaxirasini tekshirish 🥩', 'Faol kichkintoy kamqonlikka duch kelmasligi uchun Ovqatlanishni nazorat qilish vositasida uning bugungi temir iste’molini (go‘sht, dukkaklilar) tekshiring va menyuni yangilang.'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'Kunduzgi uyquga qarshi isyon! 🛌', 'Kunduzi uxlashni istamay, qochib yuribdimi? Anacan AI-dan 2 yoshli bolalarning uyquga ehtiyoji va tinch vaqt (quiet time) tashkil etish sirlari haqida so‘rang.'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'Yechinish bo‘yicha mutaxassis! 🧦', 'Paypog‘i yoki shimini o‘zi yechishga harakat qilyaptimi? Bu motorika rivojlanayotganining ajoyib belgisidir.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'Zanjabilning kuchi 🫖', 'Kun bo‘yi yugurib yurishdan belingiz va oyoqlaringiz og‘riyaptimi? Sog‘lom retseptlar bo‘limidan mushaklarni bo‘shashtiradigan choy damlab, dam oling.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'Qushlarni kuzatamiz 🕊️', 'Uyda juda zerikdimi? Yam-yashil bog‘ toping va qushlarga don berib, uning tabiatga mehrini kuchaytiring.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'Hikoya to‘qish vaqti 📖', 'Kitob o‘qishdan zerikdingizmi? Chiroqlarni o‘chiring, Oq shovqinlardan yomg‘ir ovozini yoqing va qorong‘ida birga xayoliy ertaklar to‘qib, uyquga keting.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'Yana pyurega qaytishmi? 🥣', 'Qattiq ovqatlarni chaynashga erinib, yana pyure so‘rayaptimi? Chaqaloqlar uchun retseptlar bo‘limidagi chaynash oson, ammo pyure bo‘lmagan qiziqarli kotlet retseptlarini ko‘rib chiqing.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'Yotoqxona juda issiqmi? 🌡️', 'Chaqaloq yotoqda ko‘p ag‘darilib, terlayaptimi? Xona haroratini tekshiring, uyqu taymerini yoqing va Oq shovqinlar orasidan ventilyator ovozini tanlab, xonani ruhiy jihatdan salqinroq his qiling.'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'Ortingizdan yig‘layaptimi? 🚪', 'Xonadan chiqqaningizda ortingizdan qichqirib yig‘layaptimi? Ayriliq xavotirining ushbu yangi bosqichini muloyimlik bilan yengish usullarini Anacan AI-dan so‘rang.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'Mantiq ishga tushdi 🧩', 'Geometrik shakllarni moslashtirishni yaxshi o‘zlashtiryaptimi? Tafakkurini yanada rivojlantiradigan murakkabroq o‘yinlarni topish uchun Tavsiya etilgan mahsulotlar bo‘limini ko‘rib chiqing.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'Tish pastasini tanlash 🪥', 'Endi suvni tupurib tashlashni o‘rgana boshladimi? Ftorli yoki ftorsiz tish pastasini tanlash haqida Bloglar bo‘limidagi ilmiy maqolamizni albatta o‘qing.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'Loydan tortlar! 🧁', 'Hovlida tuproq bilan o‘ynashni xohlayaptimi? Kir bo‘lishiga ruxsat bering! Sensor rivojlanishni qo‘llab-quvvatlaydigan bu ajoyib lahzalarni Chaqaloq fotosessiyasi yordamida abadiylashtiring.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'Miyangizni qayta ishga tushiring 🧘‍♀️', 'Hamma narsa ustingizga bostirib kelayotgandek tuyulyaptimi? Kayfiyat kundaligini oching va 3 daqiqa davomida to‘xtamasdan nimalarni his qilayotganingizni yozing. Yozish stressni darhol kamaytiradi.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'O‘zim quyaman! 🥛', 'Suvni stakanga o‘zi quymoqchi bo‘lib, hamma joyni ho‘l qilyaptimi? Bu amaliy hayotiy ko‘nikmalarni rivojlantirish uchun Tavsiya etilgan mahsulotlar bo‘limidagi to‘kilmaydigan aqlli stakanlarni ko‘rib chiqing.'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'Eshiklarni qarsillatadimi? 🚪', 'Jahli chiqqanda eshiklarni qarsillatib, yig‘laydimi? Bunday kuchli hissiy portlashlarni boshqarish strategiyalarini o‘rganish uchun hoziroq Anacan AI ekspertimiz bilan bog‘laning.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'Yo‘l-yo‘lakay tamaddi qilmang 🍎', 'O‘zingizni qadrlang! Sog‘lom retseptlar bo‘limidan antioksidantlarga boy rezavor mevalar salatini tayyorlang.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'Hojatxona qog‘oziga qiziqish 🧻', 'Vannaxonada hojatxona qog‘ozini rulondan yechib o‘ynaydimi? Bu qiziqishni imkoniyatga aylantiring: hoziroq Bloglar bo‘limidagi tuvakka o‘rgatishni o‘yin orqali boshlash haqidagi maqolani o‘qing.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'Bir, ikki, uch... 🔢', 'Zinadan chiqayotganda narsalarni sanashga harakat qiladimi? Bu matematik rivojlanishning ilk uchqunlaridir.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'Barcha tishlari chiqdimi? 🦷', 'Oxirgi oziq tishlari chiqyaptimi? Kalsiyga bo‘lgan ehtiyojini qondirish uchun Oziqlanishni kuzatish vositasi orqali bugun qancha yogurt va pishloq iste’mol qilganini albatta tekshiring.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'Gravitatsiya sinovi! 🍎', 'Ovqat yoki o‘yinchoqlarni yuqoridan pastga tashlashni yaxshi ko‘radimi? Bu fizik tajribalarni to‘xtatish o‘rniga, ularni boshqa yo‘nalishga burishni Anacan AI’dan o‘rganing.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'Kletchatka yetishmayaptimi? 💩', 'Najas qattiqlashib, ich qotishi bezovta qilyaptimi? Buni Taglik kuzatuvchisiga qayd eting va Oziqlanishni nazorat qilish vositasi yordamida darhol menyuga qora olxo‘ri yoki suli qo‘shing.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'Birinchi o‘yin do‘sti 👯‍♂️', 'Parkda boshqa bir bola bilan muntazam o‘ynashga harakat qilyaptimi? Onalar uchun qulay joylar bo‘limidan ijtimoiylashuvning ushbu yangi bosqichini qo‘llab-quvvatlaydigan bolalar kafelarini toping.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'Uyqu taymeri tahlili ⏱️', 'Kechqurun juda kech uxlayaptimi? Uyqu taymeri grafigiga qarang. Kunduzgi uyquni asta-sekin qisqartirish va kechki uyqu vaqtini oldinroqqa surish payti yaqinlashmoqda.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'Oyoq kiyimi birdan siqib qoldimi? 👟', 'Yugurayotganda tez-tez qoqilib ketyaptimi? Oyog‘i o‘sgan bo‘lishi mumkin! Rivojlanish kuzatuvchisiga hozirgi bo‘yi va oyoq kiyimi o‘lchamini kiriting hamda jismoniy rivojlanishini kuzatib boring.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'Qahvami yoki suv? 💧', 'Charchoqni kofein bilan bosishga urinmang! Ayollar uchun foydali retseptlar orasidan quvvat beruvchi, oqsil va mevalarga boy detoks ichimliklarini kashf eting.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'Oshpaz oshxonada 👩‍🍳', 'Chaqaloqlar uchun retseptlardan shakarsiz pechenye xamirini birga qoring. Shunda uning mayda motorikasi rivojlanadi va o‘z mehnati mahsulini ishtaha bilan yeydi.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'Kichkina alpinist 🧗', 'Mebel ustiga chiqish uning sevimli mashg‘ulotiga aylandimi? Uyni imkon qadar xavfsiz qilish uchun Tavsiya etilgan mahsulotlar bo‘limidagi maxsus himoya vositalarini ko‘rib chiqing.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'Shildiragan suvlar 🌊', 'Bugun juda jo‘shqin va yugur-yugurlarga boy kun bo‘ldimi? Chiroqlarni xiralashtiring, Oq shovqinlar bo‘limidan soy shildirashini yoqing va ikkovingiz ham shunchaki sokinlikka cho‘ming.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'O‘zingizni olqishlang 🌟', 'Kunni injiqliklarsiz yakunlay oldingizmi? Siz bo‘lmaganingizda, bunday rivojlanish ham bo‘lmasdi. Kayfiyat kundaligini oching va fidoyiligingiz uchun o‘zingizga katta rahmat yozing!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'O‘yinchoqlarga mehr 🧸', 'Ayiqchasiga alla aytyaptimi yoki ustini yopyaptimi? Bu kuchli hamdardlik tuyg‘usi rivojlanayotganidan dalolat. Buni Chaqaloq albomiga ovozli video sifatida qo‘shib, uning mehribonligini qayd eting.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'Lug‘at boyligidagi sakrash 🗣️', 'So‘z boyligi qanday? Bloglar bo‘limida shu oyga xos nutq rivojlanishi me’yorlari va rivojlanishni qo‘llab-quvvatlovchi uy o‘yinlari bilan tanishing.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'Taomlar shaklga kiradi ⭐️', 'Oddiy to‘g‘ralgan mevani yemayaptimi? Chaqaloqlar uchun retseptlardagi yulduz yoki hayvon shaklida bezatilgan qiziqarli likopchalardan ilhomlanib, ovqatlanishni ko‘rgazmali o‘yinga aylantiring.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'Yashirinib kaka qilyaptimi? 🙈', 'Parda ortiga yoki burchakka o‘tib, hojatini chiqaryaptimi? Bu tuvakka o‘rgatishga tayyorlikning eng muhim psixologik belgisidir! Buni taglik kuzatuvchisiga qayd etib, Bloglardagi o‘rgatish haqidagi maqolalarni o‘qing.'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'Belingiz zirqirayaptimi? 🧘‍♀️', 'Og‘irlashib borayotgan kichkintoyingizni ko‘tarishdan mushaklaringiz taranglashgan. Ayollar uchun foydali retseptlardan yallig‘lanishga qarshi zanjabilli choy damlab, biroz yotib, o‘zingizga vaqt ajrating.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', 'O‘zim kiyinaman san’ati 👕', 'Shimni boshiga, ko‘ylakni esa oyog‘iga kiyishga urinyaptimi? Mustaqil bo‘lishga qaratilgan bu kulgili urinishni aslo o‘tkazib yubormang! Darhol Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomga yuklang.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'Ko‘lmaklarni o‘rganamiz 🌧️', 'Yomg‘irdan keyin uyda o‘tirib bo‘lmaydi! Ona uchun qulay joylar bo‘limidan yaqin atrofdagi parkni toping, unga rezina etiklarini kiydirib, loyda sakrashiga ruxsat bering.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'Uyqu vaqti surilyapti ⏱️', 'Kunduzgi uyqudan bosh tortdimi? Kechqurun o‘ta charchab, injiqlik qilmasligi uchun uyqu taymerini ishga tushiring va kechki tartibni 30 daqiqa oldinga suring.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'Barmoqlar motorikasi rivojlanmoqda 🧩', 'U oddiy pazllarni allaqachon yodlab olgan. Aqlini yanada charxlaydigan murakkabroq, ko‘p qismlardan iborat yog‘och boshqotirmalarni Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'Polga yotib olib yig‘lash xuruji 🛑', 'Jamoat joyida o‘zini yerga tashlab, baqiryaptimi? Atrofdagilarning qarashlariga e’tibor bermang! Bunday kuchli hissiy portlashlarni xotirjam boshqarish uchun Anacan AI bilan suhbatlashib, kerakli usullarni o‘rganing.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'Kitobni yirtish emas, o‘qish 📖', 'Kechki ertak paytida sahifalarni yirtyaptimi? O‘qishga bo‘lgan qiziqishiga zarar yetkazmasdan, uning diqqatini ertakka qanday jalb qilish mumkinligini Bloglar bo‘limidan o‘qing.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'Kalsiy faqat sutda emas 🧀', 'Sut ichishni rad etyaptimi? Suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugun qancha pishloq, qatiq yoki brokkoli iste’mol qilganini hisoblab, yetishmayotgan miqdorni to‘ldiring.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'Kiyimlarni taxlash o‘yini 🧺', 'Siz kiyimlarni yig‘ayotganingizda u ham yordam bermoqchimi? Paypoqlarni juftlashni unga topshiring! Bloglarda o‘yin orqali mas’uliyat hissini singdirish sirlarini o‘qing.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'Qorong‘i xonadan qo‘rqish 🌌', 'Chiroqni o‘chirganingizda yig‘layaptimi? Tasavvuri rivojlangani sari qo‘rquvlari ham ortadi. Oq shovqinlar bo‘limidan ona qornidagi tovushni yoqib, unga avvalgi xavfsizlik hissini qaytaring.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'Kitobga qiziqish qanday paydo bo‘ladi? 📖', 'O‘qish o‘rniga sahifalarni yirtishni xohlayaptimi? Kitob o‘qish odatiga zarar yetkazmasdan uning e’tiborini ertakka qanday jalb qilish haqida Anacan AI’dan amaliy usullarni so‘rang.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'Temirning siri: Vitamin C 🍋', 'Temir organizmda yaxshi o‘zlashtirilishi uchun Oziqlanishni nazorat qilish vositasidagi bugungi menyuni ko‘rib chiqing. Go‘shtli taom yoniga albatta limonli yoki pomidorli salatni mo‘l qilib qo‘shing.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'Onaning qahva vaqti ☕', 'Uy ishlarini bir chetga surib, biroz nafas rostlang! Onalar uchun qulay joylar orasidan bolalar o‘yin burchagi bor kafeni toping, issiq qahvangizdan huzur qiling va boshqa onalar bilan tanishing.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'Tun sadosi: Poyezd 🚂', 'Kunduzgi shovqin-surondan keyingi to‘satdan paydo bo‘lgan sukunat uni bezovta qilyaptimi? Uydagi boshqa tovushlarni to‘sish uchun Oq shovqinlar orasidan poyezdning bir maromdagi tovushini yoqing va uni uyquga sozlang.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'Oyoq kiyimi birdan siqib qoldimi? 👟', 'Yugurayotganda qoqilib ketyaptimi yoki oyoq kiyimini yechishga urinyaptimi? Oyog‘i o‘sgan bo‘lishi mumkin! Joriy o‘lchamlarni Rivojlanish kuzatuvchisiga kiriting va jismoniy rivojlanishini darhol kuzatib boring.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'Shakarsiz quvvat sharchalari 🍪', 'Do‘kondagi shirinliklarga xayr! Chaqaloqlar uchun retseptlar orasidan atigi 10 daqiqada tayyorlanadigan, xurmo va suli qo‘shilgan foydali hamda mazali gazaklarni topib, uni xursand qiling.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'To‘satdan paydo bo‘ladigan tajovuzkorlik 🦖', 'Jahli chiqqanda do‘stlarini itaradimi yoki sizga qo‘l ko‘taradimi? Bu yoshda kuchayadigan tajovuzkor hissiyotlarni qanday muloyimlik bilan to‘g‘ri yo‘naltirish mumkinligini darhol Anacan AI’dan so‘rang.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'O‘zingizni unutmang ⚡', 'Tush payti holsizlanib qolasizmi? Shirinlikka oshiqmang! Ayollar uchun foydali retseptlardan bir zumda quvvat beradigan, oqsilga boy yeryong‘oq pastali smuzi tayyorlab, kuchingizni tiklang.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'Taymer yordamida uyqu tahlili ⏱️', 'Kechqurun uxlab qolishi juda uzoq cho‘zildimi? Uyqu taymerini ishga tushiring va grafikni kuzating. U bor energiyasini to‘liq sarflamaganmi yoki haddan tashqari charchaganmi — tahlil qiling.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Endi uy ishlariga qo‘l urmang! Ayollar uchun foydali retseptlardan melissa choyini damlab, kun davomida yig‘ilgan charchoqni issiq bug‘ bilan tarqating.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'Oqsil zaxirasi qanday? 🍗', 'Tinmay yugurib, sakraydigan mushaklar uchun oqsil juda zarur. Ovqatlanishni nazorat qilish vositasi yordamida uning kundalik oziq-ovqat muvozanatini baholang va menyusini boyiting.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'Tugamaydigan «Nega?» savollari 🤔', '«Bu nima? Nega bunday?» bosqichi rasman boshlandi! Bolaning bu cheksiz kashf etish qiziqishiga qanday sabr bilan va uning rivojlanishiga yordam beradigan tarzda javob berishni Bloglardan bilib oling.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'Eski ovozli yozuvlar 🎤', 'Bolangiz uxlagach, Chaqaloq albomini oching va uning bir necha oy oldin chiqargan o‘sha yoqimli tovushlarini tinglang. Qanchalik tez ulg‘ayayotganini ko‘rib, faxrlaning!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', '“Meniki!” bosqichi 🧸', 'Bog‘da o‘yinchoqlarini hech kimga bermayaptimi? 2.5 yoshga yaqinlashayotgan bolaga navbat bilan o‘ynashni qanday o‘rgatish mumkinligini Anacan AI’dan so‘rab bilib oling.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'Ko‘zgu qarshisidagi tomosha 🤪', 'Yuzini turli qiyofaga solib, o‘ziga qaragancha qah-qah otib kulyaptimi? O‘zini kashf etayotgan bu kulgili lahzani darhol videoga olib, Chaqaloq albomiga qo‘shing va kunlik stressingizni unuting.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'Sizga ham tanaffus kerak ☕', 'Uydan chiqib, biroz nafas rostlang! Onalar uchun qulay joylar bo‘limidan yaqin atrofdagi bolalar burchagi bor kafeni toping, issiq qahvangizni huzur bilan iching va boshqa onalar bilan tanishing.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'O‘zingiz bilan faxrlaning 🌟', 'U har kuni o‘rganayotgan yangi ko‘nikma va tashlayotgan har bir ishonchli qadam — sizning fidoyiligingiz samarasidir. Kayfiyat kundaligini oching va bugun o‘zingizni tik turib olqishlashga arziydigan bir qayd yozing!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'Ovqatni o‘ynab, uloqtiryaptimi? 🥣', 'Stol atrofida o‘tirishdan zerikib, qoshiqni uloqtiryaptimi? Ovqatlantirish taymerini yoqing, jarayon davomiyligini grafik orqali tahlil qiling va majburlab ovqatlantirishdan butunlay voz keching.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'Bir rangli ovqatlanish? 🟡', 'Faqat sariq rangli taomlarni (kartoshka, makaron, banan) xohlayaptimi? Ovqatlanishni nazorat qilish vositasi yordamida uning menyusini tahlil qiling hamda Chaqaloq retseptlaridan rang-barang va sabzavotlar yashirin qo‘shilgan muqobil taomlarni toping.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', 'Men va Sen o‘rtasidagi farq 🗣️', 'Endi o‘zi haqida uchinchi shaxsda emas, «Men» deb gapiryaptimi? Bu katta kognitiv sakrashni qo‘llab-quvvatlash uchun Anacan AI-dan to‘g‘ri muloqot qurish sirlarini hoziroq so‘rang.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'Yana bitta ertak! 📚', 'Uxlashga yotmaslik uchun tinmay yangi bahonalar o‘ylab topyaptimi? Uyqu taymerini ishga tushiring, belgilangan chegaralarga rioya qiling va Oq shovqinlardan okean to‘lqinlari ovozini yoqib, xonada sokin muhit yarating.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'Sakrash san’ati 🦘', 'Zinadan yoki divandan sakrashga urinyaptimi? Harakat ko‘nikmalarini rivojlantirish uchun xavfsiz joy kerak. Onalar uchun qulay joylar bo‘limidan trampolinli yopiq ko‘ngilochar markazni topib, uning kuch-g‘ayratini to‘g‘ri yo‘naltiring.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'Sizning ham quvvatingiz cheklangan 🔋', 'Kun bo‘yi «Yo‘q» deyishdan va ortidan yugurishdan charchadingizmi? Kayfiyat kundaligiga ichingizdagi barcha kechinmalarni yozing. Unutmang, o‘zingizga vaqt ajratish hashamat emas, ehtiyojdir.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'Oyoq kiyimlari teskari! 👟', 'O‘ng oyoq kiyimini chap oyog‘iga, chapini esa o‘ng oyog‘iga kiyib olib, yechishni istamayaptimi? Mustaqil bo‘lishga qaratilgan bu kulgili urinishni Chaqaloq fotosessiyasidagi quvnoq stikerlar bilan bezatib, albomning eng qiziqarli suratiga aylantiring.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'Bananmi yoki telefon? 🍌', 'Banan yoki pultni qulog‘iga tutib, xayolan gaplashyaptimi? Bu — tasavvurga asoslangan o‘yinlarning cho‘qqisi! Ushbu bebaho lahzani ovozli video shaklida darhol Chaqaloq albomiga qo‘shib, xotiraga muhrlang.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'Qorong‘i xonadan qo‘rqish 🌌', 'Chiroqni o‘chirganingizda, xonadagi buyumlarni mahluqlarga o‘xshatyaptimi? Tasavvur kuchaygani sari qo‘rquvlar ham paydo bo‘ladi. Oq shovqinlardan ona qornidagi tovushni yoqib, unga avvalgi mukammal xavfsizlik hissini qaytaring.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'Temir va quvvat siri 🥩', 'Faol kichkintoyda kamqonlik yuzaga kelmasligi uchun Oziqlanishni kuzatish vositasida uning bugungi temir iste’molini (go‘sht, yasmiq, ismaloq) tekshiring va taomnomasini C vitaminiga boy mahsulotlar bilan to‘ldiring.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'Suyuqlik iste’moli va qabziyat 💧', 'Ko‘p yuguradi, ammo kam suv ichadimi? Tagligini almashtirganda ich kelishini kuzating. Qabziyat xavfi bo‘lsa, buni ilovada qayd eting va Oziqlanishni kuzatish vositasi orqali darhol tolaga boy mahsulotlarni (nok, suli) taomnomaga qo‘shing.'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'Rang va shakllar ustasi 🔴🟩', 'Buyumlar, tugmalar yoki o‘yinchoqlarni rangiga qarab guruhlayaptimi? Uning zehnini yanada charxlaydigan va mantiqiy fikrlashini rivojlantiradigan yog‘och pazllarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'Tungi vahimami yoki qo‘rqinchli tush? 🤖', 'Yarim tunda yig‘lab uyg‘onib, hech tinchimayaptimi? Bu ikki holat o‘rtasidagi farqni tushunish va to‘g‘ri psixologik yordam ko‘rsatish uchun Bloglar bo‘limidagi ilmiy maqolalarimizni ko‘rib chiqing.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'Makaron sevgisi 🍝', 'Farzandingiz bir necha kundan beri bir xil ovqatni so‘rayaptimi? Ovqat tanlashdagi injiqlik avjiga chiqqan. Foydali retseptlar orasidan sabzavotlarni yashirish mumkin bo‘lgan qiziqarli souslarni izlab ko‘ring.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'Sukunat zavqi 🤫', 'Nihoyat, xona jimjit bo‘ldi. Ishlarni bir chetga surib, qorong‘ida o‘tiring. Ovoz o‘lchagichni yoqib, bu sukunat darajasini o‘lchang va miyangizga dam bering.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', '800-ni yakunladik!🚀', 'Endi ko‘proq savollar, ko‘proq harakat va o‘ziga xoslik namoyon bo‘ladigan davr boshlandi. Ushbu yangi va hayajonli bosqichni chuqur nafas olib boshlang.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'Mukammal ona haqidagi afsonalar 🛑', 'Bugun ekran qarshisida ko‘p vaqt o‘tkazilgani uchun o‘zingizni ayblayapsizmi? Internetdagi ideal onalarni unuting. Siz o‘z hayotingizda mukammalsiz.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'Dadaning o‘yin maydonchasi 👨‍👧', 'Sabringiz tugayaptimi? Xona eshigini yoping va bolani dadasi bilan yolg‘iz qoldiring. Bu oqshom uydagi o‘yinlarga u boshchilik qilsin.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', '“Nega?” davri 🤔', 'Har bir narsaga “Nega bunday?” deb so‘rayaptimi? Uning miyasi ma’lumotni shimgich kabi singdiradi. Sabrli bo‘ling va unga qisqa, mantiqiy javoblar bering.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'O‘zim quyaman! 🥛', 'Suvni stakanga o‘zi quymoqchi bo‘lib, hamma joyni ho‘l qilyaptimi? Amaliy hayot ko‘nikmalarini rivojlantiradigan, ammo suyuqlik to‘kilishiga yo‘l qo‘ymaydigan aqlli bolalar stakanlarini Tavsiya etilgan mahsulotlar bo‘limidan topib, ishingizni osonlashtiring.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'Oshpaz oshxonada 👩‍🍳', 'Chaqaloqlar uchun retseptlar bo‘limidagi shakarsiz bananli pechenye xamirini birga qoring. Shunda uning motorikasi rivojlanadi, o‘zi tayyorlagan pechenyeni esa zavq bilan yeb, mazza qiladi.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy ishlariga shoshilmang! Sog‘lom retseptlar bo‘limidagi melissa yoki moychechak choyini damlang, divanga cho‘ziling va shunchaki sukunatdan zavqlaning.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'Seniki ham meniki! 🧸', 'Bog‘da birovning o‘yinchog‘ini qaytarib bermayaptimi? Bu egotsentrizm davri. Unga bo‘lishishni majburlab emas, navbat bilan o‘ynash orqali o‘rgating.'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'Kitob qurti 📖', 'Eng sevimli ertak kitobini olib kelib, bir sahifani qayta-qayta o‘qib berishingizni so‘rayaptimi? Takrorlash — uning o‘rganish usuli. Sabr bilan yana o‘qib bering.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'Uy ishlari kutib turadi 🛑', 'Pol artilmaganmi? Mayli, qolaversin. Iflos uyni tozalash mumkin, ammo holdan toygan onaning tiklanishi uzoq vaqt oladi. Divanga cho‘ziling va sukunatga quloq tuting.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'Kun og‘ir o‘tdimi? 📝', 'Kayfiyat kundaligiga bugungi stressingizni yozib, ko‘nglingizni bo‘shating. Barcha onalar bunday qiyin damlarni boshdan kechiradi, siz yolg‘iz emassiz.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'Tasavvurga boy o‘yinlar 🧸', 'Mashinalarini gapirtirib, o‘yinchoq ayig‘iga ovqat beryaptimi? Uning tasavvuri jo‘sh urmoqda. Rivojlanish kuzatuvchisida bu kognitiv sakrashni qayd etib, o‘yinga qo‘shiling.'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'Uyda zerikdingizmi?', 'Onalarga qulay joylar orasidan bolalar o‘yin burchagi bor kafeni toping. U o‘ynasin, siz esa qahvangizni sovitmay iching.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'Musiqiy huzur 🎶', 'Kechga yaqin boshlanadigan injiqliklarni tinchlantirishning eng oson yo‘li — uning sevimli kuyini qo‘yib, bag‘ringizga bosgancha asta raqsga tushishdir.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'Havo g‘alati bo‘lgani uchun uyda qoldingizmi?', 'Ob-havo va kiyim vositasi derazadan qarab bilib bo‘lmaydigan haroratni sizga darhol aytib bersin, parkka chiqing.'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'O‘zim kiyinaman 👕', 'Shimini hatto boshiga kiyib olsa ham, kiyinishga urinishlariga xalaqit bermang. Mustaqil bo‘lish istagi ayni cho‘qqisida! Unga vaqt bering, o‘zi sinab ko‘rsin.'),
  ('04312503-34be-494a-8896-38312d406a86', 'Xayoliy choyxo‘rlik 🫖', 'Sizni yoki o‘yinchoqlarini xayoliy piyolalarda choy ichishga majbur qilyaptimi? Rolli o‘yinlar aqliy rivojlanishning eng yuqori bosqichidir!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'Onaning bo‘yin og‘rig‘i 🧘‍♀️', 'Polda o‘ynash va bolani ko‘tarishdan bo‘yningiz hamda belingiz qotib qoldimi? Sog‘lom retseptlar bo‘limidagi mushaklarni bo‘shashtiruvchi, yallig‘lanishga qarshi zanjabilli ko‘k choyni damlab, hordiq chiqaring.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'Karavot ostidagi maxluq? 👾', 'Tasavvur rivojlangani sayin qo‘rquvlar ham haqiqiy tus oladi. Agar chaqaloq soyalardan qo‘rqsa, chiroqlarni xiralashtiring va Oq shovqinlar bo‘limidan ona qornidagi tovushni (yurak urishini) yoqib, unga avvalgi mukammal xavfsizlik hissini qaytaring.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'Sirpanchiqdagi navbat janjali 🛑', 'Bog‘da boshqa bolalarni kutishni istamayaptimi? 2.5 yoshga yaqinlashganda navbat va sabr tushunchalarini qanday singdirish haqida Bloglar bo‘limidagi ijtimoiylashuvga oid maqolalarni albatta o‘qing.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'O‘zingizni aybdor his qilmang 💖', 'Bugun qaysarliklari sabringizni tugatib, ovozingizni balandlatishga majbur qildimi? Ichingizdagi siqilishlarni Kayfiyat kundaligiga yozib tashlang. Siz robot emassiz, mukammal bo‘lishingiz shart emas!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'Teskari kiyinish urf bo‘ldi! 👕', 'Shimini teskari, oyoq kiyimlarini esa noto‘g‘ri oyog‘iga kiyib oldimi va yechishni istamayaptimi? Mustaqil bo‘lishga qaratilgan bu kulgili urinishiga aralashmang!'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'Kunduzgi uyquga qarshi isyon! ⏱️', 'Kunduzi uxlashdan bosh tortib, endi haddan tashqari charchadimi? Uyqu taymeri jadvalini tekshiring va tungi vahimalarning oldini olish uchun kechki tartibni kamida 40 daqiqa oldinga suring.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'Ichini ushlab turibdimi? 💩', 'Tuvakka o‘rgatish arafasida tik turib, ichini ushlab qolayaptimi? Bu psixologik qabziyatga olib kelishi mumkin. Buni taglik kuzatuvchisiga qayd etib, taomnomasiga darhol o‘rik yoki suli qo‘shing.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'To‘rt devor orasida zerikyapti 🌳', 'Uyda energiyasini sarflay olmay, hamma narsani irg‘ityaptimi? Ona uchun qulay joylar xaritasini oching, yumshoq qoplamali va sirpanchig‘i bor xavfsiz parkni topib, unga ochiq havoda erkin o‘ynash imkonini bering.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'Bo‘y va vaznda keskin o‘sish! 📏', 'Kiyintirayotganda ko‘ylaklari torayganini yoki oyoq kiyimi siqayotganini sezdingizmi? Vazn kuzatuvchisiga hozirgi bo‘yi va o‘lchamlarini kiriting hamda rivojlanish egri chizig‘i qanday ko‘tarilayotganini faxr bilan kuzating.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'Temir zaxirasini tekshiring 🥩', 'Rangi oqarganmi yoki tez charchaydimi? Ovqatlanishni nazorat qilish vositasida bugun qancha temir olganini tekshiring va temirning so‘rilishini yaxshilash uchun go‘sht bilan birga albatta C vitamini (limon, pomidor) bering.'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'Sizga ham do‘st kerak 👯‍♀️', 'Kun bo‘yi faqat bolalar tilida gapirishdan charchadingizmi? Ona uchun qulay joylar orasidan onalar ko‘p yig‘iladigan bolalar kafelarini topib, o‘zingizga ham muloqot qilish uchun muhit yarating.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'Tezkor ehtiyojlar 🛒', 'Shampun, taglik yoki suli yormasi tugadimi? Bularni yodda saqlashga urinmang, Xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan sinxronlashtiring.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'Istagi bajarilmasa, o‘zini yerga tashlab, baqiradimi?', 'Kichik yoshdagi bolalarga xos jazava hali davom etadi. Yonida xotirjam turing, tinchlanganida esa uni quchoqlang.'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'Ertak qahramoni 🪄', 'Bugun kechqurun Aqlli ertaklarda qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: Tunni sevadigan jasur mittivoy.'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', '«Sizni yaxshi ko‘raman» quchog‘i 🫂', 'Kutilmaganda kelib, bo‘yningizdan quchadimi yoki yuzingizni silaydimi? U endi o‘z mehrini jismoniy harakatlar orqali namoyon etmoqda. Bu lahzadan zavqlaning.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'Buyumlarni joyiga qo‘yish 🧸', 'O‘yinchoqni qutiga solib, yana chiqaradimi? Unda «ichida» va «tashqarisida» tushunchalari shakllanmoqda. Bu kognitiv ko‘nikmani Rivojlanish kuzatuvchisiga albatta qayd eting.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'Savolingiz bormi? 🤖', '2 yoshdan keyin bolaning nutqi qanday bo‘lishi kerak? Internetdan javob izlab ovora bo‘lmang, to‘g‘ridan-to‘g‘ri Anacan AI''ga yozing va ilmiy asoslangan javob oling.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'Uzun jumlalar boshlanmoqda! 🗣️', 'U endi 4-5 ta so‘zni birlashtirib, kulgili hikoya aytib beryaptimi? So‘z boyligi jadal oshmoqda! Bu bebaho lahzani o‘tkazib yubormang — darhol ovozli tarzda Chaqaloq albomiga saqlang va rivojlanishini qayd eting.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'Mantiqiy izlanish 🧩', 'U oddiy ikki-uch bo‘lakli pazllarni allaqachon yodlab olgan. Aqlini yanada charxlaydigan, sabab-oqibat bog‘liqligini o‘rgatuvchi murakkab yog‘och o‘yinchoqlarni Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'Hammomda to‘polon 🛁', 'U suvdan chiqishni istamay, yig‘layaptimi? Cho‘milish tartibini stresssiz yakunlash uchun chalg‘ituvchi o‘yinchoqlar va bir mashg‘ulotdan boshqasiga o‘tishning amaliy usullari haqida darhol Anacan AI-dan so‘rang.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'Sirpanchiqda navbat janjali 🛑', 'U bog‘da boshqa bolalarni kutishni istamayaptimi? 2.5 yoshga yaqinlashganda navbat kutish va bo‘lishish tushunchalarini qanday singdirish haqida Bloglar bo‘limidagi ijtimoiylashuvga oid maqolalarni albatta o‘qing.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'Sahifalar jonlanmoqda 📖', 'Ertak o‘qiyotganingizda u hikoyaning oxirini o‘zi to‘qib topyaptimi? Bu ajoyib tasavvur lahzasini qo‘llab-quvvatlaydigan interaktiv o‘qish usullarini Anacan AI yordamida kashf eting.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'Suyuqlik iste’moli va qabziyat 💩', 'U ko‘p yugurib, kam suv ichyaptimi? Tagligini almashtirganda (yoki tuvakda) najasini kuzating. Qabziyat xavfi bo‘lsa, buni ilovaga qayd eting va darhol Ovqatlanishni nazorat qilish vositasi orqali menyusiga qora olxo‘ri yoki suli qo‘shing.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'Yugurish marafoni 🏃‍♂️', 'Yurish endi uning uchun zerikarli, u faqat yuguradi! Xona o‘rtasidagi mayda to‘siqlarni olib tashlang va bu tuganmas energiyani tabassum bilan kuzating.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'Qorong‘ilikdagi o‘yinlar 🐰', 'Uxlashni istamayaptimi va qorong‘ilikdan qo‘rqyaptimi? Xonani butunlay qorong‘i qiling va devorda qo‘llaringiz yordamida soyalar teatrini yarating. Qo‘rquvni o‘yin-kulgiga aylantiring.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'Onaning oflayn vaqti ☕', 'Bolangiz o‘z olamiga sho‘ng‘ib, qo‘g‘irchoqlari bilan gaplashayotganida darhol idish yuvish mashinasi oldiga yugurmang. O‘zingizga bir finjon qahva quying, telefoningizni ham chetga qo‘yib, 15 daqiqaga butunlay oflayn bo‘ling.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'Ilk uzun jumlalar 🗣️', 'Ona, mashina u yoqqa ketdi! Endi u so‘zlarni ketma-ket bog‘lab, mazmunli jumlalar tuzmoqda. Bu tarixiy lahzalarni tinglang va albatta Rivojlanish kuzatuvchisiga esdalik sifatida yozib qo‘ying.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'Blog uchun tanaffus 📱', 'Tuvakka o‘rgatishni boshlash uchun ayni vaqtmi? Ikkilanayotgan bo‘lsangiz, Anacan ilovasining bloglar bo‘limiga kiring va mutaxassislar yozgan, pediatrlar tasdiqlagan maqolalarni o‘qing.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'Kun tahlili 📝', 'Kun og‘ir o‘tdimi? Kayfiyat kundaligiga bugungi barcha stresslaringizni yozib, ichingizni bo‘shating. Barcha onalar bunday og‘ir injiqlik xurujlarini boshdan kechiradi, siz yolg‘iz emassiz.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'Ovqat bilan o‘ynayapti 🥦', 'Makaronni yeyish o‘rniga ezib, atrofga sochyaptimi? Bu yoshda ovqat ham o‘yinchoq hisoblanadi. Qancha yeganini Qidalanish rejasida qayd etib, haftalik muvozanatni kuzatib boring.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'Ertalabki faylasuf 🧦', 'Bugun ertalab paypog‘ini qo‘liga kiyishni xohladimi? O‘jarlik bilan kechadigan bunday kashfiyot onlarida jahlingiz chiqmasin. Mayli, biroz shunday yuraversin — bu uning mustaqillik sinovidir.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'Suvning sehrli kuchi 🛀', 'Kun bo‘yi yugurib, u ham, siz ham charchadingiz. Iliq vanna shunchaki poklanish emas, balki uning asab tizimini tinchlantiradigan eng yaxshi muolajadir.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'Parkdagi xudbinlik 🧸', 'Qumda o‘ynayotganda idishini hech kimga bermayaptimi? 27 oylik davrda bo‘lishish tushunchasi hali juda sust rivojlangan bo‘ladi. Uni xudbinlikda ayblamang, shunchaki navbat bilan o‘ynash qoidasini tushuntiring.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'Dadaning ovozi 📖', 'Bugun kechqurun xonada o‘zgacha muhit yarataylik. Kitob o‘qish yoki ertak aytib berishni dadasining yo‘g‘on va ishonch baxsh etuvchi ovoziga topshirib, siz bir chetda dam oling.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'Mukammal xotira 🧠', 'Kecha yashirib qo‘ygan o‘yinchog‘ingizni bugun ertalab aniq topdimi? Uning uzoq muddatli xotirasi hayratlanarli darajada rivojlangan.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'Suvdan bosh tortish 💧', 'Suv o‘rniga doim shirin sharbatlar so‘rayaptimi? Uning kunlik suvga bo‘lgan ehtiyojini hisoblang va suvni rang-barang, qiziqarli stakanlarda taklif qiling.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'To‘qima hikoyalar 🎭', 'Qo‘lidagi o‘yinchoq ayiqchasini gapirtirib, unga to‘qima hikoyalar aytib beryaptimi? Tasavvuri avjida! Uni chetdan kuzating va hech qanday aralashmang.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'Ertaksiz uxlamaymiz 🪄', 'Klassik ertaklar endi uning e’tiborini tortmayaptimi? Aqlli ertaklarda bosh qahramoni uning o‘zi bo‘lgan maxsus ertak yarating.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'Tartibsizlik ham go‘zal 🌪️', 'Har kuni bir xil o‘yinchoqlarni qutiga yig‘ishdan charchadingizmi? Bugun yig‘ishtirmang! Uydagi tartibsizlik dunyoning oxiri emas, ruhiy xotirjamligingiz muhimroq.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', 'O‘zingiz bilan 10 daqiqa 🛀', 'Xonaga sukunat cho‘kdi. Juftingizdan uydagi barcha ishlarni o‘z zimmasiga olishini so‘rang. Siz esa iliq dush qabul qilib, 10 daqiqa faqat o‘zingiz bilan yolg‘iz qoling.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'Kalsiy faqat sutda emas 🧀', 'Sut ichishdan bosh tortyaptimi? Suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida bugun iste’mol qilgan pishloq, qatiq yoki brokkoli miqdorini hisoblab, yetishmaganini to‘ldiring.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'Kichik yordamchi 🧹', 'Siz kiyimlarni taxlayotganingizda yoki polni artayotganingizda ishingizni qo‘lingizdan olishga urinadimi? U o‘zini katta his qilmoqda. Unga kichik bir latta berib, yordam berishiga ruxsat eting.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'Yostiqlardan qal’a 🏰', 'Bugun kechqurun xonani o‘yin maydonchasiga aylantiring. Divan yostiqlaridan kichik qal’a yasab, ichiga kiring. Biroz tartibsizlik bo‘ladi, ammo bu kulgilar bunga albatta arziydi.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'Diqqat sinovi 🧩', 'Bitta o‘yinchoq bilan o‘ynash vaqti endi 10-15 daqiqaga yetdimi? Diqqatni jamlash davomiyligi ortmoqda.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'Dada bilan uyqu tartibi 👨‍🍼', 'Bugun kechqurun bolani uyquga tayyorlash, tishlarini yuvdirish va pijamasini kiydirishni dadasiga topshirib, siz tinchgina choyingizni iching.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'Taomnoma tashvishi 🍲', 'Bugun nima pishirish haqida hech qanday fikringiz yo‘qmi? Internetda adashib qolmang, Ilovaning Bloglar bo‘limidagi bolalar ovqatlanishiga oid maqolalardan yangi va oson retseptlarni toping.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'Sabab-oqibatni o‘rganish 🤔', 'Buni tashlasam nima bo‘ladi?, Bu tugma nima uchun? U tinimsiz amaliy tajribalar o‘tkazmoqda. Uy xavfsizligini yana bir bor ko‘zdan kechiring.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'Birdamlik klubi 💬', 'Juda charchadingizmi va sizni hech kim tushunmayotgandek tuyulyaptimi? Darhol Anacan hamjamiyatiga yozing. U yerda xuddi siz kabi uyqusizlikdan qiynalayotgan minglab onalar sizni qo‘llab-quvvatlaydi.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'Mantiqsiz qaysarliklar 🛑', 'Bugun ertalab suvni ko‘k emas, qizil stakanda berganingiz uchun qiyomat qoyim bo‘ldimi? Bu injiqlik emas — u shunchaki dunyoni boshqara olishini sinab ko‘rmoqda. Sabrli bo‘ling.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'Vitaminlar xazinasi 🥗', 'Uni to‘ydirish uchun qo‘lingizdan kelganini qilyapsiz. O‘zingiz-chi? Sog‘lom retseptlar orasidan 10 daqiqada tayyorlanadigan, temir va kalsiyga boy tushlikni tanlab, quvvatingizni tiklang.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'Ko‘zgu qarshisida 👀', 'Ko‘zgu oldida turib, turli yuz ifodalarini ko‘rsatib, o‘z-o‘zidan kulyaptimi? Demak, uning o‘zini anglashi juda yaxshi rivojlanmoqda. Uni sezdirmay kuzating va bu kulgili lahzalardan zavqlaning.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'Uyquga qarshilik 🥱', 'Kunduzgi uyquga yotishni istamay, qarshilik ko‘rsatyaptimi? Ba’zi bolalar bu yoshda kunduzgi uyquni tashlaydi. Bahslashish o‘rniga «Tinchlik soati»ni e’lon qilib, yotoqda kitob varaqlang.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'Xona akustikasi 🤫', 'Uyquga ketishi bilan eng kichik taqillashdan ham cho‘chib uyg‘onadimi? Shovqin o‘lchagich yordamida xona akustikasini tekshiring va derazadan kiradigan tovushlarni niqoblash uchun oq shovqinni yoqing.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'Qaysarlik xurujlari 🛑', 'Do‘konda yoki bog‘da boshlanadigan injiqlik xurujlari sizni uyaltiradimi? Unutmang, atrofdagilar nima deb o‘ylashi emas, farzandingizning o‘sha paytdagi hissiyotlari muhim. U bilan ko‘z orqali aloqa o‘rnating va tinchlantiring.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'Sakrashga urinishlar 🤸‍♂️', 'U divandan polga yoki turgan joyida havoga sakrashga urinyaptimi? Yirik motorika ko‘nikmalari takomillashmoqda! Uni ruhlantiring.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'Rejimni to‘liq tahlil qilamiz ⏱️', 'Kechqurun uxlab qolishi 40 daqiqa davom etdimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyquni yanada qisqartirish va kechki uyqu vaqtini oldinga surish payti kelgandir.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'Tabiatni o‘rganish ⛅', 'To‘rt devor ichida siqilib ketdingiz. Ob-havo va kiyim vositasini oching, bolani ob-havoga mos kiyintirib, darhol bog‘ga olib chiqing. Barglar va toshlarni o‘rgansin.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'Sokinlikdan zavqlaning 🤫', 'U nihoyat uxlab qoldi. Endi uydagi eng kichik tovush ham asabingizga tegadi. Quloqchinni taqing va hech narsa tinglamasdan, shunchaki sukunatning qadriga yeting.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'Ranglarni o‘rganish 🎨', 'Qizil to‘pni so‘raganingizda aynan qizilini ko‘rsatyaptimi? U endi ranglarni farqlay boshladi. Rivojlanish kuzatuvchisiga idrok etishdagi ushbu yangi bosqichni yozib qo‘ying.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'Ertalabki injiqlik ☁️', 'Ko‘zini ochishi bilan hamma narsaga yig‘laydi va hech narsadan ko‘ngli to‘lmayaptimi? Balki u ayni o‘sish sakrashi davridadir. Uni ko‘proq bag‘ringizga bosib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8', 'Kir bo‘lishiga ruxsat bering 🏖️', 'Bog‘da loy yoki qum bilan o‘ynashni xohlayaptimi? Kir bo‘lishiga ruxsat bering! Sensor rivojlanishni qo‘llab-quvvatlaydigan bu mashg‘ulot uchun eng yaxshi Onalar uchun qulay joylarni ilovadan toping.'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'Jamoaviy ruh 🥂', 'Og‘ir kunni ortda qoldirdingiz. Bola uxlagach, juftingiz bilan bir piyola choy quyib, «Biz haqiqatan ham buning uddasidan chiqyapmiz», deya bir-biringizni qadrlang.'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'O‘zingizni qanday his qilyapsiz? 🩸', 'Quvvatingiz birdan pasaydimi yoki kayfiyatingiz tez-tez o‘zgarayaptimi? Ilovadagi Hayz kuzatuvchisiga nazar soling. Siklingizni kuzatib, tanangiz ehtiyojlarini yaxshiroq tushunishga harakat qiling.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'Xayoliy ertaklar 📖', 'Kitob o‘qishdan zerikdingizmi? Chiroqlarni o‘chiring, Oq shovqinlar bo‘limidan yomg‘ir tovushini yoqing va qorong‘ida birga xayoliy ertaklar to‘qib, uyquga keting.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'Mevali kashfiyotlar 🍏', 'Oqsilli mahsulotlar yoki sabzavotlarni rad etyaptimi? Ovqatlanishni nazorat qilish vositasi yordamida bugungi me’yorni hisoblang va Chaqaloq retseptlaridan mevali yogurt kabi mazali kombinatsiyalar tayyorlang.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'Barmoqda sanash 🔢', 'Zinadan ko‘tarilayotganda yoki mashinalarni qatorga terayotganda bir, ikki, uch deb sanashga harakat qilyaptimi? Matematik tafakkurning poydevori qo‘yilmoqda. U bilan birga hamma narsani ovoz chiqarib sanang.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'Chuqur nafas 🧘‍♀️', 'Kun bo‘yi savollarga javob beraverib, tomog‘ingiz quridi. Xonada sukunat paydo bo‘lishi bilan hech qanday ekranga qaramay, shunchaki chuqur nafas olib-chiqarib dam oling.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy ishlariga shoshilmang! Sog‘lom retseptlardan melissa yoki moychechak choyini damlang, divanga yonboshlang va shunchaki sukunatdan zavqlaning.'),
  ('37bdad79-de07-4752-a75a-2761546b1523', 'Bo‘lishish qiyin 🧸', 'Ukasiga, akasiga yoki bog‘dagi bolaga qo‘pol munosabatda bo‘lyaptimi? Bo‘lishish uning uchun hali mavhum tushuncha. Jazolamang, uning his-tuyg‘ularini tushunishingizni ko‘rsating.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'Xayoliy choyxo‘rlik 🍵', 'Sizni ham xayoliy o‘yinlariga qo‘shib, bo‘sh piyoladan choy ichishingizni so‘rayaptimi? Uning tasavvur olamining bir qismiga aylaning. Bunday o‘yinlar uning ijtimoiy intellektini rivojlantiradi.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'Dadaning hikoyasi 📖', 'Bu oqshom ovoz paylaringizga dam bering. Bolaning sevimli kitoblarini turli ovozlarda kulgili tarzda o‘qish vazifasini dadasiga topshiring.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', '“Men to‘ydim” bahonasi 🥣', 'Ikki qoshiq yeb, to‘ydim deydimi va qochib ketadimi? Uni majburlamang. Taomni kichik porsiyalarda, ammo tez-tez berib ko‘ring.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'Tana a’zolarini tanish 👀', '“Yelkang qayerda?” deb so‘raganingizda, barmog‘i bilan tegib ko‘rsatadimi? Aqliy idroki ayni cho‘qqisida! O‘yinni murakkabroq tana a’zolari bilan davom ettiring.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'Pijama jangi 👕', 'Kechqurun kiyinish katta jangga aylanadimi? Tanlovni uning o‘ziga qoldiring: “Oq pijamani xohlaysanmi yoki ko‘kini?” Bu usul ko‘pincha ish beradi.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'Boshqaning o‘yinchog‘i 🧸', 'Uyga mehmon bo‘lib kelgan bolaga o‘z o‘yinchog‘ini bermaydimi? Bu xudbinlik emas, balki shaxsiy chegaralarini himoya qilishdir. Bo‘lishishni majburlash orqali emas, o‘rnak ko‘rsatish orqali o‘rgating.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'So‘zlarni talaffuz qilish 🗣️', 'Ba’zi so‘zlarni chala yoki juda kulgili talaffuz qiladimi? Kulmang, shunchaki miyasi to‘g‘ri shaklini eslab qolishi uchun so‘zni to‘g‘ri urg‘u bilan takrorlab ayting.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'Tungi vahimadan shubha 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘laydi va tinchimaydimi? Ovozini darhol Yig‘i tahlili orqali tekshiring. Ba’zan bu shunchaki qorin dam bo‘lishi emas, balki tungi vahima bo‘lishi mumkin.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'Yiqilganda yig‘lamaslik 🧗‍♂️', 'Yengil yiqilganda darhol yig‘lamay, sizning munosabatingizga qarab, keyin nima qilishni hal qiladimi? Vahimaga tushmang, jilmayib: «Hech narsa bo‘lmadi, sen kuchlisan», deng.'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'Qorong‘ilikdan qo‘rqadimi?  🌙', 'Karavoti yoniga iliq rangli kichik tungi chiroq qo‘ying. Melatonin ajralishi uchun xonaning qolgan qismini esa butunlay qorong‘i saqlang.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'Sabzavotlarga qarshilik 🥦', 'Sho‘rvadagi barcha sabzavotlarni chetga olib qo‘yadimi? Ovqatlanish rejasida unga boshqa muqobillar izlang. Sabzavotlarni kotlet ichiga yashirish — onalarning eng qadimiy hiylalaridan biri.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'Mukammal ona bo‘lmaydi 💬', 'Hamma ishni bir vaqtning o‘zida bajara olmayotganingiz uchun o‘zingizni yomon his qilyapsizmi? Darhol Anacan Hamjamiyatiga qo‘shiling. U yerdagi onalarning samimiy e’tiroflari sizga kuch beradi.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'Qoralashga ishtiyoq 🖍️', 'Qalamni ushlash usuli o‘zgarib, qog‘ozga maqsadli chiziqlar chiza boshlaydi. Rivojlanish kuzatuvchisida mayda motorikaning bu ajoyib yutug‘ini albatta belgilang.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf'::uuid, 'Qahva quvvati ☕', 'Kun bo‘yi yugur-yugur sizni holdan toydirdi. Uni 15 daqiqaga xavfsiz mashg‘ulot (masalan, rasm bo‘yash) bilan band qiling va o‘zingiz ham albatta bir finjon qahva ichib, quvvat oling.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'Aniq otishlar ⚾', 'U siz otgan katta to‘pni qo‘llari bilan tutishga, hatto uni qaytarib otishga ham urinayaptimi? Ko‘z va qo‘l muvofiqligi jadal rivojlanmoqda. Yo‘lakda birga to‘p o‘ynang.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'Musiqali o‘tish 🛀', 'Kechki tartib qiyinlashdimi? Iliq vanna qabul qilayotganda fonda tinchlantiruvchi klassik musiqa qo‘ying. Suv va musiqa uyg‘unligi hatto eng qaysar bolani ham tinchlantiradi.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'Kunduzgi uyquni rad etish 🥱', 'Yana uxlamadimi? Kurashib, uni ham, o‘zingizni ham charchatmang. Xonada tinchgina kitob varaqlash ham miya uchun dam olishning bir turidir.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'His-tuyg‘ularni ifodalash 📝', 'Bugun juda qattiq charchadingizmi yoki u juda yoqimli bir gap aytdimi? Har ikki holatda ham Kayfiyat kundaligini oching va bu onni kelajak uchun qayd etib qo‘ying.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'Tish yuvish jangi 🦷', 'Tish cho‘tkasini og‘ziga yaqinlashtirishga yo‘l qo‘ymayaptimi? Buni majburiyatga emas, o‘yinga aylantiring. Unga tishlaringizni yuvishga ruxsat bering, keyin navbat sizniki bo‘lsin.'),
  ('7022b1d9-81c4-428f-be96-d38885bd2971', 'Erkin o‘yin 🧸', 'Uni har daqiqa ko‘nglini olishga majbur emassiz. Zerikish bolalarda ijodkorlikning boshlanishidir. Xonada o‘zi mustaqil ravishda nimanidir kashf etishiga imkon bering.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'Shunchaki quchoqlang 🫂', 'Hech qanday vosita, kitob yoki ertak kerak emas. Bu oqshom uni shunchaki bag‘ringizga bosing, hidini to‘yib ichingizga torting va qorong‘ida unga sevgingizni pichirlab ayting.'),
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4', 'Qat’iy «yo‘q»lar 🛑', 'Kimdir uni o‘pmoqchi bo‘lganida uzoqlashib, «yo‘q» deydimi? Uning shaxsiy tana chegaralarini hurmat qiling va boshqalardan ham bunga rioya qilishni talab qiling. O‘ziga ishonch aynan shundan boshlanadi.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'Bloglarni ko‘rib chiqing 📱', '2 yoshdagi injiqliklarni yengishda qiynalyapsizmi? Anacan ilovasidagi psixologik bloglarni o‘qing. O‘sha injiqlik paytida bolaning miyasida nimalar sodir bo‘layotganini tushunish vaziyatni yengillashtiradi.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'Aqlli ertak vaqti 🪄', 'Bu oqshom aqlli ertaklarda unga maxsus sarguzasht yarating: qo‘rqmas jasur quyoncha haqida hikoya. Qo‘rquvlarini ertaklar yordamida yengishiga ko‘maklashing.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'Uydagi tartibsizlik 🌪️', 'Har kuni yig‘ishtiradigan xonangiz 5 daqiqada yana to‘zib ketadimi? Qo‘yavering! Uy muzey emas, balki hayot qaynab turgan maskan. Tartibsizlikka emas, bolangizning quvonchiga e’tibor qarating.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'Qo‘rquvlarning uyg‘onishi 👻', 'Oldin hech qo‘rqmagan shovqinli changyutgichdan endi qo‘rqib, ortingizga yashirinyaptimi? Tasavvur rivojlangani sari asossiz qo‘rquvlar paydo bo‘ladi. Uni silab-siypab, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'Ko‘zlariga uyqu kelgan 🥱', 'Uyqusi kelsa ham, hecham yotishni istamaydi. Bugun kechki odatlaringizni biroz o‘zgartiring. Kitob o‘qish o‘rniga, yotoqda yonma-yon yotib, unga bugun sodir bo‘lgan quvonchli voqealarni eslating.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'Energiya to‘lqini ⛅', 'Bolangiz uyda devorlarga tirmashyaptimi? U energiyasini sarflashi kerak. Ob-havoni hisobga olib, mos kiyintiring va parkka olib chiqib, charchaguncha yugurishiga ruxsat bering.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'Ovozingizga taqlid qiladi 🗣️', 'U o‘yinchoqlariga xuddi sizning ohangingiz va iboralaringiz bilan nasihat qilyaptimi? U sizning eng yaxshi ko‘zgungiz. O‘zingizni chetdan kuzatish kulgili bo‘ladi.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'Bo‘y va vazndagi keskin o‘sish! 📏', 'Kiyintirayotganda ko‘ylaklari torayib qolganini yoki oyoq kiyimi siqayotganini payqadingizmi? Rivojlanish kuzatuvchisiga hozirgi bo‘yi va o‘lchamlarini kiriting hamda rivojlanish egri chizig‘i qanday ko‘tarilayotganini faxr bilan kuzating.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'Ona charchaganida 🛑', 'Siz robot emassiz. Agar bugun ovqat pishirishga kuchingiz bo‘lmasa, tayyor ovqat buyurtma qiling. Mukammal ona bo‘lish hamma ishni yolg‘iz bajarish degani emas.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'G‘alaba qadahi 🥂', 'Qiyin va qaysarliklarga boy kunni eson-omon yakunladingiz. Juftingiz bilan yuzma-yuz o‘tirib, choy piyolalaringizni bir-biriga urishtiring. Siz bu ulkan mas’uliyatni uddalayapsiz.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'Suvni kam ichyapti deb o‘ylaysizmi?💧', 'Unga rang-barang, turli shakldagi stakanlar olib berib, suv ichishni qiziqarli odatga aylantiring.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'Shivirlab suhbatlashish 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni unga juda past ovozda, shivirlab aytib bering. Shivirlash miyani uyquga tayyorlashning eng yaxshi usullaridan biridir.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'Tanlash erkinligi 👗', 'Kiyimlarini o‘zi tanlamoqchi, lekin ranglar umuman bir-biriga mos emasmi? Hechqisi yo‘q. Irodasini sindirmaslik uchun unga atigi 2 ta variant taklif qiling: Bunisini tanlaysanmi yoki unisini?'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'Dadasining g‘alati ovozlari 🤡', 'Chaqaloqni kuldirishning eng tezkor yo‘li — dadasining g‘alati ovozlar chiqarishi va kulgili yuz ifodalarini ko‘rsatishidir. Bu oqshom uning quvnoq qahqahalarini tinglab, siz ham chetda jilmayib turing.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'Dardlashish vaqti 💬', 'Bugun u har narsaga yig‘ladi, siz esa holdan toydingiz. Darhol Anacan hamjamiyatiga kiring va Bugun juda qiyin bo‘ldi deb yozing. Yuzlab ayollar ayni damda xuddi shunday holatni boshdan kechirayotganini ko‘rasiz.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'Konstruktor ustasi 🧱', 'Katta LEGO qismlarini bir-biriga ulab, nimadir yasashga urinyaptimi? U geometriyani kashf etmoqda. Rivojlanish kuzatuvchisiga uning bu kichik muhandislik urinishlarini ham kiriting.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'So‘zlarni takrorlash 🗣️', 'Siz aytgan har bir yangi so‘zni darhol to‘tiqushdek takrorlayaptimi? Uning so‘z boyligi oshmoqda. Uning yonida aytadigan so‘zlaringiz va ifodalaydigan his-tuyg‘ularingizga alohida e’tibor bering.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'Tun ohangi 🛀', 'Kun bo‘yi yugurib, u ham, siz ham charchadingiz. Iliq vanna va fonda yangraydigan yengil, mayin kuy uning asab tizimini butunlay tinchlantiradi.'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'Injiqlik payti 🛒', 'Do‘konda u xohlagan o‘yinchoqni olib bermaganingiz uchun baqiryaptimi? Atrofdagi o‘zini mukammal ota-ona deb biladiganlarning qarashlariga e’tibor bermang. Xotirjamlik bilan uning ko‘zlariga qarab, vaziyatni tushuntiring.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'Uy ishlari kutib tursin 🛑', 'Pol artilmagan, kiyimlar taxlanmaganmi? Mayli, shunday tursin. Iflos uyni tartibga keltirish mumkin, ammo ruhiy jihatdan holdan toygan onaning tiklanishi ancha uzoq davom etadi. Divanga yotib, dam oling.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'Uyqusizlikni qabul qiling 😭', 'Yarim tunda uyg‘onib, uxlashni istamayaptimi? Unga jahlingiz chiqmasin. Ovozini Yig‘i tahliliga eshittirib, sababini (og‘riq, gaz, qo‘rquv) aniqlang va sabr bilan bag‘ringizga bosing.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'Yangi do‘st izlash 👫', 'Bog‘da tengdoshlari bilan yugurishga, ularga yaqinlashishga harakat qilyaptimi? Demak, ijtimoiylashuv rasman boshlandi! Uni uzoqdan nazorat qilib, bu lahzani faxr bilan kuzating.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'Qarsak chalish quvonchi 👏', 'Biror ishni uddalaganida (masalan, minora qurganida) o‘z-o‘ziga qarsak chalib, faxrlanadimi? U sizning e’tirofingizni kutmoqda! Siz ham uning bu kichik yutug‘ini katta quvonch bilan olqishlang.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'Sokinlik vaqti ☕', 'Agar kunduzi uxlamasa, kamida 1 soatlik Sokinlik vaqtini (quiet time) belgilang. U o‘z yotog‘ida kitob varaqlasin, siz esa choyingizni ichib, telefoningizni ko‘ring.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'Juftlik uchun tanaffus 🥂', 'Bola uxladi. Endi telefonlar va uy ishlarini bir chetga qo‘ying. Turmush o‘rtog‘ingiz bilan kamida 20 daqiqa bola haqidagi mavzulardan boshqa istalgan mavzuda suhbatlashing. Siz ota-ona bo‘lish bilan birga juftlik ham ekansiz.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'Ertakning yakuni 🪄', 'Klassik ertaklar zerikarli bo‘lishi mumkin. Interaktiv ertaklarda bu safar hikoyaning yakunini bolangizga tanlating. «Seningcha, ayiqchaga kim yordam berdi?» deb, uning tasavvurini ishga soling.'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'Chegaralarni sinash ⚠️', '«Buni qilma», deganingizga qaramay, ko‘zingizga tik qarab, o‘sha ishni qiladimi? U sizni jahlingizni chiqarishga urinmayapti, balki chegaralaringiz qanchalik qat’iyligini sinayapti. Qat’iy bo‘ling.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'Rasmlarga munosabat 📖', 'Kitobdagi hayvonlar yoki bolalarni ko‘rganida ularga tegib, tovush chiqaradimi? Uning ko‘rish orqali idrok etishi hayratlanarli. Rivojlanish kuzatuvchisida bu tafsilotni belgilang.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'Bloglardan o‘rganing 📱', 'Farzandingizning hamma narsaga «yo‘q» deyishi sizni charchatdimi? Bu ikki yosh inqirozining klassik belgisidir. Ilovadagi psixologik bloglarni o‘qib, uning miyasida nimalar sodir bo‘layotganini tushunib oling.'),
  ('19cce24b-ae51-482e-8dc7-6812a220483b', 'O‘zingizni ayblamang 📝', 'Bugun sabringiz chidamay, ovozingizni balandlatdingizmi? Farzandingiz uxlagach, Kayfiyat kundaligiga his-tuyg‘ularingizni yozing va o‘zingizni kechiring. Siz shunchaki charchagansiz, siz ham insonsiz.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'Zinadan mustaqil chiqish 🧗‍♂️', 'Qo‘lingizdan ushlab zinadan chiqishga, hatto o‘zi mustaqil ko‘tarilishga intilyaptimi? U o‘z tanasining imkoniyatlarini sinab ko‘rmoqda. Xavfsizligini ta’minlagan holda unga bu erkinlikni albatta bering.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'Ayriliqdan qo‘rqish 🥺', 'Hatto hojatxonaga kirganingizda ham eshik ortida sizni kutib yig‘laydi. Ayriliq xavotiri ba’zan kuchayadi. Har safar unga ovoz berib, shu yerda ekaningizni va qaytib kelishingizni ayting.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'Xonaning qorong‘iligi 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni, ayniqsa, planshet ekranlarini o‘chiring. Melatonin faqat qorong‘i muhitda ajralib chiqadi.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'Ovqat ustida injiqlik 🥣', 'Ikki qoshiq yeb, to‘ydim deyaptimi? Uni majburlamang. Ovqat bilan sog‘lom munosabatni shakllantirish majburlab yedirishdan muhimroqdir. Ovqatlanish sonini ko‘paytirib, miqdorini kamaytiring.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'Ertalabki raqs 🎶', 'Ko‘zini ochishi bilan energiyaga to‘lib ketadimi? Ertalabki tartibsizlikni tinchlantirish uchun quvnoq bolalar qo‘shig‘ini qo‘ying, xonada bir necha daqiqa raqsga tushib, kunni tabassum bilan boshlang.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'Kerakli narsalar ro‘yxati 🛒', 'Taglik, shampun yoki meva pyuresi tugadimi? Boshingizni qotirmang, hammasini darhol Xaridlar ro‘yxatiga yozing va turmush o‘rtog‘ingiz bilan bir bosishda sinxronlashtiring.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'Chuqur sukunat 🤫', 'Uxlab qolganidan keyingi dastlabki yarim soat — eng nozik vaqt. Shovqin o‘lchagich yordamida xonadagi detsibel darajasini tekshiring, televizor ovozini pasaytiring va uyni qamrab olgan bu chuqur sukunatning qadriga yeting.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'Temir siri: C vitamini 🍋', 'Rangi oqarib ketganmi yoki ishtahasi yo‘qmi? Ovqatlanishni kuzatish vositasida bugungi temir iste’molini tekshiring va go‘sht bilan birga limonli salat berib, temirning so‘rilishini yaxshilang.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'Tunda uyg‘onishlar 🌌', 'Yarim tunda yig‘lab uyg‘onib, tinchlanmayaptimi? Tungi vahima bilan dahshatli tush o‘rtasidagi farqni tushunish va to‘g‘ri psixologik yondashuvni qo‘llash uchun Bloglar bo‘limini ko‘rib chiqing.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'Doira chizish san’ati! 🎨', 'Qalam bilan qog‘ozga (yoki devorga!) yopiq doiralar chizishga urinayaptimi? Bu — harakat ko‘nikmalari rivojidagi ajoyib sakrashdir.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'Ko‘katli detoks 🌿', 'O‘zingizni shishib ketgandek his qilyapsizmi? Hayz kuzatuvchisida siklingizni tekshiring va Ayollar uchun foydali retseptlardagi yashil smuzi yordamida tanangizni tozalab, energiyangizni tiklang.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'Suyuqlik ichish va qabziyat 💩', 'Ko‘p yugurib, kam suv ichyaptimi? Tagligini almashtirganda (yoki tuvakda) najasini kuzating. Qabziyat xavfi bo‘lsa, taomnomasiga suli qo‘shing.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'Mahluq ovi! 👾', 'Karavot tagidan mahluq qidiryaptimi? Tasavvur bilan bog‘liq qo‘rquvlar kuchayadi. Oq shovqinlardan ventilyator ovozini yoqib, xonada xavfsiz va bir maromdagi muhit yarating va uni tinchlantiring.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'Karavotdan qochish rejasi 🛌', 'Beshigidan tirmashib chiqishga urinyaptimi? Katta bolalar karavotiga o‘tish vaqti yaqinlashmoqda. Xona xavfsizligini pol sathidan turib yana bir bor tekshiring.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'Ona uchun tanaffus ☕', 'Bola mustaqil o‘ynayotganida darhol uy ishlariga shoshilmang. Xonadagi tartibsizlik hech qayerga qochmaydi, ammo sizning quvvatingiz tugashi mumkin. O‘tiring va issiq qahvangizni iching.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', '“Nega?” davrining cho‘qqisi 🤔', 'U nega u yerda?, Nega uxlayman?... Uning miyasi shimgichga o‘xshaydi! Bu tuganmas savollariga qisqa, ammo mantiqli javoblar bering. U dunyoni sizning so‘zlaringiz orqali kashf etmoqda.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'Parkdagi muloqot 🌳', 'Boshqa bolalar bilan o‘ynashdan ko‘ra, ularning yonida o‘zicha o‘ynaydimi? Parallel o‘yin bu yosh uchun mutlaqo tabiiy. Ob-havo va kiyimiga qarab, uni tengdoshlari bilan birga bo‘lishi uchun tez-tez sayrga olib chiqing.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'Xayoliy do‘stlar 🧸', 'O‘yinchoq ayiqchasiga ertak aytib beradimi yoki bo‘sh piyoladan choy ichadimi? Ramziy o‘yinlar — rivojlanishning haqiqiy durdonasi. Rivojlanish kuzatuvchisida bu kognitiv sakrashni faxr bilan qayd eting.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'Sukunatga ehtiyoj 🤫', 'U uxlab qolganidan keyingi dastlabki yarim soat eng nozik davrdir. Shovqin o‘lchagich yordamida muhitdagi detsibel darajasini tekshiring va qo‘shni xonadagi televizor ovozini moslang.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'Hamma narsani o‘ziniki qilmoqchimi? 🛑', 'Bo‘lishish tushunchasi hali shakllanmagan. Uni majburlamang, buning o‘rniga «Navbat bilan o‘ynaymiz» qoidasini asta-sekin joriy eting.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'Kichkina muhandis 🏗️', 'Minoralar qurib, keyin ularni buzishni yaxshi ko‘radimi? Aql-zakovati va harakat ko‘nikmalarini yanada rivojlantiradigan magnitli yoki yog‘och bloklarni hoziroq Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'Chuqur nafas oling 🌬️', 'Bugun uning ortidan yugurib, holdan toydingizmi? Kayfiyat kundaligini ochib, charchog‘ingizni yozing. Mukammal ona bo‘lishga urinmang, sizning his-tuyg‘ularingiz ham muhim!'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'O‘zingiz bilan faxrlaning 🌟', 'U har kuni o‘rganayotgan yangi ko‘nikma, har bir ishonchli qadam — siz va juftingiz mehnatining samarasidir.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'Mustaqillik deklaratsiyasi 📜', 'Hamma narsani «O‘zim qilaman!» deb, ishlarni sekinlashtiryaptimi? Chegara bilmas bu o‘jarlikni rivojlanishga yo‘naltirish usullarini hoziroq Anacan AI-dan so‘rang.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'Kitoblardagi tafsilotlar 📖', 'Kitobni varaqlab, rasmdagi eng mayda detalni barmog‘i bilan ko‘rsatyaptimi? Uning ko‘rish xotirasi a’lo darajada ishlayapti. U bilan rasmdagilar haqida suhbatlashing.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'Chizgilar ustasi 🖍️', 'Qo‘liga qalam tushishi bilan devor yoki qog‘ozga chizishni boshlaydi. Ranglar yordamida uning mayda motorikasi rivojlanadi.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'Tun sukunati 🛀', 'Iliq vanna, yengil massaj va qorong‘i xona. Uyqu tartibini aslo buzmang, chunki bu uning miyasiga uxlash uchun eng yaxshi vaqt kelganini bildiradi.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'Onalar dardlashuvi 💬', '«Nega mening bolam bunchalik o‘jar?» degan o‘y sizni charchatyaptimi? Anacan hamjamiyatiga qo‘shiling va har bir bola turli inqirozli davrlardan o‘tishini ko‘ring.'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'Og‘ir kun bo‘ldimi?', 'Bugungi stressingizni kayfiyat kundaligiga yozib, ko‘nglingizni bo‘shating. Barcha onalar bunday qiyin holatlarni boshdan kechiradi, siz yolg‘iz emassiz.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'Ona uchun ziyofat 🥑', 'Uni to‘ydirish uchun hamma narsani qilyapsiz. O‘zingiz-chi? Sog‘lom retseptlar orasidan sizga kuch beradigan, temirga boy tushlikni tanlang va xotirjam o‘tirib, ovqatlaning.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'Ikki so‘zli gaplar 🗣️', 'Ona kel, To‘pni ot – uning lug‘at boyligi kundan kunga oshib bormoqda. U chala aytgan so‘zlarni to‘g‘ri talaffuz bilan takrorlab, nutqi rivojlanishini qo‘llab-quvvatlang.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'Do‘kondagi injiqliklar 🛒', 'Do‘konda xohlagan narsasini olib bermaganingiz uchun o‘zini yerga tashladimi? Atrofdagilarning qarashlariga e’tibor bermang. Uning ko‘zlari darajasigacha egilib, his-tuyg‘ularini tushunishingizni ayting.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'Teskari kiyilgan kiyimlar 👗', 'Oyoq kiyimini almashtrib, ko‘ylagini esa teskarisiga kiyib oldi va aslo yechishni istamayaptimi? Mayli, shunday qolaversin! Bu uning o‘ziga xosligini namoyon etishining eng beozor usulidir.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'Musiqali huzur 🎶', 'Kechga yaqin boshlanadigan injiqliklarni tinchlantirishning eng oson yo‘li — uning sevimli kuyini qo‘yib, bag‘ringizga bosgancha sekin raqsga tushishdir.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'Oqshom qahramoni: Dada 🦸‍♂️', 'Bugun kechqurun uyquga tayyorlash tartibini Hamkor funksiyasi orqali turmush o‘rtog‘ingizga topshiring. Ertakni u o‘qisin, siz esa o‘zingizga iliq vanna tayyorlab, kun davomida to‘plangan stressdan xalos bo‘ling.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'Ovqat tanlash odati 🥦', 'Kecha ishtaha bilan yegan taomini bugun rad etyaptimi? Ovqatlanishni nazorat qilish vositasi yordamida menyuni tahlil qiling va Chaqaloq retseptlaridan turli xil, qiziqarli taqdimot usullarini toping.'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'Og‘riqsiz kunlar 🩸', 'Hayzingiz yaqinlashib, spazmlar boshlandimi? Dori ichishga shoshilmay, avval Ayollar uchun foydali retseptlardan magniyga boy xurmo va yong‘oqli gazak tayyorlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'Kiyimlar kichrayib qolyapti! 📏', 'Ko‘ylaklarining yenglari yana kalta bo‘lib qoldimi? 29-oyga yaqin rivojlanishdagi keskin o‘sishni aniq ko‘rish uchun Vazn kuzatuvchisiga joriy o‘lchamlarni kiriting va yuqorilab borayotgan grafikni kuzating.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'Kitob qahramoni 📖', 'Bir xil ertakni 100-marta o‘qib berishingizni so‘rayaptimi? Zerikarli tuyuladigan bu takrorlashning aqliy rivojlanishdagi beqiyos ahamiyati haqida Bloglardan o‘qing va sabringizni mustahkamlang.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'Ilk mantiqiy taxminlar 🤔', '“Buni qilsam, shunday bo‘ladi” kabi gaplar tuzyaptimi? Bu ajoyib tafakkur sakrashini o‘tkazib yubormasdan, ovozli video sifatida Chaqaloq albomiga qo‘shing va faxrlaning.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'Uxlashga qarshilik 🥱', 'Kunduzgi uyquga yotishni istamay, yig‘layaptimi? U bilan kurashmang. Buning o‘rniga, xonada jimgina kitob varaqlashi uchun 30 daqiqalik Tinchlik vaqtini e’lon qiling.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'Navbatchilikni topshirish 👨‍👧', 'Kun bo‘yi Nega? degan savollarga javob beraverib, miyangiz charchadi. Bugun kechqurun pijama kiydirish va uxlatish vazifasini juftingizga topshirib, dam oling.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'G‘ayrioddiy moda 👗', 'Qish o‘rtasida yozgi shortikni, shimni esa boshiga kiyishni xohlayaptimi? Didiga aralashmang. Bu kulgili tajribalar orqali u o‘ziga xosligini namoyon qilmoqda.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'Likopchadagi kashfiyotlar 🥦', 'Kecha yaxshi ko‘rgan taomini bugun yerga uloqtiryaptimi? Ovqatlanish rejasi vositasiga kiring va mutaxassislar 2.5 yosh uchun tayyorlagan xilma-xil, rang-barang menyu g‘oyalaridan foydalaning.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'Kutilmagan qo‘rquvlar 👻', 'Xona qorong‘iligidan yoki xayoliy soyalardan qo‘rqa boshladimi? Tasavvuri rivojlangani sari asossiz qo‘rquvlar paydo bo‘ladi. Unga dalda berib, yonida ekaningizni his qildiring.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'Tugamaydigan quvvat 🔋', 'Siz hali ko‘zingizni ochishga ulgurmagansiz, u esa gilam ustida allaqachon yugurish marafonini boshlab yuborgan. O‘zingizga katta bir finjon qahva quying, bugun juda serharakat kun bo‘ladi.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'Jamoa yig‘ilishi 🥂', 'Farzandingiz uxlagach, kun davomida to‘plangan stressdan xalos bo‘lish uchun juftingiz bilan bir piyola choy iching va «Biz ajoyib jamoamiz», deb bir-biringizni qadrlang.'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'Onalar uchun qulay joy kashfiyoti ☕', 'Uyda bir xil devorlarga qarayverish sizni holdan toydirdi. Onalar uchun qulay joylar orasidan bolalar o‘yin burchagi bor kafeni toping. Farzandingiz o‘ynasin, siz esa qahvangizdan zavqlaning.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'Hayvonlarning ovozlari 🐶', 'Mushukni ko‘rganda «miyov», itni ko‘rganda esa «vov-vov» deyishga urinayaptimi? So‘z boyligi hayvonlarning ovozlari yordamida juda yaxshi rivojlanadi. U bilan shu o‘yinni o‘ynang.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'Tezkor pediatr 🤖', '2.5 yoshga yaqinlashganda porsiya miqdori qancha bo‘lishi kerak? Ikkilanayotgan bo‘lsangiz, darhol Anacan AI’dan aniq va ilmiy asoslangan jadval so‘rang.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'Ertak qahramoni 🪄', 'Bugun kechqurun Aqlli ertaklarda bosh qahramoni o‘z farzandingiz bo‘lgan maxsus hikoya yarating: tishlarini yuvishni yaxshi ko‘radigan jasur bolakay.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', '«Sizni sevaman» quchog‘i 🫂', 'U kutilmaganda kelib bo‘yningizdan quchoqlaydimi yoki yuzingizni silaydimi? Endi u sevgisini jismonan namoyon etmoqda. Bu lahza baxsh etadigan beqiyos huzurdan zavqlaning.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'Ijodkor izidan 🖍️', 'Qog‘oz tugab, endi navbat devor va eshiklarga keldimi? Uning mayda motorikasi ranglar yordamida rivojlanmoqda. Xonaga katta karton yozib qo‘ying va unga faqat shu yerda rasm chizish mumkinligini ayting.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'Mantiqsiz qaysarliklar 🛑', 'Suvni ko‘k emas, qizil stakanda berganingiz uchun janjal ko‘tardimi? Bu injiqlik emas — u shunchaki chegaralaringizni va dunyoni boshqara olishini sinab ko‘rmoqda. Sabrli bo‘ling.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'Suvning terapevtik kuchi 🛀', 'Kun bo‘yi yugurib, u ham, siz ham charchadingiz. Iliq vanna shunchaki tozalanish emas, balki uning zo‘riqqan asab tizimini tinchlantiradigan eng yaxshi tabiiy usuldir.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'Tartibsizlik bilan murosa qilish 🌪️', 'Har kuni bir xil o‘yinchoqlarni yig‘ishtirishdan charchadingizmi? Bugun yig‘ishtirmang! Uydagi tartibsizlik dunyoning oxiri emas, ruhiy xotirjamligingiz hamma narsadan muhimroq.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'Vijdon azobini tinchlantiring 💬', 'Bugun u ekran qarshisida ko‘p vaqt o‘tkazgani uchun o‘zingizni ayblayapsizmi? Anacan hamjamiyatiga kiring, boshqa onalar ham ba’zan shunday his qilishlarini o‘qib, yengil torting. Siz yolg‘iz emassiz.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'Ko‘zgudagi shaxsiyat 👀', 'Ko‘zgu qarshisida turli mimikalar qilib, o‘zi bilan gaplashib kuladimi? Uning o‘zini shaxs sifatida anglashi ajoyib darajada. Uni sezdirmay kuzating va bu kulgili lahzalardan faxr bilan zavqlaning.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'Bog‘dagi xudbinlik 🧸', 'Qumda o‘ynayotganda chelakchasini hech kimga bermayaptimi? Bu xudbinlik emas, balki o‘z chegaralarini himoya qilishdir. Uni majburlamang, buning o‘rniga «Navbat bilan o‘ynaymiz» qoidasini muloyimlik bilan o‘rgating.'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'Xayoliy o‘yinlar 🧸', 'O‘yinchoq ayig‘i yoki qo‘g‘irchog‘iga suv ichirishga urinib, ular bilan suhbatlashyaptimi? Ramziy o‘yinlar — rivojlanishning chinakam durdonasi. Bu yoqimtoy rejissyorni chetdan qiziqish bilan kuzating.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'Yangi so‘zlar 🧠', 'Bugun kattalardek boshqacha va murakkab jumla tuzdimi? Darhol Rivojlanish kuzatuvchisini oching va bu kognitiv sakrashni kelajakda o‘qish uchun xotira sifatida qayd eting.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'Juftlik uchun tanaffus 🥂', 'Bola uxlab qoldi. Endi uy ishlarini bir chetga qo‘ying. Juftingiz bilan kamida 20 daqiqa davomida boladan boshqa istalgan mavzuda suhbatlashing. Siz nafaqat ota-ona, balki juftlik ham ekansiz.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'Maqsadli emaklash 🐢', 'Endi yurish bilan birga, ba’zan ermak uchun tez emaklab sizdan qochyaptimi? Xonadagi xavfli to‘siqlarni olib tashlang va bu quvlashmachoq o‘yiniga siz ham qo‘shiling.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'Ona uchun oflayn vaqt ☕', 'Bola o‘z dunyosiga sho‘ng‘ib o‘ynayotganida darhol idish yuvishga shoshilmang. O‘zingizga issiq choy quying, telefonni bir chetga qo‘ying va 15 daqiqa hech narsani o‘ylamay, oflayn bo‘ling.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'Shivirlab suhbatlashish 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Uning yoniga yotib, kun davomida yuz bergan voqealarni juda past ovozda, shivirlab aytib bering. Shivirlash miyani uyquga tayyorlashning eng tinchlantiruvchi usulidir.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'Og‘riqsiz kunlar 🩸', 'Hayzingiz yaqinlashib, og‘riqli spazmlar boshlandimi? Dori ichishga shoshilmay, avval Sog‘lom retseptlar bo‘limidan magniyga boy xurmo va yong‘oqli yegulik tayyorlab, o‘zingizga g‘amxo‘rlik qiling.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'Barmoqlarda sanash 🔢', 'Zinadan chiqayotganda yoki o‘yinchoqlarini terayotganda bir, ikki, uch deb aytishga harakat qilyaptimi? Demak, matematik tafakkuri uyg‘onmoqda. U bilan birga xonadagi buyumlarni ovoz chiqarib sanang.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'Quvvatingizni tiklang 🍲', 'Kundalik yugur-yugurlar sizni holdan toydirdi. Yo‘l-yo‘lakay tamaddi qilish o‘rniga, o‘zingiz uchun to‘yimli va kalsiyga boy alohida taom tayyorlab, mazza qilib yeng.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'Dadaning kulgili chehrasi 🤡', 'Chaqaloqni kuldirishning eng tezkor usuli — dadasining g‘alati tovushlar chiqarib, kulgili yuz ifodalarini ko‘rsatishidir. Bu oqshom uning quvnoq qahqahalarini tinglab, siz ham chetdan jilmayib turing.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'Onaning tonggi quvvati ⚡', 'Ertalab charchoq bilan uyg‘ondingizmi? Shirinlikka yopishmang. Sog‘lom retseptlar bo‘limidan 5 daqiqada tayyorlanadigan oqsil va mevalarga boy suli bo‘tqasi retseptini topib, kunni tetik boshlang.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'Dadaning ko‘magi kerak 🫂', 'Hayz kuzatuvchisida PMS kunlaridasiz va o‘zingizni ta’sirchan his qilyapsizmi? Hamkor funksiyasi orqali unga bugun biroz ko‘proq ko‘makka muhtoj ekaningizni bildiring.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'Yostiqlardan qal’a 🏰', 'Bu oqshom xonani o‘yin maydonchasiga aylantiring. Divan yostiqlaridan kichik qal’a yasab, ichiga kiring. Biroz tartibsizlik bo‘ladi, ammo quvnoq kulgilar bunga arziydi.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'Advokatdek muzokara 🗣️', '«Yana biroz o‘ynay, keyin kiyinaman», deyaptimi? U siz bilan allaqachon professional tarzda kelishishga urinmoqda. Nutqining rivojlanishi a’lo, ammo chegaralaringizni mehr bilan saqlashni unutmang.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'Tabiatni kashf etish 🌳', 'To‘rt devor ichida siqilib qoldingiz. Havo salqin bo‘lsa ham, uni issiqroq kiyintirib, 20 daqiqaga parkka olib chiqing. Barglar va toshlarni o‘rgansin, toza havo ikkovingizga ham yaxshi ta’sir qiladi.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', '«Seni topdim!» hayajoni 🙈', 'Bekinmachoq endi eng sevimli o‘yiniga aylandi. Parda ortiga yashirinib, uni topishingizni kutadi. Bu o‘yinni kundalik tartibingizning eng quvnoq qismiga aylantiring.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'Qorong‘ilikka ko‘nikish 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ekranlarni o‘chiring. Televizorning ko‘k nuri uyqu gormoni ishlab chiqarilishini sekinlashtiradi.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'Jasur qadamlar 🧗‍♂️', 'Divan yoki kresloga yopishib, tepaga chiqishga urinyaptimi? Uning muvozanati va mushak kuchi oshib bormoqda. Uni ehtiyot qiling, ammo bu kichik alpinistning urinishlariga aslo to‘sqinlik qilmang.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'Ovqat borasidagi qaysarlik 🥣', 'Ikki qoshiq yeb, to‘ydim degandek qochib ketyaptimi? Uni majburlamang. Ovqat bilan sog‘lom munosabatni shakllantirish majburlab yedirishdan muhimroqdir.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'Kun tahlili 📝', 'Bugun juda qattiq charchadingizmi yoki u juda yoqimli bir gap aytdimi? Har ikki holatda ham Kayfiyat kundaligini oching, bu lahzani kelajak uchun qayd eting va ko‘nglingizni yengillashtiring.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'Diqqat sinovi 🧩', 'Bitta o‘yinchoq, masalan, pazl bilan o‘ynash vaqti endi 10-15 daqiqagacha yetdimi? Bu uning diqqatni jamlash muddati uzayganini anglatadi. Xonaning bir chetida jimgina turib, uni kuzating.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'Sabab va oqibatni o‘rganish 🤔', '“Buni tashlasam, nima bo‘ladi?”, “Bu tugma nima uchun?” U tinmay amaliy tajribalar o‘tkazmoqda. Uy xavfsizligini bolaning bo‘yi darajasidan turib yana bir bor tekshirib chiqing.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'Ertaksiz uxlamaymiz 🪄', 'Klassik ertaklar endi uning e’tiborini tortmayaptimi? U bosh qahramon bo‘lgan, fonda tabiat tovushlari yangraydigan maxsus hikoya o‘ylab toping va uning tasavvur olamiga kirib boring.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'Musiqa sadolari ostida raqs 🎶', 'Quvnoq musiqa yangraganda darhol ritmga mos ravishda tebranadimi? Eshitish qobiliyati va harakat ko‘nikmalari o‘rtasidagi bog‘liqlik ajoyib rivojlanmoqda! Quvnoq qo‘shiq qo‘yib, u bilan birga xonada raqsga tushing.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'Dadaning hikoyasi 📖', 'Bugun kechqurun ovozingizga dam bering. Bolaning eng sevimli kitoblarini turli ovozlarda, kulgili tarzda o‘qib berish vazifasini dadasiga topshiring.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', 'Nega? tugadi, Qanday? boshlandi 🤔', 'Tasavvur va mantiqda katta sakrash! Endi u buyumlar qanday ishlashini ham so‘ramoqda. Anacan AI ekspertimizdan bu savollarga bolaning yoshiga mos va zeriktirmaydigan tarzda javob berish usullarini o‘rganing.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'Uyqusizlik bilan murosa qiling 😭', 'Yarim tunda uyg‘ondi va uxlashni istamayapti. Unga jahlingiz chiqmasin. Sababini (og‘riq, gaz, qo‘rquv) aniqlang va sabr bilan bag‘ringizga bosib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'Ketmaydigan dog‘lar 👗', 'Kiyimlarning doim dog‘ bo‘lishi sizni charchatyaptimi? Bundan jahlingiz chiqmasin. U taomlarni o‘rganmoqda. Silikon ko‘krakpechlardan foydalaning va bu rang-barang, betartib lahzalardan zavqlaning.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'Sizga yordam beray! 🧹', 'Siz pol artayotganingizda yoki chang olayotganingizda, u ishni qo‘lingizdan olishga urinadimi? U endi o‘zini katta his qilmoqda. Unga kichkina latta berib, jamoangizga qo‘shilishiga ruxsat bering.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'Tanangizga quloq tuting 🩸', 'To‘satdan shirinlik yegingiz kelib qoladimi yoki charchoq his qilasizmi? Hayz kuzatuvchisidagi taqvimga qarang. Agar hayz davringiz bo‘lsa, Sog‘lom retseptlardan magniyga boy yegulikni tanlang.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'Xonadagi soyalar 🌌', 'Qorong‘ilik va xayoliy maxluqlardan qo‘rqadimi? Xonani butunlay qorong‘i qilmang va Oq shovqinlar bo‘limidan ona qornidagi tovushni qo‘yib, unga o‘sha tanish, mutlaq xavfsizlik hissini bering.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'Ajralish xavotiri 🥺', 'Siz xonadan chiqqaningizda, hatto hojatxonaga borganingizda ham ortingizdan yig‘laydimi? U sizni qaytib kelmaydi deb o‘ylaydi. «Men doim shu yerdaman, ovozimni eshityapsanmi?» deb unga dalda bering.'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'Sergap kichkintoy 🗣️', 'U allaqachon 4-5 ta so‘zni birlashtirib, kulgili hikoyalar aytib beryaptimi? Uning so‘z boyligi jadal oshmoqda! Bu oltin fursatni qo‘ldan boy bermang.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'Tovushlarni yumshating 🤫', 'U uxlayotgan paytda tovushlarga sezgirligi ortadi. Derazadan keladigan tovushlarni neytrallashtirish uchun xonada past ovozda oq shovqin (white noise) qurilmasini yoki musiqani yoqing.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'Oshxonada birga 🧑‍🍳', 'Oshxonada siz bilan birga ish qilgisi keladimi? Un yoki suv solayotganda sizga yordam berishiga ruxsat bering. Hamma joy iflos bo‘lsa ham, uning quvonchi va o‘rganishga bo‘lgan ishtiyoqi bunga arziydi.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'Ro‘yxat shunchaki kerak emas, u shart 🛒', 'Uyqusizlik xotirangizni susaytirib, do‘konda olishingiz kerak bo‘lgan narsalar esdan chiqyaptimi? Miyangizni zo‘riqtirmang. Hammasini ilovadagi Xaridlar ro‘yxatiga yozib qo‘ying.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'Shunchaki quchoqlang 🫂', 'Hech qanday o‘yin yoki kitob kerak emas. Bugun kechqurun uni shunchaki bag‘ringizga bosing, hidini to‘yib hidlang va qorong‘ida unga qanchalik qadrli ekanini pichirlab ayting.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'Konstruktor ustasi 🧱', 'Yirik LEGO bo‘laklarini bir-biriga ulab, nimadir yasashga urinyaptimi? U makon va geometriyani kashf etmoqda. Rivojlanish kuzatuvchisida uning bu o‘ziga xos muhandislik urinishini belgilang.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', 'Yolg‘iz o‘zingiz uchun 10 daqiqa 🛀', 'Xonaga sukunat cho‘kdi. Juftingizdan uydagi barcha ishlarni o‘z zimmasiga olishini so‘rang. Siz esa iliq dush qabul qilib, faqat o‘zingiz bilan yolg‘iz qoling.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', '2 yosh sindromi 📱', 'Bolaning hamma narsaga yo‘q deyishi joningizga tegdimi? Bloglar bo‘limidagi maqolalarni o‘qib, uning miyasida kechayotgan bu rivojlanish bo‘ronining sabablarini tushunib oling.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'Yashirin sabzavot operatsiyasi 🥦', 'Ko‘katlar yoki brokkolini likopchadan uloqtiryaptimi? Chaqaloqlar uchun retseptlar orasidan sabzavotli, rang-barang uy keksini toping va Ovqatlanish nazorati vositasida vitaminlar me’yorini bemalol bajaring.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'Chuqur nafas oling 🧘‍♀️', 'Kun bo‘yi savollarga javob beraverib tomog‘ingiz qurib qolgan. Xonada jimlik hukm surishi bilan hech qanday ekranga qaramay, shunchaki chuqur nafas olib-chiqarib dam oling.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'So‘zlarning talaffuzi 🗣️', 'Ba’zi so‘zlarni chala yoki juda kulgili talaffuz qiladimi? Kulmang, aksincha, miyasi to‘g‘ri variantni o‘zlashtirishi uchun o‘sha so‘zni unga to‘g‘ri urg‘u bilan takrorlab ayting.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'Mustaqil o‘yin 🧸', 'Uni har daqiqada ko‘nglini olishga majbur emassiz. Zerikish bolalar uchun ijodkorlikning boshlanishidir. Xonada o‘zi mustaqil ravishda nimanidir kashf qilishiga imkon bering.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'Vaqtni to‘xtatadigan lahza 📸', 'Bolangiz uxlaganida uning beg‘ubor yuziga qarang. Kun bo‘yi sizni aqldan ozdirgan bo‘lsa ham, uxlashi bilan uni sog‘inasiz, shunday emasmi? Onalikning o‘zi mana shu paradoksdir.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'Suv ichish odati 💧', 'Suv o‘rniga doim shirin sharbatlar so‘raydimi? Oziqlanish rejasidagi suyuqlik ichish tartibini tekshiring. Suvni rangli, maxsus naychali stakanlarda taklif qilib, uni qiziqtiring.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'Qarsaklar jamoasi 👏', 'Biror narsani uddalaganida o‘ziga o‘zi qarsak chalib, quvonchini ko‘rsatadimi? Bu ajoyib lahzani ko‘rishingiz bilan uyda kichik g‘alaba raqsini tushib, uning quvonchiga sherik bo‘ling!'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'Ona charchaganda 🛑', 'Siz robot emassiz. Agar bugun ovqat pishirishga kuchingiz bo‘lmasa, tayyor ovqat buyurtma qiling. Mukammal ona bo‘lish hamma ishni yolg‘iz bajarish degani emas.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'Qat’iy «yo‘q»lar 🛑', 'Kimdir uni o‘pmoqchi bo‘lganda uzoqlashib, qat’iy «yo‘q» deydimi? Uning shaxsiy tana chegaralarini hurmat qiling. Ruxsatsiz teginishlarga qarshi chiqishi juda muhim.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'Sirlarni bo‘lishish 💬', 'Juda charchadingizmi? Anacan hamjamiyatiga qo‘shiling. Minglab onalarning haqiqiy hikoyalarini o‘qib, yolg‘iz emasligingizni his eting va kuch to‘plang.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'Sabzavotlarni yashiring 🥦', 'Sho‘rvadagi barcha sabzavotlarni chetga olib qo‘yadimi? U bilan kurashmang. Sabzavotlarni pyure qilib, sous yoki kotlet ichiga yashirish — onalarning eng qadimiy hiylalaridan biri.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'Rasmlarga munosabat 📖', 'Kitobdagi hayvonlar yoki turli buyumlarni ko‘rganda ularga tegib, tovushlar chiqaradimi? Uning ko‘rish orqali idrok etishi hayratlanarli. U bilan kitobdagi qahramonlar haqida suhbatlashing.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'Uyqu oldidan quvlashmachoq 🏃‍♂️', 'Yotmaslik uchun tinmay bahonalar o‘ylab topadimi? Uyqu taymerini yoqing, belgilangan chegaralarga rioya qiling va Oq shovqinlardan yomg‘ir tovushini qo‘yib, xonada tinch muhit yarating.'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'Suyuqlik iste’moli va qabziyat 💩', 'Ko‘p yugurib, kam suv ichyaptimi? Tuvak yoki taglikdagi najasini kuzating. Qabziyat xavfi bo‘lsa, buni ilovada qayd eting va darhol Ovqatlanishni nazorat qilish vositasi yordamida menyuga suli yormasi yoki nok qo‘shing.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'Yangi do‘st izlash 👫', 'Bog‘da tengdoshlari bilan yugurishga, ularga yaqinlashishga harakat qilyaptimi? Ijtimoiylashuv rasman boshlandi! Xavfsizligini uzoqdan nazorat qilib, bu urinishlarini faxr bilan kuzating.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'Tun ohangi 🛀', 'Kun bo‘yi yugurishdan u ham, siz ham charchadingiz. Iliq vanna va fonda yangraydigan yengil, sokin kuy uning asab tizimini butunlay tinchlantiradi.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'Kunduzgi uyquni rad etish 🥱', 'Yana uxlamadimi? U bilan kurashib, uni ham, o‘zingizni ham charchatmang. Xonada o‘yinchoqlar bilan jimgina o‘ynash ham miya uchun dam olishning bir turidir.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'Sukunat va qahva 🤫', 'U uxlab qoldi! Endi idish yuvish mashinasini bo‘shatish o‘rniga, qorong‘i xonada o‘tirib turing. 15 daqiqalik sukunatni qadrlang va dam oling.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'Pastga qarang! 👣', 'U allaqachon oyoq barmoqlarini ushlab, ularni o‘rganyaptimi, hatto yalangoyoq yurishdan zavqlanyaptimi? Oyoq kaftidagi nervlarni kashf etish uning muvozanati uchun juda muhim.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'Ob-havo syurprizi ⛅', 'Sayrga chiqqanda ob-havoga aldanib, bolangizni sovitib qo‘ymang. Derazadan qarab xulosa qilmang, tashqaridagi shamol tezligi va haqiqiy haroratni oldindan tekshiring.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'O‘zligini kashf etmoqda 👑', 'Men!, Meniki! degan so‘zlar tilidan tushmaydi. Bu egosentrizm davrining eng yaqqol bosqichidir. Uning o‘ziga xosligini hurmat bilan qabul qiling, bu rivojlanish bosqichidir.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'Otaning mas’uliyati 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechqurun bolani uxlashga tayyorlash va unga pijama kiydirishni otasiga topshirib, o‘zingiz chetdan kuzating.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'Energiya zaxirasi kerak 🍲', 'Charchoq suyak-suyagingizgacha o‘tdimi? 10 daqiqada tayyor bo‘ladigan, ham to‘q tutadigan, ham tetiklashtiradigan maxsus salat tayyorlab, o‘zingizni siylang.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'Tish cho‘tkasi uchun kurash tugaydi 🪥', 'Tish cho‘tkasini ko‘rishi bilan og‘zini mahkam yumib oladimi? Bu jarayonni osonlashtiradigan musiqali yoki aylanuvchi bolalar tish cho‘tkalarini Tavsiya etilgan mahsulotlardan izlab, gigiyenani qiziqarli mashg‘ulotga aylantiring.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'Tungi to‘fon 😭', 'Yarim tunda hech qanday sababsiz yig‘lab uyg‘ondimi? Qorni dam bo‘lganmi yoki bu shunchaki tungi vahimami? Uni ohista bag‘ringizga bosing va ovozingizni ko‘tarmasdan tinchlantiring.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'Xotira pand beryaptimi? 🛒', 'Uyqusizlik xotirangizni susaytirib, do‘konda olmoqchi bo‘lgan narsalaringiz esdan chiqyaptimi? Miyangizni zo‘riqtirmang. Hammasini ro‘yxatga yozing, turmush o‘rtog‘ingiz yo‘lda olib kelsin.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'Diplomatik muzokaralar 🤝', 'Bog‘da o‘yinchog‘ini bermayaptimi? 2.5 yoshdan keyin bolaga bo‘lishishni emas, navbat bilan o‘ynash tushunchasini qanday singdirish kerakligini Bloglar bo‘limida albatta o‘qing.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'Tunda uyg‘onishlar 🌌', 'Yarim tunda yig‘lab uyg‘onib, tinchlanmayaptimi? Uyqu taymeri grafigini tekshiring. Tungi vahima va dahshatli tush o‘rtasidagi farqni bilish uchun hoziroq Bloglar bo‘limiga kiring.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'To‘rt devor tashqarisiga ☕', 'Uydagi bir xil tartib sizni zeriktira boshladi. Bugun biroz o‘zgarish qiling. Yaqin atrofdagi sokin kafega borib, ham uning muhitini o‘zgartiring, ham qahvangizdan zavqlaning.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'Uyquga sezgirlik 🤫', 'Uyquga ketishi bilan eng kichik shovqindan ham cho‘chib uyg‘onadimi? Xona akustikasini tekshiring va derazadan kelayotgan tovushlarni bosish uchun oq shovqinni yoqing.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'Mebellarga tirmashish 🧗‍♂️', 'Divan yoki stuldan ushlab tepaga tirmashishga urinyaptimi? Oyoq mushaklari turli balandliklarni sinab ko‘rmoqda. Uning xavfsizligini ta’minlang, ammo bu alpinistlik urinishlariga to‘sqinlik qilmang.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'Likopchadagi san’at asari 🥦', 'U ovqatni yemayaptimi? Ba’zan muammo ta’mda emas, uning ko‘rinishida bo‘ladi. Rang-barang sabzavotlardan kulgili yuzchalar yasab, uning ishtahasini ochishga harakat qiling.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'Tungi alla 🎶', 'Hech bir ilova yoki tovush ona allasining o‘rnini bosa olmaydi. Bugun kechqurun uni shunchaki bag‘ringizga bosing va unga ishonch bag‘ishlaydigan sevimli allasini ohista kuylang.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'Tuvakdagi ilk g‘alaba! 🚽', 'Tuvakka o‘zi borishni xohlayaptimi? Bu 2.5 yoshdagi eng katta g‘alabadir! Taglik/Tuvak kuzatuvchisida bu muvaffaqiyatni qayd eting va Bloglarda bu bosqichga o‘tishni yanada osonlashtirish yo‘llarini o‘qing.'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'Qaysarlik xurujlari 🛑', 'Har bir «yo‘q» degan so‘zingizga qichqiriq bilan javob beradimi? Bunday boshqarib bo‘lmaydigan hissiy portlashlarni xotirjamlik bilan boshqarish va chalg‘itish usullarini o‘rganish uchun Anacan AI bilan dardlashing.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'Dadaning ertak vaqti 📚', 'Bugun kechqurun uyquga yotqizish marosimini hamkoringizga topshiring! Ilovadagi Hamkor rejimidan foydalanib, ertakni u o‘qib bersin, siz esa bemalol choyingizni iching.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'Tajriba almashish 💬', 'Bolangizning yangi bir harakati sizni qo‘rqitdimi? Internetdan qo‘rqinchli maqolalarni qidirmang. Anacan Hamjamiyatidagi tajribali onalarning maslahatlaridan foydalaning.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'Temirning siri: C vitamini 🍋', 'Rangi oqarganmi yoki ishtahasi yo‘qmi? Ovqatlanishni nazorat qilish vositasida bugungi temir iste’molini tekshiring va go‘sht bilan birga, albatta, limonli salat berib, temirning so‘rilishini yaxshilang.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'Faqat quruq ovqatlarmi? 🍞', 'Pyure va suyuq taomlardan bosh tortib, faqat non yoki pechenye so‘raydimi? Bu taom tuzilishiga nisbatan tanlab yeyishdir. Ovqatlanishni nazorat qilish vositasi yordamida menyuni tahlil qiling va Chaqaloq retseptlaridan foydali muqobillarni toping.'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'Tanangizga quloq tuting 🩸', 'To‘satdan shirinlik yegingiz kelib, jahldor bo‘lib qolyapsizmi? Hayz kuzatuvchisidagi taqvimga qarang. Agar hayz davringiz bo‘lsa, Ayollar uchun foydali retseptlardan magniyga boy xurmo va yong‘oqli gazak tayyorlang.'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'Tabiat detektivi 🔍', 'Uyda hamma narsani sochib tashlayaptimi? Lupani oling va tashqariga chiqing! Onalar uchun qulay joylar orasidan yam-yashil bog‘ toping, hasharotlar va barglarni birgalikda o‘rganib, uning energiyasini tabiatga yo‘naltiring.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'Kechki tartib qiyinlashdimi?🛀', 'Iliq vanna qabul qilayotganda fonda tinchlantiruvchi musiqa qo‘ying. Suv va ohang uyg‘unligi hatto eng qaysar bolani ham yumshatadi.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'Uydagi tartibsizlik 🌪️', 'Xonaning hamma joyi o‘yinchoqmi? Tozalikdan ko‘ra, u bilan quvnoq kayfiyatda o‘tkazgan 10 daqiqangiz muhimroq. O‘yinchoqlar ertaga ham o‘sha yerda bo‘ladi, o‘zingizni charchatmang.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'Mutlaq sukunat izlab 🛋️', 'Bola uxlashi bilanoq idish yuvish mashinasini bo‘shatishga shoshilmang! Divanga cho‘ziling, ko‘zlaringizni yuming va 15 daqiqa davomida uydagi o‘sha noyob, mutlaq sukunatga singib keting.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'Qorong‘ilikka ko‘nikish 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlar va ekranlarni o‘chiring. Melatonin gormonining ajralishi faqat tinch va qorong‘i muhitda tezlashadi.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'Seni eshityapman 🗣️', 'Sizni diqqat bilan tinglab, o‘xshash jumlalar tuzishga harakat qilyaptimi? U siz bilan gaplashyapti! Unga ko‘proq jilmayib javob bering va bu muloqotni rag‘batlantiring.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'Sayr vaqti 🌳', 'To‘rt devor orasida siqilib qoldingiz. Uni aravachasiga o‘tqazing va hech bo‘lmasa 20 daqiqaga toza havoga chiqing. Tabiatning osoyishtaligi chaqaloqqa ham, ruhiy holatingizga ham juda yaxshi ta’sir qiladi.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'Pastga qarang! 👣', 'U yalangoyoq yurishdan, oyoqlari bilan turli yuzalarni his qilib o‘rganishdan zavqlanyaptimi? Oyoq kaftidagi nerv uchlarini rag‘batlantirish uning muvozanatni saqlashi uchun juda muhim.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'Ertaklarning sehrli olami 🪄', 'Bugun kechqurun butunlay boshqacha bir ertakni sinab ko‘ring: Osmonni kashf etgan mitti bulutcha haqidagi hikoyani aytib bering. Ovoz ohangingizni ertak ritmiga moslang.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'Kechki tartibdagi sokinlik 🌬️', 'U kun bo‘yi yugurib, endi tinchlana olmayaptimi? Uyqu taymerini ishga tushiring, Oq shovqinlardan okean to‘lqinlari ovozini yoqing va xonani sokin uyqu maskaniga aylantirib, uning kuchini tiklang.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'Dadaning oshxona kuni 👨‍🍳', 'Hamkor rejimini faollashtiring. Bugun tushlik tayyorlash va bolani ovqatlantirish dadasining zimmasida! Siz esa bu vaqtni kitob o‘qish yoki dam olish orqali o‘zingizga bag‘ishlang.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'Maqsadli emaklash 🐢', 'U endi yurish bilan birga, ba’zan o‘yin uchun tez emaklab sizdan qochadimi? Xonadagi xavfli to‘siqlarni olib tashlang va bu quvlashmachoq o‘yiniga siz ham qo‘shiling.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'Nega yig‘layotganini o‘zi ham bilmaydi 😭', 'Stakani ko‘k emas, qizil bo‘lgani uchun qattiq injiqlik qilyaptimi? Aslida bunga charchoq yoki hissiy zo‘riqish sabab bo‘lishi mumkin. Bunday boshqarib bo‘lmaydigan hissiy portlashlarni xotirjamlik bilan yengish uchun Anacan AI bilan dardlashing.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'Xonadagi begona tovushlar 🌌', 'Xonadagi mutlaq sukunat yoki qo‘shni tomondan kelayotgan mayda taqillashlar uni uyg‘otadimi? Oq shovqinlardan ventilyator tovushini yoqib, uyqu muhitini tashqi tovushlardan qanday mukammal himoyalash mumkinligini ko‘ring.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'Uyni birga tozalaymiz 🧹', 'Uyni tozalash kerakmi? Hamkor rejimini ishga tushiring! Siz, dadasi va kichkintoyingiz (qo‘liga kichik latta tutqazib) uy tozalashni qanday qilib qiziqarli oilaviy o‘yinga aylantirishingiz mumkinligini bilib oling.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'Ekran o‘rniga o‘yin 📱', 'Kechga yaqin multfilm ko‘rishni xohlab, yig‘layaptimi? Ekran vaqtini stresssiz qanday cheklash va uning e’tiborini darhol boshqa o‘yinga qanday jalb qilishni Anacan AI’dan bilib oling.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'Sizning qahva vaqtingiz ☕', 'Doim uyda o‘tirishdan charchadingizmi? Onalar uchun qulay joylardan onalar ko‘p yig‘iladigan bolalar kafelarini topib, o‘zingiz uchun ham muloqot qilishga yangi muhit yarating.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'Navbat kutish san’ati 🧸', 'Bog‘da boshqa bolaning sirpanchiqdan tushishini kutishni istamayaptimi? 2.5 yoshdan keyin sabr qilish va navbat bilan o‘ynash tushunchalarini qanday singdirish haqida Bloglar bo‘limida albatta o‘qing.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'Suyaklar uchun D vitamini ☀️', 'Kalsiy so‘rilishi uchun D vitamini zarur! Ovqatlanishni nazorat qilish vositasi orqali bugungi ratsioningizni tekshiring va Tavsiya etilgan mahsulotlar bo‘limida shifokorlar tavsiya qilgan tomchilarni ko‘rib chiqing.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'Paysalga solish inqirozi 🛑', 'Uydan chiqishingiz kerak, ammo u hamma ishni sekin bajarib, shoshilmayaptimi? Bu yoshda bolalarda vaqt tushunchasi hali shakllanmagan! Uni shoshiltirish o‘rniga, bir mashg‘ulotdan boshqasiga o‘tishni qanday osonlashtirishni Anacan AI ekspertimizdan bilib oling.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'Mukammal ona bo‘lish istagi 💖', 'Bugun sabringiz tugab, ovozingizni balandlatdingizmi? O‘zingizni aybdor his qilmang. Bola uxlagach, Kayfiyat kundaligiga ichki kechinmalaringizni yozib, ko‘nglingizni yengillashtiring.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'Kunduzgi uyqu bilan xayrlashish vaqti keldimi? ⏱️', 'Kunduzi uxlashni qat’iyan rad etib, kechga borib juda charchab qoladimi? Uyqu taymeri statistikasini tahlil qilib, kunduzgi uyqu o‘rniga sokin vaqt (quiet time) rejimiga to‘liq o‘tishga tayyorligini tekshiring.'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'Onadagi PMS inqirozlari 🍫', 'Hayz arafasida quvvatingiz pasaydimi? Dori ichishga shoshilmasdan, avval Ayollar uchun sog‘lom retseptlar bo‘limidagi tabiiy shakarli rezavor mevalardan tezda quvvat beruvchi smuzi tayyorlab, tanangizni tiklang.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'O‘zim kesaman! ✂️', 'Oshxonada banan yoki o‘yin xamirini o‘zi kesishni xohlayaptimi? Bu nozik motorikani rivojlantirish uchun ajoyib istak! Tavsiya etilgan mahsulotlar bo‘limida bolalar uchun xavfsiz, tig‘siz pichoq va qaychilarni hoziroq ko‘ring.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'Temir zaxirasini tekshirish 🥩', 'Rangi oqarib ketganmi yoki ishtahasi yo‘qmi? Ovqatlanishni nazorat qilish vositasida bugun qancha temir qabul qilganini tekshiring va go‘sht bilan birga limonli salat berib, temirning so‘rilishini yaxshilang.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'Dadaning massaji 💆‍♀️', 'Kun bo‘yi bolaning ortidan yugurib, belingiz qotib qoldimi? Hamkor funksiyasi orqali unga bugun kechqurun bolani uxlatgach, yelkangizni qisqacha massaj qilib berish vaqti kelganini bildiring.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'Suv ichishni o‘yinga aylantiring 💧', 'Ko‘p yugurib, kam suv ichadimi? Ich qotishi xavfi ortadi. Ilovada ich kelishini qayd eting, so‘ng darhol Ovqatlanishni nazorat qilish vositasi orqali menyuga suli qo‘shing va Tavsiya etilgan mahsulotlardan bolalar uchun rang-barang suv idishlarini buyurtma qiling.'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'Ovqat tanlash odati 🍝', 'Faqat makaron xohlayaptimi? Ovqatlanishni nazorat qilish vositasi yordamida haftalik muvozanatni tekshiring. Atigi bir kunlik holat tufayli o‘zingizni ortiqcha tashvishga solmang.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'Charchoq ko‘z yoshlari 💧', 'Sizning ham yig‘lagingiz kelyaptimi? Bu mutlaqo tabiiy. Kayfiyat kundaligiga his-tuyg‘ularingizni yozing va o‘zingizni ayblashni bas qiling.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'Raqamlarni taniydimi? 🔢', 'Zinadan chiqayotganda yoki o‘yinchoqlarni yig‘ayotganda nimanidir sanashga urinadimi? Matematik rivojlanishning ilk uchqunlarini darhol ovozli video tarzida Chaqaloq albomiga qo‘shib, umrbod saqlanadigan xotiraga aylantiring.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'Temir va quvvat 🥩', 'Rangi oqarib ketganmi? Ovqatlanishni nazorat qilish vositasida temir iste’molini tekshiring. Go‘sht bilan birga limonli salat berib, temirning so‘rilishini yaxshilang.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'Tish cho‘tkasi jangi 🪥', 'Tish cho‘tkasini ko‘rishi bilan qochadimi? Tavsiya etilgan mahsulotlar bo‘limida musiqali cho‘tkalarni ko‘ring. Gigiyenani majburiyatga emas, o‘yinga aylantiring.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'Ekran mojarolari 📱', 'Telefonni olib qo‘ysangiz, qiyomat boshlanadimi? Ekran vaqtini stresssiz cheklashga yordam beradigan, amalda sinalgan psixologik sirlarni Anacan AI-dan so‘rang.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'Tungi vahimalar 🤖', 'Yarim tunda qichqirib uyg‘onib, sizni tanimayaptimi? Bunday holatda nima qilish kerakligini va uning boshqa holatlardan farqini Bloglar bo‘limidagi maqolalardan hoziroq bilib oling.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'Sizning ham do‘stingiz bor ☕', 'Faqat bola bilan gaplashish charchatadi. Onalar uchun qulay joylar bo‘limidan bolalar kafelarini toping, bir finjon qahva ichib, boshqa onalar bilan muloqot qiling.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'Ertalabki mojarolar 🛑', 'Har bir «yo‘q» deganingizda yig‘laydimi? Hissiy portlashlarni xotirjam boshqarish va bolaning diqqatini chalg‘itish haqida Anacan AI bilan dardlashing.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'Sabzavotlarni yashiring 🥦', 'Ko‘katlar yoki brokkolini likopchadan olib tashlayaptimi? Chaqaloq retseptlaridan rang-barang, sabzavotli uy keksini toping va Ovqatlanish nazorati vositasida vitaminlar bo‘yicha kunlik me’yorni osonlik bilan bajaring.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'Siz mukammal jamoasiz 🌟', 'Har kuni o‘rganayotgan yangi ko‘nikmasi, dadil tashlayotgan har bir qadami — siz va juftingiz mehnatining natijasi. Kayfiyat kundaligini oching va bugun jamoa sifatida o‘zingizni tik turib olqishlang!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'Bo‘y va vaznda keskin o‘sish! 📏', 'Kiyintirayotganda ko‘ylaklari toraygani yoki oyoq kiyimi siqayotganini payqadingizmi? Vazn kuzatuvchisiga hozirgi bo‘yi va o‘lchamlarini kiriting hamda rivojlanish egri chizig‘i qanday yuqorilayotganini faxr bilan kuzating.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'Dadaning ertak vaqti 📚', 'Bugun kechqurun chaqaloqni uxlatish navbati juftingizda. Ertakni u o‘qisin, siz esa sizga taqdim etilgan bu qisqa tanaffusdan zavqlaning.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', '“Nega?” savollari 🤔', 'U dunyoni tushunishni istaydi. Uning tuganmas savollariga qanday sabr bilan javob berishni Bloglardan bilib oling. Sizning sabringiz — uning rivojidir.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'To‘rt devor joniga tegdimi? 🌳', 'Uyda hamma narsa havoda uchyaptimi? Onalar uchun qulay joylardan yaqin atrofdagi parkni toping. Toza havo ham unga, ham sizga eng yaxshi davodir.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'Kir bo‘lishga ruxsat 🏖️', 'Loy bilan o‘ynashni xohlayaptimi? Mayli, kir bo‘lsin! Sensor rivojlanishni qo‘llab-quvvatlaydigan eng yaxshi vositalarni Tavsiya etilgan mahsulotlardan toping.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'Bo‘y o‘sishidagi sakrash 📏', 'Ko‘ylaklari kalta bo‘lib qoldimi? Demak, ulg‘ayayapti! Joriy o‘lchamlarini Vazn kuzatuvchisiga kiriting va rivojlanish egri chizig‘i qanday yuqorilayotganini faxr bilan kuzating.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'Issiq choy va sukunat 🍵', 'Taymer to‘xtadi, bola uxlab qoldi. Uy ishlarini unuting! Sog‘lom retseptlardan foydalanib melissa choyini damlang va shunchaki sukunatdan zavqlaning.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'Kun tartibini tahlil qilish ⏱️', 'Kechqurun uxlab qolishi juda cho‘zilyaptimi? Uyqu taymeri grafigini ko‘rib chiqing. Balki kunduzgi uyquni ancha qisqartirish vaqti kelgandir.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'Kalsiy qalqoni 🦴', 'Sut ichmayaptimi? Suyaklar uchun kalsiy zarur. Ovqatlanishni nazorat qilish vositasi yordamida qatiq yoki brokkoli iste’molini hisoblang va yetishmayotgan miqdorni to‘ldiring.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'Uzun jumlalar 🗣️', 'Endi kulgili hikoyalar aytib beryaptimi? Lug‘at boyligi jadal oshmoqda! Bu bebaho lahzani o‘tkazib yubormay, Chaqaloq albomiga ovozli xotira sifatida saqlang.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'Erta uyg‘onishlar 🌅', 'Quyosh chiqishidan oldin uyg‘onib, kuch-g‘ayratga to‘ladimi? Siz esa holdan toyganmisiz? Bu rejimni qanday tartibga solishni Anacan AI’dan so‘rang. Uyqusizlik abadiy emas.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'Dadaning ertagi 📚', 'Hamkor rejimini yoqing. Bu oqshom ertak qahramoni — dada! U o‘qisin, siz esa qahvangizni damlab, boshqa xonada sukunatdan zavqlaning.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'Bo‘lishish muammosi 🧸', 'O‘yinchog‘ini hech kimga bermaydimi? Bu xudbinlik emas, balki yoshiga xos rivojlanish bosqichi. Bloglardan navbat bilan o‘ynashni qanday o‘rgatish mumkinligini bilib oling.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'Ko‘z yoshlar — tabiiy 💧', 'Charchadingizmi va shunchaki yig‘lashni istayapsizmi? Kuchli ona bo‘lish — ba’zan zaifligingizni tan ola bilishdir.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'Quvvat pasayishi ⚡', 'Kunduzi tik turgancha mudrayapsizmi? Kofeinga emas, oqsilga murojaat qiling! Sog‘lom retseptlar bo‘limidagi bir zumda quvvat beruvchi yeryong‘oq pastali smuzi bilan tetiklaning.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'To‘satdan boshlanadigan jazava 🛑', 'Hech qanday sababsiz o‘zini yerga tashlaydimi? Bunday jazavalarni xotirjam boshqarish va atrofdagilarning qarashlariga e’tibor bermaslik uchun Anacan AI bilan dardlashing.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'Rassomning yangi asari 🖍️', 'Qog‘ozlar tugab, endi devor yoki eshikka rasm chizmoqchimi? U shunchaki chizg‘ilamayapti, balki mayda motorikasi yordamida dunyoni kashf etyapti. Unga katta karton berib, chegarani belgilab qo‘ying.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'Sukunatni his qilish 🤫', 'Uydagi tartibsizlik nihoyat tinib, u uxlab qoldi. Shovqin o‘lchagichni yoqing, xonadagi sukunat darajasini ko‘ring va 15 daqiqa davomida hech qanday ekranga qaramay, shu sukunatdan zavqlaning.'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'Sabzavotlar niqobda 🥦', 'Likopchadagi barcha yashil narsalarni bir chetga suryaptimi? Ovqat tanlash odati avjiga chiqqan. Ovqatlanish rejasi bo‘limidan sabzavotlarni pyure qilib, kotlet ichiga yashirish mumkin bo‘lgan ayyorona retseptlarni toping.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'Bolalar maydonchasidagi chegaralar 🧸', 'Qum maydonchasida chelakchasini hech kimga bermayaptimi? Bu xudbinlik emas, balki egalik tushunchasining shakllanishidir. Bo‘lishishni majburlash orqali emas, navbat bilan o‘rgating: Hozir uning navbati.'),
  ('b0edd680-c98e-4626-b7fa-18383befe832', 'Xayoliy mehmonlar keldi ☕', 'Xonada yolg‘iz o‘zi ko‘rinmas do‘stlari bilan gaplashib, ularga choy quyib beryaptimi? Bu tasavvur rivojining eng yuqori cho‘qqisi! Bu ajoyib ssenariynavisni chetdan faxr bilan kuzating.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'Sehr boshqaruvi bolaning qo‘lida 🪄', 'An’anaviy ertaklar uni zeriktirdimi? Aqlli ertaklarda bu safar qahramonni uning o‘zi tanlashiga ruxsat bering. Uchadigan it yoki Gapiradigan daraxt – tasavvuriga erkinlik bering.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'Singan pechenye fojiasi 🍪', 'Pechenyesi ikkiga bo‘lingani uchun dunyoning oxiri kelgandek bo‘lyaptimi? 2.5 yoshga xos klassik injiqliklarga xush kelibsiz. Mantiq izlamang, shunchaki uning bu ulkan qayg‘usini tushunishingizni ayting.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'Filtrlanmagan haqiqat 🛑', 'Ijtimoiy tarmoqlardagi tinch va ozoda bolalar videolarini ko‘rib, o‘zingizni ayblayapsizmi? Ular shunchaki 15 soniyalik illyuziya. Sizning tartibsiz va shovqinli hayotingiz esa eng go‘zalidir.'),
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc', 'Pijamaga qarshi norozilik 👕', 'Kiyinishni istamay, uy bo‘ylab yuguryaptimi? Bu kurashni o‘yinga aylantiring. Qani, kim tezroq kiyinar ekan? Raqobat ko‘pincha qaysarlikni yengishning eng yaxshi usulidir.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'Kichik diktofon ishga tushdi 🎙️', 'Og‘zingizdan chiqqan eng tasodifiy so‘zni ham darhol takrorlayaptimi? U sizning jonli ko‘zgungiz. Bu yoshda so‘z boyligi keskin oshadi, yangi so‘zlarni Rivojlanish kuzatuvchisiga qayd etib boring.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'Tezkor xaridlar 🛒', 'Uyqusizlik diqqatingizni tarqatib yubordimi? Nima sotib olishingiz kerakligini doim unutib qo‘yyapsizmi? Hammasini darhol Xaridlar ro‘yxatiga kiriting, turmush o‘rtog‘ingiz esa bozor-o‘char mas’uliyatini to‘liq o‘z zimmasiga olsin.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'Dadaning ertak teatri 📖', 'Ovoz paychalaringiz kun bo‘yi yo‘q deyishdan charchadi. Bugun kechqurun ertak aytish vaqtini dadasiga topshiring. U ovozini o‘zgartirib, kulgili hikoyalar aytib bersin, siz esa dam oling.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'O‘z qoidalarini o‘rnatmoqda 🛑', '«Hammasini o‘zim qilaman!» deydi. Oyoq kiyimini teskari, ko‘ylagini noto‘g‘ri kiyadi, ammo baribir o‘jarlik qiladi. Hechqisi yo‘q, mustaqil bo‘lish istagi tashqi ko‘rinishdan muhimroq — unga imkon bering.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'Suv terapiyasi 🛀', 'Kun bo‘yi yugurib, uning ham, sizning ham asablaringiz taranglashdi. Iliq vanna shunchaki gigiyena uchun emas, balki suvning taranglikni ketkazuvchi mo‘jizaviy kuchidan foydalanish uchun ham kerak.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'Toliqish hissi 🔋', 'Hamma narsaga baqirgingiz kelyaptimi? Bu — ruhiy va jismoniy holdan toyish. Darhol Anacan hamjamiyatiga kiring, siz bilan bir xil davrni boshdan kechirayotgan onalarning samimiy hikoyalarini o‘qib, yordam va dalda oling.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'Oshxonadagi g‘alayon 🧑‍🍳', 'Siz ovqat pishirayotganingizda, u qozonlar bilan konsert uyushtiryaptimi? U ham jamoaning bir a’zosi bo‘lishni xohlaydi. Qo‘liga kichkina xamir bo‘lagini bering, u ham ovqat tayyorlasin.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'Birgalikda uddalaymiz 🥂', 'Bola uxlagach, juftingiz bilan yuzma-yuz o‘tiring. Bola haqida gapirish o‘rniga, «Bugun ham omon qoldik», deb bir-biringizga jilmaying va jamoaviy ruhni his qiling.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'Tashqariga chiqish shart ⛅', 'To‘rt devor orasida siqilib qoldingiz. Ob-havo va kiyim vositasi orqali tashqarida havo qanday sezilishini tekshiring va hech ikkilanmay parkka yo‘l oling. Toza havo hatto eng kuchli injiqlik xurujlarini ham tezda bosadi.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_uz = v.t, body_uz = v.b
FROM (VALUES
  ('1e03f3e4-2305-4ae5-883c-39581f248697'::uuid, 'Raqamlarni kashf qilmoqda 🔢', 'Zinadan chiqayotganda yoki o‘yinchoqlarini terayotganda bir, ikki, uch deb sanashga harakat qiladi. Kognitiv rivojlanishning ushbu matematik bosqichini u bilan birga sanash orqali qo‘llab-quvvatlang.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'Dadaning maxfiy quroli 🤡', 'Sizning usullaringiz ish bermay qolganida, dadasining g‘alati tovushlari va kulgili yuz ifodalari vaziyatni darhol qutqaradi. Kechki injiqlik paytlarida navbatni darhol unga bering.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'Kunduzgi uyqudagi injiqliklar 🥱', 'Yotishni umuman istamayaptimi? 2.5 yoshda ayrim bolalar kunduzgi uyqudan voz kecha boshlaydi. Uni uxlashga majburlash o‘rniga, 30 daqiqalik sokin kitob o‘qish vaqtini joriy qiling.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'Pastga qarang, u yerda nima bor? 👣', 'Yalangoyoq yurishdan, turli yuzalarga (qum, gilam, tosh) tegishdan o‘zgacha zavq oladi. Oyoq kaftidagi nervlarning qo‘zg‘alishi uning nevrologik rivojlanishi uchun juda muhimdir.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'Yorug‘likni xiralashtiring 🌙', 'Uyquga 1 soat qolganda uydagi barcha yorqin chiroqlar va ko‘k nurli ekranlarni o‘chiring. Melatonin gormoni faollashishi uchun uyda oqshomgi xira va sokin muhit yarating.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'Shifokor bilan bog‘liq xavotirlar 🤖', '2.5 yoshda zarur bo‘lgan vaksinalar yoki vitaminlar haqida savollaringiz bormi? Internetdagi vahimali forumlarda adashib qolmang, darhol Anacan AI’dan aniq javob oling.'),
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498', '20 daqiqalik poyabzal 👟', 'Poyabzalini o‘zi kiyishni xohlayapti-yu, uydan chiqish kechikyaptimi? Sabringiz tugamasin.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'Gaplar uzaymoqda 🗣️', 'Endi so‘zlarni bir-biriga bog‘lab, qiziqarli va butunlay o‘z mantiqiga mos gaplar tuzmoqda. Bu lahzalarni o‘tkazib yubormang, Chaqaloq fotosessiyasi yordamida uning bu yoqimli suhbatlarini videoga oling.'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'Qorong‘ilikdagi o‘yinlar 🐰', 'Chiroqlar o‘chganda qo‘rqadimi? Xonani butunlay qorong‘ilating va fonar yordamida devorda soyalar o‘yinini yarating. Qo‘rquvni o‘yin-kulgiga aylantirib, unga qorong‘ilik bilan do‘stlashishga yordam bering.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'Bo‘y va vazndagi sakrash 📏', 'Shimlari yana kalta bo‘lib qoldimi? U tez o‘smoqda! Rivojlanish kuzatuvchisiga joriy o‘lchamlarini kiriting va uyqusiz tunlaringiz mevasi bo‘lgan yuqorilab borayotgan rivojlanish egri chizig‘iga faxr bilan qarang.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'Sababsiz uyg‘onishlar 😭', 'Yarim tunda qichqirib uyg‘ondimi? Vahimaga tushmang. Yig‘i tahlili vositasi yordamida bunga o‘sish og‘rig‘i yoki uyqudagi vahima xuruji sabab bo‘lganini tekshiring va uni sabr bilan bag‘ringizga bosing.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'Muzdek qahva ☕', 'Qahvani tayyorlab, 3 soatdan keyin ichish — onalikning rasman yozilmagan qonuni. Bugun boshqacha yo‘l tuting. Uni o‘yinchoqlari bilan o‘zi o‘ynashga qo‘ying va o‘sha qahvani 10 daqiqa ichida issiqligicha iching!'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'Kichik bahslar 🗣️', 'Yo‘q, men katta bo‘lganman, o‘zim bilaman! Endi u dalillar keltirib, sizning fikringizga qo‘shilmaslikka harakat qilmoqda. Ovozingizni balandlatmasdan, u bilan teng darajada, ammo qat’iy javob bering.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'O‘zingizga vaqt ajratish ayb emas 💆‍♀️', '«Farzandim bilan kam vaqt o‘tkazyapman» degan xavotir har bir onada bo‘ladi. Ammo holdan toygan onaning farzandiga berishga kuchi qolmasligini unutmang. Kunduzi o‘zingiz uchun 20 daqiqalik nafas rostlash tanaffusini tashkil qiling.'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'Eng yoqimli yuk 🫂', 'Kun bo‘yi sizni tinkangizni quritdi, har narsaga yig‘ladi. Ammo kechqurun uxlayotib ko‘ksingizga suykalgan o‘sha jajji, iliq tananing hidi... Mana shu dunyodagi eng yoqimli tuyg‘udir.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'Onalar uchun joy ☕', 'Har kuni bir xil bog‘ga borishdan zerikdingizmi? Onalar uchun qulay joylar orasidan bolalar ham bemalol o‘ynay oladigan, shovqinsiz va o‘zgacha qahvaxona topib, bugun o‘zingizni erkalating.'),
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80', 'Shakl va makon tushunchasi 🧩', 'U pazllarni yig‘ishga, turli shakllarni mos teshiklarga joylashga astoydil harakat qilmoqda. Xato qilsa ham aralashmang. U muammolarni hal qilish ko‘nikmasini aynan sinash va xato qilish orqali o‘rganadi.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'Tabiiy oq shovqin 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — miya eng faol bo‘ladigan payt. Xonadagi tovush darajasini shovqin o‘lchagich yordamida sozlang. Ba’zan shunchaki mayin yomg‘ir tovushi uni chuqur uyquga eltishi mumkin.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'Qo‘shiq xirgoyi qilish 🎶', 'O‘yin paytida o‘zicha tushunarsiz so‘zlar bilan qo‘shiqlar aytadi. Bu ham nutq, ham eshitish qobiliyati rivojlanayotganining belgisidir. Bu yangi bosqichni rivojlanish kuzatuvchisiga albatta kiriting.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'Dada bilan kitob o‘qish vaqti 📖', 'Bu oqshom xonada o‘zgacha muhit yarataylik. Kitob o‘qishni dadasining yo‘g‘on va ishonch baxsh etuvchi ovoziga topshirib, siz bir chetda sukunatdan bahramand bo‘ling.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'Onalarni qo‘llab-quvvatlash guruhi 💬', 'Murakkab qaror qabul qilishingiz kerakmi? (Bog‘cha, tuvakka o‘rgatish, uyqu). Anacan hamjamiyatidagi tajribali onalarning maslahatlari hech bir kitobda yozilmagan eng amaliy yechimlardir.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'Uy yig‘ilmay qolaversin 🌪️', 'Har oqshom bir xil o‘yinchoqlarni qutiga yig‘ishdan charchadingizmi? Bugun yig‘ishtirmang! Uy muzey emas, balki hayot qaynaydigan va jajji kashfiyotchi ulg‘ayayotgan maskandir.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'Nishonga otish va to‘pni tutish ⚾', 'U endi siz otgan katta to‘pni shunchaki o‘tkazib yubormay, tutishga harakat qiladi. Ko‘z va qo‘l muvofiqligi jadal rivojlanmoqda. Yo‘lakda birgalikda kichik sport o‘yinlarini o‘ynang.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'Ertaksiz uxlamaymiz 🪄', 'Xona chiroqlarini butunlay o‘chiring. Aqlli ertaklarda fon sifatida faqat tabiat tovushlari (shamol, o‘rmon) yangraydigan, so‘zsiz va tinchlantiruvchi muhit yaratib, uyquga ketishni tezlashtiring.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'O‘zingizga rahmat ayting 🎈', 'Tunlari uyqusizlik, kunduzlari yugur-yugur... Ammo siz buning uddasidan chiqdingiz. Bugun uni ovozingizni ko‘tarmay tarbiyalay olganingiz uchun o‘zingizga «Barakalla!» deng!'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'Ro‘yxatsiz do‘konga borish? Aslo! 🛒', 'Xotirangizga ishonib do‘konga borasiz-u, uyga eng kerakli narsani olmasdan qaytasiz. Bu odatdan voz keching. Uyda nima yetishmayotgan bo‘lsa, darhol Xaridlar ro‘yxatiga yozib qo‘yishni odat qiling.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'His-tuyg‘ularingizni erkin qo‘yib yuboring 📝', 'Sizni hech kim tushunmayaptimi? Charchaganingizni sezmayaptimi? Kayfiyat kundaligi — eng yaxshi sirdosh. Unga barcha stressingiz, og‘riqlaringiz va yolg‘izlik hissini yozing, shunda qalbingiz qanday yengillashganini ko‘rasiz.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'Sabzavotlar bilan adovat davom etmoqda 🥦', 'U yana sho‘rvadagi mittigina sabzi bo‘lagini ko‘rib, ovqatdan bosh tortdimi? Porsiyalarni kichraytiring, shakllarni o‘zgartiring. Ijodkorlik — onaning eng kuchli qurolidir.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', '«Seni topdim!» syurprizi 🙈', 'Bekinmachoq qoidalari o‘zgardi. Endi u yashirinadi-da, o‘zi «Men shu yerdaman!» deb qichqirib chiqadi. O‘yin qoidalarini o‘zi o‘ylab topishiga imkon bering va birga mazza qilib kuling.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'Tungi osoyishtalik 🛀', 'Agar kechqurun u juda qaysar va asabiy bo‘lsa, uni iliq suvga tushiring. Vannada shunchaki suv bilan o‘ynashi va suvning terapevtik kuchi undagi barcha salbiy energiyani yuvib ketadi.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'Jamoaviy faxr 🥂', 'Og‘ir kunni ortda qoldirdingiz. Farzandingiz uxlagach, juftingiz bilan bir piyola choy quyib, «Biz haqiqatan ham buni juda yaxshi uddalayapmiz», deya bir-biringizga dalda bering.'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'Ob-havo o‘zgaruvchan ⛅', 'Sayrga chiqqanda ob-havoga aldanib, uni sovqotib qo‘ymang. Faqat derazadan qarab qaror qilmang, Ob-havo va kiyim yordamchisi orqali tashqaridagi sharoitga eng mos kiyimlar to‘plamini tanlang.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'Jasoratli sakrashlar 🧗‍♂️', 'U divandan yostiqlar ustiga o‘zini tashlaydi. Shu tariqa tortishish kuchi va jasoratini sinab ko‘radi. Taqiqlash o‘rniga, xonada xavfsiz sakrash hududini yarating.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'Uyqusizlik bilan murosa qiling 😭', 'U yarim tunda uyg‘ondi va uxlashni istamayapti. Undan jahlingiz chiqmasin. Sababini aniqlang va shunchaki yonida ekaningizni his qildirib, uni mehr bilan silang.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'Injiqlik paytida sabr 🛒', 'Do‘konda u xohlagan o‘yinchoqni olib bermaganingiz uchun qichqiryapti. Atrofdagi o‘zini mukammal ota-ona deb biladiganlarning qarashlariga e’tibor bermang. Xotirjam ko‘ziga qarab tushuntiring va qaroringizda qat’iy turing.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', '31-oyga o‘tish!  🎉', 'U endi bolalik davrining eng intellektual va ayni paytda eng murakkab bosqichida. Uning har bir gapi, har bir savoli siz uchun katta bir kashfiyotdir.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'Ovqatlanish inqirozlari 🥣', 'Ikki qoshiq yeb, to‘ydim deydi-da, qochib ketadimi? Uni majburlamang. Ovqat bilan sog‘lom munosabatni shakllantirish likopchadagi taomni oxirigacha yeyishdan muhimroq.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'Vaqtni to‘xtatuvchi kadr 📸', 'Xonada shirin o‘ynayotganida darhol Chaqaloq fotosessiyasini oching va uning o‘zgarib, ulg‘aygan chehrasini, o‘sha charaqlagan ko‘zlarini hech qanday filtrsiz suratga olib, kelajak uchun xotiraga muhrlang.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'Ayriliq xavotiri yana qaytdimi? 🥺', 'Hatto hojatxonaga kirganingizda ham eshik ortida sizni kutib yig‘laydimi? Ayriliq xavotiri ba’zan qaytadi. Har safar unga ovoz berib, shu yerda ekaningizni va qaytib kelishingizni, hatto boshqa xonadan turib ham ayting.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'Energiyani chiqarish zarur 🌳', 'To‘rt devor orasida qolish uni tajovuzkor qiladi. Uni aravachasiga o‘tqazing yoki qo‘lidan ushlab, toza havoga olib chiqing. Tabiatning osoyishtaligi chaqaloqqa ham, sizning ruhiy holatingizga ham juda yaxshi ta’sir qiladi.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'Qorong‘ilikka ko‘nikish 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin faqat tinch va qorong‘i muhitda tez ajraladi.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', '“Bu nima?”lar seli ☝️', 'Hamma narsani barmog‘i bilan ko‘rsatib, nomini so‘rayaptimi? U sizdan atrofidagi olamdagi narsalarni nomlab berishingizni istayapti. Bu muloqot rivojidagi katta sakrash! U ko‘rsatgan har bir buyumning nomini sabr bilan takrorlang.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'Qarsak chalish quvonchi 👏', 'Biror ishni uddalaganida o‘ziga o‘zi qarsak chalib, faxrlanadimi? U e’tirof etilishni istayapti! Siz ham uning bu kichik yutug‘ini katta quvonch bilan olqishlab, ruhlantiring.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'Savolingiz bormi? 🤖', '2.5 yoshdan keyin bolaning bo‘y va vazn grafigi sizni tashvishga solyaptimi? Internetdagi qo‘rqinchli maqolalarni o‘qigandan ko‘ra, Anacan AI’dan aniq va ilmiy asoslangan ma’lumot oling.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'Dadaning g‘alati tovushlari 🤡', 'Siz qilgan hech narsa ish bermaganida, dadaning g‘alati tovushlari vaziyatni qutqaradi. Kechki injiqlik paytlarida vazifani darhol unga topshiring va chetdan jilmayib kuzating.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'Tun ohangi 🛀', 'Kun bo‘yi yugurib, u ham, siz ham charchadingiz. Iliq vanna va fonda yangraydigan yengil, mayin ohang uning asab tizimini butunlay tinchlantiradi.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'Rasmlarning ma’nosini anglaydi 📖', 'Kitobdagi hayvonlar yoki bolalarni ko‘rganida ularga tegib, «Bu nima qilyapti?» deb so‘raydi. Uning ko‘rish orqali idrok etish qobiliyati hayratlanarli. Unga qahramonlar haqida batafsil hikoyalar aytib bering.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'Ona uchun vaqt 🥑', 'Kundalik yugur-yugurda tushlikni oyoq ustida yemang. Sog‘lom retseptlardan quvvat beruvchi tamaddi tanlang va hech bo‘lmasa 10 daqiqa divanda dam olib, o‘z ovqatlanishingizni birinchi o‘ringa qo‘ying.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'Kir bo‘lishga to‘liq ruxsat 🏖️', 'Loy yoki suv bilan o‘ynashni xohlayaptimi? Mayli, kir bo‘lsin! Sensor rivojlanishni qo‘llab-quvvatlovchi bunday mashg‘ulotlar uchun oson tozalanadigan jihozlarni Tavsiya etilgan mahsulotlardan toping.'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'Shovqinlarni filtrlang 🤫', 'Uyquga ketayotgan paytda uning sezgirligi ortadi. Derazadan kelayotgan shovqinlarni neytrallash uchun xonada past ovozli oq shovqin (white noise) qurilmasini yoki tabiat musiqasini yoqing.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'Pastga qarang, u nimani kashf etyapti? 👣', 'Endi u yalangoyoq yurishdan, gilamga yoki xonadagi toshlarga tegishdan zavqlanadi. Oyoq kaftidagi nervlarning qo‘zg‘alishi uning muvozanati va harakat ko‘nikmalari uchun juda muhim.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'Shunchaki bag‘ringizga bosing 🫂', 'Hech qanday o‘yin, kitob yoki ertak kerak emas. Bu oqshom shunchaki uni bag‘ringizga bosing, hidini to‘yib his qiling va qorong‘ida uning siz uchun qanchalik qadrli ekanini pichirlab ayting.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'Tajriba almashish 💬', 'Bolangizning hamma narsaga o‘jarlik qilishi sizni qo‘rqitdimi? Internetdan vahimali maqolalarni qidirmang. Anacan Hamjamiyatidagi tajribali onalarning hayotiy tajribalaridan foydalaning.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'Maqsadli yugurishlar 🐢', 'Endi u shunchaki yurish bilan kifoyalanmaydi, tez yugurib, sizdan yashirinadi. Xonadagi xavfli to‘siqlarni olib tashlang va siz ham bu quvlashmachoq o‘yiniga katta zavq-shavq bilan qo‘shiling.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'Pichirlab suhbatlashish 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni unga juda past ovozda, pichirlab aytib bering. Pichirlash miyani uyquga tayyorlashning eng yaxshi usulidir.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'Temir va kuch 🥩', 'Rangi oqarganmi yoki tez charchaydimi? Go‘sht bilan birga limonli yoki pomidorli salat berib, temirning so‘rilishini yaxshilang.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'Ro‘yxatlarning kuchi 🛒', 'Do‘konga borganingizda doim nimanidir unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni unga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini ro‘yxat bo‘yicha olib kelsin.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'His-tuyg‘ularingizni yozing 📝', 'Sizni hech kim tushunmayaptimi? Charchaganingizni ko‘rmayaptimi? Kayfiyat kundaligi eng yaxshi sirdoshdir. Unga barcha stressingiz, og‘riqlaringiz va yolg‘izlik hissini yozing — shunda ko‘nglingiz qanchalik tez yengillashganini ko‘rasiz.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'Bu meniki 🧸', 'Uyga kelgan mehmonning bolasiga o‘z o‘yinchog‘ini bermayaptimi? Bu xudbinlik emas, balki shaxsiy chegaralarini himoya qilishdir. Uni bo‘lishishga majburlab emas, o‘zingiz namuna bo‘lib o‘rgating.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'Erkin o‘yin 🧸', 'Uni har daqiqa ko‘nglini ochish yoki unga o‘yinlar o‘ylab topishga majbur emassiz. Zerikish bolalar uchun ijodkorlikning boshlanishidir. Xonada o‘zi mustaqil ravishda nimanidir kashf etishiga imkon bering.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'Dadaning hikoyasi 📖', 'Bu oqshom ovoz paylaringizga dam bering. Bolaning sevimli kitoblarini turli ovozlarda, kulgili tarzda o‘qib berish vazifasini dadasiga topshiring.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'Qat’iy «Yo‘q»lar boshlanadi 🛑', 'Kimdir uni o‘pmoqchi bo‘lganda uzoqlashib, qat’iy yo‘q deydimi? Uning shaxsiy tana chegaralarini hurmat qiling. Ruxsatsiz teginishlarga qarshilik ko‘rsatishi kelajakdagi o‘ziga ishonchi uchun muhimdir.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'Ona charchaganida 🛑', 'Siz temirdan emassiz. Agar bugun ovqat pishirishga kuchingiz bo‘lmasa, makaron qaynatib oling yoki tayyor ovqat buyurtma qiling. Mukammal ona bo‘lish — hamma ishni yolg‘iz bajarish degani emas.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'Qabziyat belgisi 💩', 'Ko‘p yuguradi-yu, ammo suv ichishni unutadimi? Tuvakdagi najasini kuzating. Menyusiga albatta kletchatkaga boy suli yormasi va olxo‘ri qo‘shing.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'Yotoqdagi tugamaydigan tomosha 🛌', 'Uxlash o‘rniga karavotda sakrab, yugurib yuribdimi? Uyqu taymerini yoqing va chegaralarni mehr bilan saqlang. Oq shovqinlardagi o‘rmon shovqini yordamida xonani sokin uyqu maskaniga aylantiring.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'Kalsiy qalqoni 🦴', 'Sut ichmaydimi? Suyaklar uchun kalsiy zarur. Ovqatlanishni kuzatish vositasi yordamida bugun qancha pishloq, qatiq yoki brokkoli iste’mol qilganini hisoblab, yetishmayotgan miqdorni to‘ldiring.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'Yostiqlar qal’asi 🏰', 'Bu oqshom xonani o‘yin maydonchasiga aylantiring. Divan yostiqlaridan kichkina qal’a qurib, ichiga kiring. Biroz tartibsizlik bo‘ladi, ammo quvnoq kulgilar bunga albatta arziydi.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'O‘zi ovqat yeyishga intilish 🥄', 'Qoshiqni olib, hamma joyni bulg‘ayaptimi? Ovqatlanish taymerini ishga tushiring. To‘kilgan ovqatga emas, u erishayotgan mustaqillik va o‘ziga bo‘lgan ishonchga qarab faxrlaning.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'Ertalabki injiqlik ☁️', 'Ko‘zini ochishi bilan hamma narsaga yig‘layaptimi va hech narsadan ko‘ngli to‘lmayaptimi? Balki u ayni o‘sish davrining o‘rtasidadir. Uni ko‘proq bag‘ringizga bosib, o‘zini xavfsiz his qilishiga yordam bering va kunni saqlab qoling.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'Dadaning tungi navbatchiligi 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetarli. Kechqurun bolani uxlashga tayyorlash va unga pijama kiydirishni dadasiga topshirib, o‘zingiz chetdan kuzating.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'So‘zlarni takrorlash 🗣️', 'Siz aytgan har bir yangi so‘zni darhol to‘tiqushdek takrorlayaptimi? Uning so‘z boyligi oshmoqda. Uning yonida ishlatadigan so‘zlaringiz va ifodalaydigan his-tuyg‘ularingizga alohida e’tibor bering — u hamma narsani takrorlaydi.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'Sabzavotlarni yashiring 🥦', 'U yana sho‘rvadagi kichkina sabzi bo‘lagini ko‘rib, ovqat yeyishdan bosh tortdimi? Ovqatlanish rejasiga amal qilib, sabzavotlarni pyure holiga keltirib kotlet ichiga yashirish — onalarning eng qadimiy va foydali hiylalaridan biridir.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'Ob-havo syurprizi ⛅', 'Sayrga chiqqanda ob-havoga aldanib, uni sovqotib qo‘ymang. Faqat derazadan qarab qaror qilmang, Ob-havo va kiyim yordamchisi orqali tashqaridagi sharoitga eng mos kiyimlar to‘plamini tanlab, so‘ng uydan chiqing.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'Tungi dovul 😭', 'Yarim tunda hech qanday sababsiz yig‘lab uyg‘ondimi? Bunga qorin dam bo‘lishi sababmi yoki bu shunchaki tungi vahimami? Uni xotirjam bag‘ringizga bosing, ovozingizni ko‘tarmasdan tinchlantirib, yana uxlatishga harakat qiling.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'Ajralish qo‘rquvi 🥺', 'Hatto hojatxonaga kirganingizda ham eshik ortida sizni kutib yig‘laydi. Ajralish xavotiri ba’zan kuchayadi. Har safar unga ovoz berib, shu yerda ekaningizni va tezda qaytishingizni ayting.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'Yangi do‘st izlash 👫', 'Bog‘da tengdoshlari bilan yugurishga, ularga yaqinlashishga harakat qilyaptimi? Demak, ijtimoiylashuv rasman boshlandi! Xavfsizligini uzoqdan kuzatib, bu ilk urinishlarini faxr bilan tomosha qiling.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'Pijama jangi 👕', 'Kechqurun kiyinish katta jangga aylanadimi? Tanlovni unga qoldiring: Qizil pijamani xohlaysanmi yoki ko‘kini? Bu kichik hiyla unga qarorni o‘zi qabul qilganini his ettiradi.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'Sokinlik soati ☕', 'Agar kunduzi uxlamasa, hech bo‘lmaganda 1 soatlik Sokinlik soati (quiet time)ni belgilang. U o‘z yotog‘ida kitob varaqlasin, siz esa choyingizni ichib, miyangizga dam bering.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'Uyqusizlik bilan murosa qiling 😭', 'Yarim tunda uyg‘onib, uxlashni istamayaptimi? Undan jahlingiz chiqmasin. Sababini (og‘riq, qorin dam bo‘lishi, qo‘rquv) aniqlang va bag‘ringizga bosib, sabr bilan yana uxlab qolishini kuting.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'Ketmaydigan dog‘lar 👗', 'Kiyimlarning doim dog‘ bo‘lishi sizni charchatyaptimi? Bundan jahlingiz chiqmasin. U taomlarni o‘rganmoqda. Silikon ko‘krakchalardan foydalaning va bu rang-barang, betartib lahzalardan shunchaki zavqlaning.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'Ko‘zgudagi do‘st 👀', 'Uni ko‘zgu oldiga olib boring. O‘z aksiga hayrat bilan qarashi va turli yuz ifodalarini namoyon etishini kuzating. Bu uning o‘zini anglashi uchun ajoyib mashg‘ulotdir.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'Musiqa bilan uyquga tayyorgarlik 🛀', 'Kechki tartib qiyinlashdimi? Iliq vanna paytida fonda tinchlantiruvchi musiqa qo‘ying. Suv va ohang uyg‘unligi hatto eng qaysar bolani ham tinchlantiradi.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'Tish yuvish jangi 🦷', 'Tish cho‘tkasini og‘ziga yaqinlashtirishga yo‘l qo‘ymayaptimi? Buni majburiyatga emas, o‘yinga aylantiring. Avval unga sizning tishlaringizni yuvishga ruxsat bering, keyin navbat sizga kelsin.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'Ovqat yeyishdagi qaysarlik 🥣', 'Ikki qoshiq yeb, to‘ydim deb qochib ketyaptimi? Uni majburlamang. Ovqat bilan sog‘lom munosabatni shakllantirish majburlab yedirishdan muhimroq. Ovqatlanishlar sonini ko‘paytirib, miqdorini kamaytiring.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'Qorong‘ilikdagi maxluq 🌌', 'Chiroqlarni o‘chirganingizda soyalardan qo‘rqadimi? Tasavvuri rivojlangani sari qo‘rquvlari ham haqiqatdek tuyula boshlaydi. Oq shovqinlar orasidan ona qornidagi tovushni yoqib, unga zarur bo‘lgan azaliy xotirjamlikni bering.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'To‘satdan to‘kilgan ko‘z yoshlar 😭', 'Ko‘zini ochishi bilan hech bir sababsiz yig‘laydimi? Hissiy zo‘riqishni boshdan kechirayotgan kichkintoyingizni xotirjamlik bilan qanday tinchlantirishni Anacan AI ekspertimiz bilan dardlashib bilib oling.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'Toza havoga ehtiyoj 🌳', 'Uyning to‘rt devori uni ham, sizni ham siqib qo‘ydimi? Vaziyat izdan chiqmasidan, Onalar uchun qulay joylar bo‘limidan yaqin atrofdagi parkni toping. Toza havo ikkingiz uchun ham eng yaxshi davodir.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'Sizga yordam beray! 🧹', 'Siz pol artayotganingizda yoki chang olayotganingizda qo‘lingizdan olishga urinadimi? U endi o‘zini katta his qilyapti. Unga kichkina latta berib, jamoangizga qo‘shilishiga imkon bering — rivojlansin.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'Energiyani sarflash kerak 🌳', 'To‘rt devor orasida qolish uni tajanglashtiradi. Uni aravachasiga o‘tqazing yoki qo‘lidan tutib, toza havoga olib chiqing. Tabiatning osoyishtaligi chaqaloqqa ham, ruhiy holatingizga ham juda yaxshi ta’sir qiladi.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'Qorong‘ilikka ko‘nikish 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni, ayniqsa, planshet ekranlarini o‘chiring. Melatonin faqat qorong‘i muhitda ajraladi.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'Gormonlar bo‘roni 🩸', 'Birdan shirinlik yegingiz kelib, jahlingiz chiqyaptimi? Hayz kuzatuvchisiga qarang. Balki bu PMSdir. O‘zingizni ayblamang, Sog‘lom retseptlar bo‘limidagi magniyga boy, xurmo qo‘shilgan tamaddi bilan tanangizni qo‘llab-quvvatlang.'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'Sababsiz ertalabki injiqliklar 🛑', 'Ko‘zini ochishi bilan hamma narsaga baqirib, yig‘layaptimi? Hissiy zo‘riqishni boshdan kechirayotgan kichkintoyingizni qanday qilib xotirjam tinchlantirishni hoziroq Anacan AI ekspertimiz bilan suhbatlashib bilib oling.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'Ertakning oxirini u aytsin 📖', 'Bugun kechqurun ertak o‘qiyotganda gaplarni tugatmay qoldiring, davomini u aytsin! Til rivojini ajoyib tarzda qo‘llab-quvvatlaydigan bunday muloqot usullari haqida Anacan AI’dan so‘rang.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'Kir bo‘lishga to‘liq ruxsat 🏖️', 'Loy yoki suv bilan o‘ynashni xohlayaptimi? Mayli, kir bo‘lsin! Sensor rivojlanishni qo‘llab-quvvatlaydigan bunday mashg‘ulotlar uchun oson tozalanadigan jihozlarni Tavsiya etilgan mahsulotlar bo‘limidan toping.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'Tartibni tahlil qilish ⏱️', 'Kechqurun uxlab qolishi 1 soat davom etadimi? Uyqu taymeri jadvaliga qarang. Balki kunduzgi uyquni ancha qisqartirish va kechki uyqu vaqtini ertaroqqa surish payti allaqachon kelgandir.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'Birgalikda tozalash 🧹', 'Uyni yig‘ishtirish kerakmi? Xonani supurayotganingizda, u ham latta bilan artib, sizga yordam bersin. Tozalashni birgalikda qanday qilib qiziqarli o‘yinga aylantirish mumkinligini Bloglardan o‘qing.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'Yarim tunda faryod 🤖', 'Yarim tunda qichqirib uyg‘onib, sizni tanimayaptimi? Bu tungi qo‘rquv xuruji bo‘lishi mumkin. Bunday vaziyatda qanday to‘g‘ri yo‘l tutish va uni uyg‘otmaslik sirlarini hoziroq Anacan AI’dan so‘rang.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', 'Nega?lar tugamaydi 🤔', 'U dunyoni tushunishni, hamma narsaning mantiqini anglashni istaydi. Uning tuganmas savollariga zerikmay, sabr bilan javob berishni Anacan AI’dan o‘rganing. Sabringiz – uning kelajagi.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'Qahvani issiqligida ichish huquqi ☕', 'Xona tartibsizmi? Mayli, shunday qolaversin. O‘zingizga 10 daqiqa ajrating va nihoyat o‘sha qahvani issiqligida iching. Siz mukammal bo‘lishga majbur emassiz.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'Yashirincha yeyilgan shokolad 🍫', 'Oshxonaga o‘tib, undan yashirincha oyoqda turib biror shirinlik yeb oldingizmi? O‘zingizni ayblamang. Kunning shovqin-suroniga bardosh berish uchun onaning qondagi qand miqdorini ko‘tarishga to‘liq haqqi bor.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'Sahna dadasiniki 🎭', 'Sizning Ovqatingni tugat degan gapingiz endi ta’sir qilmayaptimi? Navbatni dadasiga bering. U qoshiqni uchayotgan samolyotga aylantirganida, qaysarlik qandaydir mo‘jiza bilan yo‘qoladi. Dam oling va tomosha qiling.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'Noto‘g‘ri rangdagi qoshiq mojarosi 🥄', 'Ovqatni yashil emas, sariq qoshiqda berganingiz uchun qiyomat qo‘pdimi? Chuqur nafas oling. Bu vaziyatdan mantiq izlamang, u shunchaki dunyoni boshqara olishini sinab ko‘ryapti. Qoshiqni almashtiring va tabassum qiling.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', 'Sizga yordam beray 🧽', 'Siz chang artayotganingizda qo‘lingizdan lattani tortib oladimi? U o‘zini katta his qilishni xohlaydi. Unga kichkina nam latta bering. Tozalashdan ko‘ra ko‘proq iflos qilishi mumkin, ammo o‘zidan mamnun bo‘ladi.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'Uyning akustikasi 🤫', 'Kunduzgi uyquga zo‘rg‘a ketdi. Endi uydagi eng mayda taqillash ham sizni aqldan ozdirishi mumkin. Darhol Ovoz o‘lchagichni faollashtiring, derazalarni yoping va bu mutlaq sukunatdan zavqlaning.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'Poyabzal kiyish jangi 👟', 'O‘ng poyabzalini chap oyog‘iga kiyib olib, aslo yechishni istamayaptimi? Mayli, shunday qolsin. Hozir estetika yoki to‘g‘rilik uning erkinlik hissidan muhimroq emas.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'Qorong‘ilik bilan yarashish 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida sodir bo‘lgan voqealarni unga juda past ovozda, pichirlab aytib bering. Pichirlash miyani uyquga tayyorlaydigan eng tabiiy usuldir.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'Kichkina rassom 🎨', 'Qalam bilan devorga yoki qog‘ozga doiralar chizyaptimi? Bu yirik motorika rivojidagi katta sakrashdir.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'Bog‘cha izlash boshlanyaptimi? 🏫', '3 yoshga yaqinlashganda bog‘cha haqidagi o‘y xayolingizdan ketmayaptimi? Yolg‘iz o‘ylashdan charchagan bo‘lsangiz, Anacan hamjamiyatiga qo‘shilib, boshqa onalardan tajriba va tavsiyalarini so‘rang.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'Xayoliy choyxo‘rlik ☕', 'Bo‘sh piyolani sizga uzatib, «Choy iching», deyaptimi? Ramziy o‘yinlar — rivojlanishning eng ajoyib ko‘rinishlaridan biri. O‘sha piyoladagi xona haroratidagi xayoliy choyni katta zavq bilan iching.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'Kiyimlar dog‘ bo‘lib ketdi 🎨', 'Pijamasi ovqat, ust-boshi esa bo‘yoq dog‘lariga belandmi? Bolalar doim toza holda ulg‘ayishi shart emas — ular kashf etish jarayonida kir bo‘lishadi. Silikon ko‘krakpechlardan foydalaning, qolganini esa kir yuvish mashinasiga qo‘yib bering.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', '15 daqiqalik tanaffus 🛀', 'Hojatxonaga kirib, eshikni yopdingiz-u, shunchaki telefoningizga qarab o‘tiribsizmi? Ha, bu onalarning eng mashhur biroz chekinish va dam olish usuli. Hech kimga hisob bermasdan, o‘sha sukunatdan bahramand bo‘ling.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', '«Meni o‘pmang!» degan qat’iyat 🛑', 'Qarindoshlardan biri uni o‘pmoqchi bo‘lganda, yuzini burib, itarib yuboradimi? Uning shaxsiy tana chegaralarini buzmang! Ruxsatsiz teginishlarga qarshilik ko‘rsatishi uning sog‘lom kelajagi uchun juda muhim.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'Tungi vahima haqiqati 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘ondi va hech kimni eshitmayaptimi? Bu tungi vahima xurujidir. Uni silkitmang, uyg‘otishga urinmang. Shunchaki yonida bo‘lib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'Tabiat qo‘ynida hordiq chiqarish shart 🌳', 'Bugun uydagi tartibsizlikka chidab bo‘lmay qoldimi? Darhol Havo va kiyim vositasini tekshirib, ob-havoga mos tayyorlaning va eng yaqin bog‘ga yo‘l oling. Toza havo — bolani tinchlantirishning eng yaxshi vositasi.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'Dadaning parkdagi kashfiyoti 👨‍👧', 'Onalik 24/7 navbatchilik degani emas! Bugungi sayrni dadasiga topshiring. Ular birga loyga belanib o‘ynashsin, siz esa divanda yotib, sukunatdan zavqlaning.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'Bo‘y va vazndagi sakrash 📏', 'Shimlari yana kalta bo‘lib qoldimi? U har kuni ko‘z o‘ngingizda ulg‘aymoqda! Rivojlanish kuzatuvchisiga joriy o‘lchamlarni kiriting va uyqusiz tunlaringiz samarasi bo‘lgan rivojlanish egri chizig‘iga faxr bilan qarang.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'Klassik musiqa mo‘jizasi 🎶', 'Kechga yaqin sababsiz injiqlik boshlandimi? Televizorni o‘chiring, chiroqlarni xiralashtiring va xonada klassik musiqani juda past ovozda qo‘ying. Suv va musiqa uyg‘unligi muhitni o‘zgartiradi.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'Sho‘rvadagi maxfiy agentlar 🥦', 'Yashil rangdagi barcha narsalarga qarshi boykot e’lon qildimi? Xavotir olmang. Ovqatlanish rejasidan foydalanib, sabzavotlarni pyure qilib, kotlet va souslar ichiga yashirish — onalarning eng qadimiy va foydali hiylalaridan biridir.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'To‘qima qo‘shiqlar 🎤', 'O‘yinchoqlarini tartibga solayotganda, hech bir tilda bo‘lmagan so‘zlar bilan o‘zicha qo‘shiq aytyaptimi? Uning so‘z boyligi va ritmni his qilish qobiliyati bir vaqtda rivojlanmoqda. Bu yangi musiqiy bosqichni Rivojlanish kuzatuvchisiga albatta kiriting.'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'O‘jar pijama 👕', 'Kiyinish katta jangga aylanib qoldimi? Tanlovni uning o‘ziga qoldiring: Qizil pijamani xohlaysanmi yoki ko‘kini? Bu kichik hiyla unga qarorni o‘zi qabul qilayotgandek his qildiradi va qarshilikni to‘xtatadi.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'Ajralish xavotiri 🥺', 'Xonadan bir soniyaga chiqib ketsangiz ham, ortingizdan yig‘laydi. Ajralish xavotiri ba’zan yana qaytadi. Har safar unga ovoz berib, shu yerda ekaningizni, oshxonada ekaningizni va hozir kelishingizni ayting — shu tariqa uzoqdan bo‘lsa ham unga xotirjamlik baxsh eting.'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'Mukammallik bosimi 🛑', 'Boshqa bolalar allaqachon ranglarni ayta oladi-yu, sizning bolangiz buni istamayaptimi? Taqqoslashni darhol to‘xtating! Har bir bolaning rivojlanish sur’ati turlicha. Farzandingiz o‘z maromida rivojlanmoqda va bu mutlaqo normal.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'Dadaning maxfiy usuli 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechga yaqin bolani uyquga tayyorlash va tishlarini yuvdirish jarayonini dadasining o‘yinli usullariga topshiring, o‘zingiz esa chetda tinchgina choy iching.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'Pediatriyaga oid shubhalar 🤖', '32 oylik bolaning bo‘y va vazn grafigi sizni to‘satdan xavotirga soldimi? Internet forumlaridan qo‘rqinchli kasalliklarni qidirmang, Anacan AI orqali aniq va ilmiy asoslangan ma’lumotlarni bilib oling.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'Tabiiy uyqu muhiti 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — miya eng ta’sirchan bo‘ladigan payt. Derazadan kiradigan tovushlarni neytrallash uchun xonada yengil oq shovqin (masalan, yomg‘ir ovozi) qurilmasini yoqing.'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'Sizga tushuntirib beray! ☝️', 'U hamma narsani barmog‘i bilan ko‘rsatib, ketma-ket savollar beradi. U sizdan atrofidagi narsalarning nomini aytishingizni istaydi. Bu muloqot rivojidagi katta sakrash! Charchasangiz ham, buyumlarning nomini sabr bilan takrorlang.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'So‘zlarning yangi talqini 🗣️', 'Suv o‘rniga «uv», katta o‘rniga «tatta» deydimi? Bu shunchalik yoqimli eshitiladiki, kulmaslik qiyin. Ammo miyasi to‘g‘ri talaffuzni eslab qolishi uchun har safar so‘zning to‘g‘ri shaklini mehr bilan takrorlang.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'Ertak yakunini u yozsin 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Bu safar Aqlli ertaklarda hikoya yakunini farzandingiz tanlasin. «Sizningcha, qahramonga kim yordam berdi?» deb so‘rab, uning tasavvurini ishga soling.'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'Quvvat tugaganda 🔋', 'Bugun hech narsaga kuchingiz yo‘qmi? Sog‘lom retseptlardan 5 daqiqada tayyorlanadigan, blenderdan o‘tkazilgan, temir va vitaminlarga boy smuzi tayyorlab, yo‘l-yo‘lakay iching. O‘zingizga g‘amxo‘rlik qiling.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'Xaridlar ro‘yxati — haqiqiy najotkor 🛒', 'Xotirangizga ishonib do‘konga bordingiz-u, taglik olishni unutib qaytdingizmi? Bunday holatlar bo‘lib turadi. Barcha kerakli narsalarni Xaridlar ro‘yxatiga yozishni odat qiling, ularni sizga ilova eslatib tursin.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'Kutilmagan juftlik vaqti 🥂', 'Bola kutilmaganda erta uxlab qoldi! Bu noyob fursatni uy tozalashga sarflamang. Turmush o‘rtog‘ingiz bilan yuzma-yuz o‘tiring, televizorni o‘chiring va shunchaki bir-biringizdan kuningiz qanday o‘tganini so‘rang.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'Pazl muhandisligi 🧩', 'U shakllarni mos teshiklarga joylashga astoydil urinmoqda. Xato qilsa ham, jahli chiqsa ham, darhol yordam bermang. Muammolarni hal qilish ko‘nikmasini aynan shu urinishlar va xatolar orqali o‘rganadi.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'Shunchaki quchoqlang 🫂', 'Hech qanday o‘yin, kitob yoki ertak kerak emas. Bu oqshom shunchaki uni bag‘ringizga bosing, uning yoqimli hididan to‘yib nafas oling va qorong‘ida u siz uchun qanchalik qadrli ekanini pichirlab ayting.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'Birgalikda tozalash 🧹', 'Uyni yig‘ishtirish kerakmi? Xonani supurayotganingizda, u ham latta bilan artib, sizga yordam bersin. Tozalashni jamoaviy ish va o‘yin-kulgiga aylantirish haqida Bloglardan o‘qing.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'Men juda charchadim 🔋', 'Hamma sizdan kuch-g‘ayrat kutadi, ammo quvvatingiz tugagan. Bugun hech narsa pishirmang, tayyor ovqat buyurtma qiling. Mukammal ona bo‘lish — hamma narsani yolg‘iz bajarishingiz shart degani emas. O‘zingizga bunga ruxsat bering.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'Doiradan shaklga 🎨', 'Qalam bilan devorga yoki qog‘ozga doiralar chizyaptimi? Bu sho‘xlik aslida motorika rivojidagi katta sakrashdir.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'Suv uyg‘unligi 🛀', 'Kun bo‘yi yugurib, u ham, siz ham holdan toydingiz. Iliq vanna paytida fon sifatida tinchlantiruvchi tabiat tovushlarini qo‘ying. Suv uyg‘unligi hatto eng qaysar bolani ham uyquga tayyorlaydi.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'Do‘kondagi injiqlik 🛒', 'Kassa oldida shirinlik uchun qichqiryaptimi? Atrofdagilarning uni yomon bola deb qarashlariga aslo e’tibor bermang. Xotirjamlik bilan uning ko‘zlariga qarab, qoidani tushuntiring va qaroringizdan qaytmang.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'Rejim buzilyaptimi? ⏱️', 'Kechqurun uxlab qolishi 1 soatdan ko‘proq vaqt olyaptimi? Uyqu taymeri grafigiga qarang. Balki kunduzgi uyquni ancha qisqartirib, kechki uyqu vaqtini oldinroqqa surish payti allaqachon kelgandir.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'Hayvonlarga taqlid 🐶', 'U nafaqat hayvonlarning ovozini chiqaradi, balki itdek emaklab, mushukdek suykaladimi? Tana tili va tasavvur birlashmoqda. Siz ham u bilan gilam ustidagi bu o‘yinga katta ishtiyoq bilan qo‘shiling.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'Kunduzgi uyqu inqirozi 🥱', 'Yotishni istamay, yig‘layaptimi? 3 yoshga yaqinlashganda ayrim bolalar kunduzgi uyqudan voz kecha boshlaydi. Kurashish o‘rniga, Tinchlik soatini e’lon qilib, yotoqda o‘yinchoqlar bilan shunchaki jim o‘ynashni taklif qiling.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'Uxlashni istamayaptimi va qorong‘ilikdan qo‘rqyaptimi?', 'Xonani butunlay qorong‘ilating va devorda qo‘llaringiz bilan qush, it shaklidagi soyalarni yarating. Qo‘rquvni o‘yinga aylantirib, uning qorong‘ilik bilan do‘stlashishiga yordam bering.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'Ovqatlanishdagi ishoralar 🥣', 'Ikki qoshiq yeb, to‘ydim deydimi va stuldan tushib ketadimi? Uni majburlamang. Ovqat bilan sog‘lom munosabatni shakllantirish likopchadagi taomni albatta tugatishdan ko‘ra ancha muhim. Qorni ochsa, o‘zi so‘raydi.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'Rasmli hikoyalar 📖', 'Kitobdagi hayvonlar yoki bolalarni ko‘rganda ularga tegib, «Bu nima qilyapti?» deb so‘raydimi? Uning ko‘rish orqali idrok etishi hayratlanarli darajada rivojlanmoqda. U bilan birga qahramonlar haqida mazmunli va kulgili hikoyalar to‘qing.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'Uyqu jadvali o‘zgaryaptimi? 😭', 'Yarim tunda uyg‘onib, uxlashni istamayapti. Unga jahlingiz chiqmasin. Sababini aniqlang va shunchaki yonida ekaningizni his qildirib, uni silab-siypang, uxlab qolishini kuting.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'Ob-havo syurprizi ⛅', 'Sayrga chiqayotganda ob-havoga aldanib, uni sovitib qo‘ymang. Faqat derazadan qarab qaror qilmang, Ob-havo va kiyim yordamchisi orqali tashqaridagi shamolga eng mos kiyimlar uyg‘unligini tanlab, uydan xotirjam chiqing.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'Erkin o‘yinning foydasi 🧸', 'Har daqiqada uni ko‘nglini ochish yoki unga o‘yinlar o‘ylab topishga majbur emassiz. Zerikish bolalar uchun ijodkorlik sari ilk qadamdir. Xonada o‘zi mustaqil ravishda nimanidir kashf etishiga imkon bering.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'Bozor ro‘yxatida unutiladiganlar 🛒', 'Bozorga borganingizda doim eng kerakli narsani unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni u yerga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini ro‘yxat bo‘yicha xarid qilsin.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'Tana tili orqali muloqot 🗣️', '“Ketdikmi?” deganingizda qo‘llarini ko‘taradi yoki istamagan narsasiga keskin bosh chayqaydi. Uning tushunish qobiliyati hayratlanarli darajada rivojlandi! Unga ko‘proq tasdiqlovchi jumlalar bilan javob bering.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'Musiqa bilan uyquga tayyorlanish 🎶', 'Kechga yaqin sababsiz boshlanadigan injiqliklarni yengil klassik musiqa bilan tinchlantirib ko‘ring. Ko‘pincha bu oddiy, ammo samarali usul uyda mo‘jiza yaratib, xonaga albatta osoyishtalik olib kiradi.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'Tuvakdagi g‘alaba 🚽', 'Hojati kelganini sezib, o‘zi tuvakka yuguradimi? Bu katta g‘alaba!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'Ertakni o‘zi to‘qisin 📖', 'Bugun kechqurun kitobni bir chetga qo‘ying. Hikoyani u aytib bersin! Tasavvurining ajoyib rivojlanishini qo‘llab-quvvatlaydigan suhbat usullarini Anacan AI-dan so‘rang.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'Yashil rangga qarshilik 🥦', 'Ko‘katlarni likopchadan uloqtiryaptimi? Dasturxonni jang maydoniga aylantirmang. Sog‘lom retseptlar bo‘limida sabzavotlar yashirilgan uy kekslarini topib, vitaminlarga bo‘lgan ehtiyojini sezdirmay qondiring.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'Shivirlash sehri 🌙', 'Xonadagi chiroqlarni butunlay o‘chiring. Yoniga yotib, kun davomida yuz bergan voqealarni juda past ovozda qulog‘iga shivirlab aytib bering. Shivirlash — miyani uyquga tayyorlaydigan eng tabiiy va tinchlantiruvchi usullardan biri.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'Brokkoli izquvari 🥦', 'Likopchadagi yashil sabzavotlarni topib, chetga surib qo‘yadimi? Unda niqoblash san’atiga o‘ting. Sog‘lom retseptlar bo‘limidan sabzavotlarni pyure qilib, mazali kotletlar ichiga yashirishga yordam beradigan ayyorona retseptlarni toping.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'Bastakorning ilk konserti 🎤', 'O‘yinchoqlarini terayotib, hech bir lug‘atda yo‘q so‘zlar bilan, ammo o‘ziga xos ohangda qo‘shiq aytyaptimi? Bu intellektual yuksalishni to‘xtatmang, Rivojlanish kuzatuvchisiga uning ilk asari sifatida qayd eting.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'Uy ishlarini kim qiladi? 🌪️', 'Ishlar qolib ketyaptimi? Qolaversin. Bugun uy ishlarini sherigingiz o‘z zimmasiga olishini so‘rang. Siz dam oling, chunki bu uyda eng muhim va kuch-quvvatga eng ko‘p muhtoj inson — sizsiz.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'Jamoaviy qo‘llab-quvvatlash 🥂', 'Og‘ir kunni ortda qoldirdingiz. Bola uxlagach, sherigingiz bilan bir piyola choy quyib, «Biz buni haqiqatan ham juda yaxshi uddalayapmiz», deya bir-biringizni ruhlantiring.'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'Rasmlarga ma’no beradi 📖', 'Kitobdagi qahramonlarni ko‘rganda ularga tegib, «Bu nima qilyapti?» deb so‘raydi. Uning ko‘rish orqali idrok etishi hayratlanarli. U bilan birga o‘qiyotgan kitobingiz uchun yangi, butunlay o‘ylab topilgan yakun yozing.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'Tozalik sindromi 🌪️', 'Uyni supurib-sidirib tozaladingiz, ammo 10 daqiqadan keyin hamma joy yana portlash hududini eslatyaptimi? Bugun tartibsizlikka taslim bo‘ling. Divanga o‘tiring va qahvangizni ichib tugatmaguningizcha joyingizdan turmang.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'Dadaning diplomatik yechimi 👨‍👧', 'Sizning «Ovqatingni yeb bo‘l» degan gapingiz endi ta’sir qilmayaptimi? Navbatni dadasiga bering. U qoshiqni uchar kosmik kemaga aylantirganda, qaysarlik qandaydir mo‘jiza bilan yo‘qoladi. Siz esa dam olib, tomoshani kuzating.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'Ertalabki advokat ishga kirishdi 💼', 'Bu ko‘ylakni emas, boshqasini kiyaman! Endi xonada oddiy bola emas, siz bilan professional muzokara olib borayotgan kichkina advokat bor. Bahslashmang, shunchaki unga 2 ta variant taklif qilib, qarorni o‘zi qabul qilayotgandek taassurot uyg‘oting.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'Tabiat qo‘yniga qochish rejasi ⛅', 'To‘rt devor orasida qolish uning ham, sizning ham jahlingizni chiqardi. Ob-havo va kiyim vositasini tekshirib, tezda tayyorlaning-da, parkka yo‘l oling. Toza havo hatto kichkintoyning eng kuchli injiqliklarini ham darhol bosadi.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'Oltin sukunat 🤫', 'Uydagi tartibsizlik nihoyat tugadi va u qattiq uyquga ketdi. Shovqin o‘lchagichni yoqing, xonadagi sukunat darajasini (detsibelda) ko‘ring va 15 daqiqa davomida hech qanday ekranga qaramay, bu oltin sukunatdan zavqlaning.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'Avangard moda 👗', 'Shimni boshiga kiyib olib, xona bo‘ylab mag‘rur yuribdimi? Aralashmang. Bu kulgili tajribalar uning erkinlik va o‘ziga xoslik izlayotganidan darak beradi. Ha, g‘alati ko‘rinadi, ammo bunday lahzalar juda zavqli.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'Do‘konda xotirani yo‘qotish 🛒', 'Xotirangizga ishonib do‘konga bordingiz-u, eng kerakli narsani unutib qaytdingizmi? Barcha kerakli narsalarni ilovadagi Xaridlar ro‘yxatiga yozishni odat qiling — raqamli xotirangiz sizni qutqarsin.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'Ko‘rinmas mehmonlar 👻', 'Divandagi bo‘sh joyga qarab nimalarnidir gapiryaptimi, hatto ko‘rinmas do‘stiga choy quyib beryaptimi? Xayoliy do‘stlar davri avjiga chiqdi! Endi u o‘z dunyosining ssenariy muallifi. Bu tomoshani kulib kuzating.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'Suvning xotiralarni yuvish kuchi 🛀', 'Kun bo‘yi yugurib, uning ham, sizning ham asablaringiz taranglashdi. Iliq vanna shunchaki gigiyena emas — suvning taranglikni yengillashtirib, kun davomida to‘plangan salbiy energiyani yuvib ketadigan sirli kuchidan foydalanish imkonidir.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'Otaning oshxonadagi navbati 👨‍🍳', 'Onalik yolg‘iz o‘zingiz yuguradigan marafon emas. Dam olish kunlari tushlikni ota tayyorlab, bolani ovqatlantirsin, siz esa divanda cho‘zilib, qadrli tanaffusdan zavqlaning.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'Faqat men shundaymanmi? 💬', 'Juda charchadingizmi va sizni hech kim tushunmayotgandek tuyulyaptimi? Darhol Anacan hamjamiyatiga yozing. U yerda siz kabi uyqusizlikdan qiynalayotgan minglab onalarning men ham siz kabi degan xabarlari sizga kuch beradi.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'Ssenariyni u yozsin 🪄', 'Klassik kitoblardan ikkalangiz ham zerikdingiz. Bu safar Aqlli ertaklarda hikoyaning yakunini farzandingiz tanlasin. Seningcha, qahramonga kim yordam berdi? deb, uxlashdan oldin uning tasavvurini ishga soling.'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'Onaning oziq-ovqat zaxirasi 🥗', 'Uni to‘ydirish uchun 3 xil menyu o‘ylab topdingiz, o‘zingiz esa yo‘l-yo‘lakay tamaddi qilib qo‘ya qoldingizmi? Sog‘lom retseptlar orasidan 10 daqiqada tayyor bo‘ladigan, vitaminlarga boy salatni tanlab, o‘zingizga ham g‘amxo‘rlik qiling.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'Otaning mimika teatri 🤡', 'Sizning qiliqlaringiz endi ish bermay qolganda, otaning g‘alati tovushlari vaziyatni darhol qutqaradi. Kechki injiqlik paytida navbatni unga topshiring va chetdan quvnoq qahqahalarni tomosha qiling.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'Kichkina yordamchi 🧽', 'Siz chang artayotganingizda qo‘lingizdagi lattani tortib oladimi? U o‘zini katta va jamoaning bir qismi deb his qilishni istaydi. Unga nam latta bering. Tozalashdan ko‘ra ko‘proq iflos qilishi mumkin, ammo o‘zini muhim his qiladi.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'Uyqusizlik e’loni 🥱', 'Yotishni istamay, qarshilik qilyaptimi? Ayrim bolalar bu davrda kunduzgi uyqudan voz kechadi. U bilan kurashish o‘rniga, Tinchlik soatini e’lon qiling va yotoqda o‘yinchoqlari bilan shovqin qilmay o‘ynashni taklif eting.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'Tungi vahima siri 😭', 'Yarim tunda ko‘zlari yumuq holda yig‘lab uyg‘onadi va hech kimni eshitmaydimi? Ovozini Yig‘i tahliliga eshittiring. Agar bu tungi vahima bo‘lsa, uni uyg‘otishga urinmang. Shunchaki yonida bo‘lib, o‘zini xavfsiz his qilishiga yordam bering.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'Ovqat tanlash injiqliklari 🍝', 'Kecha yaxshi ko‘rgan taomini bugun rad etyaptimi? Dasturxonni jang maydoniga aylantirmang. Ovqatlanishni nazorat qilish vositasi yordamida haftalik muvozanatni tekshiring, Sog‘lom retseptlardan taomni turlicha va qiziqarli tarzda tortish usullarini toping.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'Jarohatlangan ayiqchaning shifokori 🩺', 'O‘yinchog‘i yiqilib tushsa, uni silab, «Yig‘lama», deydimi? Unda ajoyib hamdardlik tuyg‘usi shakllanmoqda! Shaxsiyat rivojining ushbu oltin bosqichini darhol Rivojlanish kuzatuvchisiga qayd eting.'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'Melatoninga taklif 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni va ko‘k nurli ekranlarni o‘chiring. Uyqu gormoni (melatonin) faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'Qum maydonchasidagi siyosat 🧸', 'Bog‘da chelakchasini hech kimga bermayaptimi? Bu xudbinlik emas, shunchaki shaxsiy mulk tuyg‘usining kashf etilishidir. Uni uyaltirmasdan navbat bilan o‘ynashni taklif qiling va diplomatik inqirozni hal eting.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'Ko‘z bilan aloqa qilish shart 🥂', 'Bola kutilmaganda erta uxlab qoldi! Bu noyob fursatni uy tozalashga sarflamang. Juftingiz bilan yuzma-yuz o‘tiring, televizorni o‘chiring va shunchaki bir-biringizning ko‘zingizga qarab, kun qanday o‘tganini so‘rang.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'Jonli diktofon 🎙️', 'Og‘zingizdan chiqqan eng tasodifiy so‘zni ham darhol to‘tiqushdek takrorlayaptimi? U sizning jonli ko‘zgungiz. Uning yonida aytadigan so‘zlaringiz va ifodalaydigan hissiyotlaringizga ikki karra e’tiborli bo‘ling — u hamma narsani takrorlaydi.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'Sovuq qahva haqiqati ☕', 'Qahva tayyorlab, uni 3 soatdan keyin muzdek holda ichish — onalikning yozilmagan qonuni. Bugun boshqacha yo‘l tuting! Uni o‘yinchoqlari bilan o‘ynashga qo‘yib, qahvangizni 10 daqiqa ichida issiqligida iching. Siz bunga loyiqsiz.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'Onaning yashirin bo‘roni 🩸', 'To‘satdan charchoq, sababsiz yig‘lash istagi paydo bo‘ldimi? Hayz kuzatuvchisini oching. Balki siz PMS davridadirsiz. O‘zingizni ayblamang, Sog‘lom retseptlardan magniyga boy yegulik tayyorlab, tanangizga quloq tuting.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'Raqamli pediatr 🤖', '33 oylik bolaning bo‘y va vazn grafigi sizni to‘satdan xavotirga soldimi? Internet forumlaridan dahshatli kasalliklarni qidirmang, Anacan AI orqali aniq, tezkor va ilmiy asoslangan ma’lumotlarni oling.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'Motsart effektlari 🎶', 'Kechga yaqin sababsiz tajovuzkorlik boshlandi. Televizorni o‘chiring, chiroqlarni xiralashtiring va xonada juda mayin mumtoz musiqa yangrasin. Suv va musiqa uyg‘unligi muhitni sehrli tarzda o‘zgartiradi.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'Derazaga ishonmang ⛅', 'Sayrga chiqayotganda derazadan qarab aldanmang. Ob-havo va kiyim yordamchisi orqali tashqaridagi haqiqiy shamol va haroratga eng mos kiyimlar to‘plamini tanlab, bemalol yo‘lga chiqing.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'Bozorlikdagi yordamchi 🛒', 'Do‘konga borganingizda eng kerakli narsani doim unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni unga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini ro‘yxat bo‘yicha olib kelsin.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'Suv terapiyasi 🛀', 'Kun bo‘yi yugurib, siz ham, u ham charchadingiz. Iliq vanna qabul qilayotganda fonda tabiatning tinchlantiruvchi tovushlarini yoqing. Suv uyg‘unligi hatto eng qaysar bolani ham uyquga tayyorlaydi.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'Qat’iy «Yo‘q»! 🛑', 'Kimdir uni o‘pmoqchi bo‘lganda uzoqlashib, qat’iy «yo‘q» deydimi? Uning shaxsiy tana chegaralarini hurmat qiling. Ruxsatsiz teginishlarga qarshilik ko‘rsatishi sog‘lom ruhiy rivojlanishi uchun muhimdir.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'Oyi, menga qarang! 👀', 'Siz telefonga yoki boshqa ishga qarayotganingizda, yoningizga kelib yuzingizni o‘ziga qaratadimi? U butun e’tiboringizni xohlaydi. Ko‘zlariga qarab, uni tinglayotganingizni va u siz uchun muhimligini his qildiring.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'Gaplar ertakka aylanmoqda 🗣️', 'Endi so‘zlarni birlashtirib, kulgili va xayoliy hikoyalar aytyaptimi? Uning lug‘at boyligi jadal oshmoqda!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'Xona akustikasi 🤫', 'Uyquga ketayotgan paytda tovushlarga sezgirlik ortadi. Derazadan keladigan tovushlarni neytrallash uchun Shovqin o‘lchagichni tekshiring va xonada mayin oq shovqin (white noise) qurilmasini yoqing.'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'Kichkina muhandis 🤔', 'Buni tashlasam nima bo‘ladi?, Bu tugma nima uchun? U tinmay amaliy tajribalar o‘tkazmoqda. U o‘rganyapti! Uy xavfsizligini pol sathidan yana bir bor ko‘zdan kechiring.'),
  ('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5', 'Onalarning maxfiy guruhi 💬', 'Murakkab qaror qabul qilishingiz kerakmi? (Masalan, bog‘cha tanlash). Anacan hamjamiyatidagi tajribali onalarning maslahatlari — hech bir kitobda yozilmagan, amalda sinalgan eng foydali yechimlardir.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'Parvoz sinovlari 🧗‍♂️', 'U divandan yostiqlar ustiga o‘zini tashlaydi. Shu tariqa tortishish kuchi va jasoratini sinab ko‘radi. Taqiqlash o‘rniga, xonada xavfsiz sakrash joyini yarating, energiyasini chiqarib olsin.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'Tungi faryod siri 😭', 'Sababini topa olmayotgan yig‘i xurujlari odamni holdan toydiradi. Taxmin qilishni bas qiling, Yig‘i tahlili vositasi yordamida ovoz ortidagi yashirin xabarni (og‘riq, charchoq) tushunishga va uni tinchlantirishga harakat qiling.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'Niqoblash ustasi 🥦', 'U sho‘rvadagi sabzavotlarni xuddi mikroskop bilan qidirayotgandek chetga ajratib qo‘yadimi? Sog‘lom retseptlar bo‘limidan sabzavotlarni sezilmas qiladigan sous retseptlarini toping. Ijodkorlik — onaning eng kuchli yashirin qurolidir.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'Tish cho‘tkasi jangi 🦷', 'Tish cho‘tkasini og‘ziga yaqinlashtirishingizga yo‘l qo‘ymay, o‘zi tozalashni xohlayaptimi? Buni majburiyatga emas, o‘yinga aylantiring. Avval u sizning tishlaringizni tozalasin, keyin navbat sizniki bo‘lsin.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'Tartibsizlikka ruxsat 🌪️', 'Har kuni bir xil o‘yinchoqlarni qutiga yig‘ishdan charchadingizmi? Bugun yig‘ishtirmang! Uy muzey emas, balki hayot qaynab turgan makondir. Tartibsizlikka emas, farzandingizning kashf etish quvonchiga e’tibor qarating.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'Navbat dadasiga 👨‍🍼', 'Kunduzgi charchoqning o‘zi sizga yetadi. Kechqurun bolani uyquga tayyorlash, tishlarini tozalatish va pijamasini kiydirishni dadasiga topshiring, o‘zingiz esa chetda xotirjam choy iching.'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'Shunchaki quchoqlang 🫂', 'Hech qanday o‘yin, kitob yoki ertak kerak emas. Bu oqshom shunchaki uni bag‘ringizga bosing, uning yoqimli hididan to‘yib nafas oling va qorong‘ida unga qanchalik qadrli ekanini pichirlab ayting.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', '“Bu nima?” davri ☝️', 'U hamma narsani barmog‘i bilan ko‘rsatib, nomini so‘rayaptimi? U sizdan dunyodagi narsalarning nomini aytishingizni istayapti. Bu muloqot rivojidagi katta sakrash! Charchasangiz ham, o‘sha buyumlarning nomini sabr bilan takrorlang.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'Siz ham insonsiz 🛑', 'Bugun hech narsa reja bo‘yicha ketmadimi? O‘zingizni ayblamang. Siz haqiqiy onasiz, ijtimoiy tarmoqlardagi filtrlangan tasvir emassiz. Farzandingizga shunchaki siz keraksiz.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'Rejissyor ish boshida 🎭', 'Rasmli kitobdagi qahramonlarga qarab, o‘zi butunlay o‘ylab topgan voqealarni so‘zlab beryaptimi? Tasavvuri rivoji cho‘qqida! Uning bu g‘aroyib hikoyalarini bo‘lmasdan, faxr bilan tinglang.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'Iliq choy va osoyishtalik 🍵', 'Uy ishlarini unuting, hammasi kutib turishi mumkin. Sog‘lom retseptlardan foydalanib, melissa choyini damlang va o‘zingiz bilan yolg‘iz qolishdan zavqlaning.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'Park terapiyasi 🌳', 'To‘rt devor orasida qolish sizni siqmoqda. Havo salqin bo‘lsa ham, uni issiqroq kiyintirib, 20 daqiqaga parkka olib chiqing. Barglar va toshlarni o‘rgansin, toza havo uning miyasini kislorod bilan ta’minlaydi.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'Likopchadagi san’at 🥦', 'U ovqatni yemayaptimi? Ba’zan muammo ta’mda emas, balki ko‘rinishda bo‘ladi. Rang-barang sabzavotlardan kulgili yuzchalar yasab, uning ishtahasini ochishga va ovqatlanishni o‘yinga aylantirishga harakat qiling.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'Quvnoq qahqahalar 🤡', 'Sizning urinishlaringiz ish bermaganida, dadasi chiqaradigan g‘alati tovushlar vaziyatni qutqaradi. Kechki injiqlik paytida vazifani darhol unga topshiring va chetdan jilmayib kuzating.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'Yovvoyi tabiat uyda 🐶', 'U nafaqat hayvonlarning ovoziga taqlid qiladi, balki it kabi emaklab, mushuk kabi erkalanyaptimi? Tana tili va tasavvur ajoyib tarzda uyg‘unlashmoqda. Siz ham u bilan birga gilam ustidagi bu o‘yinga qo‘shiling.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'Dadaning ovoz ohangi 📖', 'Bu oqshom ovoz paylaringizga dam bering. Farzandingizning sevimli kitoblarini turli ovozlarda, ijodkorona va kulgili tarzda o‘qish vazifasini dadasiga topshiring.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'Shaxsiy mulk 🧸', 'Farzandingiz uyga kelgan mehmonning bolasiga o‘z o‘yinchog‘ini bermayaptimi? Bu xudbinlik emas, balki shaxsiy chegaralarini himoya qilishdir. Uni bo‘lishishga majburlamang, shunchaki o‘zingiz namuna bo‘lib o‘rgating.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'Onaning quvvat zaxirasi 🥑', 'Kundalik yugur-yugurda tushlikni oyoqda turib yemang. Sog‘lom retseptlardan quvvat beruvchi tamaddi tanlang va hech bo‘lmasa 10 daqiqa divanda yotib, o‘z ovqatlanishingizni birinchi o‘ringa qo‘ying.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'Quvlashmachoq marafoni 🏃‍♂️', 'Endi u shunchaki yurish bilan kifoyalanmaydi: siz chaqirganingizda tez yugurib, berkinib oladi. Xonadagi xavfli to‘siqlarni olib tashlang va bu quvnoq quvlashmachoq o‘yiniga siz ham qo‘shiling.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'Psixologiyani kashf eting 📱', 'Farzandingizning hamma narsaga «yo‘q» deyishi joningizga tegdimi? Ilovadagi psixologik bloglarni o‘qib, uning miyasida kechayotgan ushbu rivojlanish bo‘ronining chuqur sabablarini tushunib oling.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'Qorong‘ilikning kuchi 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha qo‘shimcha chiroqlarni va planshet ekranlarini o‘chiring. Melatonin faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'Yalangoyoq yurish 👣', 'U yalangoyoq yurishdan va turli yuzalarga tegishdan o‘zgacha zavq oladi. Oyoq tagidagi nervlarning qo‘zg‘alishi uning nevrologik rivojlanishi uchun juda muhim, unga paypoqsiz yurishga ruxsat bering.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'Raqamli xotira 🛒', 'Do‘konga borganingizda doim nimanidir unutib qoldirasizmi? Xaridlar ro‘yxati ilovada sizni kutmoqda. Kerakli narsalarni u yerga yozib qo‘ying, turmush o‘rtog‘ingiz ishdan qaytayotganda hammasini ro‘yxat bo‘yicha olib kelsin.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'Ovozli tasavvur 🪄', 'Aqlli ertaklarda bugun kechqurun unga maxsus sarguzasht yarating: changyutgichdan qo‘rqmaydigan jasur quyoncha haqidagi hikoya. Qo‘rquvlarni ertaklar yordamida yengish juda oson.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'Nozik g‘urur 🛑', 'O‘zim qilaman! deb har qanday yordamni rad etadi. Oyoq kiyimini teskari kiyib olsa ham, unga tegmang. Oyoq kiyimining noto‘g‘ri kiyilganidan ko‘ra, uning g‘ururiga putur yetmasligi muhimroq.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'Shubhalarga chek qo‘ying 🤖', 'Bolangizning xatti-harakatidagi to‘satdan yuz bergan o‘zgarishlar sizni tashvishga soldimi? Internet forumlaridan qo‘rqinchli kasalliklarni qidirmang, Anacan AI orqali aniq, tezkor va ilmiy asoslangan ma’lumotlarni oling.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'Uyqu qo‘riqchisi 🤫', 'U uxlab qolganidan keyingi dastlabki yarim soat miya eng faol bo‘ladigan vaqtdir. Ovoz o‘lchagich yordamida xonadagi shovqin darajasini sozlang. Ba’zan mayin yomg‘ir tovushining o‘zi uni chuqur uyquga eltishi mumkin.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'Anatomiya darsi 👀', '“Yelkang qayerda?” deb so‘raganingizda, barmog‘i bilan tegib ko‘rsatadimi? Aqliy idrok ayni cho‘qqisida! O‘yinni murakkabroq tana a’zolari bilan davom ettirib, uning lug‘at boyligini oshiring.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'Suvning qudrati 🛀', 'Kun bo‘yi yugurib, u ham, siz ham charchadingiz. Iliq vanna paytida fon sifatida tinchlantiruvchi tabiat tovushlarini qo‘ying. Suvning uyg‘unligi hatto eng qaysar bolani ham uyquga tayyorlaydi.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'Onaning likopchasidagi mazali taom 🥣', 'O‘z likopchasini chetga surib, siz yeyayotgan taomga intiladimi? Bolalar doim ota-onasining tanloviga ko‘proq ishonadi. Sog‘lom retseptlar orasidan ikkalangiz ham birga yeyishingiz mumkin bo‘lgan taomlarni tanlang.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'Sayr taktikasi ⛅', 'Sayrga chiqayotganda havoga aldanib, uni sovitib qo‘ymang. Derazadan qarab xulosa qilmang: Ob-havo va kiyim yordamchisi orqali tashqaridagi shamolga eng mos kiyimlar to‘plamini tanlab, bemalol yo‘lga chiqing.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'Melatonin fabrikasi 🌙', 'Tezroq uxlab qolishi uchun xonadagi barcha ortiqcha chiroqlarni o‘chiring va planshet ekranlarini yoping. Melatonin faqat qorong‘i va texnologiyalarsiz muhitda tez ajraladi.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'Odob qoidalari 👋', 'Kimdir eshikdan chiqayotganida, o‘z tashabbusi bilan qo‘l silkitib xayrlashadi! Ijtimoiy intellekt va empatiya shakllanmoqda. Uning bunday odobli harakatlarini ko‘proq rag‘batlantiring.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', '1000 kunga atigi 5 kun qoldi! 🎈', 'Sanoq tugash arafasida! Siz roppa-rosa 1000 kunlik ulkan va unutilmas yo‘lni bosib o‘tish arafasidasiz. Tabassum qiling, yubileyga tayyorgarlik va quvnoq g‘oyalarni hozirdanoq boshlang!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'Sokin kitob vaqti 🥱', 'Yotishni istamay, qarshilik qilyaptimi? Ayrim bolalar bu davrda kunduzgi uyqudan voz kechadi. Kurashish o‘rniga «Sokinlik vaqti»ni e’lon qilib, yotoqda shunchaki kitob varaqlashni taklif qiling.'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'Faxr varag‘i 📝', 'Shuncha uzoq va past-baland yo‘lda sizning eng katta kuchingiz — unga bo‘lgan mehringizdir. Kayfiyat kundaligini oching va unga kelajakda o‘qishi uchun faxrga to‘la kichik bir maktub yozing.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'Kichik yordamchi 🧸', 'Oyoq kiyimini olib kelish kerakligini aytsangiz, rostdan ham borib olib keladimi? So‘z boyligi va tushunish qobiliyati ayni cho‘qqisida! Uni uydagi kichik yumushlarga jalb qilib, o‘ziga bo‘lgan ishonchini oshiring.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'Haqiqiy jamoa — sizlar 🌟', 'Har bir ishonchli qadam — siz va juftingizning birgalikdagi mehnati samarasidir.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'Tartibsiz uy, quvnoq ona 🌪', 'Kiyimlar tog‘dek uyulib yotibdi, idish yuvish mashinasi to‘lib ketganmi? Mayli, tura qolsin. Bugungi uy ishlarini o‘z zimmasiga olishini juftingizdan so‘rang. Siz dam oling, axir bu uyning asosiy tayanchi sizsiz.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'Birgalikda tozalik 🧹', 'Uyni yig‘ishtirish kerakmi? Xonani supurayotganingizda, u ham latta bilan artib, sizga yordam bersin. Tozalikni jamoaviy ish va maroqli mashg‘ulotga aylantirish haqida Bloglardan o‘qing.'),
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7', 'Kun tartibi buzilyaptimi? ⏱️', 'Kechqurun uxlab qolishi juda cho‘zilyaptimi? Uyqu taymeri jadvaliga qarang. Balki kunduzgi uyquni ancha qisqartirib, kechki uyqu vaqtini oldinga surish payti allaqachon kelgandir.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', '«Men katta bo‘ldim!» qaysarligi 🛑', 'Hamma narsaga aralashishni istab, ishlarni sekinlashtiryaptimi? Mustaqillik uchun bu kulgili kurashda unga bir nechta oddiy tanlov taklif qiling.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', '1000 kunlik mo‘jiza! 👑', 'TABRIKLAYMIZ! Siz mana roppa-rosa 1000 kundirki, ushbu shiddatli, mashaqqatli, ammo dunyodagi eng qadrli yo‘lni bosib kelyapsiz! Bu alohida g‘alaba kunini hoziroq nishonlang va Anacan hamjamiyatida faxr bilan ulashing!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'Jamoaning g‘alaba raqsi 🥂', '1000 kunlik charchoq, ko‘z yoshlari va quvonchni bugun kechqurun juftingiz bilan birga nishonlang. Dasturxonga sham qo‘yib, mustahkam jamoangiz g‘alabasini katta quvonch bilan olqishlang!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'Siz buni uddaladingiz! 📈', 'Farzandingiz qanchalik uzoq yo‘lni bosib o‘tdi! Ilk kunlardagi o‘sha nozik qo‘rquv endi ulkan ishonchga aylandi. Siz bu 1000 kunlik yo‘lni katta faxr bilan bosib o‘tdingiz! Siz haqiqatan ham ajoyibsiz!'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'Xayoliy ssenariylar 🧸', 'O‘yinchoq ayiqchasiga ertak aytib beryaptimi yoki bo‘sh piyoladan choy ichyaptimi? Ramziy o‘yinlar — rivojlanishning haqiqiy durdonasi. Unga xalaqit bermang, bu jajji rejissyorni chetdan kuzating.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'Sukunatga ehtiyoj 🤫', 'Uyquga ketganidan keyingi dastlabki yarim soat — eng nozik vaqt. Shovqin o‘lchagich yordamida xonadagi detsibel darajasini tekshiring va qo‘shni xonadagi televizor ovozini moslang.'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'Bog‘dagi muloqot 🌳', 'Boshqa bolalar bilan o‘ynashdan ko‘ra, ularning yonida o‘zicha o‘ynayaptimi? Parallel o‘yin bu yosh uchun mutlaqo tabiiy. Ob-havo va kiyimiga e’tibor berib, uni bog‘ga olib chiqing.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'Tezkor pediatr 🤖', 'Tuvakka o‘rgatishda (potty training) ortga ketish kuzatilyaptimi? O‘zingizni qiynamang, Anacan AI’dan ushbu psixologik jarayon bilan bog‘liq muammoni hal qilish yo‘llarini so‘rang.'),
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d', '“Meniki!” degan qaysarlik 🛑', 'Hamma narsani o‘ziniki qilib olishni xohlayaptimi? Bo‘lishish tushunchasi hali to‘liq shakllanmagan. Uni majburlamang, buning o‘rniga “Navbat bilan o‘ynaymiz” qoidasini asta-sekin joriy eting.'),
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc', 'Sehrli tun manzarasi 🪄', 'Uyquga ketishga qiynalyaptimi? Aqlli ertaklarda maxsus ertak yaratib, yangi odatlarni hikoyaga aylantiring.'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'Kundalikda sarhisob 📝', 'Bolangiz uxlagach, Kayfiyat kundaligini oching. Bugun sizni eng ko‘p nima charchatdi, nima kuldirdi? His-tuyg‘ularingizni bemalol ifoda etib, ko‘nglingizni bo‘shating.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'G‘alabadan keyingi haqiqat 🚀', 'Kechagi yubileydan so‘ng bugun ertalab yana sochilib yotgan o‘yinchoqlar va «Xohlamayman!» degan gaplar bilan uyg‘ondik! Hayot davom etadi. Chuqur nafas oling, siz bu tartibsizlikning eng ajoyib boshqaruvchisisiz.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'Kunduzgi uyqu inqirozi 🥱', 'Uxlashni xohlamay, yig‘layaptimi? 3 yoshga yaqin ayrim bolalar kunduzgi uyqudan voz kecha boshlaydi. Kurashish o‘rniga «Tinchlik soati»ni e’lon qilib, yotoqda shunchaki kitob varaqlashni taklif qiling.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'Karavotdan qochish rejasi 🛌', 'Bolalar karavotidan oshib chiqishga urinayaptimi? Xavfsizlik uchun xonani yana bir bor ko‘zdan kechiring. Kattalar karavotiga o‘tish vaqti yaqinlashmoqda.')
) AS v(id, t, b)
WHERE x.id = v.id;
